export default [{"id":112,"question":"هل يقع الطلاق المُحَرَّم أم لا؟","title":"هل يقع الطلاق المُحَرَّم والطلاق بالثلاث؟","answer":"الجواب: مثلما تقدم: الصحيح أنه لا يقع، والجمهور على أنه يقع، والصحيح أنه في الحيض والنِّفاس لا يقع عند الأقل، وهو الصواب، والجمهور على أنه إذا طلَّق في الحيض أو النفاس يقع.\nأما طلاق الثلاث فيقع منه واحدةً إذا كان بكلمةٍ واحدةٍ، كأن يقول: أنتِ طالق بالثلاث، أو: هي طالق بالثلاث، فالصواب أنه يحسب واحدة.","link":"https://binbaz.org.sa/fatwas/3549/هل-يقع-الطلاق-المحرم-والطلاق-بالثلاث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0096.mp3","categories":["الطلاق","الأيمان والنذور"]},{"id":113,"question":"سائلٌ يقول: هل قول الرجل في الحلف: \"عليَّ الطلاق\" يُعدُّ من الحلف بغير الله؟ وهل يقع الطلاق؟","title":"ما حكم قول \"عليَّ الطلاق\"؟","answer":"الجواب: لا، ليس من الحلف بغير الله، ويُعَدُّ حَلِفًا من حيث اللغة، فيُسمَّى: يمينًا من جهة اللغة، فإذا أراد به المنع أو الحثَّ أو التَّصديق أو التَّكذيب يُسمَّى: يمينًا من حيث اللغة، وفيه الكفَّارة، فإذا قال: \"عليه الطلاق ما يُسافر\"، وقصد الامتناع من السفر، ولم يقصد إيقاع الطلاق، أو قال: \"عليَّ الطلاق ما تذهبين في هذا اليوم\"، أو: \"عليَّ الطلاق ما أُكلمك اليوم\"، وقصده الامتناع، وليس قصده فراقها؛ فهذا يُسمَّى: يمينًا، حكمه حكم اليمين، وليس بمحرمٍ، بل مكروه، وله كفَّارة يمين.\nفإذا قال: \"عليه الطلاق ما يُكلِّمها\" وقصد الامتناع، ولم يقصد فراقها، أو قال: \"عليه الطلاق ما تذهبين هذا اليوم\"، وقصد منعها، ولم يقصد فراقها؛ ففيه كفَّارة يمين، أو قال: \"عليه الطلاق ما يأكل طعامَ فلانٍ\"، أو: \"عليَّ الطلاق ما آكل طعامه ولا آكل ذلك اليوم\"، وقصد الامتناع، ولم يقصد فراق أهله؛ ففيه كفَّارة يمين إذا جلس وأكل الطعام.","link":"https://binbaz.org.sa/fatwas/3550/ما-حكم-قول-علي-الطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0097.mp3","categories":["الطلاق","الأيمان والنذور"]},{"id":253,"question":"هل يجوز إخراج كفَّارة اليمين نقودًا؟ جزاكم الله خيرًا.","title":"حكمكفَّارة اليمين وهل تجوزنقودًا؟","answer":"الجواب: الشيخ: كفَّارة اليمين لا تخرج نقودًا، الله بيَّنها في كتابه العظيم، يقول سبحانه: لَا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِنْ يُؤَاخِذُكُمْ بِمَا عَقَّدْتُمُ الْأَيْمَانَ فَكَفَّارَتُهُ إِطْعَامُ عَشَرَةِ مَسَاكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍ فَمَنْ لَمْ يَجِدْ فَصِيَامُ ثَلَاثَةِ أَيَّامٍ ذَلِكَ كَفَّارَةُ أَيْمَانِكُمْ إِذَا حَلَفْتُمْ وَاحْفَظُوا أَيْمَانَكُمْ [المائدة:89]، هذه كفَّارة اليمين التي بيَّنها الله في كتابه العظيم: طعام، أو كسوة، أو عتق رقبة، فمَن لم يستطع صام ثلاثة أيام، إن كان فقيرًا عاجزًا صام ثلاثة أيام.\nبعض العامَّة يظن أنَّ الصوم مُقدَّم، لا، ما الصوم مُقدَّمًا، المُقدَّم الإطعام والكسوة والعتق، هذا المقدم، ومَن عجز عن الثلاثة من الرجال والنساء صام ثلاثة أيام، ومَن لم يعجز فعليه أن يُطعم أو يكسو أو يعتق.\nإطعام عشرة مساكين من أوسط طعام أهله، أوسط الطعام الذي يتعاطاه، سواء كان يأكل الذرة أو الأرز أو الشَّعير أو غير ذلك، وهكذا إذا كساهم يكسوهم كسوةً تُجزئهم في الصلاة، أو يُعتق رقبةً. أما النقود فلا، لا يُخرج نقودًا، هذا الذي عليه جمهورُ أهل العلم، وهو الحق؛ لأنَّ هذا خلاف ما شرعه الله، النقود خلاف ما شرع الله، فالواجب إعطاء ما تقدَّم من طعامٍ أو كسوةٍ أو عتقٍ، فمَن عجز صام ثلاثة أيام، أما النقود فلا.\nس: الخلاف فيه للتخيير؟\nصيام ثلاثة أيام فيه خلافٌ: بعضهم يرى أنها مُتتابعة، وهذا معروفٌ عن ابن مسعود: ثلاثة أيام متتابعات، وقال بعضُ أهل العلم: ليس بشرطٍ، لكن صومها متتابعة أوْلى وأحوط، وهو قول جمعٍ من أهل العلم، وهو معروفٌ عن عبدالله بن مسعودٍ، فالذي ينبغي أن تكون متتابعةً، ثلاثة أيام متتابعة، هذا هو الذي ينبغي للمؤمن والمؤمنة.","link":"https://binbaz.org.sa/fatwas/4244/حكم-كفارة-اليمين-وهل-تجوزنقودا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0295.mp3","categories":["الطلاق","الأيمان والنذور"]},{"id":286,"question":"سمعتُ أنه لا يجوز أن يقسم بصفة الله، إلا بأن تُضاف إلى الموصوف، فما قولكم؟","title":"ما حكم وكيفية القسم بصفات الله تعالى؟","answer":"الجواب: لا بدّ من ذلك، لا يقسم بصفةٍ إلا مضافة، فيقول: بعزَّة الله، بقدرة الله، بعلم الله، بكلام الله، أو معروفة أنَّها صفة الله، مثل: والقرآن، أو بالقرآن، معروفٌ أنَّ القرآن كلام الله، فلا بأس، أما المخلوق فلا يجوز؛ يقول النبيُّ ﷺ: مَن كان حالفًا فليحلف بالله أو ليصمت.","link":"https://binbaz.org.sa/fatwas/4284/ما-حكم-وكيفية-القسم-بصفات-الله-تعالى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0333.mp3","categories":["الطلاق","الأيمان والنذور"]},{"id":353,"question":"رجلٌ تزوَّج امرأةً، وأنجبت منه، ثم طلَّقها وحرَّمها على نفسه مُتلفِّظًا بكلمة: \"هي عليه حرام، تحلّ للكلاب السود ولا تحلّ له\"، وبعد عشرين سنة حاول أحدُ أبنائها منه إقناعه بالزواج منها من جديدٍ بمُوجب عقدٍ، فهل عليه شيءٌ؟ علمًا بأنَّ له منها أبناء ومن غيرها.","title":"ما حكم من يقول لزوجته: أنت عليَّ حرام؟","answer":"الجواب: هذا لا يحتاج إلى نظر في الطلاق، لا بدّ أن ينظر في الطلاق الذي صدر منه، فإذا ثبت أن الطلاق واحدةٌ أو اثنتان فله الرجوع إليها بعقدٍ جديدٍ، وإذا ثبت أنه طلَّقها الطلقة الثالثة، وأنها الثالثة؛ فإنها لا تحلّ له حتى تنكح زوجًا غيره.\nفلا بد من النظر، لا ريب في ذلك، يتصل هو وهي ووليها بالعالم الذي يُفتيه، والقاضي الذي يُفتيه من أهل العلم، حتى يشرحوا جميعًا صفة الطلاق، الزوج والمطلقة ووليها يجتمعون عند الحاكم الشرعي أو عند العالم ليُفتيهم، حتى يشرحوا له الواقعة، وحتى يعرف الحقيقة، ثم تكون الفتوى على ضوء ذلك.\nوالقاعدة: أنه إذا كان الطلاقُ واحدةً أو اثنتين فإنها لا تحرمها، بل تجوز له بعقدٍ جديدٍ إذا كانت قد خرجت من العدَّة، أما إذا طلَّقها الطلقة الأخيرة الثالثة فإنها لا تحلّ له عند جميع المسلمين حتى تنكح زوجًا غيره؛ لقوله سبحانه: فَإِنْ طَلَّقَهَا يعني: الثالثة فَلَا تَحِلُّ لَهُ مِنْ بَعْدُ حَتَّى تَنْكِحَ زَوْجًا غَيْرَهُ [البقرة:230].\nأما التحريم فله شأنٌ آخر، إذا حرَّمها فتحريمه له شأنٌ آخر: إذا قال: \"هي عليه حرام\" أو \"كظهر أمه\" ولم يُطلقها، إنما حرمها؛ فهذا له كفَّارة، حرمها فقط ولم يُطلق، فإنَّ عليه كفَّارة قبل أن يمسَّها، وهي عتق رقبة مؤمنة، فإن عجز صام شهرين متتابعين، فإن عجز أطعم ستين مسكينًا قبل أن يمسَّها.","link":"https://binbaz.org.sa/fatwas/4545/ما-حكم-من-يقول-لزوجته-انت-علي-حرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0406.mp3","categories":["الطلاق","الأيمان والنذور","الظهار"]},{"id":368,"question":"رجلان تبايعا ثم اختلفا في المجلس، فقال البائع بالطلاق، وكررها أكثر من مرتين بألا يبيع على المُشتري الحاضر معه في المجلس أبدًا، ثم بدا له من بعد ذلك أن يبيع، فما حكم ذلك؟","title":"حكم من حلف بالطلاق بشأن بيع بضاعة","answer":"الجواب:\nأولًا لا ينبغي استعمال الطلاق في هذا، وأقل أحواله الكراهة؛ لأنه قد يُفضي إلى الطلاق، قد يُفضي إلى الفُرقة وضياع البيت.\nثم التعبير بالطلاق لا يجوز؛ لأنه حلفٌ بغير الله، فقوله بالطلاق أو بالتحريم أو بالحرام لا يجوز؛ لأنه حلف بغير الله، لا يجوز.  لكن إذا قال: \"عليه الطلاق لا يبيع\"، \"عليه الطلاق لا يُكلم فلانًا\" هذا فيه تفصيلٌ: إن كان قصده منع نفسه من هذا الشيء، ما قصده طلاقها، ليس قصده فراق زوجته، وإنما قصده التأكيد على نفسه أنه ما يبيع عليه، هذا مقصوده: لا يبيع عليه هذا؛ عليه كفَّارة يمين إذا باع عليه. أما إن كان قصده إيقاع الطلاق: هو باع الآن على أن يقع الطلاقُ على زوجته، فإنه إذا باع يقع الطلاق، فلا يبع إذا كان يُحب أن تبقى زوجته معه وأن لا يقع الطلاق. أما إذا كان لا، ما قصد إلا مجرد التأكيد ومنع نفسه من البيع، ليس قصده إيقاع الطلاق، وليس قصده مفارقة زوجته، ولكنه أراد بهذا التأكيد على أنه لا يبيع؛ فهذا فيه كفَّارة اليمين إذا باع.","link":"https://binbaz.org.sa/fatwas/4620/حكم-من-حلف-بالطلاق-بشان-بيع-بضاعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0423.mp3","categories":["الطلاق","الأيمان والنذور"]},{"id":413,"question":"عليَّ نذرٌ قدره ذبيحتان، هل يجوز أن أرسل قيمة الذَّبيحتين إلى المُجاهدين في أفغانستان نقدًا؟","title":"هل لمن نذر ذبيحة إرسال قيمتها لبلد آخر؟","answer":"الجواب: لا بأس، ترسلها نقدًا وتُذبح هناك، لا بدّ من الذبح، إذا كان حولك فقراء فاذبحها ووزّعها عليهم، وإن أرسلتها للمُجاهدين فعمّد وكيلك يذبحها ويُوزعها بين اللاجئين هناك من المجاهدين والفقراء، يوزعها بينهم، ما تكفي الدراهم، لا بد من ذبح الذَّبيحتين؛ لأن الرسول عليه الصلاة والسلام قال: مَن نذر أن يُطيع الله فليُطعه، فلا مانع أن تشتري الذَّبيحتين في أفغانستان وتُوزعها بين فقراء المجاهدين المهاجرين هناك، ويُسمون: المهاجرين، وهم اللاجئون، وإن وزّعتها في أقاربك الفقراء، أو في جيرانك الفقراء، أو في قريةٍ فقيرةٍ بين فقرائها؛ كفى ذلك، وإن أرسلتها نقودًا لكن عمّدت وكيلك الثقة أن يشتري بها ذبيحتين ويُوزعها فلا بأس.","link":"https://binbaz.org.sa/fatwas/4830/هل-لمن-نذر-ذبيحة-ارسال-قيمتها-لبلد-اخر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0471.mp3","categories":["الأيمان والنذور"]},{"id":551,"question":"إذا قال: \"أنت عليّ حرام\" يُنظر في نيته؟","title":"حكم من قال لامرأته: \"أنت عليّ حرام\"","answer":"الجواب: لا، إذا قال: \"أنتِ علي حرام\"؛ فحكمه حكم الظهار، إلا إذا عَلّق.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6382/حكم-من-قال-لامراته-انت-علي-حرام","audio":"https://files.zadapps.info/binbaz.org.sa/maram117 - 02 - .mp3","categories":["الطلاق","الأيمان والنذور","الظهار"]},{"id":554,"question":"إذا قال: إذا خرجت وإذا فعلت ِ كذا فأنتِ عليّ حرام، فهل يُسأل عن نيته؟","title":"ما معنى وحكم الطلاق المُعَلّق؟","answer":"الجواب: هل قصده تحريمها أو منعها بس؟ أما إذا كان قصده منعها فهذا عليه كفارة يمين، وإذا كان قصده تحريمها فحكمه الظهار.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6385/ما-معنى-وحكم-الطلاق-المعلق","audio":"https://files.zadapps.info/binbaz.org.sa/maram120.mp3","categories":["الأيمان والنذور","الطلاق","الظهار"]},{"id":558,"question":"إذا قال: إذا خرجت من البيت فأنت طالق، وإذا ركبت مع أخوك فأنت طالق، فهل تقع طلقتين أو طلقة؟","title":"ما حكم الطلاق المُعَلَّق؟","answer":"الجواب: إذا كان قصده منعها ففيه كفارة يمين، وإذا كان قصده الطلاق فيقع طلقتان، بالخروج من البيت طلقة، وركوبها مع أخيها طلقة، إذا كان قصده الطلاق.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6389/ما-حكم-الطلاق-المعلق","audio":"https://files.zadapps.info/binbaz.org.sa/maram124 - 02 - .mp3","categories":["الطلاق","الأيمان والنذور"]},{"id":780,"question":"ما حكم مَن يقول: في ذمَّتي؟","title":"ما حكم مَن يقول: \"في ذمَّتي\"؟","answer":"الجواب: ما أعلم فيها شيئًا، ليست يمينًا، ليست هذه يمينًا، وإنما هي عُرفٌ للناس، فيُؤكِّد، كأن يقول: أمانة في ذمَّتي، أو: دَينٌ مُتحققٌ في ذمَّتي أقوم به، نوعٌ من الالتزام.\nس: لو قد قصد بها اليمين؟\nالشيخ: اليمين ما تكون بـ\"في\"، اليمين تكون بالواو والتاء والباء والهمزة، أما \"في ذمتي\" فليست بيمينٍ.","link":"https://binbaz.org.sa/fatwas/20724/ما-حكم-من-يقول-في-ذمتي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0608ما حكم من يقول في ذمتي؟ ابن باز فتاوى المحاضرات.mp3","categories":["الأيمان والنذور"]},{"id":801,"question":"امرأة حلفت على ابنتها: ألا تخرج من الدار، وفي اليوم الثاني سمحت لها بالخروج، ولم تستطع الصيام، فهل يصوم عنها ابنُها؟ علمًا بأنها عاجزة عن الإطعام.","title":"حكم من حنثت وعجزت عن الإطعام والصيام","answer":"الجواب: كفَّارة اليمين: إطعام عشرة مساكين، أو كسوتهم، أو عتق رقبة، فمَن عجز عن هذا صام ثلاثة أيام، فإذا كانت فقيرةً لا تستطيع الكفَّارة، وعاجزة عن الصيام، يبقى مُعلَّقًا، تبقى الكفَّارة مُعلَّقة في ذمَّتها، فلا يصوم عنها، لا يُصام عن الحيِّ، لكن إذا كفَّر عنها بالطعام وأذنت له فلا بأس، إذا سمحتْ له أن يُكفِّر عنها بالطعام، أو بالكسوة، أو بالعتق لا بأس، أما الصيام فلا، فإن لم يُكفِّر عنها بقيت الكفَّارة، متى استطاعت كفَّرت بالإطعام، أو بالكسوة، أو بالعتق، ومتى استطاعت الصيام عند عجزها عن الكفَّارة بالإطعام ونحوه صامت: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16].","link":"https://binbaz.org.sa/fatwas/20795/حكم-من-حنثت-وعجزت-عن-الاطعام-والصيام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0624مسألة في كفارة اليمين؟ ابن باز فتاوى المحاضرات.mp3","categories":["الأيمان والنذور"]},{"id":824,"question":"إنَّ بعض الناس تعوَّدوا حين تهديد زوجاتهم بالطلاق، كأن يقول لزوجته: إذا خرجتِ من الدار فأنت طالقة، وإذا ذهبتِ إلى دار فلانٍ فأنت طالق، وهكذا يتكرر هذا الأمر منهم مرات عديدة، فهل يصحّ ذلك؟ أو هل يقع منهم طلاقٌ أم أنه يمينٌ؟","title":"حكم الطلاق للتهديد وحكم طلاق الثلاث","answer":"الجواب: هذا فيه تفصيل، هذا الكلام فيه تفصيل: فإذا قال: إن خرجتِ فأنت طالق، أو قال: إذا ذهبتِ إلى أهلك فأنت طالق، أو قال: إن كلمتِ فلانًا فأنت طالق، هو يقصد منعها وتهديدها وتخويفها، وليس قصده إيقاع الطلاق، إنما قصده أن يُحذِّرها من ذلك، ويمنعها منه؛ فهذا إذا خالفته فعليه كفَّارة يمين.\nوهي ليس لها أن تُخالفه، لا يجوز لها أن تعصي زوجها في مثل هذا، عليها السمع والطاعة، ولو ما طلَّق، إذا قال: لا تخرجي، لا تخرجي، لا تُكلِّمي فلانًا، لا تُكلِّمي  فلانًا، حتى يرضى، وحتى تستسمحه، فإذا طلَّق صار الأمرُ أشدَّ، فليس لها أن تعصيه في المعروف.\nوإذا كان المقصود منعها وتخويفها وتهديدها لعلها ترتدع، ثم فعلت وعاندت، فهي آثمةٌ، وعليه كفَّارة يمين هو وهي: إطعام عشرة مساكين، أو كسوتهم، أو عتق رقبةٍ، فمَن لم يستطع صام ثلاثة أيامٍ، إذا لم يستطع إطعام عشرة مساكين ولا كسوتهم ولا العتق فإنه يصوم ثلاثة أيام، والأفضل أن تكون مُتتابعةً، أما مَن يستطيع الإطعام أو الكسوة أو العتق فليس له الصيام، بل يُكفِّر بإطعامٍ أو بكسوةٍ أو بعتقٍ.\nأما إذا كان قصدُه إيقاع الطلاق، قال: إن كلمتِ فلانًا فأنت طالق، ونيته أنه متى كلمته فهي طالق، قصده فراقها، فإنه يقع طلقة في ذلك، أو قال: إذا ذهبتِ إلى أهلك بغير إذني فأنت طالق، وذهبت وقصده إيقاع الطلاق؛ يقع الطلاق.\nأما إذا كان قصده التَّهديد والتَّخويف والتَّحذير، وليس قصده إيقاع الطلاق؛ فهذا لا يقع، وعليه كفَّارة يمينٍ، أما إذا كان قصده إيقاع الطلاق وتنفيذه مع منعها، هو يريد منعها وإيقاع الطلاق أيضًا، فإنه يقع الطلاقُ، يكون طلقةً واحدةً، إذا قال: أنت طالق، أو قال: طالق بالثلاث، فهي تُعتبر واحدةً على الصحيح، الثلاث بلفظٍ واحدٍ تُعتبر طلقةً واحدةً في أصحِّ قولي العلماء.","link":"https://binbaz.org.sa/fatwas/20867/حكم-الطلاق-للتهديد-وحكم-طلاق-الثلاث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0662بعض الناس تعود أن يهدد زوجاتهم بالطلاق,فهل يقع منه الطلاق ؟ ابن باز.mp3","categories":["الطلاق","الأيمان والنذور"]},{"id":843,"question":"ما حكم مَن نذر نذرًا لم يُوفِ به في الوقت الذي حدَّده؟ فهل يجوز له أداؤه في وقتٍ بعد ذلك؟","title":"حكم من نذر نذرًا ولم يوفِ به في وقته","answer":"الجواب: إذا قال: لله عليَّ أن أُصلي ركعتين ضحى يوم الخميس، أو: ضحى يوم الجمعة، فلم يفعل، فعليه أن يُصلي ويُكفِّر كفَّارة يمينٍ عن إضاعة الوقت، هذا أحد قولي العلماء، يُكفِّر كفارة يمينٍ عن إضاعة الوقت؛ لقوله ﷺ فيما رواه مسلم من حديث عقبة بن عامر: كفَّارة نذرٍ كفَّارة يمينٍ، زاد الترمذي: إذا لم يُسَمِّ، قالوا: هذا سمَّاه، ولكن أخلَّ به، فعليه كفَّارة يمين، مع أداء الصلاة في وقتٍ آخر.\nوقال آخرون: يكفي أداء الصلاة، وعليه التوبة إلى الله من ذلك، من دون كفَّارةٍ، عليه التوبة إلى الله، ويكفي أن يؤدي الصلاة؛ لقوله ﷺ: مَن نذر أن يُطيع الله فليُطعه، فيفعل الطاعة، ويستغفر الله عمَّا جرى من التأخير، وهكذا لو نذر أن يصوم يوم الخميس الموافق كذا وكذا، ثم تساهل، فإن عليه أن يصوم يومًا بدلًا منه، كما يصوم يومًا بدل رمضان، وعليه التوبة.  وقال آخرون: وعليه مع هذا كفَّارة يمينٍ؛ لأنه أخلَّ باليوم.","link":"https://binbaz.org.sa/fatwas/20868/حكم-من-نذر-نذرا-ولم-يوف-به-في-وقته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0663ما حكم من نذر نذراً ولم يوفي به في الوقت الذي حدده فهل يجوز أداءه بعد ذلك؟ ابن باز.mp3","categories":["الأيمان والنذور"]},{"id":1017,"question":"ما حكم مَن قال لزوجته: عليَّ الحرام ما تذهبين لبيت فلانٍ، مع العلم أنَّهم أصدقاء؟ أفيدونا جزاكم الله خيرًا.","title":"حكم قول \"علي الحرام..\" للزوجة","answer":"الجواب: هذا له حالان: أحدهما أن يقصد تحريمها ومنعها من الذهاب، فهذا عليه كفَّارة الظِّهار إذا ذهبت إلى البيت الممنوع، وهي عتق رقبةٍ، فإن عجز صام شهرين متتابعين، فإن عجز أطعم ستين مسكينًا كفَّارة الظهار المذكورة في سورة قَدْ سَمِعَ.\nأما إن كان ما قصد إلا منعها، ما قصد التَّحريم، بل قصد تخويفها ومنعها فقط، ولم يقصد تحريمها عليه إن فعلت، وإنما مقصوده تخويفها وتحذيرها وتهديدها ومنعها؛ فهذا عليه كفَّارة يمينٍ، وهي إطعام عشرة مساكين، أو كسوتهم إذا ذهبت، إلا أن يكون نوى \"إلا بإذني\"، إن كان في نيته منعها إلا بإذنه، فإذا أذن لها فلا شيءَ عليه، أما هجر البيت، هو أخوه؟\nالطالب: نعم، هم أصدقاؤه.\nالشيخ: أما الهجر لهذا البيت فهذا فيه تفصيلٌ: إن كان أهلُ البيت يضرُّونها، وعليها خطرٌ منهم، يخاف عليها من شرِّ الفساد؛ فلا يأذن لها في الذهاب، ولا يحتاج حلفًا، يلزمها أن تكفَّ عنهم لشرِّهم، ولو لم يحلف عليها زوجُها، ولو ما حلف، ولو لم يمنعها، هي تمتنع، فإذا منعها؛ وجب عليها الامتناعُ طاعةً له، وحذرًا من الشرِّ. أما إن كانوا طيبين وجيرانًا أخيارًا فلا ينبغي له منعها منهم، ينبغي أن يسمح لها؛ لأن الجيران يتزاورون، ويأنس بعضُهم لبعضٍ، وبقاؤها في البيت دائمًا دائمًا قد يضرُّها ويُسبب لها عُقَدًا نفسيَّةً، فالسماح لها بالذهاب إلى جيرانها الطيبين وإلى أهلها الطيبين أمرٌ مطلوبٌ، مع تحريصها وتحريضها على الستر والبُعد عن أسباب الفتنة.","link":"https://binbaz.org.sa/fatwas/21059/حكم-قول-علي-الحرام-للزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0855ما حكم من قال لزوجته عليَّ الحرام إذا ذهبتِ إلى بيت أهلك؟ ابن باز فتاوى المحاضرات.mp3","categories":["الأيمان والنذور"]},{"id":1122,"question":"نذرتُ لله تعالى أن أُصلي ركعتين بعد كل فرضٍ، وبما أنه لا يجوز أن أُصلي بعد الفجر وبعد العصر، فهل يختلف الحالُ في حالة النَّذر؟ أفيدونا أثابكم الله.","title":"حكم من نذر صلاة ركعتين بعد كل فريضة","answer":"الجواب:\n\nعليك الوفاء بالنذر، ولا يدخل في هذا ما بعد العصر وما بعد الفجر؛ لأنَّ هذا ما هو محل عبادةٍ، ما هو محل صلاةٍ، فنذرك ونذر غيرك يُحْمَل على الأمر الشرعي، فعليك أن تُصلي ركعتين بعد الظهر، وبعد المغرب، وبعد العشاء، أما العصر والفجر فلا؛ لأنَّ ما بعدهما ليس محلَّ صلاةٍ.\n\nثم نُوصيك وغيرك بعدم النَّذر، النبي نهى عن النذر وقال: إنه لا يأتي بخيرٍ عليه الصلاة والسلام، فلا ينبغي، لكن مَن نذر طاعةً وجب عليه الوفاء، مثل هذا النذر، يقول ﷺ: مَن نذر أن يُطيع الله فليُطِعْه، ومَن نذر أن يعصي الله فلا يعصه، فالوصية عدم النَّذر مطلقًا.\n\nس: وهل تُقْضَى سنة الفجر إذا فاتت، وكذلك الوتر؟\n\nالشيخ: نعم، إذا فاتت سنةُ الفجر تُقْضَى بعد الصلاة، أو بعد طلوع الشمس وارتفاعها، هذا هو السنة، هذا هو الأفضل، وهكذا الوتر: إذا فات في الليل السنة أن يُصلِّي المؤمنُ والمؤمنة في النهار مثلما كان يُصلي بالليل، لكن لا يُوتر، يشفع، إذا كان يُصلي خمسًا صلَّى ستًّا، بثلاث تسليمات، وإذا كان يُصلي ثلاثًا سلَّم تسليمتين، وإذا كان يُصلي سبعًا صلَّى ثمان ركعات، أربع تسليمات، وهكذا.\nتقول عائشةُ رضي الله عنها: \"كان النبيُّ ﷺ إذا شغله مرضٌ أو نومٌ عن وتره من الليل صلَّى من النهار ثنتي عشرة ركعة\"، وكان في الغالب ﷺ يُصلي إحدى عشرة ركعة في الليل، فإذا شُغل عن ذلك بنومٍ أو مرضٍ صلَّاها من النهار وشفعها، صلَّاها ثنتي عشرة ركعة، ست تسليمات، فهكذا غيره ﷺ إذا وقع له مثل ذلك: شُغِلَ عن الوتر بالليل لنومٍ أو مرضٍ يُصلي من النهار، ولكن يشفع، لا يُصلي وترًا، يشفع.","link":"https://binbaz.org.sa/fatwas/21182/حكم-من-نذر-صلاة-ركعتين-بعد-كل-فريضة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0978نذرت لله أن أصلي ركعتين بعد كل فريضة فهل يجوز أن أصليها في أوقات النهي؟.mp3","categories":["الأيمان والنذور"]},{"id":1124,"question":"قلتُ لزوجتي: إذا فعلتِ هذا الخطأ سوف أُطلقك، وقلتُ هذا الكلام مرتين، وأنا في حالة غضبٍ، أفيدونا جزاكم الله خيرًا، ماذا يترتب عليَّ؟","title":"حكم من تكلم بطلاق امرأته في حالة غضب","answer":"الجواب:\nليس هذا بطلاقٍ، هذا وعيدٌ، إذا قال الرجلُ لزوجته: إذا فعلتِ هذا سوف أُطلقك، أو طلقتُك، أو فإني أُطلقك، هذا ليس بطلاقٍ، هذا وعيدٌ، فإن شاء طلَّق، وإن شاء لم يُطلِّق.\n\"إذا فعلتِ\" بخلاف إذا قال: \"إن فعلتِ فأنت طالق\":  \"إن فعلتِ هذا فأنت طالق\": هذا تعليقٌ للطلاق، إذا قصد إيقاع الطلاق يقع الطلاق، وإن قصد تخويفها ومنعها وما قصد إيقاع الطلاق، لكن أراد أن يُخوفها ويُهددها؛ فهذا حكمه حكم اليمين على الصحيح، ولا يقع به الطلاق، وعليه كفَّارة يمين.\nإن قال: \"إن كلَّمْتِ فلانًا..\" أو: \"إن خرجتِ بغير إذني فأنت طالق\"، يقصد وعيدها وتخويفها وتهديدها وتحذيرها، ولا يقصد إيقاع الطلاق؛ هذا حكمه حكم اليمين، عليه كفَّارة يمين إذا خالفت يمينه.\nأما إذا قصد إيقاع الطلاق فإنه يقع الطلاق إذا خالفته: إذا خرجت، أو كلَّمَتْ؛ يقع الطلاق الذي عُلِّق على خروجها أو كلامها، أما إذا قال: سوف أُطلقك، أو: سأُطلقك، فهذا وعيدٌ، ولا يقع به شيءٌ.","link":"https://binbaz.org.sa/fatwas/21180/حكم-من-تكلم-بطلاق-امراته-في-حالة-غضب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0976قلت لوزجتي إذا فعلتي هذا الخطأ سوف أطلقك وقلت هذا الكلام مرتين وأنا في حالة غضب فما الحكم؟.mp3","categories":["الطلاق","الأيمان والنذور"]},{"id":1128,"question":"هل الحلف على الأولاد فيه كفَّارة، مثل قولي: والله لأضربك إن فعلتَ كذا، ولم أضربه؟ وإذا كان هناك كفَّارة فما هي؟","title":"هل الحلف على الأولاد فيه كفَّارة؟","answer":"الجواب:\nإذا حلف الإنسانُ على أولاده أو على زوجته: والله لأفعلنَّ كذا، والله لأضربنَّك، أو والله لأضربنَّكِ، أو والله لتفعل كذا، أو الله أن تقوم وتفعل كذا، أو والله أن تأتي بكذا، إذا كان قاصدًا ذلك عليه الكفَّارة إذا ما فعل الولد أو الزوجة ذلك، أو هي قالت لزوجها كذلك، إذا كان شيئًا مقصودًا، هذا فيه الكفَّارة. أما إذا كان لغو اليمين، ما قُصِد، فالله يقول جلَّ وعلا: لَا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِنْ يُؤَاخِذُكُمْ بِمَا كَسَبَتْ قُلُوبُكُمْ [البقرة:225] ما عَمَدَه القلبُ وقَصَدَه، هكذا يقول جلَّ وعلا في سورة البقرة، ويقول في سورة المائدة: لَا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِنْ يُؤَاخِذُكُمْ بِمَا عَقَّدْتُمُ الْأَيْمَانَ فَكَفَّارَتُهُ يعني: اليمين إِطْعَامُ عَشَرَةِ مَسَاكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍ فَمَنْ لَمْ يَجِدْ فَصِيَامُ ثَلَاثَةِ أَيَّامٍ ذَلِكَ كَفَّارَةُ أَيْمَانِكُمْ إِذَا حَلَفْتُمْ وَاحْفَظُوا أَيْمَانَكُمْ [المائدة:89].\nفالله سبحانه يأمرنا بحفظ اليمين، ويُخبرنا بالكفَّارة إذا عقدنا اليمين، فإذا عقد اليمين الرجلُ أو المرأة على ولدٍ أو خادمٍ أو خادمةٍ أو غير ذلك؛ فإنَّ عليه الكفَّارة إذا لم ينفذ مطلوبه، إذا حصل الحنث بأن قال: والله لتفعلنَّ كذا، يقول لولده أو لخادمه، أو تقول الزوجةُ لزوجها: والله لتفعلنَّ كذا، أو والله لأفعل كذا، ثم لا يحصل المقصود؛ فيه كفَّارة اليمين، وهي إطعام عشرة مساكين، أو كسوتهم، أو عتق رقبةٍ، فمَن عجز يصوم ثلاثة أيام، والأفضل أن تكون مُتتابعةً.\nأما الأيمان الدَّارجة التي ما يتعمَّدها: والله ما فعلتُ كذا، والله لأفعلنَّ كذا، ما قصدها، وإنما مرَّت بلسانه من غير قصدٍ، هذا يُسمَّى لغو اليمين، ليس فيه شيء، أما المقصود الذي قَصَدَه القلبُ وكَسَبَه القلبُ فهذا فيه الكفَّارة.","link":"https://binbaz.org.sa/fatwas/21175/هل-الحلف-على-الاولاد-فيه-كفارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0971هل الحلف على الأولاد فيه كَفارة؟.mp3","categories":["الأيمان والنذور"]},{"id":1183,"question":"ركب معي رجلٌ في سيارتي، وأعطاني مبلغًا من المال، فأقسمتُ ألا آخذه، وأقسم أن آخذه، ولكني بعد ذلك وضعتُه في أحد صناديق هيئة الإغاثة الإسلامية، فما رأيكم؟","title":"حكم مَن حنث في يمينه إكرامًا لمن أقسم عليه","answer":"الجواب:\nقد أحسنتَ في أخذه وبررتَ قسم أخيك، وعليك كفَّارة يمينٍ، قد أحسنت في أخذه، النبي ﷺ أمر بإبرار القسم، وأخوك له حقٌّ عليك، قد أكرمتَه بذلك، وعليك كفَّارة يمينٍ، وهي إطعام عشرة مساكين أو كسوتهم؛ لأنك أقسمتَ ثم خالفت يمينك من أجل إكرام أخيك وبرّ قسمه.\nس: قوله: تصدَّق به؟\nالشيخ: ولو تصدَّق به، عليك الكفَّارة ولو تصدَّقتَ به.","link":"https://binbaz.org.sa/fatwas/21249/حكم-من-حنث-في-يمينه-اكراما-لمن-اقسم-عليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1145رجل أعطاني مبلغ فأقسمت ألاَّ آخذه وأقسم أن آخذه ثم أخذته وتبرعت به؟ ابن باز.mp3","categories":["الأيمان والنذور"]},{"id":1215,"question":"ما حكم إخراج كفَّارة اليمين نقدًا؟ وكم قيمتها؟","title":"هل يجوز إخراج كفَّارة اليمين نقدَا؟","answer":"الجواب:\nلا يجوز إخراجها نقدًا، هذا الذي عليه جمهورُ أهل العلم، وهو الصواب، الله يقول جلَّ وعلا في كتابه العظيم: لَا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِنْ يُؤَاخِذُكُمْ بِمَا عَقَّدْتُمُ الْأَيْمَانَ، ثم قال: فَكَفَّارَتُهُ يعني: اليمين إِطْعَامُ عَشَرَةِ مَسَاكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍ فَمَنْ لَمْ يَجِدْ فَصِيَامُ ثَلَاثَةِ أَيَّامٍ، ثم قال بعدها سبحانه: ذَلِكَ كَفَّارَةُ أَيْمَانِكُمْ إِذَا حَلَفْتُمْ وَاحْفَظُوا أَيْمَانَكُمْ [المائدة:89]، فكفَّارتها مثلما قال الله: إطعام عشرة مساكين من أوسط ما تُطعم أهليك، أو كسوتهم، أو تحرير رقبة، يعني: عتق، كأن تُغدّيهم أو تُعشيهم من طعامك، من أوسط ما تُطعم أهلك: من تمرٍ، أو أرزٍ، وإذا كان معه إدامٌ يكون أفضل، أو تُعشيهم في مطعم، أو في أي مكانٍ، أو تُغديهم، أو تُعطيهم شيئًا نَيِّئًا من الأرز أو من التَّمر، نصف صاع: كيلو ونصف لكل واحدٍ، أو تكسوهم كسوةً على مقطع، أو على إزار ورداء، أو قميص فقط، ذلك الكسوة، أو عتق رقبة مؤمنة، من ذكرٍ أو أنثى، فإن عجزتَ تصوم ثلاثة أيام فقط، إذا عجزتَ عن هذا كله تصوم، أما الدراهم فلا.","link":"https://binbaz.org.sa/fatwas/21271/هل-يجوز-اخراج-كفارة-اليمين-نقدا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1123ما حكم أخراج كفارة اليمين نقداً؟ ابن باز فتاوى.mp3","categories":["الأيمان والنذور"]},{"id":1340,"question":"لَعَمْرِي (من الحَلِف)؟","title":"هل قول \"لَعَمْرِي\" من الحَلِف؟","answer":"الجواب:\nلا بأس بها، ليست بحلف.\nس: طيب أحسن الله إليك قول الله : لَعَمْرُكَ إِنَّهُمْ لَفِي سَكْرَتِهِمْ يَعْمَهُونَ [الحجر:72]؟\nج: من حيث اللغة، ما هو من حيث الشرع، هذا من حيث اللغة، ولهذا جاء عن النبي الحلف بذلك وعن بعض الصحابة.","link":"https://binbaz.org.sa/fatwas/21431/هل-قول-لعمري-من-الحلف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل قول لعمري يعد حلفا.mp3","categories":["الأيمان والنذور"]},{"id":1947,"question":"دارجٌ بين الناس: يقول: حلفتُ أنَّك ما تفعل كذا، فهل يقع الحلف بلفظ: حلفتُ أنَّك ما تفعل كذا؟","title":"هل قول \"حلفتُ أنَّك ما تفعل كذا\" يُعَدُّ يَمينًا؟","answer":"الجواب:\nما تصير يمينًا، إلا إذا كان حلف.\nس: إذا حلف بالله؟\nج: نعم.","link":"https://binbaz.org.sa/fatwas/22061/هل-قول-حلفت-انك-ما-تفعل-كذا-يعد-يمينا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل قول حلفتُ أنَّك ما تفعل كذا يعد يمينا.mp3","categories":["الأيمان والنذور"]},{"id":1949,"question":"بعضهم إذا قلت له: احلف بالله، يحلف، وإذا قلت له: احلف بالولي فيحلف؟","title":"حكم الحلف بالأولياء وتعظيمهم","answer":"الجواب:\nما يحلف بالوَلِي، هذا من تعظيمه للولي، نسأل الله العافية، إذا كان تعظيمه للولي أعظم من الله كان كفرًا أكبر.","link":"https://binbaz.org.sa/fatwas/22063/حكم-الحلف-بالاولياء-وتعظيمهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الحلف بالولي أو بالوالدين.mp3","categories":["الأيمان والنذور","نواقض الإسلام"]},{"id":1950,"question":"بعض الناس إذا حُلِفَ له بالله قال: لا، احلف على المصحف، ما يُصدِّق إلا إذا حُلِفَ له على المصحف؟","title":"ما حكم الحلف على المصحف؟","answer":"الجواب:\nلا، ما يحتاج \"مصحف\"، ما يحتاج أن يُكلِّف الناس، هذا من باب تعظيم اليمين، ما يلزمه هذا، يكفيه الحلف بالله فقط.","link":"https://binbaz.org.sa/fatwas/22064/ما-حكم-الحلف-على-المصحف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الحلف على المصحف.mp3","categories":["الأيمان والنذور"]},{"id":1955,"question":"بعض الناس يقول: \"مَن يحلف وهو كاذب ينقطع ظهره\" هل هذا تخويفٌ له؟","title":"ما جزاء مَنْ يحلف كاذبًا؟","answer":"الجواب:\nما بلغني هذا، كلام النبي ﷺ: مَن اقتطع حقَّ امرئٍ مسلمٍ فقد أوجب الله له النار، وحرَّم عليه الجنة، وفي اللفظ الآخر: مَن حلف على يمينٍ يقتطع بها مال أخيه بغير حقٍّ لقي الله وهو عليه غضبان.\nس: هل يُؤخِّرها الله  في الآخرة؟\nج: هذه من عقوباتها، وقد تُعجّل له العقوبة في الدنيا، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/22070/ما-جزاء-من-يحلف-كاذبا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/جزاء من يحلف كاذبا.mp3","categories":["الأيمان والنذور"]},{"id":1957,"question":"قول: \"وعَهْد الله\" هل هو حَلِف؟","title":"هل مِن اليمين قول: \"وعَهْد الله\"؟","answer":"الجواب:\nبعض أهل العلم يرى العهد كاليمين، يُكفِّر كفَّارة يمينٍ، ولا سيما إذا نوى بـ\"عهد الله\" ما يصدر منه جل وعلا، العهود التي تصدر من الله ، مثل: \"وعلم الله\"، \"وعزة الله\".","link":"https://binbaz.org.sa/fatwas/22072/هل-من-اليمين-قول-وعهد-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل قول وعهد الله يعد يمينا.mp3","categories":["الأيمان والنذور"]},{"id":1958,"question":"نَذْر المعصية؟","title":"حكم نَذْر المعصية","answer":"الجواب:\nالصواب فيه كفَّارة يمينٍ، لو نذر أنه يشرب الدخان يُكفِّر كفَّارة يمينٍ ولا يشرب الدّخان.","link":"https://binbaz.org.sa/fatwas/22073/حكم-نذر-المعصية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/نذر المعصية.mp3","categories":["الأيمان والنذور"]},{"id":1959,"question":"الرجوع عن اليمين؟","title":"ما حكم الرجوع عن اليمين؟","answer":"الجواب:\nيستمر.\nس: يستمر فيه؟\nج:..... إذا كانت المصلحةُ في عدم اللجاج فيها يتركها ويُكفِّر عن يمينه، بعض الناس يقول: لا، حلفت يمين،ـ انْقُضْها ما دامت المصلحةُ فيها.","link":"https://binbaz.org.sa/fatwas/22074/ما-حكم-الرجوع-عن-اليمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الرجوع عن اليمين.mp3","categories":["الأيمان والنذور"]},{"id":2036,"question":"الحَلِف بغير الله شرك أصغر؟","title":"حكم الحَلِف والحالف بغير الله","answer":"الجواب:\nمن الشرك الأصغر نعم، نسأل الله العافية.\nس: من قال أن الحالف بغير الله يرتد فإذا قال: لا إله إلا الله؟\nالشيخ: لأن دواء الشرك التوحيد، مثل ما قال ابن مسعود: (لأن أحلف بالله كاذبًا أحب إليّ من أحلف بغيره صادقًا)، وكانوا في أول الإسلام يحلفون بآبائهم، فلما هاجروا المدينة ومضى بعض المدة نهاهم النبي عن الحلف بآبائهم، عليه الصلاة والسلام، كانوا يحلفون بآبائهم وشرف آبائهم، ثم نُسِخ.","link":"https://binbaz.org.sa/fatwas/22153/حكم-الحلف-والحالف-بغير-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الحلف والحالف بغير الله.mp3","categories":["الأيمان والنذور","الحلف بغير الله"]},{"id":2039,"question":"بعض الناس يحلف ويقول ورحمة جدي حسن، وليس له جد اسمه حسن؟","title":"حكم قول بعض الناس \"ورحمة جدي..\"","answer":"الجواب:\nإن قصد رحمتي له، هذا ما يجوز.  وإن كان قصده \"رحمة الله\" فهو وصف، حلف برحمة الله، لكن مثل هذا ما ينبغي؛ لأنه موهم، فما ينبغي الحلف به، بل يقول: والله كذا وكذا أني ما فعلت كذا. أما \"ورحمتي\" فهذا ما يصلح؛ لأن رحمته هو مخلوقة، ورحمة الله وصفه جل وعلا.","link":"https://binbaz.org.sa/fatwas/22156/حكم-قول-بعض-الناس-ورحمة-جدي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/قول ورحمة جدي حسن.mp3","categories":["الأيمان والنذور"]},{"id":2420,"question":"إذا نذر شخص على مسألة خوف من مرض أو خوف من مصيبة تصيبه، وبعد النذر هذا تطاول فيه كل مرة يزيد في نذره؛ حتى وصل إلى مرحلة النذر هذا لا يستطيع أن يوفي به؛نذر بصوم شهرين متتابعين بالإضافة إلى التصدق بألف ذبيحة خوفًا من مرض أن يصيبه؟","title":"ما حكم مَن عجز عن الوفاء بنذره؟","answer":"الجواب:\nهذا من الجهل، النذر ما هو من أسباب العافية، النذر مَنْهِيٌّ عنه، النبي ﷺ نهى عن النذر قال: إنه لا يأتي بخير، والنذر ما هو من أسباب العافية، الرسول ﷺ قال: لا يأتي بخير، وإنما يُسْتَخْرَج به من البخيل، لكن إذا نذر طاعة يلزمه الوفاء حسب طاقته، يبقى في ذمته؛ دَيْنٌ حتى يستطيع.\nس: وإذا لم يستطع وفاء هذا الدين؟\nالشيخ: إذا قُدِّر أنه في صورة العاجز؛ يكون كفارة يمين إذا نذر شيئًا لا يستطاع.","link":"https://binbaz.org.sa/fatwas/22548/ما-حكم-من-عجز-عن-الوفاء-بنذره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/العجز عن الوفاء بالنذر.mp3","categories":["الأيمان والنذور"]},{"id":2548,"question":"هل اليمين الغموس يكون خاص بس بالتجارة؟","title":"هل اليمين الغَمُوس خاصة بالتجارة أم عامة؟","answer":"الجواب: اليمين الغَمُوس الكاذبة، يعني اللي فيها مضرة على أحد، يعرفها بعضهم بالغميز بالكاذبة، ولكن النبي ﷺ عرفها بأنها هي التي يُقتطع بها مالُ امرئٍ بغير حق، يقتطع بها حق أخيه بغير حق، وإذا كان كاذبًا مطلقًا فهو على كُلٍّ مذموم، إلا لعلّة شرعية.\nس: ليست خاصة بالتجارة؟\nالشيخ: لا، اليمين الغَمُوس الكاذبة التي يَضُرُّ بها أحدًا، أما إذا كانت لمصلحة شرعية وتأويل، هذا شيء آخر، ولكن إذا كان يقتطع بها مال امرئ يكون أشد وأغلظ، كما قال ﷺ: من حلف على يمين يقتطع بها مال امرئ مسلم بغير حق لقي الله وهو عليه غضبان، وفي اللفظ الآخر: فقد أوجب الله له النار وحرم عليه الجنة، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/22679/هل-اليمين-الغموس-خاصة-بالتجارة-ام-عامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/اليمين الغموس الكاذبة.mp3","categories":["الأيمان والنذور"]},{"id":2569,"question":"شاب حلف قبل صلاة الفجر أنه لا ينام ثم أخذ يقرأ القرآن ثم انسدح فنام، وفاتته صلاة الفجر فماذا عليه؟","title":"حكم من حلف ألا ينام ثم نام وفاتته الصلاة","answer":"الجواب: إذا كان ما تعمّد النوم ما عليه كفارة، لكن كونه ينسدح ويتساهل، هذا من علامات التساهل بحصول النوم، اللي يحلف ينبغي له أن يتحرز ويحذر، وإلا عليه كفارة يمين؛ للتساهل.","link":"https://binbaz.org.sa/fatwas/22702/حكم-من-حلف-الا-ينام-ثم-نام-وفاتته-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حلف ألا ينام ثم نام وفاتته الصلاة.mp3","categories":["الأيمان والنذور"]},{"id":2581,"question":"بالنسبة لنذر المعصية؟","title":"ما حكم الكفارة لنذر المعصية؟","answer":"كفارة يمين النذر المباح والنذر المكروه كله كفارة يمين، أما نذر الطاعة يجب وفاؤه؛ لقوله ﷺ: من نذر أن يطيع الله فليطعه، ومن نذر أن يعصي الله فلا يعصه. ونذر عائشة يدور بين الكراهة والمعصية؛ لأنه نذر قطيعة رحم وهجره، ولكن من شدة غضبها -هي غير معصومة- من شدة غضبها نذرت هذا النذر، ويكفيها كفارة اليمين.","link":"https://binbaz.org.sa/fatwas/22714/ما-حكم-الكفارة-لنذر-المعصية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/كفارة نذر المعصية.mp3","categories":["الأيمان والنذور"]},{"id":2582,"question":"لو نذر عدة مرات هل يُكتفى بواحدة؟","title":"هل تكفي كفارة واحدة إذا تكرر النذر؟","answer":"إذا كان بفعل واحد كفارة يمين واحدة، مثل: لله علي ألا أكلم فلانًا، وكلما رآه قال هذا الكلام مرات كثيرة؛ كفارة واحدة. أما إذا تكرر قال: لله عليه ألا أكلم فلانًا، وعليه ألا يكلم فلانًا الثاني، وعليه ألا يكلم فلانًا الثالث، وعليه ألا يسافر، كل واحد له حكمه؛ كفارة اليمين.","link":"https://binbaz.org.sa/fatwas/22715/هل-تكفي-كفارة-واحدة-اذا-تكرر-النذر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إذا تكرر النذر هل له كفارة واحدة أم لكل كفارة.mp3","categories":["الأيمان والنذور"]},{"id":2585,"question":"حكم النَّذْر ابتداءً: مكروه؟","title":"ما حكم ابتداء النذر؟","answer":"الجواب: نعم، النبي ﷺ قال: لا تنذروا فإن النذر لا يَرُدُّ مِن قَدَر الله شيئًا.","link":"https://binbaz.org.sa/fatwas/22718/ما-حكم-ابتداء-النذر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم ابتداء النذر.mp3","categories":["الأيمان والنذور"]},{"id":2743,"question":"قول أنس بن النضر: لئن الله أشهدني قتال المشركين... نذر؟","title":"هل مِن النَّذْر قول: لئن الله أشهدني كذا لأفعلن؟","answer":"الجواب: قريب من النذر، ولكن ما هو بواضح النذر، ما قال: لله عليّ، بل إخبار بمعنى الوعد والمعاهدة.\nس:ما يكون النذر غير المشروط مباحًا؟\nالشيخ: محتمل أنه: ليرين الله ما أفعل، ما قال: \"علي\" ما أتى بصيغة الالتزام، لكنه وعد، والمؤمن إذا وعد وفّى، ولهذا وفّى  واجتهد يوم أُحُد.","link":"https://binbaz.org.sa/fatwas/22891/هل-من-النذر-قول-لىن-الله-اشهدني-كذا-لافعلن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/قول أنس بن النضر لئن الله أشهدني قتال المشركين هل هو نذر.mp3","categories":["الأيمان والنذور","شروح الحديث","الحلف بغير الله"]},{"id":2744,"question":"إذا لم يكن النذر مشروطًا يكون مباحًا؟","title":"حكم النذر غير المشروط","answer":"الجواب: إن كان طاعة يلزم، قال: لله علي أن أفعل كذا، طاعة؛ يلزم من نذر أن يطيع الله فليطعه، وأما إن قال: إن شاء الله، أو سأفعل إن شاء الله؛ما يصير نذر، أو قال: إن حضرت فعلت، وما التزم؛ ما يصير نذر..... أو أقمت فيهم درسًا، أو إن وجدت فلانًا نصحته؛ هذا وعد.","link":"https://binbaz.org.sa/fatwas/22892/حكم-النذر-غير-المشروط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم النذر غير المشروط.mp3","categories":["الأيمان والنذور"]},{"id":2821,"question":"رجل عليه مجموعة كفارات يمين وزوجته، هل يجمعها ويخرجها سويًّا ويعطيها مجموعة؟","title":"حكم جمع عدة كفارات يمين وكيفية إخراجها؟","answer":"الجواب: يجب عليه إن كان يمين يعطيها عشرة، ولو تعددت يعطيها عشرة، ولو هي عشر  كفارات.\nس: يعطيها واحدًا أو عشرة؟\nالشيخ: عشرة، لا بد من عشرة يدوِّرهم ولو في غرب الدنيا أو شرقها.\nس: يجمعهم؟\nالشيخ: ما هو يجمعهم، يعطي ذا ويعطي ذا، ولو هذا اليوم وذا باكر وذا عقبه، وذا في الرياض، وذا في الخرج، وذا في الحوطة؟\nس: الكفارة الواحدة تكفي عن يمينين ثلاثة كذا مثلًا.\nالشيخ: إذا كان عن يمين واحدة، إذا كان على شيء واحد ولو تعددت.","link":"https://binbaz.org.sa/fatwas/22970/حكم-جمع-عدة-كفارات-يمين-وكيفية-اخراجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/عليه مجموعة كفارات يمين هل يجمعها ويخرجها سويا.mp3","categories":["الأيمان والنذور"]},{"id":2823,"question":"بالنسبة لليمين حلف يمين اليوم وبكره يمين وبعدها يمين هل كفارة واحدة تكفي؟","title":"هل تتعدّد الكفارة بتعدُّد الأيمان واختلافها؟","answer":"الجواب: إذا كان على شيء واحد.\nس: الأيمان مختلفة؟\nالشيخ: تفهم وإلا ما تفهم، افهم! قلت اليوم: والله ما أكلم هذا الرِّجَّال، وباكر: والله ما أكلم الآخر \"زيد\"، وعقبه: والله ما أكلم \"سعيد\"، هذه ثلاث، كل واحدة لها كفارة، فهمت؟ ومن صورها أيضًا: قلت: والله ما أكلم فلان، هذه واحدة، والثانية قلت: والله ما أزور فلان، الزيارة غير الكلام، الثالثة: والله ما آكل طعامه ولا آكل وليمته، ثلاث كل واحدة لها كفارة، فهمت وإلا لا؟\nالسائل: نعم، جزاك الله خيرًا.","link":"https://binbaz.org.sa/fatwas/22972/هل-تتعدد-الكفارة-بتعدد-الايمان-واختلافها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إذا تعددت الأيمان واختلفت هل تكفي كفارة واحدة.mp3","categories":["الأيمان والنذور"]},{"id":3107,"question":"صفة إطعام ستين مسكينًا؟","title":"ما صفة إطعام ستين مسكينًا للكفّارة؟","answer":"الجواب: كل مسكين له كيلو ونصف، نصف الصاع، جَامَع في رمضان وهكذا في الظِّهار ستين مسكينًا إذا عجز عن الصيام.\nس: يطعم ستين مسكينًا على مدار السنة؟\nالشيخ: لا، حالًا، يلتمسهم ويعطيهم حالًا.\nس: مرة واحدة؟\nالشيخ: نعم.\nس: بالنسبة لإطعام المسكين كفارة اليمين أو غيره؟\nالشيخ: عشرة مساكين.\nس: ... المسكين الأول غير الثاني؟\nالشيخ: للفقير الذي يعرف ما عنده كفايته.\nس: أقصد لا بد يكون عشرة متغايرين الأول غير الثاني؟\nالشيخ: أي نعم، ما هو يرد على واحد، لا بد من عشرة، ولا بد من ستين في الستين، ما هو يردد على واحد.","link":"https://binbaz.org.sa/fatwas/23267/ما-صفة-اطعام-ستين-مسكينا-للكفارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صفة إطعام ستين مسكينا.mp3","categories":["الجماع في نهار رمضان","الأيمان والنذور"]},{"id":3689,"question":"إذا نذرت مطلقًا ما نذرت يومًا معينًا؟","title":"حكم النذر المطلق دون تحديد يوم معين","answer":"الجواب: يجب على الفور، من نذرت لله عليها أن تتصدق بكذا أو أن تصوم كذا، الأصل فيه الفورية الواجبات الأصل فيها الفورية.","link":"https://binbaz.org.sa/fatwas/23878/حكم-النذر-المطلق-دون-تحديد-يوم-معين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم النذر المطلق.mp3","categories":["الأيمان والنذور"]},{"id":3754,"question":"و\"ايم الله\" حلف؟","title":"هل من الحَلِف قول \"وايم الله\"؟","answer":"الجواب: يمين، هذا هو الأظهر، \"وايم الله\" يمين، النبي استعملها استعمال اليمين عليه الصلاة والسلام.\nس: عفا الله عنك، يعني لازم أنه ينوي بها يمين وإلا أطلقها؟\nالشيخ: ظاهرها أنها يمين، أنه متى قالها \"وايم الله لأفعل كذا، وايم الله لا أقول كذا، مثل والله، \"ايم\" صلة، صلة في الكلام.\nس: وتالله؟\nالشيخ: تالله وبالله كلها أيمان، وبالله وتالله وهالله وآلله، كلها أيمان بالهمزة والهاء.","link":"https://binbaz.org.sa/fatwas/23946/هل-من-الحلف-قول-وايم-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/قول وايم الله هل يعد يمينا.mp3","categories":["الأيمان والنذور"]},{"id":3755,"question":"إذا قال \"في عيالي\"؟","title":"هل يُعدّ يمينًا قول: \"في عيالي\"؟","answer":"الجواب: لا، اليمين: بالله أو تالله أو والله أو آلله هالله، هذه حروف القسم خمسة: بالله وتالله ووالله وهالله وآلله. والمشهور ثلاثة: الباء والتاء والواو، أما قال: في ذمتي، أو في عيالي؛ ليس بيمين.","link":"https://binbaz.org.sa/fatwas/23947/هل-يعد-يمينا-قول-في-عيالي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يعد يمينا إذا قال في عيالي.mp3","categories":["الأيمان والنذور"]},{"id":3756,"question":"لعمري؟","title":"هل كلمة \"لعمري\" يمين شرعية؟","answer":"الجواب: \"لعمري\" ليست بيمين شرعية، ليس لها حكم اليمين، فإذا قال: لعمري لأفعلن كذا ولعمري أو لا أفعلن كذا؛ لا حرج، جاء في هذا حديث عن النبي ﷺ، وفعله ابن عباس وجماعة من السلف.\nس: ما ورد حديث في \"لعمري\"؟\nالشيخ: لا بأس به جاء في حديث لا بأس به.\nس: لعمرك؟\nالشيخ: \"لعمرك\" كذلك.\nس: لعمر الله؟\nالشيخ: \"لعمر الله\" كذلك نعم.\nس: ما يكون قسم؟\nالشيخ: ما يكون له حكم القسم الذي عليه الكفارة صاحبه.\nس: تأكيد الكلام؟\nالشيخ: من باب تأكيد الكلام نعم.","link":"https://binbaz.org.sa/fatwas/23948/هل-كلمة-لعمري-يمين-شرعية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل كلمة لعمري يمينًا شرعية.mp3","categories":["الأيمان والنذور"]},{"id":3760,"question":"الذي يحلف بالقرآن والمصحف؟","title":"ما حكم من يحلف بالقرآن والمصحف؟","answer":"الجواب: القرآن كلام الله، الحلف بالله وبصفاته حق، والقرآن كلام الله، الحلف بالقرآن حلف بصفة الله، مثل: وعلم الله، وعزة الله.","link":"https://binbaz.org.sa/fatwas/23952/ما-حكم-من-يحلف-بالقران-والمصحف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم من يحلف بالقرآن والمصحف.mp3","categories":["الأيمان والنذور"]},{"id":3761,"question":"الذي يحلف بالحرام والطلاق؟","title":"حكم الحلف بالحرام والطلاق","answer":"الجواب: هذا لايجوز، لا يحلف بالحرام والطلاق. وإذا قال علي الحرام؛ هذا ما يجوز؛ لأنه ليس له أن يحرم ما أحل الله. أما إذا قال عليّ الطلاق؛ فهذا لا يسمى حلفًا من جهة الشرع، هذا حلف من جهة اللغة، من جهة عرف الفقهاء. أما اليمين فهي تكون بالباء والتاء والواو والهاء والألف، أما \"علي الطلاق\" تسمى في عرف الفقهاء يمينًا؛ لأن فيه التأكيد.\nس: ما تطلق زوجته؟\nالشيخ: لا، يكون معلقًا على حسب نيته، على الصحيح، إن كان أراد الحث أو المنع كانت يمينًا لها حكم اليمين، وإن كان أراد إيقاع الطلاق وقع.","link":"https://binbaz.org.sa/fatwas/23953/حكم-الحلف-بالحرام-والطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من يحلف بالحرام والطلاق.mp3","categories":["الأيمان والنذور"]},{"id":3763,"question":"بعض البياعين ما يبيع شيئًا إلا ويحلف عليه؟","title":"حكم الحلف على البيع والشراء","answer":"الجواب: ما ينبغي، مثل ما نهى النبي عن ذلك، ما ينبغي الحلف على البيع والشراء في الحديث:  ثلاث لا يكلمهم الله.. الحديث وفيه: ورجل جعل الله بضاعته لا يبيع إلا بيمينه ولا يشتري إلا بيمينه فينبغي التحفظ من اليمين، الله يقول: وَاحْفَظُوا أَيْمَانَكُمْ [المائدة:89] لكن إذا كان اليمين في تأكيد الخير والدعوة إلى الخير والتحذير من الشر؛ فلا بأس.","link":"https://binbaz.org.sa/fatwas/23956/حكم-الحلف-على-البيع-والشراء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الحلف على البيع والشراء.mp3","categories":["الأيمان والنذور","البيوع"]},{"id":3765,"question":"من حلف بغير الله هل يخرج من الملة؟","title":"هل يخرج من الملة من حلف بغير الله؟","answer":"الجواب: لا، عليه التوبة إلى الله، ولا يخرج من الملة؛ شرك أصغر.","link":"https://binbaz.org.sa/fatwas/23958/هل-يخرج-من-الملة-من-حلف-بغير-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يخرج من الملة من حلف بغير الله.mp3","categories":["الأيمان والنذور","الحلف بغير الله"]},{"id":3816,"question":"الذي يحلف على ترك المعصية ثم يعود إليه؟","title":"حكم من يحلف على ترك المعصية ثم يعود","answer":"الجواب: كذلك عليه الكفارة، وعليه التوبة جميعاً، إذا قال: والله لا أشرب الدخان أو لا أشرب الخمر؛ عليه أن ينفذ اليمين؛ لأن هذا حق، وعليه أن يمتنع عن المعصية ولو ما حلف، يجب عليه الامتناع من المعصية ولو ما حلف، لكن إذا حلف أكّد المقام؛ صار الواجب عليه أكثر.  لكن لو نكث وشرب الدخان أو الخمر والعياذ بالله؛ فعليه التوبة مع كفارة اليمين.","link":"https://binbaz.org.sa/fatwas/24017/حكم-من-يحلف-على-ترك-المعصية-ثم-يعود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم من يحلف على ترك المعصية ثم يعود إليه.mp3","categories":["الأيمان والنذور"]},{"id":3817,"question":"إذا حلف قبل البلوغ ورجع عن الحلف بعد البلوغ؛ يلزمه الكفارة؟","title":"هل تنعقد أيمان الصغار وتلزمهم كفارة؟","answer":"الجواب: العلماء اختلفوا في أيمان الصغار ونذورهم: هل تنعقد أو ما تنعقد قبل البلوغ؟ والأظهر أنها لا تنعقد؛ لقول النبي ﷺ: رُفع القلم عن ثلاثة منهم الصغير حتى يبلغ.","link":"https://binbaz.org.sa/fatwas/24018/هل-تنعقد-ايمان-الصغار-وتلزمهم-كفارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تنعقد أيمان الصغار، وهل عليهم كفارة.mp3","categories":["الأيمان والنذور"]},{"id":3924,"question":"مَنْ نذر نذرًا لا يملكه يُكفّر؟","title":"حكم مَنْ نذر نذرًا لا يملكه","answer":"الجواب: لا، ما جاء فيه تكفير، إنما جاء في نذر المعصية، أما هذا نذر باطل.","link":"https://binbaz.org.sa/fatwas/24142/حكم-من-نذر-نذرا-لا-يملكه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم من نذر نذرًا لا يملكه.mp3","categories":["الأيمان والنذور"]},{"id":3940,"question":"إذا لم يقدر على الإطعام تسقط عنه الكفارة؟","title":"هل تسقط الكفارة عمن لم يستطع الإطعام؟","answer":"الجواب: احتج العلماء بهذا على سقوطها، وأن النبي ﷺ قال: أطعمه أهلك، ولم يأمره بالقضاء، فدل ذلك على سقوط كفارة الوطء عن العاجز، بخلاف الظهار، وبخلاف القتل، فإنها في الذمة حتى يؤدي.","link":"https://binbaz.org.sa/fatwas/24163/هل-تسقط-الكفارة-عمن-لم-يستطع-الاطعام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من لم يستطع الإطعام في الكفارة، هل تسقط عنه.mp3","categories":["الأيمان والنذور"]},{"id":3946,"question":"إذا كان الحالف يعظّم المحلوف؟","title":"حكم من يحلف بغير الله تعظيمًا أو عادة","answer":"الجواب: إذا كان يعتقد فيه يكون شركًا أكبر، إذا كان يحلف به يعتقد فيه أنه يصلح لأن يعبد أو يُدعى أو فيه سر أنه ولي يُدعى من دون الله؛ فهذا الاعتقاد يجعله كفرًا أكبر. أما إذا كان يجري على لسانه من غير قصد لمحبته له أو تعظيمه في نفسه ولكن لا يعتقد فيه أنه يصلح للعبادة... أو جرى على لسانه هكذا على عادته القديمة؛ يكون من الشرك الأصغر.","link":"https://binbaz.org.sa/fatwas/24169/حكم-من-يحلف-بغير-الله-تعظيما-او-عادة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم إذا كان الحالف يعظم المحلوف.mp3","categories":["الأيمان والنذور","الحلف بغير الله"]},{"id":3947,"question":"بعض الناس لو طلب منه اليمين بالله يحلف، ولو طلب منه اليمين على الولي فلان أو السيد فلان يخاف؟","title":"حكم تعظيم الأولياء في الحَلِف وخشيتهم","answer":"الجواب: يختلف، لا شك أن قلوبهم مريضة بالشرك، نسأل الله العافية، ولهذا يعظّمون أولياءهم أكثر مما يعظّمون الله، هذا إنما يقع من الكفرة الفجار، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/24170/حكم-تعظيم-الاولياء-في-الحلف-وخشيتهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحلف بالله والخوف عن الحلف على الولي أو السيد.mp3","categories":["الأيمان والنذور","نواقض الإسلام"]},{"id":4047,"question":"قوله \"بذمتك\"؟","title":"حكم قول \"بذمتك\" في الحلف","answer":"الجواب: إن أراد الحلف بالباء، إن أراد الحلف بالذمة، ما يجوز.  أما العادة المعروفة عن الناس يقول \"في ذمتك\" يعني: أعطني الحقيقة لا تكذب.","link":"https://binbaz.org.sa/fatwas/24284/حكم-قول-بذمتك-في-الحلف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم قول بذمتك في الحلف.mp3","categories":["الأيمان والنذور"]},{"id":4146,"question":"يُوفُونَ بِالنَّذْرِ [الإنسان:7]؟","title":"ما تفسير قوله تعالى: {يُوفُونَ بِالنَّذْرِ..}؟","answer":"الجواب: هذه نذور الطاعات التي نذورها لله من دون تعليقٍ، ومن دون شيءٍ، ومن دون قصدٍ، بل نذروها لله، يتقرَّبون بها إليه على الوجه الذي شرع، كما قال ﷺ: مَن نذر أن يُطيع الله فليُطِعْهُ، ولكنَّهم هم منهيُّون أن يبدؤوها، فإذا فعلوها وجب الوفاء إذا كان من طاعة الله جلَّ وعلا.","link":"https://binbaz.org.sa/fatwas/24394/ما-تفسير-قوله-تعالى-يوفون-بالنذر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بقوله تعالى يُوفُونَ بِالنَّذْرِ.mp3","categories":["التفسير","الأيمان والنذور"]},{"id":4147,"question":"س: النذر بغير تعليق كيف يكون؟","title":"ما صفة النذر المعلّق والنذر المطلق؟","answer":"الجواب: تقول: \"لله عليَّ أن أتصدَّق بمئة ريـال\" هذا ما هو مُعلَّق، \"لله عليَّ أن أصوم الاثنين والخميس\" هذا ما هو مُعلَّق.  التعليق: \"لله عليَّ أن أصوم شهرًا إذا شفا الله ولدي\" هذا مُعلَّق، \"لله عليَّ أن أتصدَّق بكذا إذا ردَّ الله ولدي من سفره\"، \"لله عليَّ كذا وكذا إذا نجح ولدي من الجامعة\" هذا المعلَّق.\nس: وإذا ما نجح؟\nج: ما يصير عليه شيء.","link":"https://binbaz.org.sa/fatwas/24397/ما-صفة-النذر-المعلق-والنذر-المطلق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/النذر المطلق والنذر المعلق.mp3","categories":["الأيمان والنذور"]},{"id":4148,"question":"النذر مذمومٌ كله؟","title":"هل النذر مذمومٌ كله؟","answer":"الجواب: كله مذموم نعم، هذا ظاهر الحديث، ما ينبغي النذر، لكن إذا نذر ووقع في الأمر إن كان طاعةً أوفى، وإن كان ما هو بطاعةٍ فلا وفاء عليه، وعليه كفَّارة يمين؛ لأنَّ النذر تدخله الأحكام الخمسة: التحريم، والوجوب، والكراهة، والاستحباب، والإباحة.\nفإذا قال: لله عليه أن يصوم كذا أو يتصدق بكذا؛ هذه طاعة، يلزمه الوفاء.  وإذا قال: لله عليه أن يشرب الخمر؛ هذا مُحرَّم، لا يشرب الخمر، وعليه كفَّارة يمين.  وإذا قال: لله عليه أن يهجر فلانًا أو لا يزور فلانًا؛ هذا نذر مكروه، يُكفِّر كفَّارة يمين، ولا يهجر أخاه.  وإذا قال: لله عليه أنه ما يأكل طعام فلانٍ، أنه ما يأكل هذا الطعام؛ فهو مُخيَّر: إن شاء أوفى بالنذر، وإن شاء كفَّر عن يمينه وأكل من الطَّعام.","link":"https://binbaz.org.sa/fatwas/24398/هل-النذر-مذموم-كله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/النذر مذمومٌ كله.mp3","categories":["الأيمان والنذور"]},{"id":4157,"question":"مَن حلف يمينًا أنه يترك هذه المعصية ثم رجع للمعصية؟","title":"حكم مَن حلف أن يترك معصية ثم رجع لها","answer":"الجواب: عليه التوبة إلى الله، عليه التوبة إلى الله وكفَّارة يمين جميعًا، لا يرجع، لا يجوز له الرجوع: والله لا يشرب الخمر، والله لا يتعاطى التدخين، والله لا يعقّ والديه، يلزمه هذا، ولو ما حلف، لكن إذا حلف صار هذا تأكيدًا للمقام، فيلزمه الكفُّ عن المعصية، فإذا بُلي بها -نعوذ بالله من ذلك- فعليه الكفَّارة والتوبة جميعًا؛ كفَّارة اليمين مع التوبة والنَّدم.","link":"https://binbaz.org.sa/fatwas/24408/حكم-من-حلف-ان-يترك-معصية-ثم-رجع-لها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم مَن حلف أن يترك معصية ثم رجع لها.mp3","categories":["الأيمان والنذور"]},{"id":4161,"question":"اليمين الغموس لها كفَّارة؟","title":"هل لليمين الغموس كفَّارة؟","answer":"الجواب: ما لها كفَّارة اليمين الغموس، إثمها أعظم، الكفَّارة تكون فيما هو أسهل، في المستقبل لا يفعله ثم فعله، أو تركه ثم فعل، أو لا يفعل ثم فعل.  أما اليمين الغموس فهي عظيمة، إذا وقع فيها عليه التوبة إلى الله، وردّ الحق إلى أهله، فلو قال مثلًا: والله ما عندي لك شيء، وهو عنده هذا الشيء، أقرضه مثلًا ألف ريـال أو أكثر أو أقل، ثم طالبه بالحقِّ وقال: ما عندي لك شيء، ولا أقرضتك شيئًا، ولا عنده بينة، قد أحسن به الظنّ، ولا أشهد عليه، فحلف أنه ما عنده له شيء، فهذه اليمين الغموس، هذا من جنسها، هذا من أمثالها، فإذا هداه الله يردّ الحقَّ إلى صاحبه ويتوب إلى الله ويكفي.\nس: إذا عَرَّض وقال: ما لك عندي حقّ ..؟\nج: وهو كاذب وإلا صادق؟ وهو عنده حقٌّ له؟ هذه يمين غموس إذا حلف عليها؛ لأنَّ الحقَّ قد يكون قرضًا، قد يكون دَيْنًا، قد يكون عاريةً خانها، أمانةً خانها، لا بد على حسب نيته.","link":"https://binbaz.org.sa/fatwas/24415/هل-لليمين-الغموس-كفارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل لليمين الغموس كفَّارة.mp3","categories":["الأيمان والنذور"]},{"id":4162,"question":"إذا عاهد على شيء؟","title":"حكم مَنْ عاهد على شيء ثم أفشاه","answer":"الجواب: إذا قال: \"عليَّ عهد الله أني لا أُخبر عن هذا السرّ\" فلا يجوز له أن يُخبر، وإن خبّر عليه الإثم، وليست بيمينٍ، ليست يمينًا، بل عليه التوبة إلى الله إذا أفشى السرَّ.","link":"https://binbaz.org.sa/fatwas/24416/حكم-من-عاهد-على-شيء-ثم-افشاه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم إذا عاهد على شيء.mp3","categories":["الأيمان والنذور"]},{"id":4165,"question":"قوله: عليَّ الحرام كذا؟","title":"حكم قول \"عليَّ الحرام..\"","answer":"الجواب: مثل اليمين سواء، إذا رأى المصلحة يُكفِّر، إلا إذا كان أراد تحريم زوجته؛ صار بذلك مُظاهرًا، عليه كفَّارة الظِّهار، أما لو قال: عليه الحرام لا يفعل، عليه الحرام لا يزور فلانًا، قصده منع نفسه، ما قصده تحريم الزوجة، هذا حكمه حكم اليمين، مثلما قال سبحانه: يَا أَيُّهَا النَّبِيُّ لِمَ تُحَرِّمُ مَا أَحَلَّ اللَّهُ لَكَ تَبْتَغِي مَرْضَاتَ أَزْوَاجِكَ وَاللَّهُ غَفُورٌ رَحِيمٌ [التحريم:1].","link":"https://binbaz.org.sa/fatwas/24419/حكم-قول-علي-الحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم قول عليَّ الحرام.mp3","categories":["الأيمان والنذور"]},{"id":4167,"question":"... يبدأ بالتكفير والعمل، أو يعمل ويكفّر؟","title":"هل يجوز عملُ ما حُلف عليه قبل الكفارة؟","answer":"الجواب: جاء هذا وهذا، جاء في الرواية: فكفِّر عن يمينك، وائتِ الذي هو خير، وفي الأخرى: فائتِ الذي هو خير، وكفِّر عن يمينك، وفي بعضها: ثم ائتِ الذي هو خير، يُقدم الكفَّارة، الأمر واسع.  أما في الظهار فلا بدّ أن يبدأ بالكفَّارة: فَتَحْرِيرُ رَقَبَةٍ مِنْ قَبْلِ أَنْ يَتَمَاسَّا [المجادلة:3]، أما في غير الظهار فمُخيّر، إذا بدأ بها كان أفضل: فكفِّر عن يمينك، ثم ائتِ الذي هو خير.","link":"https://binbaz.org.sa/fatwas/24421/هل-يجوز-عمل-ما-حلف-عليه-قبل-الكفارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يبدأ بكفارة اليمن أو يجوز العمل قبل الكفارة.mp3","categories":["الأيمان والنذور"]},{"id":4168,"question":"يجوز له أن يحلف ألا يتكلم يومًا كاملاً؟","title":"حكممن حلف ألا يتكلم يومًا كاملاً","answer":"الجواب: هو ما ينبغي أن يحلف على ألا يتكلم، إذا كان أراد بالكلام العادي؛ يُكره له ذلك. أما إذا أراد بالكلام الذي فيه ردّ السلام، وفيه التَّسبيح، وفيه قراءة القرآن الواجبة؛ فهذا حرام منكر، يجب أن يحنث.  لكن إذا أراد كلامًا عاديًّا ما هو بواجبٍ كُره له ذلك، مثلما أنكر النبيُّ على أبي إسرائيل لما نذر ألا يتكلم، وأن يقف في الشمس.","link":"https://binbaz.org.sa/fatwas/24422/حكم-من-حلف-الا-يتكلم-يوما-كاملا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الحلف على ألا يتكلم يومًا كاملاً.mp3","categories":["الأيمان والنذور"]},{"id":4170,"question":"يقول:... عليَّ حرام، أو نذرتُ، أو لله عليَّ ألا آكل كذا، أو لا أشرب كذا، الراجح من أقوال العلماء أنَّ ذلك لا ينعقد إلا إذا قرنه بحلفٍ، فيلزمه كفَّارة يمين؟","title":"هل ينعقد النذر إذا لم يُقرن بحلف؟","answer":"الجواب: لا، الصواب أنه ينعقد، لكن فيه كفَّارة يمين، الصواب أنه ينعقد، نذر منعقدة، وعليه كفَّارة يمين، إلا أن تكون معصية؛ فليس له أن يُوفي في المعصية، وعليه الكفَّارة على قولين، والأرجح أنَّ عليه كفَّارة أيضًا حتى في نذر المعصية ما دام مسلمًا، ما دام ما هو بنذر شرك، ولهذا في الصحيح: كفَّارة النذر كفَّارة اليمين.\nوينبغي أن يُعلم أنَّ غالب العلماء -خصوصًا المتقدمين- يخفى عليهم أشياء من السنة؛ فيقولون بمحض اجتهادهم، على حسب ما بلغهم من السنة، ثم تبلغ السنة مَن بعدهم ممن جمعها واعتنى بها؛ فيظهر لهم من الأحكام ما لم يظهر لمن قبلهم بسبب خفاء بعض السنة عليهم، فليس كل واحدٍ يجمع الأحاديث ويحفظها كلها.","link":"https://binbaz.org.sa/fatwas/24426/هل-ينعقد-النذر-اذا-لم-يقرن-بحلف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل ينعقد النذر إذا لم يُقرن بحلف.mp3","categories":["الأيمان والنذور"]},{"id":4244,"question":"الحلف في التجارة على سلعة معينة إذا كنت مثلًا متأكدًا أنها جيدة وسعرها جيد وأنا بار؟","title":"هل يجوز الحلف في التجارة مع الصدق؟","answer":"الجواب: لا بأس، لكن لا يكثر بس، يقلّل من الأيمان، إذا دعت الحاجة لليمين وهو صادق فلا بأس، لكن ينبغي له ألا يكثر .","link":"https://binbaz.org.sa/fatwas/24511/هل-يجوز-الحلف-في-التجارة-مع-الصدق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحلف في التجارة على سلعة.mp3","categories":["الأيمان والنذور"]},{"id":4268,"question":"من نذر عند تلفظه بالنذر يُوصى بأن يقول: إن شاء الله؟","title":"حكم قول \"إن شاء الله\" عند النذر","answer":"الجواب: الشيخ: نعم؟\nس: من نذر نذرًا مباحًا يُوصى بأن يقول: إن شاء الله، قل: إن شاء الله؟\nالجواب: لا ينذر بالمرة، مكروه له النذر، الرسول ﷺ قال: لا تنذروا فإذا قال: \"إن شاء الله\" لم يتم النذر، أو قال: \"والله إن شاء الله\" ما يصير شيء، يقول النبي ﷺ: من حلف فقال في يمينه: إن شاء الله فلا حنث عليه.","link":"https://binbaz.org.sa/fatwas/24538/حكم-قول-ان-شاء-الله-عند-النذر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من قال إن شاء الله عند النذر.mp3","categories":["الأيمان والنذور"]},{"id":4273,"question":"النذر في معصية ؟","title":"حكم النذر في معصية","answer":"الجواب: يحرم الوفاء به.","link":"https://binbaz.org.sa/fatwas/24543/حكم-النذر-في-معصية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/النذر في معصية.mp3","categories":["الأيمان والنذور"]},{"id":4289,"question":"الرجل إذا قال لزوجته هي عليه حرام بنية الطلاق يكون طلاقًا؟","title":"حكم من قال لزوجته هي عليه حرام بنية الطلاق","answer":"الجواب: لا - يكون ظهارًا .","link":"https://binbaz.org.sa/fatwas/24561/حكم-من-قال-لزوجته-هي-عليه-حرام-بنية-الطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يقع الطلاق إذا قال لزوجته هي عليه حرام بنية الطلاق.mp3","categories":["الطلاق","الأيمان والنذور","الظهار"]},{"id":4373,"question":"ما الفرق بين قوله ولحياتي ولعمري؟","title":"حكم القسم بقول \"لحياتي\" و\"لعمري\"","answer":"الجواب: لعمري هذه جائزة ما فيها واو، لحياتي لقسمي قسمي بكذا وكذا، كان النبي ﷺ يستعملها واستعملها غيره فهذا لا حرج فيه، أما إذا جاءت الواو أو الباء أو التاء أو الهمزة منع.\nس: لعمرك قسم؟\nج: نعم لَعَمْرُكَ إِنَّهُمْ لَفِي سَكْرَتِهِمْ يَعْمَهُونَ [الحجر:72].\nس: ما هي حروف القسم؟\nالجواب: أربعة: الواو، والباء، والتاء، والهمزة.","link":"https://binbaz.org.sa/fatwas/24650/حكم-القسم-بقول-لحياتي-ولعمري","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الفرق بين قول العبد ولحياتي ولعمري.mp3","categories":["الأيمان والنذور"]},{"id":4375,"question":"الحلف بالأمانة أي نوع من أنواع الكفر؟","title":"حكم الحلف بالأمانة","answer":"الجواب: من الشرك الأصغر، يقول النبي ﷺ: من حلف بالأمانة فليس منا.","link":"https://binbaz.org.sa/fatwas/24652/حكم-الحلف-بالامانة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من أي نوع من أنواع الكفر الحلف بالأمانة.mp3","categories":["الأيمان والنذور","الحلف بغير الله"]},{"id":4376,"question":"القسم بآيات الله؟","title":"حكم القسم بآيات الله","answer":"الجواب: لا بأس القرآن كلام الله، إذا أقسم بآت الله يقصد القرآن لا بأس.","link":"https://binbaz.org.sa/fatwas/24653/حكم-القسم-بايات-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم القسم بآيات الله.mp3","categories":["الأيمان والنذور"]},{"id":4378,"question":"إذا حلف بآبائه قال: أن تفعل كذا، هل له أن يعصيه لأنه لم يحلف بالله؟","title":"ماذا يلزم المحلوف عليه إذا حُلِف بالآباء؟","answer":"الجواب: عليه التوبة من ذلك، ولا يلزم أحدًا شيء، ما تعتبر، يمينه باطلة، عليه التوبة منها، والمحلوف عليه ما يلزمه شيء.","link":"https://binbaz.org.sa/fatwas/24655/ماذا-يلزم-المحلوف-عليه-اذا-حلف-بالاباء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ماذا يلزم المحلوف إذا حُلِف بالآباء.mp3","categories":["الأيمان والنذور"]},{"id":4929,"question":"يقدّم الكفارة؟","title":"هل يجوز تقديم الكفارة لمن رجع في يمينه؟","answer":"الجواب:\nمخير؛ إن شاء قدمها وإن شاء أخرها؛ لحديث: فليأت الذي هو خير ثم يكفر عن يمينه  جاء بعدة روايات؛ فإن شاء قدّمها وإن شاء أخّرها.","link":"https://binbaz.org.sa/fatwas/26690/هل-يجوز-تقديم-الكفارة-لمن-رجع-في-يمينه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يجوز تقديم الكفارة لمن رجع في يمينه؟.mp3","categories":["الأيمان والنذور"]},{"id":5033,"question":"إذا حلف وهو يغلب على ظنه أنَّ ذلك الشيء وقع وهو لم يقع، فهل عليه كفَّارة؟","title":"حكم مَنْ حَلَف على شيء بغَلَبَة ظنه","answer":"الجواب: يعني: حلف أنَّ هذا الشيء وقع؟\nس: حلف أن شيئًا وقع وهو لم يقع.\nج: يعني: ناسيًا؟\nس: غلبة ظنٍّ.\nج: والله إنَّ فلانًا جاء، والله إنَّ فلانًا وصل، والله إنَّ الشهر دخل، يظن هذا؟\nس: نعم.\nج: الصواب أنَّه ليس عليه كفَّارة؛ لأنه يظن صِدْقَ نفسه.","link":"https://binbaz.org.sa/fatwas/28966/حكم-من-حلف-على-شيء-بغلبة-ظنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم من حلف على شيء بغلبة طنه.mp3","categories":["الأيمان والنذور"]},{"id":5034,"question":"هل الحلف لا يكون إلا بعد العصر؟","title":"هل الحلف بعد العصر أشَدُّ من غيره","answer":"الجواب: لا، أشد وأخطر، فالحلف يكون في كل وقتٍ، لكن الحلف بعد العصر إذا كان كاذبًا يكون أشدّ، أخطر.","link":"https://binbaz.org.sa/fatwas/28967/هل-الحلف-بعد-العصر-اشد-من-غيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل الحلف بعد العصر أشد من غيره؟.mp3","categories":["الأيمان والنذور"]},{"id":5035,"question":"إذا قال: بأبي وأمي أنت يا فلان؟","title":"معنى وحكم التفدية بالوالدين","answer":"الجواب: هذا معناه: أفديك بأبي وأمي، فداء ما هي بيمين.","link":"https://binbaz.org.sa/fatwas/28968/معنى-وحكم-التفدية-بالوالدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى وحكم التفدية بالوالدين.mp3","categories":["الأيمان والنذور"]},{"id":5156,"question":"أيضًا له سؤال آخر يقول فيه: هل قول الرجل في الحلف: \"عليَّ الطلاق\" يُعدُّ من الحلف بغير الله؟ وهل يقع الطلاق؟","title":"حكم يمين الطلاق وهل يُعدُّ من الحلف بغير الله؟","answer":"الجواب: لا، ليس من الحلف بغير الله، ويُعَدُّ حَلِفًا من حيث اللغة، فيُسمَّى: يمينًا من جهة اللغة، فإذا أراد به المنع أو الحثَّ أو التَّصديق أو التَّكذيب يُسمَّى: يمينًا من حيث اللغة، وفيه الكفَّارة، فإذا قال: \"عليه الطلاق ما يُسافر\"، وقصد الامتناع من السفر، ولم يقصد إيقاع الطلاق، أو قال: \"عليَّ الطلاق ما تذهبين في هذا اليوم\"، أو: \"عليَّ الطلاق ما أُكلمك اليوم\"، وقصده الامتناع، وليس قصده فراقها؛ فهذا يُسمَّى: يمينًا، حكمه حكم اليمين، وليس بمحرمٍ، بل مكروه، وله كفَّارة يمين. فإذا قال: \"عليه الطلاق ما يُكلِّمها\" وقصد الامتناع، ولم يقصد فراقها، أو قال: \"عليه الطلاق ما تذهبين هذا اليوم\"، وقصد منعها، ولم يقصد فراقها؛ ففيه كفَّارة يمين، أو قال: \"عليه الطلاق ما يأكل طعامَ فلانٍ\"، أو: \"عليَّ الطلاق ما آكل طعامه ولا آكل ذلك اليوم\"، وقصد الامتناع، ولم يقصد فراق أهله؛ ففيه كفَّارة يمين إذا جلس وأكل الطعام.","link":"https://binbaz.org.sa/fatwas/30074/حكم-يمين-الطلاق-وهل-يعد-من-الحلف-بغير-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 97.mp3","categories":["الأيمان والنذور"]},{"id":5208,"question":"هذا سائل يقول: ما حكم قول البعض: \"عليَّ الحرام أن أفعل كذا وأفعل كذا\"؟","title":"ما حكم قول «عليَّ الحرام أن أفعل كذا»؟","answer":"الجواب: لا يجوز هذا، ليس له أن يقول هذا الكلام، وإذا قاله فعليه كفَّارة يمين إذا خالف اليمين، ولا يجوز أن يقول: \"عليَّ الحرام\"، فالله أنكر على نبيه ذلك فقال: يَا أَيُّهَا النَّبِيُّ لِمَ تُحَرِّمُ مَا أَحَلَّ اللَّهُ لَكَ تَبْتَغِي مَرْضَاتَ أَزْوَاجِكَ وَاللَّهُ غَفُورٌ رَحِيمٌ  ۝  قَدْ فَرَضَ اللَّهُ لَكُمْ تَحِلَّةَ أَيْمَانِكُمْ [التحريم:1- 2]، فإذا قال: \"عليَّ الحرام ما أُكلم فلانًا\"، ثم كلَّمه فعليه كفَّارة يمين، مع التوبة والاستغفار، أو قال: \"عليَّ الحرام ما أُسافر\" وسافر، فعليه كفَّارة يمين، وأشباه ذلك، مع التوبة والاستغفار.","link":"https://binbaz.org.sa/fatwas/30152/ما-حكم-قول-علي-الحرام-ان-افعل-كذا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 184.mp3","categories":["الأيمان والنذور"]},{"id":5307,"question":"ما حكم من قال: \"أكون يهوديًا أو نصرانيًّا إن فعلت كذا\" ثم فعل، أو الحلال عليّ حرام إن لم أفعل كذا، ثم لم يفعل؟","title":"حكم من قال: أكون يهوديًا أو نصرانيًّا إنْ فعلت كذا","answer":"الجواب: لا يجوز له الكلام هذا، لا يجوز، الرسول ﷺ نهى عن هذا، الرسول ﷺقال: مَن حَلَفَ بمِلَّةٍ غيرِ الإسْلَامِ كَاذِبًا مُتَعَمِّدًا فَهو كما قَالَ، ولا يجوز تحريم ما أحل الله، يقول الله جل وعلا: يَا أَيُّهَا النَّبِيُّ لِمَ تُحَرِّمُ مَا أَحَلَّ اللَّهُ لَكَ [التحريم:1] فلا يجوز للإنسان أن يحرم ما أحل الله له، يجب الحذر من هذا، إذا قال عليّ الحرام ما أفعل هذا، أو علي الحرام ما أتكلم كلامًا؛ فعليه كفارة يمين، كما قال الله جل وعلا: يَا أَيُّهَا النَّبِيُّ لِمَ تُحَرِّمُ مَا أَحَلَّ اللَّهُ لَكَ تَبْتَغِي مَرْضَاتَ أَزْوَاجِكَ وَاللَّهُ غَفُورٌ رَحِيمٌ ۝ قَدْ فَرَضَ اللَّهُ لَكُمْ تَحِلَّةَ أَيْمَانِكُمْ... [التحريم:1-2] إذا قال: عليه حرام ما يكلم فلانًا، أو ما يأكل طعام فلان، أو ما يزور فلانًا، ثم نقض كلامه؛ فعليه كفارة يمين، حكمه حكم اليمين. السؤال: يقول أيضًا: وهل لو قال: أقسمت عليك لتفعلن كذا؛ يكون قسمًا، وهل قوله: يمين الله أو لعمر الله أو ايم الله قسم؟ الشيخ: \"لعمري أو لعمرك\" ليست بقسم، و\"أقسمت عليك\" ليس بقسم حتى يصرِّح، أقسمت عليك بالله، أو يقول: والله أو تالله أو بالله، أما \"وايم الله\" قسم، إذا قال \"وايم الله\" لأفعلن كذا، هذا قسم، كما قال ﷺ: وايم الله لو أن فاطمة بنت محمد سرقت لقطعت يدها وايم الله هذه قسم.[1]","link":"https://binbaz.org.sa/fatwas/30961/حكم-من-قال-اكون-يهوديا-او-نصرانيا-ان-فعلت-كذا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 027.mp3","categories":["الأيمان والنذور"]},{"id":5325,"question":"رجل نذر لله أن يذبح عشرة من الغنم فلما ذبح ما نذر به أكل من اثنتين منها، فهل أكله هذا جائز أم لا؟ وإذا كان أكله هذا غير جائز فهل يذبح اثنتين من الغنم مكان التي أكل منها؟","title":"هل يجوز لصاحب النذر الأكل منه؟","answer":"الجواب: إن كان ناويًا أن يأكل منها فليس عليه شيء، أما إن كان ما نوى فإنه يَغْرَم مقدار ما أكل، يشتري من السوق لحمًا مقدار ما أكل ويتصدق به، ولا يلزمه ذبيحتان، يغرم مقدار ما أكل من اللحم، كيلو، نصف كيلو، قدر ما يظن، ويشتري من السوق ويتصدّق به.[1]","link":"https://binbaz.org.sa/fatwas/30992/هل-يجوز-لصاحب-النذر-الاكل-منه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 046.mp3","categories":["الأيمان والنذور"]},{"id":5687,"question":"قد عزمني أحد الإخوة، وقال لي: لازم تحضر أحد أخويك العزيمة، وحرمت على الذي أمون عليه منهم، ولم يذهب معي؟","title":"حكم من حلف على شخص ولم يبر بقسمه","answer":"الجواب: إذا ما ذهب معه ما عليه شيء، لكن لو أنه أجاب الداعي، وراح معه بعض إخوانه كان أحسن، يحضر له بعض إخوانه معه الذين دعاهم يكون أحسن، ولكن هو لما حرم عليه أن يذهبوا معه، ولم يذهبوا معه، وتمموا له ما عليه شيء. السؤال: ما عليه إطعام؟ الجواب: لا، ما راحوا عليه، حرم عليهم أن يروحوا، وما راحوا، ما نقضوا عليه. السؤال: .......؟ الجواب: أين السائل؟ على كل حال إن كان قصده: أنه شدد عليهم حرم عليهم يروحوا معه، وما راحوا عليه كفارة يمين، وإن كان قصده أن حرم عليهم أنهم ما يروحون وأطاعوه فلا شيء عليه.","link":"https://binbaz.org.sa/fatwas/989/حكم-من-حلف-على-شخص-ولم-يبر-بقسمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_18.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":5691,"question":"قد عزمني أحد الإخوة، وقال لي: لازم تحضر أحد أخويك العزيمة، وحرمت على الذي أمون عليه منهم، ولم يذهب معي؟","title":"حكم من حلف على شخص ولم يبر بقسمه","answer":"الجواب: إذا ما ذهب معه ما عليه شيء، لكن لو أنه أجاب الداعي، وراح معه بعض إخوانه كان أحسن، يحضر له بعض إخوانه معه الذين دعاهم يكون أحسن، ولكن هو لما حرم عليه أن يذهبوا معه، ولم يذهبوا معه، وتمموا له ما عليه شيء. السؤال: ما عليه إطعام؟ الجواب: لا، ما راحوا عليه، حرم عليهم أن يروحوا، وما راحوا، ما نقضوا عليه. السؤال: .......؟ الجواب: أين السائل؟ على كل حال إن كان قصده: أنه شدد عليهم حرم عليهم يروحوا معه، وما راحوا عليه كفارة يمين، وإن كان قصده أن حرم عليهم أنهم ما يروحون وأطاعوه فلا شيء عليه.","link":"https://binbaz.org.sa/fatwas/989/حكم-من-حلف-على-شخص-ولم-يبر-بقسمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_18.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":5727,"question":"أحد الإخوة يسأل: إذا كانت عليه ديون كثيرة، فما هو معنى الدين؟ وأردت أن أكفر عما عليه كله، هل يجوز أن أدفع عن كل دين صاع من الأرز على مسكين واحد، يعني عن كل دين صاع واحد على مسكين واحد؟ وهل يدفع عن السائلين إذا لم يوجد غيرهم؟ وهل يدفع على الرجل وأولاد كل واحد منهم له صاع؟","title":"أنواع الكفارات ومستحقيها","answer":"الجواب:  هذا كلام مجمل، كيف الدين؟ الدين ما يؤدى عنه الأصواع الدين يؤدى لأهله، هذا السؤال ما أوضحه صاحبه، الدين إذا كان نقودًا يعطى أهله النقود من الذهب والفضة والأوراق، إذا كان الدين طعامًا يؤدى الطعام أهله، إذا كان الدين قهوة سكر يؤدى لأهله. هذا السؤال إنما الأصواع هذه للزكوات، والكفارات، إذا كان في ذمته كفارة ظهار، وكفارة الوطء في رمضان، وعدل عن الصيام، لا يستطيع الصيام شهرين يؤدي الكفارة لكل مسكين نصف صاع، ما هو صاع، نصف صاع يكفي، كل واحد له نصف الصاع من قوت البلد عن الكفارة التي في ذمته من ظهار عن زوجته، وتحريم لها، أو وطء في رمضان فإنه يعتق رقبة، وإن عجز صام شهرين متتابعين، فإن عجز أطعم ستين مسكينًا، ثلاثين صاعًا من قوت البلد، كل صاع بين اثنين، هذا محل الأصواع.  وهكذا لو أخر صيام رمضان من غير علة، ولم يقضه حتى جاء رمضان، آخر يقضي ما ضيع من صيام رمضان، ويطعم عن كل يوم مسكينًا زيادة مع القضاء نصف صاع عن كل يوم يجمعها، ويعطيها مسكينًا واحدًا.  والسائلون يعطون من الزكاة؛ لأنهم فقراء، السائلون إذا كانوا ... ويزعمون أنهم فقراء يعطون من الزكاة والكفارات؛ لأنهم أهلها داخلون في قوله: إِنَّمَا الصَّدَقَاتُ لِلْفُقَرَاء وَالْمَسَاكِينِ [التوبة:60] إلا إذا علمت أن هذا السائل كذاب، وأنه غني تنكر عليه، وتقول له: اتق الله، ليس لك السؤال وأنت غني، يقول النبي ﷺ في الحديث الصحيح: من سأل الناس أموالهم تكثرًا، فإنما يسأل جمرًا، فليستقل، أو ليستكثر إنما يسأل نارًا -نعوذ بالله- رواه مسلم في الصحيح.  ويقول -عليه الصلاة والسلام-: لا يزال الرجل يسأل الناس حتى يأتي يوم القيامة، وليس في وجهه مزعة لحم متفق عليه، فإذا كان يسأل وأنت تعلم أنه كذاب، وأنه غني فلا تعطه من الزكاة، ولا تصدق عليه، بل أنكر عليه، وقل له: هذا حرام عليك، لا يجوز لك، وقوله تعالى: وَفِي أَمْوَالِهِمْ حَقٌّ لِّلسَّائِلِ وَالْمَحْرُومِ [الذاريات: 19] يعني السائل المجهود، أو المعروف الذي يعرف أنه فقير.  والسائلون ثلاثة أقسام: قسم يعرف أنه فقير فيعطى، وقسم لا يعرف فيعطى، والقسم الثالث معروف بأنه غني لا يعطى؛ لأنه ظالم لنفسه، فلا يستحق الزكاة، ولا يجوز له السؤال. أما السائل الفقير، والسائل المجهول الذي لا تعرف حاله، فإنك تعطيه من الزكاة، ومن غيرها؛ لأن الظاهر أنه فقير، والله قال: وَفِي أَمْوَالِهِمْ حَقٌّ لِّلسَّائِلِ وَالْمَحْرُومِ [الذاريات: 19] .  قال بعض أهل العلم: أن الحق المعلوم هو الزكاة، وقال آخرون: إنه أمر غير الزكاة زائد، تفضلًا منهم، وإحسانًا منهم إلى الفقراء والمحاويج والسائلين، والمحروم هو الفقير الذي حرم المال.","link":"https://binbaz.org.sa/fatwas/1037/انواع-الكفارات-ومستحقيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_59.mp3","categories":["الجماع في نهار رمضان","الأيمان والنذور","الجنايات والحدود"]},{"id":5758,"question":"مرض ولدي وهو صغير مرضًا شديدًا، وقلت: إن أحياه الله أصوم من كل سنة شهر رجب، وأنا الآن لم أصم ولو شهرًا واحدًا، حيث إني كل سنة حامل، أو مرضع، ومضى لهذا النذر حوالي تسع سنوات، وأنا لا أستطيع، وغير صحيحة، فماذا أفعل؟","title":"نذرت صيام شهر رجب من كل عام","answer":"الجواب:  هذا نذر مكروه، نذرها أن تصوم شهر رجب كل سنة مكروه، فعليها كفارة يمين، ويكفي، فإنه صوم مكروه، والنذر مكروه، فيكفي فيه كفارة يمين، فإذا كفرت كفارة يمين، أطعمت عشرة مساكين لكل مسكين نصف صاع من قوت البلد، أو تكسوهم؛ كفى ذلك، والحمد لله، وليس عليها صيام.","link":"https://binbaz.org.sa/fatwas/1097/نذرت-صيام-شهر-رجب-من-كل-عام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_103.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":5773,"question":"مرض ولدي وهو صغير مرضًا شديدًا، وقلت: إن أحياه الله أصوم من كل سنة شهر رجب، وأنا الآن لم أصم ولو شهرًا واحدًا، حيث إني كل سنة حامل، أو مرضع، ومضى لهذا النذر حوالي تسع سنوات، وأنا لا أستطيع، وغير صحيحة، فماذا أفعل؟","title":"نذرت صيام شهر رجب من كل عام","answer":"الجواب:  هذا نذر مكروه، نذرها أن تصوم شهر رجب كل سنة مكروه، فعليها كفارة يمين، ويكفي، فإنه صوم مكروه، والنذر مكروه، فيكفي فيه كفارة يمين، فإذا كفرت كفارة يمين، أطعمت عشرة مساكين لكل مسكين نصف صاع من قوت البلد، أو تكسوهم؛ كفى ذلك، والحمد لله، وليس عليها صيام.","link":"https://binbaz.org.sa/fatwas/1097/نذرت-صيام-شهر-رجب-من-كل-عام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_103.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":5834,"question":"حلف بالطلاق أن لا يذهب إلى محل كذا، وحلف بقوله: هي علي طالق ثلاث مرات، وهو لم يقصد بهذا الطلاق، بل قصد أن يمنع نفسه عن هذا المحل، وللأسف لقد جهل الأمر، ولم تمض مدة قصيرة حتى ذهب إلى نفس المحل، فحينئذ لم يكن ناسيًا، وإنما ذاكرًا، وإنما تجاهل الأمر فقط، فما حكم ذلك؟","title":"من حلف بالطلاق ونسيه","answer":"الجواب:  إذا طلق الإنسان على شيء يفعله، أو شيء لا يفعله؛ فهذا فيه تفصيل، إذا قال: عليه الطلاق لا يزور فلانًا، ولا يدخل بيت فلان، وعليه الطلاق ألا يأكل ذبيحة فلان، وعليه الطلاق أن تأكل ذبيحتي يا فلان، وأن تبقى حتى تأكل ذبيحتي، أو عليه الطلاق ما يكلم فلانًا، أو ما يسافر إلى كذا.  كل هذه الأمور تقع من الناس، ففيه تفصيل: إن كان أراد إيقاع الطلاق، إذا فعل هذا الشيء، أو ما فعل هذا الشيء يقع عليه الطلاق أنه يسافر، ونيته أنه إذا ما سافر تطلق امرأته؛ فهو على نيته، أو قال: عليه الطلاق أنك تأكل الذبيحة، ونيته إنه إن ما أكلها أنها تطلق؛ فهو على نيته. أما إن كان أراد التأكيد على الموضوع، ولا أراد فراقها، ولا خطر بباله فراقها، ولكن أراد التأكيد، أراد على هذا أن يأكل ضيافته، وهو ليس قصده فراق أهله، ولكن يريد منه أن يأكل الضيافة إذا سمع الطلاق؛ لعله يخضع، لعله يجلس فيأكل الضيافة، فهذا حكمه حكم كفارة يمين، حكمه حكم اليمين، وعليه كفارتها، ولا يقع الطلاق. وهكذا إذا قال: عليه الطلاق أنه ما يزور بيت فلان، أو ما يدخل بيت فلان، ثم فعل ذلك، وقصده منع نفسه من هذا الشيء، ليس قصده فراق أهله، ولكن أراد أن يمنع نفسه من هذا الشيء، وأكد عليها، فهذا يكون له حكم اليمين؛ عليه كفارة يمين، إطعام عشرة فقراء، كل فقير له نصف صاع من قوت البلد، ويكفي ذلك، أو يكسوهم كسوة قميص لكل واحد، أو يعطي لكل واحد إزارًا ورداء، هذه الكسوة مما يجزي في الصلاة. هذا جواب هذه المسائل المتعددة الكثيرة إن أراد إيقاع الطلاق؛ وقع الطلاق، وإن كان ما أراد ذلك، وإنما أراد منع نفسه، أو حثها على الشيء الذي يريده، منع نفسه أنه عليه الطلاق أنه ما يسافر، ما يكلم فلانًا، هذا قصده منع  نفسه من السفر، والكلام، أو أراد حثها عليه، عليه الطلاق أنه يصوم يوم الإثنين والخميس، عليه الطلاق أنه يذبح ذبيحة لفلان، فهذا قصده حث نفسه على الشيء، فهذا حكمه حكم اليمين أيضًا، إذا كان ما قصد إلا حث نفسه، وإلزامها بهذا  الشيء.","link":"https://binbaz.org.sa/fatwas/1180/من-حلف-بالطلاق-ونسيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_176.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":5854,"question":"أنا مدرس في المرحلة المتوسطة، وإذا دخلت الفصل؛ قام التلاميذ لي تقديرًا، واحترامًا من دون ما آمرهم به، بل إني أكره  ذلك، فما حكم ذلك؟","title":"حكم قيام الطلاب للمدرس عند دخوله","answer":"الجواب: هذا الذي نبه عليه أيضًا الشيخ محمد، وهو مسألة القيام، هذا مما جاء في السنة في النهي عنه، قال أنس : كان الصحابة إذا دخل عليهم النبي لا يقومون له لما يعلمون من كراهيته لذلك، وكان يقولﷺ: من أحب أن يتمثل له الرجال قيامًا؛ فليتبوأ مقعده من النار.  فالواجب على الطلبة إذا دخل الأستاذ ألا يقوموا، بل يلزموا أماكنهم، ويسلموا عليه، ويصبحونه بالخير، ويمسونه بالخير، طيب، أما أنهم يقومون له وقوفًا؛ فلا ينبغي ذلك، أقل أحواله الكراهة الشديدة، وهو لا يحب ذلك ما يجوز له أن يحب ذلك، والأستاذ ما دام أنه لا يحب ذلك، فهو على خير، النبي -عليه الصلاة والسلام- قال: من أحب أن يتمثل له الناس قيامًا؛ فليتبوأ مقعده من النار وفي لفظ: من سره. فالحاصل: أنه إذا كان لا يحب ذلك؛ لا حرج عليه، لكن يلزمه أن يعظهم، وأن يقول لهم: لا تفعلوا، وإذا عرفوا منه الصدق، وأنه لا يرضا بذلك؛ جلسوا، لكن أخشى أنه لا يحب ذلك دعوى، وليست حقيقة، ولو كان لا يحبه حقيقة؛ لأمرهم بالجلوس، ولقال لهم: لا تقوموا. فالحاصل: أن هذا الشيء على الأستاذ أن ينبههم، وأن يقول لهم: لا تفعلوا، لا تقوموا، ولا يرضى عنهم، لا أرضى عنكم أن تفعلوا هذا، فإذا رأوا منه الصدق ما قاموا ما هم حريصين على القيام، لكن خوفًا من شره، أو يرسبهم، أو يفعل بهم أشياء تضرهم. فالحاصل: أنه إذا صدق في ذلك، وقال لهم: لا تقوموا ما قاموا، وهذا الواجب أيضًا على وزارة المعارف؛ أنها تنبه المديرين أن هذا لا يجوز، وأن الأستاذ إذا دخل لا يقومون له، وهكذا البنات، المدرسة لا يقمن لها، وعلى  الرياسة العامة للتعليم أن تنبه على ذلك؛ حتى يزول هذا الشر الذي في المدارس. أما القيام الذي معناه المواجهة، والمقابلة للمصافحة، هذا لا بأس به، إذا دخل الأستاذ، فقام له واحد ليسأله عن شيء، ليصافحه، ليقدم في مكان، أو ليجلسه في مكانه، أو في مجلس من المجالس، قام ليصافحه، ويسأله عن حاله؛ لا بأس. مثلما قام طلحة بن عبيدالله التيمي أحد العشرة المشهود لهم بالجنة، لما دخل كعب بن مالك، لما تاب الله عليه، وجاء إلى الناس، والنبي في المسجد، وعنده الحلقة، ولما رأى كعبًا أقبل؛ قام من الحلقة، وقابله، وصافحه، وهنأه بتوبة الله عليه، ولم ينكر النبي ﷺ عليه، ولم يقل له شيئًا؛ فدل على جوازه في هذا.  ولما جاء سعد بن معاذ الأنصاري  ليحكم في بني قريظة على دابة له، على حمار، لما أقبل قال النبي ﷺ: قوموا إلى سيدكم فقاموا إليه، وسلموا عليه، وأنزلوه من دابته، وكانت فاطمة -رضي الله عنها- إذا دخل والدها النبي -عليه الصلاة والسلام- قامت إليه، وأخذت بيده، وأجلسته في مكانها، وكان إذا دخلت عليه هو قام إليها، وأخذ بيدها، عليه الصلاة والسلام. هذا إذا كان القيام للمقابلة، والمواجهة، والمصافحة، أو القيام ليمشي معه حتى يخرج من المحل، هذا لا حرج فيه، فعله النبي، وفعله الصحابة، المنكر كونهم يقومون، ثم يجلسون، ما في مصافحة، ولا شيء، إنما يقومون تعظيمًا للداخل، ثم يجلسون، هذا الذي أقل أحواله الكراهة، أو التحريم، وكونه يحب ذلك في الداخل، ويسر لهذا، ويحبه هذا، لا يجوز، وقد توعد بالنار على هذا الشيء، وهم لا ينبغي لهم أن يقوموا، يكره لهم القيام، وهو لا يجوز له أن يحب ذلك، ولا يجوز له أن يأمرهم بهذا الشيء، والواجب عليه أن ينهاهم عن هذا الشيء؛ حتى يجلسوا، وحتى يعتادوا على هذا الشيء، وهو الجلوس في أماكنهم؛ حتى يأخذ مكانه، ويبدأ بالدرس، سواء كانوا ذكورًا، أو إناثًا. السؤال: بعض المدرسين يقول: إن هذا تنبيه للطلاب؟ الجواب: لا؛ هذه شبهة شيطانية، يتنبهوا بدخوله إذا قال: السلام عليكم؛ تنبهوا، وإذا واحد نعس يقول: يا فلان صاح، انتبه للدرس، لا بأس أن ينصحهم، ويحذرهم من النعاس. السؤال: ذكر فضيلة المحاضر أن القيام قد يفضي إلى الشرك، وهناك بعض المسؤولين إذا لم يقم له الإنسان؛ فقد يغضب عليه، ويعاقبه، فماذا أعمل معه؟ الجواب: يبين له مر الكلام هذا، وأنه لا يجوز القيام، والذي لا يرضى ينبه، يقال له: إن هذا لا يجوز، لولا أن الرسول كره ذلك، وأنت والحمد لله من أتباع الرسول، أنت لا تحب الشيء الذي لا يحبه الرسول ﷺ.","link":"https://binbaz.org.sa/fatwas/1203/حكم-قيام-الطلاب-للمدرس-عند-دخوله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_199.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":5909,"question":"يدعي البعض أن إتلاف المال مكروه، وليس حرامًا، ومن إتلاف المال في الدخان يقولون أيضًا: إن التحريم يحتاج إلى نص، فما رأيكم في هذا القول؟","title":"حكم إتلاف المال في الدخان وغيره","answer":"الجواب:  إتلاف المال بغير وجه شرعي هو محرم بلا شك، وليس فيه خلاف بين العلماء في هذا؛ بل هو محل إجماع أن إتلاف المال في غير أمر مباح في غير أمر شرعي لا يجوز لوجوه كثيرة، وأدلة كثيرة؛ لأن المال جعله الله، وخلقه الله لنفع الناس، ولتقضى به الحوائج، ويجاهد به في سبيل الله، ويواسى به الفقير، والمسكين، وتقام به المشاريع الخيرية، والمصالح العامة، فلا يجوز أن يضاع.  ومن ذلك قوله -جل وعلا-: وَلَا تُبَذِّرْ تَبْذِيرًا [الإسراء:26] قال العلماء: التبذير إضاعة المال، يعني صرفه في غير وجهه، كصرفه في المسكرات، وصرفه في الدخان، وصرفه في المعاصي، وطرحه في البحر، وما أشبه ذلك، هذا من التبذير.  وكذلك الإسراف، الله نهى عن الإسراف، وقال: وَلَا تُسْرِفُوا [الأنعام:141] فالإسراف: الزيادة على الحاجة، فإن كانت الزيادة عن الحاجة تمنع، فكيف بإضاعة المال أصلًا، ورأسًا! كذلك ما صح في الصحيحين عن النبي ﷺ من حديث المغيرة بن شعبة عن النبي ﷺ قال: إن الله يكره لكم، أو الله يسخط لكم: قيل وقال، وإضاعة المال، وكثرة السؤال أخبر أن الله يسخط لنا: قيل وقال، وكثرة السؤال، وإضاعة المال. والله يسخط هذا، وما سخطه الله؛ وجب علينا تركه في أدلة كثيرة غير هذا؛ لأن صرفه في الدخان، والمسكرات لا ريب أنه من التبذير، والحرام، ولا شك في ذلك، مع ما هو متقرر، ومعلوم من كون الدخان من الخبائث الضارة، والله سبحانه إنما أباح لنا الطيبات، حيث قال : يَسْأَلُونَكَ مَاذَا أُحِلَّ لَهُمْ قال الله لنبيه: قُلْ أُحِلَّ لَكُمُ الطَّيِّبَاتُ [المائدة:4] ولا يقول عاقل، لا طبيب، ولا غير طبيب: إن الدخان من الطيبات، فعلم حينئذ بنص القرآن أنه ليس من المباحات.  وقال سبحانه في وصف النبي محمد ﷺ: وَيُحِلُّ لَهُمُ الطَّيِّبَاتِ وَيُحَرِّمُ عَلَيْهِمُ الْخَبَائِثَ [الأعراف:157] فكل شيء ليس بطيب؛ فهو من قسم الخبائث، والله بعث نبيه ﷺ يحل الطيبات المآكل، والمشارب، والمراكب، والملابس، وغير ذلك، ويحرم الخبائث التي تضر العبد ضررًا عظيمًا، إما غالبًا، وإما محضًا، والدخان أضراره محضه، خبيثة، لا خير فيها، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/1234/حكم-اتلاف-المال-في-الدخان-وغيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_231.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":5936,"question":"لدي زوجة تؤدي الفروض الدينية كاملة، ولكنها تعاتب في بعض الأعمال حتى يحصل الزعل، ولا تقوم ببعض الأعمال إلا بزعل، وذلك أنها متعودة على الكسل، فهل يجوز لي طلاقها؟","title":"حكم تطليق الزوجة بسبب كسلها","answer":"الجواب: ينبغي لك الصبر، إن كانت طيبة، ودينة، وإن كان فيها بعض الكسل ينبغي لك الصبر، أنت عندك بعض الكسل، ما أحد سالم، ينبغي لك أن تكون طيبًا، وأن تعاونها على أمور البيت، عاونها، النبي كان يعاون أهله -عليه الصلاة والسلام- وهو أفضل الخلق، كان يساعد أهله في البيت على حاجات البيت. فأنت ساعدها، لا تجيب خادم، ساعدها حتى تسلم من الخادم، ساعدها على أمور البيت التي تعجز عنها، قد يكون معها أطفال قد أتعبنها، ساعدها على أمور البيت، شجعها على العمل بكلام طيب، ما هو يا خبيثة، يا فاجرة، يا كذا، يا كذا، يا بنت فلان، يا أم فلان، قومي كذا، عافاك الله، الله يرضى عليك، كذا كلام طيب.","link":"https://binbaz.org.sa/fatwas/1287/حكم-تطليق-الزوجة-بسبب-كسلها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_274.mp3","categories":["الطلاق","الأيمان والنذور","الآداب والأخلاق المحمودة"]},{"id":5967,"question":"كنت في مجلس مع زملائي، وحلفت بالله لئن جاء أخي أن أذبح شاة، وجاء أخي، وأنا في ذلك الوقت معسر، ولا أملك قيمة الشاة، فماذا أفعل؟","title":"حكم من عجز عن الوفاء بالنذر","answer":"الجواب: إذا تيسر تذبح الشاة، إذا تيسرت الشاة تذبحها؛ وفاء لنذرك، تذبحها على نية للفقراء، تعطيها للفقراء، على نية تأكلونها أنت، وأهل بيتك، تأكلها أنت، وأهل بيتك، إذا كان ما عندك نية؛ تعطيها الفقراء، لا تأكلها.","link":"https://binbaz.org.sa/fatwas/1338/حكم-من-عجز-عن-الوفاء-بالنذر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_305.mp3","categories":["الطلاق","الأيمان والنذور","الآداب والأخلاق المحمودة"]},{"id":5969,"question":"أنا موظف حكومي،  وأستلم راتب الليل، ولا أحضر؛ لأنني لا أخرج في النهار إلا الساعة الثانية والنصف بعد انتهاء جميع المعاملات، فهل ما آخذه من الليل حلال، أم حرام؟","title":"حكم استلام الراتب بدون عمل","answer":"الجواب: هذا الذي يظهر أنه ليس بحلال، ينبغي أن تأخذ إذا كنت تعمل إذا كان ما هناك عمل تخبرهم أني ما أعمل، ولا أريد هذا الشيء.","link":"https://binbaz.org.sa/fatwas/1358/حكم-استلام-الراتب-بدون-عمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_316.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":6057,"question":"في حالة الكفارة باليمين، أو إطعام عشرة مساكين، أو عتق رقبة كيف أطعم عشرة مساكين، هل بواقع النفر خمسة، أو أقل، أو أكثر؟ وكيف أعتق رقبة من أي نوع أفيدونا؟","title":"صفة كفارة اليمين","answer":"الجواب: إذا كان عليه كفارة يمين، أو كفارة ظهار، فكفارة اليمين يخير بين ثلاثة: إما إطعام عشرة مساكين، لكل مسكين نصف صاع من قوت البلد: تمرًا، أو أرزًا، أو نحو ذلك، عشرة، كل واحد نصف صاع، كيلو ونصف للواحد من العشرة، أو يكسوهم كسوة تجزئهم في الصلاة مثل: إزار ورداء، وإلا قميص، أو يعتق رقبة مؤمنة إذا تيسرت، هذا في اليمين، فإن عجز عن هذه الأمور الثلاث يصوم ثلاثة أيام، يجب أن تكون متتابعة فقط.  أما في الظهار إذا ظاهر من امرأته، وحرمها عليه: عتق رقبة مؤمنة إذا تيسر، فإن عجز؛ يصوم شهرين متتابعين قبل أن يمسها، فإن عجز؛ أطعم ستين مسكينًا، كل مسكين له نصف صاع من التمر، أو غيره من قوت البلد، مقدار كيلو ونصف تقريبًا قبل أن يمسها، هذه كفارة الظهار.","link":"https://binbaz.org.sa/fatwas/1468/صفة-كفارة-اليمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_398.mp3","categories":["الأيمان والنذور","قضايا المرأة","الأخلاق المذمومة"]},{"id":6092,"question":"ما هي مقدار كفارة اليمين؟ وما هو مذهب أهل نجد؟","title":"كفارة اليمين ونبذة عن مذهب أهل نجد","answer":"الجواب: كفارة اليمين معروفة ،وليس لأهل نجد مذهب يخالف الناس، ولكن الذي هم عليه في الغالب مذهب الحنابلة، هذا معروف، المذهب المعروف مذهب الحنابلة، إمامهم أحمد بن حنبل، رحمه الله.  ولكن علماء أهل نجد إذا عرفوا أن القول في مذهب أحمد صار مرجوحًا؛ أخذوا بالدليل، وقدموا ما يقبل الدليل، تقديمه في مسائل الخلاف. ومسائل كفارة اليمين ما فيها خلاف، بينها الله في كتابه العظيم، وأنها إطعام عشرة مساكين، أو كسوتهم، أو تحرير رقبة، هذه كفارة اليمين عند أهل العلم بالنص؛ فإن عجز عن هذه الثلاث؛ صام ثلاثة أيام، هذه كفارة اليمين، أولًا، يطعم عشرة مساكين، أو يكسوهم، أو يحرر رقبة، هذه مخير، إن أعتق؛ أجزأ، وإن كسا؛ أجزأ، وإن أطعم؛ أجزأ، مخير بين هذه الثلاث، أعظمها العتق، وهو أعلاها، فإن لم يعتق، وكساهم على كسوة كسوة، على قميص قميص، وعلى إزار ورداء عشرة؛ كفى، وإن أطعمهم، عشاهم، أو غداهم، أو أعطاهم نصف صاع تمر، أو رز من قوت البلد، وهو يقارب كيلو ونصف؛ أجزأ ذلك، فإن عجز كأن كان فقيرًا، ما عنده شيء؛ يصوم ثلاثة أيام متتابعة.","link":"https://binbaz.org.sa/fatwas/1505/كفارة-اليمين-ونبذة-عن-مذهب-اهل-نجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_435.mp3","categories":["الأيمان والنذور","قضايا المرأة","الأخلاق المذمومة"]},{"id":6147,"question":"رجل أضاف علي رجل آخر، وحلف بالطلاق ألا يأكل الذبيحة، وذهب، وجاء بذبيحة أخرى، وأكل منها، ماذا يلزم عليّ؟","title":"حكم الحلف بالطلاق على أمر دون قصد الطلاق","answer":"الجواب: إذا كان قصد الضيف أنه ما يكلف المستضيف الضيف النازل، طلق أنه ما يأكل ذبيحتك يا فلان، إن نزل عليك يبيه ما يتكلف، ولا يشتري ذبيحة، ويأكل من الطعام الحاضر، ثم أبى عليه المضيف، وجاء بذبيحة، وذبحها، وأكل منها، أو ما أكل منها؛ فإنه عليه الحكم في طلاقه إن كان أراد طلاق زوجته إن أكل الذبيحة، مضى عليه طلقة حسب ما قال. وإن كان إنما أراد منعه من الذبيحة، ولم يرد طلاق امرأته، ولكن أراد إذا سمع الطلاق أنه يمنعه ذلك؛ فعليه كفارة يمين، قال: عليه الطلاق ما يأكل الذبيحة، ما تذبح له، عليه الطلاق ما تذبح له، وذبح، أو عليه الطلاق ما يأكل، وأكل؛ فهذا عليه كفارة يمين، حكمه حكم اليمين، إذا كان المقصود من هذا الكلام منع النزول به من التكلف، وليس قصده فراق زوجته، وإنما قصده منع التكلف إذا سمع الطلاق يمتنع لا يأتي الذبيحة، ولا يتكلف، ثم صاحب الضيافة المنزول عليه تكلف، ولم يبال بيمينه، ولا بطلاقه، ثم أكل من ذبيحته إن كان طلاق أن لا يأكل، أو طلق أن لا يذبح، وذبح له؛ فإن الطلاق هذا يكون عن كفارة يمين إن كان ما قصد إيقاعه على الزوجة، ما قصد فراقها، وإنما قصد منعه من التكلف. هذا حكمه حكم اليمين، ما تحسب إذا كان قصده المنع، منع الرجل من التكلف عليه كفارة يمين، ولا يقع، إطعام عشرة مساكين، أو كسوتهم ..","link":"https://binbaz.org.sa/fatwas/1611/حكم-الحلف-بالطلاق-على-امر-دون-قصد-الطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_505.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":6184,"question":"هل لي أن أتجسس على إنسان في بيته؛ لمعرفة إن كان عنده شيء من المحرمات، أو الخمور، أو يستعملها؟","title":"حكم التجسس على شخص لمعرفة إذا كان يعصي","answer":"الجواب: ليس لك التجسس؛ لأن الله يقول: يَا أَيُّهَا الَّذِينَ آمَنُوا اجْتَنِبُوا كَثِيرًا مِنَ الظَّنِّ إِنَّ بَعْضَ الظَّنِّ إِثْمٌ وَلَا تَجَسَّسُوا وَلَا يَغْتَبْ بَعْضُكُمْ بَعْضًا [الحجرات:12] والنبي -عليه الصلاة والسلام- قال: لا تجسسوا. فلا يجوز التجسس، وهو التنقيب عن الشخص لعله يجده على معصية، لا بل إذا ستر الله مسلمًا فلا تحرص على كشفه، لكن متى ظهر الأمر، وبان بدون تجسس؛ وجب عليك النصيحة، والتوجيه إلى الخير، وإنكار المنكر، أما التجسس فلا يجوز.","link":"https://binbaz.org.sa/fatwas/1638/حكم-التجسس-على-شخص-لمعرفة-اذا-كان-يعصي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_529.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":6191,"question":"كانت عندي وليمة، وكان هناك شخص لم يرض أن يقوم معنا، فحلفت عليه، وقلت له: قم، وهكذا عليّ الحرام أنك تقوم، فأرجو من فضيلتكم أن تنصحونا بذلك؟","title":"حكم مقولة: عليَّ الحرام فِعْل كذا وكذا","answer":"الجواب: ما يجوز للإنسان أن يحرِّم ما أحل الله، فيقول: عليَّ الحرام أن تفعل كذا، أو عليّ الحرام أن لا تفعل كذا، أو عليّ الحرام من طعامك، أو شرابك، أو دارك، أو لباسك لا، الله -جل وعلا- أنكر على نبيه ﷺ وقال: يَا أَيُّهَا النَّبِيُّ لِمَ تُحَرِّمُ مَا أَحَلَّ اللَّهُ لَكَ تَبْتَغِي مَرْضَاتَ أَزْوَاجِكَ وَاللَّهُ غَفُورٌ رَحِيمٌ [التحريم:1] فليس للناس أن يحرموا ما أحل الله.  وإذا فعل الإنسان هذا؛ فعليه التوبة، وعليه كفارة اليمين، فإن الله قال: قَدْ فَرَضَ اللَّهُ لَكُمْ تَحِلَّةَ أَيْمَانِكُمْ [التحريم:2] فإذا قال: عليه الحرام، ما يأكل كذا، عليه الحرام ما يزور فلانًا، عليه الحرام ما يأكل ذبيحته، عليه الحرام ما يدخل بيتك، فهذا من باب تحريم ما أحل الله، وحكمه حكم اليمين؛ فعليه كفارة يمين إذا فعل ما حرم أن يفعل.","link":"https://binbaz.org.sa/fatwas/1658/حكم-مقولة-علي-الحرام-فعل-كذا-وكذا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_539.mp3","categories":["الأيمان والنذور","قضايا المرأة","الأخلاق المذمومة"]},{"id":6196,"question":"وكذلك سؤال آخر: غضب رجل من زوجته، فأقسم عليها يمينًا بالحرام منها أن لا يطأها مدة سنة كاملة، فما تحليل هذا الحلف؟ وما كفارته؟","title":"حكم من أقسم بالحرام أن لا يطأ زوجته سنة كاملة","answer":"الجواب: إذا حلف أن لا يطأها؛ فعليه كفارة يمين، إذا قال: عليه الحرام أنه لا يطأها شهرًا، أو سنة، أو يومًا، أو سنتين، أو أكثر؛ فهذا حكمه حكم اليمين. أما إذا قال: هي حرام علي، وجعلها كظهر أمه، أو كظهر أخته؛ فهذا حكمه حكم الظهار، تحرم عليه حتى يعتق رقبة، فإن لم يجد؛ صام شهرين متتابعين، فإن عجز؛ أطعم ستين مسكينًا. أما إذا قال: عليه الحرام ما يطأها، أو عليه حرام ما يكلمها، أو عليه حرام ما ينام معها، فهذا حكمه حكم اليمين.","link":"https://binbaz.org.sa/fatwas/1660/حكم-من-اقسم-بالحرام-ان-لا-يطا-زوجته-سنة-كاملة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_540.mp3","categories":["الأيمان والنذور","الظهار"]},{"id":6240,"question":"ما رد سماحتكم على من يقول: أن تقبيل الأجنبية ونوال منها كل شيء عدا الزنا ذنب يغسله الاستغفار؟","title":"الرد على من زعم أن تقبيل المرأة الأجنبية يمحوه الاستغفار","answer":"الجواب: هذا منكر، والإصرار عليه يكون كبيرة، ومن الكبائر لا يزيله الاستغفار، ولا يزيله إلا التوبة فإذا قبلها بغير حق قبلها وهي غير محرم له أو مسها أو ما أشبه ذلك فهذا لا يمحوه إلا التوبة، والذنب الإصرار عليه كبيرة، نسأل الله العافية.\nإذا تاب إلى الله جل وعلا ولم يصر وندم على ذلك أو حافظ على الصلوات الخمس والجمعة إلى الجمعة ورمضان إلى رمضان، وتجنب الكبائر غفر الله له الصغائر التي لم يصر عليها، أما إذا أصر عليها صارت كبيرة، نعوذ بالله لا بدّ فيها من التوبة.","link":"https://binbaz.org.sa/fatwas/1744/الرد-على-من-زعم-ان-تقبيل-المراة-الاجنبية-يمحوه-الاستغفار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_583.mp3","categories":["الأيمان والنذور","قضايا المرأة","الأخلاق المذمومة"]},{"id":6270,"question":"وآخر يقول: أغضبتني أختي غضبًا شديدًا، فحلفت بالطلاق ثلاثًا أن لا أكلمها، وأن لا أسلم عليها ما دامت على قيد الحياة، ولا تدخل بيتي، وأنا الآن نادم، وأريد أن أزورها، وقد غيرت محل السكن من الطائف إلى بلاد بني مالك، فما حكمه؟","title":"حكم من حلف بالطلاق ثلاثاً أن لا يكلم أخته","answer":"الجواب: إذا طلق الإنسان أن لا يزور فلانًا، أو أن لا يكلم فلانًا؛ فالحكم ما يتعلق بالبيت، بل يتعلق بالشخص أينما كان، البيت إذا تغير ما يتغير الحكم إلا إذا قال في هذا البيت المعين، لا أزورها في هذا البيت المعين، قصده البيت المعين، أو لا يكلمها ما دامت في البيت المعين، إذا قصد البيت المعين، فإذا انتقل عنه؛ زال الحكم، لكن ما دام مقصود هجره، ما دام مقصود الزعل عليه هو؛ فالحكم يدور معه، هو سواء كان في نجد، أو في الحجاز، أو في أي مكان.  ولكن إذا كان القصد منها الطلاق، وأن لا يكلمها، وأن لا، وأن لا، إذا كان المقصود منع نفسه من زيارتها، وكلامها، وليس المقصود فراق زوجته إن كلمها، فهذا حكمه حكم اليمين، وعليه كفارة يمين، وهي إطعام عشرة مساكين، أو كسوتهم، وإذا عشاهم، أو غداهم؛ كفى، أو أعطى كل واحد نصف الصاع من التمر، أو الرز، أو نحو ذلك، وهو كيلو ونصف؛ كفى، هذا إن كان قصده منعها من الكلام، والزيارة. أما إن كان يقصد من ذلك أنه متى كلمها يقع الطلاق، متى كلمها يفارق زوجته، يقع في الثلاث طلقة واحدة، إذا قال: أنت طالق بالثلاث، إن زارها، أو كلمها؛ يقع فيها واحدة، إذا أراد الطلاق أن يقع، يقع طلقة واحدة، ويراجعها إذا كان ما لها طلاقان، إذا كان ما طلقها طلقتين؛ يكون بهذا طلقة إذا كلم أخته، إذا كان المقصود فراق زوجته إن كلمها.  أما إن كان المقصود ليس ذلك، المقصود منع نفسه من زيارتها، وكلامها، وليس المقصود فراق زوجته؛ فهذا فيه كفارة اليمين، ويكفي، وعليه التوبة إلى الله من هذا. السؤال: والفلوس لا تكفي في الكفارة؟ الجواب: لا، إما طعام، وإما كسوة.","link":"https://binbaz.org.sa/fatwas/1766/حكم-من-حلف-بالطلاق-ثلاثا-ان-لا-يكلم-اخته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_605.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":6287,"question":"ما حكم الحلف بهذا اللفظ، أي: بحق الله، هل هذا الحلف يعتبر شركًا بالله، ولو لم يقصده؟","title":"حكم الحلف بحق الله","answer":"الجواب: لا، لا يحلف بحق الله، يحلف بالله، والله، بعزة الله، والرحمن الرحيم، والقادر على كل شيء، ورب العالمين، والذي نفسي بيده.  ولا يحلف بحق الله؛ لأن حق الله علينا تعظيمه، وطاعته، وتعظيمه وطاعته من أفعالنا، من أفعال المخلوقين، حقه علينا توحيده، وطاعته، وتعظيمه، وتوحيدنا له، وتعظيمنا له، وطاعته من أفعالنا، وأفعالنا مخلوقة، ومعناه الحلف بمخلوقاته؛ فلا يصح؛ الحلف لا يكون إلا بالله وحده، أو بأسمائه وصفاته، جل وعلا.","link":"https://binbaz.org.sa/fatwas/1812/حكم-الحلف-بحق-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_653.mp3","categories":["الأيمان والنذور","الحلف بغير الله"]},{"id":6293,"question":"وأحد الإخوة يسأل سؤالًا خاصًا فيقول: في واحد لما يشرب الدخان، تركه مدة، وعزم أنه لا يشربه، وحلف يمين على أنه إذا شربه؛ صام ثلاث سنين، ورجع إليه مرة ثانية، وشربه، فما حكم صيام الثلاث سنين الذي ألزم نفسه بها؟","title":"حكم من حلف أن يصوم ثلاث سنين إن عاد للدخان","answer":"الجواب:  عليه أن يتوب إلى الله، وعليه كفارة اليمين، لأن الرسول نهى عن صيام الأبد، وهذا صيام مستمر، بل يطعم عشرة مساكين، أو يكسوهم، ويكفي عن يمينه، وعليه التوبة إلى الله، وعدم الرجوع إلى الدخان؛ لأن مضاره كثيرة، وهو خبيث محرم؛ فعليه التوبة إلى الله، وعدم الرجوع إليه، مع كفارة يمين على حلفه أنه لا يشربه، وإن شربه؛ فعليه كفارة يمين.","link":"https://binbaz.org.sa/fatwas/1790/حكم-من-حلف-ان-يصوم-ثلاث-سنين-ان-عاد-للدخان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_629.mp3","categories":["الأيمان والنذور","قضايا المرأة","الأخلاق المذمومة"]},{"id":6376,"question":"إذا كان النذر للتقرب في طاعة؟","title":"حكم نذر الطاعة","answer":"الجواب: إذا نذر لطاعة يلزمه الوفاء، مثل ما قال النبي ﷺ: من نذر أن يطيع الله؛ فليطعه رواه البخاري في الصحيح، فإذا قال نذر لله علي أن أتصدق بمائة ريال على فلان، أو ألف ريال على فلان، وهو يستطيع؛ يلزمه، أو قال: لله عليه أن يصوم يوم الخميس، أو يصوم يوم الإثنين، أو يصلي ركعتين من الضحى؛ يلزمه. السؤال: طيب كبر في السن ولا يقدر أن يصوم السنتين؟ الجواب:  إذا عجز يصوم .... السنتين مكروهة ، النبي قال: لا صام من صام الأبد، ولما أراد عبدالله بن عمرو أن يصوم السنة؛ نهاه، قال: صوم يومًا، وأفطر يومًا وقال: أطيق أفضل من ذلك، قال: لا أفضل من ذلك ونهاه عن صوم السنة، فصوم السنة مكروهة، لا ينبغي، ولو نذره يكفر كفارة يمين، ويكفي.","link":"https://binbaz.org.sa/fatwas/1950/حكم-نذر-الطاعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_737.mp3","categories":["الأيمان والنذور","قضايا المرأة","الأخلاق المذمومة"]},{"id":6381,"question":"أحد الإخوة يقول: نذرت أنني إذا فعلت العادة السرية، أي: الاستمناء باليد أن أصوم سنتين متتابعتين، وذلك لكي أمنع نفسي من هذه العادة، ولكني فعلتها، ولا أستطيع الصيام، فما هو الحل؟","title":"كفارة النذر المكروه","answer":"الجواب: هذا النذر مكروه لا ينبغي، ولأنه نذر ليس للتقرب، إنما هو لمنع نفسه من هذه العادة، مثل الذي يقول: إن كلمت فلانًا؛ صمت سنين، أو إن زرته؛ سأصوم سنتين، هذا معناه حث نفسه على ترك هذا الشيء، ومنع نفسه من هذا الشيء، فهذا حكمه حكم اليمين، وليس عليه صيام، يطعم عشرة مساكين، أو يكسوهم، ويكفي، وليس عليه هذا الصيام؛ لأن هذا ليس مقصوده التقرب، مقصوده أن يمنع نفسه من هذا الشيء. والعادة السرية يجب عليه الحذر منها مطلقًا، ولو ما نذر، هذا النذر يجب عليه أن يحذرها، ويجب أن لا يمد بصره إلى النساء، يغض بصره عن النساء، وعن المردان، وعنده الحذر أن يخاف من الله، والمراقبة، ويكثر من الصوم، وأن يتصل بأهله إذا كان له زوجة، أو يتزوج، وبهذا يزول الشر إن كان مع العلاج، كل داء له دواء، ما أنزل الله داء إلا أنزل له دواء.","link":"https://binbaz.org.sa/fatwas/1948/كفارة-النذر-المكروه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_735.mp3","categories":["الأيمان والنذور","قضايا المرأة","الأخلاق المذمومة"]},{"id":6386,"question":"إذا كان النذر للتقرب في طاعة؟","title":"حكم نذر الطاعة","answer":"الجواب: إذا نذر لطاعة يلزمه الوفاء، مثل ما قال النبي ﷺ: من نذر أن يطيع الله؛ فليطعه رواه البخاري في الصحيح، فإذا قال نذر لله علي أن أتصدق بمائة ريال على فلان، أو ألف ريال على فلان، وهو يستطيع؛ يلزمه، أو قال: لله عليه أن يصوم يوم الخميس، أو يصوم يوم الإثنين، أو يصلي ركعتين من الضحى؛ يلزمه. السؤال: طيب كبر في السن ولا يقدر أن يصوم السنتين؟ الجواب:  إذا عجز يصوم .... السنتين مكروهة ، النبي قال: لا صام من صام الأبد، ولما أراد عبدالله بن عمرو أن يصوم السنة؛ نهاه، قال: صوم يومًا، وأفطر يومًا وقال: أطيق أفضل من ذلك، قال: لا أفضل من ذلك ونهاه عن صوم السنة، فصوم السنة مكروهة، لا ينبغي، ولو نذره يكفر كفارة يمين، ويكفي.","link":"https://binbaz.org.sa/fatwas/1950/حكم-نذر-الطاعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_737.mp3","categories":["الأيمان والنذور","قضايا المرأة","الأخلاق المذمومة"]},{"id":6388,"question":"يتردد كثيرًا على ألسنة بعض الدعاة، والشعراء، وغيرهم قولهم: لعمري، وقولهم لعمرك كذا وكذا، فهل يعد ذلك قسمًا، وحلفًا بالعمر، أم لا؟ وما معناه؟","title":"حكم قول أحدهم لعمري","answer":"الجواب: الصواب أنه لا حرج فيه، وقد وقع في بعض الأحاديث الصحيحة عن النبي ﷺ أنه قال: لعمري وقد صح عن ابن عباس وعن جماعة من السلف، والخلف، فليس بيمين بغير الله، ليس من الحلف بغير الله، أو أن هذا مما يتسامح فيه، ويقصد به التأكيد لعمرك كذا، وكذا لعمري كذا وكذا، يؤتى لتأكيد الكلام، وتقويته، وليس من مقام القصد بالحلف.","link":"https://binbaz.org.sa/fatwas/1972/حكم-قول-احدهم-لعمري","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_759.mp3","categories":["الأيمان والنذور","قضايا المرأة","الأخلاق المذمومة"]},{"id":6399,"question":"أنا قلت لزوجتي في حال غضب مني عليها: والله إذا ذهبت إلى أهلك لمدة ستة أشهر؛ فأنت طالق بالثلاثة، هل يجب الطلاق، أم يجب عليّ كفارة اليمين؟","title":"حكم طلاق الثلاث بلفظ واحد","answer":"الجواب: ينبغي للعاقل أن لا يعجل في الطلاق، ينبغي للعاقل أن يعالج الأمور بغير الطلاق، يعالج الأمور بالوعد، والوعيد، والتهديد، والتحذير بغير الطلاق،، يعدها بكذا من الكرامات، إذا استقامت؛ يتوعدها بشيء من الإهانة، وعدم إعطائها بعض المطالب، ويدع الطلاق بعيدًا، لكن هذا الذي يتوعدها بالطلاق له حالان: إحداهما: أن يقصد تنفيذ ما أراد، وأنه متى أخلت بما قالت؛ فإن الطلاق يقع بها، فهذا له ما نوى، ويقع عليها الطلاق، فإذا قال: إن مكثت عند أهلك ستة أشهر، أو يومًا، أو يومين، أو كذا، أو كذا؛ فأنت طالق، وهو يقصد طلاقها؛ وقع الطلاق، أو قال: إن كلمت فلانًا؛ فأنت طالق، وهو يقصد الطلاق؛ وقع الطلاق، أو قال: إذا خرجت إلى بيت فلا؛ن فأنت طالق، أو علي الطلاق إذا خرجت من بيتي -وهو يقصد ذلك- وقع الطلاق، يقول المصطفى -عليه الصلاة والسلام-: إنما الأعمال بالنيات، وإنما لكل امرئ ما نوى. أما الذي يقصد تهديدها، وتحذيرها، ولا يقصد فراقها، لكن يقصد تخويفها، وتحذيرها، كأن يقول: إن كلمت فلانًا؛ فأنت طالق، أو إن زرت فلانة؛ فأنت طالق، أو ذهبت إلى أهلك بغير إذني؛ فأنت طالق، يقصد تخويفها، وتحذيرها، ولم يقصد فراقها، والله يعلم ما في قلبه، وإنما أراد التحذير، فهذا حكمه حكم اليمين، وعليه كفارة ظهار إذا أخلت بالمطلوب، إذا خالفته عليه كفارة يمين، مثل قوله: والله لا تذهبين، والله ما تفعلي كذا، وكذا حكمه حكم اليمين في أصح قولي العلماء، كما أفتى بهذا جمع من أهل العلم، من السلف في عهد الصحابة، وفي عهد التابعين وأفتى بهذا أيضًا أبو العباس ابن تيمية شيخ الإسلام -رحمة الله عليه- والعلامة ابن القيم، وجمع من أهل العلم من القدماء، وغيرهم؛ لأن هذا يقع من الناس كثيرًا بالتخويف، والتحذير لا لأجل إيقاع الطلاق. أما إذا علق الطلاق على شيء ما فيه تخويف، من طبيعته أنه ليس فيه تخويف، يعني إذا دخل رمضان فأنت طالق، إذا ولدت فأنتِ طالق، إذا حملت فأنت طالق، يقع الطلاق بهذا، وما أشبه ذلك. السؤال: إذا قال لزوجته: أنتِ طالق بالثلاث الجواب: إذا قال: أنت طالق بالثلاث؛ تكون واحدة على الصحيح، إذا قال: أنت طالق بالثلاث، بهذا اللفظ، أما إذا قال: أنت طالق، ثم طالق، ثم طالق، تقع الثلاث، نسأل الله السلامة.","link":"https://binbaz.org.sa/fatwas/1970/حكم-طلاق-الثلاث-بلفظ-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_757.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":6531,"question":"تزوجت، ونذرت لله إذا جاءني بولد أن أصوم من كل شهر ثلاثة أيام، قد حصل لي الآن مرض في بطني، ومنعني الطبيب عن الصوم؛ فتركت صوم الثلاثة أيام، وإنما أصوم رمضان، فما حكم ترك صيام الثلاثة أيام؟","title":"من لم يستطع الوفاء بنذره بسبب المرض","answer":"الجواب: يقول النبي ﷺ: من نذر أن يطيع الله؛ فليطعه، ومن نذر أن يعصي الله؛ فلا يعصه فالذي نذر أن الله إن رزقه ولدًا أن يصوم ثلاثة أيام من كل شهر، أو إن الله عافاه من مرضه؛ يصوم ثلاثة أيام من كل شهر، أو إن الله رزقه الوظيفة الفلانية يصوم ثلاثة من كل شهر؛  يصوم إذا حصل مقصوده، إذا حصل الشرط؛ يلزمه الصيام، وإذا مرض يقضي، إذا مرض، وعافاه الله يقضي الأيام مثل رمضان، إذا مرض يصوم بعد ذلك، فإذا مرض الإنسان في أي الشهور يصوم بعد ذلك الثلاثة الأيام التي بعد شفائه، وليس له عذر في ترك ذلك، إلا إذا أصابه مرض لا حيلة فيه، لا يرجى برؤه؛ فحينئذ معذور مثل رمضان، يكفر، يطعم عن كل يوم مسكينًا. س: عن كل يوم في كل شهر؟  الجواب: كل شهر. الطالب: كلما يمر عليه شهر؟ الجواب: صاع ونصف عن كل شهر.\n\nالطالب: يتكرر باستمرار الشهور؟ الجواب: نعم مثل رمضان.","link":"https://binbaz.org.sa/fatwas/2386/من-لم-يستطع-الوفاء-بنذره-بسبب-المرض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_919.mp3","categories":["الأيمان والنذور","قضايا المرأة","الأخلاق المذمومة"]},{"id":6542,"question":"إنسان طلق على أنه لا يقعد عند هذا الشخص، وفي يوم من الأيام ذهب إليه، فما حكم ذلك اليمين؟","title":"حكم من علق طلاقه على شرط","answer":"الجواب: إذا طلق الإنسان لا يقعد عند فلان، أو لا يكلم فلانًا؛ فله حالان: إحداهما: أن يقصد منع نفسه، ولا يقصد إيقاع الطلاق، إنما قصد منع نفسه من هذا الشيء، وشدد على نفسه بالطلاق، ولم يرد إيقاع الطلاق على أهله، وإنما أراد منع نفسه من قعوده عنده، أو الكلام، فهذا حكمه حكم اليمين على الصحيح، وعليه كفارة اليمين ولا يقع الطلاق. أما إذا أراد وقوع الطلاق، وأنه نوى إذا قعد عنده فزوجته طالق، أو كلمه فزوجته طالق؛ فإنه متى كلمه، أو قعد عنده يقع طلقة على زوجته؛ لأنه طلاق معلق على الشرط، مثل لو قال: إذا دخل رمضان فزوجته طالق؛ تطلق، أو قال: إذا نزل المطر فزوجته طالق، أو قال: إذا حاضت فهي طالق، وما أشبه ذلك.","link":"https://binbaz.org.sa/fatwas/2372/حكم-من-علق-طلاقه-على-شرط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_906.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":6555,"question":"امرأة نذرت لله صوم شهر تصومه بدون سحور إن طلقها زوجها، هل توفي بالنذر بدون سحور، أم لا؟","title":"حكم من نذر صياماً بغير سحور","answer":"الجواب: إذا طلقها زوجها؛ تصوم، ولكن تتسحر، لا تترك السحور، السحور سنة، وقربة، والرسول ﷺ يقول: تسحروا فإن في السحور بركة فعليها أن تصوم، وعليها أن تتسحر، عليها السحور، النبي ﷺ قال: من نذر أن يطيع الله؛ فليطعه فالصوم طاعة، وترك السحور ما هو بطاعة، تتسحر ...","link":"https://binbaz.org.sa/fatwas/2413/حكم-من-نذر-صياما-بغير-سحور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_940.mp3","categories":["الأيمان والنذور","قضايا المرأة","الأخلاق المذمومة"]},{"id":6587,"question":"امرأة نذرت لله صوم شهر تصومه بدون سحور إن طلقها زوجها، هل توفي بالنذر بدون سحور، أم لا؟","title":"حكم من نذر صياماً بغير سحور","answer":"الجواب: إذا طلقها زوجها؛ تصوم، ولكن تتسحر، لا تترك السحور، السحور سنة، وقربة، والرسول ﷺ يقول: تسحروا فإن في السحور بركة فعليها أن تصوم، وعليها أن تتسحر، عليها السحور، النبي ﷺ قال: من نذر أن يطيع الله؛ فليطعه فالصوم طاعة، وترك السحور ما هو بطاعة، تتسحر ...","link":"https://binbaz.org.sa/fatwas/2413/حكم-من-نذر-صياما-بغير-سحور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_940.mp3","categories":["الأيمان والنذور","قضايا المرأة","الأخلاق المذمومة"]},{"id":6880,"question":"ما معنى أن الله واحد في صفاته، وأسمائه، مع أن هناك من يشترك معه في التسمية من العباد؟","title":"معنى أن الله واحد في أسمائه وصفاته","answer":"الجواب:\nمعنى ذلك أنه واحد في معنى الصفات، الحكيم العليم الرحمن الرحيم، والقدير، وإن سمي بعض الأطباء حكيمًا، وإن سمي بعض الناس حكيمًا، وإن سمي بعض الناس عزيزًا، إلى غير ذلك، لكن العزة المطلقة لله وحده، والحكمة المطلقة لله وحده، والقدرة المطلقة لله وحده. فالمعنى: من اعتقد أن غير الله يشاركه في هذا المعنى، وأن له مثل صفة الله في العزة، أو في الحكمة، أو في الرحمة، أو في القدرة، أو في العلم؛ كفر بالله، أما كونه يشارك في بعض الشيء، له قدرة تليق بالمخلوق، فهذا لا يقع فيه الشرك، الله سمى نفسه سميعًا بصيرًا، وسمى عبده سميعًا بصيرًا.  فالمقصود: أن جنس المشاركة في جنس القدرة، جنس العلم، جنس السمع، جنس البصر، لكن قدرة محدودة، وعلم محدود، وبصر محدود، فالإنسان له بصر محدود، وسمع محدود، وعلم محدود، وقدرة محدودة، هذه ليس فيها شركة لله  هذه الله الذي أعطاه إياها، ومنّ بها عليه  لكن إذا قال: له قدرة من جنس قدرة الله، وأنه يتصرف في الكون كما يشاء، أو أنه يعلم المغيبات، أو ما أشبه كالله هذا هو المعنى.","link":"https://binbaz.org.sa/fatwas/2779/معنى-ان-الله-واحد-في-اسماىه-وصفاته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1271.mp3","categories":["الأيمان والنذور","الأسماء والصفات"]},{"id":6896,"question":"ما معنى أن الله واحد في صفاته، وأسمائه، مع أن هناك من يشترك معه في التسمية من العباد؟","title":"معنى أن الله واحد في أسمائه وصفاته","answer":"الجواب:\nمعنى ذلك أنه واحد في معنى الصفات، الحكيم العليم الرحمن الرحيم، والقدير، وإن سمي بعض الأطباء حكيمًا، وإن سمي بعض الناس حكيمًا، وإن سمي بعض الناس عزيزًا، إلى غير ذلك، لكن العزة المطلقة لله وحده، والحكمة المطلقة لله وحده، والقدرة المطلقة لله وحده. فالمعنى: من اعتقد أن غير الله يشاركه في هذا المعنى، وأن له مثل صفة الله في العزة، أو في الحكمة، أو في الرحمة، أو في القدرة، أو في العلم؛ كفر بالله، أما كونه يشارك في بعض الشيء، له قدرة تليق بالمخلوق، فهذا لا يقع فيه الشرك، الله سمى نفسه سميعًا بصيرًا، وسمى عبده سميعًا بصيرًا.  فالمقصود: أن جنس المشاركة في جنس القدرة، جنس العلم، جنس السمع، جنس البصر، لكن قدرة محدودة، وعلم محدود، وبصر محدود، فالإنسان له بصر محدود، وسمع محدود، وعلم محدود، وقدرة محدودة، هذه ليس فيها شركة لله  هذه الله الذي أعطاه إياها، ومنّ بها عليه  لكن إذا قال: له قدرة من جنس قدرة الله، وأنه يتصرف في الكون كما يشاء، أو أنه يعلم المغيبات، أو ما أشبه كالله هذا هو المعنى.","link":"https://binbaz.org.sa/fatwas/2779/معنى-ان-الله-واحد-في-اسماىه-وصفاته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1271.mp3","categories":["الأيمان والنذور","الأسماء والصفات"]},{"id":6898,"question":"أعلنت البلدية أنه سوف توزع أراضي، وشرطت الحلف على عدم ملك عقار، أو أراضي، وأنا ليس لي أي أملاك، هل أحلف على ذلك؟","title":"حكم اليمين بعدم ملكية أي عقار للحصول على أرض","answer":"الجواب: الواجب على الرعية أن يلتزموا ما تقوله الدولة في حدود الشريعة، والاجتهاد، فإذا قالت الدولة: إنها تعطي من الضمان الاجتماعي من صفته كذا وكذا وكذا؛ فعلى الرعية أن يلتزموا بذلك، وليس لهم الكذب، والحيل حتى يقولوا: إن هذه المرأة فقيرة، وهي ليست فقيرة، أو هذا الرجل فقير، وليس بفقير، أو هي مطلقة، وهي غير مطلقة، لا يجوز. فإنه ليس له أن يكذب، وليس له أن .. الزور على أنه ما عنده بيت، ولا عنده أرض، وهو كاذب، ليس له ذلك؛ لأن الدولة لها في هذا اجتهاد، وتبرير، ولا مانع لها من هذا الشرط، فإذا كان عنده بيت، أو أرض؛ لا يفعل، ولا يحلف، وإذا طلبوا منه الحلف؛ لا يجوز له الحلف، لا يجوز أن يحلف فيقول: والله ما عندي أرض، وهو يكذب، والله ما عندي بيت، وهو يكذب، أما إذا كان صادقًا، ما عنده أرض، ولا بيت؛ فلا حرج، يحلف ولا حرج عليه. السؤال: هو تكميلًا للسؤال، يقول: هو عنده أرض واحد، وهبها له من عشر سنوات، ولكن لا يعلم أين هي، ولا موقعها، ولا يستطيع التصرف فيها، فهل ممكن يحلف على هذا الأساس؟","link":"https://binbaz.org.sa/fatwas/2829/حكم-اليمين-بعدم-ملكية-اي-عقار-للحصول-على-ارض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1277.mp3","categories":["الأيمان والنذور","قضايا المرأة","الأخلاق المذمومة"]},{"id":6931,"question":"ما حكم من حلف بالقرآن الكريم وعظمته؟","title":"حكم الحلف بالقرآن وعظمته","answer":"الجواب: القرآن كلام الله، فالحلف بالقرآن حلف بكلام الله، فإذا قال: والقرآن المجيد، أو وكلام الله لا أفعل كذا، فهو حلف بالقرآن، حلف بكلام الله، مثل لو قال: وعلم الله، وعزة الله، أو ورحمة الله، كله لا فرق. السؤال: آخر يقول: مدير العلاقات العامة الإداري بمستشفى الملك فهد يمنع من أراد أن يذَّكر في الصلاة داخل المستشفى، وهذا أمر عظيم، حيث يساعد على ترك الصلاة، فكيف يكون هذا التصرف من رجل مسؤول في بلد مسلم؛ لأنه لمن الغريب المنكر؟ الجواب: ينظر في الأمر -إن شاء الله-.","link":"https://binbaz.org.sa/fatwas/2861/حكم-الحلف-بالقران-وعظمته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1309.mp3","categories":["الأيمان والنذور","قضايا المرأة","الأخلاق المذمومة"]},{"id":6932,"question":"يقسم بآيات الله؟","title":"حكم الحلف بآيات الله","answer":"الجواب: كذلك آيات الله إذا كان أراد بها القرآن؛ فلا بأس، وإن كان أراد بها آيات الله التي هي الليل والنهار، والشمس والقمر؛ ما يجوز؛ لأنها مخلوقات. أما إذا قال: أقسمت بآيات الله، أو أقسم بآيات الله، يعني القرآن؛ فهو كلام الله، وإذا قال: أقسمت بآيات الله، أو أقسم بآيات الله، يعني: الليل والنهار، أو الشمس والقمر، أو السموات والأرض؛ لا ما يجوز؛ لأنها مخلوقات وَمِنْ آيَاتِهِ اللَّيْلُ وَالنَّهَارُ وَالشَّمْسُ وَالْقَمَرُ [فصلت:37].","link":"https://binbaz.org.sa/fatwas/2862/حكم-الحلف-بايات-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1310.mp3","categories":["الأيمان والنذور","قضايا المرأة","الأخلاق المذمومة"]},{"id":6974,"question":"اختلفت مع بعض إخوان لي اليوم، فهل الله  في السماء، لا ينزل الأرض، أم أنه كما تقول الآية: وَهُوَ الَّذِي فِي السَّمَاءِ إِلَهٌ وَفِي الْأَرْضِ إِلَهٌ [الزخرف:84] نرجو إفادتنا، جزاكم الله خيرًا؟","title":"بيان علو الله جل وعلا","answer":"الجواب:\n\nالله  في السماء في العلو -جل وعلا- فوق العرش  كما قال : الرَّحْمَنُ عَلَى الْعَرْشِ اسْتَوَى [طه:5]\n\nوقال سبحانه: إِنَّ رَبَّكُمُ اللَّهُ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ فِي سِتَّةِ أَيَّامٍ ثُمَّ اسْتَوَى عَلَى الْعَرْشِ [الأعراف:54] وقال : أَأَمِنْتُمْ مَنْ فِي السَّمَاءِ أَنْ يَخْسِفَ بِكُمُ الْأَرْضَ [الملك:16] قال: بَلْ رَفَعَهُ اللَّهُ إِلَيْهِ [النساء:158] يَا عِيسَى إِنِّي مُتَوَفِّيكَ وَرَافِعُكَ إِلَيَّ [آل عمران:55].\n\nفهو سبحانه فوق السماء، فوق العرش -جل وعلا- وليس في الأرض، بل هو فوق جميع الخلق  هذا الذي عليه أهل السنة والجماعة من أصحاب النبي ﷺ ومن تبعهم بإحسان، وهو الذي جاءت به الرسل جميعًا -عليهم الصلاة والسلام- أن الله فوق السماء، فوق العرش، في العلو، في جهة العلو -جل علا- وعلمه في كل مكان  لا يخفى عليه خافية  وجميع أعمال العباد تصعد إليه إن كانت صالحة، وإن كانت غير صالحة؛ ردت على أصحابها، ولا حول ولا قوة إلا بالله.\n\nأما قوله -جل وعلا-: وَهُوَ الَّذِي فِي السَّمَاءِ إِلَهٌ وَفِي الْأَرْضِ إِلَهٌ [الزخرف:84] معناه: أنه إله أهل السماء، وإله أهل الأرض، وهكذا قوله سبحانه: وَهُوَ اللَّهُ فِي السَّمَاوَاتِ وَفِي الْأَرْضِ يَعْلَمُ سِرَّكُمْ وَجَهْرَكُمْ [الأنعام:3] يعني هو إله لأهل السماء، وهو إله لأهل الأرض، يعني يعبدونه وحده  فهو إله الجميع: إله أهل السماء، وإله أهل الأرض، وإن كان فوق العرش -جل وعلا- فيعبده الملائكة في السماء، ويعبده المؤمنون في الأرض أينما كانوا، فهو إلههم، وفوقهم سبحانه، فوق جميع الخلق .\n\nس: مَا يَكُونُ مِنْ نَجْوَى ثَلَاثَةٍ إِلَّا هُوَ رَابِعُهُمْ [المجادلة:7]؟\n\nج: يعني بعلمه.\n\nس:  وَهُوَ مَعَكُمْ أَيْنَ مَا كُنْتُمْ [الحديد:4]؟\n\nج: يعني بعلمه  وهو فوق عرشه -جل وعلا-.","link":"https://binbaz.org.sa/fatwas/2909/بيان-علو-الله-جل-وعلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1357.mp3","categories":["الأيمان والنذور","الأسماء والصفات"]},{"id":7010,"question":"إذا قال الزوج عليه الحرام، ولا يقصد الطلاق، وكذلك لو قال: أنت علي حرام، وأراد الطلاق، فهل يكون طلاقًا؟","title":"حكم من يحرم امرأته على نفسه","answer":"الجواب:\n\nإذا قال: أنت علي حرام، وأراد الطلاق؛ فالصحيح أنه يكون طلاقًا، يكون طلقة واحدة على الصحيح، وإذا قال: عليه الحرام ما يفعل كذا، فله تفسيران:\n\nأحدهما: أن يقصد عليه الطلاق يعني: فعلى نيته إذا قصد الطلاق، وأنه إذا فعل كذا؛ وقع الطلاق، وقع الطلاق.\n\nأما إذا كان يقصد منع نفسه من هذا الشيء، عليه الطلاق ما يكلم فلانًا، عليه الطلاق ما تروحي لها، عليه الطلاق ما تكلمي فلانًا، بقصد منعها -ما قصده الطلاق- فهذا فيه خلاف بين أهل العلم، الصحيح أنه يكون في حكم اليمين، أن عليه كفارة يمين؛ لأن قصده المنع، ليس قصده الطلاق، والرسول ﷺ يقول: الأعمال بالنيات.\n\nفإذا كان قصده المنع، عليه الطلاق ما يكلم فلانُا، عليه الطلاق ما تروحي لأحد، عليه الطلاق ما تكلمي فلانًا، ما قصد إيقاع الطلاق، وإنما قصد تخويفها، ومنعها؛ فهذا الصواب فيه أنه عليه كفارة يمين.\n\nأما إذا قصد إيقاع الطلاق، منعها، وإيقاع الطلاق؛ فإنه يقع الطلاق طلقة واحدة، إلا إذا كرر عليه الطلاق، عليه الطلاق، عليه الطلاق، يقصد ثلاثًا وقعت الثلاث.","link":"https://binbaz.org.sa/fatwas/2941/حكم-من-يحرم-امراته-على-نفسه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1389.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":7041,"question":"غضبت مرة، وكان عندي زوجتين، وهما ساكنتين بالدور الثاني وقلت لهما بعدما ضربتهما: التي تنزل من الدرج فهي طالق، ومحرمة علي مثلما حرمت علي أمي وأختي -وأنا أقصد منعهما فقط- وكنت شديد الغضب، ونزلت إحداهما من الدرج، والأخرى لم تنزل، فهل يقع الطلاق، والظهار أم لا؟","title":"قال: التي تنزل فهي طالق، ومحرمة علي، فنزلت فما الحكم؟","answer":"الجواب:\n\nإذا كنت قصدك مثل ما قلت منعها من النزول، وتخويفها، ولم ترد إيقاع الطلاق؛ فالصحيح من أقوال العلماء: أن فيه كفارة يمين، ولا يقع، على حسب نيتك؛ لأن الرسول -عليه الصلاة والسلام- يقول: إنما الأعمال بالنيات، وإنما لكل امرئ ما نوى.\n\nفإن قلت: علي الطلاق من نزلت منكن؛ فهي طالق من هذه الدرجة، أو محرمة، والمقصود منعها حتى لا تنزل -وليس قصدك فراقها، ولا إيقاع الطلاق- إنما قصدت تخويفها ومنعها من النزول، فالتي نزلت منهما عليك عنها كفارة يمين؛ إطعام عشرة مساكين، أو كسوتهم، عشرة عدد أصابعك، كل واحد له نصف الصاع، تمر، أو أرز، أو حنطة من قوت البلد، نصف صاع من قوت البلد، أو تعشيهم في بيتك طعام مصلح مطبوخ، أو تغديهم نعم.\n\nالسؤال: ولو نزلت اثنتان كفارتان؟\n\nالجواب: إيه على كل واحدة كفارة نعم.","link":"https://binbaz.org.sa/fatwas/3073/قال-التي-تنزل-فهي-طالق-ومحرمة-علي-فنزلت-فما-الحكم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1458.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":7066,"question":"غضبت مرة، وكان عندي زوجتين، وهما ساكنتين بالدور الثاني وقلت لهما بعدما ضربتهما: التي تنزل من الدرج فهي طالق، ومحرمة علي مثلما حرمت علي أمي وأختي -وأنا أقصد منعهما فقط- وكنت شديد الغضب، ونزلت إحداهما من الدرج، والأخرى لم تنزل، فهل يقع الطلاق، والظهار أم لا؟","title":"قال: التي تنزل فهي طالق، ومحرمة علي، فنزلت فما الحكم؟","answer":"الجواب:\n\nإذا كنت قصدك مثل ما قلت منعها من النزول، وتخويفها، ولم ترد إيقاع الطلاق؛ فالصحيح من أقوال العلماء: أن فيه كفارة يمين، ولا يقع، على حسب نيتك؛ لأن الرسول -عليه الصلاة والسلام- يقول: إنما الأعمال بالنيات، وإنما لكل امرئ ما نوى.\n\nفإن قلت: علي الطلاق من نزلت منكن؛ فهي طالق من هذه الدرجة، أو محرمة، والمقصود منعها حتى لا تنزل -وليس قصدك فراقها، ولا إيقاع الطلاق- إنما قصدت تخويفها ومنعها من النزول، فالتي نزلت منهما عليك عنها كفارة يمين؛ إطعام عشرة مساكين، أو كسوتهم، عشرة عدد أصابعك، كل واحد له نصف الصاع، تمر، أو أرز، أو حنطة من قوت البلد، نصف صاع من قوت البلد، أو تعشيهم في بيتك طعام مصلح مطبوخ، أو تغديهم نعم.\n\nالسؤال: ولو نزلت اثنتان كفارتان؟\n\nالجواب: إيه على كل واحدة كفارة نعم.","link":"https://binbaz.org.sa/fatwas/3073/قال-التي-تنزل-فهي-طالق-ومحرمة-علي-فنزلت-فما-الحكم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1458.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":7071,"question":"غضبت مرة، وكان عندي زوجتين، وهما ساكنتين بالدور الثاني وقلت لهما بعدما ضربتهما: التي تنزل من الدرج فهي طالق، ومحرمة علي مثلما حرمت علي أمي وأختي -وأنا أقصد منعهما فقط- وكنت شديد الغضب، ونزلت إحداهما من الدرج، والأخرى لم تنزل، فهل يقع الطلاق، والظهار أم لا؟","title":"قال: التي تنزل فهي طالق، ومحرمة علي، فنزلت فما الحكم؟","answer":"الجواب:\n\nإذا كنت قصدك مثل ما قلت منعها من النزول، وتخويفها، ولم ترد إيقاع الطلاق؛ فالصحيح من أقوال العلماء: أن فيه كفارة يمين، ولا يقع، على حسب نيتك؛ لأن الرسول -عليه الصلاة والسلام- يقول: إنما الأعمال بالنيات، وإنما لكل امرئ ما نوى.\n\nفإن قلت: علي الطلاق من نزلت منكن؛ فهي طالق من هذه الدرجة، أو محرمة، والمقصود منعها حتى لا تنزل -وليس قصدك فراقها، ولا إيقاع الطلاق- إنما قصدت تخويفها ومنعها من النزول، فالتي نزلت منهما عليك عنها كفارة يمين؛ إطعام عشرة مساكين، أو كسوتهم، عشرة عدد أصابعك، كل واحد له نصف الصاع، تمر، أو أرز، أو حنطة من قوت البلد، نصف صاع من قوت البلد، أو تعشيهم في بيتك طعام مصلح مطبوخ، أو تغديهم نعم.\n\nالسؤال: ولو نزلت اثنتان كفارتان؟\n\nالجواب: إيه على كل واحدة كفارة نعم.","link":"https://binbaz.org.sa/fatwas/3073/قال-التي-تنزل-فهي-طالق-ومحرمة-علي-فنزلت-فما-الحكم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1458.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":7105,"question":"الأخ عرض هذا السؤال أكثر من مرة، ويلح علينا في عرضه، جدة زوجتي كانت عند مستشفى الشميس، ورغبت أن تركب تاكسي هي وأختها، وعندما أوقفت صاحب التاكسي؛ اتضح أنه قريب لها، وركبت هي وأختها معه، وأعطوه الأجرة، فرفض أن يأخذها منها، وحلفت بأن عليها صوم سنة كاملة بأن يأخذ الأجرة منها، ولكنه رفض، فما حكم هذا اليمين الذي حلفت على نفسها بأن تصوم سنة كاملة؟","title":"حكم من حلفت أن تصوم سنة كاملة","answer":"الجواب:\n\nعليها كفارة يمين، هذه يمين مكروهة، غير شرعية، وعليها كفارة يمين فقط؛ لأنه ما هو مقصودها الصوم، مقصودها تلزمه، فعليها كفارة يمين، إطعام عشرة مساكين، أو كسوتهم، ويكفي.","link":"https://binbaz.org.sa/fatwas/3134/حكم-من-حلفت-ان-تصوم-سنة-كاملة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1492.mp3","categories":["الأيمان والنذور","قضايا المرأة","الأخلاق المذمومة"]},{"id":7111,"question":"ما حكم من أقسم بالطلاق على أن شيئًا ما قد يحدث، وهو يعلم أنه لم يحدث، علمًا بأنه لم يكن يقصد الطلاق، أو ينويه؟","title":"حكم الإقسام بالطلاق من دون قصد الطلاق","answer":"الجواب:\n\nإذا حلف بالطلاق على أن هذا حدث ليصدق، ما قصد إيقاع الطلاق، ولكن قصد ليصدق، فقد أخطأ وكذب، وعليه التوبة إلى الله، وعليه كفارة يمين؛ لأنه ما قصد إيقاعه، إنما قصد أن يصدق، أو قصد أن يفعل هذا الفعل.\n\nقال: عليه الطلاق من امرأته، عليه الطلاق أن تكلمي فلانًا أو فلانًا، عليه الطلاق أن تشتري هذا، عليه الطلاق أن تخرجي لكذا وكذا، قصده أمرها بهذا الشيء، وتكليفها به، وتخويفها، وليس قصده إيقاع الطلاق، هذا حكمه حكم اليمين، فيه كفارة يمين على الصحيح، فيه خلاف بين العلماء، لكن هذا هو المختار.\n\nالسؤال: يعني إذا كذب يكفر كفارة يمين إذا كان كاذبًا في هذا اليمين؟\n\nالجواب: قصده التصديق ليس قصده إيقاع الطلاق.","link":"https://binbaz.org.sa/fatwas/3140/حكم-الاقسام-بالطلاق-من-دون-قصد-الطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1498.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":7122,"question":"والدي حلف على حقوق الآخرين من نخل وأرض وغير ذلك، والآن أصحاب هذه الحقوق البعض منهم توفي، والبعض له ورثة، والبعض لا يزال حيًا، والبعض الآخر لا يعرف عنه شيء، وهو الآن نادم أشد الندم وتاب، فما المخرج لوالدي من هذه الأيمان وما ترتب عليها، علمًا أنه يخشى إذا بلغ أصحاب هذه الحقوق، أو ورثتهم أن يترتب على ذلك مشاكل، وأضرار كثيرة؟","title":"حكم من حلف على عدم رد حقوق الآخرين وتاب بعدها","answer":"الجواب:\n\nالواجب عليه رد الحقوق إلى أهلها، يقول النبي ﷺ: من كانت عنده مظلمة لأخيه فليتحلله اليوم قبل أن لا يكون دينار ولا درهم، إن كانت له حسنات أخذ من حسناته بقدر مظلمته، فإن لم يكن له حسنات أخذ من سيئاتهم فحمل عليه.\n\nيجب عليه أن يعطيهم حقوقهم التي جحدها، وحلف عليها، ويتوب إلى الله  ويقول: يا إخواني أنا غلطت، وتبت إلى الله، خذوا حقوقكم إن كانوا موجودين، والذي مات يعطيه ورثته، والذي غاب يسأل عنه، والذي لا يعرف يتصدق بها عنه إذا كان ما يعرف يتصدق بها عنه للفقراء والمحاويج، أما أنه يسكت عليها لا.","link":"https://binbaz.org.sa/fatwas/3158/حكم-من-حلف-على-عدم-رد-حقوق-الاخرين-وتاب-بعدها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1516.mp3","categories":["الرقائق","الأيمان والنذور"]},{"id":7150,"question":"ذهبت زوجتي بدون إذني لزيارة أختها، فغضبت، وقلت لها: إذا ذهبت بدون إذني؛ فأنت طالق، ثم طالق، ثم طالق، وبعد فترة ذهبت مع أهلها، وأنا غير موجود، فهل يقع الطلاق؟ والآن أريد أن أتحلل، هل علي كفارة، أم ماذا أفعل؟","title":"حكم الطلاق بالثلاث في وقت واحد","answer":"الجواب:\n\nهذا يختلف إذا كنت قلت هذا لمنعها، ما قصدت الطلاق، إنما قصدت منعها، وتخويفها، فهذا يمين، عليك كفارة يمين إذا ذهبت بغير إذنك.\n\nأما إن كنت أردت الطلاق؛ فإنه يقع الطلاق ثلاث طلقات، طالق، ثم طالق، ثم طالق، إذا كنت أردت إيقاع الطلاق، إذا فعلت؛ فقد حرمت عليك حتى تنكح زوجًا غيرك.","link":"https://binbaz.org.sa/fatwas/3183/حكم-الطلاق-بالثلاث-في-وقت-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1541.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":7242,"question":"أقسمت على زوجتي ألا تحضر فرح بنت خالتي، أو بنت خالتها، وقلت لها: لو حضرت لا تجلسين معي في البيت مرة أخرى، ولكن عندما سافرت من اليمن إلى السعودية علمت أنها حضرت هذا الفرح؛ علمًا بأنه في بلد آخر، فما موقفي جزاكم الله خيرًا؟","title":"حكم من أقسم على زوجته أن لا تحضر عرساً فحضرته","answer":"الجواب:\n\nإذا كنت أردت الطلاق، وأنها تطلق بذلك؛ يقع طلقة، وإن كنت ما أردت الطلاق وإنما أردت تخويفها، وتحذريها؛ فليس عليك شيء، وإنما عليك كفارة يمين.","link":"https://binbaz.org.sa/fatwas/3299/حكم-من-اقسم-على-زوجته-ان-لا-تحضر-عرسا-فحضرته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1624.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":7276,"question":"من خطر اللسان قول بعضهم: وحياة الله، أو قاتلك الله، فما حكم ذلك؟","title":"حكم الحلف بحياة الله","answer":"الجواب:\n\nهذا الكلام فيه تفصيل: اللسان أخطاؤه كثيرة، وأغلاطه كثيرة، لكن (وحياة الله) ليس من أخطاء اللسان، هذا قسم بالله، إذا قلت: وحياة الله، أو وعلم الله، أو وعزة الله، أو وقدرة الله، فهذا من الأيمان الشرعية؛ لأن الحلف بالله وبصفاته حلف شرعي.\n\nأما قول: قاتلك الله، أو لعنك الله، أو أخزاك الله، هذا منكر، هذه من آفات اللسان -نعوذ بالله- فذكر الله، والحلف بأسمائه، هذا ليس من آفات اللسان، بل هذا من فضائل اللسان، ومن خصاله الطيبة أن يذكر الله، وأن يثني عليه، وأن يشكره سبحانه، وهكذا الحلف به عند الحاجة للحلف يحلف به سبحانه.\n\nلكن من آفات اللسان الحلف بغير الله، هذا من آفاته، كأن يقول: والنبي، والكعبة، والأمانة، وشرف فلان، وحياة فلان، وحياتك، هذا هو المنكر، هذا من آفات اللسان، الحلف بغير الله كائنًا من كان، يقول النبي ﷺ: من كان حالفًا فليحلف بالله أو ليصمت وفي اللفظ الآخر: فلا يحلف إلا بالله أو ليصمت ويقول ﷺ: من حلف بغير الله؛ فقد كفر، أو أشرك الشك من الراوي، هل قال: كفر، أو قال: أشرك؟ هذا يدل على أن الحلف بغير الله من جملة أنواع الكفر، نسأل الله العافية. \n\nفالواجب الحذر من ذلك، وألا تحلف إلا بربك  وقال أيضًا -عليه الصلاة والسلام-: من حلف بالأمانة فليس منا وقال: لا تحلفوا بآبائكم ولا بأمهاتكم ولا بالأنداد، ولا تحلفوا بالله إلا وأنتم صادقون.\n\nالسؤال: وحياة الله؟\n\nالجواب: الحياة من صفاته هو الحي القيوم سبحانه.","link":"https://binbaz.org.sa/fatwas/3341/حكم-الحلف-بحياة-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1662.mp3","categories":["الأيمان والنذور","قضايا المرأة","الأخلاق المذمومة"]},{"id":7277,"question":"ما حكم الكذب إذا كان كذبًا بسيطًا مثل: أن أكذب على أحد، دون أن أفقد صداقته؟","title":"خطورة التهاون في الكذب","answer":"الجواب:\n\nتقول أم كلثوم بنت عقبة ابن أبي معيط -رضي الله عنها-: لم أسمع النبي ﷺ يرخص في شيء من الكذب إلا في ثلاث: في الإصلاح بين الناس، وفي الحرب، وفي حديث الرجل امرأته، والمرأة زوجها، هذا المستثنى.\n\nفالإصلاح بين الناس، وفي الحرب، والحرب خدعة، وفيما بين الرجل وزوجته، يحدثها وتحدثه بأشياء غير حقيقة لما في هذا من إصلاح الحال بينهما، وتثبيت العشرة بينهما فيما لا يضر أحدًا من الناس، هذه الأشياء التي رخص فيها النبي ﷺ من الكذب.\n\nوأما غير هذه الثلاث فينبغي التحرز من الكذب، والحذر منه، وأن يعتني الإنسان بالصدق في أقواله، وفي أعماله، وأن يكون من ديدنه الصدق، ومن عادته الصدق في أموره، اللهم إلا أن يكون الصدق يجر عليه شرًا، ويسبب فتنًا، فهذا له بحثه، وله شأنه في محله، فإذا كان ظالم يسأل عن إنسان ليقتله، أو ليظلمه؛ فليس له الصدق في هذا، أن يقول: هو في المحل الفلاني، يقول: ما أدري؛ حتى لا يضر أحدًا، وإن كان يدري، إذا كان يعرف أن هذا السائل يضر هذا المسؤول عنه لو علم بمكانه ظلمًا وعدوانًا، فهذا من الكذب الواجب، وكذلك الذي يصلح بين الناس، فيقول خيرًا، أو ينمي خيرًا.\n\nالمقصود: أن الكذب في هذه الثلاثة لا بأس، وهكذا الكذب فيما دل الشرع على جوازه فيه لحماية المسلمين من الشر، ولحمايتهم من عدوهم، أو لحماية المسلم من ظلم من يظلمه، ويتعدى عليه، ونحو ذلك.","link":"https://binbaz.org.sa/fatwas/3352/خطورة-التهاون-في-الكذب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1673.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":7280,"question":"هل يعد التقليد بالحركات، أو بالصوت، أو بالكلام من الغيبة؟ وإذا كان من الغيبة فإن المغتاب إذا قيل له: لا تغتاب قال: هذا ما يفعله أو يقوله فلان؟","title":"حكم الغيبة بالحركات أو بالصوت","answer":"الجواب:\n\nنعم الغيبة تكون بالكلام، وتكون بالفعال، بالكلام إذا قال فلان كذا ما يكره، وتكون الغيبة بالفعل إذا أشار إليه، وعرف الناس أنه يريده، إذا كان يمشي مشيته، أو يتكلم بكلام على سبيل العيب له، والاستهزاء به، أو ما أشبه ذلك من الإشارات التي يراد منها تحقيره، ويراد منها ذمه، فهذا غيبه بالفعل، -نسأل الله العافية- وَيْلٌ لِكُلِّ هُمَزَةٍ لُمَزَةٍ [الهمزة:1].","link":"https://binbaz.org.sa/fatwas/3353/حكم-الغيبة-بالحركات-او-بالصوت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1674.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":7281,"question":"هل يعد التقليد بالحركات، أو بالصوت، أو بالكلام من الغيبة؟ وإذا كان من الغيبة فإن المغتاب إذا قيل له: لا تغتاب قال: هذا ما يفعله أو يقوله فلان؟","title":"حكم الغيبة بالحركات أو بالصوت","answer":"الجواب:\n\nنعم الغيبة تكون بالكلام، وتكون بالفعال، بالكلام إذا قال فلان كذا ما يكره، وتكون الغيبة بالفعل إذا أشار إليه، وعرف الناس أنه يريده، إذا كان يمشي مشيته، أو يتكلم بكلام على سبيل العيب له، والاستهزاء به، أو ما أشبه ذلك من الإشارات التي يراد منها تحقيره، ويراد منها ذمه، فهذا غيبه بالفعل، -نسأل الله العافية- وَيْلٌ لِكُلِّ هُمَزَةٍ لُمَزَةٍ [الهمزة:1].","link":"https://binbaz.org.sa/fatwas/3353/حكم-الغيبة-بالحركات-او-بالصوت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1674.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":7288,"question":"إذا كان الشخص في جماعة -يعني مع ناس- وعلق على شخص منهم، علق يعني معناه: تكلم بشيء ليس بصحيح، يريد إضحاك الجماعة، والشخص عن ذلك لم يرض، فما حكم ذلك؟","title":"حكم الكذب على شخص لإضحاك الناس","answer":"الجواب:\n\nليس له أن يعلق شيئًا يؤذي بعض الحاضرين، أو يكون كذبًا، أو يكون مغضبًا لله  ولو أراد الإضحاك.\n\nيقول النبي ﷺ: ويل للذي يحدث فيكذب ليضحك القوم، ويل له، ثم ويل له ما يجوز للإنسان أن يتكلم بالباطل ليضحك الناس، عليه أن يصون لسانه، وألا يعلق شيئًا يضحك الناس، وهو لا يجوز في نفسه إما كذب، وإما سب لأحد، وإما استهزاء بأحد، كل هذا منكر.","link":"https://binbaz.org.sa/fatwas/3345/حكم-الكذب-على-شخص-لاضحاك-الناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1666.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":7404,"question":"نذرت بهذا اللفظ، وخاطبت مجموعة من الناس كانوا جلوسًا عندي قلت لهم: إن لكم علي أربع من الغنم، وكان في النية أن أذبحها لهم، ولكن هؤلاء الناس تفرقوا، ولم يبق منهم إلا القليل، فهل يجوز لي أن أصرفه إلى الفقراء، وهل يجوز أن آكل منه، مع أنه كان في النية أن أعزم هؤلاء، والغالب عندي أن آكل من هذا النذر، فما رأي سماحتكم؟","title":"الوفاء بالنذر وما يتعلق به","answer":"الجواب:  إذا نذرت أن تذبحها لهم وأبوا؛ عليك كفارة يمين؛ لأن المقصود إكرام الضيف، المقصود من هذا إكرام الضيف، إذا قلت: والله نذر لوجه الله أن أذبحها لكم، أو والله لأذبحها لكم، أو علي الحرام أن أذبحها لكم، وأبوا؛ عليك كفارة يمين في هذا؛ لأن هذا ما هو مقصودك التقرب إلى الله، مقصودك إكرامهم هم، فإذا أبوا وعاندوك؛ فعليك كفارة يمين، بخلاف ما لو قلت: لله علي أن أتصدق بناقة، أو أتصدق بخروف، أو أتصدق ببقرة، فهذا نذر لله، عليك أن تؤده لقول النبي ﷺ: من نذر أن يطيع الله فليطعه.  وأما قولك: نذر عليَّ أن أذبح لكم، أو والله أذبح لكم، أو عليَّ الحرام أن أذبح لكم، مقصودك إكرامهم، وتلزيمهم، فأبوا؛ فعليك كفارة يمين، ويبقى مالك لك، فإن ذبحتها وتصدقت بها فلا بأس. ولا بأس أن تأكل منها إذا ذبحتها؛ لأن قصدك أن تأكل أنت وأهل بيتك مع الضيوف، إذا ذبحتها، وتصدقت منها، وأكلت منها أنت وأهل بيتك؛ فلا بأس.","link":"https://binbaz.org.sa/fatwas/3476/الوفاء-بالنذر-وما-يتعلق-به","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1780.mp3","categories":["الأيمان والنذور","قضايا المرأة","الأخلاق المذمومة"]},{"id":7419,"question":"نذرت بهذا اللفظ، وخاطبت مجموعة من الناس كانوا جلوسًا عندي قلت لهم: إن لكم علي أربع من الغنم، وكان في النية أن أذبحها لهم، ولكن هؤلاء الناس تفرقوا، ولم يبق منهم إلا القليل، فهل يجوز لي أن أصرفه إلى الفقراء، وهل يجوز أن آكل منه، مع أنه كان في النية أن أعزم هؤلاء، والغالب عندي أن آكل من هذا النذر، فما رأي سماحتكم؟","title":"الوفاء بالنذر وما يتعلق به","answer":"الجواب:  إذا نذرت أن تذبحها لهم وأبوا؛ عليك كفارة يمين؛ لأن المقصود إكرام الضيف، المقصود من هذا إكرام الضيف، إذا قلت: والله نذر لوجه الله أن أذبحها لكم، أو والله لأذبحها لكم، أو علي الحرام أن أذبحها لكم، وأبوا؛ عليك كفارة يمين في هذا؛ لأن هذا ما هو مقصودك التقرب إلى الله، مقصودك إكرامهم هم، فإذا أبوا وعاندوك؛ فعليك كفارة يمين، بخلاف ما لو قلت: لله علي أن أتصدق بناقة، أو أتصدق بخروف، أو أتصدق ببقرة، فهذا نذر لله، عليك أن تؤده لقول النبي ﷺ: من نذر أن يطيع الله فليطعه.  وأما قولك: نذر عليَّ أن أذبح لكم، أو والله أذبح لكم، أو عليَّ الحرام أن أذبح لكم، مقصودك إكرامهم، وتلزيمهم، فأبوا؛ فعليك كفارة يمين، ويبقى مالك لك، فإن ذبحتها وتصدقت بها فلا بأس. ولا بأس أن تأكل منها إذا ذبحتها؛ لأن قصدك أن تأكل أنت وأهل بيتك مع الضيوف، إذا ذبحتها، وتصدقت منها، وأكلت منها أنت وأهل بيتك؛ فلا بأس.","link":"https://binbaz.org.sa/fatwas/3476/الوفاء-بالنذر-وما-يتعلق-به","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1780.mp3","categories":["الأيمان والنذور","قضايا المرأة","الأخلاق المذمومة"]},{"id":7426,"question":"أنا رجل متزوج، ولدي ولد، وزوجتي حامل في شهرها الأول، ولقد خرجت زوجتي مع أخي إلى المستشفى، وذلك دون إذن مني، أو من والدي، فأثار ذلك غضبي، وليس بالغضب الذي يفقدني عقلي، ولكني أعي ما أقول، وأستطيع ان أمنع نفسي من أي كلمة لا أريد النطق بها، فحلفت على زوجتي بالطلاق بقصد التهديد، لا بقصد الفراق؛ لأنني سبق أن حلفت عليها بالله، وفجرتني وكفرت عن حلفي، فحلفت بالطلاق؛ لعلها تنتهي عن مخالفتي، وهذا نص الحلف:علي الطلاق بالثلاث المحرمات، أو الحارمات أنك لو تخرجين من المنزل من غير إذني أن أذهب بك إلى أهلك، وبعد تداول الكلام بيننا بعد ذلك قال: إذا خرجت من فتحة الباب شبرًا واحدًا بدون إذن مني؛ فأنت طالق، وبعد ذلك بيومين خرجت مع والدي إلى المستشفى بدون إذن مني مع العلم أني موجود، ولكنها تقول: إنها لم تسمع الطلاق، والآن أود استرجاعها من أجل ابني ومن أجل الجنين الذي في بطنها، أفيدونا أفادكم الله، وأنني أقصد التهديد في كلا الحالتين، وإذا كانت حاملًا في الشهر الأول فمتى تنتهي عدتها؟ أي متى آخر موعد لاسترجاعها، وهل تلزم علي نفقتها وهي الآن في منزل والدها؟","title":"حكم من حلف على زوجته بالطلاق بقصد التهديد لا الفراق","answer":"الجواب: إذا كان الواقع هو ما ذكره السائل؛ فإن هذا الكلام يكون حكمه حكم اليمين؛ لأن المقصود تهديدها، وتخويفها، وليس المقصود إيقاع الطلاق، فمثل ما فعلت في المرة الأولى عليك كفارة يمين، وهي: إطعام عشرة مساكين، أو كسوتهم بسبب خروجها لو كانت متعمدة، ولو كانت عالمة، أما ما دامت لم تسمع الكلام؛ فليس عليك شيء؛ لأنها جاهلة أو ناسية، لو كانت فعلت ناسية كذلك؛ لأن الله يقول: رَبَّنَا لَا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا [البقرة:286] وصح عن رسول الله ﷺ أنه قال: قال الله: قد فعلت فإذا خرجت جاهلة، ما درت عن يمينه، ما سمعت أو ناسية؛ فليس عليه كفارة، أما لو تعمدت وهي ذاكرة لو تعمدت فعليك كفارة يمين، ما دام القصد التهديد، والمنع، وليس القصد فراقها، لعلك فهمت.","link":"https://binbaz.org.sa/fatwas/3517/حكم-من-حلف-على-زوجته-بالطلاق-بقصد-التهديد-لا-الفراق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1821.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":7429,"question":"ما الحكم على من تستر على الذين يتركون الصلاة، ويقضون وقتهم مع لعب الورق؟","title":"حكم التستر على تارك الصلاة","answer":"الجواب: الواجب على المؤمنين التعاون، مثلما سمعت في الكلام، التعاون على الخير، وأن ينصحوا من تخلف عن الصلاة، وأن لا يتركوهم في باطلهم، ومع الشياطين، بل ينصحونهم ويوجهونهم إلى الخير، فإن استقاموا وإلا رفع الأمر إلى المسؤول عنهم حتى يقيم في حقهم ما يلزم، وحتى يبلغ عنهم ما يلزم، المقصود أن ترك الناس على باطلهم أمر منكر، والله -جل وعلا- يقول: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ [التوبة:71]، ويقول سبحانه: كُنْتُمْ خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ تَأْمُرُونَ بِالْمَعْرُوفِ وَتَنْهَوْنَ عَنِ الْمُنْكَرِ [آل عمران:110].  ويقول النبي ﷺ: من رأى منكم منكرًا؛ فليغيره بيده، فإن لم يستطع فبلسانه، فإن لم يستطع فبقلبه، وذلك أضعف الإيمان فإذا علم أن أهل المكتب الفلاني، أو البيت الفلاني يضيعون الصلوات، ولا يبالون بهم؛ نصحهم الإخوان، واتصل بهم الإخوان، ووجهوهم إلى الخير وحذروهم من مغبة عملهم، فإن استقاموا؛ وإلا رفع بأمرهم إن كانوا في دائرة يرفع إلى رئيس الدائرة، أو إلى الهيئة، أو إلى أمير القرية، أو ما أشبه ذلك ممن يرجو أنه ينفع في هذا المقام، من باب التعاون على البر والتقوى، بعدما ينصح لهم، ويجتهد، وإذا تيسر أن يكون الناصح معه غيره لا يكون فردًا؛ يذهب معه بعض إخوانه؛ لأن كلمة الجماعة أشد أثرًا، إذا كان الناصحون اثنين، أو ثلاثة، أو نحو ذلك كان هذا أشد أثرًا في نفس المنصوح، وأقرب إلى النتيجة الصالحة.","link":"https://binbaz.org.sa/fatwas/3514/حكم-التستر-على-تارك-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1818.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":7654,"question":"طيب لو جامع، نحب أن نعرف الحد على ذلك؟","title":"ما هو حد الجماع في نهار رمضان؟","answer":"الجواب: الجماع هو إيلاج الذكر، الحشفة في الفرج، إذا أولج ولو ما أنزل ، إذا أولج ذكره في فرجها في النهار فهذا الصيام هذا لا يجوز، وعليه التوبة والاستغفار وعليه الندم، وعليه كفارة مع ذلك وهي عتق رقبة مؤمنة، فإن لم يستطع صام شهرين متتابعين، فإن لم يستطع الصوم أطعم ستين مسكيناً لكل مسكين نصف صاع من قوت البلد من تمر أو رز أو غيرهما، هذه كفارة الوطء في رمضان، أما في الليل فلا بأس، إن جامع أهله في الليل لا بأس، في رمضان كله حتى في العشر الأخيرة، إذا كان ما هو معتكف حتى في العشر الأخيرة، إذا لم يعتكف له الجماع، أم في النهار لا، لا يجامع زوجته أبداً في نهار الصيام في نهار رمضان، ويحرم عليه جماعها، وأما التقبيل كونه يقبلها.. يلمسها.. يضمها إليه.. ينام معها كل هذا لا حرج فيه والحمد لله، لكن إذا كان شديد الشهوة يخشى من الجماع فالأولى به أن يترك التقبيل والضم إليه إذا كان شديد الشهوة، وينام وحده في النهار، لا يضمها إليه إذا كان إنساناً شديد الشهوة لا يتمالك يترك هذا الشيء، أما إذا كان لا، عنده تحمل.. عنده صبر.. عنده تمالك فلا بأس أن ينام معها ولا بأس أن يقبلها، والحمد لله. نعم.","link":"https://binbaz.org.sa/fatwas/4793/ما-هو-حد-الجماع-في-نهار-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_036/03605.mp3","categories":["الجماع في نهار رمضان","الأيمان والنذور"]},{"id":7675,"question":"هذه رسالة أيضاً من سليم محمد الزهراني بعث بها يقول: قبل مدة من الزمن قد تزيد عن السنة وفي منطقة معينة، وكان لي زملاء فقلت لهم: إن حصل لي كذا وكذا فلكم علي أن أذبح لكم ذبيحة بهذا اللفظ، وبالطبع حصل ما كنت أقصده، ولكن سافرت وابتعدت عن هؤلاء الزملاء سفر فجأة بحكم العمل، ولم أتذكر ذلك إلا بعد مغادرتي تلك المنطقة التي نذرت فيها النذر المخصص لأولئك النفر المخصصون، و هل يلزمني أن أوفي بنذري في مكاني الحالي، أو في أي مكان وعند أي أناس، مع العلم أنه ليس بالإمكان رجوعي إلى مقري السابق وتقبلوا تحياتي؟","title":"ما يلزم من قال: إن حصل لي كذا فعلي كذا؟","answer":"الجواب: هذا ليس بنذر، إذا قال: إن حصل لي كذا وكذا فعليكم علي كذا وكذا هذا ليس بنذر هذا وعد، النذر: أن يقول: صدقة لوجه الله، أو نذر لله علي إذا شفاني الله أو حصل لي كذا وكذا أن أفعل كذا وكذا، أن أصوم كذا، أن أتصدق بكذا، هذا النذر، أما قوله: إن حصل لي كذا أعطيتهم كذا، أو ذبحت لكم ذبيحة هذا وعد وليس بنذر، فإن ذبح لهم فلا بأس وإن ترك فلا بأس لا يلزمه ذلك، وإن تيسر وذبح لهم فهذا حسن، وأما إذا نذر نذر قال صدقة لوجه الله علي، أو نذر لله علي أن أفعل كذا وكذا إذا حصل كذا وكذا فإنه يوفي بنذره نذر الطاعة، إذا كان للفقراء والمساكين، أو صلاة أو صوم شرعي فلا بأس، أما لواحد معين نذر لله علي أو صدقة لوجه الله علي إن شفاني الله أن أعطي فلان كذا، أو أكسوه وهو فقير يستحق ذلك فإنه يوفي. نعم.","link":"https://binbaz.org.sa/fatwas/4874/ما-يلزم-من-قال-ان-حصل-لي-كذا-فعلي-كذا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_040/04002.mp3","categories":["الأيمان والنذور"]},{"id":7701,"question":"يقول في سؤاله الأخير مختار صالح حامد من السودان الخرطوم: سمعنا في برنامجكم نور على الدرب أن الحلف بغير الله حرام، كما سمعنا فيه أن شخصاً حلف بالطلاق فلا تطلق زوجته، أليس في ذلك تناقض يا سماحة الشيخ؟","title":"الحلف بالطلاق ليس حلفاً بغير الله","answer":"الجواب: الحلف بغير الله منكر، النبي ﷺ قال: من كان حالفاً فليحلف بالله أو ليصمت، وقال عليه الصلاة والسلام: من حلف بغير الله فقد كفر أو أشرك وهو حديث صحيح، وقال عليه الصلاة والسلام: من حلف بالأمانة فليس منا، وقال: لا تحلفوا بآبائكم ولا بأمهاتكم ولا بالأنداد، ولا تحلفوا بالله إلا وأنتم صادقون هذا حكمه عليه الصلاة والسلام، وهو منع الحلف بغير الله كائناً من كان، فلا يجوز الحلف بالنبي عليه الصلاة والسلام، ولا بالكعبة، ولا بالأمانة، ولا بحياة فلان، ولا شرف فلان، كل هذا لا يجوز؛ لأن الأحاديث الصحيحة دلت على منع ذلك، وقد نقل أبو عمر بن عبد البر -الإمام المشهور- رحمه الله إجماع أهل العلم على أنه لا يجوز الحلف بغير الله، فالواجب على المسلمين أن يحذروا ذلك، وليس لأحد أن يحلف بحياة فلان أو بشرف فلان أو بالكعبة أو بالنبي أو بالأمانة، كل هذا لا يجوز. \nأما الطلاق فلا يسمى حلف في الحقيقة، وإن سماه الفقهاء حلفاً، لكن ليس من جنس هذا، الحلف بالطلاق معناه: إيقاعه على وجه الحث والمنع والتصديق والتكذيب مثل: والله ما أقوم، والله ما أكلم فلان، هذا يسمى يمين، فإذا قال: عليه الطلاق ما يقوم، عليه الطلاق ما يكلم فلان، نسميه يمين من هذه الحيثية، يعني: من جهة ما يتضمنه من الحث والمنع أو التصديق والتكذيب، سمي يميناً لهذا المعنى، وليس فيه حلفاً بغير الله، ما قال: بالطلاق ما أفعل كذا، لا يحلف بالطلاق، لا يقول: بالطلاق ما أفعل كذا، بالطلاق ما أكلم.. لا، هذا لا يجوز، لكن إذا قال: عليه الطلاق إنه ما يكلم فلان، عليه الطلاق إنك ما تروحي يا فلانة عند كذا وكذا، يعني زوجته، عليه الطلاق ما يسافر إلى كذا وكذا، هذا طلاق معلق يسمى يميناً؛ لأنه في حكم اليمين من جهة الحث والمنع والتصديق والتكذيب، فالصواب فيه أنه إذا كان قصد منعها أو منع نفسه أو منع غيره من هذا الشيء اللي حلف عليه يكون حكمه حكم اليمين، فيه كفارة يمين، وليس في هذا مناقضة لقولنا: إن الحلف بغير الله ما يجوز، وليس في هذا مخالفة؛ لأن هذا شيء وهذا شيء، ذاك حلف بغير الله يقول: باللات والعزى، بفلان، بحياة فلان وحياة فلان، هذا حلف بغير الله، أما هذا طلاق معلق ليس حلفاً في المعنى والحقيقة بغير الله، ولكنه حلف في المعنى من جهة منعه وتصديقه وتكذيبه، فإذا قال: عليه الطلاق ما يكلم فلان، كأنه قال: والله ما أكلم فلان، أو قال: عليه الطلاق ما تكلمي فلان يخاطب زوجته كأنه قال لها: والله ما تكلمي فلان، فإذا حصل الخلل وحنث في هذا الطلاق الصواب أنه يكفر عن يمينه كفارة يمين، يعني له حكم اليمين، إذا كان قصد منع الزوجة أو منع نفسه، ما قصد إيقاع الطلاق، إنما نوى منع هذا الشيء منع نفسه أو منع الزوجة من هذا الفعل أو من هذا الكلام، فهذا يكون له حكم اليمين عند بعض أهل العلم وهو الأصح، وعند الجمهور: يقع الطلاق، عند الأكثرين: يقع الطلاق، لكن عند جماعة من أهل العلم: لا يقع الطلاق وهو الأصح، وهو اختيار شيخ الإسلام ابن تيمية وابن القيم وجماعة من السلف رحمة الله عليهم؛ لأنه له معنى اليمين من جهة الحث والمنع والتصديق والتكذيب، وليس له معنى اليمين في تحريم الحلف بغير الله؛ لأنه ليس حلفاً بغير الله، وإنما هو تعليق، فينبغي فهم الفرق بين هذا وهذا، والله أعلم. نعم.","link":"https://binbaz.org.sa/fatwas/4900/الحلف-بالطلاق-ليس-حلفا-بغير-الله ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_029/02903.mp3","categories":["الطلاق","الأيمان والنذور"]},{"id":7744,"question":"أيضاً يقول في رسالته: نلاحظ -فضيلة الشيخ- أن بعض الناس وبالذات طلاب المدارس يحلف بالنجاح فيقول: بنجاحي، ويقول: بتوفيقي، فهل هي شرك بالله؟ أرشدنا مع التوجيه السليم على القضاء على هذه العادة، مع العلم أنها منتشرة مع كثير من الطلاب، وفقكم الله؟","title":"تحريم الحلف بغير الله","answer":"الجواب: الحلف بغير الله من المنكرات ومن المحرمات الشركية، وقد أوضح النبي ذلك عليه الصلاة والسلام، وكان الناس أولاً يحلفون بآبائهم، كانت العرب تحلف بآبائها وأمهاتها، فأنكر النبي صلى الله عليه وسلم ذلك بعد ذلك، وأدرك بعض الصحابة في ركبهم يحلفون بآبائهم فنهاهم وقال: «إن الله نهاكم أن تحلفوا بآبائكم»، وقال: «من كان حالفاً فليحلف بالله أو ليصمت»، وقال: «لا تحلفوا بآبائكم ولا بأمهاتكم ولا بالأنداد، ولا تحلفوا بالله إلا وأنتم صادقون»، وقال عليه الصلاة والسلام: «من حلف بغير الله فقد كفر أو أشرك»، وقال: «من حلف بالأمانة فليس منا»، ولما قال سعد: «يا رسول الله! إني حلفت فقلت في يميني: واللات والعزى، فقال له: قل: (لا إله إلا الله) .......... سبع مرات»، وفي بعض الروايات: «تعوذ بالله من الشيطان».\nفالمقصود أن الحلف بغير الله منكر ومن المحرمات الشركية، فلا يجوز أن يحلف بنجاحه ولا بأبيه ولا بأمه ولا بحياة فلان ولا برأس فلان ولا بالنبي ولا بالكعبة ولا بشرف فلان، كل هذه منكرات ومحرمات شركية ليس لأحد أن يتعاطها أبداً، ومن فعل شيئاً من هذا فعليه البدار بالتوبة من المحرمات الشركية ومن الشرك الأصغر يعني، وقد يكون شركاً أكبر، إذا قام بقلبه تعظيم المحلوف به وأنه يعظمه كما يعظم الله أو أنه يعتقد فيه شيء من العبادة والسر، هذا يكون شركاً أكبر نسأل الله العافية، أما إذا جرى على لسانه من غير قصد ولكنها عادة فهذا من الشرك الأصغر، فينبغي الحذر من هذا، وألا يحلف بأبيه ولا بأمه ولا بنجاحه ولا بتوفيقه ولا بغير ذلك، أما إذا كان قال: بتوفيقي، أي: (بتوفيق الله لي) قصده بتوفيق الله هذا شيء آخر، سأنجح بتوفيق الله أو كذا، أما (بتوفيقي) يقصد (بتوفيقي) الحلف بذلك، هذا لا يجوز، بل هو من المحرمات الشركية.\nفالحاصل أن الواجب على المسلم أن يحذر ورطات اللسان، فإن ورطات اللسان كثيرة وخطيرة وهذا منها، الحلف بغير الله من ورطات اللسان ومن آفات اللسان، فليحذر ذلك غاية الحذر، وإذا رأى من يفعله ينكر عليه ويعلمه وينصحه ويقول له: إن هذا لا يجوز، وأن الواجب الحلف بالله وحده سبحانه وتعالى. نعم.","link":"https://binbaz.org.sa/fatwas/4947/تحريم-الحلف-بغير-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_042/04205.mp3","categories":["الأيمان والنذور","الحلف بغير الله"]},{"id":7764,"question":"الرسالة الأخيرة في لقائنا هذا وردتنا من عدة مرسلين، يقول فيها مرسلوها -الزملاء: محمد سرور الشمري، عبد الله إسماعيل، محمد محمد اليمامي، سعيد الشهري- يقول: قال الله تعالى: فَكَفَّارَتُهُ إِطْعَامُ عَشَرَةِ مَسَاكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ [المائدة:89] أولاً يقول: ما المقصود بالإطعام؟ هل يكفي العيش أو الخبز أم أنه لابد أن أعطي الفقير ملح ودهن ولحم وصلصة وبهارات وبصل.. إلى آخره؟ أو أعمل غداء وأعزم الفقراء عليه؟ أو أعطيه المساكين جاهزاً في منازلهم؟ وما كيفية الكسوة؟ هل هي ثوب فقط أم ثوب وغترة وطاقية ووهاف وفنيلة.. إلى آخره، أفتونا جزاكم الله خير، وأنيروا لنا الطريق فنحن في حيرة من أمرنا؟","title":"كيفية الإطعام والكسوة في كفارة اليمين","answer":"الجواب: الإطعام أوضح العلماء وأهل التفسير معناه، وأنه يشمل ما ذكره السائل، يشمل أن يعطيهم طعاماً نيئاً يصنعه للفقير في بيته، يعطيهم مثلاً نصف صاع من الأرز.. من الحنطة.. من الشعير يتصرف فيه الفقير، هذا هو أحسن ما قيل في ذلك، نصف صاع، كيلو ونصف تقريباً، من هذه الحبوب التي يعيش بها أهل البلد، يعني من قوت بلده، نصف صاع من قوت البلد، قريب كيلو ونص، ومثله التمر، نص صاع من التمر كذلك أو الزبيب من قوت البلد أياً كان، وله أيضاً أن يطعمهم شيء مصلح في بيته، يعني: طعام مجهز مطبوخ من الخبز وأدم، يغديهم ويعشيهم مثل: رز مطبوخ مع اللحم؛ يعشيهم ويغذيهم، كل هذا طيب، إذا صنع لهم طعاماً من أرز أو من حنطة من خبز مع إدامه هذا طيب، ودعاهم إليه وأكلوا كفى.\nفالمقصود أن الإطعام يشمل هذا وهذا، يشمل كونه يعطيهم طعاماً يأكلونه في بيوتهم، ويشمل ما لو دعاهم إلى طعام في بيته وصنعه لهم أو في فندق أو في مطعم، لا بأس بذلك.\nوأما الكسوة فهي ما يجزئه في الصلاة كما نبه عليه أهل العلم، الكسوة التي يلبسها وتجزئه في الصلاة مثل: إزار ورداء، يعطي إزار ورداء طيب، يعطيهم قميص، ما يلزم غترة، موه لزوم غترة، إذا أعطاه قميص كفى، أو إزار ورداء، أو سراويل ورداء، كل هذا يجزي، لأن هذا يجزؤه في الصلاة، وهو كسوة تامة، سراويل ورداء أو إزار ورداء أو قميص كسوة. نعم.\nوإذا كمل وأعطاه مع القميص يعني: عمامة -غترة- طيب، هذا مزيد خير. نعم.\nالمقدم: لكن بالنسبة للإطعام لو أعطاه نصف صاع ما يلزمه مثلاً: دهونات أو أملاح؟\nالشيخ: لا يلزمه.\nالمقدم: يكفيه نصف صاع فقط؟\nالشيخ: نعم.\nالمقدم: أحسنتم أثابكم الله.\nالشيخ: ولهذا في حجة الوداع لما بين النبي صلى الله عليه وسلم معنى قوله سبحانه وتعالى: فمَنْ كَانَ مِنْكُمْ مَرِيضًا أَوْ بِهِ أَذًى مِنْ رَأْسِهِ فَفِدْيَةٌ مِنْ صِيَامٍ أَوْ صَدَقَةٍ أَوْ نُسُكٍ [البقرة:196]، بين الصدقة وأنها نصف صاع من تمر لكل مسكين، فإذا أعطى نصف صاع من التمر أو من غيره من الحبوب كفى. نعم.","link":"https://binbaz.org.sa/fatwas/4974/كيفية-الاطعام-والكسوة-في-كفارة-اليمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_045/04506.mp3","categories":["الأيمان والنذور"]},{"id":7798,"question":"هذه رسالة بعث بها المرسل (ع. ع. ع) من الرياض يقول: إني من زمان قديم لا يقل عن عشر سنوات وبعد أن تسحرنا جامعت زوجتي ولا أدري هل قد طلع الفجر أم لا حيث لم يكن طلوعه واضح، والآن أنا في حيرة من أمري ماذا أعمل، هل الكفارة تلزم الرجل أو المرأة؟","title":"حكم من جامع آخر الليل شاكاً في طلوع الفجر","answer":"الجواب: إذا كان الجماع في آخر الليل ولم يتيقن طلوع الفجر فليس على الزوج ولا على الزوجة شيء لا قضاء ولا كفارة، إذا كانا لم يتحققا طلوع الفجر فالأصل بقاء الليل وعدم وجوب الكفارة هذا هو الأصل وعدم وجوب القضاء، فإذا كان الجماع وقع في آخر الليل ثم جاء الشك بعد ذلك هل طلع الفجر أم لم يطلع الفجر فليس عليهما قضاء ولا كفارة، بل صومهم صحيح وليس عليهم شيء؛ لأن الأصل بقاء الليل والأصل براءة الذمة من الكفارات والقضاء، فإن علموا فإن علم الرجل أو المرأة علما أنهما صادفا الصبح وأن الجماع صار بعد الصباح وبعد الفجر يقيناً إذا علما هذا يقيناً فعليهما الكفارة وعليهما قضاء اليوم، إذا علما هذا يقيناً أنه صادف أن الجماع صادف النهار فعليهما القضاء لذلك اليوم، وعليهما أيضاً الكفارة، وهي: عتق رقبة، فإن لم يجدا فصوم شهرين متتابعين، فإن لم يستطيعا فإطعام ستين مسكيناً، كل واحد عليه ذلك، هي عليها عتق رقبة وهو كذلك، فإن عجزا فصيام شهرين متتابعين على كل واحد منهما، فإن لم يستطيعا أطعما عن ذلك ستين مسكيناً، عليها ستين مسكين وعليه ستين مسكين، يعني: ستين صاعاً لكل مسكين صاع نصفه عنها ونصفه عنه إذا كانت مطاوعة له لم تكره ولم تجبر. نعم.","link":"https://binbaz.org.sa/fatwas/5150/حكم-من-جامع-اخر-الليل-شاكا-في-طلوع-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_050/05003.mp3","categories":["الجماع في نهار رمضان","الأيمان والنذور"]},{"id":7818,"question":"تقول السائلة: إخوتي عندما أقسم عليهم بفعل شيء أو تركه لا ينفذون ذلك، فهل علي كفارة؟ وما هي كفارة اليمين بعض الناس يقولون: تكفي مائة ريال عن اليمين، فهل هذا صحيح؟","title":"حكم من حلف على شخص بعمل شيء فلم يفعله","answer":"الجواب: إذا حلفت عليهم ولم يبروا يمينك فعليك الكفارة، وهي مذكورة في قوله جل وعلا : وَلَكِنْ يُؤَاخِذُكُمْ بِمَا عَقَّدْتُمُ الأَيْمَانَ فَكَفَّارَتُهُ إِطْعَامُ عَشَرَةِ مَسَاكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍ فَمَنْ لَمْ يَجِدْ فَصِيَامُ ثَلاثَةِ أَيَّامٍ [المائدة:89].\nوالكفارة مثلما قال الله جل وعلا إطعام عشرة مساكين، ما هو بدراهم إطعام عشرة مساكين كل مسكين له نصف الصاع أو تعشونهم أو تغدونهم، أو عتق رقبة، أو كسوة كل واحد يعطى قميص أو إزار ورداء الكسوة الشرعية، فمن عجز عن هذا كله فعليه أن يصوم ثلاثة أيام، والأفضل أن تكون متتابعة، هذا هو الأفضل صيام ثلاثة أيام متتابعة، إذا عجز عن الكسوة والإطعام والعتق.","link":"https://binbaz.org.sa/fatwas/5210/حكم-من-حلف-على-شخص-بعمل-شيء-فلم-يفعله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_051/05128.mp3","categories":["الأيمان والنذور"]},{"id":7848,"question":"هذه رسالة وردت من المرسلة (رقية . م. ع) تشكو زوجها في هذه الرسالة، تقول: بسم الله الرحمن الرحيم، إلى سماحة الشيخ عبد العزيز بن باز وفقه الله آمين وأمد في عمره وجعل الجنة مثواه آمين، السلام عليكم ورحمة الله وبركاته، وبعد: سماحة الشيخ: إني أشكو زوجي لا معترضة عليه، ولكن لكي أقف على الحقيقة، فقد منعني هداه الله من الحج، وذلك أني نذرت أن أحج هذه السنة وقال: ليس للمرأة أن تنذر شيئاً ولم تخبر زوجها قبل، فهل له أن يمنعني من القيام بوفاء هذا النذر، أجيبوني، وفقكم الله لما يحبه ويرضاه؟","title":"حكم امرأة نذرت أن تحج ومنعها زوجها","answer":"الجواب: هذا أيضاً سؤال له أهميته وله قيمته نؤجله إلى حلقة أخرى حتى أتأمل كلام أهل العلم في ذلك، حتى أنظر في كلام أهل العلم، وهل يجب عليه أن يوكلها أو لا مانع من التأخير هذا محل نظر، أما النذر فهو لاشك أنه حق ولكن لا ينبغي له النذر، ولقد وقع، فعلى كل حال مادام وقع النذر لابد من النظر في جوابه إن شاء الله في حلقة أخرى، ننظر فيه أيها السائلة! سننظر في الموضوع إن شاء الله ثم نجيبك إن شاء الله من طريق نور على الدرب بحول الله، نجيبك بما نراه موافقاً للشريعة في هذا الأمر، حتى يعلم زوجك وحتى تعلمي أنت ما يجب شرعاً في هذا المقام حسب ما نعلم من شرع الله بعد النظر وبعد التأمل في الموضوع إن شاء الله.","link":"https://binbaz.org.sa/fatwas/5252/حكم-امراة-نذرت-ان-تحج-ومنعها-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_054/05406.mp3","categories":["الأيمان والنذور"]},{"id":8101,"question":"وأول رسالة نبدأ بها، رسالة الأخت انتصار سعيد من جمهورية اليمن الديمقراطية الشعبية، من شارع المختار: فضيلة الشيخ! إن والدتي قد نذرت نذراً كبيراً لم تستطع أن توفي به، وذلك لظروف، وهذا النذر هو أنها نذرت أن تذبح في كل سنة رأس كبش، وقد كانت الأحوال المادية في السابق حسنة جداً، ولكنها ساءت في الأخير، ونذرها هذا؛ بسبب مرض أخي فقالت: إن شفي فإني سوف أذبح كل سنة كبش، لكن نظراً لسوء الظروف لم تستطع، فما المخرج من ذلك وفقكم الله؟","title":"حكم من نذرت ذبح كبش كل عام وعجزت عن الوفاء","answer":"الجواب: بسم الله الرحمن الرحيم الحمد لله، والصلاة والسلام على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: إذا كان أخوها قد شفي، فالنذر ثابت في ذمة أمها، وإذا كانت عجزت ولم تؤده وماتت، فإنه يؤدى من تركتها إذا كان لها تركة، أما إن كان ما لها تركة فإنه يسقط عنها، إلا إذا أداه عنها أولادها فجزاهم الله خيراً، إذا كان الكبش لله وحده، فنذرت هذا الكبش لله وحده، تقرب إلى الله سبحانه وتعالى، أما إذا كان الكبش منذور للعيدروس ، أو لبعض الأولياء هذا شرك أكبر باطل، لا يوفى به، وهو باطل شرك ولا يصلح، وهي على هذا تكون مشركة بهذا النذر والعياذ بالله. فالمقصود إن كان الذبح، إن كان الكبش نذرته لله وحده، أن تذبحه لله تقرباً إلى الله سبحانه وتعالى فهذا حق؛ لأن الرسول ﷺ قال: من نذر أن يطيع الله فليطعه. أما إن كان نذرته لبعض الأولياء للعيدروس في عدن، أو لبعض السادة الأموات هناك في حضرموت أو غيرهم، أو لبعض الأولياء الآخرين، هذا نذر باطل، وشرك بالله ، ولا وفاء له بل هو باطل. نعم.","link":"https://binbaz.org.sa/fatwas/5897/حكم-من-نذرت-ذبح-كبش-كل-عام-وعجزت-عن-الوفاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_087/08701.mp3","categories":["الأيمان والنذور"]},{"id":8108,"question":"تحرير الرقبة سماحة الشيخ أصبح مكان إشكال لبعض السادة المستمعين فهم لا يعلمون معناه ربما لأنهم لم يروا ذلك على الطبيعة، أخونا مثلاً يسأل ويقول: أسأل عن تحرير الرقبة حيث أننا نسمع كثيراً من الكفارات تقول: تحرير رقبة ولا ندري ما هي الرقبة، هل هو إنسان محكوم عليه بالقتل ثم يعفى عنه أو أنه من الحيوانات، أفيدونا أفادكم الله؟","title":"معنى تحرير رقبة","answer":"الجواب: تحرير الرقبة يراد به: عتق المملوك من الذكور والإناث، وقد شرع الله سبحانه وتعالى لعباده إذا جاهدوا أعداء الإسلام وغلبوهم أن تكون ذرياتهم ونساؤهم أرقاء مماليك للمسلمين يستخدمونهم وينتفعون بهم ويبيعونهم ويتصرفون فيهم، وكذلك الأسرى إذا أسروا منهم أسرى فولي الأمر بالخيار إن شاء قتل الأسرى، وإن شاء أعتق الأسرى إذا رأى المصلحة في ذلك وأطلقهم، وإن شاء استرقهم وجعلهم غنيمة، وإن شاء قتلهم إذا رأى المصلحة في القتل، وإن شاء فادى بهم إذا كان عند الكفار أسرى للمسلمين يفادي بذلك، فيأخذ من المشركين أسرى من المسلمين ويعطيهم أسرى، أو يأخذ منهم أموالاً لفك أسراهم كما فعل النبي ﷺيوم بدر، فقد كان عند النبي ﷺ أسرى قتل بعضهم وفادى ببعضهم، وكان من جملتهم النضر بن الحارث و عقبة بن أبي معيط فقتلهما بعد انتهاء الوقعة، والبقية فادى بهم وأمر المسلمين أن يفادوا بهم ويأخذوا الفداء من المشركين في مقابل أسراهم.\nومنهم من عفا عنه عليه الصلاة والسلام، فالعفو جائز لولي الأمر إذا رأى المصلحة وجائز له القتل إذا رأى المصلحة، وجائز له الاسترقاق إذا رأى المصلحة، وجائز له أخذ الفداء، كما قال عز وجل: فَإِمَّا مَنًّا بَعْدُ وَإِمَّا فِدَاءً حَتَّى تَضَعَ الْحَرْبُ أَوْزَارَهَا [محمد:4].\nفهذه هي الرقاب: المملوك الذي يملكه المسلمون عند غلبتهم لعدوهم وقهرهم لعدوهم الكافر فيأخذوا منه ذرية، يعني:صبية صغاراً لم يبلغوا يأخذونهم أو نساء، فهؤلاء يكونون أرقاء للمسلمين مماليك للمسلمين يقسمون في الغنيمة يقسمون بين الغانمين كل يأتيه نصيبه من هؤلاء الذرية وهؤلاء النساء، وهكذا الأسرى الكبار المقاتلون إذا استرقهم ولي الأمر وجعلهم غنيمة كذلك. فإذا كان عند المسلم الغانم واحد أو اثنان أو ثلاثة فهو بعد ذلك بالخيار، إن شاء استخدمه في حاجاته، وإن شاء باعه وانتفع بثمنه، وإن شاء أعتقه لله عز وجل تبرعاً وتطوعاً، أو أعتقه في الكفارة مثل كفارة القتل.. كفارة الوطء في رمضان.. كفارة الظهار.. كفارة اليمين، وإن تركه يستعمله صار مملوكاً له يورث بعده إذا مات كسائر أمواله.\nهذا معنى تحرير رقبة، يعني: عتق الرقبة التي ملكتها أيها المسلم ملكتها بالحرب التي جرت بينك وبين عدوك حتى صار أولادهم ونساؤهم لكم غنيمة فتقسمها المسلمون وصارت بينهم وصار لكل مسلم نصيبه من هذه الغنيمة مملوكاً له يتصرف فيه بالبيع وغيره، فإذا أعتقه لله تطوعاً أو عن كفارة فله أجره في ذلك، وبهذا تؤدى الكفارة ويسمى العتق تحرير، يسمى عتقه تحرير رقبة، فإذا قال: أعتقت فلاناً لله، فهذا معناه تحرير رقبة سواء كان عن كفارة أو تطوعاً وتبرعاً، يقول النبي ﷺ: أي امرء مسلم أعتق امرءاً مسلماً أعتق الله بكل عضو منه عضواً من النار فعتق الرقاب له شأن عظيم وفضل كبير في الشرع المطهر، ولعلك -أيها السائل- بهذا عرفت معنى عتق الرقبة وتحريرها.","link":"https://binbaz.org.sa/fatwas/5904/معنى-تحرير-رقبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_102/10203.mp3","categories":["الجماع في نهار رمضان","الأيمان والنذور","الجنايات والحدود"]},{"id":8117,"question":"شيخ عبد العزيز أولى رسائل هذه الحلقة وصلت إلى البرنامج من الأخ عيسى حسن غازي من جدة أو عازب: أخونا يقول: ابعث لفضيلتكم برسالتي هذه والتي أرجو التكرم بعرض ما فيها من أسئلة واستفسارات لأحد أصحاب الفضيلة العلماء الأجلاء أعزهم الله.إنني شاب أبلغ من العمر السادسة والعشرين عاما، قدر الله علي بحصول غمامة من غمامات الدهر التي تعترض كل شاب وكل مسلم متزوج ولي ثلاثة من الأبناء يعيشون تحت كنف رعايتي بعد الله، ووالدتي طاعنة في السن أو، وقد حجبتني الأقدار الإلهية عن رؤيتهم ما يقارب من سنة وستة أشهر، أنذرت لله أنه عند عودتي لمنزلي وأطفالي الذين أصبحوا فترة غيابي تحت برارة المتصدقين أن أصوم لله تعالى ستة أيام حمداً وشكراً لله، وأذبح اثنتين من الذبائح لله تعالى، وأزور مكة والمدينة أنا ووالدي، وأقوم بحمل والدتي على أكتافي أطوف بها وأسعى، وعندما انجلت تلك الغمامة ولسوء حالتي المادية وحالة أسرتي قمت بذبح ذبيحة واحدة ولم أستطع إحضار الأخرى، كذلك لم أستطع الذهاب بأسرتي ووالدتي لمكة والمدينة وفاءً بنذري وذلك لسوء حالتي المادية حتى الصيام لم أستطع القيام به، وخوفاً من وقوعي في الذنب والوزر بعثت برسالتي هذه عسى ولعلي أجد أبسط الطرق التي تجعلني أتقرب إلى الله وأوفي بها ما أنذرت، علماً أنني شاب محافظ على أداء الفرائض والنوافل حتى الليل والضحى أبتهل إلى العلي القدير أن يوفقكم للإجابة رعاكم الله؟","title":"حكم من لم يستطع الوفاء بنذره","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:\nفالحمد لله الذي يسر لك الاجتماع بوالديك وأولادك، ونسأله جل وعلا أن يصلح حالكم جميعاً، وأن يعينك على ما يحبه ويرضاه.\nأما النذر فالواجب عليك هو الوفاء به حسب الطاقة، وقد مدح الله المؤمنين الموفين بالنذر في قوله جل وعلا: يُوفُونَ بِالنَّذْرِ وَيَخَافُونَ يَوْمًا كَانَ شَرُّهُ مُسْتَطِيرًا [الإنسان:7] وقال النبي عليه الصلاة والسلام: من نذر أن يطيع الله فليطعه، ومن نذر أن يعصي الله فلا يعصه خرجه الإمام البخاري في صحيحه عن عائشة رضي الله عنها.\nفعليك أن تؤدي الذبيحة الثانية عند القدرة لا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا [البقرة:286] متى استطعت وتيسر لك ما تشتري به الذبيحة الثانية فافعل واذبحها وتصدق بها على الفقراء إلا أن تكون نويت أن تأكلها مع أهلك أنت على نيتك؛ لقول النبي ﷺ: إنما الأعمال بالنيات وإنما لكل امرئ ما نوى.\nأما إن كنت نذرت الذبح ولم تقصد أن تأكلها مع أهلك فإنك تعطيها الفقراء.\nوعليك أن تصوم متى تيسر لك ذلك ستة أيام؛ لأنها طاعة لله، فعليك أن تصومها متى استطعت ولو متفرقة، إلا إن كنت نويت أن تصومها متتابعة فأنت على نيتك، فالأعمال بالنيات، إن كنت نويتها متتابعة صمها متتابعة وفاءً بنذرك ونيتك، أما إن كنت لم تنو التتابع فإنك تصومها ولو متفرقة ولا حرج في ذلك.\nوعليك أيضاً أن تحج بوالديك، تذهب بوالديك إلى مكة وإلى المدينة كما نذرت إن كنت أردت العمرة، فالعمرة وإن كنت أردت حجاً فحجا، على حسب نيتك في ذهابك إلى مكة كنت أردت بهم عمرة العمرة تكفي، فإن كنت أردت حجاً فعليك أن تحج بهم متى استطعت لا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا [البقرة:286] ويقول سبحانه: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] وعليك أن تذهب بهم إلى المدينة أيضاً؛ لأن شد الرحال إلى المدينة للصلاة في مسجد النبي ﷺ سنة وقربة، وإذا زرت المدينة تسلم على الرسول ﷺ وعلى صاحبيه هذا هو الأفضل لك، فإن زيارة قبره صلى الله عليه وسلم وقبر صاحبيه لمن كان في المدينة مشروع، مشروعة، إنما الذي ينهى عنه شد الرحل من أجل الزيارة فقط، أما شد الرحل للمسجد والزيارة داخلة في ذلك فلا بأس، فتسلم على النبي ﷺ وعلى صاحبيه رضي الله عنهما، أما النساء فلا يزرن القبور، ولكن أنت وأبوك ومن معكم من الرجال.\nأما النساء فلا يزرن القبور ولكن يصلين في مسجد النبي صلى الله عليه وسلم ويصلين عليه في محلهن في المسجد وفي البيوت وفي الطريق صلى الله وسلم عليه وعلى آله وأصحابه.\nويشرع لكم -أيها الرجال- أيضا أنت ومن معك من الرجال زيارة البقيع وزيارة الشهداء، كل هذا مشروع للرجال زيارة القبور، ويستحب لك أيضاً ومن معك من النساء والرجال زيارة مسجد قباء والصلاة فيه؛ لأنه مسجد فاضل تستحب الزيارة لمن كان في المدينة.\nأما حملك لأمك أو لأبويك أن تحج بهما وتحملهما فلا، ليس عليك ذلك ولكن تطوف أمك بنفسها، ويطوف أبوك بنفسه، ويسعى كل منهما بنفسه، أو في عربانة إن كان يشق عليه ذلك فالحمد لله الأمر واسع، أما حملهما فليس عليك حملهما بل تكفر عن نذرك هذا بكفارة يمين عن حملهما، عليك كفارة يمين عن حملهما وهي إطعام عشرة مساكين أو كسوتهم، عشرة تعطي كل واحد نصف صاع من التمر أو البر أو الأرز، أو تكسو كل واحد كسوة تجزئه في الصلاة كالقميص أو إزار ورداء ويكفي، وليس عليك حملهما بل يطوفان بأنفسهما ويسعيان بأنفسهما، وإذا عجزا يطاف بهما ويسعى بهما والحمد لله.\nونسأل الله أن يعينك على الوفاء وأن يتقبل منا ومنك، ونوصيك بعدم النذر نوصيك في المستقبل أن لا تنذر، لأن الرسول عليه السلام قال: لا تنذروا فإن النذر لا يرد من قدر الله شيئاً، وإنما يستخرج به من البخيل فنوصيك في المستقبل أن لا تنذر أبداً ولو حصل لك نعم تشكر الله وتطيع الله وتحمده ولكن لا حاجه إلى النذر.\nوقلت في كلامك (ولكن حجبتني الأقدار)، فالأفضل أن تقول في مثل هذا: ولكن قدر الله كذا كذا؛ لأن الأقدار ليس تصرف التصرف لله وحده، فتقول في مثل هذا قدر الله علي كذا قدر الله كذا، إني لا أستطيع كذا.. أني أتأخر عن أولادي كذا، تعبر بنسبة الأمر إلى الله سبحانه وتعالى، قدر الله علي كذا أو أراد الله كذا، هذا هو المشروع.\nرزقنا الله وإياك العلم النافع والعمل الصالح. نعم.","link":"https://binbaz.org.sa/fatwas/5915/حكم-من-لم-يستطع-الوفاء-بنذره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_103/10301.mp3","categories":["الأيمان والنذور"]},{"id":8118,"question":"سماحة الشيخ! يكثر الشكوى من حالته الاقتصادية كما يقول؟","title":"بذل الأسباب في طلب الرزق","answer":"الجواب: الحمد لله، عليك -يا أخي- أن تصبر وأن تأخذ بالأسباب والحمد لله ربما يكون هذا خيراً لك، جاء في بعض الآثار الإلهية يقول الرب : إن من عبادي من لا يصلحه إلا الفقر ولو أغنيته لأفسده ذلك فعليك أن تأخذ بالأسباب والله جل وعلا مسبب الأسباب، فعليك أن تسعى في طلب الرزق بأي عمل مباح تفعله من تجارة وبيع وشراء، أو العمل عند من يتيسر عنده العمل المباح، أو الوظيفة إذا تيسرت المباحة الحمد لله تفعل الأسباب وتستعين بالله وتطلبه الرزق من عنده جل وعلا، ولا مانع أن تأخذ الزكاة من أهل الزكاة إذا عجزت ولم يتيسر لك ما يقوم بحالك لا بأس أن تأخذ الزكاة ولا مانع من صرف الزكاة فيك عند عجزك عما يقوم بحالك، والله المستعان وهو ولي التوفيق سبحانه.\nالمقدم: بارك الله فيكم، إذاً ما نذر من النذر الذبائح والحالة هذه تسقط عليه وحالته الاقتصادية سماحة الشيخ؟\nالجواب: لا، تبقى دين معلق، ديناً معلقاً كسائر الديون.\nالمقدم: وإذا لم يستطع فلا محذور؟\nالشيخ: لا شيء عليه، إذا مات ولم يستطع، إن يسر الله في التركة شيء أوفى عنه الورثة، وإن كان ما وراه تركة سقطت. نعم.","link":"https://binbaz.org.sa/fatwas/5917/بذل-الاسباب-في-طلب-الرزق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_103/10302.mp3","categories":["الأيمان والنذور"]},{"id":8134,"question":"سؤاله الأخير يقول: ما هي كفارة اليمين وفقكم الله؟","title":"توضيح كيفية كفارة اليمين","answer":"الجواب: كفارة اليمين مثل ما قال الله جل وعلا: فَكَفَّارَتُهُ إِطْعَامُ عَشَرَةِ مَسَاكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍ [المائدة:89] هذه كفارة اليمين، إما عشرة مساكين يطعمهم يعشيهم أو يغديهم، أو يعطيهم من قوت البلد نصف الصاع من تمر من رز من غيره من قوت البلد، أو يكسوهم كسوة، أو يعتق رقبة ذكر أو أنثى، هذه كفارة اليمين، من حلف مثلاً إنه لا يكلم فلان ثم كلمه أو حلف إنه ما يبيت عند فلان وبات عنده أو لا يجيب ضيافته ثم أجابه يكفر كفارة يمين يطعم عشرة مساكين نصف صاع كل واحد، كيلو ونصف، وإن أعطاه زيادة فلا بأس، أو يكسوه، أو يعشيه أو يغديه، أو يعتق رقبة، فإن عجز عن هذه كلها صام ثلاثة أيام، إذا عجز عن ......... فقير ما يقدر يصوم ثلاثة أيام؛ لقوله سبحانه: فَمَنْ لَمْ يَجِدْ فَصِيَامُ ثَلاثَةِ أَيَّامٍ [المائدة:89] والأولى أن تكون متتابعة كما قرأ ابن مسعود رضي الله عنه: ....... متتابعة ، هذا هو الذي ينبغي. نعم.","link":"https://binbaz.org.sa/fatwas/5935/توضيح-كيفية-كفارة-اليمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_088/08806.mp3","categories":["الأيمان والنذور"]},{"id":8249,"question":"أسئلتها بسيطة لكن رجتنا ألا نهمل رسالتها سماحة الشيخ، تقول أيضاً: إن زوجي حلف بالطلاق إذا لم ترجع أخته الدينار لصاحبه ولكن أخته لم ترجعه وأخذته، وفي المرة الثانية كان الأمر كذلك، فماذا يكون الحكم؟","title":"حكم من حلف بالطلاق للتشديد والتخويف","answer":"الجواب: هذا فيه تفصيل: إن كان قصد بذلك إيقاع الطلاق إن لم ترجع الدينار وقع طلقة على زوجته بذلك وله مراجعتها ما دامت في العدة إذا كان ليس قبل ذلك طلقتان، وإن كان أراد التشديد عليها أو تخويفها ولا يريد إيقاع الطلاق فلم تفعل فعليه كفارة يمين؛ لأن هذا في حكم اليمين وهي إطعام عشرة مساكين لكل مسكين نصف صاع من قوت البلد، يعني: كيلو ونص من قوت البلد من التمر أو الأرز أو غيرهما أو كسوتهم كسوة تجزئهم الصلاة كالقميص لكل واحد، أو عتق رقبة مؤمنة، فإن عجز وكان فقيراً لا يستطيع صام ثلاثة أيام ويكفي ذلك.","link":"https://binbaz.org.sa/fatwas/6064/حكم-من-حلف-بالطلاق-للتشديد-والتخويف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/%D8%A7%D9%84%D8%AD%D9%84%D9%81%20%D8%A8%D8%A7%D9%84%D8%B7%D9%84%D8%A7%D9%82%20%D8%A7%D9%84%D9%85%D8%B9%D9%84%D9%82.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":8326,"question":"وهذه رسالة من المرسل (محمود . ت. س) مصري يعمل بالمملكة يقول في رسالته: لقد حلفت على زوجتي بأن تكون طالق إذا فعلت كذا، وكان بنية التهديد، مع العلم أنه حدث مني ثلاث مرات، وكل ما وقع في الحالات الثلاث عاشرتها بعد الحلف من غير أن أسأل عن ذلك؛ لأنني لم أقصد بأنها يمين صحيح أو يمين طلاق، بل كانت يمين بنية التهديد، فوقع مني يمين رابع وكان بنية الطلاق، فأريد أن تفتوني في الحكم؟","title":"حلف على زوجته بالطلاق للتهديد فما حكمه؟","answer":"الجواب: أما الأيمان الثلاث الأولى التي بقصد التهديد وليس بقصد إيقاع الطلاق ولكن لتخويفها وتهديدها، فهذه الثلاث الصواب فيها أنها في حكم اليمين، وعلى السائل كفارة اليمين في كل واحدة، وهي إطعام عشرة مساكين أو كسوتهم أو عتق رقبة، والكسوة: إزار ورداء أو قميص، أما الإطعام: فهو نصف صاع من التمر أو من الرز أو غير ذلك من قوت البلد، هذا هو الإطعام، وإن غداهم أو عشاهم كفى ذلك، ولا يقع الطلاق بذلك في أصح قولي العلماء، وذهب الجمهور إلى أنه يقع الطلاق بهذه اليمين إذا قال: إن كلمت فلان فأنت طالق، أو إن ذهبت إلى بيت أهلك فأنت طالق، أو إن فعلت شيئاً آخر فأنت طالق، قصده التهديد، فالأكثرون على أنه يقع ولا تنفعه هذه النية، ولكن الصحيح الذي عليه المحققون من أهل العلم أن هذا في حكم اليمين، ولا يكون طلاقاً بل عليه كفارة اليمين، وهذا هو الذي نفتي وهو الأصح، وهو الذي أفتى به شيخ الإسلام ابن تيمية رحمه الله والعلامة ابن القيم، وهو ظاهر ما نقل عن جماعة من السلف الصالح من التابعين، وهو ظاهر ما نقل عن ابن عمر وعن صفية زوجته بنت أبي عبيد، وعن جماعة فيمن حلفت بالعتق والصدقة بمالها وعتق عبيدها على أنه لا يفعل كذا فلم يفعل، قالوا لها: عليك كفارة يمين؛ لأنها إنما قصدت إلزامه لم تقصد العتق ولا الصدقة، وإنما أرادت إلزام هذا الشخص بأن يطلق زوجته ... فقالوا: عليك بهذا كفارة يمين، ولا يلزمك أن يكون مالك صدقة ولا عتق الرقاب؛ لأنها لم ترد ذلك وإنما أرادت إلزامه والتأكيد عليه، فإذا كان هذا في المحبوب إلى الله من الصدقة والعتق وهما محبوبان إلى الله، فالطلاق المبغوض إلى الله من باب أولى أنه لا يقع مع التهديد وقصد التأكيد والتشديد والتخويف لا بقصد إيقاع الطلاق هذا هو الصواب.\nأما الرابعة التي علقها على شرط يريد إيقاع الطلاق فهي تقع، فإذا قال: إن خرجت بغير إذني فأنت طالق، وقصده إيقاع الطلاق وقع إذا خرجت، أو قال: إن كلمت فلاناً وقصده إيقاع الطلاق وقع على نيته، الأعمال بالنيات. نعم.\nالمقدم: جزاكم الله خير، بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6142/حلف-على-زوجته-بالطلاق-للتهديد-فما-حكمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_202/20207.mp3","categories":["الطلاق","الأيمان والنذور"]},{"id":8334,"question":"أختنا سنعود إلى رسالتها إن شاء الله في حلقة قادمة؛ وذلك لنتيح الفرصة أمام عدد من السادة المستمعين كيما تطرح أسئلتهم، فننتقل إلى رسالة وصلت إلى البرنامج من الخبر، وباعثتها إحدى الأخوات من هناك، تقول السائلة (ر. ع. د) أختنا رسالتها مطولة أستأذن سماحة الشيخ في أن أقرأها كما وردت تقول: الحمد لله رب العالمين، والصلاة والسلام على نبينا محمد ﷺ أما بعد:زوجني أبي مرغمة علي برجل يكبرني بخمسة وعشرين عاماً، ولقد مضى على زواجي منه ربع قرن وأنجبت منه أربع بنات وولداً، ولقد كان على علم في البداية بأنني لا أريد أن أرتبط به، وأرسلت له عن طريق البريد رسائل أخبره بذلك، وبأنني مرغمة على الزواج منه ولا أريد له ولي التعاسة، فهو كان متزوجاً من قبلي ابنة عمه وأنجب منها وطلقها، ولا أريد أن يكون مصيري كهذا، تزوجته وعشت معه ثلاث سنوات لا أريد أن أربط نفسي به، وقدر الله وما شاء فعل، وأنجبت منه أربع بنات وولد، وكنت أعيش معه في بيت واحد، والعلاقة بيننا فاترة، لقد عشت معه عشر سنوات لا علاقة بيننا ولم يبين أو يعتذر ولم أسأله، عشنا أغراباً عن بعضنا، وكرست وقتي لبناتي وابني، وكان كل ما يفعل يؤلمني، المهم والأهم من ذلك في يوم من الأيام خرج من المنزل وغاب فانزعجت أنا وأطفالي لتأخره، وبعد البحث علمت أنه سافر وتركنا لا حول لنا ولا قوة، فحلفت وأقسمت أنني لم ولن أتعرف عليه بعد ذلك، وبرغم تحملي كل ذلك يتركني أنا الضعيفة ذات الجناح المكسور وبناتي وابني ويذهب دون أن يخبرني، فحلفت حتى إذا مات لن أعتد عليه، وبعد فترة من الزمن حوالي خمسة عشر يوماً علمت أنه في إحدى البلدان، وقد اتصل بأهلي وأخبرهم بأنني يجب أن أعود إليه فرفضت وبقيت في مكاني، وتوفي هو بعد ذلك بفترة، ولكنني لم أدخل العدة؛ أولاً: لأنني حلفت.ثانياً: لعدم العلاقة التي تربطنا به.رابعاً: تركنا. فما الكفارة التي تجب علي؟ وما عقابي، والله شهيد على ما أقول وأستغفر الله العظيم، ولا حول ولا قوة إلا بالله. هذه رسالتها بطولها سماحة الشيخ؟","title":"حكم من حلفت ألا تسأل عن زوجها ولا تعتد إن مات","answer":"الجواب: أما الزواج فقد انتهى والحمد لله، وأنت قد أحسنت في مراعاة خاطر أبويك وأحببت إرضاءهما وتزوجت فالحمد لله.\nأما يمينك أن لا تسألي عنه وأن لا تعرفي عليه فعليك عنها كفارة يمين إذا كنت سألت وتعرفت عنه، عليك كفارة يمين وهي: إطعام عشرة مساكين أو كسوتهم، عشرة؛ كل واحد يعطى نصف الصاع من قوت البلد من تمر أو غيره، أو كسوة يكسى كسوة تجزئه في الصلاة. وأما كونك حلفت أن لا تعتدي عليه إذا مات فهذا غلط منك، ولا يجوز لك ذلك، والواجب عليك العدة فإذا كانت العدة قد مضت ولم تعتدي عليه فعليك التوبة والاستغفار عما جرى منك من التقصير، ولو كنت فعلت العدة عنه لكان هو الواجب وعليك كفارة يمين أيضاً عن يمينك أنك لا تعتدي مثل كفارة الأولى، وإذا كان موته قد مضى بعده أربعة أشهر وعشر فقد انتهيت من العدة وعليك التوبة والاستغفار؛ لعدم تعاطيك ما شرع الله في العدة من ترك الزينة والطيب والحلي ونحو ذلك، وقد مضت العدة والحمد لله وليس عليك أن تعيديها، بل مضت، قد مضت العدة، أما إن كان بقي منها شيء لن تكمل المدة أربعة أشهر وعشر فعليك أن تعتدي الباقي منها، تتجنبي الملابس الجميلة والطيب والحلي والكحل ونحو ذلك حتى تتم العدة، وهي أربعة أشهر وعشر، نسأل الله أن يعفو عنا وعنك وعن كل مسلم.","link":"https://binbaz.org.sa/fatwas/6149/حكم-من-حلفت-الا-تسال-عن-زوجها-ولا-تعتد-ان-مات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_111/11106.mp3","categories":["الأيمان والنذور"]},{"id":8422,"question":"رسالة وصلت إلى البرنامج من المملكة الأردنية الشقيقة وباعثها أخونا صبري محمد ضحى فيما يبدو مصري، أخونا بدأ رسالته بقوله: أحييكم بتحية الإسلام التي في أولها: السلام عليكم، وفي آخرها: الرحمة والبركات من عند المولى . سلام الله عليكم ورحمته وبركاته وحسناته ومرضاته، وبعد: نحن متابعون برنامجكم العظيم، فنفعنا الله بعلمكم، وجزاكم الله خيراً، وبارك لنا فيكم، وإني أتوجه إليكم بسؤالين، وفقنا الله وإياكم لما فيه الخير، السؤال الأول: ما حكم الإسلام في يمين الطلاق أمام الزوجة أو غيابها؟","title":"حكم يمين الطلاق","answer":"الجواب: وعليكم السلام ورحمة الله وبركاته، نعم، الطلاق له صور كثيرة، فإذا كان الطلاق معلقاً على وجه اليمين كأن يقول لها مشافهةً: إذا كلمت فلاناً فأنت طالق، أو إذا خرجت إلى بيت فلان فأنت طالق، أو ما أشبه ذلك مما يقصد منه الحث أو المنع أو التصديق أو التكذيب، هذا الطلاق يقال له: يمين؛ لأنه في معنى اليمين؛ ولأن مقصوده مقصود اليمين، فإذا كان قصد المطلق منعها من شيء، أو حملها عليه، أو التصديق أو التكذيب، فهذا عند المحققين من أهل العلم في حكم اليمين، وذهب الأكثرون إلى أنه يقع، له حكم الشرط حكم المعلق، ولكن الصواب الذي عليه جمع من أهل التحقيق أنه في حكم اليمين، فعليه كفارتها إذا لم يقصد إيقاعه، وإنما قصد منعاً، أو حثاً، أو تصديقاً، أو تكذيباً؛ فإنه يكون له حكم اليمين في عدم الوقوع والاكتفاء بالكفارة، فإذا قال لها: إن كلمت فلاناً فأنت طالق، قصده أن يمنعها من ذلك، ليس قصده إيقاع الطلاق، إنما قصده منعها من تكليمه، فإنها إذا كلمته يكون على زوجها كفارة اليمين، ولا يقع الطلاق في أصح قولي العلماء.\nوهكذا لو قال لزوجته: إن خرجت من بيتك اليوم أو غداً أو قصده دائماً بغير إذني فأنت طالق، ومقصوده منعها من الخروج، وليس قصده إيقاع الطلاق؛ فإنها بذلك إذا خرجت بغير إذنه يكون عليه كفارة، ولا يقع الطلاق؛ لأنه لم يقصد إيقاعه وإنما قصد المنع، أما إن قصد إيقاع الطلاق فإنه يقع متى خرجت. نعم.","link":"https://binbaz.org.sa/fatwas/6306/حكم-يمين-الطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_118/11813.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":8428,"question":"أنا مواطن مصري مقيم في الرياض، وحصل أن أصيبت زوجتي بمرض ولزمت السرير، فنذرت نذراً لوجه الله إذا صحت زوجتي من هذا المرض أن أذبح خروف، وأعمل به احتفال للأهل والجيران، على أن يكون بمثابة صدقة لوجه الله، وعندما عدت إلى مصر وجدت زوجتي قد صحت من مرضها، فقررت أن أفي بنذري، لكن صادف أن توفي أحد الجيران مما تعذر علي عمل النذر، فعدت إلى السعودية، والآن أسأل: هل يمكن أن أبعث بقيمة الخروف لأخي؛ لكي ينوب عني ويفي بالنذر، أم أنه لا يجوز أن ينوب عني أفيدوني أفادكم الله، وصاحب الرسالة هو أخونا عطية جابر محمد ....... فيما يبدو تفضل؟","title":"حكم التوكيل في الوفاء بالنذر","answer":"الجواب: نعم لك أن ترسل القيمة لأخيك، أو تعمده بأن يشتري خروف نيابة عنك تبرعاً منه، أو قرضاً عليك، ثم يذبح ويتصدق، أو يدعو من أردتم من أقاربكم وجيرانكم لهذا الخير.\nيقول النبي ﷺ: من نذر أن يطيع الله فليطعه، ومن نذر أن يعصي الله فلا يعصه، والله سبحانه مدح الموفي بالنذر فقال  في سورة الإنسان: يُوفُونَ بِالنَّذْرِ وَيَخَافُونَ يَوْمًا كَانَ شَرُّهُ مُسْتَطِيرًا [الإنسان:7]، مدح المتقين الأبرار بهذا العمل.\nفالواجب عليك أن توفي بالنذر، وإذا ذبحته هناك بواسطة أخيك أو غير أخيك من الوكلاء عنك فلا بأس. نعم.","link":"https://binbaz.org.sa/fatwas/6312/حكم-التوكيل-في-الوفاء-بالنذر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_119/11905.mp3","categories":["الأيمان والنذور"]},{"id":8461,"question":"أخونا عبد الله سعود آل مرشد من حوطة بني تميم أسفل الباطن يقول: إذا حلف الرجل ليتم أمراً ما، وهو في حالة قد لا يملك شعوره هل يلزمه التكفير أم لا؟ وما هو لو تكرمتم؟","title":"حكم الحنث في اليمين","answer":"الجواب: اليمين إذا حلف الإنسان على شيء يفعله فلم يفعله لزمته اليمين، فإذا قال: والله لأكلمن فلاناً، والله لأزورنه، والله لأصلي كذا وكذا وما أشبه ذلك، عليه أن يفعل أو يكفر عن يمينه، إذا كان حلف هذا الأمر وهو يعي يعقل.\nأما إذا كان اشتد ... مع الغضب حتى صار ليس في وعيه، فاليمين لا تنعقد؛ لأن الوعي لا بد منه لا بد أن يعقل ما يقول ويفهم ما يقول، فإذا اشتد معه الغضب شدة تجعله لا يعقل ما يقول، ولا يضبط ما يقول، هذا لا يعتبر يمينه شيء. نعم.","link":"https://binbaz.org.sa/fatwas/6467/حكم-الحنث-في-اليمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_123/12308.mp3","categories":["الأيمان والنذور"]},{"id":8463,"question":"من كفارة اليمين إطعام عشرة مساكين، هل يجوز إطعام واحد منهم الآن والآخر بعد أسبوع؛ لأنه قد لا تجد عشرة مساكين دفعة واحدة وهل إذا أطعمت واحداً عشر مرات كأني أطعمت عشرة مساكين؟","title":"كيفية الإطعام في كفارة اليمين","answer":"الجواب: يجب التماس العشرة وإذا أطعمت واحداً وكررت ذلك لا، لا يكفي، لا بد من عشرة كما قال الله ، فـ إِطْعَامُ عَشَرَةِ مَسَاكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ [المائدة:89] لا بد من التماس العشرة ولو تعددت الأيام، ولو .. أطعم هذا في يوم، والآخر في يوم ثاني، والآخر في يوم ثالث، لكن تجب المبادرة حسب الطاقة، ولو كان إطعامه متفرقاً في أيام، لا بأس، إنما عليك أن تجتهد وتلتمس العشرة، وتبادر بإخراج الكفارة. نعم.","link":"https://binbaz.org.sa/fatwas/6469/كيفية-الاطعام-في-كفارة-اليمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_123/12310.mp3","categories":["الأيمان والنذور"]},{"id":8510,"question":"يقول: لقد أقسمت بالعظيم على إحداهن ألا تخرج من البيت، وبعد سفري حصل حادث وفاة لأحد أقاربها وخرجت من البيت، وأرسلت إلي خطاب عرفتني بذلك، فماذا أفعل؟","title":"حكم من حلف على زوجته ألا تخرج من البيت فخرجت","answer":"الجواب: عليك كفارة يمين، ما دمت حلفت عليها ألا تخرج ثم خرجت؛ عليك أن تكفر كفارة يمين، إطعام عشرة مساكين، كل مسكين يعطى نصف الصاع، كيلو ونص تقريباً من قوت البلد من تمر أو شعير أو أرز أو غير ذلك من قوت البلد يكفي عشرة، أو تكسوهم كسوة، كل مسكين يعطى قميصاً أو إزار ورداء، هذا هو الواجب عليك في هذه اليمين. نعم.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6593/حكم-من-حلف-على-زوجته-الا-تخرج-من-البيت-فخرجت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_203/20310.mp3","categories":["الأيمان والنذور"]},{"id":8531,"question":"أخيراً يقول الأخ (س. م. ت) من الرياض في رسالته: حصل خلاف بيني وبين إخوتي، فأقسمت بالله عدد ما في الأرض وعدد ما في السماء وكررت ذلك، وأنا الآن أريد أن أصالحهم وأرجع معهم، ولا أدري هل يعتبر كل هذا القسم، هل يكفي في كل هذا القسم كفارة واحدة أم لكل قسم كفارة؟","title":"كفارة اليمين المتكررة على شيء واحد","answer":"الجواب: تراجع المفتي في بلدك، تراجع المفتي أو المحكمة في بلدك وينظرون في أمرك مع ولي المرأة، مع المرأة ووليها.\nالمقدم: هذا يا شيخ قسم خلاف فقط بينه وبين إخوانه فأقسم بالله عدد ما في الأرض وعدد ما في السماء ألا يكلمهم يعني: ليس طلاقاً. نعم.\nالشيخ: ما قال: طلقت؟\nالمقدم: لا.\nالشيخ: إيش يقول.. أعد؟\nالمقدم: .. يقول: اختلفت أنا وإخواني وغضبت منهم، فأقسمت بالله عدد ما في الأرض وعدد ما في السماء، وكررت ذلك أن لا أكلمهم ولا أدفع لهم مالاً، ولكن الآن أنا ندمت وأريد أن أعود لهم فلا أدري كيف أكفر هذا القسم؟\nالجواب: عليك -يا أخي- كفارة يمين فقط ولو كررته مائة مرة؛ لأنه قسم على شيء واحد وهو عدم تكليمهم، فعليك أن تكفر عن ذلك كفارة واحدة، وهي إطعام عشرة مساكين أو كسوتهم أو عتق رقبة، فإذا أطعمت عشرة عشيتهم أو غديتهم أو أعطيت كل واحد نصف صاع من التمر أو من الأرز كفى ذلك، وإن كسوتهم كفى ذلك؛ لأن مقصودك منع الكلام معهم، فإذا فعلت هذا كفى، سواء فعلته قبل الكلام أو بعد الكلام. (لا أكلمهم) وايش بعد لا أكلمهم؟\nالمقدم: هو لا يكلمهم ولا يدفع لهم مالاً..؟\nالشيخ: كذلك إذا دفعت لهم مالك تصير كفارة ثانية، كفارة عن الكلام وكفارة عن دفع المال إذا دفعت لهم مالاً، فيصير كفارتان، كفارة عن المال وكفارة عن الكلام. نعم.\nالمقدم: لكن قوله: عدد ما في الأرض وعدد ما في السماء؟\nالشيخ: ولو ما يضر هذا، لو قال: والله ثم والله.. والله، ولو كرر، نعم، الشيء المحلوف عليه واحد.. هو الكلام وعدم المال. نعم.\nالمقدم: بارك الله فيكم، العبرة بالمحلوف عليه، نعم، جزاكم الله خير، وبارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6624/كفارة-اليمين-المتكررة-على-شيء-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_205/20515.mp3","categories":["الأيمان والنذور"]},{"id":8568,"question":"هذه رسالة وردتنا من سوريا من المرسل محمد الأحمد الفواز، يقول: عندي حاجة نافعة مفيدة لكل إنسان، وهذه الحاجة أعطيتها لأحد أقاربي فضيعها، وحلفت بالطلاق طلقة واحدة إذا وجدتها لا أعطيها لأحد، وفعلاً وجدت هذه الحاجة، وصار لها عندي خمسة عشر سنة، وكل إنسان يسألني عنها أقول: ليست موجودة احتفاظاً بكلمة الطلاق مع أنها موجودة عندي، فهل علي في ذلك إثم؟","title":"حكم من أقسم بالطلاق ألا يعطي أحداً شيئاً عنده","answer":"الجواب: هذا فيه تفصيل: فإن كانت الحاجة تنفع الناس فينبغي له أن يعيرها الناس وينفع الناس والطلاق ينظر فيه، فأما إن كانت الحاجة ليس لها أهمية بالنسبة إلى الناس، بالنسبة إلى أقاربه أو غيرهم فإن الأمر فيها سهل، وليس في حاجة إلى أن يسأل عن الطلاق، لكن الطلاق فيه تفصيل، فإن كان أراد بذلك منع نفسه من تسليم الحاجة لأحد من الناس، ولم يرد إيقاع الطلاق، وإنما أراد أن يمنع نفسه بهذا الطلاق من تسليمها للناس، فهذا عليه كفارة يمين، ويجوز له ولا حرج عليه إذا سلمها للناس ولا يقع طلاق.\nإذا كنت -أيها السائل- أردت بذلك منع نفسك من تسليم الحاجة لأحد من الناس ولم ترد إيقاع الطلاق، فإنه لا يقع طلاق بذلك وعليك كفارة يمين إذا أعطيتها أحداً من الناس.\nأما إن كنت أردت إيقاع الطلاق إن أعطيتها أحداً من الناس فإنه يقع طلقة على زوجتك إذا أعطيتها أحداً من الناس، والطلقة الواحدة لا تحرمها عليك، لك المراجعة في الحال، لك أن تراجعها في الحال، فتشهد شاهدين بأنك راجعت زوجتك فلانة، وتصح الرجعة والحمد لله، إذا أعطيتها لأحد هذه الحاجة، وأنت تريد بالطلاق إيقاع الطلاق.\nهذا إذا كانت المرأة لم تطلقها قبلها طلقتين، أما إذا كان زوجتك قد سبق لها طلقتان، فإن هذه الطلقة تحرمها عليك الطلقة الأخيرة، إذا أعطيت الحاجة لأحد من الناس وأنت مريد إيقاع الطلاق تكون هذه الطلقة هي الثالثة، وبها تحرم المرأة على زوجها حتى تنكح زوجاً غيره، نكاحاً شرعياً، نكاح رغبة لا نكاح تحليل، ويطأها الزوج الذي نكحها، لابد أن يطأها ثم يفارقها بعد هذا إما بموت أو طلاق. نعم.\nالمقدم: بارك الله فيكم\nالمقدم: لكنه يسأل في آخر الرسالة أو ذكر أنه يكذب إذا سأله أحد عن هذه الحاجة، قال: ليست موجودة عندي وهي عنده خوفاً من وقوع الطلاق؟\nالشيخ: هذا غلط، والواجب عليه في هذا التوبة إلى الله ، فإن المؤمن ليس له أن يكذب، وإذا كان هناك حاجة لعدم بيان وجودها فيعرض بشيء، ليست موجودة، يعني: في المكان المعين الذي هي فيه، أو ليست موجودة في أي محل معين، يعني: ينوي مكاناً غير موجودة فيه، مثلاً: في المجلس وهي في مكان آخر في المخزن، أو ينوي ليست عندي في الدهليز، أو ليست عندي في الدكان، أو في المكتب أو ما أشبه ذلك، حتى يكون غير كاذب، يتأول في هذا حتى يكون لا يقع عليه الكذب. نعم.\nالمقدم: أحسنتم، جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6642/حكم-من-اقسم-بالطلاق-الا-يعطي-احدا-شيىا-عنده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_207/20703.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":8575,"question":"[ما هو قولكم فيمن يحلف بالطلاق]؟","title":"تفصيل قولي العلماء في الحلف بالطلاق دون قصده","answer":"الجواب: ........ أن يزور فلان، عليه الطلاق أن يكلم فلان قصده الحث، هذا كله في حكم اليمين، وعليه كفارة اليمين إذا فعل ما حلف على تركه أو ترك ما حلف على فعله عليه كفارة اليمين، وهي إطعام عشرة مساكين، أو كسوتهم، أو عتق رقبة، فمن لم يجد صام ثلاثة أيام.\nأما إن كان قصد إيقاع الطلاق، قال: عليه الطلاق ما يكلم فلاناً، عليه الطلاق ما يشتري السيارة الفلانية، وقصده أنه متى فعل وقع الطلاق فإنه يقع الطلاق، لقول النبي ﷺ: الأعمال بالنيات وإنما لكل امرئ ما نوى هذا هو الصواب من قولي العلماء.\nوذهب الأكثر إلى أنه يقع الطلاق مطلقاً ولو قصد الحث والمنع أو التصديق أو التكذيب، ولكن الصواب التفصيل، الصواب التفصيل، فإن كانت النية حثاً ومنعاً أو تصديقاً أو تكذيباً ليس قصده إيقاع الطلاق إنما قصده تخويف زوجته من أن تفعل كذا وردعها عن ذلك، أو قصده أن يمنع نفسه من كذا وليس قصده إيقاع الطلاق فهذا حكمه حكم اليمين في أصح قولي العلماء، واختار هذا القول أبو العباس شيخ الإسلام ابن تيمية رحمه الله والعلامة ابن القيم رحمه الله وجماعة من أهل العلم المحققين، نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/6659/تفصيل-قولي-العلماء-في-الحلف-بالطلاق-دون-قصده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_208/20807.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":8582,"question":"هذه رسالة وردتنا من المدرس محمد سلمان سليم الجرامين من الأردن، يدرس في الجمهورية العربية اليمنية يقول: نذرت على نفسي أن أذبح لوجه الله ذبيحتين إذا وهبني الله طفلاً، وعاش حتى الأربعين، نذرت هذا وأنا مقيم بالأردن ولكن لفظي كالتالي: يا رب! إذا وهبتني طفل وعاش فعلى أربعينه سوف أذبح لوجهك ذبيحتين، وشاءت الأقدار وسافرت إلى اليمن وقد وردتني برقية تفيد بأن زوجتي أنجبت طفلة وهي بخير، السؤال هو: هل يحق لي أن أنتظر حتى أعود من اليمن إلى الأردن ومن ثم أوفي بنذري أم أوفي به في اليمن، وما هي أفضل الطريقة لتوزيع النذر، وهل لي أن آكل من النذر أم لا؟ وهل لي أن أدعو عليه أحد، أفيدوني جزاكم الله خيراً؟","title":"وجوب البدار بالوفاء بالنذر","answer":"الجواب: الواجب البدار بالنذر؛ لأن القاعدة الشرعية (أن الواجبات يجب البدار بها)، إلا أن تكون مؤقتة بوقت، الواجب البدار بالوفاء بالنذر إذا كمل الأربعين، إذا كمل الطفل أربعين فالواجب عليك البدار بما نذرت في نفس اليمن، أما كونك تأكل أو ما تأكل فهذا يرجع إلى نيتك، إن كنت أردت أنك تأكل منها أنت وجيرانك وأقاربك تذبح الذبيحتين وتأكل أنت وجيرانك وأقاربك من ذلك، أما إن كنت ما نويت شيئاً فإنها تذبح، فإن الذبيحتين تذبح للفقراء، توزع على الفقراء والمساكين، ولا تأكل منها شيء؛ لأنك لم تنو ذلك، والأصل في النذور أنها للفقراء والمحاويج ليست للناذر، هذا هو الأصل إلا أن تكون نويت أنك تأكل منها أنت وأهل بيتك، فلك نيتك تأكل منها أنت وأهل بيتك وجيرانك وتعطي الفقراء، وينبغي لك ألا تنذر في المستقبل، الرسول صلى الله عليه وسلم نهى عن النذر قال: «إنه لا يأتي بخير، وإنما يستخرج به من البخيل» فينبغي لك ألا تنذر أبداً؛ لأن الرسول نهى عن ذلك عليه الصلاة والسلام، قال: «لا تنذروا، فإن النذر لا يرد من قدر الله شيئاً ، وإنما يتسخرج به من البخيل» .\nثانياً: وقع في كلامك وشاءت الأقدار، وهذه العبارة لا تصلح ولا يجوز أن يقال: شاءت الأقدار، ولكن يقال: شاء الله سبحانه، شاء ربي سبحانه، شاء الملك، الرب جل وعلا، شاء الرحمن، شاء ربي وما أشبه ذلك، يعني: ينسب إلى الله، المشيئة إلى الله؛ لأن الأقدار ما لها تصرف، الأقدار شيء مضى به علم الله سبحانه وتعالى. نعم.\nالمقدم: بارك الله فيكم...\nالشيخ: ذكر ذبيحتين؟\nالمقدم: نعم.\nالشيخ: ذبيحتين؟\nالمقدم: نعم.\nالشيخ: نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6671/وجوب-البدار-بالوفاء-بالنذر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_209/20910.mp3","categories":["الأيمان والنذور"]},{"id":8585,"question":"هذه رسالة وردتنا من المدرس محمد سلمان سليم الجرامين من الأردن، يدرس في الجمهورية العربية اليمنية يقول: نذرت على نفسي أن أذبح لوجه الله ذبيحتين إذا وهبني الله طفلاً، وعاش حتى الأربعين، نذرت هذا وأنا مقيم بالأردن ولكن لفظي كالتالي: يا رب! إذا وهبتني طفل وعاش فعلى أربعينه سوف أذبح لوجهك ذبيحتين، وشاءت الأقدار وسافرت إلى اليمن وقد وردتني برقية تفيد بأن زوجتي أنجبت طفلة وهي بخير، السؤال هو: هل يحق لي أن أنتظر حتى أعود من اليمن إلى الأردن ومن ثم أوفي بنذري أم أوفي به في اليمن، وما هي أفضل الطريقة لتوزيع النذر، وهل لي أن آكل من النذر أم لا؟ وهل لي أن أدعو عليه أحد، أفيدوني جزاكم الله خيراً؟","title":"وجوب البدار بالوفاء بالنذر","answer":"الجواب: الواجب البدار بالنذر؛ لأن القاعدة الشرعية (أن الواجبات يجب البدار بها)، إلا أن تكون مؤقتة بوقت، الواجب البدار بالوفاء بالنذر إذا كمل الأربعين، إذا كمل الطفل أربعين فالواجب عليك البدار بما نذرت في نفس اليمن، أما كونك تأكل أو ما تأكل فهذا يرجع إلى نيتك، إن كنت أردت أنك تأكل منها أنت وجيرانك وأقاربك تذبح الذبيحتين وتأكل أنت وجيرانك وأقاربك من ذلك، أما إن كنت ما نويت شيئاً فإنها تذبح، فإن الذبيحتين تذبح للفقراء، توزع على الفقراء والمساكين، ولا تأكل منها شيء؛ لأنك لم تنو ذلك، والأصل في النذور أنها للفقراء والمحاويج ليست للناذر، هذا هو الأصل إلا أن تكون نويت أنك تأكل منها أنت وأهل بيتك، فلك نيتك تأكل منها أنت وأهل بيتك وجيرانك وتعطي الفقراء، وينبغي لك ألا تنذر في المستقبل، الرسول صلى الله عليه وسلم نهى عن النذر قال: «إنه لا يأتي بخير، وإنما يستخرج به من البخيل» فينبغي لك ألا تنذر أبداً؛ لأن الرسول نهى عن ذلك عليه الصلاة والسلام، قال: «لا تنذروا، فإن النذر لا يرد من قدر الله شيئاً ، وإنما يتسخرج به من البخيل» .\nثانياً: وقع في كلامك وشاءت الأقدار، وهذه العبارة لا تصلح ولا يجوز أن يقال: شاءت الأقدار، ولكن يقال: شاء الله سبحانه، شاء ربي سبحانه، شاء الملك، الرب جل وعلا، شاء الرحمن، شاء ربي وما أشبه ذلك، يعني: ينسب إلى الله، المشيئة إلى الله؛ لأن الأقدار ما لها تصرف، الأقدار شيء مضى به علم الله سبحانه وتعالى. نعم.\nالمقدم: بارك الله فيكم...\nالشيخ: ذكر ذبيحتين؟\nالمقدم: نعم.\nالشيخ: ذبيحتين؟\nالمقدم: نعم.\nالشيخ: نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6671/وجوب-البدار-بالوفاء-بالنذر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_209/20910.mp3","categories":["الأيمان والنذور"]},{"id":8687,"question":"هذه رسالة أيضاً وردت من السائل (أ. م. ع) مدرس مصري معار بالجمهورية العربية اليمنية، يقول: في ظروف طارئة مع زوجتي وكنت في لحظة يأس وغضب بعدما حصل منها، صدر مني يمين وقلت: علي الطلاق لازم أتزوج ولو على آخر يوم من عمري، وكانت النية صريحة وأنا في لحظة غضب، ما حكم هذا اليمين؟","title":"حكم من حلف بالطلاق على امرأته أن يتزوج","answer":"الجواب: إذا كان المقصود من هذا التأكيد على نفسك أنك تتزوج وإغاظتها في ذلك، وليس قصدك إخراقها إن لم تتزوج، فإن هذا حكمه حكم اليمين، لقول النبي ﷺ: إنما الأعمال بالنيات، وإنما لكل امرئ ما نوى فإذا كنت أردت بهذا التأكيد على نفسك أنك تتزوج ولو لم ترض الزوجة وإنما أردت بهذا التأكيد ولم تقصد أنك إن لم تتزوج فهي مطلقة إنما أردت التأكيد على نفسك، فهذا حكمه حكم اليمين وعليك كفارة اليمين، وما دمت أردت ولو في آخر حياتك فالأمر في هذا فيه سعة. نعم.\nالمقدم: بارك الله فيكم، يضيف أيضاً ويقول: صدر مني يمين قبل ذلك وأنا في لحظة غضب أيضاً بسبب امتناعها عن حقوقي الشرعية، وللعلم بأنني رزقني الله منها بولدين وأربع بنات وإذا فعلت ذلك -أظنه يشير إلى الزواج- سأكون السبب في تشريد هؤلاء الأولاد وضميري لا يسمح بذلك، فهل علي كفارة أو ماذا أفعل؟\nالشيخ: إذا كان المقصود السؤال الأول وأنك طلقت أنك تتزوج ولو في آخر حياتك، فأنت بالخيار إن شئت تزوجت ووفيت بيمينك وإن شئت كفرت عن يمينك، إذا كان المقصود من هذا التأكيد على نفسك، ليس المقصود فراق زوجتك إنما المقصود في أن تؤكد على نفسك أنك تتزوج فأنت بعد هذا بالخيار، إن شئت تزوجت ولا شيء عليك وإن شئت كفرت كفارة يمين ولا شيء عليك. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6815/حكم-من-حلف-بالطلاق-على-امراته-ان-يتزوج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_215/21502.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":8721,"question":"أولى رسائل هذه الحلقة وردتنا من المرسل سيد أحمد عثمان مصري الجنسية ومقيم بالعراق محافظة صلاح الدين يقول: قبل أن أتجه إلى العراق حلفت بالطلاق بالثلاث لزوجتي، بأن لو ذهبت إلى بيت أهلك لا يكن لك ردة علي، إلا إذا كان هناك وفاة أو مرض خطير جداً، وأنا هنا لي سنة وستة أشهر فما رأي فضيلتكم إذا أرسلت لها بأن تذهب لتزورهم، وفقكم الله؟.","title":"الطلاق بالثلاث يعتبر واحدةفي أصح قولي العلماء","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن سلك سبيله واهتدى بهداه إلى يوم الدين.\nأما بعد: فهذا السؤال يختلف الجواب عنه بحسب نية المطلق، فإن كنت أيها السائل أردت بذلك منعها من الذهاب إلى أهلها ولم ترد إيقاع الطلاق، وإنما قصدت المنع، هذا له حكم اليمين، فمتى ذهبت إلى أهلها فإن عليك كفارة يمين، وهي إطعام عشرة مساكين أو كسوتهم أو عتق رقبة، فمن لم يجد صام ثلاثة أيام.\nوهذا أفتى به جمع من السلف الصالح وأفتى به أبو العباس ابن تيمية شيخ الإسلام ابن تيمية رحمه الله وابن القيم وجماعة من أهل العلم، لأنه ما أراد الطلاق، والرسول عليه الصلاة والسلام يقول: إنما الأعمال بالنيات، وإنما لكل امرئ ما نوى.\nوهذا إنما أراد منعها ولم يرد إيقاع الطلاق عليها، فتكون له نيته كما قاله النبي عليه الصلاة والسلام، أما إن كنت أردت إيقاع الطلاق عليها إن ذهبت أنه يقع الطلاق فإنه يقع عليها طلقة واحدة، لأن إيقاع الطلاق بالثلاث في أصح قولي العلماء يعتبر واحدة، لما ثبت في الصحيحين من حديث ابن عباس رضي الله تعالى عنهما قال: كان الطلاق على عهد النبي ﷺ، وعهد أبي بكر وسنتين من خلافة عمر طلاق الثلاث واحدة، فقال عمر: إن الناس قد استعجلوا في أمر كانت لهم فيه أناة فلو أمضيناه عليهم فأمضاه عليهم رواه مسلم في الصحيح.\nفهذا هو الذي وقع في عهد عمر  وأرضاه، والصواب والأرجح: هو ما كان عليه الحال في عهد النبي ﷺ وعهد الصديق وفي أول خلافة عمر رضي الله تعالى عنه، فإذا كنت أردت الطلاق إن ذهبت فإنه يقع عليها واحدة ولك مراجعتها مادامت في العدة، ومتى خرجت العدة ولم تراجع، فلك العود إليها بنكاح جديد بشروط معتبرة شرعاً، إذا كنت ما طلقتها قبل هذا طلقتين، وهذا إن لم تكن أردت ...إلا بإذنك، فإن كنت أردت بهذا الكلام إلا بإذنك، قلت: علي الطلاق بالثلاث أنك ما تذهبي لأهلك إلا عند وفاة أو مرض، يعني: أردت في نيتك إلا بإذنك، يعني: أردت في قلبك إلا بإذنك فإنك متى أذنت لها فلا يقع شيء، لا كفارة ولا طلاق، متى أذنت لها أن تذهب إليهم فإنه لا يقع شيء، أما إن كنت قلت هذا الكلام ولم ترد إلا بإذنك، بل أطلقت الكلام فإن كنت أردت منعها فقط فإنه كفارة يمين على الصحيح من قولي العلماء.\nأما إن أردت إيقاع الطلاق عند ذهابها إلى أهلها فإنه يقع عليها طلقة واحدة كما تقدم، والله ولي التوفيق.\nالمقدم: بارك الله فيكم وجزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6870/الطلاق-بالثلاث-يعتبر-واحدة-في-اصح-قولي-العلماء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_216/21601.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":8766,"question":"هذه رسالة وردت إلينا من السائل سليمان أبو خليل مصري الجنسية يعمل بالدمام يقول: حلفت على زوجتي وأنا في حالة غضب يمين بالطلاق بالثلاث وأن تكون محرمة علي مثل أمي وأختي إذا ذهبت إلى منزل والدها طول غيابي، وحتى الآن لم تذهب، وعندما قرأت حديثاً عن الرسول ﷺ يقول: لا يدخل الجنة قاطع رحم أود أن أرسل لها رسالة وأقول لها: اذهبي إلى أهلك، لكن ما الحكم في يميني؟","title":"حكم الحلف بالطلاق ثلاثاً مع التحريم على فعل شيء","answer":"الجواب: إذا كنت أردت بذلك منعها فقط ولم ترد فراقها إن ذهبت وإنما أردت منعها فقط من الذهاب إلى بيت والدها، فهذا له حكم اليمين، وعليك كفارة يمين إذا ذهبت ولا بأس بذلك، وإن كنت أردت إلا بإذنك، ليس لها الذهاب ناوٍ إلا بإذنك ثم أذنت لها فلا شيء عليك، أما إذا كنت ما نويت إلا بإذنك وأردت طلاقها وتحريمها إن ذهبت فإنك إذا أذنت لها وذهبت يقع طلقة واحدة عليك، يقع طلقة واحدة عليها في أصح قولي العلماء، وعليك كفارة الظهار إن كنت أردت تحريمها، فعليك كفارة الظهار وهي: عتق رقبة عبد أو أمة مؤمنة فإن عجزت ولم تستطع هذا العتق فصيام شهرين متتابعين، فإن لم تستطع أطعمت ستين مسكيناً ثلاثين صاعاً لكل مسكين نصف صاع، وهو كيلو ونص تقريباً قبل أن تمسها سواءً كان من رز أو من تمر أو من حنطة يعني من قوت البلد، هذا هو الواجب عليك قبل أن تمسها ويقع عليها طلقة واحدة، إذا كنت أردت إيقاع الطلاق عليها وتحريمها، وإن كنت ما أردت الطلاق وإنما أردت المنع منعها من الذهاب فقط، فإنك عليك كفارة يمين إذا ذهبت إلى والدها إلا أن تكون أردت في قلبك إلا بإذنك ناوياً إلا بإذنك، فإنك إذا أذنت لها فلا شيء عليك، والله أعلم. فينبغي لك أن تحذر هذا، هذا ما يجوز ليس للمسلم أن يحرم أهله وليس له أن يطلق بالثلاث، الطلاق الشرعي واحدة، يطلق واحدة فقط، ثم إذا طابت نفسه طلق الثانية وهكذا، أما كونه يجمع الطلاق الثلاث لا يجوز، كما أنه لا يجوز له أن يحرم زوجته بل هو منكر من القول وزور كما بينه الله في كتابه العظيم، فالواجب على المسلم أن يتقي الله وأن يحذر ما حرمه الله عليه، ومما حرمه الله عليه الطلاق بالثلاث، والتحريم من زوجته والظهار منها كل هذا منكر، فالواجب على كل زوج أن يتقي الله وأن يتحرى الطلاق الشرعي فيطلقها طلقة واحدة .... إذا عزم على الطلاق يطلق واحدة فقط حال كونها طاهراً لم يجامعها وليست في حيض ولا في نفاس، هذا هو المشروع يطلقها في حال طهرها وعدم الوقوع بها يعني: عدم جماعها أو في حال حملها كونها حامل، هذا هو الطلاق الشرعي ويكون الطلاق واحدة لا بالثلاث، وأما التحريم فلا يجوز ليس له أن يحرمها يقول: حرام علي أو هي علي مثل أمي أو أختي كل هذا لا يجوز، بل هذا مما أنكره الله على عباده، وأرشدهم إلى تركه . نسأل الله للجميع الهداية. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6926/حكم-الحلف-بالطلاق-ثلاثا-مع-التحريم-على-فعل-شيء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_218/21808.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":8769,"question":"هذه رسالة وردت إلينا أيضاً من جمعة عبد الله محمد مصري يعمل بالعراق أيضاً يقول: أنا أسكن مع زملائي وحصل نقاش بيننا فحلفت وقلت: علي اليمين أني لا آكل مع زملائي طوال هذه الرحلة، وفعلاً نفذت اليمين ولكن هذا منع النقاش وحصل خصام، وفي هذا يقول الحديث الشريف عن النبي ﷺ: لا يحل لمسلم أن يهجر أخاه فوق ثلاث فما رأي الشرع في هذا علماً بأنني لا زلت محافظاً على يميني أفتوني أثابكم الله؟","title":"حكم من حلف أن لا يأكل مع زملائه","answer":"الجواب: يقول النبي ﷺ: إذا حلفت على يمين فرأيت غيرها خيراً منها فكفر عن يمينك الذي هو خير متفق عليه، ويقول عليه الصلاة والسلام: إني -والله- إن شاء الله لا أحلف على يمين فأرى غيرها خيراً منها إلا كفرت عن يميني وأتيت الذي هو خير، فأنت أيها الحالف إذا رأيت أن رجوعك إلى إخوانك وأكلك معهم أنسب وأصلح، تكفر عن يمينك ولا حرج عليك، والكفارة هي: إطعام عشرة مساكين، عشرة عدد أصابعك تعطي كل واحد نصف صاع من التمر أو من الأرز أو من الحنطة من قوت البلد، وهو كيلو ونصف تقريباً، أو تكسوهم كسوة على قميص قميص أو إزار ورداء، فإن عجزت صمت ثلاثة أيام، إن كنت فقيراً لا تستطيع صمت ثلاثة أيام. والمقصود بهذا أنك تعمل الأصلح، إن كان الأصلح عدم الأكل معهم؛ لأنهم فساق أهل خمور وأهل فساد فالبعد عنهم أولى وأمض يمينك ولا ترجع إليهم، والتمس أصحاباً آخرين خيراً منهم، أما إن كانوا طيبين وأكلك معهم لا يضرك في دينك فلا بأس أن ترجع إليهم وتكفر عن يمينك ولا تهجرهم، أما إذا كان هجرهم حق؛ لأنهم أهل فسق أهل فساد، قد أعلنوا فسادهم بشرب المسكرات أو التظاهر بما حرم الله من الأمور الأخرى، فهؤلاء يستحقون الهجر وترك صحبتهم أولى ولا حرج عليك في ذلك، ولا يدخل في الحديث: لا يحل لمسلم أن يهجر أخاه فوق ثلاث؛ لأن الحديث إنما هو فيما يتعلق بأمور الناس فيما بينهم خصوماتهم ودنياهم، فليس لأحد أن يهجر أخاه من أجل الدنيا، أو الخصومة التي بينه وبينه أكثر من ثلاث لهذا الحديث الصحيح، أما إذا كانت الهجرة من أجل إعلان الفسوق والمعاصي وإظهار البدع، فهؤلاء يهجرون حتى يتوبوا ولو أكثر من ثلاثة أيام ولو سنة ولو سنتين، وقد ثبت عن النبي ﷺ أنه هجر ثلاثة من الصحابة تخلفوا عن الغزو بغير عذر شرعي فهجرهم النبي ﷺ وأمر الناس بهجرهم، حتى مضى عليهم خمسون ليلة، ثم تاب الله عليهم وأنزل توبتهم ﷺ، فكلمهم النبي ﷺ وكلمهم الناس.\nفالمقصود أن الهجر إذا كان للدنيا والخصومات فإنه ثلاث فأقل، أما إذا كان لله من أجل البدع وإظهار المعاصي فهذا لا يتقيد بمدة معينة بل بالتوبة، متى تابوا ورجعوا عما هم عليه من الباطل كلمهم إخوانهم وتركوا هجرهم.\nالمقدم: بارك الله فيكم وجزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6922/حكم-من-حلف-ان-لا-ياكل-مع-زملاىه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_218/21804.mp3","categories":["الأيمان والنذور"]},{"id":8771,"question":"له سؤال ثالث وأخير وهو شبيه بسؤاله الأول، حيث أنه حلف يميناً بعد شجار بينه وبين أحد أقربائه بأن قال: علي اليمين أن أتزوج، ويقول: إن زوجته التي معه لم يحصل منها أي شيء، فهل لهذا كفارة، أو لا بد أن أتزوج؟","title":"حكم من حلف على أن يتزوج بأخرى","answer":"الجواب: أنت بالخيار؛ إن تزوجت فلا شيء عليك إذا رأيت المصلحة في الزواج، وإن لم تر المصلحة بالزواج ورأيت أن بقاءك مع زوجتك أولى فعليك كفارة اليمين وهي: إطعام عشرة مساكين كما تقدم. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6924/حكم-من-حلف-على-ان-يتزوج-باخرى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_218/21806.mp3","categories":["الأيمان والنذور"]},{"id":8773,"question":"هذه رسالة وردتنا من السائل أحمد سيد حزين من جمهورية مصر العربية ومقيم بالعراق يقول: أقسمت على زوجتي طلاق بالثلاث بأن تخرج من منزلي وتكون علي حرام كأمي وأختي مع سبق النية بأن أطلقها، وفعلاً خرجت من المنزل وذهبت إلى أهلها، وبعد فترة من الزمن عادت إلى المنزل بواسطة الأهل وبدون علمي وإلى الآن لم أعاشرها معاشرة الأزواج، أفيدوني أفادكم الله؟","title":"حكم من طلق بالثلاث وظاهر في نفس الوقت","answer":"الجواب: ما دمت قصدت بهذا طلاقها وفراقها فإن هذا الطلاق يقع به واحدة، إذا كان بهذا اللفظ الذي قلته، قلت: طالق بالثلاث يقع به واحدة على الصحيح من أقوال العلماء، ولك الرجوع إليها ما دامت في العدة، تقول: راجعت زوجتي فلانة ويكفي هذا، والسنة أن يكون بحضرة شاهدين، تقول هذا الكلام بحضرة شاهدين من أخيار المسلمين، تقول: راجعت زوجتي فلانة ويكفي، إذا كنت ما طلقتها قبل هذا طلقتين.. إذا كان ما سبق منك شيء قبل هذا من طلاق مرتين، فإن هذا يكون واحدة، فإن كان سبق منك واحدة قبل هذا يكون هذه ثانية ولك المراجعة، فإن كان سبق منك طلقتان فهذه تكون الثالثة ولا رجعة ما دمت أردت بهذا طلاقها وفراقها بالكلية وإخراجها من بيتك مطلقة، ومتى رجعت إليك لأن هذا الطلاق ما قبله طلقتان فإن عليك أيضاً كفارة الظهار؛ لأنك حرمتها أيضاً، فعليك مع ذلك كفارة الظهار قبل أن تقربها قبل أن تمسها، وكفارة الظهار هي: عتق أمة أو عبد إذا تيسر ذلك لوجه الله، فإن لم تستطع ذلك تصوم شهرين متتابعين عن هذا الظهار، فإن لم تقدر على ذلك لظروفك فعليك أن تطعم ستين مسكيناً، عليك عند العجز عن الصيام إطعام ستين مسكيناً، أي: ستين فقير من فقراء المسلمين تعطيهم ثلاثين صاع كل صاع بين اثنين، والصاع أربع حفنات باليدين الممتلأتين المعتدلتين كل حفنة مد، والأربع صاع بصاع النبي عليه الصلاة والسلام ملء اليدين المعتدلتين المملوءتين وهو معروف، أو تكسوهم كسوة كل واحد يعطى قميص أو إزار ورداء، أو تعتق عبد أو عبدة، لكن تقدم إذا عجزت عن..، المقصود في هذا ما فيه إلا الإطعام ما فيه كسوة الكسوة هذا في كفارة اليمين، المقصود عليك في هذا إطعام ستين مسكين كل مسكين له نصف الصاع فقط، ومقداره بالوزن كيلو ونصف تقريباً من قوت البلد من تمر أو أرز أو حنطة أو ذرة إن كانت قوت البلد أو شعير إن كانت كان قوت البلد يكفي هذا، قبل أن تمسها قبل أن تقربها إذا عجزت عن الصيام وعن العتق، هذا عن الظهار، أما الطلاق فعرفت أن عليك أنه يقع طلقة واحدة ولك مراجعتها في حال عدتها، فإن كانت قد خرجت من العدة فلا بد من نكاح جديد بالشروط المعتبرة شرعاً. نعم.\nالمقدم: بارك الله فيكم وجزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6925/حكم-من-طلق-بالثلاث-وظاهر-في-نفس-الوقت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_218/21807.mp3","categories":["الظهار","الطلاق","الأيمان والنذور"]},{"id":8788,"question":"الرسالة التالية وصلت إلى البرنامج من السائل عباس جداح الجنابي ، محافظة بابل، قضاء المسيب، من الجمهورية العراقية، يقول في رسالته: يعد برنامجكم من البرامج الناجحة التي من شأنها أن تخدم المسلمين وترشدهم إلى الطريق الصحيح، وهذا شيء تشكرون عليه إن شاء الله.السؤال الأول: سبق أن نذرت نذراً لوجه الله تعالى على شرط أن يكون هذا النذر بدون معاملة، أي: بدون مناقشة على السعر عند الشراء، فلما ذهبت إلى السوق عرض علي سلعة بسعر ثمانين ديناراً، مع العلم أنه لا يعادل سعر السلعة إلا ثلاثين ديناراً، فساومت البائع على السعر واشتريت السلعة بسعر أقل، فهل أصبح النذر محللاً أم لا؛ أفيدوني أفادكم الله؟","title":"من أنواع النذر غير المشروع","answer":"الجواب: هذا النذر نذر غير مشروع، لأن المناقشة لا بأس بها؛ ولأن كثيراً من الناس قد يرفع السعر بلا حق، فيحتاج إلى مناقشة، وقد سام النبي ﷺ بعيراً من جابر وناقشه في ذلك عليه الصلاة والسلام، فالمقصود: أن نذرك أنك لا تناقش نذر غير مشروع، فلك أن تناقش في السلع حتى تشتريها بالسعر المناسب الذي يعرف في الأسواق، وعليك كفارة يمين عن هذا، عليك كفارة يمين عن نذرك هذا، وهي: إطعام عشرة مساكين، أو كسوتهم، لكل مسكين كيلو ونص تقريباً من التمر أو من الأرز أو غيرهما من قوت البلد، ولك أن تناقش. نعم.","link":"https://binbaz.org.sa/fatwas/6943/من-انواع-النذر-غير-المشروع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_220/22006.mp3","categories":["الأيمان والنذور"]},{"id":8906,"question":"نعود في بداية هذا اللقاء إلى رسالة الأخ آدم محمد عثمان، السوداني والمقيم بالعراق، أخونا يسأل في هذه الحلقة ويقول: يوجد بعض من الناس عندما يطلق زوجته يقول: أنت في مكان والدتي، فما حكمه إذا أرجعها، وهل يحق له رجوعها أو لا؟","title":"حكم من قال لزوجته عند تطليقها: (أنت في مكان والدتي)","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فإذا كان الطلاق رجعيًا، إن كان طلقها طلقة واحدة أو طلقتين فله مراجعتها ما دامت في العدة، فإذا خرجت من العدة قبل أن يراجعها جاز له أن يعود إليها بنكاح جديد بالشروط المعتبرة شرعًا من الولي والشاهدين، والرضا كما هو معلوم.\nأما قوله: أنت في مكان والدتي، بعدما طلقها، هذا يرجع إلى نيته، إن كان قصده من ذلك: أنها عنده عزيزة، وكريمة وأنه يقدرها، هذا ليس بشيء ولا حرج فيه وليس من الظهار في شيء، يعني: عبارة موهمة.\nأما إن كان قصده (أنت في مكان والدتي)، يعني: أنت محرمة علي، وأنت علي حرام كوالدتي، فهذا يسمى الظهار، ولا تحل له إذا كان الطلاق رجعيًا إلا بعد الكفارة، لا يمسها ولو راجعها، يراجعها لا بأس أو يعقد عليها إذا كانت قد خرجت من العدة، لا بأس، لكن لا يمسها حتى يكفر كفارة الظهار وهي عتق رقبة مؤمنة، فإن عجز صام شهرين متتابعين، فإن عجز أطعم ستين مسكينًا ثلاثين صاعًا، كل صاع يقسم بين اثنين، كل واحد له نصف الصاع من التمر، من الرز، من الحنطة، من قوت البلد، هذا هو الواجب، وليس له أن يمسها حتى يخرج هذه الكفارة، بعدما يراجعها أو بعدما يعقد عليها ليس له أن يمسها يعني: ليس له أن يجامعها إلا بعدما يخرج هذه الكفارة.\nأولًا: رقبة -عتق رقبة مؤمنة- إن قدر.\nثانيًا: صيام شهرين متتابعين، إذا عجز عن الرقبة.\nثالثًا: أن يطعم ستين مسكينًا ثلاثين صاعًا من قوت البلد، إذا عجز عن الصيام، ثم بعد هذا له أن يباشرها.\nأما إن كان الطلاق كاملًا، طلقها الطلقة الأخيرة -الثالثة- فهذه لا تحل له حتى تنكح زوجًا غيره، حتى تنكح زوجًا آخر نكاحًا شرعيًا لا نكاح تحليل، وحتى يطأها أيضًا الزوج الثاني، فإذا طلقها الطلقة الأخيرة-الثالثة- فإنها تحرم عليه تحريمًا مؤقتًا مادامت لم تتزوج، فإذا تزوجت زواجًا شرعي ووطئها الزوج الجديد ثم طلقها أو مات عنها فإنها تحل للأول، إذا كان النكاح شرعي مو بنكاح تحليل، أما نكاحها للتحليل ليحللها للأول هذا نكاح باطل لا يجوز، لكن إذا تزوجها الزوج الجديد بنية الرغبة فيها لكن لم يقدر الله له الرغبة بل طلقها بعد الدخول بها، أي: بعد أن جامعها أو مات عنها، فإنها تحل للأول بعقد جديد، ........... جديد بشروطه المعتبرة شرعًا.\nوإذا كان قال لها بعدما طلقها الطلقة الأخيرة: أنت في مكان أمي، فهذا لا يؤثر شيء، ولو كان أراد التحريم، لأنها صارت أجنبية، صارت أجنبية ما يكون تحريمها تحريم الظهار، إذا كانت بعد الطلقة الأخيرة، قال: أنت في مكان أمي، قصده تحريمها، قصده أن ينوي هذا تحريمها، أو قال: أنت كظهر أمي، أو أنت محرمة علي، فإنه لا يلحقها هذا كالزوجة، ولكن يجب فيه كفارة يمين، مثل: تحريم الطعام والشراب ونحو ذلك، لأنها صارت أجنبية بعد الطلقة الأخيرة، فإذا قال لها: أنت محرمة علي، أو أنت علي كظهر أمي، بعد الطلاق الأخير، فإنها تكون في حكم تحريم الطعام واللباس والشراب، يعني: يستحلها بكفارة اليمين، كفارة يمين ويكفي، إطعام عشرة مساكين أو كسوتهم، ولا يكون ظهارًا؛ لأن الظهار إنما يكون مع النساء مع الزوجات، كما قال تعالى: وَالَّذِينَ يُظَاهِرُونَ مِنْ نِسَائِهِمْ [المجادلة:3] هي بعد الطلقة الأخيرة ما عاد صارت من النساء، صارت أجنبية، فيكون تحريمه لها مثل تحريم الثياب والطعام ونحو ذلك والجواري فيه كفارة اليمين. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/7062/حكم-من-قال-لزوجته-عند-تطليقها-انت-في-مكان-والدتي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_169/16901.mp3","categories":["الظهار","الطلاق","الأيمان والنذور"]},{"id":8914,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المنطقة الشرقية الخبر، باعثتها إحدى الأخوات من هناك تقول: (أ. م) أختنا تقول: أمي حلفت بالله على شيء، ولكنها رجعت ففعلت، فأخرجت كفارة اليمين خمسين ريالًا وأعطتها أخاها؛ لأنه فقير وخال من العمل، ولكنها لا تصلي، فهل كفارتها صحيحة؟ وإذا كانت غير صحيحة فماذا تفعل؟","title":"حكم كفارة اليمين لتارك الصلاة","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فإن الله  قد أوضح الكفارة -أعني: كفارة اليمين- في كتابه الكريم، حيث قال سبحانه: لا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِنْ يُؤَاخِذُكُمْ بِمَا عَقَّدْتُمُ الأَيْمَانَ فَكَفَّارَتُهُ إِطْعَامُ عَشَرَةِ مَسَاكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍ فَمَنْ لَمْ يَجِدْ فَصِيَامُ ثَلاثَةِ أَيَّامٍ ذَلِكَ كَفَّارَةُ أَيْمَانِكُمْ إِذَا حَلَفْتُمْ وَاحْفَظُوا أَيْمَانَكُمْ [المائدة:89] .. الآية، فقد أوضح سبحانه كفارة اليمين، وأنها إطعام عشرة مساكين من أوسط ما يطعمه الإنسان أهله، أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍ، يعني: عتق رقبة، فَمَنْ لَمْ يَجِدْ ذلك يعني: كان فقيرًا لا يستطيع صام ثلاثة أيام، وبناء على هذا فالذي أخرجته أم السائلة وهو خمسون درهمًا عن كفارة اليمين لا تجزئ؛ لأنه خلاف ما شرعه الله، فلابد من التكفير بما شرعه الله، فعليها أن تخرج الكفارة لعشرة من الفقراء المسلمين، وهي خمسة آصع من الرز أو التمر أو الحنطة لكل واحد نصف الصاع، يعني: كيلو ونصف تقريبًا، وإن عشتهم شيئ مصنوع مطبوخ أو غدتهم كفى ذلك، وإن كستهم على قميص قميص أو إزار ورداء كفى ذلك.\nأما كونها لا تصلي فهذا منكر عظيم، وكفر شنيع، فالواجب عليها التوبة إلى الله سبحانه، والرجوع إليه جل وعلا والندم على ما مضى، والإقلاع من ذلك، والبدار إلى التوبة إلى الله مع فعل الصلاة؛ لأن الصلاة عمود الإسلام، وأعظم أركانه بعد الشهادتين، فمن تركها فقد ترك عمود الإسلام، ومن ترك ذلك كفر كفرًا أكبر في أصح قولي العلماء، وإن كانت تجحد وجوب ذلك أو تستهزئ بالصلاة أو بأهلها كان كفرها كفرًا إجماعيًا بين أهل العلم جميعًا، نسأل الله السلامة.\nوقد صح عن رسول الله عليه الصلاة والسلام أنه قال: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر خرجه الإمام أحمد وأهل السنن بإسناد صحيح عن بريدة ، وفي صحيح مسلم عن جابر بن عبدالله الأنصاري  عن النبي ﷺ أنه قال: بين الرجل وبين الكفر والشرك ترك الصلاة والمراد: جنس المكلف رجل أو امرأة؛ لأن أحكام الشرع تعم الجميع، فهذا يدل على أن من ترك الصلاة وإن لم يجحد وجوبها يكون كافرًا كفرًا أكبر؛ لأن المصطفى عليه الصلاة والسلام قال: بين الرجل وبين الكفر والشرك... وهذا كفر معرف، وشرك معرف؛ فهو الشرك الأكبر، والكفر الأكبر نسأل الله العافية.\nفالواجب على أمك -أيها السائلة- أن تتوب إلى الله توبة صادقة، وأن تبادر بذلك، والتوبة الصادقة تشمل أمورًا ثلاثة: الندم على الماضي، والحزن على الماضي.\nوترك المعصية والإقلاع منها.\nوالثالث: العزم الصادق على عدم العودة.\nوإذا كانت المعصية تتعلق بأمور الناس فلابد من إعطائهم حقوقهم أو تحلله منها، كما قال عليه الصلاة والسلام: من كان عنده مظلمة لأخيه من عرضه أو شيء فليتحلله اليوم قبل ألا يكون درهم ولا دينار يعني: قبل يوم القيامة، فإنه يوم القيامة ليس هناك دراهم ولا دنانير إنما هي الأعمال؛ ولهذا قال: فإن كان له عمل صالح أخذ من حسناته بقدر مظلمته، فإن لم يكن له حسنات أخذ من سيئات صاحبه فحمل عليه، فهذه حاله يوم القيامة، يجازى بأحد أمرين: إما بالأخذ من حسناته للمظلوم، فإن لم تكن له حسنات أو لم تكفه حسناته؛ لأن المظلمة كبيرة، أخذ من سيئات المظلوم فطرحت على الظالم نسأل الله العافية، فيجب الحذر.\nوأمر الصلاة أمر عظيم، وقد تساهل بها الكثير من الناس وهذا من الفساد العظيم، والخطر العظيم، يقول الله : حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلاةِ الْوُسْطَى [البقرة:238]، ويقول سبحانه: وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكَاةَ وَارْكَعُوا مَعَ الرَّاكِعِينَ [البقرة:43]، ويقول سبحانه: وَأَقِمِ الصَّلاةَ إِنَّ الصَّلاةَ تَنْهَى عَنِ الْفَحْشَاءِ وَالْمُنْكَرِ [العنكبوت:45]، ويقول : قَدْ أَفْلَحَ الْمُؤْمِنُونَ ۝ الَّذِينَ هُمْ فِي صَلاتِهِمْ خَاشِعُونَ [المؤمنون:1-2] إلى أن قال سبحانه: وَالَّذِينَ هُمْ عَلَى صَلَوَاتِهِمْ يُحَافِظُونَ ۝ أُوْلَئِكَ هُمُ الْوَارِثُونَ ۝ الَّذِينَ يَرِثُونَ الْفِرْدَوْسَ هُمْ فِيهَا خَالِدُونَ [المؤمنون:9-11]، والفردوس: هو أعلى الجنة وأوسطها وأشرفها، ويقول جل وعلا: إِنَّ الإِنسَانَ خُلِقَ هَلُوعًا ۝ إِذَا مَسَّهُ الشَّرُّ جَزُوعًا ۝ وَإِذَا مَسَّهُ الْخَيْرُ مَنُوعًا ۝ إِلَّا الْمُصَلِّينَ ۝ الَّذِينَ هُمْ عَلَى صَلاتِهِمْ دَائِمُونَ [المعارج:19-23] إلى أن قال : وَالَّذِينَ هُمْ عَلَى صَلاتِهِمْ يُحَافِظُونَ ۝ أُوْلَئِكَ فِي جَنَّاتٍ مُكْرَمُونَ [المعارج:34-35]، وقال : فَخَلَفَ مِنْ بَعْدِهِمْ خَلْفٌ أَضَاعُوا الصَّلاةَ وَاتَّبَعُوا الشَّهَوَاتِ فَسَوْفَ يَلْقَوْنَ غَيًّا [مريم:59]، الغي عند أهل التفسير هو الخسار والدمار، والعاقبة الوخيمة، وقيل: أنه وادي في جهنم بعيد قعره خبيث طعمه، فتوعد الله من أضاع الصلاة بهذا الوعيد العظيم، وقال سبحانه: فَوَيْلٌ لِلْمُصَلِّينَ ۝ الَّذِينَ هُمْ عَنْ صَلاتِهِمْ سَاهُونَ [الماعون:4-5]، توعدهم بالسهو عنها فكيف بتركها؟ الترك أعظم، وقال  في المنافقين: إِنَّ الْمُنَافِقِينَ يُخَادِعُونَ اللَّهَ وَهُوَ خَادِعُهُمْ وَإِذَا قَامُوا إِلَى الصَّلاةِ قَامُوا كُسَالَى [النساء:142]، فأخبر عن المنافقين أنهم يتكاسلون عن الصلاة، وذمهم على هذا، فكيف بمن تركها؟ يكون أقبح من فعل المنافقين.\nفيجب الحذر على كل مسلم كل مكلف ينتسب إلى الإسلام يجب عليه الحذر، يجب أن يبادر بالمحافظة على الصلوات في أوقاتها في جماعة إذا كان رجلًا، وإن كانت امرأة ففي البيت تحافظ على ذلك وتلزم هذه الصلاة، تسأل الله العون عليها، وما سبق من تقصير ففيه التوبة اللازمة، التوبة النصوح، والله يتوب على التائبين سبحانه وتعالى. نعم.\nالمقدم: جزاكم الله خيرًا، إذا أذنتم لي سماحة الشيخ: هل هناك فرق بين من يترك الصلاة عمدًا أو تهاونًا أو تكاسلًا؟\nالشيخ: نعم مثل ما تقدم، الفرق بينهما: أن من ترك الصلاة عمدًا جاحدًا لوجوبها أو مستهزئًا بها فهذا يكون كافرًا عند جميع العلماء مرتدًا عن الإسلام، يجب قتله؛ لأنه بدل دينه؛ لأنه كذب الله ورسوله باعتقاده عدم وجوبها أو باستهزائه بها، والله يقول: قُلْ أَبِاللَّهِ وَآيَاتِهِ وَرَسُولِهِ كُنتُمْ تَسْتَهْزِئُونَ ۝ لا تَعْتَذِرُوا قَدْ كَفَرْتُمْ بَعْدَ إِيمَانِكُمْ [التوبة:65-66].\nأما الذي يتركها تهاونًا، ويقول: أنا أؤمن بها وأنا أعرف أنها واجبة وفريضة، يعترف بهذا ولكنه يتساهل فلا يصلي أو يصلي الجمعة دون غيرها، أو في رمضان دون غيره، فهذا هو الذي محل الخلاف، ذهب جمع من أهل العلم إلى أنه يكون كافرًا كفرًا أصغر أو ظلمًا أصغر وفسقًا أصغر ما دام يقر بالوجوب فلا يكون كفره كفرًا أكبر، مثلما جاء في الحديث الآخر: لا ترجعوا بعدي كفارًا يضرب بعضكم رقاب بعض، ومثل قوله ﷺ: .... ربكم .... من آبائكم، ومثل قوله ﷺ: اثنتان في الناس هما بهم كفر: الطعن بالنسب والنياحة على الميت قالوا: هذا كفر دون كفر، فيكون قوله ﷺ في حق التارك للصلاة: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر يعني: الكفر الأصغر، وهكذا يقولون في الحديث الآخر: بين الرجل وبين الكفر والشرك ترك الصلاة قالوا: يكون المراد بهذا الكفر والشرك الكفر الأصغر والشرك الأصغر. المقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/7071/حكم-كفارة-اليمين-لتارك-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_170/17001.mp3","categories":["حكم الصلاة وأهميتها","الأيمان والنذور"]},{"id":9009,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول: الجعيدي يماني، أخونا يقول: إنني إذا سمعت القرآن أحلف يميناً أنني لن أترك الصلاة بعد اليوم لكن فاتتني أيام لم أصل فيها، كيف تنصحونني والعمل الذي فات؟","title":"حكم من حلف على عدم ترك الصلاة ثم تركها","answer":"الجواب: أولاً عليك التوبة إلى الله فإن الصلاة عمود الإسلام، وهي أعظم أركانه بعد الشهادتين، وقد قال عليه الصلاة والسلام في الحديث الصحيح: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر.\nفعليك أن تتوب إلى الله من هذا العمل وهو ترك الصلاة في أيام، وعليك أن تبادر وتسارع إلى المحافظة عليها وإن قضيتها خروجاً من الخلاف فحسن، وإلا فالصواب: أن من تركها عمداً يكفر وليس عليه قضاء، لكن إذا كانت قليلة وقضيتها من باب الاحتياط فلا بأس، وعليك كفارة يمين؛ لأنك حلفت أن لا تترك وقد تركت فعليك كفارة يمين عما فعلت من الترك وهي إطعام عشرة مساكين أو كسوتهم أو عتق رقبة، هذا هو الواجب عليك، وأهم شيء وأعظمه: التوبة إلى الله سبحانه وتعالى والبدار بالمحافظة على الصلاة مع إخوانك في مساجد الله جل وعلا والحذر كل الحذر من تركها بعد ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/7167/حكم-من-حلف-على-عدم-ترك-الصلاة-ثم-تركها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_147/14702.mp3","categories":["الأيمان والنذور","حكم الصلاة وأهميتها"]},{"id":9114,"question":"والدي حلف يمين على عدم إدخال الفيديو في البيت، ونظرًا لحالتي فقد أدخلت الفيديو دون علمه، ما الحكم، انصحوني جزاكم الله خيرًا؟","title":"حكم مخالفة الابن لأبيه في عدم إدخال الفيديو البيت","answer":"الجواب: أولًا: أنت عاصٍ في هذا الحال؛ لأن الواجب عليك طاعة والدك في المعروف، وهذا من المعروف والفيديو لا يأتي بخير لا يأتي إلا بالشر؛ لأن الغالب على الفيديو أن يكون فيه الصور الخليعة والأغاني والملاهي، فليس لك أن تدخله حتى ولو كان سليمًا عليك أن تطيع والدك، من باب سد الذريعة، فأنت عاصٍ بهذا وعليك التوبة إلى الله وإخراج الفيديو، والوالد ليس عليه كفارة؛ لأنه لم يعلم، لكن أنت العاصي وأنت الذي عليك التوبة إلى الله وإخراج الفيديو من البيت طاعة لأبيك وحذرًا من شر الفيديو؛ لأنه في الغالب لا يسلم من أن يكون فيه ما يغضب الله من الصور الخليعة والكلام المحرم والأغاني المنكرة ونحو ذلك، نسأل الله لنا ولك الهداية.\nالمقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/7274/حكم-مخالفة-الابن-لابيه-في-عدم-ادخال-الفيديو-البيت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_179/17908.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة","الدعوة والدعاة"]},{"id":9124,"question":"هذه رسالة وصلت إلى البرنامج من المنطقة الشرقية وباعثها أحد الإخوة من هناك يقول: سيد (ع. ع. ع) أخونا يقول في رسالته: في مرة من المرات حلفت على زوجتي وقلت: إذا استعملت أي نوع من العطور أو الحناء والتي تستعمل بالعطور أو جاملت بها لإحدى النساء، وذلك أثناء وجودي بالشقة التي نسكنها فإنك تكوني طالق، ولم أتخذ هذا القرار إلا بعد جهد وتكرار ومحاولات لإقناعها لتترك استعمالها أثناء وجودي، حيث أن هذه العطور والروائح تسبب لي صداع ومضايقات شديدة، علمًا بأن الشقة لا تتسرب منها رائحة العطور بسرعة، وبعد مضي عدة أشهر نسيت زوجتي بهذا الحلف وأخذت زجاجة عطر وفتحتها وأدخلت أصبعها داخل الزجاجة ومسحت بها، وبعد ذلك تذكرت بالحلف وأسرعت إلى مكان آخر وأخبرتني بذلك، علمًا بأنني كنت نائم داخل المنزل، أرجو من سماحتكم إفادتي عما حدث مني جزاكم الله خيرًا؟","title":"حكم من حلف بالطلاق على امرأته أن تفعل كذا وفعلته","answer":"الجواب: إذا كانت المرأة فعلت ذلك نسيانًا كما قلت في السؤال فليس عليك شيء وليس عليها شيء، يقول الله سبحانه: رَبَّنَا لا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا [البقرة:286]، وصح عن رسول الله عليه الصلاة والسلام أن الله قال: قد فعلت، فالناسي ليس عليه شيء والحمد لله، أما إن تعمدت ذلك وأنت تقصد منعها ولا تقصد فراقها وإنما قصدت منعها وتخويفها، فإذا فعلت ذلك عمدًا فعليك كفارة يمين ولا يقع الطلاق إذا كان المقصود منعها وتخويفها وتحذيرها، أما إن كان المقصود إيقاع الطلاق إذا فعلت، فإنها إذا فعلت ذلك عمدًا يقع طلقة واحدة بهذا الكلام الذي قلت، وإن كان عن نسيان فإنه لا يقع شيء والحمد لله. نعم.","link":"https://binbaz.org.sa/fatwas/7284/حكم-من-حلف-بالطلاق-على-امراته-ان-تفعل-كذا-وفعلته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_179/17910.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":9132,"question":"وهذه رسالة وصلت إلى البرنامج من الأخ (محمود . ع) من الكويت الجهرة، يقول في رسالته وفي بدايتها: بسم الله الرحمن الرحيم، السلام عليكم ورحمة الله وبركاته، تحية طيبة مباركة أتقدم بها إلى الأفاضل المشايخ في برنامج نور على الدرب، أنا شاب مصري أعمل بالكويت واسمي محمود ذهبت إلى مصر لقضاء إجازتي، وفي أثناء وجودي في البلدة حصل حوار بيني وبين زوجتي وغضبت منها غضباً شديداً فقلت: علي الطلاق تكوني خالصة لو ذهبت إلى البلدة التي يعيش فيها أهلها، وأقصد بذلك بيت أهلها، فبعد سفري إلى الكويت مرة ثانية أرسلت لي خطاباً تقول: أريد أن أذهب إلى بيت أهلي، وتقصد أنها كانت متضايقة مما قلته لها، فوافقت وبعثت إليها بخطاب بالموافقة وأنا ما زلت في الكويت وذهبت بموافقتي، هل اليمين يكون واقعاً، علماً أنني حلفت اليمين وأقصد به تخويفها ولم أشعر باليمين، هل علي كفارة يمين أم اليمين واقعة، وإذا كان علي كفارة يمين هل أدفعها لعشرة أفراد أم أدفعها لفرد واحد، وإذا كانت تقدر بالدينار كما عندنا في الكويت أدفع كم دينار أفيدونا أفادكم الله؟","title":"حكم الحلف بالطلاق بنية المنع والتخويف","answer":"الجواب: إذا كان الواقع كما ذكرت وأنك طلقت عليها أن لا تذهب لأهلها بقصد تخويفها ومنعها لا لقصد إيقاع الطلاق فإنه لا يقع الطلاق؛ لقول النبي ﷺ: إنما الأعمال بالنيات، وإنما لكل امرئ ما نوى، فما دمت حين منعتها من أهلها أو طلقت على ذلك أردت بذلك منعها وتخويفها لا إيقاع الطلاق عليها إن ذهبت فإنه عليك كفارة يمين فقط، وهي إطعام عشرة مساكين لكل مسكين نصف صاع من التمر أو من الرز أو غيرهما من قوت البلد، عشرة لا يعطاها واحد بل لا بد من عشرة ولا بد من طعام ولا تجزي النقود لا دينار ولا غيره، الواجب إخراجها من الطعام تعشيهم في بيتك أو تغديهم ولو متفرقين ولو اثنين اثنين واحد واحد حتى تكمل العشرة، أو تعطيهم الطعام بأيديهم نصف صاع كيلو ونصف من التمر من الأرز من الحنطة يعني: من قوت البلد ويكفي ذلك والحمد لله ولا يقع الطلاق.\nوإن كنت أردت بهذا الكلام إلا بإذنك أنها لا تخرج إليهم إلا بإذنك، ناوي هذا ناوي الإذن ثم أذنت لها فلا شيء عليك لا كفارة ولا غيرها، إذا كنت نويت بإذنك يعني: ليس لكي الخروج إلى أهلك والذهاب إلى أهلك إلا بإذني هذا نيتك وأنك متى أذنت فلا شيء فقد أذنت لها ولا يقع شيء الحمد لله، أما إذا كنت ما نويت الإذن بأن قلت: عليك الطلاق ألا تذهبي لأهلك وإذا ذهبت فأنت طالق وقصدك منعها وتخويفها فإنها بهذا الإذن يباح لها أن تذهب إلى أهلها وعليك الكفارة المذكورة وهي كفارة يمين وهي إطعام عشرة مساكين عشرة فقراء. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7293/حكم-الحلف-بالطلاق-بنية-المنع-والتخويف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_229/22906.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":9152,"question":"السؤال الثاني في رسالة الأخ (م. ج) سوريا الرقة يقول فيه: عندنا الكثير من الناس يحلفون بغير الله، فهل هذا جائز؟ مثلاً يقولون: وحياة النبي محمد عليه الصلاة والسلام، وحياة عيسى أو موسى عليهما السلام، أو وحياة القرآن، أو وحياة قبر أبوي، أو أقسم في شرفي. أفيدوني بهذا جزاكم الله خير الجزاء.","title":"حكم الحلف بالأنبياء والآباء والشرف والقرآن","answer":"الجواب: الحلف بغير الله لا يجوز، بل يجب أن يكون الحلف بالله وحده سبحانه وتعالى؛ لما ثبت عن رسول الله عليه الصلاة والسلام أنه قال: من كان حالفاً فلا يحلف إلا بالله أو ليصمت، وقال عليه الصلاة والسلام: من حلف بغير الله فقد أشرك وفي اللفظ الآخر: فقد كفر وفي اللفظ الآخر: فقد كفر أو أشرك، فالحلف بغير الله من المحرمات الكفرية، ولكنه من الشرك الأصغر؛ إلا إذا قصد أن محلوفه عظيم كعظمة الله أو أنه يتصرف في الكون أو أنه يصلح أن يدعى من دون الله صار كفراً نعوذ بالله، فإذا قال: وحياة فلان أو وحياة الرسول أو وحياة عيسى أو وحياة موسى أو شرفي أو قبر أبي أو ما أشبه ذلك كله حلف بغير الله كله لا يجوز، أو حلف بالأمانة أو بالكعبة كل ذلك منكر. الواجب أن لا يحلف إلا بالله وحده سبحانه وتعالى أو بصفة من صفاته أو باسم من أسمائه عز وجل، والقرآن من كلام الله، القرآن من صفات الله، فإذا قال: والقرآن أو وحياة القرآن هذا لا بأس لأن القرآن كلام الله سبحانه وتعالى، فإذا حلف بالقرآن أو قال: بعزة الله أو بعلم الله أو بحياة الله فلا بأس، صفات الله يقسم بها، لكن المخلوقون لا لا يقسم بمخلوق، لا بالنبي صلى الله عليه وسلم وهو أشرف الخلق ولا بالكعبة ولا بالأمانة ولا بحياة فلان ولا شرف فلان ولا غير ذلك؛ لأن الرسول نهى عن هذا عليه الصلاة والسلام وحذر منه عليه الصلاة والسلام، وقال ابن عبد البر الإمام المشهور رحمه الله: أجمع العلماء على أنه لا يجوز الحلف بغير الله.\nفيجب على المؤمن أن يحذر هذه الأيمان الباطلة، وأن يحذر إخوانه من ذلك، وأن يدعوهم إلى أن يحلفوا بالله وحده . نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7310/حكم-الحلف-بالانبياء-والاباء-والشرف-والقران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_231/23102.mp3","categories":["الطلاق","الأيمان والنذور","الحلف بغير الله"]},{"id":9158,"question":"الأخ المستمع (أ. ب. ك) محافظة دهوك العراق يقول في رسالته: إني شاب مسلم في العشرين من العمر غير متزوج أصوم شهر رمضان المبارك منذ تسع سنوات، وأصلي حسب الأصول والحمد لله، أحب ديني الإسلام إلى درجة كبيرة جداً، وختمت القرآن مرات عديدة، ولكن مع الأسف الشديد لي شهوة جنسية عالية وقد ارتكبت خطأً كبيراً وتبت بعد ذلك، وقد حلفت أن لا أفعل مرة أخرى، وإذا فعلت فأنا لست على دين الإسلام، وقد ارتكبت نفس الخطأ مرة أخرى ومع الأسف الشديد الآن تبت إلى الله ولن أفعل مرة أخرى بإذن الله، أرجوكم أرشدوني كيف أخلص نفسي من عذاب الله؟ وماذا أفعل تجاه هذا الحلف وجزاكم الله خير الجزاء؟","title":"حكم من حلف على ترك المعاصي فوقع فيها","answer":"الجواب: الحمد لله الذي هداك للتوبة وأرشدك إليها، وأبشر يا أخي أنك على خير إن شاء الله، والتوبة تجب ما قبلها، ولو عدت ما دمت تبت توبة صادقة في الأول و في الآخر فاحمد الله على ذلك، قال الله جل وعلا: وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَا الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ [النور:31] فجعل التوبة طريق الفلاح، فقد أفلحت إن شاء الله في ذلك، وقال النبي ﷺ: التوبة تجب ما كان قبلها يعني: تزيل ما كان قبلها وتهدم ما كان قبلها، فإذا كان الكفر وهو أعظم الذنوب إذا تاب الإنسان منه غفره الله، كما قال : قُلْ لِلَّذِينَ كَفَرُوا إِنْ يَنتَهُوا يُغْفَرْ لَهُمْ مَا قَدْ سَلَفَ [الأنفال:38] فالكفر أعظم الذنوب ومتى تاب الإنسان منه تاب الله عليه، إذا تاب صادقاً ندم على الماضي وعزم أن لا يعود فيه وأقلع منه تاب الله عليه، وهكذا الزنا وسائر المعاصي من تاب منها توبة صادقة بالندم على الماضي والإقلاع من الفاحشة والعزم الصادق أن لا يعود فيها فإن الله يمحوها عنه ويكفرها له، أما اليمين فعليك كفارة اليمين، حلفك عليك أن تكفر كفارة يمين وهي إطعام عشرة مساكين لكل مسكين نصف صاع من التمر أو الأرز أو غيرهما من قوت البلد، أو تكسوهم كسوة كل واحد تعطيه قميصاً أو إزاراً ورداءً، هذه كفارة يمينك والحمد لله، ونسأل الله لك الثبات على الحق، والعافية من نزغات الشيطان إنه جل وعلا جواد كريم.","link":"https://binbaz.org.sa/fatwas/7318/حكم-من-حلف-على-ترك-المعاصي-فوقع-فيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_231/23109.mp3","categories":["الأيمان والنذور"]},{"id":9168,"question":"السؤال الثاني في رسالة الأخ (م. ج) سوريا الرقة يقول فيه: عندنا الكثير من الناس يحلفون بغير الله، فهل هذا جائز؟ مثلاً يقولون: وحياة النبي محمد عليه الصلاة والسلام، وحياة عيسى أو موسى عليهما السلام، أو وحياة القرآن، أو وحياة قبر أبوي، أو أقسم في شرفي. أفيدوني بهذا جزاكم الله خير الجزاء.","title":"حكم الحلف بالأنبياء والآباء والشرف والقرآن","answer":"الجواب: الحلف بغير الله لا يجوز، بل يجب أن يكون الحلف بالله وحده سبحانه وتعالى؛ لما ثبت عن رسول الله عليه الصلاة والسلام أنه قال: من كان حالفاً فلا يحلف إلا بالله أو ليصمت، وقال عليه الصلاة والسلام: من حلف بغير الله فقد أشرك وفي اللفظ الآخر: فقد كفر وفي اللفظ الآخر: فقد كفر أو أشرك، فالحلف بغير الله من المحرمات الكفرية، ولكنه من الشرك الأصغر؛ إلا إذا قصد أن محلوفه عظيم كعظمة الله أو أنه يتصرف في الكون أو أنه يصلح أن يدعى من دون الله صار كفراً نعوذ بالله، فإذا قال: وحياة فلان أو وحياة الرسول أو وحياة عيسى أو وحياة موسى أو شرفي أو قبر أبي أو ما أشبه ذلك كله حلف بغير الله كله لا يجوز، أو حلف بالأمانة أو بالكعبة كل ذلك منكر. الواجب أن لا يحلف إلا بالله وحده سبحانه وتعالى أو بصفة من صفاته أو باسم من أسمائه عز وجل، والقرآن من كلام الله، القرآن من صفات الله، فإذا قال: والقرآن أو وحياة القرآن هذا لا بأس لأن القرآن كلام الله سبحانه وتعالى، فإذا حلف بالقرآن أو قال: بعزة الله أو بعلم الله أو بحياة الله فلا بأس، صفات الله يقسم بها، لكن المخلوقون لا لا يقسم بمخلوق، لا بالنبي صلى الله عليه وسلم وهو أشرف الخلق ولا بالكعبة ولا بالأمانة ولا بحياة فلان ولا شرف فلان ولا غير ذلك؛ لأن الرسول نهى عن هذا عليه الصلاة والسلام وحذر منه عليه الصلاة والسلام، وقال ابن عبد البر الإمام المشهور رحمه الله: أجمع العلماء على أنه لا يجوز الحلف بغير الله.\nفيجب على المؤمن أن يحذر هذه الأيمان الباطلة، وأن يحذر إخوانه من ذلك، وأن يدعوهم إلى أن يحلفوا بالله وحده . نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7310/حكم-الحلف-بالانبياء-والاباء-والشرف-والقران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_231/23102.mp3","categories":["الطلاق","الأيمان والنذور","الحلف بغير الله"]},{"id":9181,"question":"هذه رسالة وصلت إلى البرنامج من المستمع (س. م. ع) من العراق نينوى أخونا يقول: حدث مشكلة بيني وبين أخي حول السيارة التي نمتلكها نحن، وقد غضبت غضبًا شديدًا وحلفت طلاقًا وقلت: بطلاقي الثلاثة لا أقوم بقيادة السيارة وفعلًا لم أقم بقيادة السيارة أكثر من ثمانية أشهر، ونتيجة للظروف التي يمر بها أخي حيث لا يستطيع هو قيادة السيارة فما هو الواجب الذي يجب أن أعمله أنا، هل نقوم ببيع هذه السيارة ونشتري سيارة أخرى لا أقوم بقيادتها أنا؟ أم أقوم بقيادة السيارة نفسها، وما هو حكم الطلاق بالنسبة لي في هذه الحالة؟","title":"حكم الحلف بالطلاق والواجب فيه","answer":"الجواب: إذا كنت أيها السائل المطلق إنما أردت منع نفسك من قيادة السيارة ولم ترد إيقاع الطلاق وإنما أردت منع نفسك من قيادة السيارة غضبًا على أخيك فإن عليك كفارة اليمين ولا حرج أن تقود السيارة، وهذا يكون له حكم اليمين في أصح قولي العلماء، فعليك كفارة يمين وهي إطعام عشرة مساكين أو كسوتهم، لكل مسكين نصف صاع من قوت البلد، وهو كيلو ونصف تقريبًا، أو كسوة العشرة مما يحزئهم في الصلاة، أما إن كان قصدك إيقاع الطلاق سقتها فإنه يقع الطلاق فإنك إذا سقتها يقع طلقة واحدة على زوجتك، ولك مراجعتها ما دامت في العدة في الحال، إذا كنت لم تطلقها قبل هذا طلقتين.\nأما بيع السيارة وعدم بيع السيارة فهذا يرجع إليكما، لكما أن تبيعاها ولكما أن تتركاها لكن إن كان قصدك هذه السيارة بعينها فإذا بيعت لك أن تقود غيرها ولا يقع شيء، أما إن كان قصدك ترك مساعدة أخيك لا في هذه السيارة ولا في غيرها، وأنك تريد أن لا تسوق معه سيارة وأن لا تخدمه في هذا الشيء فلا فرق بين هذه السيارة وغيرها، ولا تنحل اليمين ببيعها حتى السيارة الأخرى إذا جاءت ليس لك أن تقودها؛ لأنك قصدت بذلك مغاضيه أخيك وهجران مساعدته، فإذا قدت السيارة الثانية فهي كالأولى إن كنت أردت إيقاع الطلاق وقع الطلاق وإن كنت لم ترد ذلك وإنما أردت هجران أخيك وعدم مساعدته في هذا الشيء فعليك كفارة اليمين كما تقدم. نعم.","link":"https://binbaz.org.sa/fatwas/7341/حكم-الحلف-بالطلاق-والواجب-فيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_180/180005.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":9233,"question":"هذه رسالة وردتنا من محمد المطيري من الزلفي الحي الشمالي، الأخ محمد يقول في رسالته: حلفت والدتي بالله العظيم بأن ابنتها لا تأخذ شخصاً أردت أنا أن أزوجه أختي، وبعد حين جاء أحد الأقارب أقارب والدتي وطلب أختي وزوجها من الشخص الذي حلفت عليه أمي أنه لا يأخذ ابنتها، وقد عقد له عليها، وبعد ذلك اتضح بأن الذي زوجناه رضيع لأختي فأخلى سبيلها،  هل عليها كفارة أو أي شيء آخر، فهي محرجة تماماً من أقاربها بسبب زواج الشخص المذكور أفيدونا أفادكم الله؟","title":"حكم من حلف على شيء أن لا يقع فوقع","answer":"الجواب: عليها كفارة اليمين؛ لأن ما حلفت عليه وقع، حلفت أن لا يزوج من هذا الشخص، أن لا تزوج ابنتها من هذا الشخص ثم سمحت بذلك ووافقت على ذلك، أو زوجت من غير انشراح، بكل حال ما دام زوجت عليه فعليها كفارة اليمين، وهي إطعام عشرة مساكين أو كسوتهم، عشرة كل مسكين يعطى نصف الصاع من التمر كيلو ونصف تقريباً من التمر أو من الأرز أو من أي نوع من أنواع قوت البلد، أو تكسوهم كسوة على قميص قميص أو على إزار ورداء هذه هي الكفارة، أو عتق عبد مؤمن أو أمة مؤمنة. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7396/حكم-من-حلف-على-شيء-ان-لا-يقع-فوقع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_234/23406.mp3","categories":["الأيمان والنذور"]},{"id":9243,"question":"وهذه رسالة وردت لنا من السائل (م. أ) من خميس مشيط يقول في رسالته: إنني حلفت بيمين تبع يمين -هكذا كتب- على أنني لا أتعاطى الدخان مرة أخرى، لكن لم أستطع محاربة ذلك، وعدت مرة أخرى لتعاطيه، فهل هذا الحلف بمعنى الطلاق أو حلف بالله؟","title":"حكم من حلف على الامتناع من شيء أيماناً متتابعة وفعل","answer":"الجواب: إذا حلفت بالله مرات كثيرة أنك لا تعود إلى التدخين أنك لا ترجع إلى التدخين كأن تقول والله ما أشرب الدخان والله ما أشرب الدخان والله لا أعود إليه ولو خمس مرات ولو عشر مرات ولو مائة مرة، ثم عدت عليه فعليك التوبة إلى الله، وعليك كفارة يمين واحدة فقط؛ لأنها على شيء واحد، فعليك كفارة يمين وهي إطعام عشرة مساكين لكل واحد نصف صاع من التمر أو غيره من قوت البلد، أو كسوتهم أو عتق رقبة إن تيسر لك، فإن عجزت عند ذلك صمت ثلاثة أيام. وعليك التوبة إلى الله من التدخين والجد والنشاط في محاربته والصبر والمصابرة وصحبة الأخيار الذين لا يشربونه، وإذا فعلت هذا أعانك الله  لكن لا تصحب الذين يشربونه إذا صحبتهم رجعت إليه فعليك أن تحارب ذلك وأن تترك صحبة من يشربه حتى لا تعود إليه، فإنه خبيث مضر ومحرم. فالواجب تركه والحذر منه ولا يجوز بيعه ولا شراءه ولا التجارة فيه لا في البقالات ولا في غيرها، بل يجب أن يترك ويحارب لمضرته العظيمة وخبثه، والله يقول  : يَسْأَلُونَكَ مَاذَا أُحِلَّ لَهُمْ قُلْ أُحِلَّ لَكُمُ الطَّيِّبَاتُ [سورة المائدة:4].  فالله ما أحل لنا إلا الطيبات وهو ليس من الطيبات بل هو من الخبائث المحرمة. وقال  : وَيُحِلُّ لَهُمُ الطَّيِّبَاتِ وَيُحَرِّمُ عَلَيْهِمُ الْخَبَآئِثَ [الأعراف:157]. هكذا بعث الله النبي ﷺ يحل الطيبات ويحرم الخبائث. فالدخان فيها خبائث منكرة، المضرة ببدن الإنسان وصحته ومسببة لأمراض كثيرة وخطيرة وهكذا بقية المسكرات والمخدرات كلها ضرر عظيم يجب أن تحارب -نسأل الله للمسلمين الهداية والعافية منها-.  المقدم: بارك الله فيكم، يسأل أيضًا ويقول: صار بيني وبين شخص قريب لي شجار، وحلفت ألا أشرب ولا آكل في منزله، فعدت وتناولت ما طاب لي من مأكل ومشرب فما عقاب ذلك الحلف؟ الشيخ: عليه كفارة يمين، عليه كفارة يمين وهي: إطعام عشرة مساكين كما تقدم، لكل مسكين نصف صاع من التمر أو الرز أو غيره من قوت البلد، أو عتق رقبة مؤمنة، أو كسوة العشرة من الفقراء لكل واحد قميص، يكفي، فإذا عجزت ولم تستطع ذلك فعليك صيام ثلاثة أيام، نسأل الله التوفيق والهداية. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7412/حكم-من-حلف-على-الامتناع-من-شيء-ايمانا-متتابعة-وفعل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_235/23511.mp3","categories":["الأيمان والنذور"]},{"id":9286,"question":"تسأل أيضاً عن كفارة اليمين سماحة الشيخ؟","title":"كفارة اليمين يجب فيها إحدى ثلاث","answer":"الجواب: كفارة اليمين مثلما قال الله في كتابه العظيم: لا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِنْ يُؤَاخِذُكُمْ بِمَا عَقَّدْتُمُ الأَيْمَانَ فَكَفَّارَتُهُ إِطْعَامُ عَشَرَةِ مَسَاكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍ فَمَنْ لَمْ يَجِدْ فَصِيَامُ ثَلاثَةِ أَيَّامٍ ذَلِكَ كَفَّارَةُ أَيْمَانِكُمْ إِذَا حَلَفْتُمْ وَاحْفَظُوا أَيْمَانَكُمْ [المائدة:89] الآية، فالله سبحانه بين أن كفارة اليمين: إِطْعَامُ عَشَرَةِ مَسَاكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍ [المائدة:89]، فالواجب أحد الثلاث:\nالواجب إما إطعام عشرة مساكين.\nوإما الكسوة.\nوإما العتق.\nوالإطعام يكون نصف صاع، يعني: كيلو ونصف تقريباً من الطعام الذي يقتاته هو وأهله في البلد من أرز أو حنطة أو تمر أو شعير أو غير ذلك مما يقتاته أهل البلد، ويكون من الوسط لا من الرديء ولا من أعلى شيء فيكون من الوسط، يطعمهم كما يطعم أهله، أو يكسوهم كسوة تجزئهم في الصلاة كالقميص أو الإزار والرداء، أو يعتق عبداً أو أمة، فإن عجز عن ذلك كله صام ثلاثة أيام فقط، والأفضل أن تكون متتابعة. نعم.","link":"https://binbaz.org.sa/fatwas/7450/كفارة-اليمين-يجب-فيها-احدى-ثلاث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_154/15415.mp3","categories":["الأيمان والنذور"]},{"id":9293,"question":"وهذه رسالة وردت إلى البرنامج من السائل منصور الدوسري من منطقة الخرج، يقول: في يوم من الأيام حدث خلاف خفيف بيني وبين الوالد؛ لأنه توجد سيارة ملك لوالدي فغضب من أجل سيارته وأخفاها، وقال لي: امش على رجليك، فطلقت زوجتي بالثلاث على أن أشتري سيارة جديدة ولا أركب سيارة الوالد، لكنني اضطررت واحتجت إلى سيارة الوالد لكي أوصل زوجتي لأهلها، ورجعت واشتريت سيارة جديدة من مالي الخاص، ثم ذهبت إلى الزوجة وأرجعتها إلى بيتي من غير ما تدري عن الطلاق الذي حدث في وقت الزعل، وتندمت على ما حدث، وأتوب إلى الله، ثم أعدكم أن لا يتكرر مني هذا الطلاق مرة أخرى، أفيدوني أفادكم الله؟","title":"حكم من حلف بالطلاق على عدم فعل شيء ثم فعله","answer":"الجواب: إذا كان المقصود من هذا الطلاق منع نفسك من ركوب سيارة الوالد، وحتى تجتهد في شراء السيارة الجديدة، وليس قصدك فراق أهلك وإيقاع الطلاق عليهم، وإنما أردت بذلك منع نفسك من ركوب سيارة الوالد، وحث نفسك على الشراء شراء السيارة الجديدة، فهذا الشيء يكون في حكم اليمين، يكون طلاقك هذا في حكم اليمين، وعليك كفارة اليمين ويكفي، ولا يقع الطلاق، والحمد لله.\nأما إن كان قصدك إيقاع الطلاق إن ركبت سيارة أبيك فإنه يقع طلقة على زوجتك؛ لأن الثلاث بكلمة واحدة تعتبر واحدة في أصح قولي العلماء، ويكون جماعك لها بعد ذلك مراجعة ويقع عليها طلقة إن كان لم يسبقها شيء، فإن كان سبقها طلقة تضاف إلى الطلقة السابقة، أما إن كان سبقها طلقتان، فهذه تكون الطلقة الثالثة، ولا تحل لك إذا أردت إيقاع الطلاق، أما إن كنت ما أردت إيقاع الطلاق وإنما أردت منع نفسك من ركوب سيارة الوالد، وحث نفسك على شراء السيارة الجديدة، فهذا مثل ما تقدم حكمه حكم اليمين، وعليك كفارة اليمين وزوجتك معك، لا يقع عليها طلاق، والحمد لله. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7457/حكم-من-حلف-بالطلاق-على-عدم-فعل-شيء-ثم-فعله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_236/23603.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":9301,"question":"وهذه رسالة وردت إلى البرنامج من يوسف محمد با بكر سوداني مقيم في المملكة في تربة ... يقول: لقد حلفت قبل سنة بكلمة علي الطلاق، وذلك لابن أخي حيث يريد أن يذهب إلى مكان لا أريده أن يذهب إليه، وقد رفض الرجوع واستمرت المقاطعة مدة سنة كاملة بيننا ثم أرسل إلي ..الشيخ: ماذا قال؟ أعد؟المقدم: قال: عليه الطلاق، وهو يريد يمنع أن ابن أخيه..الشيخ: اقرأ كما قال؟المقدم: بكلمة علي الطلاق لا يدي ولا يدك إذا لم ترجع معي، وكانت ذلك لابن أخي وهو يريد أن يذهب إلى مكان كنت لا أريده أن يذهب إليه، ورفض الرجوع معي واستمرت المقاطعة مدة سنة كاملة لا سلام ولا كلام بيننا وبعدها أرسل ابن أخي خطاباً يطلب مني أن أسامحه، وعند قراءة الخطاب، تأثرت وكبتت له بالمسامحة، وأعرفكم بأني متزوج بامرأتين، فهل يقع الحلف على الاثنتين، أم على واحدة، أفيدوني أفادكم الله؟","title":"حكم من حلف على شخص بالطلاق ألا يفعل شيئاً ففعله","answer":"الجواب: هذا فيه تفصيل، إن كنت أردت بهذا الطلاق منعه من الذهاب إلى الجهة التي تريد منعه منها، وأن يرجع إلى قولك، ليس قصدك إيقاع الطلاق، وإنما قصدت تخويفه والتشديد عليه لعله يوافق ولعله يترك ما أردت تركه له، هذا حكمه حكم اليمين، وعليك كفارة اليمين في مسامحته ولا يقع الطلاق على زوجتيك جميعاً، إذا كان المقصود من هذا هو حثه على الرجوع إلى قولك، وترك ما أراد وليس قصدك إيقاع الطلاق على زوجتيك، فهذا حكمه حكم اليمين، أما إذا كنت أردت بذلك إيقاع الطلاق، وأنك متى سامحته وتركت ما قلت من أجله أن الطلاق يقع على زوجتيك فأنت على نيتك، النبي ﷺ، يقول: إنما الأعمال بالنيات وإنما لكل امرئ ما نوى.\nفإذا كنت أردت إيقاع الطلاق فإنه يقع الطلاق على زوجتيك جميعاً، إلا إذا كنت أردت واحدة منهما فأنت على نيتك أيضاً، أما إذا كان المقصود تخويفه وتحذيره من هذا العمل، ولم ترد أنك متى فعل هذا العمل أنه لا تصالحه وأنك متى صالحته يقع الطلاق على زوجتيك، إذا كنت نويت هذا فأنت على نيتك من وقوع الطلاق، وإذا كنت ما نويت ذلك، وإنما نويت وأردت منعه من هذا العمل، وتخويفه حتى لا يفعل ولم ترد إيقاع الطلاق على زوجتيك فإن الأعمال بالنيات، وعليك كفارة اليمين ولا يقع الطلاق.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7471/حكم-من-حلف-على-شخص-بالطلاق-الا-يفعل-شيىا-ففعله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_236/23612.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":9340,"question":"هذه رسالة وردت من عبدالمنعم أحمد عبدالعزيز مقيم بالدمام يقول: أنا وبعض الإخوة في مجال العمل أحياناً تخرج من أفواهنا ألفاظ عندما نتناقش أو نحتدم في الحديث يقول الواحد منا: علي الطلاق لا أفعل كذا أو أن أفعل كذا، وتتكرر كلمة علي الطلاق، لكن بدون نية الطلاق، أو قصد الزوجة، ولكنه لفظ تعودنا عليه بكثرة، فقد سألنا وقيل سواء كنتم قصدتم أو لم تقصدوا فهي تعتبر طلقة واحدة، أفيدونا أفادكم الله؟","title":"حكم قول علي الطلاق","answer":"الجواب: أولاً: لا ينبغي لكم هذا، أولاً لا ينبغي للمؤمن أن يتخذ الطلاق لهجة له وديدناً له في أكثر كلامه وأحاديثه، ينبغي له أن يحترم الطلاق، وهو أمر شرعي وأمر يتعلق به أحكام، فينبغي له أن يصون لسانه عن ذلك إلا عن قصد وعن نية وعن رغبة، وإلا فليصن لسانه عن ذلك حتى لا تقع الطلقة عليه وهو لا يشعر، أو يقع الطلاق الكثير عليه وهو لا يشعر، يعني: على زوجته، ينبغي له أن يصون لسانه عن ذلك، وأن يبتعد عن إيقاع الطلاق، والكلام فيه إلا عن قصد واضح، يقصد به طلق زوجته إذا طابت نفسه منها، أما إذا تلاعب بالطلاق ويكثر من الطلاق فهذا لا ينبغي له ويخشى عليه من الإثم، لكن الحكم في هذا يختلف، إذا كان قال عليه الطلاق ما يفعل كذا، عليه الطلاق ما يكلم فلان، عليه الطلاق ما يعمل العمل الفلاني، وهو قصده من ذلك منع نفسه من هذا الشيء أن يمنع نفسه، وليس قصده إيقاع الطلاق على زوجته، إنما أراد منع نفسه عليه الطلاق ما يكلم فلان، علي الطلاق أن تأكل هذه الذبيحة، على الطلاق أن تسافر معي، أن تذهب معي إلى فلان، هذا كله في حكم اليمين على الصحيح، وعليه كفارتها إذا لم ينفذ مطلوبه.\nيكون حكمه حكم اليمين فيما ذكره جماعة من أهل العلم وروي عن جماعة من السلف، وعن بعض الصحابة ما يدل على ذلك، وهذا هو الذي قرره أبو العباس ابن تيمية وابن القيم وجماعة وذكروا أنه في حكم اليمين، واحتجوا على هذا بآثار سلفية، وبعض الأحاديث الواردة في هذا الباب.\nوالخلاصة: أن الواجب على هؤلاء عدم التلاعب بالطلاق والحذر من ذلك، فإذا وقع الطلاق بهذه الصيغة، عليه الطلاق ما يفعل كذا، عليه الطلاق أن يكلم فلان، عليه الطلاق أن يسافر، عليه الطلاق أنه ما يأكل عند فلان، وما أشبه هذه الأشياء، فإن نفذ فلا شيء عليه، وإن لم ينفذ بل أخل بما قال فعليه كفارة اليمين إذا كان المقصود هو تنفيذ هذا الشيء أو عدم تنفيذه، ليس المقصود فراق الزوجة، فهو بمثابة لو قال: والله لا أفعل كذا، والله لا أكلم فلان، والله لا أسافر، عليه كفارة اليمين. نعم.\nالمقدم: وإذا كان لا يقصد لا يمين ولا طلاق لكن ألفاظ جرت على اللسان؟\nالشيخ: لابد أن يقصد منع نفسه من شيء، مثل هذا أو حمله على شيء، الناس يستعملونه إما لحملها على شيء، وإلا لمنعها من شيء، هذا هو القاعدة المعروفة عند كما يفعلون مع الضيوف، علي الطلاق أن تأكل الذبيحة، علي الطلاق أن تجلس تأكل كرامتك، علي الطلاق أني ما أكلم فلان لأنه فعل وفعل، عليه الطلاق أنه ما يزور فلان لأنه غضبان عليه وهكذا. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7513/حكم-قول-علي-الطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_238/23809.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":9359,"question":"ننتقل إلى رسالة وصلت إلى البرنامج من أحد الإخوة يقول: عبدالله محمد هلال أخونا رسالته مطولة في الواقع لكنها تحكي قصة يمين بالطلاق، أستأذن سماحة الشيخ في قراءتها كما وردت؟يقول: في لحظة غضب وانفعال قلت لزوجتي التي كانت السبب في هذا الغضب: علي الطلاق ما أنت ذاهبة إلى المدرسة بكرة، وكررت ذلك ثلاث مرات، وأنا لا أدري ما أقول، ولا أقصد الطلاق أبداً؛ لأني أبغضه ولا أعرف أحكامه، بل أريد منعها عن المدرسة، فهي تعمل مدرسة وكان ذلك ليلة أول يوم في العام الدراسي، في الصباح ألحت علي زوجتي بأنه من الضروري الذهاب إلى المدرسة وخاصة في أول يوم من العام الدراسي، فاضطررت إلى توصيلها إلى المدرسة وكلي خوف من الله؛ لأني لا أعرف بالضبط حكم ما قلت: هل هو يمين طلاق أم لا، بسؤالي بعض الإخوة المتفقهين في الدين عن حكم ذلك فأفاد البعض أن هذا حلف بغير الله  ويستوجب الكفارة وهي: إطعام عشرة مساكين أو كسوتهم أو صيام ثلاثة أيام متتابعة، وقد كفرت عن هذا اليمين بإطعام عشرة مساكين، أفيدوني جزاكم الله خيراً، هل ما فعلت وهو إطعام عشرة مساكين صحيح ويكفي، وأن هذا اليمين حلف بغير الله، أم أنه يعتبر يمين طلاق أستغفر الله، إنني أعيش في خوف وفزع وصراع نفسي رهيب، أخشى أن أكون أعيش مع زوجتي في الحرام وأن ما حدث يعتبر يمين طلاق، علماً بأنني ندمت على ذلك ندماً كبيراً وتبت إلى الله وعزمت على عدم العودة إلى ذلك أبداً، إنني أدعو الله أن يبارك فيكم ويكثر من أمثالكم، والسلام عليكم ورحمة الله؟","title":"متى يكون حكم الحلف الطلاق حكم اليمين؟","answer":"الجواب: هذا الطلاق حكمه حكم اليمين، مادمت تقصد منعها ولا تريد إيقاع الطلاق وإنما قصدت منعها من الذهاب إلى المدرسة فهذا حكمه حكم اليمين وقد فعلت الكفارة والحمد لله، ولا حرج عليك في أصح قولي العلماء، ولا يعتبر في حكم الحلف بغير الله، يعني: يكون شرك، لا. ليس في حكم الحلف بغير الله، ولكنه له حكم اليمين من جهة الكفارة فقط، فينبغي لك أن لا تعود إليه؛ لأن الكثير من أهل العلم يرونه يقع به الطلاق، فينبغي لك أن لا تعود إلى ذلك.\nوأما الصواب: فهو الذي فعلته وهو الكفارة هذا هو الصواب، أنه تكفي فيه الكفارة؛ لأنك لم ترد إيقاع الطلاق وإنما أردت منع زوجتك من الذهاب إلى المدرسة فيكفي في هذا كفارة اليمين وهي إطعام عشرة مساكين أو كسوتهم وقد فعلت ذلك، لكن من عجز عن الإطعام والكسوة والعتق فإنه يصوم ثلاثة أيام؛ لأن الكفارة فيها تخيير وفيها ترتيب، فالتخيير هو عتق رقبة أو إطعام عشرة مساكين أو كسوتهم أي واحدة فعلها من هذه الثلاث أي واحدة فعلها كفى، فإن عجز عن الثلاث كلها صام ثلاثة أيام.\nولكن مثلما تقدم ليس هذا حكمه حكم الحلف بغير الله من جهة أنه شرك كما لو قال: والنبي أو والأمانة، أو بالنبي هذا شرك لا يجوز، أما قول: علي الطلاق أو علي الحرام ليس حكمه حكم الحلف بغير الله ولكنه ما ينبغي فعله، ولاسيما الحرام لا يجوز تحريم الإنسان ما أحل الله له، وعليه في هذا كفارة اليمين إذا كان قصد منع من حلف عليه، منع زوجته أو منع غيره كأن يقول: علي الحرام ما أكلم فلان، علي الطلاق ما أكلم فلان، علي الطلاق ما تروحي يا فلانة إلى كذا وكذا، هذا كله حكمه حكم اليمين إذا قصد المنع. نعم.\nالمقدم: بارك الله فيكم، لو افترضنا أنه حصل شيء من المعاشرة الزوجية قبل تكفير اليمين؟\nالشيخ: لا حرج، الكفارة إن شاء قدمها وإن شاء أخرها. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/7523/متى-يكون-حكم-الحلف-الطلاق-حكم-اليمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_156/15605.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":9375,"question":"هل صلاة التسابيح واردة في السنة النبوية، وما الحكم في قائل يقول.. -أو نغفل هذا السؤال سؤال الواقع ربما يكون سيئ سماحة الشيخ-؟الشيخ: لا، لا، هاته لا بأس.المقدم: نعم.الشيخ: لا بأس.المقدم: يقول عليه الطلاق من دينه؟الشيخ: أيش؟المقدم: يسأل عن سائل قال تلكم العبارة؟","title":"حكم من قال عليه الطلاق من دينه","answer":"الجواب: هذا على كل حال كلام منكر، أما صلاة التسابيح فقد اختلف فيها العلماء من صحح حديثها، ومنهم من ضعف أحاديثها، والصواب: أنها ضعيفة وأنها لا تشرع ولا تستحب، هذا الصواب في صلاة التسبيح. وأما هذا الذي قال: عليه الطلاق من دينه ما يفعل كذا وكذا، معناه: عليه الخروج من دينه، وهذا كلام منكر، يقول النبي ﷺ: من حلف بملة غير الإسلام كاذبًا متعمدًا فهو كما قال فالمقصود: أن هذا يجب عليه أن يتوب إلى الله، وأن يحذر مثل هذا الكلام، لا يقول عليه الطلاق من دينه، أو هو كافر أو هو يهودي أو نصراني ما يفعل كذا، أو سوف يفعل كذا أو ما أشبه ذلك، لا، يستعمل غير هذا، يقول: والله لأفعلن كذا، أو والله ما أفعل كذا، يكفي هذا، أما أن يقول: هو يهودي أو نصراني أو عليه الطلاق من دينه إنه ما يفعل كل هذا غلط ومنكر لا يجوز، وتعريض لدينه للذهاب والضياع والردة عن الإسلام نعوذ بالله، فيجب الحذر والتوبة من هذا نسأل الله العافية. نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7539/حكم-من-قال-عليه-الطلاق-من-دينه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_186/18613.mp3","categories":["الأيمان والنذور","نواقض الإسلام"]},{"id":9387,"question":"نذرت أن أعتكف في العشر الأواخر من رمضان في بيت الله الحرام إن تحقق لي غرض أسعى لإنهائه ومرة أخرى قلت: إن تحقق ذلك الأمر أو لم يتحقق فسأعتكف لكني لم أتمكن، ماذا علي؟","title":"نذر نذرا وعجز عنه فماذا عليه؟","answer":"الجواب: إذا كنت نذرت أن تعتكف في رمضان في العشر الأواخر في المسجد الحرام إذا حصل مطلوبك وحصل المطلوب وجب عليك أن تعتكف، فإذا فاتك ذلك فعليك التوبة إلى الله جل وعلا من تقصيرك، وعليك كفارة يمين وعليك الاعتكاف أيضاً ولو في غير رمضان، لقول النبي ﷺ: من نذر أن يطيع الله فليطعه، ومن نذر أن يعصيه فلا يعصه رواه البخاري في الصحيح، فعليك أن توفي بالنذر، وعليك كفارة يمين عن ذهاب الوقت الذي عينته، وعليك أن تستغفر الله وتتوب إليه عن تقصيرك، والله المستعان. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/7551/نذر-نذرا-وعجز-عنه-فماذا-عليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_157/15705.mp3","categories":["الأيمان والنذور"]},{"id":9431,"question":"مستمع مصري يقول: (ي. ق. م) يسأل هذا السؤال، يقول: إنني في يوم حلفت على أختي أنني لا أدخل بيتك خمس سنوات، وعندما كنت مسافرًا قلت لنسيبي: أحضر أختي لكي أسلم عليها خارج البيت في الشارع، وعندما حضرت أختي سلمت عليها وجذبتني إلى داخل البيت، فهل وقع يميني أم لا؟ وكان حلفي هو: علي الطلاق لا أدخل بيتك خمس سنوات، وكنت غضبانا؟","title":"حكم من حلف بالطلاق ألا يدخل بيت أخته ثم دخله","answer":"الجواب: نعم، لما جرتك ودخلت البيت باختيارك ووافقت على الدخول فقد حنثت في اليمين هذه، فإن هذا العمل يسمى يمينًا إذا كنت قصدت منع نفسك من الدخول ولم تقصد إيقاع الطلاق فهذه يمين وقد حنثت فيها وعليك كفارة يمين، ولا يقع الطلاق على زوجتك، إذا كنت إنما قصدت منع نفسك من الدخول وهجر أختك ولم تقصد إيقاع الطلاق على زوجتك، فإن هذا يسمى يمينًا في الحكم الشرعي من جهة الكفارة، ولا يقع الطلاق في أصح قولي العلماء، وزوجتك باقية في عصمتك.\nوالكفارة هي إطعام عشرة مساكين، أو كسوتهم، أو عتق رقبة، وإطعامهم يكون بإطعامهم عشاء أو غداء ولو متفرقين، أو إعطائهم نصف صاع لكل واحد من التمر أو من الرز أو غيرهما من قوت البلد، كل واحد نصف صاع، كيلو ونصف تقريبًا، أو تعطي كل واحد كسوة تجزئه في الصلاة كقميص أو إزار ورداء ويكفي، والحمد لله، مع التوبة والاستغفار عن قطيعتك لأختك، فإن المؤمن يجب عليه أن يصل أن أرحامه، والأخت من أقرب الرحم، وقد صح عن رسول الله عليه الصلاة والسلام أنه قال: لا يدخل الجنة قاطع رحم هذا وعيد عظيم، والله يقول في كتابه العظيم : فَهَلْ عَسَيْتُمْ إِنْ تَوَلَّيْتُمْ أَنْ تُفْسِدُوا فِي الأَرْضِ وَتُقَطِّعُوا أَرْحَامَكُمْ ۝ أُوْلَئِكَ الَّذِينَ لَعَنَهُمُ اللَّهُ فَأَصَمَّهُمْ وَأَعْمَى أَبْصَارَهُمْ [محمد:22-23]، هذا وعيد عظيم أيضًا، فالقطيعة من الكبائر.\nفعليك -يا أخي- أن تتوب إلى الله، وأن تصل أختك، وأن تدع هذا اليمين الخاطئة، وعليك كفارة يمين إذا كنت أردت منع نفسك من الدخول على أختك ولم ترد إيقاع الطلاق.\nأما إن كنت أردت إيقاع الطلاق فإنه يقع طلقة واحدة بدخولك على أختك، ولك أن تراجعها حالًا بإشهاد اثنين أنك راجعت زوجتك، إذا كنت لم تطلقها قبل هذا طلقتين.\nأما إن كنت طلقتها قبلها طلقتين فإن هذه تكون الثالثة، ولا تحل إلا بعد زوج إذا كنت أردت إيقاع الطلاق، أما إن كنت ما أردت إيقاع الطلاق وإنما غضبت على أختك فأردت منع نفسك منها وعدم الدخول عليها ولم ترد أنك لو دخلت فإن الطلاق يقع على زوجتك لم ترد هذا، وإنما في بالك وفي نفسك إنما هو المنع، منع نفسك من الدخول على أختك؛ ولهذا طلقت للتأكيد على نفسك ومنعها من الزيارة لأختك، نسأل الله للجميع الهداية.","link":"https://binbaz.org.sa/fatwas/7596/حكم-من-حلف-بالطلاق-الا-يدخل-بيت-اخته-ثم-دخله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_190/190014.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":9436,"question":"يسأل أيضاً ويقول: بأنه متزوج وله أولاد ويعيش في أحسن حال، فأراد أخوه أن يتزوج من أخت زوجته وهي مطلقة بسبب عدم الخلف كذا يقول، وأنا رفضت وقلت لأهل زوجتي: إذا زوجتم أخي فتكون زوجتي طالق، والنية صادقة في الطلاق إذا حدث زواج، لكن أخي تزوج من هذه المرأة فهل تصبح زوجتي طالق، علماً بأنني لا أريد طلاقها لكن أريد أن أمنعهم من هذا الزواج أفتوني بارك الله فيكم؟","title":"الطلاق المعلق بنية المنع","answer":"الجواب: إذا كان قصدك من ذلك منعه من الزواج وليس قصدك إيقاع الطلاق إن تزوج فعليك كفارة يمين، وليس على زوجتك طلاق، إذا كان هذا قصدك ونيتك أنك قلت هذا حتى يمتنع أخوك، فإن هذا يكون له حكم اليمين وعليك كفارة يمين، وهي إطعام عشرة مساكين أو كسوتهم أو عتق رقبة، فإن لم تستطع هذا كله فعليك أن تصوم ثلاثة أيام.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7609/الطلاق-المعلق-بنية-المنع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_239/23910.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":9462,"question":"وأولى رسائل هذه الحلقة وردتنا من المرسلة (ن. م) من العراق محافظة التأميم تقول في رسالتها: بعد غضب شديد وقع مني دون أن أفقد وعيي حلفت بالله ثلاث مرات: والله والله والله وبالقرآن على أن لا أتزوج طول حياتي، وبما أنه لا رهبانية في الإسلام فماذا علي أن أفعل؟ وما هي الكفارة التي أكفرها عن يميني أرشدوني بارك الله فيكم؟","title":"حكم من حلف أن لا يتزوج مطلقاً","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله رب العالمين، والعاقبة للمتقين، وصلى الله وسلم وبارك على عبده ورسوله وأمينه، نبينا وإمامنا محمد بن عبد الله، وعلى آله وأصحابه ومن سلك سبيله واهتدى بهداه إلى يوم الدين.\nأما بعد: هذه اليمين خاطئة ولا يجوز تنفيذها، فإن المؤمن لا يمتنع من الزواج، بل يسعى في ذلك؛ لقول النبي ﷺ: يا معشر الشباب! من استطاع منكم الباءة فليتزوج، فإنه أغض للبصر، وأحصن للفرج، ومن لم يستطع فعليه بالصوم؛ فإنه له وجاء، وهذا يعم الرجال والنساء فعليك كفارة يمين، وهي إطعام عشرة مساكين أو كسوتهم أو تحرير رقبة، فمن عجز عن ذلك فعليه صيام ثلاثة أيام ولو كانت اليمين مكررة، ولو كررت اليمين مرات كثيرة، بالله أو بصفة من صفاته أو بالقرآن؛ لأن القرآن كلام الله، هذه اليمين وإن كررت مرات كثيرة، ولو في أيام كثيرة ولو في أعوام كلها حكمها حكم اليمين الواحدة، فعليك كفارتها وهي كما تقدم إطعام عشرة مساكين من الفقراء، كل مسكين له نصف الصاع تمر أو رز أو غيرهما من قوت البلد، ومقداره كيلو ونصف تقريباً تدفع إلى عشرة، أو كسوة لكل واحد إزار ورداء أو قميص، أو عتق رقبة مؤمنة من ذكر أو أنثى، فمن عجز عن ذلك بأن كان فقيراً لا يستطيع الإطعام ولا الكسوة ولا العتق، فإنه يجزئه أن يصوم ثلاثة أيام، والحمد لله. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7622/حكم-من-حلف-ان-لا-يتزوج-مطلقا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_240/24001.mp3","categories":["الأيمان والنذور"]},{"id":9465,"question":"المستمع شيخون حنفي محمد مصري الجنسية ويعمل بالمملكة في جدة، بعث برسالة إلى البرنامج يقول فيها: لقد سرقت لي سلسلة من الذهب في البيت، وقد حلفت على زوجتي بالطلاق وقلت لها: بأنت محرمة علي إذا لم توجد السلسلة، ثم إنني عرفت بأنها بريئة وأن سارقًا هو الذي سرق السلسلة، أرجو الإفادة جزاكم الله خيرًا فيما صدر مني؟","title":"كفارة الظهار","answer":"الجواب: هذا فيه تفصيل:\nوفي الحقيقة أنك استعجلت، ولكن هذا فيه تفصيل: فإن كنت أردت أنها محرمة عليك ولو لم تكن عندها السلسلة، وأنها إذا لم تحضر السلسلة فهي محرمة عليك لأنك ظننت أنها عندها وأنها خانتك فيها، فلو كنت جازمًا بهذا وأنها حرام عليك إلا أن تؤدي السلسلة فهذا حكمه حكم الظهار وعليك كفارة الظهار، وهي عتق رقبة مؤمنة ذكر أو أنثى، فإن لم تجد صمت شهرين متتابعين، فإن لم تستطع أطعمت ستين مسكينًا لكل مسكين نصف صاع تكون من قوت البلد من تمر أو أرز أو غيرهما قبل أن تمسها، قبل أن تتصل بها، هذا هو الواجب عليك ؛ لأن هذا في حكم الظهار.\nأما إن كنت ما أردت تحريمها وإنما أردت تشجيعها على البيان والإيضاح، وأنك تتهمها بهذا لكن تريد من هذا الكلام حثها على البيان وعلى رد السلسلة ولم ترد تحريمها، ولكن أردت تخويفها أو تحذيرها من الكتمان، وحثها على البيان فهذا حكمه حكم اليمين، وعليك كفارة اليمين وتكفي، وهي إطعام عشرة مساكين لكل مسكين نصف صاع من قوت البلد، من تمر أو أرز أو حنطة أو غير ذلك، أو كسوتهم بما يجزئهم في الصلاة كقميص أو إزار ورداء، أو عتق عبد أو أمة مؤمنة، هذا هو الكفارة، هذه هي الكفارة للظهار، فإذا عجز الحالف عن هذه الكفارة ولم يكن عنده قدرة صام ثلاثة أيام.\nوأسأل الله لنا ولك الهداية. نعم.","link":"https://binbaz.org.sa/fatwas/7625/كفارة-الظهار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_191/19109.mp3","categories":["الظهار","الطلاق","الأيمان والنذور"]},{"id":9495,"question":"وهذه رسالة وردت إلى البرنامج من محمود أبو بكر عبدالجواد مصري الجنسية، يعمل في بريدة في القصيم، يقول: حصل مناقشة وكلام في وقت غضب بيني وبين زوجتي، فأردت أن أتهجم عليها فكان الناس يمنعونني عن التهجم عليها، فقلت لهم: (إن عيشتها معي حرام) ثلاث مرات، ولكن بدون أي حلفان يمين وهي تعيش معي، فهل علي كفارة في هذا، أفيدوني أفادكم الله؟","title":"حكم من قال لزوجته: إن عيشتي معك حرام","answer":"الجواب: عليك عن هذا كفارة يمين، قولك: (إن عيشتها معك حرام) عليك أن تكفر كفارة يمين عن هذا الأمر، ولا يضرك شيء بعد ذلك؛ لأن هذا حكمه حكم اليمين، تكفر كفارة يمين وهي إطعام عشرة مساكين أو كسوتهم أو عتق رقبة، وإطعامهم معناه أن يعطى كل واحد نصف صاع من التمر أو الأرز أو غيرهما من قوت البلد، ونصف الصاع كيلو ونصف تقريباً، ويكفي هذا والحمد لله، وعليك التوبة والاستغفار؛ لأن المسلم لا يحرم ما أحل الله له. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7662/حكم-من-قال-لزوجته-ان-عيشتي-معك-حرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_242/24205.mp3","categories":["الأيمان والنذور"]},{"id":9528,"question":"يقول أخيراً في رسالته: هل يقع الطلاق على المرأة وأنا في خارج البيت وفي عملي، وحلفت بالطلاق على فعل شيء أو تركه ووقعت في ما حلفت فيه؟ فهل يقع الطلاق بالرغم أن المرأة لم تسمع هذا الكلام؟ وهل هناك فرق بين الطلاق في غيبة المرأة أو في حضورها؟","title":"حكم وقوع الطلاق في غياب الزوجة.","answer":"الجواب: ليس من شرط وقوع الطلاق أن تحضر.. يقع الطلاق في غيبتها وفي حضورها لو طلقها في بلاد بعيدة وقع الطلاق، فليس من شرط الطلاق أن تكون حاضرة، ولكن الطلاق المعلق على شيء يختلف، فإذا كان المعلق عليه شيئاً يقصد منعه أو حصوله أو التصديق أو التكذيب فهذا له حكم اليمين على الصحيح من أقوال العلماء له حكم اليمين يكفر كفارة يمين ولا يقع الطلاق كأن يقول: عليه الطلاق ما يكلم فلان، عليه الطلاق أن لا يسافر في يوم كذا، عليه الطلاق أن لا تخرجي إلى أهلك، عليه الطلاق أن لا تكلمي فلاناً أو فلانة يقصد من هذا منعها من الكلام أو الخروج، كونه يقصد من قوله: (عليه الطلاق أن لا يسافر) منع نفسه من السفر وما أشبه ذلك فهذا حكمه حكم اليمين عليه الكفارة وهي إطعام عشرة مساكين أو كسوتهم ولا يقع الطلاق على زوجته، أما إذا كان قصده إيقاع الطلاق قال هذا الكلام مقصوده التخويف من هذا الشيء ولكنه يقصد وقوع الطلاق قال: علي الطلاق أن لا تخرجي إلى بيت أهلك، علي الطلاق أن لا تكلمي فلاناً هو يقصد منعها ويقصد إيقاع الطلاق إذا فعلت، فإنه يقع الطلاق عليها. نعم.\nالمقدم: بارك الله فيكم وجزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/7699/حكم-وقوع-الطلاق-في-غياب-الزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_245/24511.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":9550,"question":"هذه رسالة وردت إلينا من كمال كامل حسن مصري الجنسية يعمل في الدمام بالمملكة، يقول في رسالته: يوجد عندنا في مصر مشايخ عندما يحلف الرجل بالطلاق يذهب لهذا الشيخ ويضع يده في يده، ويقول له كلام وهو يردده، وبعد ذلك يقول له: خلاص قد حل اليمين، الرجاء أن تفيدونا عن صحة هذا بارك الله فيكم؟","title":"مسألة في الحلف بالطلاق","answer":"الجواب: هذا الكلام الذي ذكرته أيها السائل غير معقول! وضع اليد في اليد والكلام الذي يقوله الأستاذ أو العالم، مجرد كلام يقوله تقول: حل الطلاق هذا ليس بمعقول! ولا يعرف وجهه، لكن إذا كان يستفتيه فأفتاه بأن يفعل كذا ويفعل كذا يفتيه على الوجه الشرعي، يقول له: طلاقك هذا واقع أو طلاقك غير واقع؛ لأن شروط وقوعه لم تتوفر هذا محل نظر، يعني: لا بد يعرف وايش يقول الأستاذ حين وضع يده في يده ماذا يقول له؟ ماذا أفتاه به؟ كيف وقع الطلاق؟ لا بد من تفصيل.\nفإذا كان المستفتي سأل العالم أنا قلت لامرأتي: أنت طالق إن فعلت كذا، إن كلمت فلاناً، فقال له العالم: إذا كانت ما كلمت فلان ما صار طلاق، هذا صحيح.\nأو قال: أنت طالق إن أكلت كذا، أو إن شربت كذا فلم تشرب ولم تأكل هذا الشيء الذي منعها منه، ما وقع الطلاق.\nأو قال لها: أنت طالق إن زرت آل فلان يقصد منعها، فقال له العالم: عليك كفارة يمين، إذا كان قصده منعها على الصحيح من أقوال العلماء فيه كفارة يمين حكمه حكم اليمين؛ لأنه ما أراد إيقاع الطلاق وإنما أراد منعها من الزيارة مثلاً، فهذا فيه كفارة اليمين عند جمع من أهل العلم وهو الصواب، فالحاصل أنه لا بد من تفصيل، ومعرفة ماذا يقول العالم لهذا المستفتي، أما وضع اليد على اليد وقراءة شيء، أو اختار كلامًا ليس له تعلق بالفتوى، فهذا لا يحل شيئاً، ولا يترتب عليه إزالته حكم الطلاق. نعم.\nالمقدم: أثابكم الله.","link":"https://binbaz.org.sa/fatwas/7715/مسالة-في-الحلف-بالطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_255/25512.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":9551,"question":"هذه رسالة وردت من جمال عبدالباسط مصري الجنسية مقيم بالمملكة يقول: أنا أشرب الدخان وقد قلت: علي الطلاق، ثم علي الطلاق، ثم علي الطلاق، أن لا أشرب الدخان مرة أخرى، ثم شربته أفيدوني ما الحكم بارك الله فيكم؟","title":"حكم الحلف بالطلاق بقصد منع النفس من شيء ما","answer":"الجواب: أولاً: يا أخي! ننصحك بأن تدع الدخان؛ لأنه خبيث ومضر ضرره عظيم، فالواجب عليك تركه وأن تستعين بالله على ذلك، وأن تتعاطى الأمور التي تعينك على ذلك، حسب الطاقة، وأن تستفيد من الأطباء في ذلك لعلهم يفيدونك بشيء يعينك على تركه.\nأما هذا الطلاق فأنت فيه بين أمرين: إن كنت نويت فراق أهلك بالطلقات الثلاث إن شربت الدخان، فقد طلقت زوجتك ثلاث طلقات، إذا كنت نويت إيقاع الطلاق الثلاث عليها بهذا الكلام إذا شربت الدخان. أما إذا كنت لا، إنما أردت منع نفسك تقصد من هذا أن تمنع نفسك من الدخان، ما قصدت إيقاع الطلاق، ولا تريد الطلاق، ولكن تريد أن تمنع نفسك وأن تشدد على نفسك لعلك تتركه، لعلك تسلم من شره، فهذا له حكم اليمين، فعليك كفارة اليمين وهي إطعام عشرة مساكين أو كسوتهم، هذا هو الذي عليك ولا يقع الطلاق؛ لأنه لم يرد ولم يقصد وإنما أردت منع نفسك من الدخان، فإذا شربته فعليك التوبة إلى الله؛ لأنه محرم وعليك كفارة اليمين؛ لأنك ما قصدت إيقاع الطلاق وإنما قصدت منع نفسك من هذا الدخان، فعليك كفارة اليمين وهي كما تقدم إطعام عشرة مساكين لكل مسكين نصف صاع من قوت البلد من تمر أو أرز أو غيرهما، وهو كيلو ونصف تقريباً، أو كسوتهم بما يجزئهم في الصلاة كالقميص، أو إزارٍ ورداء، أو عتق رقبة لو وجدت الرقاب عتق رقبة، هذه كفارة اليمين. فمن عجز عن ذلك لأنه فقير لا يستطيع الإطعام ولا الكسوة ولا العتق فإنه يجزئه صيام ثلاثة أيام كما بين الله ذلك في كتابه العظيم في سورة المائدة. نعم.","link":"https://binbaz.org.sa/fatwas/7716/حكم-الحلف-بالطلاق-بقصد-منع-النفس-من-شيء-ما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_255/25513.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":9552,"question":"أولى الرسائل وردت من محمد الباز مصري الجنسية يعمل في الأردن يقول: بأنه متزوج منذ عشر سنوات ولديه ثلاثة أولاد، ولكن حصل منه أيمان بالطلاق منها يمين بالطلاق على أن يتزوج ولو آخر يوم في عمره، يقول: وقد كنت غاضباً ولم أشعر كيف حلفت بهذا اليمين، وبعد عشرين يوم حلفت يميناً آخر بالطلاق على زوجتي أن أطلقها ولم أحدد متى أطلقها، وكنت غاضباً ولم أشعر كيف حلفت هذا اليمين. أفيدوني أفادكم الله، مع أنني لن أطلق ولن أتزوج بارك الله فيكم؟","title":"حكم من حلف بالطلاق على زوجته أن يطلقها ولم يحدد متى يطلقها","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله رب العالمين، والعاقبة للمتقين، والصلاة والسلام على عبده ورسوله وصفوته من خلقه وأمينه على وحيه نبينا وإمامنا وسيدنا محمد بن عبد الله، وعلى آله وأصحابه ومن سلك سبيله واهتدى بهداه إلى يوم الدين.\nأما بعد: فهذا الطلاق على أنك تتزوج وعلى أنك تطلق فيه تفصيل: فإن كنت أردت فراقها وإيقاع الطلاق إن لم تتزوج وقع طلقة في آخر حياتك ولك مراجعتها، ولا يقع الآن شيء لأنك قلت ولو في آخر حياتك، فإذا جاء في آخر الحياة قبل أن تموت بقليل تقع الطلقة إن كنت أردت إيقاع الطلاق، أما إن كنت ما أردت إيقاع الطلاق وإنما أردت حث نفسك على الزواج أو تكدير زوجتك وأنت ما أردت إيقاع الطلاق إنما أردت حث نفسك على الزواج فهذا في حكم اليمين عليك كفارة يمين ويكفي، أو إطعام عشرة مساكين أو كسوتهم، وهكذا قولك: عليك الطلاق أنك تطلقها، إذا كان مقصودك حث نفسك على أن تطلق وليس مقصودك إيقاع الطلاق إن لم تطلق فإن عليك كفارة يمين مثلما تقدم إطعام عشرة مساكين أو كسوتهم، عشرة، كل مسكين.. نصف الصاع تمر أو رز أو غيره من قوت البلد، أما إن كنت أردت إيقاع الطلاق في وقت معين نويته إن لم تطلقها فإنها طالق بهذه النية يقع طلقة إذا كنت نويت ذلك وإلا فالواجب كفارة يمين. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7717/حكم-من-حلف-بالطلاق-على-زوجته-ان-يطلقها-ولم-يحدد-متى-يطلقها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_270/27001.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":9579,"question":"أولى الرسائل في هذه الحلقة وردت من صلاح أحمد محمد، مصري الجنسية مقيم بالمملكة الأردنية الهاشمية يقول: حلفت بالطلاق وأنا في شبه الغضب على أن أسافر إلى مصر في رمضان المقبل، فهل إذا جاء رمضان المقبل وكان في العمر بقية ولم أسافر هل تعتبر طلقة؟ وإذا كانت تقع وسافرت فهل ترتفع، أفيدوني أفادكم الله؟","title":"من حلف بالطلاق أن يسافر هل يقع لو سافر؟","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فهذا الطلاق المعلق فيه تفصيل: فإن كنت أيها السائل أردت بذلك التأكيد على نفسك وحثها على السفر، ولم ترد إيقاع الطلاق على زوجتك إن لم تسافر فهذا حكمه حكم اليمين في أصح قولي العلماء، وعليك كفارتها إن لم تسافر ولا يقع شيء، وزوجتك باقية في عصمتك، هذا إذا كنت إنما أردت التأكيد على نفسك وحثها على السفر في رمضان.\nأما إن كنت أردت إيقاع الطلاق إن لم تسافر فإنه يقع طلقة على زوجتك واحدة، ولك مراجعتها في الحال بإشهاد اثنين من المسلمين الطيبين على أنك راجعت زوجتك فلانة، تخبرهم بالواقع وتقول: راجعتها، إلا إذا كنت قد طلقتها قبلها طلقتين فهذه تكون الثالثة ما فيها مراجعة، أما إذا كنت ما طلقتها قبل هذا طلقتين فإنك تراجعها إذا كنت أردت إيقاع الطلاق إن لم تسافر. والله أعلم. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7744/من-حلف-بالطلاق-ان-يسافر-هل-يقع-لو-سافر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_248/24801.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":9607,"question":"يسأل أيضاً ويقول: في كفارة اليمين، هل يصح أن أعطي رجلاً يعول أسرةً فقيرةً ما يكفي لإطعام هذه الأسرة إذا كانت مكونة من خمسة أو ستة أو عشرة أشخاص من كبير وصغير؟ وهل تكفي وجبة واحدة أم قوت يوم كامل، أفيدونا بارك الله فيكم؟","title":"حكم إعطاء كفارة اليمين لأقل من عشرة مساكين","answer":"الجواب: الواجب نصف صاع لكل واحد من قوت البلد من تمر أو أرز أو حنطة أو غير ذلك، فإذا كان أهل البيت خمسة وهم فقراء أعطاهم النصف نصف الكفارة، والتمس آخرين يعطيهم النصف الثاني، وإذا كانوا سبعة أعطاهم حصة السبعة، والتمس ثلاثةً آخرين حتى يعطيهم البقية، ولا يعطيهم الجميع لا يعطي السبعة والخمسة الجميع، لا، يعطيهم حصتهم حتى يكمل السبعة، وإذا كان في البيت سبعة فقراء أعطاهم إياها كلها. نعم.\nالمقدم: عشرة وإلا سبعة يا شيخ؟\nالشيخ: إذا كان في البيت عشرة فقراء أعطاهم الكفارة كلها، وإذا كانوا سبعة أعطاهم حصة السبعة والتمس ثلاثة آخرين ولو من بيت آخر، أو من السائل عند الأبواب. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7778/حكم-اعطاء-كفارة-اليمين-لاقل-من-عشرة-مساكين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_249/24906.mp3","categories":["الأيمان والنذور"]},{"id":9617,"question":"الرسالة التالية وصلت من المستمع بلّه إدريس سوداني مقيم في المملكة يقول في رسالته: لي أصدقاء أعزاء علي ودامت بيني وبينهم صداقة دامت عدة أعوام، وكنت أزورهم في منزلهم كل صباح، علمًا أنهم ليس لي بهم صلة رحم بل صداقة وأتردد عليهم كثيرًا، وطبعًا بدون أي قصد علاقة شريفة، وفي يوم من الأيام واجهتني مشكلة من شخصين لهم صلة بأصدقائي، أي أقصد الأسرة التي كنت أتردد في زيارتهم، فقالوا لي: لماذا تتردد على أهلنا؟ أنت عندك قصد غير شريف، فتلون وجهي وتشردت أفكاري، علمًا بأنني متزوج وعند وصولي إلى منزلي سألتني زوجتي لماذا تلون وجهك وكنت اليوم غير طبيعي؟ شرحت لها الموقف وحلفت أمامها ألا أزور أصدقائي في منزلهم مرة أخرى، علمًا بأنني أعمل في المملكة العربية السعودية ووصلني من هؤلاء الأصدقاء ثلاث خطابات ولكن مشكلتي هي أنني حلفت بالحرام أي علي الحرام ألا أصل هؤلاء الأشخاص في منزلهم، فما رأي الدين في ذلك أفيدونا أفادكم الله؟","title":"حكم من أقسم بالحرام على نفسه ألا يفعل ثم فعل","answer":"الجواب: مادام الأمر على ما قلت وأنك تزورهم لله وفي الله محبة في الله وليس هناك أسباب محرمة، وإنما زيارة محبة وزيارة شريفة ليس فيها محظور شرعًا فإنه لا حرج عليك أن تزورهم وعليك كفارة يمين عن التحريم إذا قلت: علي الحرام ألا أزورهم إذا كنت قصدت منع نفسك في زيارتهم فعليك كفارة يمين وهي إطعام عشرة مساكين لكل مسكين نصف صاع من قوت البلد من تمر أو رز أو غيره أو تكسوهم كسوة على قميص أو على إزار ورداء ويكفي هذا، هذا إذا كان قصدك منع نفسك من زيارتهم.\nأما إذا كان المقصود تحريم زوجتك وأنها حرام عليك إن زرتهم قصدت هذا فعليك أن تعتق عبد أو عبدة، فإن لم تستطع تصوم شهرين متتابعين، فإن لم تستطع تطعم ستين مسكينًا ثلاثين صاع ستين مسكينًا ثلاثين صاعًا كل صاع بين اثنين كل واحد له نصف الصاع قبل أن تمسها، هذا إذا كان قصدك تحريمها، أما إذا كان المقصود إنما هو منع نفسه من زيارتهم شددت على نفسك بهذا لتمتنع من زيارتهم ما قصدت تحريم زوجتك فهذا يكفي كفارة يمين والحمد لله. نعم.","link":"https://binbaz.org.sa/fatwas/7777/حكم-من-اقسم-بالحرام-على-نفسه-الا-يفعل-ثم-فعل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_193/19313.mp3","categories":["الأيمان والنذور"]},{"id":9618,"question":"بارك الله فيكم، تقول هذه السائلة: كنت طالبةً في المدرسة، وقد بلغت البلوغ الشرعي، فخرجت من الامتحان وأنا خائفة من الرسوب، فقلت: نذرت إن نجحت في الامتحان سوف أصوم، ونسيت هل قلت: شهرين، أم ثلاثة، ولم أعرف، هل قلت: متتابعة، أم لا، وفعلًا لم أنجح في الدور الأول، علماً أنني قصدت النجاح أو الرسوب في الدور الأول، فرسبت في الدور الأول، واختبرت في الدور الثاني فنجحت، أرجو إفادتي هل يلزمني الصوم، بارك الله فيكم؟","title":"الشك في النذر المشروط","answer":"الجواب: إذا كانت النية في الدور الأول ولم تنجحي إلا في الدور الثاني فليس عليك شيء (المسلمون على شروطهم)، وأما إذا كنت أردت في الدور الأول أو الثاني، فعليك أن تصومي شهرين؛ لأنها متيقنة، مادام عندك شك شهرين أو ثلاثة، تصومين شهرين وليس عليك متابعة، مادمت ما عندك جزم بنية المتابعة، ستين يوماً ولو متفرقة، لكن المتابعة أفضل وأولى، لكن ما دمت نويت النجاح في الدور الأول -في الفصل الأول- فليس عليك شيء؛ لأن المقصود لم يحصل. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7779/الشك-في-النذر-المشروط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_271/27106.mp3","categories":["الأيمان والنذور"]},{"id":9630,"question":"هذه رسالة من سعيد السيد حسن من جمهورية مصر العربية مقيم في ...... في المملكة، يقول: في يوم من الأيام تشاجرت مع زوجتي وقلت لها: علي الطلاق بالثلاث لن تبيتي هنا، يعني: في بيت الزوجية، ولكن أصرت على البقاء لظروف خلاف مع والديها بسببي، وهجرتها لمدة عشرة أيام ثم جامعتها فهل علي إثم؟ وهل علي كفارة يمين أم أن هذا طلاق أفيدوني أفادكم الله؟","title":"حلف بالطلاق لمنع زوجته من المبيت عند والدها","answer":"الجواب: هذا الطلاق، وأشباهه يختلف بحسب النية؛ لقول النبي ﷺ: إنما الأعمال بالنيات وإنما لكل امرئ ما نوى فإن كان قصدك أيها السائل! منعها من المبيت ولم تقصد إيقاع الطلاق، وإنما أردت منعها وتحذيرها وتخويفها لعلها تخرج وتبيت خارج البيت، فهذا حكمه حكم اليمين وعليك كفارة اليمين.\nأما إن كنت أردت إيقاع الطلاق إن لم تخرج فإنه يقع عليها طلقة ولك مراجعتها، وجماعك لها بنية الرجعة رجعة، إلا أن تكون قد طلقتها قبل هذا طلقتين فهذه تكون الثالثة فلا تحل إلا بعد زوج؛ لقول الله جل وعلا: فَإِنْ طَلَّقَهَا [البقرة:230] يعني: الثالثة فَلا تَحِلُّ لَهُ مِنْ بَعْدُ حَتَّى تَنكِحَ زَوْجًا غَيْرَهُ [البقرة:230].\nفالواجب عليك النظر في هذا الأمر، وخوف الله  ومراقبته، فإن كانت الطلقة هذه هي الأخيرة وقبلها طلقتان وأنت قصدت إيقاع الطلاق فقد تمت الثلاث، أما إن كنت ما قصدت إيقاع الطلاق وإنما نويت إلزامها بالخروج وعدم المبيت وتخويفها بالطلاق، فهذا له حكم اليمين، في أصح قولي العلماء وعليك كفارة اليمين وهي إطعام عشرة مساكين لكل مسكين نصف صاع من قوت البلد من تمر أو أرز أو حنطة أو غيرها من قوت البلد، أو كسوتهم تكسو كل واحد قميصاً أو إزاراً ورداء، أو عتق رقبة. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7801/حلف-بالطلاق-لمنع-زوجته-من-المبيت-عند-والدها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_250/25009.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":9635,"question":"وهذه رسالة من الأخ حسن عوض من جمهورية مصر العربية يقول فيها: إنني مقيم في الأردن، أما مشكلتي فهي أنني عندما عزمت على السفر إلى الأردن أقسمت يمينًا قاطعًا على نفسي بأنني لن أدخن طوال مدة غيابي في الأردن، وقد وضعت القرآن الكريم على جبهتي وبعد ذلك وجدت نفسي أنني أدخن، فما حكم الإسلام في ذلك أرشدونا أفادكم الله؟","title":"حكم من أقسم على الامتناع من التدخين ثم دخن","answer":"الجواب: عليك التوبة إلى الله لأن التدخين محرم ولا يجوز ضرره كثير وعظيم، فعليك يا أخي أن تتوب إلى الله وأن تندم على ما فعلت وأن ..... أن لا تعود في ذلك وعليك كفارة يمين عن حنثك: إطعام عشرة مساكين أو كسوتهم؛ عشرة تطعمهم على نصف صاع تمر أو رز أو تعشيهم أو تغديهم أو تكسوهم كسوة ويكفي هذا، وعليك التوبة إلى الله عن التدخين والحذر منه لأن شره كثير ومضاره عظيمة هداك الله وأرشدك.","link":"https://binbaz.org.sa/fatwas/7796/حكم-من-اقسم-على-الامتناع-من-التدخين-ثم-دخن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_193/19314.mp3","categories":["الأيمان والنذور"]},{"id":9665,"question":"وهذا الأخ أبو رائد من الرياض أرسل إلينا هذه الرسالة يقول فيها: لقد نذرت نذراً أن أصوم خمسة أيام لله تعالى كلما شربت سيجارة دخان، وذلك من باب الامتناع عنه، وقد نذرت هذا النذر وأنا في حالة ليست بالغضب الكامل وأعي ما أقول ومصمم على النذر، ومرت الأيام لكن لم أستطع مقاومة شيطان الرغبة إلى الدخان، وشربت أول سيجارة وصمت الخمسة أيام بعد ذلك، فهل هذا الصيام يمحو النذر الأول أم أنني كلما شربت سيجارة بعد ذلك لزمني أن أصوم عنها خمسة أيام؛ لأنني قد شربت الكثير، ولا أستطيع حصرها تصل إلى مئات السجائر وأنا قادر على الإطعام والكسوة لأي عدد من الفقراء، أما الصيام فإنني لا أستطيعه ليس لصحتي ولكن لانشغالي في عملي، أصبحت في حيرة من أمري أفيدوني أفادكم الله؟","title":"حكم من نذر أن يصوم خمسة أيام كلما شرب سيجارة","answer":"الجواب: أسأل الله أن يهديك ويعيذك من الشيطان حتى تدع هذا الخبيث وهو التدخين، وتسلم من شره الديني والدنيوي، أما هذا النذر وهو أنك نذرت إن شربت الدخان أن تصوم خمسة أيام فأنت بالخيار، إن شئت صمت الخمسة وإن شئت كفرت كفارة يمين؛ لأن مقصودك الامتناع من هذا الخبيث، فهو نذر في حكم اليمين، فأنت مخير إن صمت الأيام كفت، وإن تركت الصيام فعليك كفارة يمين وهي إطعام عشرة مساكين لكل مسكين نصف صاع من قوت البلد من التمر أو الأرز أو الحنطة، أو الذرة أو الشعير حسب قوت البلد، أو تكسوهم كسوة على كل واحد له قميص أو إزار ورداء عشرة، يكفي عن الصيام، ولا يلزمك صيام آخر متى فعلت التدخين مرة أخرى تكفي المرة الأولى، إذا كنت قلت: إن شربت السيجارة صمت خمسة أيام، فهذا يكفيك الصوم الأول أو الكفارة الأولى، هذا هو الواجب.\nأما إذا كنت قلت: كلما شربت فعليك صوم.. إذا كنت قلت هذا الكلام كلما شربت صمت خمسة أيام، هذا كلما شربت عليك كفارة يمين، أو صوم، إما أن تصوم وإما تكفر كفارة يمين؛ لأنك قلت: كلما فهذا ينطبق على كل شيء يأتي في المستقبل، فالواجب عليك أن تتقي الله وأن تدع هذا الخبيث وتجتهد وتأخذ من الأطباء ما يعينك على تركه؛ لأنه مضر بدينك ودنياك ومحرم، لا يجوز شربه ولا بيعه ولا شراؤه ولا التجارة فيه، فاتق الله وحاسب نفسك، وجاهدها لله سبحانه وتعالى، واعرف الفتوى، الفتوى على التفصيل الآتي:\nأولاً: إذا كنت قلت: إن شربت فعلي صيام خمسة أيام، فهذا فيه الخيار بعدما شربت الشربة الأولى السيجارة الأولى بعدما شربتها أنت مخير إن شئت صمت وقد صمت والحمد لله وانتهى الأمر، وإذا عدت فليس عليك شيء، ولو أنك كفرت كفارة يمين كفى عن الصيام؛ لأن هذا النذر في حكم اليمين، وليس من باب القرب؛ لأن المقصود منه الزجر لنفسك، والمنع لها من التدخين وليس القصد التقرب بالصيام، إنما القصد منع نفسك؛ لأنك متى ذكرت أنك عليك صيام امتنعت، ولكن الشيطان غلبك حتى فعلت هذا التدخين، فينبغي أن تغلب عدو الله جاهده واغلبه واستعن بالله حتى تدع هذا الخبيث وحتى تسلم من مضاره الكثيرة.\nأما إن كنت قلت: كلما شربت صمت خمسة أيام، فهذا يلزمك كلما شربت تصوم، أو تكفر كفارة يمين، أحد الأمرين، أنت مخير، كلما شربت سيجارة فعليك أن تصوم خمسة أيام أو تكفر كفارة يمين بإطعام عشرة مساكين أو كسوتهم، والله ولي التوفيق. نعم.\nالمقدم: بارك الله فيكم، يعني: العبارة الاختلاف في الفتوى هو أن العبارة الأولى: مرة واحدة تكفي؟\nالشيخ: نعم.\nالمقدم: والعبارة الثانية: كلما إذا تكرر الحدث تكرر الصيام أو كفارة يمين.\nالشيخ: نعم، أو كفارة يمين.\nالمقدم: أثابكم الله.","link":"https://binbaz.org.sa/fatwas/7825/حكم-من-نذر-ان-يصوم-خمسة-ايام-كلما-شرب-سيجارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_251/25107.mp3","categories":["الأيمان والنذور"]},{"id":9671,"question":"الرسالة التالية وصلت من الأخ السيد نصر أحمد سعيد والأخ خالد أحمد علام من جمهورية مصر العربية ومقيمين بالأردن- عمان الرسالة تحتوي على موضوعين السؤال الأول يقول فيه: ما رأيكم في رجل حلف يمين طلاق واحد بالثلاثة على أخ مسلم آخر يعمل شيئًا ما ولكن الشيء لم ينفذ، فهل اليمين يعتبر نافذة في حد ذاته على امرأته؟ وما حكم الإسلام إذا لم ينفذ بذلك اليمين في حد ذاته أفيدونا أفادكم الله؟","title":"حكم الحلف بالطلاق بالثلاث وعدم إنفاذه","answer":"الجواب: إذا حلف الإنسان بالطلاق الثلاث على أن فلان يفعل كذا ويفعل كذا كأن يقول: علي الطلاق بالثلاث أن تكلم فلان، علي الطلاق بالثلاث أن تصنع الوليمة الفلانية، علي الطلاق مثلًا أن تتزوج فلانة، فهذا ينظر في قصده، فإن كان قصده التلزيم والتأكيد وليس قصده إيقاع الطلاق فهذا يكون حكمه حكم اليمين فيه كفارة اليمين إطعام عشرة مساكين أو كسوتهم أو تحرير رقبة فإن عجز صام ثلاثة أيام، أما إن كان قصده إيقاع الطلاق إن لم ينفذ هذا الشيء قصده إيقاع الطلاق فهذا يقع به طلقة واحدة على الصحيح ويراجع زوجته إذا كان ما طلقها قبل هذا طلقتين. نعم.","link":"https://binbaz.org.sa/fatwas/7837/حكم-الحلف-بالطلاق-بالثلاث-وعدم-انفاذه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_194/19419.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":9677,"question":"وهذه رسالة من المرسل أحمد حسن عبدالرحيم يقول في رسالته: أرجو الإفتاء لي عن يمين حلفته على زوجتي وهو كالآتي: قلت: حرام علي لأبيع البيت الذي أسكن فيه -في حالة غضب- ولم أقصد به طلاق زوجتي، ولا نيتي فيه الطلاق أفيدوني عن هذا اليمين بارك الله فيكم؟","title":"حكم من قال: حرام علي لأبيع البيت، ولم يقصد به الطلاق","answer":"الجواب: عليك كفارة يمين إذا كنت حلفت أنك لا تبيعه وبعته فعليك كفارة يمين، وإن كنت حلفت أنك تبيعه ثم هونت عن بيعه فعليك كفارة يمين، الحرام هذا حكمه حكم اليمين، مثل لو قال الإنسان: حرام علي ما أزور فلان، حرام علي ما أكلم فلان، حرام علي ذبيحك يا فلان، حرام علي ضيافتك يا فلان، فيه كفارة يمين؛ لأن الله سبحانه يقول: يَا أَيُّهَا النَّبِيُّ لِمَ تُحَرِّمُ مَا أَحَلَّ اللَّهُ لَكَ تَبْتَغِي مَرْضَاةَ أَزْوَاجِكَ وَاللَّهُ غَفُورٌ رَحِيمٌ ۝ قَدْ فَرَضَ اللَّهُ لَكُمْ تَحِلَّةَ أَيْمَانِكُمْ.. [التحريم:1-2] فالحرام في مثل هذا يمين مكفرة، إذا قال: حرام علي أن أبيع بيتي، أو علي حرام أني لا أبيعه ثم باعه، أو حرام علي أني أبيعه ثم باعه، المقصود أنه إذا حرم شيئاً ثم فعله فعليه كفارة اليمين، إلا الزوجة إذا حرم الزوجة قال: هي علي حرام فهذا حكمه حكم الظهار، يكون فيه كفارة الظهار، أما إذا حرم بيع بيته أو بيع سيارته أو حرم أنه ما يأكل ضيافة فلان، أو حرم أنه ما يكلم فلان، أو ما يزور فلان، فهذا كله فيه كفارة اليمين، إطعام عشرة مساكين أو كسوتهم، لكل مسكين نصف صاع من التمر أو غيره من قوت البلد، أو يكسوه كسوة قميص ....... يستره في الصلاة، أو إزار ورداء. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7902/حكم-من-قال-حرام-علي-لابيع-البيت-ولم-يقصد-به-الطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_254/25411.mp3","categories":["الأيمان والنذور","الظهار"]},{"id":9679,"question":"وهذه رسالة من المرسل أحمد حسن عبدالرحيم يقول في رسالته: أرجو الإفتاء لي عن يمين حلفته على زوجتي وهو كالآتي: قلت: حرام علي لأبيع البيت الذي أسكن فيه -في حالة غضب- ولم أقصد به طلاق زوجتي، ولا نيتي فيه الطلاق أفيدوني عن هذا اليمين بارك الله فيكم؟","title":"حكم من قال: حرام علي لأبيع البيت، ولم يقصد به الطلاق","answer":"الجواب: عليك كفارة يمين إذا كنت حلفت أنك لا تبيعه وبعته فعليك كفارة يمين، وإن كنت حلفت أنك تبيعه ثم هونت عن بيعه فعليك كفارة يمين، الحرام هذا حكمه حكم اليمين، مثل لو قال الإنسان: حرام علي ما أزور فلان، حرام علي ما أكلم فلان، حرام علي ذبيحك يا فلان، حرام علي ضيافتك يا فلان، فيه كفارة يمين؛ لأن الله سبحانه يقول: يَا أَيُّهَا النَّبِيُّ لِمَ تُحَرِّمُ مَا أَحَلَّ اللَّهُ لَكَ تَبْتَغِي مَرْضَاةَ أَزْوَاجِكَ وَاللَّهُ غَفُورٌ رَحِيمٌ ۝ قَدْ فَرَضَ اللَّهُ لَكُمْ تَحِلَّةَ أَيْمَانِكُمْ.. [التحريم:1-2] فالحرام في مثل هذا يمين مكفرة، إذا قال: حرام علي أن أبيع بيتي، أو علي حرام أني لا أبيعه ثم باعه، أو حرام علي أني أبيعه ثم باعه، المقصود أنه إذا حرم شيئاً ثم فعله فعليه كفارة اليمين، إلا الزوجة إذا حرم الزوجة قال: هي علي حرام فهذا حكمه حكم الظهار، يكون فيه كفارة الظهار، أما إذا حرم بيع بيته أو بيع سيارته أو حرم أنه ما يأكل ضيافة فلان، أو حرم أنه ما يكلم فلان، أو ما يزور فلان، فهذا كله فيه كفارة اليمين، إطعام عشرة مساكين أو كسوتهم، لكل مسكين نصف صاع من التمر أو غيره من قوت البلد، أو يكسوه كسوة قميص ....... يستره في الصلاة، أو إزار ورداء. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7902/حكم-من-قال-حرام-علي-لابيع-البيت-ولم-يقصد-به-الطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_254/25411.mp3","categories":["الأيمان والنذور","الظهار"]},{"id":9688,"question":"يسأل أخيراً ويقول: حلفت بالطلاق ثلاثاً على والدتي لا تفعل كذا ففعلت، وأنا أقصد من هذا منع والدتي، وذهبت إلى أحد العلماء فقال لي: تحسب عليك طلقة وَردَّ إليَّ زوجتي بيني وبينه والله شاهد على ذلك وليس فيه شهود، وقال لي: تعطي زوجتك شيئاً من النقود، وأعطيتها أيضاً مثلما قال لي: وسمعت في بعض حلقات برنامجكم إذا كان القصد ليس الطلاق فيحتسب علي كفارة يمين، أنا أستفسر عن هذا وقد مضى عليه ست سنوات أفيدوني أفادكم الله؟","title":"حكم الحلف بالطلاق لقصد المنع أو الحث","answer":"الجواب: إذا كنت قد قنعت بالفتوى السابقة واطمأن قلبك إليها وأخذت بها فاحتسبها طلقة كما أفتاك الذي أفتاك، والحمد لله، أما في المستقبل لو وقع شيء من هذا وأنت قصدك اليمين ليس قصدك إيقاع الطلاق وإنما قصدك منع الشخص من فعل ما حلفت عليه في الطلاق، أو حثه على فعله، كأن تقول: علي الطلاق أن تفعل كذا، أو تعطيني كذا وقصدك حثه على فعل الشيء، أو منعه منه كأن تقول: والله لا تفعل كذا وكذا، أو علي الطلاق لا تفعل كذا وكذا، فخالفك وأنت قصدك إنما هو الحث والمنع ليس قصدك إيقاع الطلاق، فإنه لا يقع الطلاق وعليك كفارة اليمين.\nلكن هذه الفتوى التي صدرت من المفتي وأنت اقتنعت بها تمضي على حالها. نعم.\nالمقدم: بارك الله فيكم، لا أدري سماحة الشيخ تساهل الناس بمثل هذا اللفظ بقولهم: عليه الطلاق لا تفعل، أو عليه الطلاق افعل، لو نبهتم إليه؟\nالشيخ: تقدم التنبيه على هذا وأنه مكروه لا ينبغي، ينبغي للمؤمن التباعد عن الطلاق والتلاعب بالطلاق، ينبغي له أن يحذر الحلف بالطلاق والإكثار من الطلاق في كلامه مع أهله أو غيرهم؛ لأن الطلاق أمره خطير وقد يسبب فرقته لأهله، فينبغي له الحذر من ذلك، وأن لا يطلق إلا عن حاجة وعن بصيرة وعن اقتناع بالطلاق، وإذا طلق طلق واحدة فقط، لا يطلق بالثلاث، الواجب أنه يقتصر على الواحدة فقط، هذه السنة، والرسول ﷺ غضب على من طلق بالثلاث، فينبغي للمؤمن إذا أراد الطلاق أن يحاسب نفسه وأن يتأنى ولا يعجل، فإذا عزم على الطلاق طلق واحدة فقط، في حال كون المرأة طاهراً طهراً لم يجامعها فيه، أو في حال كونها حاملاً، هذا هو السنة، الطلاق يكون في حالين:\nإحداهما: أن تكون حاملاً.\nالثانية: أن تكون طاهراً طهراً لم يجامعها فيه وليست حاملاً، هذا محل الطلاق السني، والسنة يكون واحدة فقط، طلقة واحدة فقط، أما الطلاق في الحيض أو في النفاس أو في طهر جامعها فيه فهو طلاق منكر لا يجوز، لقول الله تعالى: يا أيها النَّبِيُّ إِذَا طَلَّقْتُمُ النِّسَاءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ [الطلاق:1] قال العلماء: معناه: طلقوهن طاهرات من غير جماع، هذا معنى: طلقوهن لعدتهن أن يكن طاهرات من دون جماع أو حبالى هذا طلاق للعدة. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7865/حكم-الحلف-بالطلاق-لقصد-المنع-او-الحث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_253/25306.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":9710,"question":"أولى رسائل هذه الحلقة وردت من السليمانية من العراق من خالد خليل خيري ، يقول: لقد حلفت بالقرآن العظيم أكثر من ثلاث مرات أو أقل -لست متأكداً تماماً؛ لأنه قد صار لهذا الأمر وقت طويل- حلفت على أن أجتنب الزنا؛ لكنني لم أستطع السيطرة على نفسي، وهذه الحالات تسببها لي زوجتي؛ لأنها لا تعرف واجبات الزوجية مطلقاً مما جعلني لا أحبها وأكرهها، علماً أن عندي منها خمسة أطفال، فما هي الكفارة عن كل يمين؟ وهل الكفارة تمحو ذنبي وهو الذنب الذي حلفت عليه؟ وهل الله عز وجل يبقى غاضباً علي علماً أنني أصلي وأصوم شهر رمضان سنوياً، ودائماً أفكر في عذاب الله ولكن النفس أمارة بالسوء أفيدوني أفادكم الله؟","title":"حكم تكرار اليمين على شيء واحد","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله رب العالمين، والصلاة والسلام على عبده ورسوله نبينا محمد، وعلى آله وأصحابه ومن سلك سبيله واهتدى بهداه إلى يوم الدين.\nأما بعد: فلا ريب أن الزنا من أقبح الكبائر ومن أعظم السيئات، فالواجب عليك أيها السائل التوبة إلى الله من ذلك، وجهاد النفس حتى لا تقع في هذه الفاحشة العظيمة، والله يقول سبحانه: وَلا تَقْرَبُوا الزِّنَى إِنَّهُ كَانَ فَاحِشَةً وَسَاءَ سَبِيلًا [الإسراء:32] ويقول سبحانه: وَالَّذِينَ لا يَدْعُونَ مَعَ اللَّهِ إِلَهًا آخَرَ وَلا يَقْتُلُونَ النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ وَلا يَزْنُونَ وَمَنْ يَفْعَلْ ذَلِكَ يَلْقَ أَثَامًا ۝ يُضَاعَفْ لَهُ الْعَذَابُ يَوْمَ الْقِيَامَةِ وَيَخْلُدْ فِيهِ مُهَانًا ۝ إِلَّا مَنْ تَابَ وَآمَنَ وَعَمِلَ عَمَلًا صَالِحًا فَأُوْلَئِكَ يُبَدِّلُ اللَّهُ سَيِّئَاتِهِمْ حَسَنَاتٍ وَكَانَ اللَّهُ غَفُورًا رَحِيمًا [الفرقان:70].\nفعليك أيها السائل! بالتوبة إلى الله، والبدار بذلك، وجهاد النفس جهاداً كبيراً، حتى تسلم من هذه البلية العظيمة، والمصيبة الكبيرة، والكبيرة الخطيرة، وعليك كفارة اليمين عن حلفك بالقرآن أنك لا تزني، وهي كفارة واحدة، إذا كانت اليمين واحدة كررتها تقول: بالقرآن لا أزني، بالقرآن لا أزني، بالقرآن لا أزني، ولو مرات كثيرة كفارة واحدة، وهكذا لو قال الإنسان: والله لا أكلم فلان، والله لا أكلم فلان، والله لا أكلم فلانة، فإنه عليه كفارة واحدة، إذا كانت اليمين مكررة على شيء واحد، فإن كفارتها واحدة، وهكذا لو قلت: والله لا أزور فلاناً، والله لا أزور فلاناً، والله لا أزور فلاناً، فإنها كفارة واحدة إذا زرته إذا كنت نافي والله لا أزور وزرته كفارة واحدة.\nولا تكفي الكفارة عن التوبة، لا بد من الكفارة عن يمينك، ولابد من التوبة من الزنا، التوبة الصادقة، ومعناها الندم على الماضي من الفواحش، والإقلاع من ذلك، وعدم العود إلى هذا الأمر، والعزم الصادق على ذلك، هذه هي التوبة، تشمل أموراً ثلاثة:\nالأمر الأول: الإقلاع من المعصية والحذر منها تعظيماً لله وخوفاً منه سبحانه وتعالى.\nالأمر الثاني: الندم على الماضي الندم الصادق، والحزن على ما مضى من عملك السيئ.\nوالأمر الثالث: العزيمة الصادقة أن لا تعود في ذلك.\nومن تاب تاب الله عليه، أما الكفارة فلا تكفي. احذر يا عبد الله! أن يهجم عليك الأجل وأنت على هذه الحالة السيئة، فإن الزنا شره عظيم وعاقبته وخيمة، أما الزوجة فإذا كان لا تناسبك ولا تحبها فالحمد لله لك فرج طلقها والتمس غيرها امرأة مناسبة لعل الله يغنيك بها عن الفاحشة، الله جعل الطلاق رحمة لعباده عند الحاجة إليه، فطلقها طلقة واحدة والتمس غيرها وأبشر بالخير إذا صدقت، وأردت الخير أبشر بالخير : وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا ۝ وَيَرْزُقْهُ مِنْ حَيْثُ لا يَحْتَسِبُ ۝ وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:2-4] هذا كلام ربنا عز وجل وهو الصادق سبحانه، فاتق الله وراقب الله واحذر غضبه، واحذر أن تلقى ربك وأنت على هذه الفاحشة، نسأل الله لنا ولك الهداية والتوبة النصوح. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7859/حكم-تكرار-اليمين-على-شيء-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_253/25301.mp3","categories":["الأيمان والنذور"]},{"id":9711,"question":"يسأل أيضاً ويقول: عندي بنت عقدت لها على أحد الرجال، وكان بيني وبينه وبين ابنتي وعد، لكنه أخلف الوعد، قبل أن يدخل بها، مما جعل غضبي يشتد عليه وغضب ابنتي أيضاً فاضطررت أن أقول: بالطلاق لن تكوني له زوجة، أفيدوني أفادكم الله؟","title":"توضيح ونصيحة في عدم التعجل بالحلف بالطلاق","answer":"الجواب: هذا فيه تفصيل: إن كان الوعد أنه يصلي ويستقيم ويتوب إلى الله من أعماله السيئة فهذا الوعد يجب أن يطالب به، فإن تاب واستقام ورجع إلى الله فأوفوا له بالزوجية إذا كان تركه للصلاة بعد الزواج، أما إن كان تركه للصلاة قبل الزواج فالعقد لا يصح في أصح قولي العلماء؛ لأنه لا يجوز تزويج المسلمة المصلية بشخص لا يصلي في أصح أقوال أهل العلم.\nأما إن كان الوعد بأنه يترك السكر أو يترك أمراً آخر ليس بمحرم فهذا محل نظر وفي الإمكان المصالحة بينكم وبينه وحثه على التوبة من معصيته لعله يتوب ويستقيم.\nأما طلاقك ففيه تفصيل: إن كنت أردت منعها من بقائها معه ولم ترد إيقاع الطلاق وإنما قصدت منعها حتى ترتدع إذا سمعت الطلاق، فهذا عليك فيه كفارة اليمين ولا يقع الطلاق، أما إن كنت أردت إيقاع الطلاق إن أعدتها إليه، فإنه يقع عليك على زوجك طلقة واحدة، يقع بهذا طلقة واحدة على الزوجة، ولك أن تراجعها ما دامت في العدة، إذا كنت لم تطلقها قبل هذا طلقتين، ونوصيك بعدم العجلة في الأمور، وأن لا تطلق إلا على بصيرة، وإذا غضبت فقل: أعوذ بالله من الشيطان الرجيم ولا تعجل في الأمور، نسأل الله للجميع الهداية والتوفيق.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7860/توضيح-ونصيحة-في-عدم-التعجل-بالحلف-بالطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_253/25302.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":9742,"question":"أولى رسائل هذه الحلقة وردت من المستمع (ف. ع. م. ص) يقول في رسالته: أنا رجل متزوج وبعد زواجي بحوالي ست سنوات، سافرت إلى بلد أخرى من أجل السعي والبحث عن الرزق، وكنت أصلي وأصوم ولله الحمد، ولكن لعب بي الشيطان ومارست العادة السرية؛ لأنني بعيد عن زوجتي، وبعد هذا قلت: هذا عمل حرام ولا بد أن أتركه، فبدأت أصلي وأصوم وقلت: حلفت علي الطلاق بالثلاث لا أفعل هذا العمل مرة ثانية، وكانت نيتي الطلاق، وبعد فترة لعب بي الشيطان مرة ثانية فوقعت في هذا الأمر، ثم رجعت عنه، ف هل هذا الطلاق واقع علي أم لا، مع العلم أن زوجتي لم تسمعه، أفيدوني أفادكم الله؟","title":"حكم الحلف بالطلاق مع قصد الطلاق","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فإن العادة السرية التي يعتادها بعض الناس محرمة، وفيها أضرار كثيرة وهي الاستمناء، وقد قال الله عز وجل في وصف المؤمنين: وَالَّذِينَ هُمْ لِفُرُوجِهِمْ حَافِظُونَ ۝ إِلَّا عَلَى أَزْوَاجِهِمْ أوْ مَا مَلَكَتْ أَيْمَانُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ ۝ فَمَنِ ابْتَغَى وَرَاءَ ذَلِكَ فَأُوْلَئِكَ هُمُ الْعَادُونَ [المؤمنون:5-7].\nوهذه العادة الخبيثة هي غير ما أباح الله من إتيان الزوجة والسرية، فتكون محرمة وتكون من العدوان الذي بينه الله سبحانه في هذه الآية، قد بين الأطباء العارفون بهذه العادة مضرتها العظيمة وشرها الكثير.\nفالواجب على كل مؤمن أن يحذرها غاية الحذر.\nأما ما ذكره السائل من تعليقه الطلاق على العودة، فإذا كان يقصد مثل ما قال: إيقاع الطلاق، فإنه يقع طلقة واحدة؛ لعوده إليها؛ لأنه طلاق معلق على شرط يقصد منه الوقوع فوقعت بذلك طلقة واحدة على الصحيح؛ لأنه ثبت من حديث ابن عباس رضي الله عنهما عن النبي ﷺ ما يدل أن إيقاع الثلاث بلفظ واحد يعتبر طلقة واحدة.\nولك أيها السائل! مراجعتها بعدما عاودت هذه العادة الخبيثة؛ لأنه طلاق رجعي.\nأما إذا كنت لم تطلقها قبل هذا طلقتين، أما إن كنت طلقتها قبلها طلقتين فهذه تكون الثالثة ولا رجعة، نسأل الله للجميع الهداية.\nالمقدم: وبالنسبة سماحة الشيخ لما قاله: بأن زوجته لم تسمع هذا الطلاق؟\nالشيخ: ولو ما سمعت، ماله تعلق، سماعها وعدم سماعها سواء. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7908/حكم-الحلف-بالطلاق-مع-قصد-الطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_256/25601.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة","الدعوة والدعاة"]},{"id":9743,"question":"يسأل أيضاً ويقول: نحن ثلاثة إخوة ولم نقسم الميراث الذي تركه لنا والدنا، وأخي الأكبر ساعدني في الزواج من نفس التركة، وأخذ علي ورقة بأنه ليس لي في الميراث شيء، ووقعت على هذه الورقة، وبعد فترة غضبت زوجتي وذهبت إلى بيت أبيها، وذهبت لإرجاعها فرفض والدها قائلاً: لن أرجعها لك حتى تأتي بالورقة التي أخذها عليك أخوك بتنازلك عن نصيبك في الميراث، فجئت إلى أخي وحلفت له، وقلت: علي الطلاق بعد أن آخذ من عندك الورقة وأريها لوالد زوجتي أعيدها، وكان في نيتي عدم الطلاق، وعدم إرجاع الورقة في نفس الوقت لأنها ظلم، وبعد أن أخذت الورقة لم أرجعها إلى أخي، فأسأل: هل وقع علي هذا الطلاق أم لا؟","title":"حكم الحلف بالطلاق مع عدم قصد إيقاع الطلاق","answer":"الجواب: إذا كنت لم تقصد إيقاع الطلاق وإنما قصدت بذلك أنه يعطيك الورقة حتى يصدقك فيما تقول ويعطيك الورقة فإنه لا يقع بهذا طلقة، لا يقع شيء بهذا الطلاق، وينبغي لك في مثل هذه الأمور أن تستعمل الأمور الواضحة التي تحل النزاع بينك وبين أخيك، أما هذا الطلاق الذي قصدت منه أن يصدقك أخوك وأن يعطيك الورقة ولم تقصد إيقاع الطلاق فإنه لا يقع بذلك الطلاق. نعم.\nالمقدم: بارك الله فيكم.\nالشيخ: وعليك عن هذا كفارة يمين.\nالمقدم: نعم.\nالشيخ: .. عليك أيها السائل عن هذا كفارة يمين في أصح قولي العلماء. نعم.\nالمقدم: ولا يلزمه إرجاع الورقة؟\nالشيخ: هذا شيء، هذا بينه وبين أخيه خصومة عند المحكمة. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7910/حكم-الحلف-بالطلاق-مع-عدم-قصد-ايقاع-الطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_256/25602.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":9751,"question":"ويسأل أيضاً ويقول: يقول النبي ﷺ: من حلف بغير الله فقد أشرك وقد علمنا من برنامجكم أن الحلف بالطلاق ليس شركاً، ونعلم أن الطلاق ليس من أسماء الله تعالى ولا من صفاته، ويفتى لمن حلف بالطلاق إذا كان يقصد الحلف واليمين، بأن عليه كفارة يمين، فكيف يعتبر يمين وهو بغير أسماء الله وصفاته، أفيدونا أفادكم الله؟","title":"بيان كون الحلف بالطلاق ليس شركاً","answer":"الجواب: يفتى بأنه يمين؛ لأنه في حكم اليمين، لأن مقصوده الحث والمنع والتصديق والتكذيب، فهو في حكمها من جهة المعنى، من جهة المعنى الذي تترتب عليه الكفارة، وليس في المعنى من جهة تحريم الحلف بغير الله لأنه ما حلف بغير الله، إنما علق تعليقاً قال: علي الطلاق ليفعلن كذا، علي الطلاق لا يكلم فلاناً بخلاف الحلف بغير الله، كالحلف بالأصنام أو بالأنبياء أو بالأمانة أو بالكعبة هذا حلف باطل، ولا تترتب عليه كفارة يمين لأنه يمين باطلة وأما التعليقات تعليق الطلاق أو العتق أو الصدقات على أشياء هذا في حكم اليمين من جهة الكفارة، وليس في حكمها من جهة التحريم.\nفإذا قال: عليه الطلاق لا يكلم فلان أو عبيده أحرار إن كلم فلان، أو أمواله صدقة إن كلم فلان، قصده منع نفسه من هذه الأشياء، هذا له حكم اليمين من جهة الكفارة، ولا تلزمه هذه الأشياء، لأنه من باب النذر الذي .... يفعل هذا في الغالب للتأكيد على نفسه، إما في منع وإما في فعل، فحكمه حكم اليمين من هذه الحيثية، وليس له حكمها من جهة أن هذا يحرم عليه؛ لأنه لم يحلف بغير الله، وإنما علق تعليق، وهذا مروي عن السلف الصالح جعلوه في حكم اليمين ولم يجعلوه محرماً، بل جعلوه في حكم اليمين في حكم الكفارة، لما نذرت امرأة يقال لها: ليلى بن العجماء أن عبيدها أحرار وأن مالها صدقة إن لم تفرق بين فلان وفلانة جارية لها، فأفتاها ابن عمر وجماعة من السلف بأن عليها كفارة اليمين. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7917/بيان-كون-الحلف-بالطلاق-ليس-شركا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_256/25608.mp3","categories":["الطلاق","الأيمان والنذور"]},{"id":9754,"question":"ويسأل أيضاً ويقول: يقول النبي ﷺ: من حلف بغير الله فقد أشرك وقد علمنا من برنامجكم أن الحلف بالطلاق ليس شركاً، ونعلم أن الطلاق ليس من أسماء الله تعالى ولا من صفاته، ويفتى لمن حلف بالطلاق إذا كان يقصد الحلف واليمين، بأن عليه كفارة يمين، فكيف يعتبر يمين وهو بغير أسماء الله وصفاته، أفيدونا أفادكم الله؟","title":"بيان كون الحلف بالطلاق ليس شركاً","answer":"الجواب: يفتى بأنه يمين؛ لأنه في حكم اليمين، لأن مقصوده الحث والمنع والتصديق والتكذيب، فهو في حكمها من جهة المعنى، من جهة المعنى الذي تترتب عليه الكفارة، وليس في المعنى من جهة تحريم الحلف بغير الله لأنه ما حلف بغير الله، إنما علق تعليقاً قال: علي الطلاق ليفعلن كذا، علي الطلاق لا يكلم فلاناً بخلاف الحلف بغير الله، كالحلف بالأصنام أو بالأنبياء أو بالأمانة أو بالكعبة هذا حلف باطل، ولا تترتب عليه كفارة يمين لأنه يمين باطلة وأما التعليقات تعليق الطلاق أو العتق أو الصدقات على أشياء هذا في حكم اليمين من جهة الكفارة، وليس في حكمها من جهة التحريم.\nفإذا قال: عليه الطلاق لا يكلم فلان أو عبيده أحرار إن كلم فلان، أو أمواله صدقة إن كلم فلان، قصده منع نفسه من هذه الأشياء، هذا له حكم اليمين من جهة الكفارة، ولا تلزمه هذه الأشياء، لأنه من باب النذر الذي .... يفعل هذا في الغالب للتأكيد على نفسه، إما في منع وإما في فعل، فحكمه حكم اليمين من هذه الحيثية، وليس له حكمها من جهة أن هذا يحرم عليه؛ لأنه لم يحلف بغير الله، وإنما علق تعليق، وهذا مروي عن السلف الصالح جعلوه في حكم اليمين ولم يجعلوه محرماً، بل جعلوه في حكم اليمين في حكم الكفارة، لما نذرت امرأة يقال لها: ليلى بن العجماء أن عبيدها أحرار وأن مالها صدقة إن لم تفرق بين فلان وفلانة جارية لها، فأفتاها ابن عمر وجماعة من السلف بأن عليها كفارة اليمين. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7917/بيان-كون-الحلف-بالطلاق-ليس-شركا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_256/25608.mp3","categories":["الطلاق","الأيمان والنذور"]},{"id":9816,"question":"وهذه رسالة من حسين محمد الزبير سوداني الجنسية يعمل في الكويت، يقول في رسالته: حلفت بالحرام أن لا أمضي في هذا البلد إلا سنة واحدة وأرجع، لكني قد تجاوزت السنة ولم أرجع ولم أوف بحلفي، فماذا أعمل وأنا أريد الآن السفر وأنا متزوج فخشيت من هذا الحلف أن يؤثر علي أفيدوني أفادكم الله؟","title":"الحلف بالحرام فيه كفارة يمين","answer":"الجواب: إذا كان المقصود من هذا الحلف حث نفسك على الخروج وعدم الزيادة على السنة ولم ترد تحريم زوجتك، وإنما أردت حث نفسك على أن تخرج من البلد وتسافر قبل السنة، فإن عليك كفارة يمين، إذا زدت على السنة عليك كفارة يمين، وهي إطعام عشرة مساكين أو كسوتهم، لقوله : يَا أَيُّهَا النَّبِيُّ لِمَ تُحَرِّمُ مَا أَحَلَّ اللَّهُ لَكَ تَبْتَغِي مَرْضَاةَ أَزْوَاجِكَ وَاللَّهُ غَفُورٌ رَحِيمٌ ۝ قَدْ فَرَضَ اللَّهُ لَكُمْ تَحِلَّةَ أَيْمَانِكُمْ [التحريم:1-2].\nفالمقصود: أن عليك كفارة يمين وهي إطعام عشرة مساكين من قوت البلد لكل مسكين نصف صاع، يعني: كيلو ونصف تقريباً من قوت البلد من رز أو تمر أو حنطة أو غير ذلك، وعليك التوبة والاستغفار؛ لأن التحريم لا يجوز.\nأما إن كنت أردت تحريم زوجتك فإن عليك كفارة الظهار، وهي عتق رقبة مؤمنة، فإن لم يتيسر ذلك تصوم شهرين متتابعين، فإن لم تستطع ذلك تطعم ستين مسكيناً ثلاثين صاعاً من التمر أو الحنطة أو الرز أو الشعير لكل مسكين نصف صاع، يعني: كيلو ونصف تقريباً لكل واحد من قوت البلد من تمر أو غيره أو أرز أو حنطة ونحو ذلك قبل أن تمسها قبل أن تقربها؛ لأن هذا في حكم الظهار، إذا كنت أردت تحريم زوجتك إذا زدت على السنة. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7992/الحلف-بالحرام-فيه-كفارة-يمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_260/26013.mp3","categories":["الظهار","الطلاق","الأيمان والنذور"]},{"id":9846,"question":"أولى رسائل هذه الحلقة وردت من عبد الحميد أحمد حربي من جمهورية مصر العربية من محافظة كفر الشيخ ويقيم بالأردن، يقول في رسالته: عقد قراني ولم أدخل إلى الآن، وبعد العقد بمدة غضبت من هذه المرأة؛ لأنها مشت مشياً أغضبني فناديتها ولم ترض فحلفت عليها يمين الطلاق، إذا لم تأت تكوني على ذمة نفسك ولم ترض، فمشيت وراءها حتى أرضيها فحلفت عليها ثانية يمين الطلاق وأنا في أشد الغضب وقلت: لن تكوني لي امرأة ولن تدخلي بيتي، فما الحكم في هذا؟ بارك الله فيكم.","title":"حكم الحلف بالطلاق قبل الدخول بالزوجة المعقود عليها","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فهذا الطلاق الذي وقع منك.. الأول والثاني، له معنيان:\nأحدهما: أن تكون قصدت بذلك حثها على الاستجابة والامتثال لأمرك، ولم ترد إيقاع الطلاق عليها، فهذا لا يقع الطلاق وعليك كفارة يمين عن الأول والثاني، عن الطلاق الأول والثاني، يعني: كفارتان، وكفارة اليمين هي إطعام عشرة مساكين، لكل مسكين نصف صاع من قوت البلد، من تمر أو أرز ونحوهما، وإن عشيت المساكين أو غديتهم مرتين العشرة عن الطلاقين كفى.\nأما إن كنت أردت بذلك الطلاق الأول إيقاع الطلاق فإنه وقع عليها الطلاق ولا يلحقها الطلاق الآخر؛ لأن الأول يكفيها؛ لأنه غير مدخول بها تبين بالطلاق الأول ولا يلحقها الطلاق الآخر.\nوإن كنت أردت بالطلاق الأول اليمين يعني: حثها على طاعتك، والاستجابة لطلبك ولم ترد إيقاع الطلاق فإن فيه كفارة يمين، ثم ينظر في الطلاق الثاني. فإن كنت أردت به أيضاً أن تمتثل وأن تطيع أمرك، ولم ترد إيقاع الطلاق، فإن هذا يكون فيه كفارة يمين، وأما إن كنت أردت إيقاع الطلاق فإنه يقع عليك الطلاق، والذي نرى فإنه يقع عليها الطلاق، والذي نرى أن تستفتي أهل العلم عندك في الأردن أو في مصر حتى تحضر أنت والمرأة ووليها تحضرون جميعاً عند المفتي أو عند الحاكم الشرعي في الأردن أو في مصر، حتى تشرحوا له جميعاً صفة الواقع، وحتى يفتيكم على بينة وعلى أمر واضح فيما وقع منك بحضور المرأة وحضور وليها جميعاً، هذا هو الأولى وهذا هو الأحوط حتى يكون كل منكم على بينة وعلى بصيرة. نعم.\nالمقدم: أثابكم الله.","link":"https://binbaz.org.sa/fatwas/8008/حكم-الحلف-بالطلاق-قبل-الدخول-بالزوجة-المعقود-عليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_262/26201.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":9847,"question":"هذه رسالة وردت إلينا من (م. م. ح) مقيم بنجران وهو مصري الجنسية، الأخ السائل في رسالته يقول: أنا متزوج من بنت عمي شقيق أبي، وعلى إثر خلاف كبير بيني وبين عمي وزوجته، أدى إلى تحطيم مستقبلي ومستقبل أولادي فمنعت زوجتي من الذهاب إلى أبيها وأمها، ومنعت أيضاً والد زوجتي ووالدتها من الحضور إلى بيتي و لم يزل الخلاف قائماً، وقبل حضوري إلى المملكة طلبت مني زوجتي أن ترى والدها ووالدتها وإخوتها، فأثار ذلك جنوني وغضبي الشديد ورفضت هذا المطلب وضربتها، وحلفت عليها يميناً هذا نصه: علي الطلاق بالثلاث لو ذهبت إلى بيت أبيك في غيابي لن أخليك في البيت عند عودتي، وكررت ذلك مرة ثانية، في أقل من ربع ساعة، فهل إذا ذهبت إلى بيت أبيها في غيابي تكون طالقاً مرتين، أم يعتبر يميناً معلقاً له كفارة، وإذا كان كذلك فما كفارته أفيدوني بارك الله فيكم؟","title":"حكم منع الزوجة من زيارة والديها والحلف على ذلك بالطلاق","answer":"الجواب: هذا فيه تفصيل على حسب نيتك: إن كنت نويت منعها من هذا الذهاب وتخويفها وتحريجها وليس القصد من ذلك أنها طالق، وإنما أردت تخويفها وتحذيرها ومنعها فهذا فيه كفارة اليمين يمين واحدة، أما إذا كنت أردت بذلك إيقاع الطلاق، وأنها متى خرجت متى راحت إلى أهلها وقع الطلاق، فإنه يقع عليها طلقة واحدة، وإذا كنت أردت بالتكرار طلقة ثانية، فإنه يقع طلقة ثانية، أما إذا أردت بالتكرار تأكيد الكلام وتأكيد المقام لا طلاقاً آخر، فإنه لا يقع إلا طلقة واحدة، ولك العود إليها بنكاح جديد، بشروطه المعتبرة شرعاً، هذا هو التفصيل في هذا الأمر، أما كونها تذهب إلى والديها، فهذا فيه تفصيل:\nإن كان ذهابها إليهم يضرك ويضرها لسوء أخلاقهم وسوء أعمالهم، ويفسدونها عليك فلا حرج في منعها، أما إذا كان ذهابها إليهم لا يضرك ولا يضرها، فينبغي أن تسمح بذلك، وعلى كل حال ينبغي علاج هذا الأمر بالطرق الطيبة بينك وبين والدي زوجتك؛ لأن هذا يشق عليها كثيراً إذا طال، فينبغي أن تعالج هذا الأمر بواسطة أهل الخير والإصلاح بينكم حتى يتيسر ذهابها إليهم عن رضا منك، نسأل الله للجميع الهداية.\nالمقدم: أثابكم الله.","link":"https://binbaz.org.sa/fatwas/8024/حكم-منع-الزوجة-من-زيارة-والديها-والحلف-على-ذلك-بالطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_262/26212.mp3","categories":["الطلاق","الأيمان والنذور","الحقوق الزوجية"]},{"id":9857,"question":"له سؤال ثانٍ في رسالته يقول فيه: ما حكم من نذر مبلغًا من المال لبناء مسجد لكنه لم يبن المسجد، هل يحل له أن يأخذ المبلغ له أو يحوله إلى مسجد آخر ليبنى به علمًا بأن المشترك واحد من أربعة أشخاص؟","title":"حكم الرجوع عن نذر الطاعة","answer":"الجواب: إذا نذر المسلم دراهم معلومة أو نوعًا من المال المعلوم ليصرف في تعمير مسجد أو رباط للفقراء أو ليصدق بها على الفقراء وجب عليه النذر، وليس له أن يرجع عن ذلك، قال الله جل وعلا مادحًا لأهل الإيمان: يُوفُونَ بِالنَّذْرِ وَيَخَافُونَ يَوْمًا كَانَ شَرُّهُ مُسْتَطِيرًا [الإنسان:7]، وقال النبي ﷺ: من نذر أن يطيع الله فليطعه، ومن نذر أن يعصي الله فلا يعصه، فأمر عليه الصلاة والسلام من نذر طاعة أن يوفي بنذره.\nفعليك يا عبد الله أن توفي بنذرك، فإذا لم تصرفه في هذا المسجد المعين صرفته لمسجد آخر، أما أن ترجع فليس لك الرجوع. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8016/حكم-الرجوع-عن-نذر-الطاعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_198/19810.mp3","categories":["الأيمان والنذور"]},{"id":9858,"question":"وله استفتاء ثالث أيضًا يقول فيه: ما حكم المرأة التي تقول لزوجها: الله يحرمك عليَّ، وتروح إلى بيت أهلها وترجع بعد ذلك إلى بيت الزوجية؟","title":"حكم تحريم المرأة زوجها على نفسها","answer":"الجواب: هذا لفظه لفظ الخبر، ومعناه الدعاء، ولا وجه له ولا يحصل به شيء، ولا يترتب عليه شيء فقولها: الله يحرمك، أو الله يجعلك علي حرام، ما يترتب عليه شيء لكنه دعاء لا ينبغي منها، وهو معناه طلب شيء يجعلها محرمة عليه وهذا لا ينبغي منها.\nأما لو قالت: أنت حرام علي، أو أنت محرم علي، فإن هذا أولًا لا يجوز لها، وثانيًا عليها كفارة يمين إذا فعلت ذلك؛ لأن المسلم إذا حرم الحلال عليه كفارة يمين ؛ لقول الله سبحانه: يَا أَيُّهَا النَّبِيُّ لِمَ تُحَرِّمُ مَا أَحَلَّ اللَّهُ لَكَ تَبْتَغِي مَرْضَاةَ أَزْوَاجِكَ وَاللَّهُ غَفُورٌ رَحِيمٌ ۝ قَدْ فَرَضَ اللَّهُ لَكُمْ تَحِلَّةَ أَيْمَانِكُمْ [التحريم:1-2]، فمن حرم ما أحل الله له كأن يحرم طعام فلان، أو زيارة فلان، أو شراب فلان، أو الجلوس عند فلان، أو كلام فلان، عليه كفارة يمين، وهكذا إذا قالت المرأة: زوجي حرام علي، أو أنت علي مثل أبي أو ما أشبه ذلك فإن هذا كلام منكر وعليها التوبة إلى الله من ذلك، وعليها كفارة اليمين؛ لأن الظهار لا يكون من النساء إنما يكون من الرجال للنساء، أما المرأة فليس منها ظهار للزوج؛ لأن الله قال سبحانه: وَالَّذِينَ يُظَاهِرُونَ مِنْ نِسَائِهِمْ [المجادلة:3]، فالظهار للزوج مع المرأة، أما هي إذا ظاهرت من زوجها أو حرمت زوجها فعليها كفارة اليمين، وهي إطعام عشرة مساكين لكل مسكين نصف صاع من قوت البلد من تمر أو غيره، أو كسوتهم للواحد ما يجزئ في الصلاة من قميص أو إزار ورداء، أو عتق رقبة؛ عتق عبد أو عبدة ، أحد الثلاث: إما إطعام عشرة مساكين، وإما كسوتهم، وإما إعتاق رقبة مؤمنة، فإن عجز عن ذلك ولم يستطع هذه الكفارة أجزأه أن يصوم ثلاثة أيام عند العجز. نعم.\nالمقدم: يعني حالة هذه لا تعتبر الآن يعني عليها كفارة فيها؟\nالشيخ: لا؛ لأنها دعاء ما ....: الله يحرمكم ما فيه كفارة. نعم.","link":"https://binbaz.org.sa/fatwas/8019/حكم-تحريم-المراة-زوجها-على-نفسها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_198/19811.mp3","categories":["الظهار","الطلاق","الأيمان والنذور"]},{"id":9862,"question":"يقول في بقية سؤاله يا سماحة الشيخ: أنا قلت لوالدي: طلقها وأنا أزوجك خيرًا منها، وقلت لوالدي: علي الطلاق إن لم تطلق زوجتك، فقال: لن أطلقها، فكيف أعمل بيمين الطلاق؟","title":"حكم قول الرجل علي الطلاق","answer":"الجواب: هذا تراجع فيه المحكمة من جهة ما قال أبوك ومن جهة النصيحة لأبيك، ومن جهة طلاقها وتجديد العقد معها إذا كانت تائبة، هذا شيء يتعلق بالمحكمة، لكن من جهة طلاقك أنت فيه نظر، فإن كنت قصدت بهذا حث والدك على طلاقها ولم ترد إيقاع الطلاق وإنما أردت حثه على طلاقها والعزم عليه، وإلا فلم ترد إيقاع الطلاق عليها، فعليك كفارة اليمين ولا يقع الطلاق.\nأما إن كنت أردت إيقاع الطلاق مع حث والدك على الفراق فإنه يقع عليها طلقة بذلك، وتراجعها في الحال بإشهاد شخصين من خواص المسلمين من العدول ويكفي ذلك، إذا كنت لم تطلقها قبل هذا طلقتين فإن الطلقة هذه تكون رجعية ولك أن تراجعها في الحال إذا كنت أردت إيقاع الطلاق، والله المستعان. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8029/حكم-قول-الرجل-علي-الطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_198/19815.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":9869,"question":"هذه رسالة وردت من سعد ضيف الله يقول فيها: أنا نذرت أنه إذا سلم ابن أخي من المرض فسوف أذبح ناقة، وقد تم له الشفاء، لكني بعد ذلك لم أفعل، بل شككت وذهبت أسأل أحد العلماء فقال لي: ما هي نيتك؟ فقلت: ناقة إما مكسورة أو مريضة أو رخيصة الثمن، هذه نيتي عند النذر، فقال لي: عليك كفارة ولا نذر عليك، فعملت الكفارة ولكنني شككت في أمري، فتقدمت إليكم بالسؤال؟","title":"حكم الوفاء بالنذر المعلق","answer":"الجواب: ما دمت قلت: إن شفى الله فلان فعلي ناقة، أو بعير فعليك الناقة التي قلت، عليك ناقة سليمة مثل الضحية، سليمة من العيوب حسب طاقتك، تشتريها وتذبحها وتوزعها بين الفقراء، إلا إذا كان لك نية أنك تذبحها في بيتك ويأكل منها أهلك وأقاربك وجيرانك فلا بأس أنت على نيتك، لقول النبي ﷺ: إنما الأعمال بالنيات، وإنما لكل امرئ ما نوى أما إن كنت ما نويت شيئاً وإنما قلت: عليك كذا وكذا إن شفى الله مريضك، فإنك تذبحها وتوزعها بين الفقراء في البلد التي أنت فيها، أو في البلد الأخرى. نعم.\nالمقدم: أثابكم الله.","link":"https://binbaz.org.sa/fatwas/8037/حكم-الوفاء-بالنذر-المعلق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_263/26305.mp3","categories":["الأيمان والنذور"]},{"id":9870,"question":"ويقول أيضاً: إذا حلف الشخص بالطلاق وهو في الرياض، وزوجته في بلاده، لأي سبب مثلاً على أخ أو صديق بحكم المجاملة في أكل أو شرب فهل يقع هذا الطلاق، وهل هو حرام؟","title":"حكم الحلف بالطلاق في غيبة الزوجة","answer":"الجواب: ما ينبغي التلاعب في الطلاق، ولا ينبغي اتخاذه الإنسان ديدنه في كلامه وأيمانه، بل ينبغي أن يبعده عن ذلك ويتحرز من ذلك، فإذا طلق في كلامه نظر في أمره يختلف، فإذا قال: عليه الطلاق أن تأكل، أو عليه الطلاق أن تروح معي إلى كذا وكذا، تذهب معي إلى محل كذا، أو علي الطلاق أنك ما تكلمي فلان، قصده منعه من الكلام أو قصده التأكيد عليه أنه يأكل من طعامه، ما قصده الطلاق، هذا له حكم اليمين، يكفر عن يمينه كفارة يمين ويكفي ولا يقع الطلاق على امرأته، سواء كانت حاضرة أو غائبة، وهكذا لو قال: عليه الطلاق أنه ما يسافر قصده منع نفسه من السفر، أو عليه الطلاق أنه ما يزور فلان، هذه وأشباهها كلها إذا كان قصده منع نفسه، أو حث نفسه على كذا، لا يقع الطلاق بل فيه كفارة اليمين.\nأما إذا كان قصده.. إذا قال: عليه الطلاق ما يزور فلان، قصده فراق أهله إن زار فلان، عازم على الطلاق، يقع الطلاق طلقة واحدة، إذا كان قبلها طلقتان انتهى تم الطلاق وحرمت عليه، وإن كان ما قبلها طلقتان فله المراجعة.\nفالحاصل أنه يختلف بحسب نيته، لقول النبي ﷺ: «الأعمال بالنيات» فمن نوى في طلاقه منع شيء أو حثاً على شيء فهو على نيته وعليه كفارة يمين إذا لم ينفذ طلاقه، إذا لم يتم أمر طلاقه إذا حنث، أما إذا كان نوى بإيقاع الطلاق نوى بـ(عليه الطلاق) أنه لا يأكل كذا، أو عليه الطلاق أنه ما يكلم فلان، أو عليه الطلاق أنه ما يسافر، وهو ناوي إيقاع الطلاق، متى كلمه أو سافر أو نحو ذلك وقع، فإنه يؤخذ بنيته ويقع الطلاق. نعم.","link":"https://binbaz.org.sa/fatwas/8043/حكم-الحلف-بالطلاق-في-غيبة-الزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_263/26311.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":9894,"question":"هذا السائل الذي رمز لاسمه بـأحمد حسين ، يقول هذا السائل: شخص قام بتحريم فتاة على نفسه أن يتزوجها قبل أن يخطبها، وبعد ذلك أراد أن يتزوجها، فهل هي حرام عليه بعد ذلك، وإن لم تكن حرام فماذا عليه أن يفعل؟","title":"حكم من حرم على نفسه فتاة قبل أن يتزوجها","answer":"الجواب: إذا حرم إنسان امرأة قبل العقد عليها أنه لا يتزوجها فقد أثم عليه التوبة إلى الله، وعليه كفارة يمين، لقول الله سبحانه: يَا أَيُّهَا النَّبِيُّ لِمَ تُحَرِّمُ مَا أَحَلَّ اللَّهُ لَكَ تَبْتَغِي مَرْضَاةَ أَزْوَاجِكَ وَاللَّهُ غَفُورٌ رَحِيمٌ ۝ قَدْ فَرَضَ اللَّهُ لَكُمْ تَحِلَّةَ أَيْمَانِكُمْ [التحريم:1-2] وقوله ﷺ: من حلف على يمين فرأى غيرها خيراً منها، فليكفر عن يمينه وليأت الذي هو خير والتحريم في حكم اليمين، فإذا قال: فلانة علي حرام، قبل أن يعقد عليها، فله أن يتزوجها وعليه كفارة يمين، إطعام عشرة مساكين أو كسوتهم عن يمينه، وله أن يتزوجها. نعم.","link":"https://binbaz.org.sa/fatwas/8062/حكم-من-حرم-على-نفسه-فتاة-قبل-ان-يتزوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_273/27306.mp3","categories":["الأيمان والنذور"]},{"id":9944,"question":"يسأل أيضاً عن طلاق مماثل فيقول: إنه يعمل في مزرعة في المملكة، وقد طلب من زميل له أن يعطيه شريط ليسجل فيه، فراوغه كثيرًا فصدر منه طلاق على أنه لن يسجل شريطًا بعد ذلك طول وجوده في المملكة، ولكن يقول: بعد ذلك رجعت عن كلامي وسجلت أشرطة، فهل يكون هذا طلاقًا واقعًا؟","title":"حلف بالطلاق لزميله أنه لن يسجل شريطًا ثم رجع","answer":"الجواب: إذا كان المقصود من الطلاق على التسجيل منع نفسك من التسجيل وليس قصدك فراق أهلك إن سجلت، إنما قصدت منع نفسك حتى لا تسجل مرة أخرى فإن هذا الطلاق في حكم اليمين، أما إن كنت قصدت إيقاع الطلاق فإنه يقع الطلاق إذا سجلت، ومادمت في المملكة ففي إمكانك أن تسأل أحد القضاة أو أحد العلماء والزوجة معك ووليها إن كان حاضراً حتى يتضح الأمر لك ولها في المسألة هذه وفي التي قبلها، أو تحضر عندنا إن كنت في الرياض حتى نسألك عما يلزم، وبكل حال فالجواب هو ما سمعت. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8112/حلف-بالطلاق-لزميله-انه-لن-يسجل-شريطا ثم-رجع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_274/27405.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":9962,"question":"وهذه رسالة وردتنا من السائل عبد الهادي محمد بكري مصري الجنسية ويعمل في نجران، يقول في رسالته: أنا ساكن مع واحد من زملائي، وقد غضبت منه وحلفت بالطلاق بالثلاث لا أبيت في نفس الغرفة، فقالوا لي الزملاء: بأن علي أن أبيت وأن هذا لا يضر، فما حكم عملي هذا وفقكم الله؟","title":"على من حلف بالطلاق يريد إيقاعه أن يستفتي المحكمة","answer":"الجواب: هذا يختلف بحسب نيتك، إن كنت أردت إيقاع الطلاق إن بت في الغرفة ثم بت بها فإنه يقع الطلاق، أما إن كنت أردت منع نفسك من المبيت ولم ترد إيقاع الطلاق وإنما أردت بهذا منع نفسك من المبيت، فإن عليك كفارة يمين إذا بت فيها وهي إطعام عشرة مساكين أو كسوتهم أو عتق رقبة، فمتى فعلت واحدة من هذه الثلاث حصل المقصود، إطعام عشرة مساكين كل مسكين له نصف الصاع يعني: كيلو ونصف من التمر أو غيره من قوت البلد، أو كسوتهم كل واحد يكسى بما يجزئه في الصلاة كقميص أو إزار ورداء أو عتق رقبة مؤمنة، فإن لم تستطع تصوم ثلاثة أيام، هذا إذا كنت أردت منع نفسك من المبيت ولم ترد إيقاع الطلاق، أما إن كنت أردت إيقاع الطلاق ثم بت فإنه يقع الطلاق، ثم عليك أن تستفتي بعد ذلك المحكمة في الطلاق أو تكتب لنا في ذلك. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8136/على-من-حلف-بالطلاق-يريد-ايقاعه-ان-يستفتي-المحكمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_266/26602.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":9971,"question":"وهذه رسالة وردتنا من السائل عبد الهادي محمد بكري مصري الجنسية ويعمل في نجران، يقول في رسالته: أنا ساكن مع واحد من زملائي، وقد غضبت منه وحلفت بالطلاق بالثلاث لا أبيت في نفس الغرفة، فقالوا لي الزملاء: بأن علي أن أبيت وأن هذا لا يضر، فما حكم عملي هذا وفقكم الله؟","title":"على من حلف بالطلاق يريد إيقاعه أن يستفتي المحكمة","answer":"الجواب: هذا يختلف بحسب نيتك، إن كنت أردت إيقاع الطلاق إن بت في الغرفة ثم بت بها فإنه يقع الطلاق، أما إن كنت أردت منع نفسك من المبيت ولم ترد إيقاع الطلاق وإنما أردت بهذا منع نفسك من المبيت، فإن عليك كفارة يمين إذا بت فيها وهي إطعام عشرة مساكين أو كسوتهم أو عتق رقبة، فمتى فعلت واحدة من هذه الثلاث حصل المقصود، إطعام عشرة مساكين كل مسكين له نصف الصاع يعني: كيلو ونصف من التمر أو غيره من قوت البلد، أو كسوتهم كل واحد يكسى بما يجزئه في الصلاة كقميص أو إزار ورداء أو عتق رقبة مؤمنة، فإن لم تستطع تصوم ثلاثة أيام، هذا إذا كنت أردت منع نفسك من المبيت ولم ترد إيقاع الطلاق، أما إن كنت أردت إيقاع الطلاق ثم بت فإنه يقع الطلاق، ثم عليك أن تستفتي بعد ذلك المحكمة في الطلاق أو تكتب لنا في ذلك. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8136/على-من-حلف-بالطلاق-يريد-ايقاعه-ان-يستفتي-المحكمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_266/26602.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":9972,"question":"وهذه رسالة وردت من سائل رمز لاسمه بأخيكم في الإسلام من السودان، يقول في رسالته: أنا شاب أبلغ من العمر الثامنة والعشرين تزوجت في هذا العام إكمالًا لديني، ولكن مع الأسف لقد حلفت بقول: علي الحرام، علمًا بأنني في شعوري ولست مخمورًا ولكنني حلفت وأنا لا أقصد بأن أحرم زوجتي علي، فبكيت وندمت أشد الندم على الذي حصل مني، وصرت أستغفر الله وأدعوه في كل صلاة أن يعفو عني وتصدقت بإطعام ستين مسكيناً لكي يغفر الله لي هذا الذنب، فأسأل عن حكم ذلك؟ بارك الله فيكم.","title":"حكم من قال: (زوجتي علي حرام)","answer":"","link":"https://binbaz.org.sa/fatwas/8127/حكم-من-قال-زوجتي-علي-حرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_274/27408.mp3","categories":["الظهار","الطلاق","الأيمان والنذور"]},{"id":9979,"question":"تسأل أيضاً وتقول: بأنه حدث بينها وبين زوجها خلاف فحلف زوجها عليها بالطلاق ألا تخرج من بيتها وألا تذهب إلى بيت أهلها، فتقول: لم أخرج وبقيت في بيتي، وفي هذه الأثناء خرج زوجي من البيت وتركني ورجع إلى البيت وقد نسي الخلاف الذي حدث وعادت الأمور بيننا طبيعية، فما هي كفارة هذا اليمين، وماذا يفعل زوجي حتى يزيل أثر هذا اليمين لأنه قد حلف مرة أخرى ألا أزور أهلي أبدًا، فلكنني أخرج من غير علمه فلا أدخل بيتهم إنما يخرجون ويكلمونني عند الباب، فما الحكم في ذلك؟","title":"حكم من حلف بالطلاق على امرأته ألا تخرج من بيتها","answer":"الجواب: إذا كان المقصود منعك من الذهاب إلى أهلك وليس المقصود الطلاق إنما المقصود منعك من الأهل فإنه يكفر كفارة يمين، وحكم هذا حكم اليمين، إذا منعك من الخروج إلى أهلك أو من الزيارة إلى أهلك فلا تخرجي إلا بإذنه، ومتى سمح فعليه كفارة اليمين إذا كان أراد منعك ولو بإذنه، أما إذا كانت نيته أنه أنك لا تخرجين إلا بإذنه فمتى أذن فليس عليه شيء وليس عليك شيء.\nوأما إن كان أراد منعك مطلقًا ثم بدا له أن يأذن فعليه كفارة اليمين، مادامت النية والقصد منعك لا فراقك، والأعمال بالنيات، يقول النبي ﷺ: إنما الأعمال بالنيات، وإنما لكل امرئ ما نوى متفق على صحته، فهو مسئول عن نيته وهو أعلم بها، والله هو الذي يسأله عنها  مادام قصد منعك لا فراقك فإذا خرجت فعليه كفارة يمين وهي إطعام عشرة مساكين أو كسوتهم، كل واحد يعطى نصف صاع تمر أو رز أو حنطة أو غير ذلك من قوت البلد أو يكسوه قميصاً من الخام المعتاد أو إزار ورداء والحمد لله. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8140/حكم-من-حلف-بالطلاق-على-امراته-الا-تخرج-من-بيتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_274/27411.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":9986,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول: أخوكم في الله (ح. س) -سؤاله طويل في الواقع- يقول: إنني شاب أبلغ من العمر إحدى وعشرين سنة متزوج حديثًا، ولقد اعتدت قبل الزواج أن أحلف بقولي: حرام أن أفعل كذا، أو حرام لن أفعل كذا، وبعد الزواج حاولت أن أبتعد عن مثل هذا الحلف ولكن بعض الأحيان أنسى وأحلف به من غير قصد، أي: أنه يخرج مني غصبًا؛ لأن لساني اعتاد عليه، وأنا أخاف من عقاب الله عز وجل وأريد أن أتوب، ولكني أجد في نفسي حرجًا من هذا اليمين؛ لأنني تلفظت به أكثر من مرة، وإن شاء الله لن أعود إليه، والسؤال هو: هل هذا الحلف يؤثر على علاقتي الزوجية، أم أنه يحسب لي يمين وتلزمني بذلك كفارة اليمين، أفيدوني ووجهوني، جزاكم الله خيرًا؟","title":"حكم قول القائل: حرام لن أفعل كذا","answer":"الجواب: أولًا: عليك التوبة من ذلك والامتناع من هذا اللفظ؛ لأنه لا يجوز لمسلم أن يحرم ما أحل الله، وقد أنكر الله على نبيه ﷺ ذلك، فقال: يَا أَيُّهَا النَّبِيُّ لِمَ تُحَرِّمُ مَا أَحَلَّ اللَّهُ لَكَ تَبْتَغِي مَرْضَاةَ أَزْوَاجِكَ [التحريم:1].\nفالواجب عليك التوبة إلى الله من ذلك وأن لا تستعمل هذا التحريم.\nالأمر الثاني: عليك كفارة يمين ولا يتعلق بزوجتك شيء، بل عليك كفارة يمين؛ لأنك لا تقصد تحريمها وإنما تقصد تحريم الأشياء التي أردتها، حرام علي ما أفعل كذا، حرام علي ما أتكلم في كذا، فإذا فعلت الذي قلته أنك حرام عليك أو تكلمت بالذي قلته إنه حرام عليك فعليك كفارة يمين، فإذا قلت: حرام علي ما آكل طعامك، حرام علي ما أكلم فلان، ثم كلمته أو أكلت طعامه يكون عليك كفارة يمين، وهي إطعام عشرة مساكين أو كسوتهم، عشرة عدد الأصابع، تطعم كل واحد نصف صاع من التمر أو من الحنطة أو من الرز من قوت البلد، أو بالوزن كيلو ونصف تقريبًا، لكل واحد من العشرة، أو تكسو كل واحد كسوة تجزئه في الصلاة، كالقميص أو إزار ورداء، ويكفي ذلك مع التوبة والاستغفار. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8154/حكم-قول-القاىل-حرام-لن-افعل-كذا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_331/33103.mp3","categories":["الأيمان والنذور"]},{"id":10012,"question":"تقول: لقد حلفت بالله أنني لا أسلم على إحدى الزميلات بسبب زعل بيننا، ومرت الأيام وقابلتني فسلمت عليها فما هي الكفارة عن الحلف بالله؟","title":"حلفت ألا تسلم على زميلاتها ثم سلمت","answer":"الجواب: عليك كفارة اليمين وهي إطعام عشرة مساكين أو كسوتهم أو عتق رقبة، والإطعام يكون نصف صاع لكل واحد من العشرة كيلو ونص تقريبًا أو قميص يجزئه في الصلاة أو عتق رقبة مؤمنة، ومن عجز عن ذلك كله وصار فقيرًا لا يقدر يصوم ثلاثة أيام.\nولا ينبغي لك هجر أختك في الله من غير حق إذا كانت أخطأت عليك فالتسامح طيب، ولا بأس بالهجر ثلاثة أيام عند الحاجة، أما الزيادة عن ثلاثة أيام لا تجوز، يقول النبي ﷺ: لا يحل لمسلم أن يهجر أخاه فوق ثلاث، يلتقيان فيعرض هذا ويعرض هذا وخيرهما الذي يبدأ بالسلام.\nفالواجب عليك أن لا تهجريها من أجل حظك أو خطئها عليك أو نحو ذلك فوق ثلاثة أيام، وإذا صالحتيها كفرت عن يمينك كفارة يمين كما تقدم.\nأما إن كان الهجر لله لأنها تظهر المعاصي، أو لأنها عندها بعض البدع وهجرتيها لله حتى تتوب فهذا ليس له حد، لا ثلاث ولا غيرها حده التوبة متى تابت تسلمي عليها، وما دامت تعلن المعاصي فهي تستحق الهجر ولو سنة ولو سنتين ولو أكثر، وقد هجر النبي ﷺ ثلاثة من الصحابة تخلفوا عن الغزو يعني: عن الجهاد بغير عذر شرعي فهجرهم خمسين ليلة عليه الصلاة والسلام حتى تاب الله عليهم.\nفالمقصود: أن الهجر إذا كان لحظ النفس من أجل خصومة أو كلمة زل بها الإنسان على أخيه أو زلت بها المرأة على أختها هذا يكون مقيدًا بثلاثة أيام ولا تجوز الزيادة، أما إذا كان الهجر لله للمعاصي والبدع فهذا ليس له حد إلا التوبة متى تاب صاحب المعصية أو البدعة سلم عليه، إلا أن يكون الهجر يزيد الشر شرًا يزيد البلاء بلاءً فلا يشرع الهجر، ولكن يديم النصيحة والإنكار والتوجيه إلى الخير حتى يقل الشر أو يزول الشر. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8181/حلفت-الا-تسلم-على-زميلاتها-ثم-سلمت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_332/33201.mp3","categories":["الأيمان والنذور"]},{"id":10017,"question":"تقول: شخص يحلف على شيء ماضٍ، كي يفهم صاحبه منه شيء حاضر، فهل هذا جائز أو لا؟","title":"حكم الحلف على شيء مضى","answer":"الجواب: إذا قال يا أخي والله إن هذا صار وهو صادق، والله إن فلان سافر، والله إن فلان أعطاني كذا، والله إن فلان ما أعطاني كذا، والله إن فلان مريض، والله إن فلان ميت فلا حرج إذا كان صادقًا لا حرج في ذلك، وإن كان كاذب فعليه التوبة، وهذه تسمى يمين غموس، إن كان كاذباً فعليه التوبة لأنه آثم، وإن كان صادقًا فلا شيء عليه.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8186/حكم-الحلف-على-شيء-مضى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_276/27605.mp3","categories":["الأيمان والنذور"]},{"id":10067,"question":"رسالة وصلت إلى البرنامج من جازان وباعثها المستمع عبدالله مهدي صنقور بعث يسأل ويقول: ما حكم من حلف بالله كاذبًا متعمدًا عند المزاح أو غير قاصد، نرجو التوجيه جزاكم الله خيرًا؟","title":"حكم الحلف بالله كذبًا","answer":"الجواب: لا يجوز الحلف بغير الله كاذبًا ولا المزاح في ذلك وإذا كان على مال يأخذه صار أكبر، يقول النبي ﷺ: من حلف على يمين يقتطع بها مال امرئ مسلم هو فيها كاذب لقي الله وهو عليه غضبان، ويسمي العلماء اليمين الكاذبة اليمين الغموس لأنها تغمس صاحبها في الإثم ثم في النار فلا يجوز للمؤمن أن يحلف كاذبًا، بل يجب أن يتحرى الصدق والنبي ﷺ قال: من حلف بالله فليصدق، ... يتحري الصدق إلا إذا ظلم وأجبر على غير حق بأن قال: احلف بالله أنك ما قتلت فلان أو أنك ما ظلمت فلان أو ما أشبه ذلك فحلف بالله أنه ما قتل فلان أو ما ظلم فلان وهو في هذا كاذب هو قتله لكن قتله بحق أو أخذ ماله بحق، لم يقتله ظلمًا ولم يأخذ ماله ظلمًا بل أخذ مالًا بحق في البيع والشراء أو قتله بحق قصاص أو ما أشبه ذلك من الحق، فالمقصود أنه إذا أجبر على يمين وهو فيها في نفسه محق ولكن حلف ليتخلص من شرهم فلا يضره ذلك، كذبه فيها لأنه في الحقيقة ليس بكاذب ما قتله على وجه الذي قالوا، إنما قتله أو أخذ المال على وجه آخر صحيح وهكذا إذا حلف بالله كاذبًا ليخلص آخاه من شر كأن يريدوا قتله بغير حق فيحلف بالله إنه أخوه أو أنه قريبه ليخلصه من شر هؤلاء الظلمة فلا بأس في ذلك. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8230/حكم-الحلف-بالله-كذبا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_333/333004.mp3","categories":["الأيمان والنذور"]},{"id":10100,"question":"إحدى المستمعات من العراق تقول: المسلمة (ف. ط. ع) من العراق الموصل تقول: إنها نذرت أن تصوم عن الكلام ثلاثة أيام فلم تستطع ماذا تفعل؟","title":"حكم من نذر صومًا عن الكلام ولم يف بنذره","answer":"الجواب: هذا نذر مكروه فينبغي عليها أن تكفر كفارة يمين ولا تمسك عن الكلام، نذر رجل في عهد النبي ﷺ أن لا يتكلم فأمره النبي أن يتكلم لأن هذا منكر وعليه كفارة يمين.","link":"https://binbaz.org.sa/fatwas/8269/حكم-من-نذر-صوما-عن-الكلام-ولم-يف-بنذره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_333/33312.mp3","categories":["الأيمان والنذور"]},{"id":10146,"question":"تقول: هل كلمة (والله) تعد حلفاً بالله يجب إنفاذ ما حلف عليه وهل تكون ككلمة (والله العظيم) أرشدوني مأجورين جزاكم الله خيرا؟","title":"انعقاد اليمين بكلمة والله","answer":"الجواب: نعم والله كافية يمين، لكن لا يجب تنفيذ ما حلف عليه إلا إذا كان واجباً شرعاً، فإذا قال: والله لآكلن هذا الطعام، والله لأشربن هذا الماء، والله لأزورن فلان ما تلزمه الزيارة ولا تلزمه الأكل والشرب، فعليه كفارة يمين إن فعل فلا بأس وإن ترك يكفر كفارة يمين، وهي إطعام عشرة مساكين أو كسوتهم أو عتق رقبة، فإن عجز صام ثلاثة أيام هذه كفارة اليمين، كل مسكين يعطى نصف الصاع تمر أو رز كيلو ونصف، أو كسوة تجزئه في الصلاة، فإذا قال: والله لأزورن فلان، والله لآكلن من هذا الطعام، والله لأشربن من هذا اللبن أو من هذا الماء، هو مخير إن شاء فعل ولا كفارة عليه، وإن شاء ترك وعليه كفارة اليمين، أو قال: والله لأسافرن اليوم إلى مكة أو إلى كذا، فهو مخير إن شاء سافر وإن شاء ترك، فإن ترك فعليه كفارة يمين وإن سافر فلا بأس.\nأما إذا كان المحلوف عليه واجب أو معصية فيلزمه فعل الواجب وترك المعصية، فإذا قال: والله لأصومن رمضان، والله لأصلين الصلوات الخمس يلزمه أن يصلي ولو ما حلف تكون اليمين تأكيد، والله لا أكذب يلزمه أنه لا يكذب ولو ما حلف، فاليمين تكون تأكيد، والله لا أعمل بالربا يلزمه أن لا يعمل بالربا، والله لا أغتاب أحداً، يلزمه أن لا يغتاب أحد، فاليمين تأكيد تؤكد هذا الشيء.\nأما إذا قال: والله لأقتلن فلان، يعني: بغير حق هذا ما يجوز له، عليه كفارة يمين، ولا يجوز له قتله بغير حق أو قال: والله لأزنين أو لأشربن الخمر، لا يجوز له، هذا حرام ومن الكبائر العظيمة وعليه كفارة يمين عن يمينه، أو والله لا أطيع والدي أو لا أصل رحمي كل هذا منكر يكفر عن يمينه يبر والديه ويصل رحمه وهذه أمثلة يعرف بها ما سواها. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8316/انعقاد-اليمين-بكلمة-والله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_306/30605.mp3","categories":["الأيمان والنذور"]},{"id":10152,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات تقول في رسالتها حسنية محمد باوزير من حضرموت: هناك شخص ما زال يدرس وليس له مال من عمله، ولكن تحصل على بعض المال من أقاربه، وهذا المال يكفي لقضاء كفارة، هل عليه أن يكفر عن يمينه أولًا، أم يتصرف في هذا المال لقوته وقوت يومه، جزاكم الله خيرًا؟","title":"كفارة اليمين لمن لم يكن له مال يقتات منه","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فإذا كان الطالب المذكور عليه يمين وليس لديه ما يقوم بحاله إلا ما حصل له من أقاربه بقدر نفقته فإنه لا تلزمه الكفارة بالمال، ولكن يكفر بالصيام وذلك صيام ثلاثة أيام كما نص عليه الرب عز وجل في كتابه العظيم في سورة المائدة؛ حيث قال : لاَ يُؤَاخِذُكُمُ اللّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِن يُؤَاخِذُكُم بِمَا عَقَّدتُّمُ الأَيْمَانَ فَكَفَّارَتُهُ إِطْعَامُ عَشَرَةِ مَسَاكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍ فَمَن لَّمْ يَجِدْ فَصِيَامُ ثَلاَثَةِ أَيَّامٍ ذَلِكَ كَفَّارَةُ أَيْمَانِكُمْ إِذَا حَلَفْتُمْ وَاحْفَظُواْ أَيْمَانَكُمْ [سورة المائدة:89]. فبين  أن من عجز عن هذه الكفارة التي هي الإطعام والكسوة والعتق من عجز عن هذه الثلاث يصوم ثلاثة أيام، فإذا كان الطالب ليس عنده إلا ما يسد فاقته وحاجته من المطعم والمشرب والملبس فإنه يكفر بالصيام، صيام ثلاثة أيام والحمد لله. المقدم: جزاكم الله خيرًا، إذاً: قوت اليوم أولى من تقديم الكفارات والكفارة تبقى مؤجلة في ذمته؟ الشيخ: يعتبر فقيراً، فالكفارة باقية، وإذا صام ثلاثة أيام أجزأت. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8320/كفارة-اليمين-لمن-لم-يكن-له-مال-يقتات-منه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_307/30701.mp3","categories":["الأيمان والنذور"]},{"id":10154,"question":"ماذا لو كان فعل شخص شيئاً حراماً واعتاد على هذا الشيء، ثم حلف ألا يفعله ففعله مرة أخرى، ماذا عليه؟ وكيف توجهونه جزاكم الله خيراً؟","title":"حكم من حلف أن لا يقترف ذنباً ثم اقترفه","answer":"الجواب: عليه التوبة إلى الله سبحانه وتعالى، فإن المعاصي دواؤها التوبة، يقول جل وعلا: وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَا الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ [النور:31]، ويقول سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا تُوبُوا إِلَى اللَّهِ تَوْبَةً نَصُوحًا [التحريم:8]، فالواجب على كل مسلم اقترف ذنباًَ أن يبادر بالتوبة إلى الله عز وجل، وذلك بالندم على الماضي من سيئاته، وبالإقلاع منها والحذر منها، وبالعزم الصادق أن لا يعود فيها خوفاً من الله وتعظيماً له وإخلاصاً له سبحانه، هذا هو الواجب على كل عاصٍ من الرجال والنساء. وعليه كفارة اليمين، إذا حلف ألا يعود ثم عاد عليه كفارة اليمين مع التوبة وهي إطعام عشرة مساكين لكل مسكين نصف صاع من قوت البلد من تمر أو غيره ومقداره كيلو ونص تقريباً، أو كسوتهم كل واحد يعطى ما يجزئه في الصلاة قميص أو إزار ورداء، أو عتق رقبة، فمن لم يستطع هذا كله يصوم ثلاثة أيام، والتوبة لا بد منها من جميع المعاصي.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8321/حكم-من-حلف-ان-لا-يقترف-ذنبا-ثم-اقترفه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_307/30702.mp3","categories":["الأيمان والنذور"]},{"id":10157,"question":"سماحة الشيخ! أخونا أيضاً يسأل في باب الكفارات ويقول: هل يجب على الإنسان أن يكفر فوراً، أم لا مانع من أن تبقى الكفارة في ذمته؟","title":"الكفارات واجبة على الفور","answer":"الجواب: لا، الواجب الفورية، متى وجبت الكفارة فالواجب البدار بها سواء كانت كفارة ظهار أو كفارة وطء في رمضان أو كفارة قتل أو كفارة يمين الواجب البدار؛ لأن أوامر الله على الفور إلا ما دل الدليل على التراخي فيه، والله سبحانه قال: وَتُوبُوا إِلَى اللَّهِ جَمِيعًا [النور:31]، فالتوبة واجبة من المعاصي والكفارة جزء من التوبة، فإن العاصي إذا كان في ذنبه كفارة يجمع بين الأمرين، فالذي مثلاً ظاهر من زوجته عليه التوبة والكفارة، والذي وطئها في رمضان عليه التوبة والكفارة مع قضاء اليوم الذي حصل فيه الجماع، والذي حلف وتعمد الحنث عليه التوبة إذا كان المعصية مع الكفارة مثل أن يقول: والله! ما أشرب الخمر، والله! ما أعق والدي، والله! ما أغتاب أحداً ثم يفعل عليه التوبة والكفارة جميعاً، فكما أن عليه البدار بالتوبة عليه البدار بالكفارة لأنها من تمام التوبة ومن كمالها. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8322/الكفارات-واجبة-على-الفور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_307/30703.mp3","categories":["الجماع في نهار رمضان","الأيمان والنذور"]},{"id":10205,"question":"المستمعة فائزة صالح المالكي ، بعثت تسأل وتقول: يا فضيلة الشيخ! إذا كان علي كفارة، فهل أعطيها لعدد من الفقراء أم أكتفي ببيت واحد أهله كلهم من الفقراء جزاكم الله خيرا؟","title":"كيفية توزيع الكفارات","answer":"الجواب: الكفارات تختلف، إذا كانت كفارة يمين لابد من إعطائها عشرة مساكين عشرة ما يكفي بيت واحد، إلا إذا كان البيت فيه عشرة فلا بأس، وإن كانت كفارة جماع في رمضان فلابد من ستين مسكين، في حق من عجز عن العتق وعن صيام شهرين يطعم ستين مسكينا، وهكذا كفارة القتل الخطأ إذا كان قتل فيها عتق رقبة، فإن عجز صام شهرين متتابعين، وهكذا كفارة الظهار إذا حرم الرجل امرأته، الكفارة مرتبة عتق أول إن قدر، فإن لم يتيسر العتق صام شهرين متتابعين ستين يوماً، فإن عجز أطعم ستين مسكينا، فلابد من مراعاة العدد الذي بينه الله جل وعلا في الكفارات، كفارة الظهار والجماع في رمضان، وكفارة اليمين، لابد من العدد.\nأما إذا كانت صدقة يرجو بها ما عند الله ما هي بكفارة لشيء محدود، بل صدقة يرجو بها كفارة الذنوب، فهذا يعطيها ولو فقير واحد لا بأس، الصدقات ولو .. فقير واحد ولو كانت كبيرة؛ هي من أسباب تكفير الذنوب كما في الحديث الصحيح: الصدقة تطفئ الخطيئة الصدقات من أسباب غفران الذنوب، فإذا تصدق بمائة ريال أو ألف ريال أو أكثر أو أقل على فقير واحد فهذا مطلوب وفيه خير عظيم ومن أسباب تكفير السيئات، نعم.\nالمقدم: جزاكم الله خيراً وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8373/كيفية-توزيع-الكفارات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_278/27804.mp3","categories":["الجماع في نهار رمضان","الأيمان والنذور"]},{"id":10229,"question":"المستمع محمد عبد التواب حسن من محافظة المنيا بعث يسأل ويقول: سماحة الشيخ! حلفت بالطلاق على أمر من الأمور أن لا أفعله لكني فعلته، والآن أنا في حيرة من أمري، لكن زوجتي بعيدة عني، وأريد أن أستفتي عن هذا الموضوع فوجهوني جزاكم الله خيرا هل وقع الطلاق أم لا؟","title":"حلف بالطلاق ألا يفعل أمرا ثم فعله","answer":"الجواب: إذا كان مقصودك الامتناع من هذا الأمر وليس قصدك إيقاع الطلاق، إنما قصدت الامتناع من هذا الشيء والحذر منه فعليك كفارة يمين ولا يقع الطلاق، حكمه حكم اليمين في أصح قولي العلماء، فإذا قلت مثلًا: علي الطلاق أني ما أكلم فلان، أو علي الطلاق أني ما آكل طعام فلان، أو علي الطلاق أني ما أشرب الدخان، أو ما أشرب الخمر وما أشبه ذلك وأنت قصدك الامتناع ليس قصدك طلاق أهلك، تحبهم وليس مقصودك فراقهم، إنما المقصود أن تمتنع من هذا الشيء، فعليك كفارة يمين إذا فعلته مع التوبة إلى الله، أما إذا كان معصية مع التوبة إلى الله إذا كان معصية كشرب الخمر ونحوه.\nأما إذا كنت أردت الطلاق أردت إيقاع الطلاق يقع الطلاق يقع طلقة، إذا كنت قلت: علي الطلاق يقع به طلقة واحدة، إذا كنت قصدت الطلاق إذا فعلت الشيء المحلوف عليه، وفق الله الجميع.\nالمقدم: اللهم آمين جزاكم الله خيراً وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8391/حلف-بالطلاق-الا-يفعل-امرا-ثم-فعله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_278/27808.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":10253,"question":"رسالة وصلت إلى البرنامج من المستمع محمود أبو الحسن محمود من جمهورية مصر العربية يقول: حيث أنني وقع مني يمين، وقلت في يميني هذه: علي الطلاق بالثلاث وتروح حرمانة مثل أمي وأختي، وهذا اليمين وقع علي بسبب قطعة أرض بيني وبين أخي، وحلفت اليمين على أنني لن أضع يدي على هذه الأرض، وحاليًا مضطر لأني محتاج، أرجو إفتائي جزاكم الله خيرًا؟","title":"حكم من حلف بالطلاق ثلاثًا وبالحرام","answer":"","link":"https://binbaz.org.sa/fatwas/8424/حكم-من-حلف-بالطلاق-ثلاثا-وبالحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_336/33606.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":10263,"question":"المستمع علي حسين جابر من مدينة ضبا في الشمال بعث يسأل ويقول: إذا سئل إنسان عن أمر ما هل فعله ثم أجاب بلفظ: لا والله لم أفعله، ثم اتضح له فيما بعد أنه فعله فهل يعتبر هذا يمين؟","title":"حكم من حلف على شيء نسيانًا واتضح خلافه","answer":"الجواب: إذا كان ناسيًا ثم ذكر أنه فعله فلا يضره، يقول الله سبحانه: رَبَّنَا لا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا [البقرة:286].\nأما إذا كان متعمدًا فعليه التوبة والاستغفار وهذا خطأ، عليه التوبة والاستغفار ويكفي لأنها يمين كاذبة، فعليه التوبة والحمد لله، إذا قال: والله ما فعلت هذا؟ وهو فعله، هذا كذب ما يجوز، والله ما زرت فلان، والله ما كلمت فلان، وهو قد كلمه لكن ما أحب يخبر هذا الشخص الذي سأله، فيكون عليه التوبة إلى الله وليس عليه كفارة يمين؛ لأن هذا كذب كذبها أعظم وشرها أعظم، وإنما الكفارة تكون في اليمين المستقبلة والله لا أفعل كذا، والله لأفعلن كذا، فإذا أخل بذلك فعليه كفارة يمين، أما على الماضي فإنها تعتبر يمينًا غموس يمينًا كاذبة ليس لها كفارة إلا التوبة، لكن لو كان ناسيًا فلا شيء عليه. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8434/حكم-من-حلف-على-شيء-نسيانا-واتضح-خلافه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_337/33703.mp3","categories":["الأيمان والنذور"]},{"id":10264,"question":"حدثونا عن لغو اليمين كما يقول سماحة الشيخ؟","title":"حقيقة يمين اللغو","answer":"الجواب: يقول الله سبحانه: لا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِنْ يُؤَاخِذُكُمْ بِمَا كَسَبَتْ قُلُوبُكُمْ [البقرة:225]هكذا في سورة البقرة، وفي سورة المائدة يقول : لا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِنْ يُؤَاخِذُكُمْ بِمَا عَقَّدْتُمُ الأَيْمَانَ [المائدة:89] فلغو اليمين اليمين التي لم يعقد عليها قلبه ولم يقصدها، بل جرت على لسانه من غير قصد، في عرض كلامه، والله لا والله في عرض كلامه من غير قصد اليمين، ومن غير قصد عقدها، فهذه اليمين تكون لاغية.\nومثلها لو كان حلف على أمر يظنه مصيب، فبان غير مصيب، كأن يقول: والله لقد رأيت فلانًا ثم تبين له شبه له ليس هو فلان، وهو يعتقد أنه مصيب فهذا من لغو اليمين.\nوأما إذا قصد اليمين وعقد عليها قلبه .... في قلبه فهذه فيها الكفارة؛ لأنه قاصد لها حيث قال: والله لأفعلن كذا، والله لأزورن فلان، والله لا أزور فلان، والله لا أكلمه، والله لأكلمنه، قاصدًا ذلك، فهذا يمين منعقدة، إذا أخل بها وجبت عليه الكفارة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8435/حقيقة-يمين-اللغو","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_337/33704.mp3","categories":["الأيمان والنذور"]},{"id":10385,"question":"من الرياض المستمع أحمد عبدالله سليمان بعث يسأل ويقول: ارتكبت معصية وبعدها نذرت نذرًا وهو صيام شهر إذا كررتها مرة أخرى، وحيث أنني فعلت هذه المعصية مرة أخرى، هل يلزمني الوفاء بهذا النذر أم يعتبر من الأيمان وأكفر كفارة يمين؟","title":"حكم صيام شهر لمن ارتكب معصية","answer":"الجواب: إذا كنت نذرت الشهر أن تمتنع ليمنعك من العودة إليها، فالحكم حكم كفارة اليمين، عليك كفارة يمين ويكفي إطعام عشرة مساكين أو كسوتهم، إذا كان المقصود من النذر الامتناع من العود إليها، نذرت هذا النذر رجاء أن يمنعك الله به منها، فهذا حكمه حكم اليمين، وعليك كفارة يمين. نعم.\nالمقدم: جزاكم الله خيراً وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8557/حكم-صيام-شهر-لمن-ارتكب-معصية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_280/28010.mp3","categories":["الأيمان والنذور"]},{"id":10399,"question":"رسالة وصلت إلى البرنامج من المستمع (ع. ن. ت) من السودان دار مالي، أخونا يقول في رسالته: حلفت ثلاثًا على ألا أفعل شيئًا معينًا وفعلت ذلك الشيء، فماذا علي؟","title":"حكم من حلف على عدم فعل أمر ما ثم فعله","answer":"الجواب: عليه كفارة يمين ولو كررت اليمين مرات كثيرة، ما دام المحلوف عليه شيئًا واحدًا فالواجب كفارة واحدة، مثل أن تقول: والله لا أكلم فلان، والله لا أكلم فلان، والله لا أكلم فلان، ثم كلمته عليك كفارة واحدة، أو والله لا أزور فلان، والله لا أزور فلان، والله لا أزور فلان، ثم زرته كفارة واحدة، أما إذا كان على أفعال فكل فعل له كفارة، كأن تقول: والله لا أزور فلان، والله لا أكلم فلان، والله لا أفعل كذا شيئًا آخر كل واحد له كفارة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8571/حكم-من-حلف-على-عدم-فعل-امر-ما-ثم-فعله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_340/34006.mp3","categories":["الأيمان والنذور"]},{"id":10500,"question":"عند الكسوة في كفارة اليمين، هل هناك أعمار محددة أو لا؟","title":"حكم إخراج كفارة اليمين كسوة للصغار","answer":"الجواب: ما فيه أعمار، المقصود يعطي عشرة وبس، فلو أعطى إنساناً فقير عنده تسعة وهو العاشر كفى والحمد لله إذا كانوا فقراء. نعم.\nالمقدم: جزاكم الله خيرًا و أحسن إليكم، إذاً لا يشترط أن يكون هناك سن معين سواء كانوا أطفال أو غير أطفال؟\nالشيخ: نعم، نعم.\nالمقدم: جزاكم الله خيرًا وأحسن إليكم، مع أن هناك فارق في القيمة سماحة الشيخ كما تعلمون؟\nالشيخ: ولو ولو ينفع الجميع، ينفع الجمع إذا ..... وعياله الفقراء، نفعهم.\nالمقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8675/حكم-اخراج-كفارة-اليمين-كسوة-للصغار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_282/28208.mp3","categories":["الأيمان والنذور"]},{"id":10510,"question":"من المملكة الأردنية الهاشمية رسالة بعث بها المستمع (أ. ح. م) يسأل ويقول: قلت لزوجتي: إذا ذهبت إلى دار أهلك بدوني تكوني طالق، وبعد فترة من الزمن أجبرتها الظروف أن تذهب إلى دار أهلها برغبتي، وذهب معها زوجها ولم يدخل البيت، فما رأيكم؟","title":"حكم الطلاق المعلق بالمنع","answer":"الجواب: ما دمت ذهبت أذنت لها فلا بأس، .... قلت: بغير أذني، فإذا أذنت لها فلا حرج فالحمد لله، أما إذا لم تأذن هذا فيه التفصيل: إن كنت أردت إيقاع الطلاق يقع الطلاق، وإن كنت أردت التخويف والتحذير والمنع ولم ترد إيقاع الطلاق فهذا فيه كفارة اليمين، حكمه حكم اليمين، فيه كفارة اليمين. نعم.\nالمقدم: جزاكم الله خيرًا، يقول: إنه قال لها: بدوني.\nالشيخ: بدوني وإلا بدون إذني؟\nالمقدم: بدوني، وذهب معها إلى الباب ولم يدخل البيت؟\nالشيخ: ما دام بدوني ... ذهبت معها ما ذهبت بدونك لا حرج؛ لأنك ذهبت معها إلى الباب، فلا بأس. نعم.\nالمقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8685/حكم-الطلاق-المعلق-بالمنع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_282/28218.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":10517,"question":"ننتقل بعد هذا إلى رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات، رمزت إلى اسمها بحروف (م. م) أختنا لها رسالة مطولة كلها شكوى وملاحظات على زوجها فهي تقول: أنا فتاة في الثامنة عشرة من عمري ملتزمة والحمد لله، وقد زوجني أبي وأنا عمري في السادسة عشرة من رجل عنده امرأتان ولديه خمسة عشر ولداً، أكبرهم في سني، وأنا أشكو من زوجي الذي آمره بأن يعفي لحيته طاعة لله ورسوله، ولكنه لم يفعل بل يقصرها على آخر شيء، ولولا كثرة الشيب لكان يحلقها بالموس، ولأنه يقول: إن الموس تكثر الشيب فاتخذ القص بدلًا من الحلق، وكلما أردت أن أكرر النصيحة قال: لا تتدخلين في شأني، علماً بأنني لم أنجب أبناء منه حتى الآن، فأخبرني يا سماحة الشيخ هل أطلب الطلاق من ذلكم الرجل أم أعيش وأصبر؟ وكيف تنصحونني جزاكم الله خيرًا، علماً بأنني أعتبره عاصٍ لله ولرسوله؟","title":"حكم طلب المرأة للطلاق لامتناع الزوج من إعفاء اللحية","answer":"الجواب: لقد أحسنت في إنكار المنكر جزاك الله خيراً، وفعلت ما يجب من إنكار المنكر، والله جل وعلا هو الذي يهدي من يشاء كما قال سبحانه: لَيْسَ عَلَيْكَ هُدَاهُمْ وَلَكِنَّ اللَّهَ يَهْدِي مَنْ يَشَاءُ [البقرة:272]، ويقول سبحانه: إِنَّكَ لا تَهْدِي مَنْ أَحْبَبْتَ وَلَكِنَّ اللَّهَ يَهْدِي مَنْْ يَشَاءُ [القصص:56]، والواجب عليه أن يتقي الله، وأن يطيع الرسول ﷺ، فالرسول عليه السلام يقول: قصوا الشوارب وأعفوا اللحى، خالفوا المشركين، ويقول ﷺ: قصوا الشوارب ووفروا اللحى، خالفوا المشركين، فالواجب عليه أن يتقي الله وأن يطيع الرسول ﷺ، وأن يعفي لحيته ويكرمها ويوفرها طاعة لله ولرسوله، وحذرًا من غضب الله، فالواجب عليه أن يسمع ويطيع لأمر الله ورسوله، وأن يشكرك على ما فعلت من الخير، وأن يقبل منك النصيحة؛ لأنك فعلت ما ينبغي وما يجب.\nأما ما يتعلق بطلب الطلاق فهذا شيء يرجع إليك إذا رأيت المصلحة في طلب الطلاق فلا بأس، إذا كان استمر على حاله ولم تنجبي منه فلا مانع من طلب الطلاق لعل الله يرزقك من هو خير منه، ويرزقك أيضاً ذرية، فهذا عذر شرعي، لا بأس أن تطلبي الطلاق إذا سمح أن يطلق فهذا طيب، ولعل الله يرزقك بما هو أصلح منه. نعم.","link":"https://binbaz.org.sa/fatwas/8692/حكم-طلب-المراة-للطلاق-لامتناع-الزوج-من-اعفاء-اللحية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_283/28306.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة","الدعوة والدعاة"]},{"id":10564,"question":"نعود إلى أسئلة أختنا (ع. هـ. م) السودانية، حيث تسأل هذا السؤال عن النذر فتقول: كان لدي طفل مكسور ونذرت أن أذبح إذا قدر الله لهذا الطفل أن يمشي، فعلاً شفي الطفل وهو يمشي الآن وأسأل كيف أتصرف في النذر، هل لي الأكل منه أو لا أنا وأسرتي؟ جزاكم الله خيراً.","title":"حكم الوفاء بالنذر المشروط ولمن يعطى","answer":"الجواب: عليك أن توفي بالنذر؛ لأن النبي عليه السلام يقول: من نذر أن يطع الله فليطعه الله سبحانه مدح الموفي بالنذر فقال جل وعلا في صفة الأبرار: يُوفُونَ بِالنَّذْرِ وَيَخَافُونَ يَوْمًا كَانَ شَرُّهُ مُسْتَطِيرًا [الإنسان:7].\nوأنت على نيتك إن كنت نويت بالنذر الفقراء فقسميه بين الفقراء، وإن كنت ما نويت شيئاً فكذلك أعطيه الفقراء، أما إذا كنت نويت أن تذبحي شاة في البيت وتأكلي منها أنت وأهل البيت فأنت على نيتك، النية مقدمة في هذا، يقول النبي ﷺ: إنما الأعمال بالنيات، وإنما لكل امرئ ما نوى. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8740/حكم-الوفاء-بالنذر-المشروط-ولمن-يعطى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_322/32210.mp3","categories":["الأيمان والنذور"]},{"id":10590,"question":"نعود مع مطلع هذه الحلقة إلى رسالة إحدى الأخوات المستمعات، بعثت برسالة تقول في بدايتها: أنا أختكم في الله (ع. ن) من المدينة المنورة، أختنا عرضنا لها قضيتين في هذه الرسالة وبقي لها قضيتان، القضية الأولى المتبقية تقول: إنني نذرت نذراً إن رزقني الله بطفل أن أسميه باسم أحد الصحابة، وعندما أنجبت الطفل لم أستطع تسميته، وقد أنجبت ثمانية أطفال، فهل علي ذنب في عدم الوفاء بالنذر؟ وما هي كفارته؟ علماً بأن زوجي تزوج امرأة ثانية وأنجب منها وسمى الطفل بالاسم الذي أريده وقال: إنه وفاء لنذري فهل يكفي ذلك؟","title":"حكم من نذر بنذر ولم يستطع الوفاء به","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فعليك كفارة يمين عن نذرك، ولا يكفي كون زوجك سمى بأسماء بعض الصحابة؛ لأنك أنت الناذرة فعليك كفارة يمين، وهي إطعام عشرة مساكين أو كسوتهم، عشرة إما غداء وإما عشاء وإما نصف صاع من قوت البلد من تمر أو رز أو حنطة، هذا هو الواجب، أو كسوة كل واحد له قميص أو إزار ورداء عن يمينك. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8763/حكم-من-نذر-بنذر-ولم-يستطع-الوفاء-به","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_325/32501.mp3","categories":["الأيمان والنذور"]},{"id":10594,"question":"نعود مع مطلع هذه الحلقة إلى رسالة إحدى الأخوات المستمعات، بعثت برسالة تقول في بدايتها: أنا أختكم في الله (ع. ن) من المدينة المنورة، أختنا عرضنا لها قضيتين في هذه الرسالة وبقي لها قضيتان، القضية الأولى المتبقية تقول: إنني نذرت نذراً إن رزقني الله بطفل أن أسميه باسم أحد الصحابة، وعندما أنجبت الطفل لم أستطع تسميته، وقد أنجبت ثمانية أطفال، فهل علي ذنب في عدم الوفاء بالنذر؟ وما هي كفارته؟ علماً بأن زوجي تزوج امرأة ثانية وأنجب منها وسمى الطفل بالاسم الذي أريده وقال: إنه وفاء لنذري فهل يكفي ذلك؟","title":"حكم من نذر بنذر ولم يستطع الوفاء به","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فعليك كفارة يمين عن نذرك، ولا يكفي كون زوجك سمى بأسماء بعض الصحابة؛ لأنك أنت الناذرة فعليك كفارة يمين، وهي إطعام عشرة مساكين أو كسوتهم، عشرة إما غداء وإما عشاء وإما نصف صاع من قوت البلد من تمر أو رز أو حنطة، هذا هو الواجب، أو كسوة كل واحد له قميص أو إزار ورداء عن يمينك. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8763/حكم-من-نذر-بنذر-ولم-يستطع-الوفاء-به","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_325/32501.mp3","categories":["الأيمان والنذور"]},{"id":10612,"question":"يسأل أيضاً ويقول: عندنا في القرية إذا حصل للإنسان مكروه يقول: إذا أزال الله عني هذا المكروه سوف أذبح ذبيحة على قبر الشيخ فلان، هل يصح الأكل من هذه الذبيحة؟ وهل يصح الوفاء بهذا النذر إذا زال المكروه.","title":"أقسام النذر وحكم كل قسم","answer":"الجواب: النذر فيه تفصيل: فإذا كان النذر طاعة لله كأن يقول: لله علي إن شفى الله مريضي فلان أن أصلي كذا وكذا، أو أصوم أيام كذا وكذا، أو شهراً أو ما أشبه ذلك، أو أتصدق بكذا هذا نذر طاعة، يقول النبي ﷺ: من نذر أن يطيع الله فليطعه، فإذا قال: إن شفى الله مريضي، أو رد غائبي، أو شفيت من كذا صمت لله خمسة أيام أو عشرة أيام، تصدقت بألف درهم، صليت كذا وكذا كل هذا نذر طاعة، متى حصل المطلوب وجب عليه الوفاء.\nأما إذا كان النذر معصية لله فإنه لا يوفي به؛ لقوله ﷺ: من نذر أن يعصي الله فلا يعصه، فلو قال: لله علي إن شفى الله مريضي أن أذبح للشيخ فلان ذبيحة، للبدوي ، أو للحسين ، أو للشيخ عبد القادر أو لغيرهم، هذا شرك أكبر هذا ما يجوز، هذا لا يحل الوفاء به، وعليه التوبة إلى الله من ذلك؛ لأن هذا شرك أكبر، الذبح للأموات التقرب إليهم بالذبائح أو النذور هذا شرك أكبر، العبادة حق الله وحده، ... يقول سبحانه: وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ [الإسراء:23] ويقول سبحانه: قُلْ إِنَّ صَلاتِي [الأنعام:162] يعني: قل يا محمد للناس إِنَّ صَلاتِي وَنُسُكِي [الأنعام:162] يعني: ذبحي. وَمَحْيَايَ وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ ۝ لا شَرِيكَ لَهُ وَبِذَلِكَ أُمِرْتُ وَأَنَا أَوَّلُ الْمُسْلِمِينَ [الأنعام:162-163] ويقول سبحانه لنبيه ﷺ: إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ ۝ فَصَلِّ لِرَبِّكَ وَانْحَرْ [الكوثر:1-2]، ويقول النبي ﷺ: لعن الله من ذبح لغير الله، فلا يجوز الذبح للجن ولا للمشايخ أصحاب القبور، ولا لغيرهم من أصنام أو أشجار أو أحجار أو ملائكة أو أنبياء لا، الذبح يكون لله وحده، التقرب يكون لله بالذبح كالضحايا والهدايا لله وحده سبحانه وتعالى، فيقول: لله علي إن شفى الله مريضي أن أذبح كذا وكذا لله وحده، ناقة أو بقرة أو ذبيحة من الغنم لله وحده، هذا قربة طاعة عليه أن يوفي بذلك، أما أن يذبح للشيخ فلان يتقرب إليه حتى يشفع له أو يشفي مريضه هذا شرك أكبر، وهكذا لو قال: يا شيخ فلان اشف مريضي أو انصرني، أو يا رسول الله اشفني أو انصرني، أو يا شيخ عبد القادر انصرني، أو يا شيخ أحمد البدوي ، أو يا سيدي الحسين ، أو يا شيخ فلان انصرني، أو اشف مريضي أو رد غائبي كل هذا من الشرك الأكبر، لأنه لا يجوز دعاء الأموات ولا الاستغاثة بالأموات ولا النذر لهم، ولا سؤال الجن ولا النذر لهم، ولا التقرب للأصنام من الحجارة أو غيرها كل هذا منكر عظيم وشرك أكبر، الله يقول سبحانه: فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن:18] ويقول سبحانه: وَلا تَدْعُ مِنْ دُونِ اللَّهِ مَا لا يَنْفَعُكَ وَلا يَضُرُّكَ فَإِنْ فَعَلْتَ فَإِنَّكَ إِذًا مِنَ الظَّالِمِينَ [يونس:106] يعني: المشركين، وقال : فَاعْبُدِ اللَّهَ مُخْلِصًا لَهُ الدِّينَ ۝ أَلا لِلَّهِ الدِّينُ الْخَالِصُ [الزمر:2-3]، ويقول سبحانه: وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ [البينة:5].\nفالواجب إخلاص العبادة لله وحده، ومن ذلك الدعاء والخوف والرجاء والذبح والنذر كله عبادة، يجب أن تكون لله وحده ولا يصرف منها شيء لا لأصنام ولا للشيوخ ولا للأنبياء ولا للجن ولا للأشجار ولا للملائكة ولا غيرهم، العبادة حق الله وحده .\nوهكذا لو قال: لله عليّ إن شفى الله مريضي أو رد غائبي أن أشرب الخمر أو أزني، هذه معصية لله لا يوفي بها، هذا منكر عظيم يتقرب لله بالمعاصي هذا منكر عظيم، لا يجوز له الوفاء بذلك، وعليه كفارة يمين عن هذا النذر الباطل، عن نذر المعصية.\nوالخلاصة أن النذر أقسام: فما كان لله وحده إذا كان طاعة لله وجب الوفاء به، وما كان معصية أو شركاً لا يوفى به، المعصية يجب التوبة منها، والشرك يجب التوبة منه.. تجب التوبة منه، أما إذا كان لا ليس شركاً ولا معصية ولا طاعة، مثل: لله علي أن أزور فلان أو آكل طعام فلان، هذا مخير إن شاء زاره وإن شاء كفر عن نذره ولم يزره ولم يأكل طعامه، مخير؛ لأن هذا مباح، أو لله علي أن أعزم فلان وأصنع له طعام هو مخير إن شاء عزمه ودعاه وإن شاء تركه، لكن إذا لم يعزمه ولم يوف بنذره فعليه كفارة يمين، وهي إطعام عشرة مساكين أو كسوتهم أو عتق رقبة، فإن عجز صام ثلاثة أيام، هذه كفارة اليمين كما نص على ذلك ربنا  في سورة المائدة. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8785/اقسام-النذر-وحكم-كل-قسم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_326/32612.mp3","categories":["الأيمان والنذور"]},{"id":10614,"question":"المستمع فهد عبد الله باسلامة من جدة، بعث برسالة يقول فيها: ما قولكم في شخص قال -في نفسه دون أن ينطق-: إن شاء الله سوف أصوم ولا أتوقف إلا بعذر شرعي لا أستطيع السيطرة عليه، ولكن توقف بدون العذر، هل يعتبر هذا نذراً عليه، علماً أنه قال هذا دون أن يطلب من الله شيئاً، أي: أنه لم يقل: إذا وفقت، أو إذا وفقني الله في عمل ما سوف أصوم، بل كان مجرد كلام في نفسه، وجهونا حول هذا الموضوع جزاكم الله خيراً؟","title":"حكم تبييت النذر في النية دون التلفظ به","answer":"","link":"https://binbaz.org.sa/fatwas/8794/حكم-تبييت-النذر-في-النية-دون-التلفظ-به","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_327/32706.mp3","categories":["الأيمان والنذور"]},{"id":10619,"question":"رسالة وصلت إلى البرنامج من المستمع: محمد صالح محمد أحمد ، أخونا محمد يقول: حلفت يوماً من الأيام أن لا أفعل شيئاً ما، ولكني فعلت ذلك الشيء، ماذا يجب علي أن أفعل، علماً بأني لا أستطيع الصيام؟","title":"كفارة من حنث ولا يستطيع الصيام","answer":"الجواب: عليك الكفارة كفارة يمين، الله يقول سبحانه: لا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِنْ يُؤَاخِذُكُمْ بِمَا عَقَّدْتُمُ الأَيْمَانَ فَكَفَّارَتُهُ إِطْعَامُ عَشَرَةِ مَسَاكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍ فَمَنْ لَمْ يَجِدْ فَصِيَامُ ثَلاثَةِ أَيَّامٍ ذَلِكَ كَفَّارَةُ أَيْمَانِكُمْ إِذَا حَلَفْتُمْ [المائدة:89]، فالصيام إنما هو بعد العجز عن الإطعام، والعجز عن الكسوة، والعجز عن العتق، فإذا حلفت أن تفعل شيئاً ولم تفعله، فعليك إطعام عشرة مساكين، إطعام عشرة مساكين من أوسط ما تطعم أهلك، من طعامكم من رز أو تمر أو حنطة، وإذا كان معه إدام مع الرز أو مع الحنطة، إدام كان ذلك أفضل.\nوإن عشيتهم في بيتك أو في مطعم أو في أي مكان أو غديتهم أو كسوتهم كسوةً تجزئهم في الصلاة حصل المقصود والحمد لله.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8791/كفارة-من-حنث-ولا-يستطيع-الصيام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_327/32703.mp3","categories":["الأيمان والنذور"]},{"id":10668,"question":"المستمع علي محمد علي سوداني مقيم بالمجمعة، بعث برسالة يقول فيها: فقدت مني أشياء ثمينة، فأقسمت بالله العظيم أن من يجدها سأعطيه مكافأة، ووجدها رجل لكني لم أعطه شيئاً حتى الآن، فهل علي إثم في هذا؟ وهل يجب علي أن أعطيه المكافأة، أفيدوني جزاكم الله خيراً؟","title":"حكم من أكد وعده بيمين على إعطاء شيء ولم يفعل","answer":"الجواب: يشرع لك أن توفي بوعدك، وما حلفت عليه، وتعطيه المكافأة المناسبة وإن لم تعطه فعليك كفارة اليمين لأنه حلف، إما أن تعطيه مكافأة وإما أن تكفر كفارة يمين، والمشروع لك أن تعطيه المكافأة لأنك وعدت وحلفت على ذلك فينبغي لك أن توفي والمؤمن إذا وعد وفى.  نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8847/حكم-من-اكد-وعده-بيمين-على-اعطاء-شيء-ولم-يفعل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_329/32913.mp3","categories":["الأيمان والنذور"]},{"id":10678,"question":"إذا حلف إنسان بأن يفعل شيئاً ولم يفعله مع استطاعته، فما الحكم في هذه الحالة؟","title":"حكم من حلف على فعل شيء ولم يفعله","answer":"الجواب: عليه كفارة اليمين، إذا قال: والله لأكلمن فلان، أو والله لأزورن فلان، أو والله لأعطين فلان كذا وكذا فلم يفعل فعليه كفارة يمين: وهي إطعام عشرة مساكين أو كسوتهم أو عتق رقبة، فمن عجز صام ثلاثة أيام. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8863/حكم-من-حلف-على-فعل-شيء-ولم-يفعله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_330/33013.mp3","categories":["الأيمان والنذور"]},{"id":10691,"question":"من جمهورية مصر العربية محافظة كفر الشيخ المستمع: عيد السيد صلاح بعث برسالة يقول فيها: ذات يوم أعطيت شيئاً لشخص ما، واتفقت معه على ثمنه، وحدد اليوم المتفق عليه لرد الثمن، وذهبت إليه في الموعد المحدد لكي أسترد ثمنه فلم يستجب، فكررت الطلب عدة مرات، وفي يوم ما جلست معه لكي نتفاهم فلم يستجب، وفي هذه اللحظة ثارت أعصابي فحلفت اليمين بالطلاق: لو أن هذا الشيء موجود في هذه اللحظة لأحرقته، وهو ليس موجود فعلاً، ولكنه أحضره بعد عشرة أيام، فماذا أفعل به؟ هل أحرقه؟ أم ماذا أفعل جزاكم الله خيراً؟","title":"حلفت على إحراق شيء إن وُجِد ثم وجد بعدُ؛ فماذا أفعل؟","answer":"الجواب: ما دامت النية للوقت الحاضر، لو كان حاضراً لأحرقته ما عليك شيء؛ لأنك حلفت الوقت الحاضر، ولم تحلف على أنك تحرقه مستقبلاً، والأعمال بالنيات، فليس عليك شيء.\nالمقدم: جزاكم الله خيراً.\nالشيخ: نعم.","link":"https://binbaz.org.sa/fatwas/8865/حلفت-على-احراق-شيء-ان-وجد-ثم-وجد-بعد-فماذا-افعل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_330/33015.mp3","categories":["الأيمان والنذور"]},{"id":10739,"question":"رسالة وصلت إلى البرنامج من كرار نافع مصطفى ، يقول في رسالته -وهي طويلة- يقول: رزقني الله بثلاثة من الأولاد، وعاهدت نفسي وقلت: إذا رزقني الله بغلام في المرة القادمة -إن شاء الله- سوف أجعل تعليمه يكون في الأزهر الشريف من المرحلة الابتدائية وحتى نهاية تعليمه، طمعاً في أن يكون حافظاً للقرآن الكريم والفقه والسنة، وكنت أتمنى أن يكون واعظاً دينياً، ورزقني الله بهذا الغلام واستجاب الله لدعائي، وكبر الغلام وبلغ الخامسة من عمره فأردت أن أوفي بعهدي، ولكن حدثت مشكلة أنني أسكن في الناحية الغربية لنهر النيل والمعهد الديني بالناحية الشرقية، والحائل بيننا هذا النيل، ولم يكن عندنا قطارات أو سيارات، ولكن في الناحية الموجود بها المعهد قطارات وسيارات تمر، وخشيت على ابني من الغرق في النيل أو الخطر من القطارات والسيارات، ولم يكن لدي أي وقت أن أذهب بنفسي إلى المعهد؛ لأنني أعمل في الزراعة، ولم أجد أحداً من أهل القرية يريد أن يأخذ ابني معه.خلاصة ما في الموضوع: أنني لم أتمكن من الوفاء بما قلت، أرجو توجيهي جزاكم الله خيراً، وهل أكون قد ارتكبت إثماً؟","title":"كفارة النذر وحكمه إذا قيد بالمشيئة","answer":"الجواب: إن كنت نذرت قلت: لله علي أو نذر لله، أو صدقة لله أن أجعل ولدي في الأزهر نذراً، فهذا تكفر بكفارة كفارة يمين؛ لأنك لا تطيق هذا الشيء، فعليك كفارة يمين والحمد لله، وهي إطعام عشرة مساكين، كفارة اليمين إطعام عشرة مساكين أو كسوتهم، أو عتق رقبة مؤمنة، فإذا أطعمت عشرة عشيتهم أو غديتهم أو كسوتهم، كسوة تجزئهم في الصلاة فقد أديت ما عليك والحمد لله.\nوإذا أعطيتهم طعاماً كل واحد كيلو ونصف من الرز أو التمر أو الحنطة كفى ذلك، وإن كسوت كل واحد قميصاً كفى ذلك.\nأما إن كنت ما نذرت إن قلت: لأفعلن ولكن ما نذرت ما قلت: نذر لله ولا حلفت فليس عليك شيء، ولكن تلتمس له المدرسة الطيبة التي فيها الناس الطيبون الأخيار من أهل السنة والجماعة ، من أنصار السنة وغيرهم من أهل السنة المعروفين بالخير حتى يدرس فيها، أو معهداً من المعاهد الشرعية السليمة الطيبة يدرس فيه، والحمد لله عليك أن تجتهد حتى يكون في مدرسة طيبة تدرس القرآن وتعلم الناس العلوم الشرعية، وليس فيها مخرفون من أهل البدع حتى تكون بذلك قد أديت الأمانة؛ لأنه أمانة في ذمتك هذا الولد أمانة، فعليك أن تجتهد حتى يكون تعليمه في محل طيب، ليس فيه خرافات بل في مدرسة طيبة أو معهد طيب، ولا يلزمك أن تعلمه في الأزهر، وعليك كفارة يمين إذا كنت ناذراً، أما إذا كنت ما نذرت إنما قلت: إن شاء الله، أو سأفعلن كذا هذا ليس بنذر، ولا عليك شيء، أما إن قلت: والله لأفعلن أو نذر لله علي لأفعلن فعليك كفارة يمين.\nأصلح الله ولدك ووفقنا وإياك للخير.\nالمقدم: جزاكم الله خيراً، سماحة الشيخ! فيما إذا قيد كلامه بالمشيئة؟\nالشيخ: ما عليه شيء، إذا قال: إن شاء الله ما عليه شيء. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8915/كفارة-النذر-وحكمه-اذا-قيد-بالمشيىة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_345/34506.mp3","categories":["الأيمان والنذور"]},{"id":10856,"question":"المستمع (م. ع. م) القرني يقول: هل يجوز دفع النقود بدلًا من الإطعام، وذلك عن كفارة اليمين؟","title":"حكم دفع النقود بدلاً عن الإطعام في كفارة اليمين","answer":"الجواب:  لا، لا يجوز دفع النقود لا عن كفارة اليمين، ولا عن كفارة الظهار، بل هو إطعام، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9045/حكم-دفع-النقود-بدلا-عن-الاطعام-في-كفارة-اليمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_357/35713.mp3","categories":["الأيمان والنذور"]},{"id":10863,"question":"بعد هذا رسالة وصلت إلى برنامج من حجر في الأحساء المنطقة الشرقية، وصلت رسالة من أحد الإخوة المستمعين يقول: أخوكم (ن. أ. إبراهيم . أ. أ) عرض قضية يقول فيها: أنا شاب وقعت لي شبهة في نذر منذ سنوات، وأنا متردد بين أمرين، بين شك ويقين، هل نويت النذر، أو لم أنو؟ ولكن في غالب تفكيري يترجح عندي أني نويت النذر، هذا فصل، الفصل الآخر أنا شاك في عدد النذر، ما بين شاة واحدة وبين اثنتين، وقد اشتريتهما، وفي انتظار ما تتفضلون به من الإجابة حول هذا الموضوع، جزاكم الله خيرًا.","title":"حكم من شك في أنه نذر أم لا","answer":"الجواب:  إذا كان يغلب على ظنك أنك نذرت شاة، أو شاتين لله سبحانه إن الله عافاك أو شفاك من مرض، أو شفى فلانًا، أو أن الله نجحك في أمر من الأمور، أو نجح ولدك فأوف بنذرك، وأبر ذمتك حتى تكون على راحة وطمأنينة، ولكن لا يلزمك إلا باليقين، لا يلزمك النذر إلا باليقين لقول النبي ﷺ: من نذر أن يطيع الله فليطعه، ومن نذر أن يعصي الله فلا يعصيه، والله مدح المؤمنين الموفين بالنذور فقال سبحانه: يُوفُونَ بِالنَّذْرِ وَيَخَافُونَ يَوْمًا كَانَ شَرُّهُ مُسْتَطِيرًا [الإنسان:7]. فإذا كنت جازمًا وجب عليك الوفاء من أجل الطاعة، كأن تقول: لله علي إن شفاني الله من كذا أن أذبح شاة، أو شاتين، أو أتصدق بكذا وكذا، أو إن الله شفى ولدي، أو زوجتي، أو أخي، أو إن الله نجحني في كذا، أو نجح ولدي في كذا ذبحت كذا وكذا، أو تصدقت بكذا وكذا، أو صمت كذا وكذا؛ توفي بنذرك، هذا إذا كنت جازمًا.  أما إذا كنت شاكًا فلا يلزمك، لكن إذا وفيت بذلك براءة للذمة واحتياطًا وحرصًا على الخير، فهذا أطيب وأحسن وأفضل، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9037/حكم-من-شك-في-انه-نذر-ام-لا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_357/35705.mp3","categories":["الأيمان والنذور"]},{"id":10869,"question":"المستمع (م. ع. م) القرني يقول: هل يجوز دفع النقود بدلًا من الإطعام، وذلك عن كفارة اليمين؟","title":"حكم دفع النقود بدلاً عن الإطعام في كفارة اليمين","answer":"الجواب:  لا، لا يجوز دفع النقود لا عن كفارة اليمين، ولا عن كفارة الظهار، بل هو إطعام، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9045/حكم-دفع-النقود-بدلا-عن-الاطعام-في-كفارة-اليمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_357/35713.mp3","categories":["الأيمان والنذور"]},{"id":10927,"question":"رسالة وصلت إلى البرنامج من المستمع (أ. ي. أ) مصري مقيم بالرياض، أخونا رسالته مطولة بعض الشيء، يقول فيها: لظروف ما أقيم أنا وزوجتي وأولادي في منزل الأهل، وحدث خلاف في المنزل كان على أثره أنني قمت بحلف يمين الطلاق على زوجتي بعدم تركها للمبيت بمنزل الأهل، بنية الذهاب بها إلى منزل والدها، إلا أن زوجتي وقعت على الأرض فاقدة النطق والحركة، وحملتها وذهبت بها إلى الطبيب في نفس اليوم، وأحضرت لها علاجًا، وشعرت أنني لا أستطيع تنفيذ يميني؛ وخوفًا من وقوع يميني حملتها، ولأنها لا تقدر على الحركة جعلتها تبيت عند إحدى الجارات بنفس المنزل، ف هل يقع يمين الطلاق بسبب عدم الذهاب بها إلى منزل والدها، أو عند حملها للمبيت عند إحدى الجارات، ذلك أني تفاديت وقوع اليمين لعدم مبيتها معي في نفس الغرفة التي تقيم معي فيها، أرجو الإفادة؟ هل إذا وقع اليمين له رد أو كفارة؟ وكيف أرد اليمين، أو أؤدي الكفارة؟ أفيدوني جزاكم الله خيرًا.","title":"حكم الحلف بالطلاق المعلق دون الوفاء به","answer":"الجواب: سؤالك هذا فيه اشتباه من جهة أوله، فإذا كان مقصودك أنك طلقتها على أنك تنقلها إلى بيت أبيها، وبسبب الحادث الذي أصابها لم تتمكن من نقلها إلى بيت أبيها، فهذا يرجع إلى نيتك، فإن كان مقصودك بذلك الطلاق حث نفسك على نقلها إلى بيت أبيها، وعدم مبيتها في بيت أهلك إذا كان هذا قصدك أنك تنقلها من بيت أهلك إلى بيت أبيها للمبيت عند أبيها تلك الليلة، وليس المقصود فراقها إن لم تنقلها، إنما أردت حث نفسك على نقلها إلى بيت أبيها بسبب ما حدث في بيت الأهل، فهذا له حكم اليمين وعليك كفارة اليمين؛ لأنك لم تحقق ما حلفت عليه.  أما إن كان قصدك فراقها إن لم تنقلها في نيتك، وفي قصدك أنك إذا لم تنقلها إلى بيت أبيها تلك الليلة، فإنه يقع عليها الطلاق، فإنه يقع عليها طلقةً واحدة، ولك مراجعتها ما دامت في العدة، إذا كنت لم تطلقها قبل هذا طلقتين، إذا كنت لم تطلقها قبل هذا الطلاق طلقتين فلك أن تراجعها، وتقع واحدة، إذا كنت قصدت إيقاع الطلاق إن لم تنقلها إلى بيت أبيها.  فأما إن كان المقصود هو حث نفسك على نقلها، والتشديد على نفسك أن تنقلها، وليس المقصود فراقها إن لم تنقلها فهذا له حكم اليمين، وإذا كنت في الرياض قريبًا فبالإمكان أن تأتي ونسألك من الرأس عما نويت وقصدت بهذا الطلاق، وعن صفة الواقع بالتفصيل، نسأل الله للجميع الهداية، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9116/حكم-الحلف-بالطلاق-المعلق-دون-الوفاء-به","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_362/36213.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":10931,"question":"يقول: كنت قد حلفت بالله كاذبًا، ولكن كان هذا الحلف لابد منه، فلو لم أحلف كاذبًا -والله أعلم- كان قد أصابني ظلم، فماذا تعد هذه اليمين؟","title":"حكم الحلف الكاذب للاضطرار","answer":"الجواب:  إذا كنت مضطرًا إليها فلا شيء عليك، تسمى يمين الغموس إذا كان الإنسان ليس مضطرًا لها، فإذا اضطر إليها فلا حرج في ذلك، كأن يطلب منه أن يقر بشيء وهو بريء منه، فيحلف أنه لم يفعله وهو يعتقد أنه فعله، لكن لو أقر به لأقيم عليه الحد، فلا حرج أن يحلف، ويستر على نفسه. المقصود أنه إذا حلف يمينًا اضطر إليها، ولو لم يحلف لأصابه شيء يضره، وليس فيها حق لمسلم، فإنه لا حرج عليه ليدفع عن نفسه الضرر، ومن ذلك لو قيل له: احلف أنك ما زنيت، أو ما شربت الخمر، أو ما أشبه ذلك، فحلف على ذلك؛ لئلا يقام عليه الحد فلا حرج عليه في ذلك، وعليه التوبة إلى الله فيما بينه وبين ربه  ومن تاب تاب الله عليه إذا صدق في التوبة. أما إذا كان في حق المسلم كأن يحلف أنه ما عنده دين لفلان، أو ما عنده حق لفلان، وهو يكذب فهذه يمين الغموس، هذا عليه فيها الإثم العظيم، ولا تبرأ ذمته، وعليه أن يسلم الحق لصاحبه ولو حلف، عليه أن يتوب إلى الله، ويسلم الحق لصاحبه من مال أو قصاص، أو غير ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9113/حكم-الحلف-الكاذب-للاضطرار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_362/36210.mp3","categories":["الأيمان والنذور"]},{"id":10956,"question":"نذر أحدهم نذرًا، فلم يقدر أن يوفيه لله  ماذا يفعل؟ هل ينتظر حتى يتمكن، أم أن هناك كفارة؟","title":"حكم من نذر ولم يستطع الوفاء بنذره","answer":"الجواب: ينتظر حتى يعينه الله، فمن نذر أن يصوم، ولكن أصابه مرض ينتظر حتى يزول المرض، أو نذر أن يتصدق بمال، وليس عنده المال، يكون في ذمته، فمتى تيسر تصدق، وإن مات وهو عاجز فلا شيء عليه، ولكن يخرج من التركة إن كان له تركة، كأن يقول: لله عليه أن يتصدق بألف ريال على الفقراء والمساكين، ومات وهو عاجز لم يتصدق، وخلف تركة فإنه يؤدى منها هذا الحق، كما تؤدى الديون التي للناس، يؤدى حق الله  يخرج من التركة، ويوفى عنه هذا النذر. وهكذا لو نذر أن يصوم، فإنه يصوم عنه أولياؤه كأخيه وعمه وولده، لقوله ﷺ: من مات وعليه صيام صام عنه وليه فإن لم يصوموا أخرجوا، تصدقوا عنه عن كل يوم إطعام مسكين، عن كل يوم إطعام مسكين. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9144/حكم-من-نذر-ولم-يستطع-الوفاء-بنذره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_364/364011.mp3","categories":["الأيمان والنذور"]},{"id":11025,"question":"يقول: لقد حلفت بالطلاق على ألا أعمل في إحدى الشركات لكون راتبها قليل، ولكن لظروف معينة اضطررت للعمل في تلك الشركة، فما حكم ذلكم الطلاق؟","title":"حكم من حلف بالطلاق ألا يعمل ثم اضطر للعمل","answer":"الجواب:  إذا كان مقصودك الترك والامتناع، وليس قصدك إيقاع الطلاق إن عدت إلى الشركة فإنه لا يقع الطلاق، وعليك كفارة يمين، حكمه حكم اليمين، وهي إطعام عشرة مساكين -عشرة فقراء- أو كسوتهم، أو عتق رقبة، كل واحد يعطى نصف صاع، كيلو ونصف من التمر أو الحنطة أو الرز، نصف صاع، كيلو ونصف، أو قميص، أو إزار ورداء يجزئان في الصلاة، أو عتق عبد، فإن عجزت تصم ثلاثة أيام، هذا إذا كنت ما قصدت الطلاق إنما قصدت الامتناع، ومنع نفسك من الشركة. أما إن كنت قصدت إيقاع الطلاق فإنه يقع الطلاق، فإذا قلت: علي الطلاق ما أعمل عند الشركة، وقصدك إيقاع الطلاق تقع طلقة واحدة، إذا عملت عندهم تراجع زوجتك، إذا كنت ما طلقتها قبل هذا طلقتين راجعها، أما إذا كنت ما أردت إلا الامتناع من التوظف عندها، وليس قصدك إيقاع الطلاق، فهذا له حكم اليمين كما تقدم، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9203/حكم-من-حلف-بالطلاق-الا-يعمل-ثم-اضطر-للعمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_367/36704.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":11047,"question":"السائل: (ح. م. س) من شمال سيناء، يقول: إطعام ستين مسكينًا كيف يكون الإطعام؟ هل هو لمدة ثلاثين يومًا عن كل يوم مرتين؟ أو إطعام ستين يومًا كل يوم مرة؟ أرجو منكم الإفادة.","title":"كيفية إطعام ستين مسكيناً في الكفارة","answer":"الجواب:  المطلوب يعطيه ستين مسكينًا ولو في يوم واحد، يوزع عليهم الطعام ثلاثين صاعًا، كل واحد نصف الصاع من التمر، أو من الأرز، أو الحنطة، يعني: كل واحد كيلو ونص تقريبًا، ولو في يوم واحد كفى، لكن لابد يكون ستين مسكينًا، يوزع عليهم الطعام، أو يعشيهم جميعًا، أو يغديهم، أو متفرقين، كل يوم يعشي عشرة، أو يغدي عشرة، أو عشرين لا بأس، لا بد أن يكون ستين، يطعمهم شيئًا نيئًا بأيديهم، أو يدعوهم، يجعل لهم وليمة غداء، أو عشاء، سواء مجتمعين، أو متفرقين. نعم.","link":"https://binbaz.org.sa/fatwas/9225/كيفية-اطعام-ستين-مسكينا-في-الكفارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_288/28803.mp3","categories":["الجماع في نهار رمضان","الأيمان والنذور"]},{"id":11048,"question":"هذا سائل من الأردن: كنت نذرت لله تعالى بأن أذبح أمام أحد المساجد في مدينة الزرقاء، وهذا المسجد يقع في السوق، وعلى شارع رئيسي، وأن أوزع ما أذبحه على الفقراء، فهل يجوز أن أستبدل المسجد ليتم الذبح في مسجد آخر، ليأكل منه الفقراء والأغنياء من أهل الدعوة إلى الله تعالى؟ علمًا بأن الذبح فيه سهل وميسور، وكذلك الطبخ، جزاكم الله خيرًا.","title":"حكم من نذر أن يذبح أمام مسجد ثم غير رأيه","answer":"الجواب:  لا حرج في ذلك، إذا كنت لا تقصد فقراء معينين عند المسجد الأول، إنما قصدت جنس الفقراء، وليس لك قصد في فقراء معينين فلا مانع أن تذبحها عند مسجد آخر، أما إذا كنت تقصد فقراء معينين عند المسجد الأول، تريد الإحسان إليهم في نذرك فاذبح في محلك الأول؛ لأنك قصدت فقراء معينين، أما إذا كان قصدك الفقراء فقط من حيث الحاجة، وليس قصدك فقراء الحارة المعينة في نذرك فلك أن تذبح فيها، وفي غيرها. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9226/حكم-من-نذر-ان-يذبح-امام-مسجد-ثم-غير-رايه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_288/28804.mp3","categories":["الأيمان والنذور"]},{"id":11074,"question":"تقول السائلة سماحة الشيخ: لقد حصل بيني وبين زوجي شجار، وحلف بالحرام أن لا يأخذ مني أي مبلغ من المال، ولكن زوجي -تقول- ذو حاجة، فهل أعطيه ليشتغل به إذا احتاج، ويدفع لي أرباحًا عليه نصف الربح، ولي النصف الآخر، أو أحسب ما نتفق عليه؟","title":"حكم من حلف بالحرام ألا يأخذ من زوجته مالاً","answer":"الجواب:  لا مانع من دفع المال إليه مضاربة بالنص، أو بالثلث أو بالربع لا بأس، يكون لك نصف الربح، أو ثلث، الربح، أو أكثر، أو أقل، لا حرج في ذلك، هذه تسمى مضاربة، وأما تحريمه إن كان قصده أنه ما يقبل منك عطية فهذه ما هي بعطية هذه معاملة شركة، فلا حرج عليه. أما إذا كان قصده لا يقبل منك عطية، ولا مضاربة، ولا أي معروف فعليه كفارة يمين عن تحريمه، كفارة يمين، إطعام عشرة مساكين، أو كسوتهم؛ لأن التحريم للشيء الذي أحله الله يكون بمثابة اليمين، إلا إذا قصد تحريم الزوجة فهذا يكون له حكم الظهار، أما إذا قصد تحريم الشيء الذي.. المال أو الملبس أو السكن أو الكلام، فهذا يكون حكمه حكم اليمين. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9252/حكم-من-حلف-بالحرام-الا-ياخذ-من-زوجته-مالا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_288/28822.mp3","categories":["الأيمان والنذور"]},{"id":11097,"question":"السائلة تقول سماحة الشيخ: هل يشترط لكفارة اليمين بالنسبة لصيام ثلاثة أيام أن تكون متتابعة؟ فإن كان يشترط أن تكون متتابعة فماذا أفعل بالذي قمت بأدائه؟ هل أقوم بإعادتها أم لا؟ جزاكم الله خيرًا.","title":"حكم تتابع صيام كفارة اليمين","answer":"الجواب:  الصواب أنه لا يشترط؛ لأن الله قال: فَصِيَامُ ثَلاثَةِ أَيَّامٍ [المائدة:89]، وأطلق  لكن إذا صامتها متتابعة يكون أحسن؛ خروجًا من الخلاف؛ لأنه جاء عن ابن مسعود، وعن جماعة صومها متتابعة، ولكن الصواب، أنها لا تجب المتابعة، فإذا صامتها مفرقة أجزأت، نعم، إنما التتابع مستحب. نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/9275/حكم-تتابع-صيام-كفارة-اليمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_290/29005.mp3","categories":["الأيمان والنذور"]},{"id":11143,"question":"بعد هذا رسالة وصلت إلى البرنامج من مدينة الخبر باعثها المستمع عبدالسلام الرشيدي، يقول: أولًا: يقول لكم سماحة الشيخ: أتقدم لفضيلة الشيخ لكي أسأله عن حكم من أراد أن يقلع عن فعل ذنب من الذنوب رغبة منه في التوبة إلى الله، والإقلاع عن هذا الفعل المحرم الذي لا يعد من الكبائر، ورغبة منه في زجر نفسه ونهيها أقسم بالله العظيم على كتابه الكريم في مسجد الله، وأعاهد الله على ألا يعود لفعل ذلك المحرم، ولكن بعد أن أقسم استمر فترة وجيزة ملتزمًا بما عاهد الله عليه، ثم خدعه الشيطان، وغلبه هواه، فعاد إلى ذلكم الفعل المحرم، ما حكم هذه الحالة؟ وما هي كفارة هذا القسم على القرآن في المسجد، وبماذا تنصحون به هذا الذي يرغب رغبة أكيدة بالتوبة النصوح، ثم يغلبه هواه فيعود لاقتراف الفعل المحرم؟ جزاكم الله خيرًا.","title":"حكم من تاب من ذنب وأقسم ألا يعود ثم عاد","answer":"الجواب:  على المذنب -سواء كان الذنب كبيرًا أو صغيرًا- عليه التوبة إلى الله، والمسارعة إلى ذلك، ولا يلزمه القسم ولا حاجة إلى القسم، بل الواجب عليه الندم على ذنبه الماضي، والحزن على ذلك، والترك له خوفًا من الله، وتعظيمًا له سبحانه، والعزم الصادق ألا يعود، هذا الواجب عليه، أمور ثلاثة: أولًا: الندم على الماضي. ثانيًا: ترك الذنب والحذر منه، تعظيمًا لله ورغبة فيما عنده سبحانه. ثالثًا: العزم الصادق ألا يعود في ذلك. ولا حاجة إلى أن يقسم، ولا حاجة إلى أن يكون في المسجد، فإذا أقسم كان الأمر أشد، إذا أقسم بالله على المصحف، أو في المسجد كان الأمر أعظم، ولكن لا يلزمه ذلك، ولا حاجة إلى القسم، التوبة تكفي بدون قسم، وبدون وجوده في المسجد، متى ندم وأقلع، وترك الذنب، وعزم ألا يعود قبل الله منه في أي مكان، وفي أي زمان، وإذا عاد يؤخذ بالذنب بعد العودة.  أما الماضي فقد تاب منه وانتهى، لكن عليه أن يتوب من العودة التي زين له الشيطان العودة فيها، عليه أن يتوب مثل ما تاب أولاً، وكلما تاب تاب الله عليه، إذا صدق في التوبة وأخلص فيها واستوفى شروطها، وعليه كفارة يمين التي حلفها أنه لا يعود، عليه كفارة يمين، وهي إطعام عشرة مساكين أو كسوتهم، أو عتق رقبة، فإن عجز صام ثلاثة أيام... كما بين الله ذلك في كتابه العظيم من سورة المائدة، حيث قال سبحانه: لا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِنْ يُؤَاخِذُكُمْ بِمَا عَقَّدْتُمُ الأَيْمَانَ فَكَفَّارَتُهُ إِطْعَامُ عَشَرَةِ مَسَاكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍ فَمَنْ لَمْ يَجِدْ فَصِيَامُ ثَلاثَةِ أَيَّامٍ ذَلِكَ كَفَّارَةُ أَيْمَانِكُمْ إِذَا حَلَفْتُمْ وَاحْفَظُوا أَيْمَانَكُمْ [المائدة:89]، هكذا يقول . فالواجب على من حلف ألا يفعل شيئًا، ثم فعله أن يكفر هذه الكفارة، وإن كان ذنبًا فعليه مع الكفارة التوبة، الندم، والإقلاع، والعزم الصادق ألا يعود، تعظيمًا لله، ورغبة فيما عنده . وإن كان الذنب يتعلق بالمخلوق ظلمًا له في دم، أو مال، أو عرض، فلابد أن يستحله من هذا الذنب، شرط رابع لا بد منه، أو يعطيه حقه، إما أن يستحله فيسمح أو يعطيه حقه، وإن كان الذنب عرضًا يعني: غيبة، استحله إن تيسر، وإلا دعا له، واستغفر له، وذكره بالأعمال الطيبة التي يعرفها عنه، ذكره بأخلاقه الطيبة التي يعرفها عنه بدلاً مما ذكره عنه من الأخلاق السيئة، تكن هذه بهذه، رزق الله الجميع الهداية والتوفيق. المقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9332/حكم-من-تاب-من-ذنب-واقسم-الا-يعود-ثم-عاد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_370/37008.mp3","categories":["الرقائق","الأيمان والنذور"]},{"id":11166,"question":"بعد هذا رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول: المستمع عبدالله مقيم في الرياض يقول: حلفت بالطلاق لأحد الإخوان حتى يأخذ مبلغًا من المال فرفض وحلف بالله أن لا يأخذ المبلغ، فهل وقع الطلاق حينئذٍ جزاكم الله خيرًا؟","title":"حكم الحلف بالطلاق بنية الحث أو المنع أو الإلزام","answer":"الجواب:  هذا فيه تفصيل: إن كان المقصود إلزامه بالأخذ، التأكيد عليه، وليس قصدك إيقاع الطلاق فإنه لا يقع الطلاق ويكون له حكم اليمين، وعليك كفارة يمين، فإذا قال الإنسان: عليه الطلاق أن تأخذ هذه الدراهم، أو عليه الطلاق أن تأكل الطعام، أو عليه الطلاق أن تخرج من البيت، أو عليه الطلاق أن تسافر إلى كذا، ولم ينفذ يكون عليك كفارة يمين، إذا كان المقصود التأكيد في الموضوع ليس المقصود إيقاع الطلاق، وإنما المقصود التأكيد فيما ذكر، فإنه يكون في حكم اليمين، وعليه كفارة اليمين، إذا أخل المحلوف عليه بالشرط ولم يمتثل، فإذا قال: عليه الطلاق أن تشرب القهوة وأبى وقصده إلزامه ليس قصده تطليق زوجته، وإنما المقصود إلزامه، والتأكيد عليه، فهذا فيه كفارة يمين، وهكذا لو قال لزوجته: عليه الطلاق أن لا تخرجي من البيت، أو أن لا تكلمي فلانًا والقصد المنع، المنع من الخروج أو من الكلام فلم تمتثل فإن عليه كفارة يمين، ولا يقع الطلاق؛ لأن هذه الأنواع كلها في حكم اليمين، والمقصود منها التأكيد بفعل شيء أو منع شيء، أما إذا كانت له نية أخرى ..... ينظر فيه إذا وقع، يستفتي فيه العلماء ويفتونه إذا كان له نية أخرى غير هذا غير نية المنع والحث. فالمقصود: أن هذه الشروط فيها تفصيل: تارة صاحبها يقصد المنع من شيء، أو الحث على شيء، وتارة يقصد هذا مع الطلاق، فإذا قصد الأمرين جميعًا وقع الطلاق، إن لم يكن هناك مانع من وقوعه، نعم، من حيض أو نحو ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9351/حكم-الحلف-بالطلاق-بنية-الحث-او-المنع-او-الالزام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_371/37115.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":11197,"question":"يقول: إذا حلف شخص على شخص آخر بأن يدخل محله أو يأخذ شيئًا معينًا مثلًا ولم يوافق المحلوف عليه، فهل يلزم الحالف كفارة أفتونا جزاكم الله خيرًا؟","title":"حكم من حلف على شخص بفعل شيء ولم يفعله","answer":"الجواب:  نعم يلزمه الكفارة، يلزمه الكفارة إذا أبى المحلوف عليه مثل لو قال: والله تفضل للقهوة أو للغداء أو للعشاء وأبى يكون عليه كفارة يمين. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9368/حكم-من-حلف-على-شخص-بفعل-شيء-ولم-يفعله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_372/37213.mp3","categories":["الأيمان والنذور"]},{"id":11211,"question":"هذا السائل من الطائف أبو فيصل يقول: يا سماحة الشيخ! بأنه قبل ثلاثة أعوام حلف على زوجته بكلمة الحرام، بأنك لو فعلت كذا وكذا لن تسافري إلى أهلك وقد فعلت ذلك الأمر، يقول: ولنسيان الحلف بالحرام فقد سافرنا إلى أهلها، وقد تكرر ذلك الأمر منها مرتين، وتكرر أيضًا مني الحلف بالحرام، أرجو من فضيلتكم التوجيه؟","title":"حكم من حلف بالحرام ألا تفعل زوجته شيئًا ففعلته ناسية","answer":"الجواب:  إذا كان السفر عن نسيان فلا شيء، يقول الرب جل وعلا: رَبَّنَا لا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا [البقرة:286]، وثبت عن رسول الله: إن الله جل وعلا قد فعل، فالناسي لا شيء عليه، إذا قلت: علي الحرام لا تسافرين في يوم كذا وسافرت نسيانًا فلا شيء.  أما إن كانت عمدًا وأنت تقصد منعها ألا تسافر، قلت: علي الحرام، مقصودك منعها، لم تقصد تحريمها إنما قصدت المنع والتخويف فهذا فيه كفارة اليمين إطعام عشرة مساكين، أو كسوتهم، أو عتق رقبة، فمن عجز صام ثلاثة أيام، إذا كان المقصود التخويف والمنع والتحذير. أما إذا كان المقصود تحريمها عليك إذا سافرت فعندها يجب عليك كفارة الظهار وهي: عتق رقبة، فإن عجزت تصوم شهرين متتابعين ستين يومًا، فإن عجزت تطعم ستين مسكينًا ثلاثين صاعًا تسعين كيلو، كل فقير له نصف الصاع كيلو ونصف. أما إذا كان المقصود التحذير والتخويف، قلت: علي الحرام لا تسافرين، وقصدك التخويف والتحذير فهذا كفارة يمين، إذا فعلت المحلوف عليه عامدة، أما إن كانت ناسية فلا شيء عليك. نعم.","link":"https://binbaz.org.sa/fatwas/9392/حكم-من-حلف-بالحرام-الا-تفعل-زوجته-شيىا-ففعلته-ناسية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_291/29111.mp3","categories":["الظهار","الطلاق","الأيمان والنذور"]},{"id":11219,"question":"أخيرًا نعرض سؤالًا لأحد الإخوة المستمعين يقول: أخوكم في الله سيد أحمد عبدالعال حسن من جمهورية مصر العربية، يسأل سماحتكم فيقول: هل يجوز الحلف في المعاريض (التورية) أم لا؟ وهل من دليل جزاكم الله خيرًا؟","title":"حكم الحلف بالمعاريض","answer":"الجواب:  الحلف إذا كان صادقًا لا بأس إذا احتاج إلى ذلك، النبي ﷺ حلف أيمانًا كثيرة وهو صادق عليه الصلاة والسلام، فإذا حلف للتأكيد وتطمين الشخص وهو صادق فلا بأس. أما المعاريض التي يعرض بها حتى لا يقع في الكذب، فإذا نوى شيئًا وحلف عليه فلا بأس، إذا نوى شيئًا قال: والله إن فلانًا ما هو بحاضر الآن، قصده في البيت المعين الفلاني، ولا يستطيع يبين حاله، وهو ناوٍ في البيت معين وهو صادق فلا بأس بالمعاريض، أو والله إن فلانًا لم يفعل كذا وكذا، والمراد ما فعله في وقت كذا أو في وقت كذا، عند الضرورة إلى هذا الشيء، يعني: وقتًا معينًا ما فعله فيه، إذا كان في ذلك مصالح ودرء شر. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9413/حكم-الحلف-بالمعاريض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_373/37312.mp3","categories":["الأيمان والنذور"]},{"id":11224,"question":"أخيرًا نعرض سؤالًا لأحد الإخوة المستمعين يقول: أخوكم في الله سيد أحمد عبدالعال حسن من جمهورية مصر العربية، يسأل سماحتكم فيقول: هل يجوز الحلف في المعاريض (التورية) أم لا؟ وهل من دليل جزاكم الله خيرًا؟","title":"حكم الحلف بالمعاريض","answer":"الجواب:  الحلف إذا كان صادقًا لا بأس إذا احتاج إلى ذلك، النبي ﷺ حلف أيمانًا كثيرة وهو صادق عليه الصلاة والسلام، فإذا حلف للتأكيد وتطمين الشخص وهو صادق فلا بأس. أما المعاريض التي يعرض بها حتى لا يقع في الكذب، فإذا نوى شيئًا وحلف عليه فلا بأس، إذا نوى شيئًا قال: والله إن فلانًا ما هو بحاضر الآن، قصده في البيت المعين الفلاني، ولا يستطيع يبين حاله، وهو ناوٍ في البيت معين وهو صادق فلا بأس بالمعاريض، أو والله إن فلانًا لم يفعل كذا وكذا، والمراد ما فعله في وقت كذا أو في وقت كذا، عند الضرورة إلى هذا الشيء، يعني: وقتًا معينًا ما فعله فيه، إذا كان في ذلك مصالح ودرء شر. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9413/حكم-الحلف-بالمعاريض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_373/37312.mp3","categories":["الأيمان والنذور"]},{"id":11313,"question":"يقول: سبق وأن حلفت بالله بأن زوجتي لا تذهب إلى حفل زواج، وبعد ذلك سمحت لها بالذهاب، فهل علي كفارة وما هي الكفارة؟الشيخ: أعد.المقدم: يقول: حلفت على زوجتي ألا تذهب إلى حفل زواج، وبعد ذلك سمحت لها بالذهاب، فهل علي كفارة وما هي الكفارة؟","title":"حكم من حلف مانعاً زوجته من حضور عرس ثم أذن لها","answer":"الجواب: إذا كنت أردت إلا بإذنك فليس عليك شيء، أما إذا كنت حلفت ألا تذهب، ولم تنو إلا بإذنك فإنها متى ذهبت عليك الكفارة -كفارة اليمين-، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9493/حكم-من-حلف-مانعا-زوجته-من-حضور-عرس-ثم-اذن-لها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_377/37704.mp3","categories":["الأيمان والنذور"]},{"id":11342,"question":"نعود مع مطلع هذه الحلقة إلى رسالة وصلت إلى البرنامج من المستمع (أ. م) يسأل ويقول: إذا نذر الإنسان وأراد أن يطعم عشرة مساكين، وهناك أسرة تتكون من عشرة أفراد ووالدهم، هل يجزئ أن يوزع تلك الصدقة عليهم؟ جزاكم الله خيرًا.","title":"حكم إعطاء كفارة اليمين أسرة مكونة من عشرة أفراد","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فلا حرج أن يعطي البيت الواحد كفارة اليمين، أو كفارة النذر إذا كانوا عشرة أو أكثر يعطيها القائم على البيت الفقير والدهم أو أمهم، المقصود يعطيها القائم على هؤلاء، سواء كان أبًا أو أمًا أو أخًا أو نحو ذلك إذا كانوا عشرة فأكثر، وإن كانوا أقل أعطاهم وكمل في غيرهم. والنذر فيه تفصيل، إن كان النذر عبادة كأن يقول: لله علي أن أصوم كذا أو أصلي كذا هذا ما فيه كفارة، يصلي أو يصوم، إذا قال: لله علي أن أصوم ثلاثة أيام أو لله علي أن أصلي ركعتين يلزمه أن يفعل، لقوله ﷺ: من نذر أن يطيع الله فليطعه، ومن نذر أن يعصي الله فلا يعصه، أما إذا كان النذر ليس عبادة مثل قال: نذر لله ... أنه يضرب فلانًا أو يسب فلانًا، هذا لا يسبه ولا يضربه، يكفر كفارة يمين إطعام عشرة مساكين، أو قال: نذر لله علي أني أزور فلانًا أو آكل طعام فلان ما هو بلازم إذا كفر كفارة يمين كفى عن الزيارة وعن أكل الطعام، أو قال: نذر لله علي أن أسافر اليوم .... إذا ما سافر عليه كفارة يمين، نذر المباحات. نعم. المقدم: بارك الله فيكم. الشيخ: أو نذر مكروه، قال: لله علي ألا أصلي الراتبة -راتبة الظهر- أو لا أصلي راتبة الفجر، هذا نذر مكروه، صل الراتبة وكفر عنه كفارة يمين، أو نذر معصية قال: لله علي أني أسرق أو أزني يكفر كفارة يمين ولا يفعل. المقدم: بارك الله فيكم وجزاكم الله خيرًا، إذًا إذا نذر أن يعطي عشرة مساكين فوجد أسرة عددها عشرة أشخاص. الشيخ: كفى. المقدم: كفى. الشيخ: كفى الفقراء، نعم. المقدم: بارك الله فيكم، وجزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9524/حكم-اعطاء-كفارة-اليمين-اسرة-مكونة-من-عشرة-افراد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_378/37801.mp3","categories":["الأيمان والنذور"]},{"id":11358,"question":"نعود مع مطلع هذه الحلقة إلى رسالة وصلت إلى البرنامج من المستمع (أ. م) يسأل ويقول: إذا نذر الإنسان وأراد أن يطعم عشرة مساكين، وهناك أسرة تتكون من عشرة أفراد ووالدهم، هل يجزئ أن يوزع تلك الصدقة عليهم؟ جزاكم الله خيرًا.","title":"حكم إعطاء كفارة اليمين أسرة مكونة من عشرة أفراد","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فلا حرج أن يعطي البيت الواحد كفارة اليمين، أو كفارة النذر إذا كانوا عشرة أو أكثر يعطيها القائم على البيت الفقير والدهم أو أمهم، المقصود يعطيها القائم على هؤلاء، سواء كان أبًا أو أمًا أو أخًا أو نحو ذلك إذا كانوا عشرة فأكثر، وإن كانوا أقل أعطاهم وكمل في غيرهم. والنذر فيه تفصيل، إن كان النذر عبادة كأن يقول: لله علي أن أصوم كذا أو أصلي كذا هذا ما فيه كفارة، يصلي أو يصوم، إذا قال: لله علي أن أصوم ثلاثة أيام أو لله علي أن أصلي ركعتين يلزمه أن يفعل، لقوله ﷺ: من نذر أن يطيع الله فليطعه، ومن نذر أن يعصي الله فلا يعصه، أما إذا كان النذر ليس عبادة مثل قال: نذر لله ... أنه يضرب فلانًا أو يسب فلانًا، هذا لا يسبه ولا يضربه، يكفر كفارة يمين إطعام عشرة مساكين، أو قال: نذر لله علي أني أزور فلانًا أو آكل طعام فلان ما هو بلازم إذا كفر كفارة يمين كفى عن الزيارة وعن أكل الطعام، أو قال: نذر لله علي أن أسافر اليوم .... إذا ما سافر عليه كفارة يمين، نذر المباحات. نعم. المقدم: بارك الله فيكم. الشيخ: أو نذر مكروه، قال: لله علي ألا أصلي الراتبة -راتبة الظهر- أو لا أصلي راتبة الفجر، هذا نذر مكروه، صل الراتبة وكفر عنه كفارة يمين، أو نذر معصية قال: لله علي أني أسرق أو أزني يكفر كفارة يمين ولا يفعل. المقدم: بارك الله فيكم وجزاكم الله خيرًا، إذًا إذا نذر أن يعطي عشرة مساكين فوجد أسرة عددها عشرة أشخاص. الشيخ: كفى. المقدم: كفى. الشيخ: كفى الفقراء، نعم. المقدم: بارك الله فيكم، وجزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9524/حكم-اعطاء-كفارة-اليمين-اسرة-مكونة-من-عشرة-افراد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_378/37801.mp3","categories":["الأيمان والنذور"]},{"id":11359,"question":"نعود مع مطلع هذه الحلقة إلى رسالة وصلت إلى البرنامج من المستمع (أ. م) يسأل ويقول: إذا نذر الإنسان وأراد أن يطعم عشرة مساكين، وهناك أسرة تتكون من عشرة أفراد ووالدهم، هل يجزئ أن يوزع تلك الصدقة عليهم؟ جزاكم الله خيرًا.","title":"حكم إعطاء كفارة اليمين أسرة مكونة من عشرة أفراد","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فلا حرج أن يعطي البيت الواحد كفارة اليمين، أو كفارة النذر إذا كانوا عشرة أو أكثر يعطيها القائم على البيت الفقير والدهم أو أمهم، المقصود يعطيها القائم على هؤلاء، سواء كان أبًا أو أمًا أو أخًا أو نحو ذلك إذا كانوا عشرة فأكثر، وإن كانوا أقل أعطاهم وكمل في غيرهم. والنذر فيه تفصيل، إن كان النذر عبادة كأن يقول: لله علي أن أصوم كذا أو أصلي كذا هذا ما فيه كفارة، يصلي أو يصوم، إذا قال: لله علي أن أصوم ثلاثة أيام أو لله علي أن أصلي ركعتين يلزمه أن يفعل، لقوله ﷺ: من نذر أن يطيع الله فليطعه، ومن نذر أن يعصي الله فلا يعصه، أما إذا كان النذر ليس عبادة مثل قال: نذر لله ... أنه يضرب فلانًا أو يسب فلانًا، هذا لا يسبه ولا يضربه، يكفر كفارة يمين إطعام عشرة مساكين، أو قال: نذر لله علي أني أزور فلانًا أو آكل طعام فلان ما هو بلازم إذا كفر كفارة يمين كفى عن الزيارة وعن أكل الطعام، أو قال: نذر لله علي أن أسافر اليوم .... إذا ما سافر عليه كفارة يمين، نذر المباحات. نعم. المقدم: بارك الله فيكم. الشيخ: أو نذر مكروه، قال: لله علي ألا أصلي الراتبة -راتبة الظهر- أو لا أصلي راتبة الفجر، هذا نذر مكروه، صل الراتبة وكفر عنه كفارة يمين، أو نذر معصية قال: لله علي أني أسرق أو أزني يكفر كفارة يمين ولا يفعل. المقدم: بارك الله فيكم وجزاكم الله خيرًا، إذًا إذا نذر أن يعطي عشرة مساكين فوجد أسرة عددها عشرة أشخاص. الشيخ: كفى. المقدم: كفى. الشيخ: كفى الفقراء، نعم. المقدم: بارك الله فيكم، وجزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9524/حكم-اعطاء-كفارة-اليمين-اسرة-مكونة-من-عشرة-افراد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_378/37801.mp3","categories":["الأيمان والنذور"]},{"id":11502,"question":"يقول أخونا: نذرت إن شفاني الله من مرض أن أقوم بالذبح لله، والحمد لله شفيت، لكنني لم أستطع الوفاء بالنذر، فماذا علي؟","title":"حكم من نذر نذراً وعجز عن الوفاء به","answer":"الجواب:  ... يبقى دين في الذمة حتى يتيسر الأمر، يبقى دين في الذمة إذا تيسر؛ تذبح لله ما نذرت، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9674/حكم-من-نذر-نذرا-وعجز-عن-الوفاء-به","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_383/38307.mp3","categories":["الأيمان والنذور"]},{"id":11564,"question":"لها سؤال آخر مطول بعض الشيء، تسأل فيه وتقول: إنها حلفت إذا رزقت بنتًا أن تسميها هدى، فلما أنجبت البنت، وأرادت تسميتها؛ رفض والد الزوج، فماذا عليها؟","title":"حكم اليمين على فعل شيء لم يفعل","answer":"الجواب:  المشروع أن يتفقوا على الاسم الذي .... ولا تخالف، فإذا لم يرض زوجها، أو والده؛ تكفر عن يمينها، والحمد لله، ويسمون اسمًا يرضونه جميعًا، وعليها كفارة اليمين، إطعام عشرة مساكين، أو كسوتهم، أو عتق رقبة، فإن عجزت لأنها فقيرة؛ تصم ثلاثة أيام والحمد لله، ولا تعصيهم في الاسم الذي يريدون، والد زوجها له حق، فإذا اتفقت معهم على اسم غير هدى؛ تكفر عن يمينها، والحمد لله. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9747/حكم-اليمين-على-فعل-شيء-لم-يفعل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_297/29713.mp3","categories":["الأيمان والنذور"]},{"id":11576,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من إحدى الأخوات رمزت إلى اسمها بالحروف (س. ع) تقول: امرأة قالت لأخرى بعد زعل بينهما: حرام علي ألا أتصل بتلفونك بعد اليوم، ثم إنها اعتذرت لها واتصلت بتلفونها، فماذا عليها؟ جزاكم الله خيرًا.","title":"حكم من حرم شيئًا على نفسه ثم رجع إليه","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد.  فليس للمسلم أن يحرم ما أحل الله له، قال الله -جل وعلا-: يَا أَيُّهَا النَّبِيُّ لِمَ تُحَرِّمُ مَا أَحَلَّ اللَّهُ لَكَ [التحريم:1] الآية، فالمسلم ليس له أن يحرم ما أحل الله له، ولكن متى وقع ذلك مثل ما قالت هذه المرأة: أنها حرام عليها أن تكلمها بالتلفون متى كلمتها فعليها كفارة اليمين، حكمه حكم اليمين، ولهذا قال الله سبحانه بعدما أنكر على نبيه ﷺ تحريم ما أحل الله، قال: قَدْ فَرَضَ اللَّهُ لَكُمْ تَحِلَّةَ أَيْمَانِكُمْْ [التحريم:2] فدل على أن هذا حكمه حكم اليمين، فإذا قال: حرام عليه أن يكلم فلانًا؛ حرام عليه أن يزور فلانًا، حرام عليه أن يأكل طعام فلان. أو قالت المرأة كذلك: حرام علي أن أكلم فلانة، أو فلانًا، أو أزور فلانة، أو فلانًا، فيه كفارة اليمين، وهي إطعام عشرة مساكين أو كسوتهم، أو عتق رقبة، فمن عجز عن هذا كله؛ فعليه كفارة اليمين، كما أوضح الله ذلك في كتابه العظيم في سورة المائدة، والإطعام نصف صاع لكل واحد، كيلو ونصف لكل واحد من تمر، أو غيره من قوت البلد، كالأرز والحنطة ونحو ذلك، أو يكسوهم على قميص قميص، أو إزار ورداء، أو يعتق رقبة عبد، أو أمة، فمن عجز عن هذا الشيء يصوم ثلاثة أيام، والحمد لله. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9759/حكم-من-حرم-شيىا-على-نفسه-ثم-رجع-اليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_298/29801.mp3","categories":["الأيمان والنذور"]},{"id":11617,"question":"ما حكم من يحلف بالقرآن ويقول، من لم يحلف به؛ فهو كافر؟ أرجو إعطائي دليلًا من الكتاب أو السنة إن وجد، جزاكم الله خيرًا.","title":"ما حكم من يحلف بالقرآن؟","answer":"الجواب:  هذا كلام جاهل، الحلف بالقرآن إذا أراد كلام الله لا بأس، بس ما هو بلازم يحلف الناس بالقرآن، ما هو بلزوم، يحلفون بأسماء الله: والله، والرحمن، والرحيم، والعزيز، ليس من اللازم أن يحلف بالقرآن، لكن يجوز الحلف بالقرآن إذا أراد كلام الله  أما إذا ترك ذلك؛ فلا بأس عليه، لا معصية، ولا كفر أعوذ بالله؛ لأنه يمكن أن يحلف بغير القرآن، يحلف بالله، أو بالعزيز، أو بالحكيم، أو بالقدير، وكلام الله صفة من صفاته، فيجوز الحلف به كما يقول: وعلم الله، وعزة الله، لا بأس، لكن لا يلزم الحلف بالقرآن إذا حلف بغيره من أسماء الله وصفاته فلا بأس، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9808/ما-حكم-من-يحلف-بالقران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_388/38819.mp3","categories":["الأيمان والنذور"]},{"id":11625,"question":"رسالة بتوقيع أحد الإخوة يسأل ويقول: ما حكم المرأة التي رفعت كتاب الله، وحلفت به مرتين قائلة لزوجها أنا محرمة عليك في العيشة والأكل، أو بعبارة أخرى، قالت له: وهذا المصحف، وهذا المصحف أنا محرمة عليك في النوم أي: لا أنام معك، وفي الأكل لا آكل معك والمعيشة، هل تملك الطلاق؟ أم أن الطلاق بيد الزوج؟ جزاكم الله خيرًا.","title":"حكم تحريم المرأة نفسها على زوجها وحلفها على ذلك","answer":"الجواب: الطلاق بيد الزوج بإجماع المسلمين، وأما تحريمها نومها معه، وأكلها معه هذا لا يجوز لها، وعليها التوبة إلى الله من ذلك، ولو حلفت بالقرآن، ولو قالت: بالله، أو وبالله، أو والله العظيم، كل ذلك لا يجوز لها، وعليها أن تكفر عن يمينها، وعن تحريمها كفارة يمين، ولا يحرم عليها زوجها، ولا تحرم عليه، ولكن عليها كفارة اليمين، لقول الله -جل وعلا-: يَا أَيُّهَا النَّبِيُّ لِمَ تُحَرِّمُ مَا أَحَلَّ اللَّهُ لَكَ تَبْتَغِي مَرْضَاةَ أَزْوَاجِكَ وَاللَّهُ غَفُورٌ رَحِيمٌ ۝ قَدْ فَرَضَ اللَّهُ لَكُمْ تَحِلَّةَ أَيْمَانِكُمْ [التحريم:2] فتحريمها حكمه حكم اليمين، فعليها أن تكفر عن ذلك. والنبي ﷺ لما حرم الجارية وفي رواية: حرم العسل أمره الله بكفارة اليمين، فعليها كفارة يمين، ولا تملك الطلاق، ولا تملك الظهار.. الظهار للزوج خاصة، والطلاق للزوج خاصة، أما تحريمها للزوج هي مثل تحريمها للطعام، أو الشراب؛ عليها كفارة اليمين، وهي حل لزوجها، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9800/حكم-تحريم-المراة-نفسها-على-زوجها-وحلفها-على-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_388/38811.mp3","categories":["الأيمان والنذور"]},{"id":11731,"question":"أختنا تقول: كنت قد عاهدت الله عهودًا كثيرة، وقلت على كل عهد يمين: إن حصل لي كذا فسأفعل كذا حيث أني مصابة بمرض نفسي، والحمد لله، فقد كنت أشفى تارة، ويعاودني المرض تارة أخرى، وأنا عاهدت الله إن شافاني الله مدة ذلك المرض نهائيًا فأنا سأنفذ تلك العهود، ولكني أحسست بداخلي أنني في المستقبل لا أستطيع الوفاء بها، فاستغفرت الله، وتبت إليه، فهل يعتبر ذلك من نقض العهد؟","title":"حكم من نذر إن شفاه الله ويخشى ألا يفي به","answer":"الجواب:  المسلم إذا نذر نذورًا كلها طاعة، وجب عليه الوفاء حسب طاقته صومًا، أو صلاة، أو صدقة إلا أن يكون ما نذره مكروهًا كصوم الدهر، هذا يكفيه كفارة اليمين إذا كان النذر مكروهًا، أو يصلي بعد العصر، أو يصلي بعد صلاة الفجر؛ لأنها ليس محلًا للصلاة، يكفي فيه كفارة اليمين، أما إذا نذر، وعاهد عهود طاعة، ووجد شرطه؛ فإنه يلزمه أن يوفي، لقول النبي ﷺ: من نذر أن يطيع الله فليطعه ولقوله سبحانه: يُوفُونَ بِالنَّذْرِ [الإنسان:7]، ولأن المنافق هو الذي لا يوفي، المنافق إذا عاهد غدر، وإذا نذر لم يوف، وإذا حدث كذب، وإذا وعد أخلف، فلا ينبغي للمؤمن أن يتشبه بأعداء الله المنافقين. فالواجب عليك الوفاء بما نذرت، وعاهدت إلا عند العجز، إذا عجزت؛ فاتقوا الله ما استطعتم، يقول الله -جل وعلا-: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185]، ويقول سبحانه: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، فإذا كنت نذرت مثلًا صوم يوم الإثنين والخميس تصومين، وإذا أصابك مرض أفطرت وقضيت. وهكذا إذا نذرت الصدقة، إذا شفاك الله من المرض، وعاهدت الله أن تتصدقي بمائة ريال بألف ريال بأكثر؛ فافعلي، فإذا عجزت؛ يبقى دينًا في الذمة فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] حتى تستطيعي، ثم توفي، أما إذا كان الشفاء ما تم الشرط، ما تم، قلت: إن شافاني الله؛ ولكن ما تم الشفاء فليس عليك شيء حتى يتم الشفاء، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9914/حكم-من-نذر-ان-شفاه-الله-ويخشى-الا-يفي-به","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_421/42112.mp3","categories":["الأيمان والنذور"]},{"id":11732,"question":"أيضًا تقول سماحة الشيخ: علي أيمان كثيرة، ولكني لا أستطيع الوفاء بها، إما لعدم وجود المساكين والفقراء، أو لعدم من يساعدني في ذلك، مع أني أملك المال الكافي، لكني لا أستطيع القيام بذلك، وليس هناك أحد يساعدني في ذلك، أرجو إفادتي جزاكم الله خيرًا.","title":"حكم من لم يتمكن من كفارة اليمين لعدم وجود مساكين","answer":"الجواب:  عليك الوفاء بما حلفت كفارة الأيمان، إذا حلفت أيمانًا، ونقضتيها؛ فعليك الكفارة، فإذا قلت: والله! ما أزور آل فلان يمينًا مقصودة، والله ما أكلم فلانًا، والله ما ألبس هذا الشيء، اليمين المقصودة عليك الكفارة والفقراء موجودون، وإذا كنت عاجزة ما عندك مال؛ تصومين ثلاثة أيام؛ لأن الله -جل وعلا- قال في كتابه العظيم: لا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِنْ يُؤَاخِذُكُمْ بِمَا عَقَّدْتُمُ الأَيْمَانَ فَكَفَّارَتُهُ إِطْعَامُ عَشَرَةِ مَسَاكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍ فَمَنْ لَمْ يَجِدْ فَصِيَامُ ثَلاثَةِ أَيَّامٍ [المائدة:89]، ثم قال سبحانه: ذَلِكَ كَفَّارَةُ أَيْمَانِكُمْ إِذَا حَلَفْتُمْ وَاحْفَظُوا أَيْمَانَكُمْ [المائدة:89]. فالواجب على الرجل والمرأة المسلم حفظ اليمين، والحذر من التساهل، فإذا حلف على شيء أنه لا يفعله، ثم فعله؛ عليه كفارة يمين، أو حلف أنه يفعل هذا الشيء ولم يفعل، حلف أنه يصوم يوم الإثنين، حلف أنه يزور فلانًا يوم كذا، حلف أنه يأكل من طعامه، فلم يفعل؛ عليه كفارة يمين، فإذا عجز لفقره؛ صام ثلاثة أيام، والذي ينبغي أن تكون متتابعة؛ لأن جماعة من أهل العلم ذكروا ذلك شرطًا، وقرأ بعض الصحابة: (فصيام ثلاثة أيام متتابعة). فالمقصود: أن الأحوط أن يصومها متتابعة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9918/حكم-من-لم-يتمكن-من-كفارة-اليمين-لعدم-وجود-مساكين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_421/42113.mp3","categories":["الأيمان والنذور"]},{"id":11780,"question":"حلفت بالله العظيم ثلاث مرات على أن أفعل شيئًا إذا لم يحصل ما أريد، وأنا في يقين نفسي مترددة في ذلك، ومتأكدة أنه لن يحصل هذا الذي أريده، ومتأكدة أنني لن أنفذ الذي وعدت به، وإنني الآن نادمة جدًا، فهل علي إثم؟ جزاكم الله خيرًا.","title":"حكم من حلف على فعل شيء ثلاث مرات ثم حنث","answer":"الجواب:  إذا حلف الإنسان على شيء يفعله، أو لا يفعله ثلاث مرات، أو أربعًا، أو عشرًا، أو أكثر، فإنه إذا حنث؛ يكون كفارة واحدة، الكفارة تكون واحدة، إذا كان المحلوف عليه شيئًا واحدًا، كأن يقول: والله لا أكلم فلانًا، والله لا أكلم فلانًا، والله لا أكلم فلانًا، أو والله لا أزور فلانًا، أو والله لا أزور فلانًا، أو والله لا أزور فلانًا، ثم زاره، أو كلمه؛ كفارة واحدة.  أو قال: والله لأتزوجن فلانة، أو والله لأتزوجن فلانة، أو والله لأتزوجن فلانة، ثم لم يتزوج؛ كفارة واحدة، أو والله لأسافرن إلى بلد كذا، والله لأسافرن، والله لأسافرن، ثم رأى عدم السفر، كفارة واحدة. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9966/حكم-من-حلف-على-فعل-شيء-ثلاث-مرات-ثم-حنث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_395/39504.mp3","categories":["الأيمان والنذور"]},{"id":11800,"question":"يقول في سؤال آخر: هناك امرأة في القرية لها بنت مريضة بمرض عضال، وقد ذهبت بها إلى جميع المستشفيات والأطباء، ولم يقسم لها الشفاء حتى الآن، لكن هناك أمل في الله  هذه المرأة نذرت بنذر إذا شفيت هذه البنت؛ فسوف أزوجها فلانًا، هل يلزمها فعلًا أن تفي بهذا النذر، أم أن لها مخرجًا؟ جزاكم الله خيرًا.","title":"حكم من نذرت إن شُفيت ابنتها أن تزوجها شخصاً معيناً","answer":"الجواب:  ليس الأمر في يدها، إذا رضيت البنت بعد شفائها رضيت؛ فلا بأس، وإلا فعليها أن تكفر عن هذا النذر كفارة يمين؛ لأنها نذرت شيئًا لا تملكه، الزواج ليس في يدها، بل في يد البنت، لا تزوج إلا بإذنها، فإن سمحت؛ فالحمد لله، إذا عافاها الله، وإن لم تسمح؛ فإن عليها كفارة اليمين كفارة النذر كفارة اليمين في مثل هذا، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9984/حكم-من-نذرت-ان-شفيت-ابنتها-ان-تزوجها-شخصا-معينا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_423/42302.mp3","categories":["الأيمان والنذور"]},{"id":11855,"question":"نعود إلى سؤال الأخ أحمد شعبان الذي يقول فيه: ما المقصود باللغو الذي لا يحاسب عليه الله  في الأيمان، وما هو تعقيد الأيمان الذي يوجب الكفارة عند وقوعه؟","title":"تعريف يمين اللغو والمعقدة","answer":"الجواب:  يقول الله سبحانه: لا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِنْ يُؤَاخِذُكُمْ بِمَا كَسَبَتْ قُلُوبُكُمْ [البقرة:225]، هذا في سورة البقرة، ويقول في سورة المائدة: لا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِنْ يُؤَاخِذُكُمْ بِمَا عَقَّدْتُمُ الأَيْمَانَ [المائدة:89]، فاللغو: هي اليمين التي لا تقصد، تجري على اللسان من غير قصد، والله لا أفعل كذا، والله ما فعلت كذا، ما قصدها، .. تجري على لسانه عادةً، هذه ليس فيها شيء. أما المقصودة التي يقولها قاصدًا متعمدًا لها مريدًا معناها: والله ما أكلم فلانًا، قاصدًا له، والله ما فعلت كذا، قاصدًا لذلك، هذه الأيمان المعقودة المعقدة، التي يكسبها القلب، يقولها اللسان والقلب كاسبًا لها، مريد لها، عامد لها: والله ما أكلم فلانًا، والله ما أزور فلانًا، والله ما فعلت كذا، قاصدًا لذلك، هذه الأيمان المعقدة، إن كانت كذبًا؛ فهي اليمين الغموس، وليس فيها كفارة، فيها التوبة، وإن كانت على فعل .... مستقبل، والله ما أكلم فلانًا، والله ما أزوره، فإذا أخل بيمينه؛ فعليه كفارة. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10047/تعريف-يمين-اللغو-والمعقدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_397/39710.mp3","categories":["الأيمان والنذور"]},{"id":11856,"question":"إذا نذر شخص ذبح شاة لأمر معين، وتحقق هذا الأمر، فهل يجوز أن ينوي ذبح الشاة لعيد الأضحى، وكذلك النذر، إذا كان لا يملك ذبح شاتين للعيد والنذر؟","title":"حكم الذبح بنية الضحية والنذر","answer":"الجواب:  يذبحه لما نذره، في الوقت الذي نذر، فإن نذر إذا أعطاه الله ولدًا أن يذبح شاة، أو نذر إذا تملك دارًا للسكن أن يذبح شاةً، أو نذر إذا بلغه عن فلان ما يسره أن يذبح شاةً، أو نذر إذا نجح في الاختبار أن يذبح شاةً، فيذبحها في وقتها، ولا يؤجلها إلى العيد.... يذبحها في وقتها، ويتصدق بها على الفقراء والمحاويج، إلا أن تكون له نية، نوى أنه يذبحها لأقاربه وجيرانه، ويأكل معهم؛ فهو على نيته؛ لقول النبي ﷺ: إنما الأعمال بالنيات، وإنما لكل امرئ ما نوى فهو يذبحها على ما نوى، والحمد لله، قربة لله  يرجو بها فضله سبحانه، والأجر عنده. لكن ينبغي أن يعلم أن النذر غير مشروع، فلا ينبغي له أنه ينذر لقول النبي ﷺ: لا تنذروا؛ فإن النذر لا يرد من قدر الله شيئًا، وإنما يستخرج به من البخيل لكن إذا نذر طاعة؛ لزمه الوفاء، لقول النبي ﷺ: من نذر أن يطيع الله؛ فليطعه، ومن نذر أن يعصي الله؛ فلا يعصه فإذا نذر طاعة؛ وجب عليه الوفاء، مثلما تقدم: لله عليه أن يصلي ركعتين يوم كذا، يوم الخميس، لله عليه أن يوتر بإحدى عشرة ليلة كذا عليه أن يوفي به، لله عليه أن يذبح شاة إذا رزقه الله مولودًا، أو رزقه الله سكنًا، أو بلغه سلامة فلان من المرض، يوفي بنذره. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10042/حكم-الذبح-بنية-الضحية-والنذر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_397/39705.mp3","categories":["الأيمان والنذور"]},{"id":11859,"question":"هل صيام الكفارة لليمين يكون متتابعًا، أو لا مانع أن يكون متقطعًا؟","title":"حكم التتابع في صيام كفارة اليمين","answer":"الجواب:  الأفضل التتابع، وإن لم يتتابع؛ أجزأ؛ لأن الله  لم يشترط التتابع، قال: فَمَنْ لَمْ يَجِدْ فَصِيَامُ ثَلاثَةِ أَيَّامٍ [المائدة:89] ولم يقل: (متتابعة)، لكن بعض السلف قرأها.... ابن مسعود  كان يقرأ متتابعة، ويرى التتابع، فالأفضل التتابع، ولكن لو صامها غير متتابعة؛ أجزأت، والحمد لله على الراجح. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10048/حكم-التتابع-في-صيام-كفارة-اليمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_397/39711.mp3","categories":["الأيمان والنذور"]},{"id":11864,"question":"تسأل أختنا وتقول: إذا نذرت أن أشتري لإنسان هدية معينة عندما يتحقق لي شيء معين، ومات هذا الشخص، فماذا أفعل؟ هل أتصدق بالمبلغ؟ أم ماذا؟ جزاكم الله خيرًا.","title":"حكم من نذر شراء هدية لشخص ثم مات المنذور له","answer":"الجواب:  إذا مات المنذور له بطل النذر، ولم يكن على الناذر شيء؛ لأن المقصود هو إعطاؤه، والميت لا يعطى؛ زال حكم تملكه للعطية، فبطل النذر حينئذٍ، وليس على الناذر شيء، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10039/حكم-من-نذر-شراء-هدية-لشخص-ثم-مات-المنذور-له","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_397/39702.mp3","categories":["الأيمان والنذور"]},{"id":11951,"question":"يقول: إنني ألاحظ أن كثيرًا من الناس يكثر الحلف عندما يتحدث، فبم تنصحون الناس؟ جزاكم الله خيرًا.","title":"حكم الإكثار من الحلف عند التحدث مع الناس","answer":"الجواب:  نوصي إخواننا جميعًا من الرجال والنساء بالحذر من كثرة الحلف، ونوصيهم بالتقليل من الحلف، لأن الله يقول سبحانه: وَاحْفَظُوا أَيْمَانَكُمْ [المائدة:89]، ويقول النبي ﷺ: ثلاثة لا يكلمهم الله، ولا ينظر إليهم يوم القيامة، ولا يزكيهم، ولهم عذاب أليم ذكر منهم: رجل جعل الله بضاعته، لا يبيع إلا بيمينه، ولا يشتري إلا بيمينه. فالمقصود: الوصية بترك كثرة الحلف، وألا يحلف إلا عند الحاجة لليمين؛ لأن كثرة الحلف وسيلة للكذب، ووسيلة لعدم الكفارة في أيمانه التي يحنث فيها، فنوصي الجميع رجالًا ونساءً بالتقليل من الأيمان، وألا يحلف إلا عند الحاجة. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10136/حكم-الاكثار-من-الحلف-عند-التحدث-مع-الناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_428/42815.mp3","categories":["الأيمان والنذور"]},{"id":12026,"question":"من بيشة أحد الإخوة المستمعين يقول: معروف رمضان عرفات يقول: قبل وفاة زوجتي كنت حلفت أنا وهي إذا مات أحدنا قبل الآخر لا يتزوج بعده، والآن قدر الله وتوفيت زوجتي، فهل لي أن أتزوج؟ علمًا بأن الأسرة مجمعون على الزواج، جزاكم الله خيرًا.","title":"حكم من حلف لزوجته أن لا يتزوج بعد وفاتها","answer":"الجواب:  نعم نعم المشروع لك الزواج، بل يجب عليك إذا كنت تحتاج إلى ذلك، ولا يجوز لك تركه إذا كان قد يفضي بك إلى الخطر. المقصود: أن الواجب عليك الزواج، وعليك كفارة اليمين، عليك كفارة اليمين عن يمينك لزوجتك، وهي إطعام عشرة مساكين، أو كسوتهم، عشرة كل واحد له نصف الصاع من قوت البلد، من تمر، أو حنطة، أو أرز، أو شعير، أو نحو ذلك، وليس لك أن تدع الزواج وأنت تقدر عليه، نعم. المقدم: جزاكم الله خيرًا، يمينه يكفر عنها سماحة الشيخ؟ الشيخ: كفارة يمين، نعم. المقدم: يلزمه كفارة يمين؟ الشيخ: يلزمه كفارة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم. الشيخ: وهي كذلك لو مات قبلها؛ كفرت عن يمينها ..... المقدم: وتزوجت. الشيخ: نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10211/حكم-من-حلف-لزوجته-ان-لا-يتزوج-بعد-وفاتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_432/43217.mp3","categories":["الأيمان والنذور"]},{"id":12081,"question":"المستمع محمد حسن عصيدة بعث برسالة، و ضمنها جمعًا من الأسئلة، من بينها سؤال يقول: إن زوج أختي قد أهدى زوجتي مبلغًا من المال كيما يكون عونًا لها على حياتها، لكنه أخبر زوجته، ثم إن زوجته نشرت الخبر، فتضايقت زوجتي من هذا التصرف، وحرمته، هل يجب علينا حينئذٍ أن نعيد ذلك المال، أم كيف نتصرف؟ جزاكم الله خيرًا.","title":"كيفية التخلص من المال إذا حرمه الإنسان على نفسه","answer":"الجواب:  إن أعادته فعليها كفارة اليمين عن تحريمها، وإن لم تعده؛ فلا بأس؛ سدًا لباب التهمة، سدًا لباب التهمة بهذه الهدية، وإن أعادته لأنها لا تهمة في ذلك؛ فعليها كفارة اليمين عن تحريمها، وهي إطعام عشرة مساكين، أو كسوتهم عشرة، كل واحد له نصف الصاع، تمر، أو رز، يعني: كيلو ونصف، أو كسوة قميص، أو إزار ورداء؛ تجزئ في الصلاة عن تحريمها؛ لأن هذا التحريم بمعنى اليمين، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10266/كيفية-التخلص-من-المال-اذا-حرمه-الانسان-على-نفسه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_435/43514.mp3","categories":["الأيمان والنذور"]},{"id":12099,"question":"إذا حلف إنسان، أو نذر، ثم أعقب قوله ذلك بكلمة: إن شاء الله، ولم يفعل ما نذر، أو حلف من أجله، فهل عليه كفارة؟","title":"حكم من قال في نذره أو قسمه: إن شاء الله","answer":"الجواب:  الصواب لا كفارة عليه، إذا قال: والله لأفعلن كذا -إن شاء الله- أو نذر لله علي لأفعلن كذا -إن شاء الله- فلا شيء عليه؛ لأن هذه المشيئة تجعل له فرجًا ومخرجًا، وفي الحديث الصحيح يقول ﷺ: من قال في يمينه: إن شاء الله؛ فلا حنث عليه نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10284/حكم-من-قال-في-نذره-او-قسمه-ان-شاء-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_437/43702.mp3","categories":["الأيمان والنذور"]},{"id":12105,"question":"رسالة مطولة بتوقيع إحدى الأخوات المستمعات تقول المرسلة (ح. س. د) أختنا لها مشكلة في كتابة مطولة، ملخص هذه القضية أنها ابتليت بزوج سكير، وقد اكتشفت أنه كذلك بعد سنتين من الزواج، لكنه غير مدمن كما تصفه، بل يشربه بين فترة وأخرى، وحينئذٍ أنكرت عليه؛ فحلف لها بالطلاق ثلاث مرات أنه لا يسكر، لكنه عاد، ما هو توجيهكم؟","title":"حكم من حلف بالطلاق ألا يشرب الخمر ثم عاد","answer":"الجواب:  الواجب نصيحته، وتحذيره من مغبة هذا العمل السيئ، فإن الخمر من أقبح السيئات، ومن أقبح الكبائر، فالواجب على هذا الرجل أن يتقي الله، وأن يدع هذا الشراب الخبيث، والرسول ﷺ: لعن الخمر وشاربها وساقيها وحاملها والمحمولة إليه وعاصرها ومعتصرها وبائعها ومشتريها وآكل ثمنها وقال ﷺ: لا يشرب الخمر حين يشربها وهو مؤمن وهذا من باب الوعيد الشديد؛ لأنها تنافي كمال الإيمان الواجب، فالواجب عليه أن يتقي الله، وأن يتوب إلى الله، وعليك أن تنصحيه، وتحذريه من شؤمها. وأما طلاقه ألا يشرب؛ فهذا فيه تفصيل: إن كان طلق ألا يشرب وقصده الامتناع، وليس قصده وقوع الطلاق، ولكن قصده أن يمتنع منه، وأن يشدد على نفسه، وليس قصده إيقاع الطلاق، فعليه كفارة يمين، ولا يقع، أما إن كان قصده إيقاع الطلاق؛ فإنه يقع الطلاق، نسأل الله لنا وله الهداية. المقدم: جزاكم الله خيرًا، وأحسن إليكم، إذًا هل تنصحونه بالبقاء معه، أم تتصرف تصرفًا آخر سماحة الشيخ؟ الشيخ: نوصيها بالبقاء معه والنصيحة، فإذا لم يقبل النصيحة نوصيها بالفراق، ولو بإعطائه ماله، نعم. إذا لم يطلقها بدون مال، أو ترفع أمرها للمحكمة، نعم. المقدم: جزاكم الله خيرًا. وتلك الأيمان بالطلاق ثلاث مرات على ألا يعود ثم يعود؟ \nالشيخ: أخبرناها أن هذا فيه التفصيل: إن كان أراد الامتناع، ولم يرد إيقاع الطلاق؛ فإن عليه كفارة يمين عن كل واحدة، أما إن كان أراد الامتناع مع إيقاع الطلاق إن شرب؛ فإنه يقع الطلاق، وإذا تكرر ثلاثًا؛ حرمت عليه، نعم. حتى تنكح زوجًا غيره، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10290/حكم-من-حلف-بالطلاق-الا-يشرب-الخمر-ثم-عاد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_437/43708.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة"]},{"id":12106,"question":"من المدينة المنورة رسالة بعث بها مستمع من هناك يقول: أبو مها، أبو مها يسأل سماحتكم عن الأيمان التي توجب الكفارة؟ جزاكم الله خيرًا.","title":"الأيمان التي توجب الكفارة","answer":"الجواب:  الأيمان هي التي تحصل من العبد على أمور مستقبلة: والله لا آكل كذا، والله لا أزور فلانًا، والله لا أفعل كذا، أو والله لأفعلن كذا، أو لأكلمنه، أشياء مستقبلة، إذا خالف وجبت عليه الكفارة، مثل قال: والله لا أزور فلانًا، ثم زاره؛ عليه كفارة، أو والله لا أشرب هذا الشيء، فشربه؛ وجبت عليه كفارة، أو والله لا أسافر اليوم، فسافر؛ عليه الكفارة، وهكذا، نعم. أما الماضي فهذا يسمى كذبًا، الماضي إذا قال: والله ما فعلت كذا، وهو يكذب؛ هذا يأثم، وعليه التوبة إلى الله، أو والله ما زرت فلانًا، وهو يكذب؛ عليه التوبة، وليس فيه كفارة، أو قال: والله ما عاملت فلانًا، أو ما أعطيته كذا، وهو يكذب؛ يكون عليه التوبة، نعم، وليس فيه الكفارة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10291/الايمان-التي-توجب-الكفارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_437/43709.mp3","categories":["الأيمان والنذور"]},{"id":12107,"question":"ما حكم من حلف ولم يكفر عن يمينه؟","title":"حكم من وجبت عليه كفارة يمين ولم يكفر","answer":"الجواب:  عليه أن يكفر عنها ولو طالت المدة، عليه أن يتوب إلى الله، ويستغفر، ويبادر بالكفارة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10292/حكم-من-وجبت-عليه-كفارة-يمين-ولم-يكفر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_437/43710.mp3","categories":["الأيمان والنذور"]},{"id":12137,"question":"من بغداد في العراق رسالة بتوقيع إحدى المستمعات تقول: أختكم في الله ميسرة تسأل جمعًا من الأسئلة، في أحدها تقول: اضطررت في مرة من المرات أن أحلف اليمين على القرآن، ولكني كنت على غير طهارة، فما حكم ما فعلت؟","title":"حكم الحلف على القرآن ولمسه على غير طهارة","answer":"الجواب:  ما فيه حاجة للحلف على القرآن، يكفي اليمين من غير حاجة إلى الحلف على القرآن، وإذا حلفت على القرآن وأنت على غير طهارة لمستيه؛ فعليك التوبة والاستغفار؛ لأن القرآن لا يمسه إلا طاهر، إلا من هو على وضوء، وليس على جنابة، يكون متطهرًا من الجنابة، ومن الحدث الأصغر أيضًا؛ لقوله -جل وعلا-: لا يَمَسُّهُ إِلَّا الْمُطَهَّرُونَ [الواقعة:79] ولأن الرسول ﷺ أمر أن لا يمس القرآن إلا طاهر قال: لا يمس القرآن إلا طاهر... المقصود: أنك إذا كنت لمست القرآن عند الحلف، وأنت على غير وضوء؛ فعليك التوبة والاستغفار، وليس هناك أصل بين للذين يحلفون على القرآن، يكفي أن يحلف وإن كان على غير القرآن، يقول: والله ما فعلت كذا، والله إنه صار كذا، يكفي، ولا حاجة إلى أن يقال له: احلف على القرآن؛ لعدم الدليل على هذا الأمر، فإذا حلف لخصمه أنه ما عنده إلا هذا الحق المدعى، وليس هناك بينة؛ كفى، ولا حاجة إلى أن يحلف على القرآن، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10322/حكم-الحلف-على-القران-ولمسه-على-غير-طهارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_439/43906.mp3","categories":["الأيمان والنذور"]},{"id":12139,"question":"من صنعاء رسالة بعثت بها إحدى المستمعات، تقول: المرسلة أم مروان عبدالله نصر أم مروان لها جمع من الأسئلة في أحدها تقول: إن لي جارة لم تحمل، وأنذرت لله أن تذبح خروفًا، وتعطيه المساكين في حالة حملها، لكن مضى الآن سنتان ولم تحمل، فماذا يجب عليها؟","title":"حكم من نذرت نذر طاعة على تحقق شيء ولم يتحقق","answer":"الجواب:  متى حملت؛ توفي بنذرها، يقول النبي ﷺ: من نذر أن يطيع الله؛ فليطعه، ومن نذر أن يعصي الله فلا يعصه رواه البخاري في الصحيح، فإذا يسر الله لها الحمل، يسر الله أمرها؛ فلتذبح الخروف الطيب مثل الضحية، جذع ضأن، أو ثني ماعز يذبح سليمًا من العيوب للفقراء، يذبح ذبيحة طيبة، ليس فيها عيوب، ولا مريضة، ولا مكسورة القرن، ولا مقطوعة الأذن، تكون سليمة من العيوب، مثل الضحية، تذبح وتوزع للفقراء إذا يسر الله حملها. متى يسر الله لها الحمل؛ عليها أن توفي بالنذر، وما دامت لم تحمل؛ ما عليها شيء، والحمد لله، ونوصيها بعدم النذر، نوصي كل مسلم بعدم النذر؛ لقول النبي ﷺ: لا تنذروا؛ فإن النذر لا يرد من قدر الله شيئًا، وإنما يستخرج به من البخيل خرجه الشيخان في الصحيحين.  فالنذر لا يأتي بخير، فنوصي الجميع بعدم النذر؛ لقوله ﷺ: لا تنذروا؛ فإن النذر لا يرد من قدر الله شيئًا، وإنما يستخرج به من البخيل لكن من نذر أن يطيع الله؛ فعليه أن يطيع الله؛ لقول الله سبحانه: يُوفُونَ بِالنَّذْرِ وَيَخَافُونَ يَوْمًا كَانَ شَرُّهُ مُسْتَطِيرًا [الإنسان:7] فالمؤمنون يوفون بنذور الطاعة، أما نذر المعصية لا يوفى به، لو قال: لله عليه أنه يزني، ما يجوز له الزنا، عليه كفارة يمين، أو قال: لله عليه أن يضرب فلانًا بغير حق، لا يجوز له، وعليه كفارة يمين عن نذره، نذر المعصية، أو قال: لله عليه أن يسرق، ما يجوز له، وعليه أن يتوب إلى الله، ويكفر كفارة يمين. أما الشيء المباح لو قال: نذر لله عليه أنه يزور فلانًا، أو يأكل طعام فلان، أو يكلم فلانًا، هو مخير، إن شاء فعل، وإن شاء كفّر عن يمينه، وإن زار أخاه؛ لأن الزيارة مستحبة، إذا كان أخوه رجلًا طيبًا، فالزيارة أولى كونه يزوره أولى؛ لأنها نوع من العبادة. فالأفضل أن يوفي بنذره، ويزور أخاه، إذا كان أخًا طيبًا زيارته طيبة، فالأفضل أن يزوره، والأحوط أن يزوره، ولا يكفر، .... طاعة، والرسول ﷺ يقول: من نذر أن يطيع الله؛ فليطعه. أما لو قال: لله عليه أن يأكل كذا، أو يشرب كذا، أو يفعل كذا من المباحات؛ فهو مخير، إن شاء فعل، وإن شاء كفر عن يمينه، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10324/حكم-من-نذرت-نذر-طاعة-على-تحقق-شيء-ولم-يتحقق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_439/43908.mp3","categories":["الأيمان والنذور"]},{"id":12160,"question":"المستمع: سليمان ضاوي بعث برسالة يسأل فيها سماحتكم عن الحلف بالطلاق بعد كتابة العقد على الزوجة، وقبل الدخول، هل يؤثر، أو لا يؤثر؟","title":"حكم الحلف بالطلاق بنية الحث أو المنع أو التصديق","answer":"الجواب:  هذا فيه تفصيل: والمشروع ترك الحلف بالطلاق، بالكلية، لا يعتاده، لا يقل: علي الطلاق ما أفعل كذا، علي الطلاق لأفعلن كذا، إن قمت فأنت طالق، يترك هذه المسألة، المشروع للزوج أن يتباعد عن الطلاق، حتى لا يقع فيه، لكن الحلف بالطلاق معناه: تعليقه على أمر يقصد المنع منه، أو الحث عليه، أو التصديق أو التكذيب، هذا يسمى: حلف، يسمى: يمينًا، علي الطلاق ما أفعل كذا، علي الطلاق ما أسافر، علي الطلاق ما أكلم فلانًا، علي الطلاق ما تخرجين المحل الفلاني، علي الطلاق ما تكلمين فلانًا، علي الطلاق أن تدخلي في البيت، علي الطلاق أنك ما تصنيعن الطعام الفلاني، وهكذا، هذا يسمى: يمينًا، إذا كان قصده حث، أو منع، أو تصديق، أو تكذيب، علي الطلاق أني ما فعلت هذا، أني ما قلت هذا الكلام، .... حتى يصدق، يسمى: يمينًا، علي الطلاق أن فلانًا ما هو صادق، يعني يبيه يكذب . علي الطلاق عن أكل طعام فلان ..... حتى يأكله، علي الطلاق ما أكلم فلانًا حتى يمتنع، هذا يسمى: يمينًا، أما لو قال: علي الطلاق إذا دخل رمضان هذا ما يسمى يمينًا، هذا شرط، هذا معلق به، علي الطلاق إذا دخل رمضان، علي الطلاق إذا دخل شوال، علي الطلاق إذا نزل المطر، هذا معناه: التعليق فقط، ما يسمى يمينًا، يسمى: تعليقًا؛ لأن ما فيه حث، ولا منع، ولا تصديق، ولا تكذيب.  المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10345/حكم-الحلف-بالطلاق-بنية-الحث-او-المنع-او-التصديق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_441/44110.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":12171,"question":"يقول: حدث شجار بيني وبين عمي، فقلت: لحمكم علي حرام، ثم ندمت، فما الحكم في ذلك، وهل هنالك كفارة؟","title":"كفارة الحلف على تحريم الحلال","answer":"الجواب:  نعم عليك كفارة يمين إذا أكلت من لحمهم، وهي إطعام عشرة مساكين، أو كسوتهم، عشرة فقراء، تعطي كل واحد نصف صاع من تمر، أو رز، أو غيره من قوت البلد، ومقدار ذلك كيلو ونصف تقريبًا، يدفع للفقير الواحد، الجميع خمسة عشر كيلو، لكل واحد كيلو ونصف، وذلك نصف صاع من قوت البلد من رز، أو تمر، أو حنطة، أو شعير، أو ذرة، ونحو ذلك، حسب قوت البلد. أو كسوتهم إذا كسوت كل واحد إزارًا ورداء أو قميصًا؛ فلا بأس، يكفي عن الطعام، أو عتق رقبة مؤمنة، فإن لم تستطع هذا كله، لا إطعام، ولا كسوة، ولا عتق؛ فعليك أن تصوم ثلاثة أيام، هذا في حق الفقير العاجز، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10357/كفارة-الحلف-على-تحريم-الحلال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_442/44209.mp3","categories":["الأيمان والنذور"]},{"id":12215,"question":"ينتشر بين كثير من الناس -السؤال لا زال لأختنا أم عبدالله- ينتشر بين كثير من الناس قول: أقسم بآيات الله، أرجو من سماحتكم توضيح عقوبة هذا الأمر مشكورًا، كما ينتشر قولهم عند القسم: ورحمة والدي، أو ورأس فلان، أرجو منكم التوضيح بشدة عند هذا المقام جزاكم الله خيرًا.","title":"حكم القسم بآيات الله وصفاته","answer":"الجواب:  أما الإقسام بآيات الله فهذا لا حرج فيه إذا كان المقسم يقسم بالقرآن حين قال: أقسم بآيات الله، قصده القرآن؛ فلا حرج؛ لأن القرآن كلام الله، كما لو قال: أقسم بعلم الله، بعزة الله؛ لا حرج في ذلك. أما إذا كان يقصد الآيات المخلوقة كالليل والنهار والسماء والأرض هذا لا يجوز، وهكذا رحمة والديك هذا مجمل، لا يصلح تقسم برحمة والديك، أو بالأمانة، أو برأس فلان، أو شرف فلان، كل هذا لا يجوز ...... والديك من يرحم رحمتك أنت لوالديك وإلا رحمته هو، وإلا رحمة الله، إذا كان المقصود رحمة الله، أن الله يرحم والديك؛ فهذا له حكم الصفات، إذا قصد رحمة الله لوالديه هذه صفة من صفات الله، أما إذا قال: ... رحمته هو، إن الله يرحم والديه، إنك ترحم والديك وتعطيني كذا وكذا، ترحمه أنت، فرحمة المخلوق لوالديه رحمة مخلوقة، لا يقسم بها. والحاصل أن القسم يكون بالله، أو بصفة من صفاته، لا بصفات المخلوقين، ولا بحياتهم، ولا برأس فلان، ولا شرف فلان إلى غير ذلك، هذا لا يجوز، إنما القسم يكون بالله وحده أو بصفة من صفاته  نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10401/حكم-القسم-بايات-الله-وصفاته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_446/44603.mp3","categories":["الأيمان والنذور"]},{"id":12224,"question":"بعض الناس إذا مرض؛ نذر أن يذبح بعض الدجاج؛ بناءً على نصائح بعض المشعوذين الذين يحددون لهم ألوانه، هل هذا جائز، أم لا؟ أفيدونا جزاكم الله خيرًا.","title":"حكم من ذبح ذبيحة شرطها عليه المشعوذون","answer":"الجواب:  إذا كان على طريقة المخرفين والدجالين والكهانة ونحو هذا؛ فلا يجوز، أما إذا أراد التقرب إلى الله إن الله شفاه أن يذبح دجاجًا، أو ناقة، أو شاة للفقراء والمحاويج، هذا قربة إلى الله، ولكن النذر مكروه ما ينبغي النذر، لكن لو نذر عليه أن يوفي بنذره؛ لقول النبي ﷺ: من نذر أن يطيع الله؛ فليطعه ولقول الله سبحانه: يُوفُونَ بِالنَّذْرِ [الإنسان:7] لكن النبي ﷺ نهى عن النذر قال: إنه لا يأت بخير فينبغي له ألا ينذر، لكن إذا نذر طاعة لله كصلاة وصوم وصدقة يوفي بنذره إذا حصل الشرط. أما أن ينذر دجاجة على رأي المخرفين الذين قد يجرونه إلى الشرك، ويقول له: إن نذرت دجاجة صفتها كذا، أو دجاجًا صفته كذا أو كذا يشفى مرضك، هذا كله باطل لا أصل له، هذا منكر، لا يطيعهم في ذلك، وإنما الذبح صدقة إذا نذر على أنه صدقة لله؛ لعل الله ينفعه بهذه الصدقة؛ لا بأس، أما على اعتقاد أن هذا الشيء يحصل به الشفاء بأسباب قول المخرفين هذا لا يجوز، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10412/حكم-من-ذبح-ذبيحة-شرطها-عليه-المشعوذون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_446/44612.mp3","categories":["الأيمان والنذور"]},{"id":12227,"question":"ما حكم الحلف بالأمانة والذمة، كقول الناس: أمانة عليك أخبرني بهذا الشيء، أو في ذمتك؟ جزاكم الله خيرًا.","title":"حكم الحلف بالأمانة ونحوها","answer":"الجواب:  الحلف بالأمانة، أو بالذمة لا يجوز، ولا بغيرهما من المخلوقات، يقول النبي ﷺ: من كان حالفًا؛ فليحلف بالله، أو ليصمت وقال -عليه الصلاة والسلام-: من حلف بشيء دون الله؛ فقد أشرك رواه الإمام أحمد بإسناد صحيح من حديث عمر  وفي الصحيحين عن النبي -عليه الصلاة والسلام- أنه قال: لا تحلفوا بآبائكم، من كان حالفًا؛ فليحلف بالله، أو ليصمت، وقال أيضًا -عليه الصلاة والسلام-: لا تحلفوا بآبائكم، ولا بأمهاتكم، ولا بالأنداد، ولا تحلفوا بالله إلا وأنتم صادقون وقال أيضاً -عليه الصلاة والسلام-: من حلف بالأمانة؛ فليس منا. فلا يجوز للمسلم، ولا للمسلمة الحلف بغير الله، فلا يقول: بالأمانة ما فعلت كذا، ولا بذمتي ما فعلت كذا، ولا بحياتك ما فعلت كذا، أو وحياتك ما فعلت كذا، أو شرفك أو بالنبي، أو بالكعبة، كل هذا لا يجوز، كله من الشرك، لكن إن قال: في ذمتي هذا ما يسمى يمينًا، في ذمتي.. ما يسمى يمينًا، أو قال: أعطيك هذا الشيء وأنا مؤتمن عليه، ما يحلف بالأمانة يقول: لك بهذا ذمتي لك بهذا أمانتي أني لا أخونك، هذا ما يسمى يمينًا. أما إذا قال: بأمانتي، أو برأس فلان، أو بذمتي، أو والأمانة فهذا كله لا يجوز؛ لأن الحلف يكون بالباء، أو بالواو، أو بالتاء: تالله، والله، بالله، فهكذا إذا قال: بالأمانة والأمانة والكعبة بالكعبة، وحياة فلان، وشرف فلان، وحياة أبيه، ونحو هذا، كل هذا يسمى حلفًا بغير الله، لا يجوز، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10415/حكم-الحلف-بالامانة-ونحوها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_447/44703.mp3","categories":["الأيمان والنذور","الحلف بغير الله"]},{"id":12269,"question":"المستمع (م. أ. م) مصري بعث برسالة يقول فيها: حصلت مشادة عنيفة بيني وبين أحد أبناء عمي، وعندما ذهبت إلى المنزل صادفت زوجتي فبادرتها قائلًا: إذا ذهبت إلى بيت ابن عمي؛ فأنت تحرمي، ولم أكمل: علي، وكان هذا منذ مدة طويلة، وحصلت حالة وفاة في بيت ابن عمي، وأنا موجود في العراق، فذهبت زوجتي دون علمي، ولي منها ثلاثة أطفال، ولم أفاتحها بموضوع ذهابها من أجل الأطفال، وعلاقتي بها علاقة طبيعية، لكني أخشى أن يكون تحريمي قد وقع، أو أن يكون علي كفارة، أرجو إفادتي جزاكم الله خيرًا.","title":"حكم من حرَّم زوجته إن هي فعلت شيئاً منعها منه","answer":"الجواب:  إذا كان قصدك منعها من الذهاب إلى بيت ابن عمك، وليس قصدك تحريمها، ولا طلاقها؛ فعليك كفارة يمين: وهي إطعام عشرة مساكين، أو كسوتهم، عشرة عدد أصابعك، وهي نصف صاع لكل واحد، بصاع النبي -عليه الصلاة والسلام- ومقدار ذلك كيلو ونصف تقريبًا من الرز أو التمر أو الحنطة، يدفع إلى بعض الفقراء، أو كسوتهم، كل واحد يكسى قميصًا، كما قال تعالى في الأيمان: وَلَكِنْ يُؤَاخِذُكُمْ بِمَا عَقَّدْتُمُ الأَيْمَانَ فَكَفَّارَتُهُ إِطْعَامُ عَشَرَةِ مَسَاكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ [المائدة:89] الآية، قد أفتى بهذا جمع من الصحابة  ويدل على هذا قوله -جل وعلا-: يَا أَيُّهَا النَّبِيُّ لِمَ تُحَرِّمُ مَا أَحَلَّ اللَّهُ لَكَ تَبْتَغِي مَرْضَاةَ أَزْوَاجِكَ وَاللَّهُ غَفُورٌ رَحِيمٌ [التحريم:1] جاء في التفسير: أن ذلك تحريمه لأمته، وقال آخرون: تحريمه للعسل. فالمقصود: أن الإنسان إذا قال مثل هذا الكلام: إن ذهبت إلى بيت ابن عمي، أو إلى بيت آل فلان؛ فأنت حرام علي، قصده المنع؛ فإن عليه كفارة يمين إذا ذهبت إليهم، إما إن كان قصدك تحريمها، أو طلاقها إن ذهبت؛ فإنها تحرم عليك حتى تكفر كفارة الظهار، وهي عتق رقبة مؤمنة، فإن عجزت؛ تصم شهرين متتابعين، فإن عجزت؛ تطعم ستين مسكينًا، ثلاثين صاعًا قبل أن تمسها، قبل أن تقربها، وإذا كنت قد قربتها؛ تمتنع حتى تكفر هذه الكفارة، وهي مرتبة، أولًا: عتق رقبة مؤمنة، فإن عجزت؛ تصم شهرين متتابعين، ستين يومًا، فإن عجزت؛ تطعم ستين مسكينًا، ثلاثين صاعًا، بصاع النبي ﷺ، ومقدار الصاع ثلاثة كيلو تقريبًا، لكل مسكين نصف صاع، كيلو ونصف تقريبًا للستين، قبل أن تمسها، هذا إذا كنت قصدت التحريم، إذا ذهبت، أما إن كنت قصدت الطلاق، ما قصدت التحريم؛ فيقع طلقة واحدة، وتراجعها إذا كان ما قبلها طلقتان، إذا كنت لم تطلقها قبل هذا طلقتين تراجعها، والحمد لله، تقول: اشهد يا فلان وفلان أني راجعتها، أو تقول: قد راجعتك يا فلانة، يكفي، وإذا شاهدت عدلين يكون أنسب وأفضل. أما إذا كنت ما أردت تحريمها، ولا طلاقها، وإنما أردت تهديدها، ومنعها وتخويفها، ولم ترد لا طلاقًا، ولا تحريمًا؛ فإن عليك كفارة اليمين فقط، ويكون لهذا الكلام حكم اليمين، كما تقدم، وهي إطعام عشرة مساكين، لكل مسكين نصف صاع من التمر، أو الحنطة، أو الرز، مقداره كيلو ونصف تقريبًا، أو تكسوهم كسوة، كل واحد قميصًا ... أو إزارًا ورداءًا يجزئه في الصلاة، يكفي هذا، إذا كنت ما أردت الطلاق ولا التحريم، وإنما أردت تهديدها ومنعها، وينبغي لك أن تحذر مثل هذا، وألا تستعمله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10469/حكم-من-حرم-زوجته-ان-هي-فعلت-شيىا-منعها-منه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_450/45006.mp3","categories":["الأيمان والنذور","الظهار"]},{"id":12362,"question":"بعد هذا رسالة بعث بها المستمع محمد عبدالحليم موسى يقول: نذرت لله صيام شهرين متتابعين منذ سنتين أو أكثر إذا فتح الله علي بالرزق الوفير، والحمد لله قد حصل، ولكني كلما بدأت الصوم لا أستطيع تكملة اليوم بسبب العمل الذي يرهقني، فأنا أعمل في مزرعة ذات عمل متواصل، فهل هناك كفارة لهذا النذر؟","title":"هل هناك كفارة للنذر الذي يشق القيام به؟","answer":"الجواب:  عليك أن توفي بنذرك، وأن تجعل في المزرعة من يكفيك بعض المؤنة مدة الصيام، تستعين بالله، ثم ببعض العمال حتى يكفوك المؤنة، ما دام أعطاك الله الرزق الوفير؛ استعمل مما أعطاك الله عمالاً يكفونك المؤنة حتى تصوم، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10574/هل-هناك-كفارة-للنذر-الذي-يشق-القيام-به- ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_400/40012.mp3","categories":["الأيمان والنذور"]},{"id":12367,"question":"بعد هذا رسالة بعث بها المستمع محمد عبدالحليم موسى يقول: نذرت لله صيام شهرين متتابعين منذ سنتين أو أكثر إذا فتح الله علي بالرزق الوفير، والحمد لله قد حصل، ولكني كلما بدأت الصوم لا أستطيع تكملة اليوم بسبب العمل الذي يرهقني، فأنا أعمل في مزرعة ذات عمل متواصل، فهل هناك كفارة لهذا النذر؟","title":"هل هناك كفارة للنذر الذي يشق القيام به؟","answer":"الجواب:  عليك أن توفي بنذرك، وأن تجعل في المزرعة من يكفيك بعض المؤنة مدة الصيام، تستعين بالله، ثم ببعض العمال حتى يكفوك المؤنة، ما دام أعطاك الله الرزق الوفير؛ استعمل مما أعطاك الله عمالاً يكفونك المؤنة حتى تصوم، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10574/هل-هناك-كفارة-للنذر-الذي-يشق-القيام-به- ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_400/40012.mp3","categories":["الأيمان والنذور"]},{"id":12407,"question":"يقول: إنني حلفت بالله  على ألا أرتكب معصية من المعاصي، لكني عدت وفعلت، ماذا علي؟ أرشدوني جزاكم الله خيرًا.","title":"حكم من حلف على ترك المعصية ففعلها","answer":"الجواب:  عليك التوبة إلى الله، والندم، والإقلاع من المعصية، والحذر من العود إليها، والتصميم ألا تعود إليها، عليك التوبة إلى الله -جل وعلا- وعليك كفارة اليمين؛ لأنك حانث، فعليك كفارة يمين عن يمينك، وهي إطعام عشرة مساكين، أو كسوتهم، أو عتق رقبة، فمن عجز؛ صام ثلاثة أيام، وعليك مع ذلك التوبة إلى الله، والندم، والإقلاع، وعدم العود إلى هذه المعصية، العزم الصادق ألا تعود إليها، ومن يستعين بالله؛ يعينه الله، جل وعلا. فاتق الله، وراقب الله، واحذر هواك وشيطانك، والزم التوبة من هذه المعصية، وغيرها، وعليك كفارة اليمين وهي إطعام عشرة مساكين، عشرة فقراء تعشيهم، أو تغديهم، أو تعطي كل واحد نصف صاع من التمر، أو من الأرز، أو من البر، نصف صاع، كيلو ونصف تقريبًا لكل واحد، أو تعشيهم، أو تغديهم، ولو متفرقين، ليس من اللازم أن تجمعهم، ولو متفرقين، أو تكسوهم كسوة على قميص، قميص كل واحد كسوة تجزئه في الصلاة، قميصًا، أو إزارًا ورداء، أو تعتق رقبة إذا وجدت شيئًا، فإن عجزت عن هذا كله، فقير ما تستطيع، لا إطعام، ولا تستطيع الكسوة، ولا عتق؛ عند ذلك تصوم ثلاثة أيام، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10612/حكم-من-حلف-على-ترك-المعصية-ففعلها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_455/45512.mp3","categories":["الأيمان والنذور"]},{"id":12476,"question":"بعد هذا ننتقل إلى قضية أخرى تسأل عنها أختنا فائزة أحمد من ليبيا، فتسأل هذا  كفارة اليمين هل يجوز تأخيرها عن وقتها، أم أن لها وقتًا محددًا؟ جزاكم الله خيرًا.","title":"وجوب المبادرة بكفارة اليمين","answer":"الجواب:  الواجب المبادرة بكفارة اليمين إذا حنث، الواجب المبادرة، هذه قاعدة في الأوامر المبادرة؛ لقول النبي ﷺ في الحديث الصحيح: ما أمرتكم به؛ فأتوا منه ما استطعتم، وما نهيتكم عنه؛ فاجتنبوه ويقول الله -جل وعلا-: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، ويقول سبحانه: وَمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانْتَهُوا [الحشر:7].  فالواجب على المؤمن أن يتقي الله في كل شيء، ومن ذلك المبادرة بأداء الواجب في وقته، وأداء كفارة اليمين في وقتها إذا حنث، كفارة الظهار في وقتها، كفارة الجماع في رمضان في وقتها، وهكذا. يجب على المؤمن أن يبادر بما أوجب الله عليه في وقته مع الاستطاعة، وكفارة اليمين وضحها الله في سورة المائدة في قوله سبحانه: لا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِنْ يُؤَاخِذُكُمْ بِمَا عَقَّدْتُمُ الأَيْمَانَ فَكَفَّارَتُهُ [المائدة:89] يعني: اليمين إِطْعَامُ عَشَرَةِ مَسَاكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍ فَمَنْ لَمْ يَجِدْ فَصِيَامُ ثَلاثَةِ أَيَّامٍ ذَلِكَ كَفَّارَةُ أَيْمَانِكُمْ إِذَا حَلَفْتُمْ وَاحْفَظُوا أَيْمَانَكُمْ [المائدة:89] فهذه كفارة اليمين: إطعام عشرة مساكين من أوسط الطعام، لا من أعلاه، ولا من أدناه الأوسط، وإذا أخرج من الأعلى؛ كان أفضل، إذا أنفق من الأعلى؛ كان أطيب وأفضل، فإذا حنث قال: والله ما أكلم فلانًا، وكلمه، أو: والله ما أسافر، وسافر، أو ما أشبه ذلك؛ يبادر بالكفارة، فإذا حنث بترك ما حلف عليه، أو فعل ما حلف على تركه؛ يبادر بالكفارة بإطعام عشرة مساكين، كل مسكين له نصف الصاع بصاع النبي ﷺ من قوت البلد، قوت بلده، رز، أو تمر، أو شعير، أو ذرة، أو حنطة، قوت بلده فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُم [التغابن:16] أو يكسوهم كسوة، كل واحد له قميص، أو إزار ورداء، أو عتق رقبة، عتق عبد وإلا عبدة مخير. ومقدار نصف الصاع كيلو ونصف تقريبًا، كيلو ونصف تقريبًا، هذا نصف الصاع، من قوت البلد بلده هو، لا يتكلف من قوت بلده متوسط، وإن أخذ من الأعلى؛ كان أفضل وأكثر، لكن لا يجوز أن يخرج من الأدنى، الله يقول سبحانه: وَلا تَيَمَّمُوا الْخَبِيثَ مِنْهُ تُنفِقُونَ [البقرة:267] الخبيث: الرديء، ولكن المؤمن يخرج من الوسط، أو من الأعلى، وهكذا الزكاة تكون من الوسط، أو من الأعلى. فإن عجز؛ صام ثلاثة أيام، والأفضل أن تكون متتابعة؛ لأن بعض أهل العلم أوجب أن تكون متتابعة، فالأفضل الاحتياط، وأن يصومها متتابعة، إذا عجز عن الإطعام، وعن الكسوة، وعن الرقبة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10681/وجوب-المبادرة-بكفارة-اليمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_405/40502.mp3","categories":["الأيمان والنذور"]},{"id":12477,"question":"أحد الإخوة المستمعين يقول: المرسل (ج . أ. صالح) يسأل ويقول: لقد ضايقني كفيلي، وحملني أكثر مما أطيق، وذات مرة قلت: تكون زوجتي طالق إذا رجعت مرة ثانية، أسمعت بها نفسي، ثم رجعت مرة ثانية، مع العلم أنني ذهبت إلى بلدي، ومكثت فيها ستة أشهر، ثم رجعت، والآن مر أكثر من عام ونصف، مع العلم أيضًا أن ذلك من باب التحدث بالنعم أنني من حفظة كتاب الله، وأحفظ القرآن كله تقريبًا، وكنت أعلم ابن كفيلي أحكام التجويد؟ وجهوني جزاكم الله خيرًا.","title":"حكم من قال: تكون زوجتي طالقًا إذا رجعت ورجع","answer":"الجواب:  هذا فيه تفصيل: إن كنت أردت بقولك: إذا رجعت فامرأتك طالقة الامتناع من الرجوع، وليس قصدك إيقاع الطلاق، قصدك منع نفسك من الرجوع، وليس قصدك بذلك تطليق امرأتك، فهذا حكمه حكم اليمين، وعليه كفارة يمين، أما إن كنت قصدت الطلاق؛ فإنه يقع الطلاق... مانع من وقوعه. فالحاصل: أنك تسأل قاضي البلد عندك، تحضر مع المرأة ووليها حتى يرشدك القاضي إلى الواجب، فالمقصود أن هذا فيه تفصيل، وفي قرار المحكمة لديكم -إن شاء الله- الكفاية، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10687/حكم-من-قال-تكون-زوجتي-طالقا-اذا-رجعت-ورجع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_405/40508.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":12506,"question":"يسأل سماحتكم فيقول: ما الفرق بين اليمين الغموس، واليمين اللغو؟","title":"الفرق بين يمين الغموس ويمين اللغو","answer":"الجواب:  اليمين الغموس هي التي يتعمد فيها الكذب، كذاب كاذب، يقول: والله ما بعت كذا، وهو يكذب، والله ما سافرت إلى كذا، وهو يكذب، وما أشبه ذلك،، هو يقال لها: اليمين الغموس؛ لأنها تغمس صاحبها في الإثم، ثم في النار، أعوذ بالله ..... جريمة، وهي المراد في قوله ﷺ: من حلف على يمين هو فيها كاذب؛ لقي الله وهو عليه غضبان وفي اللفظ الآخر: من اقتطع حق امرئ مسلم بيمينه؛ فقد أوجب الله له النار، وحرم عليه الجنة. هذه يقال لها: اليمين الغموس، وهي اليمين الكاذبة الفاجرة التي يتعمدها الإنسان، أما اليمين اللاغية هي التي لا يتعمد فيها الكذب، تجري على لسانه من غير قصد، كما في قوله سبحانه: لا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ [البقرة:225] قالت عائشة -رضي الله عنها-: \"هو قول الرجل: لا والله، وبلى والله -بلسانه من غير قصد- تجري على لسانه من غير قصد\" في حديثه مع الناس من غير تعمد الكذب، ولكن إنما تجري على لسانه من غير قصد في عرض الحديث، فهذه يقال لها: لغو اليمين. وهكذا من لغو اليمين: اليمين التي يحلف بها ظانًا صدقه، فيبين أنه قد أخطأ، هذه لاغية، لا شيء فيها، مثل الذي يقول: والله إن فلانًا قد وصل، شفته أمس، ثم تبين له أنه غلطان، ما هو ..... شبيه له، هذه يمين تسمى: لاغية؛ لأنه ظنه صاحبه، ما تعمد الكذب، والله إن فلانًا وصل، والله إن فلانًا سافر، يظن ذلك؛ لأنه رآه، وشبه عليه، فظن أنه هو .. ثم ظهر له أنه قد أخطأ، وأن الذي سافر، أو قدم ليس هو صاحبه، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10712/الفرق-بين-يمين-الغموس-ويمين-اللغو","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_407/40706.mp3","categories":["الأيمان والنذور"]},{"id":12516,"question":"بعد هذا ننتقل إلى رسالة أخرى بعث بها مستمع من منطقة تبوك هو صالح عبدالعزيز الشايع: كنت من الذين يشربون الدخان، ومَنَّ الله  علي وتركته، إلا أنني أيام ما كنت أدخن نذرت لله أني إن بطلت هذا الدخان لأذبحن خروفين لله تعالى، وأنا الآن لي سنتين منذ أن تركته ولم أف بالنذر لسوء أحوالي المادية، فبماذا تنصحونني؟ جزاكم الله خيرًا.","title":"حكم الوفاء بالنذر للعاجز عنه","answer":"الجواب:  ننصحك بالوفاء بالنذر، الله يقول: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] ويقول سبحانه: وَإِنْ كَانَ ذُو عُسْرَةٍ فَنَظِرَةٌ إِلَى مَيْسَرَةٍ [البقرة:280] ويقول النبي ﷺ: من نذر أن يطيع الله؛ فليطعه وأنت نذرت أن تطيع الله بالخروف، فعليك أن تذبحه متى تيسر، في أي وقت تيسر لك تذبحه، وتوزع لحمه على الفقراء، نعم؛ شكرًا لله على التوبة.","link":"https://binbaz.org.sa/fatwas/10715/حكم-الوفاء-بالنذر-للعاجز-عنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_407/40709.mp3","categories":["الأيمان والنذور"]},{"id":12535,"question":"سنعود إلى بقية أسئلة أخينا في حلقات قادمة -إن شاء الله تعالى- أما الآن فهذه رسالة المستمعة: (ج. م. م) من الكويت، بعثت برسالة تقول فيها: لسبب صحتي نذرت ألا آكل سوى وجبتين في اليوم فقط، وحيث أنني طالبة، وأعود إلى المنزل سيرًا على الأقدام، فقد أصبحت أجوع جوعًا شديدًا، والفترة بين الغداء، ووجبة الإفطار في اليوم التالي متباعدة، ماذا أفعل؟ هل أستمر، أم أن علي كفارة فيما إذا أردت أن آكل وجبة ثالثة، أفيدوني، جزاكم الله خيرُا؟","title":"حكم الوفاء بالنذر المباح","answer":"الجواب:  هذا يسمى: نذرًا مباحًا، أو نذرًا مستحبًا على الأكثر بقصد الاقتصاد، أو لقصد النشاط في العبادة، أو لقصد النشاط في طلب العلم، فلا بأس إذا أكلت أزيد من ذلك، وعليك كفارة اليمين، هذا النذر ليس بواجب، ليس طاعة لله يجب الوفاء به، بل هذا قصاراه أن يكون مباحًا؛ فعليك كفارة اليمين، والحمد لله: إطعام عشرة مساكين، أو كسوتهم، وتأكلين ثلاث وجبات، أو أكثر، لا بأس بذلك. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10742/حكم-الوفاء-بالنذر-المباح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_409/40904.mp3","categories":["الأيمان والنذور"]},{"id":12584,"question":"إذا تصدق شخص بأن يصوم شهرًا، وحدث عليه بعض البدل، فماذا عليه؟","title":"الفرق بين النذر بالشيء ومجرد النية به","answer":"الجواب:  هذا السؤال فيه إجمال: إن كان قصده تصدق، يعني نذر، قال: صدقة لوجه الله أني أصوم شهرًا؛ فهذا يسمى نذرًا، ما يسمى صدقة، يسمى نذرًا؛ فعليه أن يوفي بنذره إذا استطاع ذلك، فإن لم يستطع؛ بقي في ذمته حتى يستطيع؛ لقول النبي ﷺ: من نذر أن يطيع الله؛ فليطعه. أما إن كان مجرد نية أنه يتصدق، أو قال: إن شاء الله أصوم؛ هذا ما يلزمه شيء، إنما يلزمه إذا قال: نذر لله، أو علي لله، أو صدقة لله أن أصوم كذا، أو أصلي كذا؛ فإنه يلزمه، فإذا عرض له عارض يمنعه من مرض، أو سفر فعله بعد ذلك. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10786/الفرق-بين-النذر-بالشيء-ومجرد-النية-به","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_412/41203.mp3","categories":["الأيمان والنذور"]},{"id":12613,"question":"مستمع من مصر هو محمد أحمد عبداللطيف يوسف بعث يقول: حلف أخ لي عدة أيمان بأن أرافقه إلى منزله، وكان الوقت متأخرًا من الليل، فحلفت يمينًا بأن لا أذهب معه، فقال لي: أنا حلفت عدة أيمان، وأنت حلفت يمينًا واحدًا، وأخيرًا ذهبت معه، وأنا غير راضٍ عن هذا، فهل هذا اليمين الذي حلفته يعد لغوًا، أم تجب فيه الكفارة؟ وإذا كانت تجب فيه الكفارة، نرجو إفادتنا ما هي؟ جزاكم الله خيرًا.","title":"حكم من حلف على شيء فحنث في يمينه","answer":"الجواب: نعم تجب فيه الكفارة، والحمد لله إذا لنت في يد أخيك على وجه ليس فيه معصية لله؛ فلا بأس، وعليك كفارة اليمين، النبي ﷺ أمر بإبرار قسم المقسم، فإذا بررت قسم أخيك، وطاوعته في أمر لا يغضب الله، فأنت مأجور، وعليك كفارة اليمين: وهي إطعام عشرة مساكين، أو كسوتهم عشرة، تغديهم، أو تعشيهم، أو تدفع لكل واحد نصف صاع، كيلو ونصف من التمر، أو غيره من قوت البلد، أو تكسوه كسوة تجزي الصلاة، كالقميص، والإزار، والرداء، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10817/حكم-من-حلف-على-شيء-فحنث-في-يمينه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_414/41405.mp3","categories":["الأيمان والنذور"]},{"id":12627,"question":"من جمهورية مصر العربية رسالة وصلت إلى البرنامج من إحدى المستمعات من هناك تقول أم عبدالله: أم عبدالله في سؤال طويل لها تقول: هل يجوز لزوجي أن يمنعني من زيارة أهلي -أبي وأمي وإخواني- وأن يقول لي: أنت مخيرة في البقاء معي، أو تزوري بيت أهلك إذا خرجت لزيارة أهلك لا تدخلي بيتي مرة ثانية، علمًا بأن أهلي غير ملتزمين، ولما علم زوجي بأنني حزنت بسبب هذا الكلام قال لي: إذًا في كل شهر مرة، سافر زوجي بعد ذلك، وغاب لمدة أربعة أشهر، ومنعني من الذهاب إلى أهلي وامتثلت، سؤالي هو: هل يحق لزوجي أن يمنعني من زيارة أهلي لكونهم غير ملتزمين، وهل أكون آثمة والحالة هذه؟ وجهونا جزاكم الله خيرًا.","title":"حكم منع الرجل زوجته من زيارة أهلها غير الملتزمين","answer":"الجواب:  نعم، له أن يمنعك من زيارة أهلك إذا كانت الزيارة تضرك وتضره؛ لأنهم غير ملتزمين، أما إذا كانت الزيارة لا تضرك، ولا تضره، كأن تزوريهم لصلة الرحم والبر وتنصحيهم وتوجهيهم إلى الخير؛ هذا أمر طيب، وينبغي ألا يمنعك، أما إن كانت الزيارة تضرك وتضره، وتسبب مشاكل بينكم، بينكما وبين الأهل؛ فله أن يمنعك من ذلك؛ لما في هذا من المضرة عليه وعليك. وإذا طلق ألا تزوريهم؛ لا تذهبي إليهم، وإن ذهبت إليهم؛ وقع الطلاق إن كان أراد وقوعه، أما إن كان أراد منعك، لا وقوع الطلاق، ولكن أراد أن يمنعك، وأراد تخويفك، وتهديدك، ولم يرد إيقاع الطلاق؛ فإن هذا له حكم اليمين، وعليه كفارتها. وبكل حال، فالواجب عليك السمع والطاعة فيما يقول لك إذا كان معروفًا، وليس فيه ما يخالف شرع الله، أما إذا كان شيئًا يخالف شرع الله، إذا كان منعه لك لا سبب له، ولا وجه له شرعي، فهذا يرجع إلى المحكمة إن لم تصلحي أنت وإياه، فالمرجع في هذا إلى المحكمة، والمحكمة تنظر في الأمر، وفي حل المشكلة، إلا إذا صلحتما فالصلح بينكما جائز وماضي، لكن بشرط ألا يكون ذلك في معصية الله، لابد أن يكون الصلح على وجه شرعي، ليس فيه معصية لله  نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10843/حكم-منع-الرجل-زوجته-من-زيارة-اهلها-غير-الملتزمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_415/41507.mp3","categories":["الطلاق","الحقوق الزوجية","الأيمان والنذور"]},{"id":12681,"question":"رسالة وصلت إلى البرنامج من إحدى المستمعات، الرسالة مكتوبة بالأسلوب العامي، وهي طويلة أيضًا، ملخص ما في هذه الرسالة: أن أباها زوجها من رجل وعمره ثمان وخمسون سنة، وهي صغيرة، لم تتجاوز العشرين، وحينئذ لما عرض عليها هذا الزواج؛ حلفت ألا تقبل به، لكن والدها أرغمها على ذلك، وحينئذ جبرت نفسها، وتزوجت، وهي الآن تعيش مع هذا الرجل، ويقسم لها مع ضراتها، وتسأل سماحتكم عن ذلكم اليمين كيف يكون تصرفها تجاهه، جزاكم الله خيرًا؟","title":"من حلفت ألا تتزوج برجل ثم أجبرها أبوها فتزوجت","answer":"الجواب:  عليها كفارة اليمين، عليها أن تكفر كفارة يمين، وقد أحسنت في طاعة أبيها، والحمد لله على ذلك، ونسأل الله أن يجعله زواجًا مباركًا، وأن ينفعها بذلك. وعليها كفارة اليمين، وهي إطعام عشرة مساكين، أو كسوتهم، يعني: يعطى كل واحد نصف صاع من التمر أو الحنطة أو الرز، كيلو ونصف تقريبًا، أو كسوة، كل واحد قميصًا، أو إزارًا ورداءً، هذه هي الكفارة عشرة، كل واحد يعطى نصف صاع من قوت البلد، ومقداره كيلو ونصف تقريبًا، أو كسوة قميص، أو إزار ورداء، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10891/من-حلفت-الا-تتزوج-برجل-ثم-اجبرها-ابوها-فتزوجت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_417/41709.mp3","categories":["الأيمان والنذور"]},{"id":12704,"question":"وجهوني -جزاكم الله خيرًا- إلى كيفية النذر الصحيح حتى أكون على بصيرة من أمري؟","title":"حكم النذر، وبيان بعض أحكامه","answer":"الجواب:  النذر لا ينبغي، الرسول نهى عن النذر -عليه الصلاة والسلام- وقال: لا تنذروا فإن النذر لا يرد من قدر الله شيئًا، وإنما يستخرج به من البخيل فلا ينبغي النذر، لكن من نذر طاعة؛ وجب عليه الوفاء، لقول النبي ﷺ: من نذر أن يطيع الله؛ فليطعه، ومن نذر أن يعصي الله؛ فلا يعصه ولأن الله مدح الموفي بالنذر في صفة الأبرار، فقال سبحانه: يُوفُونَ بِالنَّذْرِ وَيَخَافُونَ يَوْمًا كَانَ شَرُّهُ مُسْتَطِيرًا [الإنسان:7].  وهذه نذور الطاعة نذور الطاعة، يجب على الناذر أن يوفي بها، ويمدح بالوفاء، مثل أن ينذر أن يصوم يوم الإثنين والخميس، أن يصوم ثلاثة أيام من كل شهر، أو يصوم ستة أيام من شوال، فهذا نذر طاعة يلزمه الوفاء، أو ينذر أن يتصدق بكذا وكذا من المال، أو ينذر أن يحج، أو يعتمر، كل هذه النذور طاعة؛ فعليه أن يوفي بها. أما إذا كان الناذر نذر معصية مثل قال: لله عليه أن يشرب الخمر، أو لله عليه أن يقطع رحمه أو يعق والديه، هذا نذر منكر، ليس له الوفاء به، وعليه كفارة يمين، وهكذا لو نذر النذور الأخرى مكروهة، أو مباحة إن وفى بها؛ فلا بأس، وإلا فعليه كفارة يمين. مثل نذر لله أنه ما يصلي سنة الظهر، أو سنة الفجر يومًا معينًا، هذا نذر مكروه، يصليها ويكفر عن يمينه، وإن لم يصلها؛ فلا كفارة عليه؛ لأنها نافلة، أو نذر مباح، مثل لله عليه أن يأكل طعام فلان، أو لله عليه ألا يأكل طعام فلان، هذا نذر مباح، إن أكل طعامه الذي نذر أنه لا يأكله؛ عليه كفارة يمين، وإن لم يأكل وهو نذر أن يأكل؛ فعليه كفارة يمين؛ لأن هذه من النذور المباحة، أو قال: لله عليه أن يزور فلانًا، أو لله عليه أن -مثلًا- لا يزور فلانًا، فإذا خالف نذره؛ عليه كفارة يمين، نعم. المقدم: بارك الله فيكم، وجزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10914/حكم-النذر-وبيان-بعض-احكامه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_459/45909.mp3","categories":["الأيمان والنذور"]},{"id":12778,"question":"أخيرًا يسأل سماحتكم عن النذر، يقول: هل يجوز أن ينذر الإنسان بأنه إذا حصل له ما هو كذا وكذا أن يصلي عشرًا، أو عشرين ركعة، أو أكثر، أو أقل، جزاكم الله خيرًا؟","title":"حكم من نذر أن يصلي لله إذا حصل مراده","answer":"الجواب:  النذر منهي عنه، لا ينبغي النذر، ولكن متى رزقه الله خيرًا شكر الله بطاعته بالصلاة وغيرها، وأما النذر فمنهي عنه، يقول النبي ﷺ: لا تنذروا؛ فإن النذر لا يرد من قدر الله شيئًا، وإنما يستخرج به من البخيل متفق على صحته. فالمؤمن ينبغي له ترك النذر، لكن إن نذر طاعة؛ وجب عليه الوفاء، إذا نذر طاعة؛ وجب عليه الوفاء؛ لأن الله أثنى على الموفين بالطاعات، فقال سبحانه: يُوفُونَ بِالنَّذْرِ وَيَخَافُونَ يَوْمًا كَانَ شَرُّهُ مُسْتَطِيرًا [الإنسان:7] وقال النبي ﷺ: من نذر أن يطيع الله؛ فليطعه، ومن نذر أن يعصي الله؛ فلا يعصه خرجه البخاري في صحيحه -رحمه الله- فإذا نذر أن يصلي كذا وكذا، أو يصوم الإثنين والخميس، أو إذا رزقه الله ولدًا؛ تصدق بكذا، أو إذا تزوج؛ تصدق بكذا؛ يوفي بنذره إذا كان طاعة لله، مثلما ذكر. أما نذر المعاصي لا يجوز، لو قال: نذر لله عليه أنه يشرب الخمر، أو يسرق، أو يزني؛ فهذا نذر منكر، لا يجوز له الوفاء به، ولهذا قال ﷺ: من نذر أن يعص الله؛ فلا يعصه وعليه كفارة يمين في أصح قولي العلماء عن هذا النذر الخبيث. أما النذر المباح فهو مخير، إن شاء فعله، وإن شاء كفر عنه، مثل لو قال: نذر لله أني آكل من هذا الطعام، نذر لله أني أبيت في هذا البيت، أو أسافر اليوم، هو مخير، إن شاء أوفى، وإن شاء كفر عن يمينه كفارة النذر، لقول النبي ﷺ: كفارة النذر كفارة اليمين، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10992/حكم-من-نذر-ان-يصلي-لله-اذا-حصل-مراده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_420/42005.mp3","categories":["الأيمان والنذور"]},{"id":12787,"question":"ننتقل إلى رسالة وصلت إلى البرنامج من المملكة الأردنية الهاشمية، صاحب الرسالة هو المستمع: أحمد محمد العلياني، يقول: نذرت نذرًا، وتأخر الوفاء به لمدة ثلاثة أعوام، هل في ذلك إثم؟","title":"استحباب المبادرة في الوفاء بالنذر","answer":"الجواب:  الواجب عليك البدار بالنذر، إذا نذر الإنسان نذرًا يطيع الله فيه؛ وجب عليه البدار، والله مدح الموفين بالنذر، فقال سبحانه في سورة الإنسان: يُوفُونَ بِالنَّذْرِ وَيَخَافُونَ يَوْمًا كَانَ شَرُّهُ مُسْتَطِيرًا [الإنسان:7] ويقول النبي ﷺ: من نذر أن يطيع الله؛ فليطعه، ومن نذر أن يعصي الله؛ فلا يعصه. فالواجب على من نذر طاعة أن يبادر بها، فإذا قال: لله عليه أن يتصدق بألف ريال، لله عليه أن يصلي الضحى ركعتين، لله عليه أن يصوم يوم الإثنين، أو يوم الخميس، أو ثلاثة أيام من كل شهر؛ عليه أن يبادر، ويصوم كما نذر، مع أنه لا ينبغي النذر، الرسول ﷺ نهى عن النذر، قال: لا تنذروا؛ فإن النذر لا يرد من قدر الله شيئًا، وإنما يستخرج به من البخيل فالنذر لا ينبغي، ولكن متى كان طاعة؛ وجب الوفاء به، لقوله ﷺ: من نذر أن يطيع الله؛ فليطعه. فالمؤمن لا يتأخر، إذا نذر؛ يوفي، يبادر، وهكذا لو نذر أنه يحج؛ بادر بالحج، أو يعتمر؛ بادر بالاعتمار، وهكذا لو نذر أنه يصلي ركعتين، أربع ركعات، ست ركعات؛ بادر بذلك، يسلم من كل ثنتين، هذا هو السنة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11001/استحباب-المبادرة-في-الوفاء-بالنذر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_461/46107.mp3","categories":["الأيمان والنذور"]},{"id":12872,"question":"المستمع: محمد عبدالفتاح بعث برسالة يقول فيها: أنا متزوج منذ عشر سنوات، وعندي ثلاثة أولاد، قلت لزوجتي عندما سافرت: لا تذهبي لزيارة أهلك، وإذا ذهبت أنت محرمة، وقلتها ثلاث مرات، لم أعرف معناها جيدًا في ذلك الوقت، المهم في الأمر أنها ذهبت رغم ما قلت لها، أرجو إفادتي يا سماحة الشيخ عن الحكم، جزاكم الله خيرًا.","title":"حكم تحريم الزوجة","answer":"الجواب:  هذا يختلف بحسب النية، إن كنت أردت تحريمها إذا خرجت، أو طلاقها إذا خرجت؛ فإنها تحرم إذا خرجت، وعليك كفارة الظهار، عتق رقبة مؤمنة، فإن عجزت؛ تصوم شهرين متتابعين، فإن عجزت؛ تطعم ستين مسكينًا، ثلاثين صاعًا، كل مسكين له نصف الصاع من التمر، أو الأرز، أو غيرهما من قوت البلد. فأما إن كنت أردت الطلاق يقع طلقة واحدة، إذا أردت إيقاع الطلاق بخروجها، بهذا المعنى بقولك: محرمة إن أردت الطلاق فالأعمال بالنيات، يقع طلقة وتراجعها، تقول: قد راجعت زوجتي، وتشهد اثنين الأفضل من إخوانك الطيبين أنك راجعتها، إذا كنت ما طلقتها قبل ذلك طلقتين. فأما إن كنت ما أردت الطلاق، ولا التحريم، إنما أردت منعها، حين قلت: إن ذهبت أردت المنع فقط، ولم تقصد لا تحريمًا، ولا طلاقًا، إنما أردت منعها وتهديدها، فعليك كفارة يمين، ولا يقع شيء بخروجها على الصحيح من كلام أهل العلم؛ لأن هذا التعليق بهذه النية في حكم اليمين، إذا كان بنية المنع، أو التهديد، لا بنية الطلاق، ولا بنية التحريم، فهذا يكون في حكم اليمين بهذه النية، والرسول  قال: الأعمال بالنيات وأنت أعلم بنيتك، نسأل الله لنا ولك التوفيق، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11087/حكم-تحريم-الزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_466/46604.mp3","categories":["الظهار","الطلاق","الأيمان والنذور"]},{"id":12883,"question":"من سلطنة عمان هذه المستمعة: (ع. ع. ج) بعثت برسالة ضمنتها عددًا كبيرًا من الأسئلة، من بينها سؤال تقول فيه عن نفسها: إنها امرأة متزوجة، وعمرها ثلاثة وعشرون عامًا، ولديها طفل عمره ثلاث سنوات، ولقد حملت مرتين، وأنجبت بنتًا، ولقد حلفت بينها وبين نفسها أن تسمي ابنتها هدى، لكن والد زوجها غضب، وطلب أن يسمي البنت باسم أخته المتوفاة، فصمت ثلاثة أيام، ووزعت جونية أرزًا على الفقراء، هل يكفي هذا، أم توجهوني بشيء آخر جزاكم الله خيرًا؟","title":"صامت ثلاثة أيام ووزعت جونية على الفقراء هل يكفي كفارة؟","answer":"الجواب:  يكفي في كفارة اليمين إطعام عشرة مساكين، كل مسكين له نصف الصاع من التمر، أو من الرز، كيلو ونصف تقريبًا كل واحد، والجونية إذا كانت تبلغ هذا فهي كافية من الرز، أما الصيام فلا يجزي إلا في حق العاجز، الذي لا يستطيع الكفارة بالطعام، ولا بالكسوة، ولا بالعتق، إذا عجز عن هذه الثلاث؛ يصوم ثلاثة أيام، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11098/صامت-ثلاثة-ايام-ووزعت-جونية-على-الفقراء-هل-يكفي-كفارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_466/46615.mp3","categories":["الأيمان والنذور"]},{"id":12908,"question":"آخر سؤال له يقول: إذا نذرت لله  ثلاث مرات في مناسبات مختلفة، هل علي صيام تسعة أيام لهذه النذور الثلاثة، أم يكفي صيام ثلاثة أيام فقط عن هذه النذور المجتمعة؟ أفيدوني أفادكم الله، وشكرًا لكم.","title":"حكم النذر الذي لم يسم","answer":"الجواب:  النذر يختلف؛ فإذا قلت: لله علي نذر إن فعلت كذا، أو فعلت كذا، وفعلته؛ عليك كفارة يمين؛ لأنك ما سميت شيْئًا، ما قلت: أن أصوم، أو أتصدق بكذا، إذا كان النذر لم يسم فيه كفارة يمين، وإذا أتيت بنذر آخر، وقلت: لله علي نذر إن كلمت فلانًا غير نذرك الأول، وكلمته؛ عليك أيضًا كفارة يمين، وإن أتيت بنذر ثالث، قلت: لله علي نذر إن سافرت إلى كذا،، ثم سافرت؛ عليك كفارة يمين، لقول النبي ﷺ: كفارة النذر، كفارة اليمين إذا لم يسم كفارة النذر كفارة اليمين إذا لم يسم. أما إذا سميت قلت: لله علي أن أصوم ثلاثة أيام إن ولد لي ولد، لله علي أن أصوم عشرة أيام إن شفاني الله من كذا وكذا، فعليك أن تصوم إذا شفاك الله، لقول النبي ﷺ: من نذر أن يطيع الله؛ فليطعه، ومن نذر أن يعصي الله؛ فلا يعصه هكذا لو قلت: لله علي نذر أن أتصدق بمائة ريال، أو بألف ريال إن شفى الله ولدي، أو شفاني الله أنا، أو شفى الله أبي أو أمي، فحصل الشفاء؛ تصدق بما قلت، وهكذا ما أشبه ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11123/حكم-النذر-الذي-لم-يسم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_468/46810.mp3","categories":["الأيمان والنذور"]},{"id":12960,"question":"ننتقل إلى رسالة وصلت من مدينة بريدة السائل (ج. ر) يقول: ما هي كفارة الحلف اليمين؟ وهل العمال الذين يأتوننا من الخارج إلى بلادنا هل يعتبرون من الفقراء، أو المساكين؟ وما الفرق بين الفقير والمسكين؟الشيخ: نعم.المقدم: هذه الفقرة الأولى سماحة الشيخ تفضل.","title":"كفارة اليمين والفرق بين الفقير والمسكين","answer":"الجواب:  كفارة اليمين معروفة، بيَّنها الله في كتابه العظيم في سورة المائدة، قال -جل وعلا-: لا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِنْ يُؤَاخِذُكُمْ بِمَا عَقَّدْتُمُ الأَيْمَانَ فَكَفَّارَتُهُ إِطْعَامُ عَشَرَةِ مَسَاكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍ فَمَنْ لَمْ يَجِدْ فَصِيَامُ ثَلاثَةِ أَيَّامٍ ذَلِكَ كَفَّارَةُ أَيْمَانِكُمْ إِذَا حَلَفْتُمْ وَاحْفَظُوا أَيْمَانَكُمْ [المائدة:89] بيَّنها الرب  فكفارة اليمين إطعام عشرة مساكين، كل مسكين له نصف الصاع، تمر أو نحوه من قوت البلد، أو كسوة قميص، أو إزار ورداء لكل واحد، أو عتق رقبة عبد وإلا عبدة، فإن عجز عن الثلاث؛ يصوم ثلاثة أيام، هذه كفارة اليمين، نعم. المقدم: يقول: وهل العمال الذي يأتوننا من الخارج إلى بلادنا، هل يعتبرون من الفقراء، أو المساكين؟ وما الفرق بين الفقير والمسكين؟ الجواب: فيهم تفصيل: من عرف أنه فقير؛ يعطى من الزكاة، إذا كان مسلمًا؛ يعطى من الزكاة والصدقات إذا كان معاشه قليل، أو ما له معاش، ما تيسر له معاش، يعطى من الصدقات، سواء كان مسلمًا أو غير مسلم، لكن إن كان مسلمًا يعطى من الزكاة، وغير الزكاة، وإن كان غير مسلم وهو فقير يعطى من غير الزكاة أحوط، إلا إذا كان إنسانًا مؤلفًا له شأن إذا أعطي من الزكاة إذا أسلم؛ يسلم غيره فلا بأس أن يعطى من الزكاة؛ لأن الله جعل للمؤلفة قلوبهم حقًا في الزكاة، وهم الرؤساء والأعيان الذين يتبعهم غيرهم، هذا يعطى من الزكاة، أما أفراد الكفار، وعامة الكفار يعطون من غير الزكاة إذا كانوا محاويج فقراء. والفرق بين الفقير والمسكين، الفقير المعدم الذي ما عنده شيء بالكلية، أو شيء يسير، والمسكين، لا، عنده بعض الشيء لكن ليست عنده النفقة الكاملة، فالمسكين أحسن حالًا من الفقير. وإذا أطلق أحدهما دخل فيه الآخر، إذا قيل: الفقير دخل فيه المسكين، وإذا قيل: المسكين دخل فيه الفقير، فإذا جمع بين الفقير والمسكين مثلما في آية الزكاة: إِنَّمَا الصَّدَقَاتُ لِلْفُقَرَاءِ وَالْمَسَاكِينِ [التوبة:60] فالفقير المعدم الذي ما عنده شيء بالكلية، أو عنده شيء يسير، والمسكين الذي عنده بعض النفقة، عنده نصفها، أو ثلثاها، يعني: عنده شيء جيد منها، لكنه ما عنده الذي يكمل سنته، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11177/كفارة-اليمين-والفرق-بين-الفقير-والمسكين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_502/50216.mp3","categories":["الأيمان والنذور"]},{"id":13032,"question":"آخر سؤال له يقول: إني أقسمت بوضع يدي على كتاب الله أن أقلع عن معصية معينة، وأقلعت فعلًا، ولكن حدث وأن عدت مرة ثانية، سؤالي: هل علي كفارة؟ أرجو إفادتي جزاكم الله خيرًا.","title":"حكم من أقسم على ترك معصية ثم عاد إليها","answer":"الجواب:  عليك التوبة والكفارة جميعًا، التوبة إلى الله إذا كان معصية، إذا كان العمل معصية، وعليك كفارة -كفارة يمين- وهي إطعام عشرة مساكين، أو كسوتهم، إطعام عشرة تعشيهم، وإلا تغديهم، أو تدفع لهم نصف صاع من التمر، أو من الأرز، أو من الحنطة، ومعه إدام يكون أفضل، أو تكسوهم كسوة تجزئهم في الصلاة، كالقميص، أو إزار ورداء لكل واحد، أو تعتق رقبة إن قدرت، وإن عجزت عن الثلاثة تصوم ثلاثة أيام، هذه كفارة اليمين، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11249/حكم-من-اقسم-على-ترك-معصية-ثم-عاد-اليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_472/47212.mp3","categories":["الأيمان والنذور"]},{"id":13213,"question":"هذا السائل من جمهورية مصر العربية طنطا أحمد عبدالسلام يقول: ما هي اليمين الغموس؟ ولماذا سميت بذلك؟ وما هي الكفارة؟","title":"تعريف اليمين الغموس وسبب تسميتها بذلك","answer":"الجواب:  اليمين الغموس هي الكاذبة، التي قال فيها النبي ﷺ: من حلف على يمين صبر وهو فيها فاجر؛ لقي الله وهو عليه غضبان وفي اللفظ الآخر: من حلف على يمين صبر وهو فيها كاذب؛ أوجب الله له النار، وحرم عليه الجنة. فالواجب على المؤمن أن يحذر الكذب بالأيمان، وغير الأيمان، وإذا حلف على ذلك؛ صار الإثم أكثر، ولاسيما إذا اقتطع بها حق أخيه، كأن يحلف أن ما عنده لفلان شيء وهو عنده له مال، يحلف أنه ما أخذ منه شيئًا، وهو قد أخذ منه، هذا ظلم، كذب وظلم؛ ولهذا قال ﷺ: من حلف على يمين صبر يقتطع بها مال امرئ مسلم بغير حق؛ لقي الله وهو عليه غضبان وفي اللفظ الآخر: فقد أوجب الله له النار، وحرم عليه الجنة، قالوا: وإن كان شيئًا يسيرًا يا رسول الله؟ قال: وإن قضيبًا من أراك. فالواجب الحذر، يقال لها: اليمين الغموس؛ لأنها تغمس صاحبها في الإثم، ثم في النار، تغمسه في الإثم، والعصيان لله، ثم تغمسه في النار، فهي من أسباب دخول النار -نسأل الله العافية- نعم.","link":"https://binbaz.org.sa/fatwas/11486/تعريف-اليمين-الغموس-وسبب-تسميتها-بذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_520/52004.mp3","categories":["الأيمان والنذور"]},{"id":13253,"question":"السائلة (م) رمزت لاسمها بهذا الرمز من سلطنة عمان تقول: نذر أبي أن يزوج إحدى أخواتي لأحد أبناء أخيه المتوفى، ما رأيكم في هذا النذر؟ وهل يجوز؟ وما موقف أبي حينما يرفض ابن عمي؟ وما هي الكفارة في ذلك؟","title":"كفارة النذر","answer":"الجواب:  إن تيسر للوالد النذر، وافقت البنت والولد؛ فلا بأس، وإلا عليه كفارة اليمين، ولا ينبغي له النذر، لكن إذا نذر أنه يزوج فلانة ابن عمها فلانًا، ورضوا كلهم، ووافقوا؛ فالحمد لله. أما إذا أبوا، أبى الزوج، أو أبت المرأة؛ لا يجبر أحد، وعليه كفارة يمين عن نذره، كفارة النذر، كفارة يمين في مثل هذا النذر الذي يسمى، والنذر الذي بمعنى اليمين، مثل: أن ينذر أنه يعزم فلانًا، أو ينذر أنه يأكل طعام فلان، أو ينذر أنه يزوج فلانة، أو يزوج فلانًا، ولا يتيسر؛ فعليه كفارة يمين. نعم.","link":"https://binbaz.org.sa/fatwas/11538/كفارة-النذر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_513/51317.mp3","categories":["الأيمان والنذور"]},{"id":13262,"question":"تقول أختنا: عندما أحقق النجاح في أي مرحلة أقول: والله لأصومن ثلاثة أيام، إلا أني لم أفعل ذلك، فهل علي ذنب؟","title":"التحذير من كثرة الأيمان وبيان كفارة الحنث في اليمين","answer":"الجواب:  ينبغي عدم الإكثار من الأيمان، الله قال: وَاحْفَظُوا أَيْمَانَكُمْ [المائدة:89] فلا ينبغي الإكثار من الأيمان؛ لأنها عرضة لإهمالها، وعدم تنفيذ ما تضمنته، وعدم الكفارة، فينبغي للمؤمن والمؤمنة التحرز من ذلك، والحذر من الإكثار من الأيمان؛ لأن الله -جل وعلا- يقول: وَاحْفَظُوا أَيْمَانَكُمْ [المائدة: 89] وفي الحديث يقول ﷺ: ثلاثة لا يكلمهم الله، ولا ينظر إليهم يوم القيامة، ولا يزكيهم، ولهم عذاب أليم: أشيمط زاني يعني: شيبة زاني وعائل مستكبر، ورجل جعل الله بضاعته، لا يبيع إلا بيمينه، ولا يشتري إلا بيمينه يعني: يكثر من الأيمان. فينبغي الحذر من هذه الأيمان، ومتى وقع شيء من ذلك؛ فعليك إما الصوم، وإما الكفارة، إما أن تصومي ما قلت، وهذا أفضل، وإما أن تكفري كفارة يمين عن يمينك، وعليك أن تحسبي الأيمان، وتعديها، ثم تكفرين عن كل يمين كفارة، أو تصومين ما قلت، إما أن تصومي، وإما أن تكفري. وهكذا لو قال إنسان: والله لأكلمن فلانًا، ثم لم يكلمه في الوقت المحدد؛ يكفر كفارة يمين، أو والله لأصلين اليوم ركعتين، ولا صلى؛ كفارة يمين، أو قال: والله لأعودن فلانًا، مريض يعوده في محل له في المستشفى، ولم يعده في اليوم الذي حدد؛ عليه كفارة يمين، وهكذا. نعم. المقدم: جزاكم الله خيرًا، هل تتفضلون بتذكيرها بكفارة اليمين؟ الجواب: كفارة اليمين مثلما بين الله في سورة المائدة في آخرها، قال -جل وعلا-: لا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِنْ يُؤَاخِذُكُمْ بِمَا عَقَّدْتُمُ الأَيْمَانَ فَكَفَّارَتُهُ إِطْعَامُ عَشَرَةِ مَسَاكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍ فَمَنْ لَمْ يَجِدْ فَصِيَامُ ثَلاثَةِ أَيَّامٍ ذَلِكَ كَفَّارَةُ أَيْمَانِكُمْ إِذَا حَلَفْتُمْ وَاحْفَظُوا أَيْمَانَكُمْ كَذَلِكَ يُبَيِّنُ اللَّهُ لَكُمْ آيَاتِهِ لَعَلَّكُمْ تَشْكُرُونَ [المائدة:89] فأوضح سبحانه تفصيل الكفارة، وأوضح أيضًا ما ينبغي للمؤمن من حفظ اليمين، وأنه بين هذه الأمور ليشكره العباد، ويحمدوه، ويثنى عليه؛ لأنه بين لهم الأحكام التي تهمهم في أيمانهم، وحثهم على ما شرع لهم فيها؛ فليشكروه سبحانه على بيانه، وإيضاحه، وما تفضل به من الأحكام الذي جعلها كفارة للأيمان. فإطعام عشرة مساكين يعني: من قوت البلد، كل واحد يعطى نصف الصاع من قوت البلد، أو يعشى أو يغدى، وإذا جعل مع نصف الصاع من التمر، أو الرز، أو نحو ذلك شيئًا من الإدام؛ هذا حسن، أو يكسوهم كسوة تجزئهم في الصلاة، مثل القميص، أو إزار ورداء، أو يعتق رقبة مؤمنة من ذكر وأنثى، فإن لم يستطع هذه الأمور الثلاثة كلها؛ صام ثلاثة أيام، والأفضل أن تكون متتابعة، أما من قدر فإنه يخرج واحدة من هذه الثلاث، إما إطعام، وإما كسوة، وإما كسوة، وإما عتق. نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11547/التحذير-من-كثرة-الايمان-وبيان-كفارة-الحنث-في-اليمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_476/47606.mp3","categories":["الأيمان والنذور"]},{"id":13326,"question":"السائل الذي رمز لاسمه بـ (س. ع. د) يقول في هذا  سماحة الشيخ! أنا رجل فعلت مخالفات في أحد الأيام، وبعد ذلك ندمت، وحلفت، وقلت: حلفت، ونذرت أن أدفع مبلغًا من المال إلى الفقراء إن فعلت تلك المخالفة، وفعلتها فعلًا مرة أخرى، فهل علي دفع المال المذكور؟ أو يكفي كفارة يمين؟ وجزاكم الله عنا كل خير.","title":"ما يلزم من حلف ونذر ألا يعد لمعصية ثم عاد؟","answer":"الجواب: الواجب على كل مسلم ومسلمة إذا فعل شيئًا من المعاصي أن يبادر بالتوبة، هذا هو الواجب على كل مسلم البدار بالتوبة إذا فعل المعصية؛ لأن الله سبحانه يقول: وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَا الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ [النور:31] ويقول سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا تُوبُوا إِلَى اللَّهِ تَوْبَةً نَصُوحًا [التحريم:8] هذا هو الواجب على كل مسلم ومسلمة، إذا بدر منه ذنب؛ بادر بالتوبة، وسارع إليها.. شرب مسكرًا.. عقوق.. ربا.. زنا.. إلى غير هذا، متى وقعت منه المعصية؛ بادر، وسارع إلى التوبة، والندم، والإقلاع، والعزم ألا يعود، مع الإكثار من العمل الصالح، كما قال الله تعالى: وَإِنِّي لَغَفَّارٌ لِمَنْ تَابَ وَآمَنَ وَعَمِلَ صَالِحًا ثُمَّ اهْتَدَى [طه:82]. وإذا حلف، أو نذر إن رجع إليها أن يتصدق بكذا، أو يصلي كذا، أو يصوم كذا؛ فهذا فيه تفصيل؛ إن أراد بهذا القربة إلى الله، وأنه متى فعل، وعاد إليها؛ تاب، وتقرب إلى الله بهذا زيادة في التوبة؛ هذا يلزمه؛ لأن الرسول يقول ﷺ: من نذر أن يطيع الله؛ فليطعه، ومن نذر أن يعصي الله؛ فلا يعصه. نذر الطاعة يجب الوفاء به لهذا الحديث الصحيح: من نذر أن يطيع الله؛ فليطعه واجب. أما إذا كان أراد بهذا أن يردع نفسه حين قال: نذر علي إن عصيت أن أتصدق بكذا، أو أن أصوم شهرًا، أو كذا.. مقصوده يردع نفسه، يخوف نفسه حتى لا يلزمه الصوم والصدقة، ما قصده التقرب، إنما قصده أن يمنع نفسه من هذه المعصية، فإذا عاد إليها؛ فعليه التوبة، وعليه كفارة يمين عن نذره؛ لأنه ما أراد القربة بهذا، أراد أن يمنع نفسه، وأن يردعها عن هذا الشيء؛ فهذا يكون فيه كفارة يمين: إطعام عشرة مساكين، أو كسوتهم، أو عتق رقبة، فإن عجز صام ثلاثة أيام، وإطعام العشرة؛ يكون لكل واحد نصف الصاع -كيلو ونصف- من قوت البلد، أو كسوة قميص، أو إزار ورداء، هذا هو الواجب على من فعل هذا. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11612/ما-يلزم-من-حلف-ونذر-الا-يعد-لمعصية-ثم-عاد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_541/54108.mp3","categories":["الأيمان والنذور"]},{"id":13327,"question":"يقول السائل: هل من حلف عدة أيمان في أمر واحد، ولم يكفر؛ فهل يكفر لكل يمين كفارة بعدها؟ أم تكفي كفارة واحدة؟ وجزاكم الله خيرًا.","title":"كفارة من حلف عدة أيمان على أمر واحد","answer":"الجواب: إذا كان على أمر واحد تكفيه كفارة واحدة، فإذا قال: والله ما أكلم فلانًا، والله ما أكلمه، والله ما أكلمه، قالها مرات كثيرة، ثم كلمه، كفارة واحدة؛ لأنه فعل واحد، أو قال: والله ما أزور فلانًا، والله ما أزور فلانًا، والله ما أزور فلانًا، ثم زاره؛ كفارة واحدة. أما إذا كان على فعلين قال: والله ما أزور فلانًا، والله ما أكلم فلانًا، ثم كلم هذا، وزار هذا؛ كفارتان؛ لأن كل واحدة يمين مستقلة على فعل مستقل. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11613/كفارة-من-حلف-عدة-ايمان-على-امر-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_541/54109.mp3","categories":["الأيمان والنذور"]},{"id":13355,"question":"يقول في سؤاله الثاني سماحة الشيخ: ذهبت إلى أحد أصدقائي، وحلفت بالحرام بأن لا أجلس معه، في هذا الوقت، هو حلف أيضًا بالحرام بأن أجلس، وحلفنا في نفس الوقت، ماذا علينا أن نفعل؟","title":"حكم من حلف ألا يفعل وحلف عليه غيره أن يفعل","answer":"الجواب: الذي لم يتم أمره؛ عليه الكفارة، الحرام حكم اليمين، فإذا قال: علي الحرام ما أجلس، وذاك قال: علي الحرام أن تجلس، الذي ما حصل مطلوبه؛ عليه الكفارة منهما، مثل: عليه الحرام ما يأكل، والآخر يقول: علي الحرام أن تأكل، وهذا يقول: علي الحرام أن تقهوى، وهذا يقول: علي الحرام ما أتقهوى، الذي تمت يمينه ما عليه شيء، والذي ما تمت يمينه؛ عليه الكفارة.  فإذا قال: عليه الحرام ما يتقهوى، وتقهوى؛ عليه الكفارة، عليه الحرام، ما يتغدى، ثم تغدى؛ عليه الكفارة، وهكذا، وهي كفارة يمين، إطعام عشرة مساكين، أو كسوتهم، عشرة، كل مسكين له نصف صاع تمرًا، أو رزًا، حكمه حكم اليمين، أو حنطة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11641/حكم-من-حلف-الا-يفعل-وحلف-عليه-غيره-ان-يفعل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_523/52312.mp3","categories":["الأيمان والنذور"]},{"id":13403,"question":"السؤال الأخير لأختنا تقول: صمت ستة أيام كفارة يمينين، لكن الصيام لم يكن متتاليًا، فهل أعيد ما صمت؟ أم أن ما فعلت كان على الطريقة الصحيحة؟","title":"هل يجزئ من صامت كفارة اليمين غير متتابعة؟","answer":"الجواب: يجزئ -إن شاء الله- لكن التتابع أولى؛ لأن بعض الصحابة أفتى بالتتابع، وقرأ في قوله -جل وعلا-: فَصِيَامُ ثَلاثَةِ أَيَّامٍ [المائدة:89] قرأها (متتابعة) وهو ابن مسعود  فينبغي أن تصام متتابعة، ومن صامها متفرقة؛ نرجو أن تجزئه، لكنه ترك الأحوط، وإن قضيتيها احتياطًا متتابعة فلا بأس. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11696/هل-يجزى-من-صامت-كفارة-اليمين-غير-متتابعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_477/47707.mp3","categories":["الأيمان والنذور","قضايا المرأة"]},{"id":13473,"question":"من الجمهورية اليمنية هذه رسالة من إحدى الأخوات المستمعات من هناك تقول: أختكم في الله المستمعة (ج. ع) أختنا لها جمع من الأسئلة، من بينها سؤال يقول: إذا حلف الشخص ألا يعمل عملًا في الحاضر وعمله في المستقبل، فهل تجب عليه الكفارة؟","title":"اشتراط النية في اليمين","answer":"الجواب: هذا يرجع إلى نيته، فإذا قال: والله لا أكلم فلانًا، وقصده في هذا اليوم المعين، ثم كلمه بعد ذلك؛ فلا شيء عليه في المستقبل؛ لأنه إنما نوى اليوم الحاضر، وهكذا لو قال: والله لا أشتري السلعة الفلانية، قصده اليوم؛ فلا شيء عليه إذا اشتراها بعد ذلك. أما إذا قال: والله لا أكلمه، قصده أبدًا، أو قال: والله لا أشتري هذه السلعة أبدًا، هذا قصده، فإنه متى كلمه، أو اشتراها؛ وجبت عليه الكفارة، وهكذا ما يشابه ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11776/اشتراط-النية-في-اليمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_478/47802.mp3","categories":["الأيمان والنذور"]},{"id":13528,"question":"من أسئلة هذا السائل سماحة الشيخ عبدالعزيز يقول: ما حكم من صام بعد منتصف شعبان لصوم عليه قد نذر لله  أن يصومه؟","title":"حكم صيام النذر بعد النصف من شعبان","answer":"الجواب: إذا كان عليه صوم؛ فعليه أن يصوم في النصف الأول والنصف الأخير جميعًا، الذي عليه صوم نذر، أو من رمضان السابق عليه أن يقضيه، النهي فيمن يتطوع، الحديث الصحيح: إذا انتصف شعبان فلا تصوموا هذا في حق من يتطوع. أما الذي عليه دين .. عليه صوم من رمضان قضاء، أو عليه نذر، أو كفارة، هذا يصوم ولو في آخر شعبان؛ ولهذا في الحديث في الصحيحين يقول ﷺ: لا تقدموا رمضان بصوم يوم ولا يومين، إلا رجل كان عليه صوم فليصم إذا كان عليه صوم كفارة نذر، قضاء رمضان، هذا غير منهي، عليه أن يصوم قبل النصف، وبعد النصف. النهي إنما هو في حق من يتطوع، إذا انتصف شعبان ولم يصم قبل ذلك، لا يبتدئ الصوم بعد النصف، ولا عند دخول رمضان. نعم.","link":"https://binbaz.org.sa/fatwas/11867/حكم-صيام-النذر-بعد-النصف-من-شعبان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_532/53207.mp3","categories":["الأيمان والنذور"]},{"id":13604,"question":"لي خالة تصلي وتصوم، ولكنها تصدق بسبحة اليسر، وهذه السبحة يكتب عليها أسماء الله الحسنى، وكذلك تحلف بالرسول ﷺ وبعض المشايخ، وقبر أخيها، فهل مثل هذه الأشياء تمنعنا من زيارتها، أو الجلوس معها إذا زارتنا هي أيضًا؟","title":"حكم كتابة أسماء الله على حبات السبحة، والحلف بغير الله","answer":"الجواب: يجب أن تنصحوها، وأن تعلموها أن هذا لا يجوز، كونها تجعل في حبات السبحة أسماء الله؛ لأن هذا نوع امتهان لأسماء الله، فلا يجوز وضعها في حجرات السبحة، كذلك الحلف بالرسول ﷺ والحلف بقبر أخيها، أو بالمشايخ، كله لا يجوز، كله منكر، بل هو من المحرمات الشركية، يقول النبي ﷺ: من كان حالفًا؛ فليحلف بالله، أو ليصمت ويقول ﷺ: من حلف بشيء دون الله؛ فقد أشرك. فلا يجوز الحلف بغير الله كائنًا من كان، لا بالنبي ﷺ ولا بالكعبة، ولا بالأمانة، ولا بغير ذلك، فهذه المرأة تنصحونها، وتوجهونها إلى الخير، وتعلمونها ما شرع الله، وإذا لم تقنع؛ تطلبون من بعض أهل العلم أن يعلمها ذلك، بأن يكتب لها، أو يكلمها بالهاتف حتى تقلع؛ لأن المرأة الجاهلة تعلم، فأنتم تقنعونها، فإن أبت؛ تطلبون من بعض أهل العلم يقنعونها بالهاتف، أو بالكتابة؛ لعل الله يهديها، وتدع هذا المنكر. والتسبيح بالأصابع أولى من السبحة، كون الإنسان يسبح بأصابعه يهلل بأصابعه؛ هذا أفضل وأولى، ولكن لا يجوز أن يوضع في أحجار السبحة أسماء الله، ولا شيئًا من الآيات القرآنية، ولا ذكر الله -جل وعلا- لأن هذا يكون فيه امتهان بوضع الأسماء على هذه الحجرات. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11945/حكم-كتابة-اسماء-الله-على-حبات-السبحة-والحلف-بغير-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_480/48013.mp3","categories":["الأيمان والنذور","الحلف بغير الله"]},{"id":13637,"question":"هذا السائل مصري الحقيقة أرسل بمجموعة من الأسئلة، وكتب هذه الأسئلة بأسلوبه الخاص يقول: سماحة الشيخ! كنت في موقف صعب آخر السنة في الجامعة بالنسبة للنجاح والرسوب، فنذرت إذا نجحت بأن أصوم كل يوم خميس دائمًا، فنجحت -والحمد لله- وصمت عدة سنوات، ولكنني لم أستطع الاستمرار لعدة أسباب، وظروف، ومنها المرض، هل من حل؟ وهل يوجد كفارة؟ علمًا بأنني لا أستطيع الاستمرار على ذلك مستقبلًا، وجهوني يا سماحة الشيخ.","title":"حكم من نذر نذرًا وشق عليه الوفاء به","answer":"الجواب: الواجب عليك أن تستمر؛ لقول النبي ﷺ: من نذر أن يطيع الله؛ فليطعه هكذا قال ﷺ رواه البخاري في الصحيح من نذر أن يطيع الله؛ فليطعه، ومن نذر أن يعصي الله؛ فلا يعصه بل رواه مسلم في الصحيح. المقصود: أن عليك الوفاء بالنذر، فإذا عجزت عجزًا كاملًا لا تستطيع صيام نذر، ولا صيام رمضان، عجز مرة؛ فعليك كفارة يمين عن النذر المعجوز عنه، كما قال ابن عباس  ويروى مرفوعًا: من نذر نذرًا لا يطيقه؛ فكفارته كفارة يمين أما مادمت تستطيع رمضان؛ فعليك أن تصوم الخميس الذي نذرت، والله يقول -جل وعلا-: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] ويقول -جل وعلا-: يَا أَيُّهَا النَّاسُ اتَّقُوا رَبَّكُمُ [النساء:1] فمن نذر أن يطيع الله؛ فعليه أن يطيعه، وعليه أن يوفي بالنذر، ومن نذر أن يعصي الله؛ فلا يعصه. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11969/حكم-من-نذر-نذرا-وشق-عليه-الوفاء-به","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_528/52812.mp3","categories":["الأيمان والنذور"]},{"id":13842,"question":"هذا السائل الذي رمز لاسمه بـ (م. م. س) يقول: سماحة الشيخ! سؤالي بأنني أقسمت على ترك عادة التدخين وعدت إليها مرة ثانية، وأقسمت على ذلك أنني إن عدت إليها - أي عدت إلى التدخين مرة ثانية - سأصوم شهرين متتالين، ولم أستطع المقاومة على النفس في هذا الأمر وعدت إلى التدخين، فهل يترتب علي صيام شهرين؟ أو أنها كفارة يمين فقط، وهل يجوز أن أطعم مساكين عوضًا عن الصيام؟","title":"ما يجب على من أقسم ألا يعود للتدخين ثم عاد؟","answer":"الجواب: عليك التوبة إلى الله، وعليك الكفارة، عليك التوبة إلى الله بالعود إلى الدخان؛ لأنه محرم ومنكر خبيث، وعليك كفارة اليمين، إذا كان المقصود من الصيام أن تردع نفسك بالمنع فعليك كفارة يمين عندما عدت إليه وهي إطعام عشرة مساكين أو كسوتهم أو عتق رقبة، فإن لم تستطع تصوم ثلاثة أيام، هذه هي كفارة اليمين، والواجب عليك ترك التدخين فإنه محرم منكر وخبيث، فالواجب الحذر منه والتوبة إلى الله منه وعدم مجالسة أهله حتى لا يوقعوك فيه احذر مجالستهم واستعن بربك وأبشر بالخير إن شاء الله. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12214/ما-يجب-على-من-اقسم-الا-يعود-للتدخين-ثم-عاد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_537/53716.mp3","categories":["الأيمان والنذور"]},{"id":13860,"question":"يسأل أخونا من الزلفي فيقول: هل يجوز التذميم بقوله لأخيه: بذمتك أو بصلاتك أو بقوله: بحرج إن فعلت كذا، فمثل هذه العادات منتشرة عند النساء والأطفال، نرجو التوجيه جزاكم الله خيرًا.","title":"حكم الحلف بالذمة وغيرها","answer":"الجواب: لا يجوز الحلف لا بالصلاة ولا بالذمة ولا بالحرج ولا بغير ذلك من المخلوقات، الحلف يكون بالله وحده، فلا يقول: بذمتي ما فعلت كذا، ولا بذمة فلان، ولا بحياتي ولا بصلاتي، ولا أن يطالب يقال قل: بذمتي ولا قل: بصلاتي، ولا قل: بزكاتي، كل هذا لا أصل له ولا يجوز؛ لأن الصلاة فعل العباد، والزكاة فعل العباد، وأفعال العباد لا يحلف بها وإنما الحلف بالله وحده ، يقول النبي عليه الصلاة والسلام: من كان حالفًا فليحلف بالله أو ليصمت، ويقول عليه الصلاة والسلام: من حلف بشيء دون الله فقد أشرك خرجه الإمام أحمد بإسناد صحيح عن عمر ، وخرج أبو داود والترمذي بإسناد صحيح عن ابن عمر رضي الله تعالى عنهما عن النبي عليه الصلاة والسلام أنه قال: من حلف بغير الله فقد كفر أو أشرك وقال عليه الصلاة والسلام: من حلف بالأمانة فليس منا.\nفالواجب على كل مؤمن ومؤمنة أن يحذر ذلك وأن لا يحلف إلا بالله وحده  يقول: بالله ما فعلت كذا، والله ما فعلت كذا، إذا دعت الحاجة، والمشروع أن يحفظ يمينه ولا يحلف إلا عند الحاجة قال تعالى: وَاحْفَظُوا أَيْمَانَكُمْ [المائدة:89] لكن إذا دعت الحاجة يحلف يقول: والله ما فعلت كذا إذا كان صادقًا، والله ما ذهبت إلى فلان، بالله ما فعلت كذا، تالله ما فعلت كذا، إذا كان صادق هذا يمين بالله ، أما الحلف بغير ذلك بالأمانة أو بالنبي أو بالكعبة أو بحياة فلان أو شرف فلان أو صلاتي أو ذمتي فلا يجوز.\nأما إذا قال: في ذمتي ليس بيمين، هذا ليس بيمين في ذمتي يعني: هذا الشيء في ذمتي أمانة، أو ما أخون فيه أو ما أشبه ذلك هذا ليس يمينًا، أما إذا قال بذمتي أو بصلاتي أو بزكاتي أو حياتي أو حياة والدي هذا ما يجوز، هذا من الحلف بغير الله ، نسأل الله للجميع الهداية.\nالمقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12236/حكم-الحلف-بالذمة-وغيرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_603/60307.mp3","categories":["الطلاق","الأيمان والنذور","الحلف بغير الله"]},{"id":13921,"question":"السائلة أختكم في الله (هـ. س) من مكة المكرمة تقول: هل يجوز الفصل بين صيام الكفارة لليمين الثلاثة أيام؟","title":"حكم الفصل بين صيام أيام كفارة اليمين","answer":"الجواب: الأفضل المتابعة، وإن فصل فلا حرج، لكن الأفضل أن يصومها متتابعة، كما قاله جماعة من السلف كـابن مسعود وغيره، ولو صامها متفرقة أجزأت على الصحيح. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12328/حكم-الفصل-بين-صيام-ايام-كفارة-اليمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_544/54414.mp3","categories":["الأيمان والنذور"]},{"id":13934,"question":"يقول: حلفت يمين أن أترك الدخان، وتركته فترة معينة إلا أنني رجعت ما حكم ما فعلت؟ وماذا أفعل إذا كان علي كفارة؟ جزاكم الله خيرًا.","title":"حكم من حلف على ترك الدخان ثم عاد إليه","answer":"الجواب: عليك التوبة إلى الله؛ لأن الدخان محرم خبيث ومضاره كثيرة، فعليك التوبة إلى الله جل وعلا وأن تحذر مجالسة المدخنين، فإن مجالستهم من أسباب رجوعك إليه. وعليك كفارة اليمين عن يمينك وهي إطعام عشرة مساكين أو كسوتهم أو عتق رقبة، فإن كنت فقير لا تستطيع عاجز عن الطعام والكسوة والعتق فإنك تصوم ثلاثة أيام هذه كفارة اليمين، قال الله سبحانه: لا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِنْ يُؤَاخِذُكُمْ بِمَا عَقَّدْتُمُ الأَيْمَانَ فَكَفَّارَتُهُ إِطْعَامُ عَشَرَةِ مَسَاكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍ فَمَنْ لَمْ يَجِدْ فَصِيَامُ ثَلاثَةِ أَيَّامٍ ذَلِكَ كَفَّارَةُ أَيْمَانِكُمْ إِذَا حَلَفْتُمْ وَاحْفَظُوا أَيْمَانَكُمْ [المائدة:89] الآية في سورة المائدة، فالرب جل وعلا يأمرنا بالكفارة من أوسط الطعام أو كسوة أو عتق رقبة، فإن عجز الحالف صام ثلاثة أيام، وأمر بحفظ الأيمان، وأنه لا ينبغي للإنسان أن يحلف إلا عند الحاجة. والدخان شره كثير، فينبغي لك يا عبد الله! أيها السائل! أن تحذره وأن تستمر في تركه، وألا تجالس أهله، وأن تنصحهم لعل الله يهديك ويهدي بك، بارك الله فيك. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12333/حكم-من-حلف-على-ترك-الدخان-ثم-عاد-اليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_482/48209.mp3","categories":["الطلاق","الأيمان والنذور","نصائح وتوجيهات"]},{"id":13978,"question":"نعود في بداية هذه الحلقة إلى رسالة المستمع رياض بن داري القدري من جدة، أخونا عرضنا جزءًا من أسئلته في حلقة مضت، وفي هذه الحلقة يسأل ويقول: هل تجوز الكفارة عن حلف اليمين بالله بدفع مبلغ من المال لشخص أو أكثر من فقراء المسلمين، بدلًا من إطعام عشرة مساكين، وما قيمة هذا المبلغ؟","title":"حكم دفع كفارة اليمين نقودًا لشخص أو أكثر","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فكفارة اليمين قد نص الله عليها في كتابه الكريم، فليس لأحد أن يخالف نص كتاب الله ، يقول الله سبحانه: لا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِنْ يُؤَاخِذُكُمْ بِمَا عَقَّدْتُمُ الأَيْمَانَ فَكَفَّارَتُهُ إِطْعَامُ عَشَرَةِ مَسَاكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍ فَمَنْ لَمْ يَجِدْ فَصِيَامُ ثَلاثَةِ أَيَّامٍ ذَلِكَ كَفَّارَةُ أَيْمَانِكُمْ إِذَا حَلَفْتُمْ وَاحْفَظُوا أَيْمَانَكُمْ [المائدة:89].. الآية. فالله  أوضح الكفارة، وبينها ونوعها؛ فليس لأحد أن يخالف ذلك، فلا يجزي أن تقدم لمسكين طعامًا أو نقودًا أو غير ذلك، بل لا بد من عشرة، كما نص الله على ذلك، عشرة فقراء يعطون طعامًا قدره نصف صاع لكل واحد، كيلو ونصف تقريبًا، من قوت البلد من تمر أو رز أو حنطة أو غير ذلك من قوت البلد، أو يدعون لطعام الغداء أو العشاء مجتمعين أو متفرقين حتى تكمل العشرة، أو تكسوهم كسوة لكل واحد ما يكفيه في الصلاة، كإزار ورداء أو قميص، أو تعتق رقبة مؤمنة، فإن لم تستطع هذه كلها؛ فعليك أن تصوم ثلاثة أيام.\nهذه هي الكفارة التي نص الله عليها جل وعلا، وليس لأحد أن يخالف ذلك، ولو .. أطعمهم مفرقين على خمسة اليوم وخمسة غدًا، أربعة اليوم وستة غدًا، ثلاثة اليوم وثلاثة غدًا وثلاثة بعد غد، أو أربعة، كل هذا لا بأس به، ليس من شرط هذا أن يجتمعوا، ولو فرق ذلك بين بيتين أو ثلاثة، بيت فيه أربعة، وبيت فيه أربعة، وبيت فيه اثنان لا بأس، الحاصل أنه لابد من عشرة في الطعام والكسوة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12389/حكم-دفع-كفارة-اليمين-نقودا-لشخص-او-اكثر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_606/60601.mp3","categories":["الأيمان والنذور"]},{"id":14012,"question":"المستمع (د. م) سوداني مقيم في المملكة يقول: لدى بعض دلالي الأغنام في السودان عادة سيئة، وهي كثرة الحلف بالطلاق لترويج أغنامهم، وبعضهم متزوج وقد يكون ما حلف عليه بالطلاق مخالف للواقع، ما حكم هذا الحلف؟ وهل يقع الطلاق فعلًا؟ وهل هناك كفارة؟ وجهوهم شيخ عبد العزيز، جزاكم الله خيرًا.","title":"حكم ترويج البضاعة بالحلف بالطلاق","answer":"الجواب: هذا عمل لا يجوز لا بالطلاق ولا بغير الطلاق، ليس له أن يروج بضاعته بالأيمان لا بالأيمان بالله ولا بالطلاق كل ذلك لا يجوز؛ لأن هذا تغرير للناس وخداع للناس وربما كذب في ذلك، فإن من أكثر الأيمان يغلب عليه الكذب، ثم إنه يخدع الناس، قد يكون كاذبًا في ذلك ويخدع الناس بأيمانه حتى يشتروا سلعته، وإن كانت رديئة أو يشتروها بأكثر من ثمنها لكثرة أيمانه.\nوقد جاء في الحديث عنه عليه الصلاة والسلام أنه قال: ثلاثة لا يكلمهم الله ولا ينظر إليهم يوم القيامة ولا يزكيهم ولهم عذاب أليم: أشيمط زاني يعني: شائب زاني وعائل مستكبر يعني: فقير ومستكبر ورجل جعل الله بضاعته لا يشتري إلا بيمينه ولا يبيع إلا بيمينه. فكثرة الحلف في البيع والشراء أمر منكر وخطير، ومن أسباب غضب الله ، فينبغي للمؤمن أن يحذر ذلك وأن لا يكثر الأيمان، فإن دعت الحاجة إلى اليمين فليكن صادقًا من غير إكثار، فإن اتهموه بأنه غاش في كذا أو غاش في كذا وهو ليس بغاش بل صادق وحلف لهم يمينًا بالله أنه صادق فلا بأس بذلك عند الحاجة، أما إكثار الأيمان بالطلاق أو بالله فهذا لا يجوز، وهو من أسباب الكذب، ومن أسباب الخداع والغش، وإذا كان صادقًا في طلاقه لا يقع شيء، لكن لا ينبغي له استعمال ذلك؛ لأنه وسيلة إلى وقوع الباطل ووسيلة إلى الطلاق الكاذب، وسيلة إلى فراق أهله، فينبغي للمؤمن أن يحذر ذلك، وأن يعتاد الصدق مع قلة الأيمان والمحافظة عليها، والله يقول سبحانه: وَاحْفَظُوا أَيْمَانَكُمْ[المائدة:89]. والإكثار من الأيمان من أسباب الكذب، من أسباب الوقوع في الكذب، ومن أسباب غش الناس وخديعة الناس، فالواجب الحذر من ذلك. وإذا كان في يمينه صادقًا أو في طلاقه صادقًا فلا شيء عليه لكن لا ينبغي له الإكثار من ذلك، بل يكون عند الحاجة مع القلة والعناية بعدم الكثرة حتى يسلم من الوعيد الشديد ومن غضب الله ، أما الكاذب هذا فيه وعيد الكذب -نسأل الله العافية-، وهو على خطر عظيم من الوعيد في كذبه في أيمانه وفي طلاقه، ويقول النبي ﷺ: من حلف على يمين وهو فيها كاذب لقي الله وهو عليه غضبان نسأل الله العافية.  فالواجب على المؤمن أن يحذر، وإذا كان كاذبًا، فقد ذهب أكثر أهل العلم إلى أنه يقع الطلاق نسأل الله العافية، والصواب أنه لا يقع الطلاق؛ لكنه لا يجوز له إذا كان قصده في يمينه أن يصدق في ذلك، وأن تقبل سلعته، وأن يأمنه الناس في ذلك فهو في ذلك مجرم إذا كان كاذبًا، ولكن ليس قصده إيقاع الطلاق وإنما قصده أن يصدقه الناس وأن يقبلوا سلعته، فهو على كل حال في هذا ظالم ومجرم ولا يجوز له فعله، وأما وقوع الطلاق لا يقع؛ لأن قصده تصديقه وليس قصده إيقاع الطلاق فيكون كفارة يمين في أصح قولي العلماء، لكن لا يجوز له تعاطي ذلك بل يجب عليه الحذر من ذلك؛ لئلا يوهم الناس ولئلا يخدع الناس، ولأن الكذب محرم مطلقًا. نعم.\nالمقدم: جزاكم الله خيرًا، ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/12433/حكم-ترويج-البضاعة-بالحلف-بالطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_611/61103.mp3","categories":["الأيمان والنذور","البيوع"]},{"id":14039,"question":"يسأل أخونا عن حكم الدين في الذي يكثر الحلف بالطلاق، وهل يجوز رد الطلاق؟","title":"حكم من يكثر الحلف بالطلاق، وهل يقع طلاقه؟","answer":"الجواب: لا ينبغي للمؤمن أن يكثر من ذلك، بل يكره له ذلك، ينبغي له حفظ لسانه، الطلاق أبغض الحلال إلى الله الطلاق، فينبغي للمؤمن أن يتثبت في الأمور، ويحرص على حفظ اللسان عن كل ما لا ينبغي، ومن ذلك الطلاق، فلا ينبغي له أن يطلق إلا عن بصيرة وعن نظر وعن عناية، فإذا ظهرت المصلحة والفائدة في الطلاق؛ طلق طلقة واحدة فقط، لا زيادة؛ لأنه قد يندم، فيراجع زوجته والحمد لله.\nالمقصود: أن الإكثار من الحلف بالطلاق خطر، وهو يفضي إلى وقوع الطلاق، فإنه قد يحلف بالطلاق ناويًا وقوع الطلاق؛ فيقع، إذا فعل ما حلف على تركه، أو ترك ما حلف على فعله، أما إذا كان إنما أراد التهديد والتخويف، كأن يقول: إن كلمت فلانًا؛ فأنت طالق، أو إن ذهبت إلى فلان؛ فأنت طالق من باب التخويف والتحذير، وليس قصده إيقاع الطلاق؛ فهذا عند المحققين من أهل العلم فيه كفارة يمين، ولا يقع به الطلاق.\nهذا هو الصواب الذي اختاره جمع من أهل العلم؛ لأنه لم يرد الطلاق، وإنما أراد التهديد والتخويف والتهديد.\nولكن بكل حال ينبغي له ترك ذلك، والحذر من اعتياد الطلاق، وأن يكون في لسانه؛ لأنه قد يوقعه بالقصد، ولأن بعض أهل العلم يراه يقع وإن كان قصد التهديد والتأكيد؛ فينبغي الحذر من ذلك، وينبغي تجنب ذلك احتياطًا لدينه واحتياطًا لما يجب عليه من حفظ الفرج، والبعد عن شبهة الحرام.\nوإذا طلق فيطلق عن بصيرة، لا بالغضب والعجلة، بل يتحرى وينظر، فإذا رأى المصلحة في الطلاق؛ لأنها سيئة الأخلاق.. سيئة السيرة.. ضعيفة الدين؛ إذا رأى المصلحة في ذلك طلق طلقة واحدة، في طهر لم يجامع فيه أو في حال الحمل، هذا السنة، أن يكون الطلاق في حالين: إحداهما: حال الحمل، والثانية: أن تكون المرأة في طهر لم يجامعها فيه، هذا هو محل الطلاق الشرعي.\nأما الطلاق في الحيض أو في النفاس أو في طهر جامع فيه، فهو طلاق بدعي، مخالف لقوله تعالى: يا أيها النَّبِيُّ إِذَا طَلَّقْتُمُ النِّسَاءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ [الطلاق:1]، بين النبي ﷺ في حديث ابن عمر أن طلاقها في العدة أن تكون طاهرة، من دون جماع أو حاملا.\nفينبغي لأهل الإسلام، ينبغي لكل مسلم أن يتحرى هذه الأمور، وأن يحافظ على السنة، وأن يحذر طاعة الشيطان في طلاقه على وجه غير شرعي، وأن يحذر العجلة في إيقاع الطلاق الثلاث.\nبل يجب أن يراعي ما شرع الله، وأن يحذر ما حرم الله، في طلاقه وفي سائر شئونه، المؤمن عبد مأمور، له شريعة إسلامية يجب أن يلتزم بها في كل شيء، وأن يتحرى ما أحل الله له في كل شيء، وأن يحذر ما حرم الله عليه، وليس له التساهل في كل شيء، بل يجب الحذر، وأن تكون أعماله وأقواله مقيدة بالشريعة، رزق الله الجميع التوفيق والهداية.\nالمقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12467/حكم-من-يكثر-الحلف-بالطلاق-وهل-يقع-طلاقه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_607/60708.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":14070,"question":"حلفت يومًا نتيجة زعل أن لا أصل الزوجة إلا بعد كذا يوم، وقد وصلتها قبل إتمام المدة، ما هو توجيهكم؟","title":"حكم من حلف على عدم فعل شيء ثم فعله","answer":"الجواب: عليه كفارة يمين، كما تقدم في السؤال اللي قبلك، عليه كفارة يمين، إذا حلف الإنسان على شيء مستقبل، مثل: والله لا أصل زوجتي يومين أو ثلاث، أو والله لا أجامعها يومين أو ثلاث، أو والله لا أكلمها، ثم خالف يمينه؛ فإن عليه كفارة اليمين، وهي: إطعام عشرة مساكين، أو كسوتهم، أو عتق رقبة، فمن عجز فعليه صيام ثلاثة أيام، والمعنى: أنه يكفر بإطعام عشرة مساكين، يعني: يعشيهم أو يغديهم، عشرة فقراء، أو يدفع إليهم طعامًا، كل واحد يعطى نصف صاع، يعني: كيلو ونصف تقريبًا من التمر أو الأرز أو الحنطة، أو غيره من قوت البلد، أو يكسوهم كسوة تجزئهم في الصلاة: كالقميص، أو إزار ورداء، ونحو ذلك، أو يعتق رقبة مؤمنة، فإن عجز عن هذي الثلاث؛ فإنه يصوم ثلاثة أيام، هذه هي الكفارة، كما نص الله عليها في كتابه العظيم في سورة المائدة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12507/حكم-من-حلف-على-عدم-فعل-شيء-ثم-فعله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_609/60904.mp3","categories":["الأيمان والنذور"]},{"id":14075,"question":"من اليمن هذه رسالة بعث بها المستمع (أ. ع. ع. أ) سوداني مقيم في اليمن، أخونا له أربعة أسئلة.في سؤاله الأول يقول: لي أخ مستخرج جواز سفر، وأراد استخراج واحد آخر، وفي أثناء التحري قال له المتحري: أتحلف أن ليس لك جواز سابق، وكان لم ير مصحفًا أمام المتحري، ثم أخرجه المتحري، وقد خاف الأخ وحلف على أنه لم يستخرج جواز سفر آخر، أفيدونا عن حكم ذلك، وهل عليه ذنب؟ وهل تجزئ الكفارة؟","title":"ما الواجب على من حلف كاذبًا؟","answer":"الجواب: عليه التوبة إلى الله سبحانه؛ لأنه كاذب، والكاذب عليه التوبة إلى الله ، والصدق في ذلك والندم وعدم العود إلى ذلك، وليس في اليمين الكاذبة كفارة على الصحيح، الكفارات في الأيمان على المستقبل إذا خالف، مثل يقول: والله ما أفعل كذا، والله لأكلمن فلانًا.\nفالأيمان التي فيها الكفارة هي التي على الأشياء المستقبلة، أما الكذاب فعليه التوبة فقط، يتوب إلى الله وينيب إليه، ويندم على ما مضى منه، ويعزم عزمًا صادقًا أن لا يعود في ذلك، وبذلك يمحو الله عنه الذنب، فإن التوبة تمحو الذنوب، يمحو الله بها الذنوب، كما قال النبي ﷺ: التائب من الذنب كمن لا ذنب له، والله يقول سبحانه: وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَا الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ [النور:31]. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12505/ما-الواجب-على-من-حلف-كاذبا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_609/60903.mp3","categories":["الأيمان والنذور"]},{"id":14077,"question":"حلفت يومًا نتيجة زعل أن لا أصل الزوجة إلا بعد كذا يوم، وقد وصلتها قبل إتمام المدة، ما هو توجيهكم؟","title":"حكم من حلف على عدم فعل شيء ثم فعله","answer":"الجواب: عليه كفارة يمين، كما تقدم في السؤال اللي قبلك، عليه كفارة يمين، إذا حلف الإنسان على شيء مستقبل، مثل: والله لا أصل زوجتي يومين أو ثلاث، أو والله لا أجامعها يومين أو ثلاث، أو والله لا أكلمها، ثم خالف يمينه؛ فإن عليه كفارة اليمين، وهي: إطعام عشرة مساكين، أو كسوتهم، أو عتق رقبة، فمن عجز فعليه صيام ثلاثة أيام، والمعنى: أنه يكفر بإطعام عشرة مساكين، يعني: يعشيهم أو يغديهم، عشرة فقراء، أو يدفع إليهم طعامًا، كل واحد يعطى نصف صاع، يعني: كيلو ونصف تقريبًا من التمر أو الأرز أو الحنطة، أو غيره من قوت البلد، أو يكسوهم كسوة تجزئهم في الصلاة: كالقميص، أو إزار ورداء، ونحو ذلك، أو يعتق رقبة مؤمنة، فإن عجز عن هذي الثلاث؛ فإنه يصوم ثلاثة أيام، هذه هي الكفارة، كما نص الله عليها في كتابه العظيم في سورة المائدة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12507/حكم-من-حلف-على-عدم-فعل-شيء-ثم-فعله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_609/60904.mp3","categories":["الأيمان والنذور"]},{"id":14152,"question":"هذه رسالة الحقيقة أرسل بها أحد الإخوة لم يذكر الاسم في هذه الرسالة يقول في هذا  هل يجوز الحلف بكتاب الله؟","title":"حكم الحلف بكتاب الله","answer":"الجواب: نعم؛ لأن القرآن كلام الله، فإذا قال: وكتاب الله، يقصد القرآن، أو وكلام الله، أو وعزة الله، فلا بأس؛ لأن الله جل وعلا يحلف به وبصفاته كما قال ﷺ: من كان حالفًا فليحلف بالله أو ليصمت فمن حلف بالله أو بصفة من صفاته فقد حلف بالله، بعزة الله، بعلم بالله، بكلام الله، بكتاب الله، كل هذا ......\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12593/حكم-الحلف-بكتاب-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_546/54617.mp3","categories":["الأيمان والنذور"]},{"id":14267,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من جمهورية مصر العربية وباعثها مستمع من هناك يقول: سامي محمد خليفة، الأخ سامي يقول في رسالة بعث بها إنه في ساعة غضب أقسم على المصحف الشريف ألا يسكن في هذا المنزل أو الحوش وعندما زال الغضب وجد أنه مخطئ إذ لا غنى له عن هذا المنزل، فسأل بعض الناس فأخبروه بأن عليه أن يصوم ثلاثة أيام، فصام ثلاثة أيام وعاد إلى المنزل، فهل هذا صحيح أم لا؟!","title":"حكم القسم على المصحف والكفارة الحنث في ذلك","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فإذا حلف الإنسان على أنه لا يسكن في هذا المكان أو لا يكلم فلانًا أو لا يأكل كذا أو ما أشبه ذلك سواءً على المصحف أو على غير المصحف ثم أحب أن يفعل ذلك أو فعله لأسباب دعت إلى ذلك فإنه يكفر كفارة يمين ولا شيء عليه، إذا كان المفعول مباحًا شرعًا، مثل: سكنى المنزل، أو أكل طعام فلان المباح، أو تكليم فلان اللي لا بأس بكلامه؛ لأن النبي ﷺ قال: إذا حلفت على يمين فرأيت غيرها خيرًا منها فكفر عن يمينك وائت الذي هو خير.\nوالله بين كفارة اليمين في كتابه العظيم فقال : لا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِنْ يُؤَاخِذُكُمْ بِمَا عَقَّدْتُمُ الأَيْمَانَ فَكَفَّارَتُهُ إِطْعَامُ عَشَرَةِ مَسَاكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍ فَمَنْ لَمْ يَجِدْ فَصِيَامُ ثَلاثَةِ أَيَّامٍ ذَلِكَ كَفَّارَةُ أَيْمَانِكُمْ إِذَا حَلَفْتُمْ وَاحْفَظُوا أَيْمَانَكُمْ [المائدة:89]، الآية في سورة المائدة، هذه كفارة اليمين، إطعام عشرة مساكين، أو كسوتهم، أو تحرير رقبة، يعني: عتق رقبة، فإن عجز ولم يستطع صام ثلاثة أيام.\nفالسائل صام ثلاثة أيام ولا ندري هل هو عاجز أم لا، فإذا كان عاجزًا لا يستطيع إطعام عشرة مساكين ولا يستطيع كسوتهم ولا عتق رقبة أجزأه الصيام، وإلا فعليه أن يطعم عشرة مساكين ولا يجزئه الصيام، إذا كان يستطيع يعطي كل واحد نصف صاع من تمر أو أرز أو بر، يعني: بصاع النبي ﷺ ومقداره كيلو ونص تقريبًا، فإذا كان يستطيع ذلك فالصيام لا يجزئه، أو يكسوه كسوة يعطي كل واحد قميصًا أو إزارًا ورداءً، يعني: كسوة تجزئه في الصلاة. نعم.\nالمقدم: جزاكم الله خيرًا، إذًا: كفارة اليمين ليست على التخيير؟!\nالشيخ: في الثلاثة مخير، إطعام عشرة مساكين، أو كسوتهم، أو تحرير رقبة، أحد هذه الثلاثة، فإن عجز عنها كلها انتقل إلى الصيام.\nثم الحلف بالمصحف ليس له أصل فلا حاجة إلى الحلف على المصحف، إذا قال: والله لا أفعل كفى، ولا حاجة إلى أن يأتي بالمصحف ولا دليل على شرعية ذلك، فالأولى عدم الحاجة إلى الحلف على المصحف ولو أكد يمينه يقول: والله ما أفعل كذا، والله العظيم ما أفعل كذا، ويكفي، والله لا أزور فلان، والله لا أكلم فلان، المقصود: ليس هناك حاجة إلى إحضار المصحف وإنما هذا شيء يفعله الناس من باب التشديد على أنفسهم بدون دليل. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12726/حكم-القسم-على-المصحف-والكفارة-الحنث-في-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_621/62101.mp3","categories":["الأيمان والنذور","الحلف بغير الله"]},{"id":14293,"question":"تقول السائلة: هل ممكن أن أخرج الكفارة على شكل أموال بدلًا من إطعام المساكين، أي: أقدم طعامًا للمساكين؟","title":"وجوب أداء الكفارات كما شرع الله","answer":"الجواب: الكفارة تختلف: كفارة اليمين عشرة مساكين كل واحد له نصف الصاع كيلو ونص، وكفارة الظهار ستين مسكينًا، كفارة الجماع في رمضان ستين مسكينًا لمن عجز عن العتق والصيام، فلابد من إخراج الكفارة كما شرع الله، إن كان في جماع رمضان أو في الظهار تحريم الزوجة هذا الواجب فيه عتق رقبة، فإن عجز صام شهرين متتابعين، فإن عجز أطعم ستين مسكينًا قبل أن يمسها في الظهار، وإذا جامع في رمضان عليه كفارة هو والمرأة جميعًا عتق رقبة فإن عجز صام شهرين متتابعين وهي كذلك، فإن عجزا أطعما ستين مسكينًا هو يطعم ستين مسكينًا وهي كذلك، كل واحد له نصف الصاع، ستين صاعًا عنهما جميعًا بين ستين مسكينًا كل مسكين له صاع نصفه عن الزوج ونصفه عن الزوجة، إذا عجزا عن العتق والصيام. نعم.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12753/وجوب-اداء-الكفارات-كما-شرع-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_549/54922.mp3","categories":["الأيمان والنذور"]},{"id":14305,"question":"رسالة وصلت إلى البرنامج من الدوحة قطر باعث الرسالة مستمع من هناك يقول: (ع. ن. ف) يسأل ويقول: تشاجرت مع ابن عمتي والسبب قوله: إنك قلت لأهلي كذا وكذا، وأنا لا أعرف هل قلت هذا الكلام أم لا، وقلت: تحرم علي زوجتي بأني لم أقل هذا الكلام، وبعد ذهابه بدأت أفكر هل زوجتي حلال أم طالق، برغم أنني لا أعرف هل أنا قلت الكلام الذي ذكره ابن عمتي أم لم أقل، واليوم أنا في حيرة، أرشدوني جزاكم الله خير الجزاء.","title":"حكم من حلف بالطلاق أو الحرام على ما يَشُك فيه","answer":"الجواب: إذا كنت قلت ذلك لقصد أن يسمح عنك وأن يصدقك ولم ترد تحريم أهلك ولا طلاق أهلك وإنما قلت ذلك ليصدقك وليعذرك وينتهي النزاع بينكما فليس عليك طلاق ولا تحريم، ولكن عليك الكفارة كفارة اليمين، وهي إطعام عشرة مساكين أو كسوتهم، أو تحرير رقبة، هذا هو الواجب في مثل هذا في أصح قولي العلماء أن التحريم والطلاق إذا كان المقصود منه الحث أو المنع أو التصديق أو التكذيب وليس القصد تحريم الزوجة ولا طلاقها وإنما أراد المطلق أو المحرم تصديق أخيه أو منعه من كذا أو الحث على كذا تلزمه كفارة يمين، فإذا كنت أردت بذلك أن يصدقك وأن ينتهي النزاع وأن ترضيه بما قلت. وإن كنت لا تعلم الواقع فأنت في هذا عليك كفارة اليمين فقط ولا يقع الطلاق ولا يقع التحريم. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12794/حكم-من-حلف-بالطلاق-او-الحرام-على-ما-يشك-فيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_622/62207.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":14312,"question":"المستمع (م. ح. م) من اليمن ومقيم في مدينة الخبر بعث برسالة ضمنها عددًا من الأسئلة فيقول: منذ حوالي ست عشرة سنة تزوجت وبعد سنة رزقنا الله بولد، ودار نقاش بيني وبين زوجتي حول الولد، ومن فرحتي به قلت لها لأطيب خاطرها: يحرمن علي الحريم من بعدك، أقصد أنني لن أتزوج بعدها، وبعد سنة واحدة توفيت ومكثت سبع سنين بدون زواج، بعدها تزوجت أختها والآن صار عندي ثلاثة أولاد منها، هل علي أثم بما تلفظت به سابقًا؟ وهل النساء يحرمن علي بعدها؟ وهل علي كفارة أم ماذا؟ أفيدوني أفادكم الله.","title":"حكم من حلف بالحرام أن لا يتزوج ثم تزوج","answer":"الجواب: لا يجوز للمسلم أن يحرم ما أحل الله له، لا النساء، ولا الطعام، ولا اللباس، ولا غير ذلك؛ لأن الله يقول سبحانه لنبيه ﷺ: يَا أَيُّهَا النَّبِيُّ لِمَ تُحَرِّمُ مَا أَحَلَّ اللَّهُ لَكَ [التحريم:1]، فليس لك ولا لغيرك تحريم ما أحل الله ، وعليك عما قلت كفارة اليمين، وهي إطعام عشرة مساكين أو كسوتهم أو عتق رقبة، هذا هو الواجب عليك، وقد تزوجت والحمد لله فعليك هذه الكفارة، إطعام عشرة مساكين كل مسكين له نصف الصاع من التمر أو غيره من قوت البلد كالأرز والبر، ومقدار ذلك كيلو ونص تقريبًا بالوزن، تدفعها إلى عشرة من الفقراء، كل واحد يعطى نصف صاع، يعني: كيلو ونص تقريبًا، لكل واحد من الفقراء العشرة من البر أو الشعير أو التمر أو الأرز كفارة لما قلت: يحرم علي النساء بعدك، فهذه هي الكفارة مع التوبة والاستغفار عما صدر منك. والله ولي التوفيق.","link":"https://binbaz.org.sa/fatwas/12807/حكم-من-حلف-بالحرام-ان-لا-يتزوج-ثم-تزوج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_622/62212.mp3","categories":["الأيمان والنذور"]},{"id":14315,"question":"المستمع (م. ح. م) من اليمن ومقيم في مدينة الخبر بعث برسالة ضمنها عددًا من الأسئلة فيقول: منذ حوالي ست عشرة سنة تزوجت وبعد سنة رزقنا الله بولد، ودار نقاش بيني وبين زوجتي حول الولد، ومن فرحتي به قلت لها لأطيب خاطرها: يحرمن علي الحريم من بعدك، أقصد أنني لن أتزوج بعدها، وبعد سنة واحدة توفيت ومكثت سبع سنين بدون زواج، بعدها تزوجت أختها والآن صار عندي ثلاثة أولاد منها، هل علي أثم بما تلفظت به سابقًا؟ وهل النساء يحرمن علي بعدها؟ وهل علي كفارة أم ماذا؟ أفيدوني أفادكم الله.","title":"حكم من حلف بالحرام أن لا يتزوج ثم تزوج","answer":"الجواب: لا يجوز للمسلم أن يحرم ما أحل الله له، لا النساء، ولا الطعام، ولا اللباس، ولا غير ذلك؛ لأن الله يقول سبحانه لنبيه ﷺ: يَا أَيُّهَا النَّبِيُّ لِمَ تُحَرِّمُ مَا أَحَلَّ اللَّهُ لَكَ [التحريم:1]، فليس لك ولا لغيرك تحريم ما أحل الله ، وعليك عما قلت كفارة اليمين، وهي إطعام عشرة مساكين أو كسوتهم أو عتق رقبة، هذا هو الواجب عليك، وقد تزوجت والحمد لله فعليك هذه الكفارة، إطعام عشرة مساكين كل مسكين له نصف الصاع من التمر أو غيره من قوت البلد كالأرز والبر، ومقدار ذلك كيلو ونص تقريبًا بالوزن، تدفعها إلى عشرة من الفقراء، كل واحد يعطى نصف صاع، يعني: كيلو ونص تقريبًا، لكل واحد من الفقراء العشرة من البر أو الشعير أو التمر أو الأرز كفارة لما قلت: يحرم علي النساء بعدك، فهذه هي الكفارة مع التوبة والاستغفار عما صدر منك. والله ولي التوفيق.","link":"https://binbaz.org.sa/fatwas/12807/حكم-من-حلف-بالحرام-ان-لا-يتزوج-ثم-تزوج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_622/62212.mp3","categories":["الأيمان والنذور"]},{"id":14363,"question":"المستمع عبدالمحسن أسامة محمد، من اليمن الشمالية، بعث يسأل ويقول: هل الحلف بالطلاق لتأكيد كلام بدون نية الطلاق يقع طلاق أو لا؟ وهل العبارة التي تقول: (الحلف بالطلاق ليس طلاقًا) حديث عن رسول الله ﷺ؟","title":"هل يقع الحلف بالطلاق؟ وهل \"الحلف بالطلاق ليس طلاقًا\" حديث؟","answer":"الجواب: ليس حديثًا عن النبي ﷺ، ولكن فيه تفصيل: الحلف بالطلاق إن كان أراد به إيقاع الطلاق وقع الطلاق، وإن كان ما أراد أن يكون، فيه كفارة يمين عند جمع من أهل العلم، وبعض أهل العلم يراه: طلاقًا، مطلقًا، ولو قصد به اليمين. والحلف بالطلاق كأن يقول: عليه الطلاق ما يكلم فلانًا، عليه الطلاق لا تخرجي من البيت، عليه الطلاق لا تكلمي فلانًا، عليه الطلاق ألا يزور فلانًا، هذا يسمى يمين إذا كان قصد به المنع، أو الحث أو التصديق أو التكذيب، فإذا قال: عليه الطلاق أنك ما تكلمين أخاك فلانًا، أو جارك فلانًا، وقصده منعها ليس قصده فراقها، فهذا عليه كفارة يمين إذا كلمت، وهكذا لو قال: عليه الطلاق أنه ما يزور فلانًا قصده منع نفسه من الزيارة، هذا يسمى يمينًا.\nأما إن أراد إيقاع الطلاق فهذا يقع الطلاق بالزيارة؛ لأنه علقه عليها، فإذا زار وقعت طلقة واحدة كما قال، مثلما لو قال: إذا دخل رمضان فأنت طالق، هذا ما يسمى يمين هذا تعليق، إذا دخل رمضان طلقت، أو قال: متى حضت أو متى ولدت، أو نحو ذلك. المقصود: أن الطلاق المعلق إذا كان ما قصده التصديق أو التكذيب أو الحث أو المنع إنما قصده التعليق فقط فهذا يقع، إن كلمت زيدًا فأنت طالق، قصده أنه يقع الطلاق وقع الطلاق، إذا دخل رمضان فأنت طالق يقع إذا دخل رمضان، أما إذا قال: إن كلمت زيدًا وقصده منعها من الكلام ما يحب أنها تكلمه، هذا إذا كلمته يكون عليه كفارة يمين؛ لأنه أراد منعها فيسمى يمينًا في أصح قولي العلماء، وتكون فيه الكفارة فقط. وقال بعض أهل العلم: إن الطلاق يقع مطلقًا، ولو نوى به اليمين، وهذا قول ضعيف. والصواب: أنه متى نوى اليمين فإنه ليس عليه، لا يقع عليها طلاق، ولكن عليه الكفارة، واحتج العلماء على ذلك بأدلة كثيرة، منها قوله ﷺ: الأعمال بالنيات وهو لم يرد إلا منعها ما أراد إيقاع الطلاق، إنما أراد منعها، أو منع نفسه من شيء.\nومنها ما حصل من فتاوى بعض الصحابة فيمن حلف ألا يفعل كذا، وإن فعل فعبيده أحرارن وماله صدقة، قد أفتى في هذا ابن عمر وبعض الصحابيات بأنه يمين، والطلاق هو أشد، الطلاق هو مبغوض إلى الله، فإذا كان العتق والصدقة يمين فالطلاق من باب أولى.\nويروى عن جماعة من الصحابة أنهم جعلوه يمينًا، يروى عن علي والزبير وجماعة أنه جعلوه يمينًا. فالحاصل: أن هذا الطلاق لم يرده صاحبه، والرسول ﷺ يقول: إنما الأعمال بالنيات وهو إنما أراد منعًا أو حثًا أو تصديقًا أو تكذيبًا، فإذا قال: عليه الطلاق ألا يكلم فلانًا قال: أراد منع نفسه، وإذا قال: عليه الطلاق أن يزور فلانًا، أراد حث نفسه على الزيارة، وإذا قال: عليه الطلاق أنه ما فعل كذا، أراد التصديق أنه يصدق في ذلك، أو قال: عليه الطلاق مثلًا أن فلانًا كاذبًا، وأراد بذلك أن يكذب فلانًا. فالحاصل: أنه لم يرد إيقاع الطلاق إنما أراد معنىً آخر فيكون له ما أراد على الصحيح، وعليه الكفارة إذا كان أراد هذا المعنى، ولا يقع الطلاق، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12843/هل-يقع-الحلف-بالطلاق-وهل-الحلف-بالطلاق-ليس-طلاقا-حديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_487/48710.mp3","categories":["الطلاق","الأيمان والنذور"]},{"id":14402,"question":"في يوم الجمعة يقول قبل صعود الخطيب للمنبر صليت ركعتين، وقمت بمسك المصحف الشريف، وقلت: بحق هذا القرآن لا أشرب السجائر والدخان مرة ثانية طول عمري، فإذا شربت مثلًا الشيشة هل أكون قد وقعت في اليمين؟ وهل علي كفارة؟","title":"ما حكم الحلف بحق المصحف؟ وحكم شرب والدخان والشيشة","answer":"الجواب: لا يجوز لك أن تحلف بحق القرآن، حق القرآن تعظيمه، وتعظيمه من أعمالك، لكن أن تقول بالله، أو بكلام الله تحلف بالله، أو بكلامه وصفاته، لا بأس، أما بحق القرآن، حق القرآن عليك أن تعظمه، وأن تعمل به، وهذا من عملك، وعملك مخلوق، فلا تقسم بالمخلوقات، لكن تقسم بنفس القرآن، بالله، بكلام الله، بعلم الله، بعزة الله، تقسم بالله أو بصفاته لا بأس. وعليك أن تجتنب الدخان وسائر المحرمات، عليك أن تحذر الدخان والشيشة والخمر وجميع المخدرات المسكرة وإن لم تحلف، وإن لم تقسم، يجب عليك أن تجتنبها وتحذرها؛ لأنها منكرة ومحرمة، فالواجب عليك الحذر منها، وتركها مطلقًا، ولو لم تحلف. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12884/ما-حكم-الحلف-بحق-المصحف-وحكم-شرب-والدخان-والشيشة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_552/55221.mp3","categories":["الأيمان والنذور","الطلاق","الأطعمة والأشربة"]},{"id":14460,"question":"ابن دامري من كركوك، بعث يسأل ويقول: إذا حلف شخص بالله على ألا يفعل شيئًا ما بعدة مرات، وفعل ذلك الشيء عمدًا، هل يقع عليه أن يدفع كفارة واحدة...الشيخ: أعد.المقدم: يقول: إذا حلف شخص بالله ألا يفعل شيئًا ما بعدة مرات، وفعل ذلك الشيء عمدًا هل يقع عليه أن يدفع كفارة واحدة، أم عدة كفارات وفي أماكن مختلفة؟جزاكم الله خيرًا.","title":"كم كفارة تلزم إذا تعددت اليمين؟","answer":"الجواب: ما دام المحلوف عليه شيئًا واحدًا، فليس عليه إلا كفارة واحدة، إذا كان المحلوف عليه شيئًا واحدًا، كأن يقول: والله ما أكلم فلانًا، والله ما أكلم فلانًا، ثم يكرر في أيام كثيرة، أو في شهور يحلف أنه ما يكلم فلانًا، هذه يمين واحدة ولو كررها، إذا كلمه ليس عليه إلا كفارة واحدة، وهكذا لو قال: والله ما أزور فلانًا، والله ما أزور فلانًا، والله ما أزوره، وكرر مائة مرة، في أيام كثيرة، ثم زاره ليس عليه إلا كفارة واحدة، لأن فعله واحد. أما لو قال: والله لا أزور فلانًا، ووالله لا أكلمه، ووالله لا آكل طعامه، ثم زاره وكلمه وأكل طعامه، هذا عليه ثلاث كفارات؛ لأن كل فعل له يمين خاص، الطعام والزيارة والكلام، كل فعل له كفارة؛ لأنها أفعال مختلفة، نعم.","link":"https://binbaz.org.sa/fatwas/12939/كم-كفارة-تلزم-اذا-تعددت-اليمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_488/48808.mp3","categories":["الأيمان والنذور"]},{"id":14471,"question":"كفارة اليمين هي إطعام عشرة مساكين، أو صيام ثلاثة أيام، أو عتق رقبة، فهل يجوز لي أن أخرج خمسة عشر كيلو من البر، وأعطيها لرجل وعياله، يزيد عددهم على عشرة مساكين؟","title":"حكم إعطاء كفارة اليمين لأسرة أفرادها أكثر من عشرة","answer":"الجواب: نعم، كفارة اليمين إطعام عشرة مساكين، أو كسوتهم، أو تحرير رقبة، فمن عجز صام ثلاثة أيام، ليس مخير بالصيام، الصيام إنما يجوز عند العجز عن الإطعام والكسوة والكفارة بالعتق، فإذا عجز عن الثلاث عن الإطعام والكسوة والعتق جاز له الانتقال حينئذٍ إلى الصيام ثلاثة أيام.  وأما مع القدرة على الإطعام أو الكسوة أو العتق فإنه يلزمه واحد من الثلاثة، ولا يجوز له الصوم، ولا يجزئه الصوم. وإذا كان في البيت فقراء قدر عشرة أو أكثر، وأعطيتهم الكفارة كفى ذلك؛ لأن المقصود دفعها إلى عشرة، فإذا كان في البيت إنسان وأولاده يبلغون العشرة، وكلهم فقراء، فإن دفع الكفارة إليهم مجزئ، والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12957/حكم-اعطاء-كفارة-اليمين-لاسرة-افرادها-اكثر-من-عشرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_624/62414.mp3","categories":["الأيمان والنذور"]},{"id":14519,"question":"هذا سؤال من السائل: أحمد بن قاسم بن عبدالعزيز العبيدات من الدمام، يقول: والدي اشترى سيارة من زوج أختي، وكنت يومها متخاصمًا مع أخي، فحلفت وقلت: عليَّ بالطلاق بالثلاثة إذا سجلت السيارة باسم أخي لأحرقها، وحلفت اليمين وأنا غاضب على أخي جدًا، ولم أكن أنوي الطلاق حقيقة، وإنما تخويفًا لهم، فهل إذا حرقتها الآن أكون قد وفيت بيميني أم لا، أو ماذا علي أن أفعل؟","title":"حكم الحلف بالطلاق للمنع والتخويف","answer":"الجواب: عليك كفارة اليمين، ما دمت أردت تخويفهم ومنعهم فعليك التوبة والاستغفار من هذا العمل، وعليك كفارة يمين؛ وذلك بإطعام عشرة مساكين عشرة فقراء لكل فقير نصف صاع من التمر، أو من الأرز، أو الحنطة أو غيرها من قوت البلد، وإن عشيتهم أو غديتهم أو كسوتهم على قميص كفى ذلك، والحمد لله، نسأل الله للجميع الهداية، نعم. المقدم: اللهم آمين.\nالشيخ: ولا يقع الطلاق؛ لأن الطلاق بهذا المعنى في حكم اليمين، ولا يقع بها طلاق؛ لأنك ما أردت إيقاع الطلاق، وإنما أردت التخويف والمنع من هذا العمل.\nالمقدم: إحراقه للسيارة؟\nالشيخ: لا، لا يحرق السيارة، يكفر كفارة يمين ولا يحرق السيارة، هذا إضاعة مال وظلم، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/13008/حكم-الحلف-بالطلاق-للمنع-والتخويف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_633/nour_63307.mp3","categories":["الأيمان والنذور"]},{"id":14524,"question":"هذا سؤال من السائل: أحمد بن قاسم بن عبدالعزيز العبيدات من الدمام، يقول: والدي اشترى سيارة من زوج أختي، وكنت يومها متخاصمًا مع أخي، فحلفت وقلت: عليَّ بالطلاق بالثلاثة إذا سجلت السيارة باسم أخي لأحرقها، وحلفت اليمين وأنا غاضب على أخي جدًا، ولم أكن أنوي الطلاق حقيقة، وإنما تخويفًا لهم، فهل إذا حرقتها الآن أكون قد وفيت بيميني أم لا، أو ماذا علي أن أفعل؟","title":"حكم الحلف بالطلاق للمنع والتخويف","answer":"الجواب: عليك كفارة اليمين، ما دمت أردت تخويفهم ومنعهم فعليك التوبة والاستغفار من هذا العمل، وعليك كفارة يمين؛ وذلك بإطعام عشرة مساكين عشرة فقراء لكل فقير نصف صاع من التمر، أو من الأرز، أو الحنطة أو غيرها من قوت البلد، وإن عشيتهم أو غديتهم أو كسوتهم على قميص كفى ذلك، والحمد لله، نسأل الله للجميع الهداية، نعم. المقدم: اللهم آمين.\nالشيخ: ولا يقع الطلاق؛ لأن الطلاق بهذا المعنى في حكم اليمين، ولا يقع بها طلاق؛ لأنك ما أردت إيقاع الطلاق، وإنما أردت التخويف والمنع من هذا العمل.\nالمقدم: إحراقه للسيارة؟\nالشيخ: لا، لا يحرق السيارة، يكفر كفارة يمين ولا يحرق السيارة، هذا إضاعة مال وظلم، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/13008/حكم-الحلف-بالطلاق-للمنع-والتخويف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_633/nour_63307.mp3","categories":["الأيمان والنذور"]},{"id":14525,"question":"رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات، تقول أم خالد والعمر ستة وثلاثون عامًا، تقول: تزوجت من قبل سبعة عشر عامًا وبقيت ثلاث سنوات بدون طفل، بعدها رزقت ببنت توفيت في الولادة، فنذرت لوجه الله تعالى أن أذبح خروفًا كل سنة إذا رزقني ربي بالأولاد، وكان سعر الخروف في ذلك الوقت لا يزيد على خمسة دنانير، أما الآن فسعر الخروف يزيد على مائة دينار، إني الآن أشعر بالذنب وحائرة، ماذا أعمل؟ حيث أنني لم أذبح ولا خروفًا واحدًا حتى الآن بسبب حالتي المعاشية. أرجو من سماحتكم إرشادي إلى الطريق الصحيح، كيف أكفر عن ذنبي؟ حيث أنني لا أستطيع أن أذبح أربعة عشر خروفًا، أي: بعمر أكبر أبنائي، حيث -والحمد لله- رزقني الله بأربعة أبناء بعد أربع سنوات من الزواج.","title":"ما يلزم من نذرت ولكن عجزت عن الوفاء؟","answer":"الجواب: يقول الله : وَإِنْ كَانَ ذُو عُسْرَةٍ فَنَظِرَةٌ إِلَى مَيْسَرَةٍ [البقرة:280] فما دمت لا تستطيعين فليس عليك شيء، بل تكون هذه الذبائح في ذمتك دينًا، فمتى استطعت ذبحت ما تيسر منها، قربة إلى الله ، ووزعتيه بين الفقراء، إذا كان قصدك إطعامه الفقراء، أو كان لا نية لك، فإن هذه الذبيحة توزع بين الفقراء، متى تيسر لك ذلك، وما دمت عاجزة فالله -جل وعلا- لا يكلفك ما لا تستطيعين، يقول الله سبحانه: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]. وإذا كان دين المخلوقين يؤجل لأجل العسر فدين الله أولى؛ لأنه  أسمح وأقرب إلى العفو من المخلوق، فلا حرج عليك حتى تستطيعي. فإذا استطعت فاذبحي ما تيسر حسب الطاقة، ولا تعودي للنذر في المستقبل، لا تنذري أبدًا، النبي  نهى عن النذر، وقال: إنه لا يأتي بخير، وإنما يستخرج به من البخيل. فالنصيحة لك أن لا تنذري في المستقبل، أما هذا النذر فعليك فيه تقوى الله، فمتى استطعت فاذبحي حتى تؤدي ما عليك من الذبائح، وما دمت عاجزة فالله -جل وعلا- عفو كريم، كما قال سبحانه: وَإِنْ كَانَ ذُو عُسْرَةٍ فَنَظِرَةٌ إِلَى مَيْسَرَةٍ [البقرة:280]، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13026/ما-يلزم-من-نذرت-ولكن-عجزت-عن-الوفاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_634/nour_63408.mp3","categories":["الأيمان والنذور","قضايا المرأة"]},{"id":14532,"question":"تقول أم خالد من العراق: زوجي يصوم ويصلي، ولكنه لا يؤمن بالنذور، ويتحجج بالحالة المعاشية، ويقول: لا توفي بنذرك وأنا أتحمل ذنبك.علمًا أن لي دخلًا ثابتًا يزيد على مائة دينار شهريًا، حيث أنني أعمل مدرسة في مدرسة ثانوية.","title":"ما يلزم من نذرت وتستطيع الوفاء؟","answer":"الجواب: سبق الجواب في هذا، لا طاعة لمخلوق في معصية الخالق، الرسول  يقول: من نذر أن يطيع الله فليطعه هكذا يقول ﷺ: من نذر أن يطيع الله فليطعه، ومن نذر أن يعصي الله فلا يعصه خرجه البخاري في الصحيح. فإذا كنت نذرت لله العبادة، وهي التي تقدم ذكرها الذبيحة للصدقة على الفقراء، فأوفي متى استطعت من مالك، من معاشك، أو من غيره، وإذا عجزت يؤجل حتى تستطيعي، كما قال الله سبحانه: وَإِنْ كَانَ ذُو عُسْرَةٍ فَنَظِرَةٌ إِلَى مَيْسَرَةٍ[البقرة:280] وإذا كان معاشك تستطيعين منه أن تشتري الذبيحة التي نذرت فاشتريها من معاشك، أو من غير معاشك حسب القدرة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13027/ما-يلزم-من-نذرت-وتستطيع-الوفاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_634/nour_63409.mp3","categories":["الأيمان والنذور","قضايا المرأة"]},{"id":14570,"question":"من سوسة الجمهورية التونسية، السائل وناس، يقول في هذا  سماحة الشيخ، ما هي اليمين الغموس؟ وهل توجد كفارة لليمين الغموس إن كان كذلك؟","title":"ما هي اليمين الغموس؟ وهل لها كفارة؟","answer":"الجواب: اليمين الغموس هي اليمين الكاذبة التي يقتطع بها الإنسان حق أخيه بغير حق، هذه اليمين الغموس الكاذبة، وهي التي قال فيها النبي ﷺ: من حلف على يمين ليقتطع بها مال امرئ مسلم بغير حق، فقد أوجب الله له النار، وحرم عليه الجنة في اللفظ الآخر: لقي الله وهو عليه غضبان. فالذي يحلف كاذبًا أنه اشترى كذا، أو أنه أعطي كذا، أو ما أشبه ذلك، وهو كاذب هذه اليمين الفاجرة الغموس ليأخذ بها مال أخيه بغير حق، أو يحلف على أنه ما فعل كذا من العدوان على أخيه، أو أنه ما سبه، أو ما أشبه ذلك وهو كاذب هذه يمين الغموس، الذي يقتطع بها حق أخيه بغير حق. وكل كاذبة فهي يمين غموس، لكنها تختلف في الكبر والعظم على حسب ما يترتب عليها من الظلم والشر، وليس فيها كفارة، فيها العقوبة العظيمة، والوعيد الشديد، فلو قال: والله ما سافرت وهو يكذب تكون يمين الغموس كاذبة، يأثم بها، ولكنها ليست مثل من قال: والله ما أخذت منه ولا شيئًا، وقد أخذ منه شيئًا؛ لأن هذا أخذ مال أخيه بغير حق، كأن يدعي عليه إنسان يقول: إنه اقترض مني ألف ريال فيحلف، يقول: ما اقترضت منه، والمقرض ما عنده بينة، والمقترض كاذب، يقول: والله ما اقترضت منه، هذه يمين الغموس؛ لأنه أخذ بها مال أخيه بغير حق، أو أعاره عارية مثل سلاح أو عباءة، أو إناء ثم يجحد ويحلف أنه ما استعار، فهذه يمين غموس؛ لأنه أخذ مال أخيه بغير حق بهذه اليمين، أو باع على أخيه شيء ثم جحد البيع، وليس عنده بينة، ليس عند المشتري بينة، فيحلف إني ما بعته، فهذا يمين الغموس عظيمة خطيرة؛ لأنه أخذ مال أخيه بغير حق، جحد حق أخيه بغير حق، وهكذا ما أشبه ذلك، واليمين الغموس كما تقدم هي الكاذبة، لكنها تختلف وتتفاوت تفاوتًا عظيمًا على حسب ما يترب عليها من الشر، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13067/ما-هي-اليمين-الغموس-وهل-لها-كفارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_556/55608.mp3","categories":["الأيمان والنذور"]},{"id":14618,"question":"السائلة (س. ع) من الدمام تقول: ما حكم من حلف بالله على شيء واحد، أربع مرات أو أكثر، هل يصوم عن كل يمين ثلاثة أيام أم على الجميع ثلاثة أيام؟ مع العلم بأن هذا الشيء واحد، وليس شيئًا منفصلًا.","title":"حكم كفارة اليمين المكررة على شيء واحد","answer":"الجواب: إذا كان المحلوف عليه واحد، كفارة واحدة، يعني إذا قال: والله ما أكلم فلانًا، والله ما أكلم فلانًا، والله ما أكلم فلانًا، مرات كثيرة، كفارة واحدة إذا كلمه، كفارة واحدة، أو قال: والله ما آكل هذا الطعام، والله ما آكل هذا الطعام، والله ما أكل هذا الطعام، وهو يعزم عليه، وهو يحلف، ثم هداه الله وأكل، يكفر يمين واحدة، يكفر واحدة؛ لأنه فعل واحد.  أما لو قال: والله ما آكل هذا الطعام، والله ما أكلم فلانًا، والله ما أسافر، هذه لكل يمين كفارة؛ لأنها أفعالًا متعددة، والله ما أسافر، عليه كفارة، والله ما آكل، وأكل عليه كفارة، والله ما أكلم فلانًا وكلمه عليه كفارة؛ لأنها مختلفة فهمنا؟ نعم.\nالمقدم: أحسن الله إليكم يا سماحة الشيخ عبدالعزيز ، يكثر بعض الناس من كثرة الحلف في أموره كلها؟ الشيخ: ما يجوز، لا يجوز، المسلم ينبغي له أن يحفظ يمينه، الله يقول: وَاحْفَظُوا أَيْمَانَكُمْ [المائدة:89] ويقول النبي ﷺ: ثلاث لا يكلمهم الله، ولا ينظر إليهم يوم القيامة، ولا يزكيهم، ولهم عذاب أليم: أشيمط زاني أشيمط يعني: شيخ شايب وعائل مستكبر فقير ومستكبر ورجل جعل الله بضاعته، لا يبيع إلا بيمينه، ولا يشتري إلا بيمينه يعني: يكثر منها، فالواجب الحذر من ذلك؛ لأن ربنا يقول: وَاحْفَظُوا أَيْمَانَكُمْ [المائدة:89] ولأنه إذا أكثر منها هذا من وسائل التساهل بها، والحلف على الباطل والكذب. فالواجب الحذر، وألا يتكلم، وألا يحلف إلا على شيء بين، يعرف أنه صادقًا فيه، أو يعرف أن حلفه له مصلحة كأن يقول: والله ما أفعل هذا الشيء، يكرر، والله ما أشرب الخمر، والله ما أشرب الخمر، والله ما أعق والدي، يؤكد على نفسه لا بأس، والله ما أكلم فلانًا صاحب البدعة، وأشباه ذلك، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13110/حكم-كفارة-اليمين-المكررة-على-شيء-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_559/55907.mp3","categories":["الأيمان والنذور"]},{"id":14660,"question":"رسالة وصلت إلى البرنامج من الحديدة، في الجمهورية العربية اليمنية، باعثها المستمع عبدالعزيز محمد قاسم القدسي، يسأل ويقول: والدتي نذرت أن تصوم يومين من كل شهر لله  إن اهتدى أخي إلى طريق الحق والصواب، وقد هدى الله أخي إلى طريق الصواب، وبدأت والدتي في صوم ما عليها من نذرها، ولكن المشكلة أن والدتي لا تستطيع الصوم إلا بمشقة؛ لأنها دائمًا تشكو من وجع الرأس والصداع، وهي تريد الآن أن تسأل: هل يجوز لها أن تكفر عن نذرها بكفارة اليمين؟وإذا كان الجواب بنعم، فهل يجوز لها أن تخرج المال بدلًا عن الإطعام أو الكسوة؟أفيدونا، جزاكم الله خيرًا.","title":"ما يلزم من نذرت أن تصوم ولكنه يشق عليها؟","answer":"الجواب: يلزمها الصوم إذا كانت تستطيع؛ لقول النبي ﷺ: من نذر أن يطيع الله فليطعه، ومن نذر أن يعصي الله فلا يعصه فعليها الصوم ما دامت تستطيع لهذا الحديث الصحيح، وعليها أن تبتعد عن النذر مستقبلًا، لا تنذر النذر، الرسول ﷺ نهى عن النذر، وقال: لا تنذروا، فإن النذر لا يرد من قدر الله شيئًا لكن متى نذر الإنسان طاعة فعليه الوفاء، فإذا عجزت عن صوم اليوم من كل شهر أجلت ذلك إلى حسب طاقتها وتصومها بعد ذلك، مثلما تؤجل رمضان إذا عجز الإنسان بالمرض، ثم تقضي، هذا هو الأظهر من السنة؛ لقوله تعالى: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ[التغابن:16]. فإذا أصابها في بعض الشهور مرض، وعجزت قضت اليومين في الشهر الآخر، والحمد لله، فإذا كبر السن، وكبرت سنها، وعجزت أطعمت مسكينًا عن يومين صاعًا من كل شهر عن اليومين من البر، أو من الرز، كما يطعم من عجز عن صوم رمضان لكبر سنه، عن كل يوم مسكينًا، هكذا هذه الناذرة إذا عجزت تطعم عن كل يوم مسكينًا بعد كبر سنها.  أما المرض العارض فلها أن تفطر عند المرض العارض، ثم إذا طابت وشفيت قضت في الشهر الآخر، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13149/ما-يلزم-من-نذرت-ان-تصوم-ولكنه-يشق-عليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_637/nour_63701.mp3","categories":["الأيمان والنذور","قضايا المرأة"]},{"id":14698,"question":"المستمع (م. م. م) مقيم في المملكة، وهو سوداني، بعث برسالة كتبها بلهجته العامية، مفهوم ما في هذه الرسالة يقول: على إثر نزاع بينه وبين زوجته حلف بالحرام لا يأكل من طعامها، ولا يصلها، ففعل، ويسأل عن الحكم.","title":"حكم من حلف بالحرام ألا يفعل شيئًا ما ثم فعله","answer":"الجواب: هذا يختلف بحسب النية، إذا كان حلفه بالحرام ألا يأكل من طعامها قصده الامتناع من ذلك يقصد الامتناع مما حلف عليه، وليس يقصد تحريمها هي، وإنما قصد من ذلك أن يمتنع مما حلف عليه، فهذا يكفيه كفارة يمين، مع التوبة إلى الله، والاستغفار.  وكفارة اليمين: إطعام عشرة مساكين من قوت البلد، أو كسوتهم، كل واحد يعطى نصف الصاع من التمر أو الأرز أو البر مقداره كيلو ونصف تقريبًا، أو يكسو كل واحد منهم كسوة تجزئهم في الصلاة، كالقميص أو إزار ورداء، فإن كان عاجزًا فقيرًا لا يستطيع ذلك صام ثلاثة أيام. أما إن كان قصد تحريمها، وأنها حرام عليه كأمه وأخته، فهذا يسمى ظهارًا إذا كان قصده ذلك، فإذا أكل أو فعل شيئًا مما حرم عليه فإنه يكون عليه كفارة الظهار، المذكورة في سورة المجادلة قَدْ سَمِعَ [المجادلة:1] وهي عتق رقبة مؤمنة، فإن عجز صام شهرين متتابعين ستين يومًا، فإن عجز أطعم ستين مسكينًا كل مسكين يعطى نصف صاع من قوت البلد من تمر أو أرز أو غيرهما، وهو كيلو ونصف تقريبًا، وإن عشاهم أو غداهم كفى ذلك، ستين مسكينًا، ستين فقيرًا، يعطون ثلاثين صاعًا، كل صاع بين اثنين، هذا إن كان قصد تحريمها. أما إذا كان ما قصد إلا الامتناع من الأكل ونحوه، وليس قصده تحريمها، فإنه يكفيه كفارة اليمين، كما تقدم.\nالمقدم: جزاكم الله خيرًا، لو تكرمتم إعادة مقدار ما يعادل الصاع بالكيلو سماحة الشيخ؟\nالشيخ: ثلاثة كيلو، يعادل الصاع ثلاثة كيلو تقريبًا، يعادل الصاع، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13224/حكم-من-حلف-بالحرام-الا-يفعل-شيىا-ما-ثم-فعله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_629/nour_62911.mp3","categories":["الأيمان والنذور","الظهار"]},{"id":14705,"question":"المستمع (م. م. م) مقيم في المملكة، وهو سوداني، بعث برسالة كتبها بلهجته العامية، مفهوم ما في هذه الرسالة يقول: على إثر نزاع بينه وبين زوجته حلف بالحرام لا يأكل من طعامها، ولا يصلها، ففعل، ويسأل عن الحكم.","title":"حكم من حلف بالحرام ألا يفعل شيئًا ما ثم فعله","answer":"الجواب: هذا يختلف بحسب النية، إذا كان حلفه بالحرام ألا يأكل من طعامها قصده الامتناع من ذلك يقصد الامتناع مما حلف عليه، وليس يقصد تحريمها هي، وإنما قصد من ذلك أن يمتنع مما حلف عليه، فهذا يكفيه كفارة يمين، مع التوبة إلى الله، والاستغفار.  وكفارة اليمين: إطعام عشرة مساكين من قوت البلد، أو كسوتهم، كل واحد يعطى نصف الصاع من التمر أو الأرز أو البر مقداره كيلو ونصف تقريبًا، أو يكسو كل واحد منهم كسوة تجزئهم في الصلاة، كالقميص أو إزار ورداء، فإن كان عاجزًا فقيرًا لا يستطيع ذلك صام ثلاثة أيام. أما إن كان قصد تحريمها، وأنها حرام عليه كأمه وأخته، فهذا يسمى ظهارًا إذا كان قصده ذلك، فإذا أكل أو فعل شيئًا مما حرم عليه فإنه يكون عليه كفارة الظهار، المذكورة في سورة المجادلة قَدْ سَمِعَ [المجادلة:1] وهي عتق رقبة مؤمنة، فإن عجز صام شهرين متتابعين ستين يومًا، فإن عجز أطعم ستين مسكينًا كل مسكين يعطى نصف صاع من قوت البلد من تمر أو أرز أو غيرهما، وهو كيلو ونصف تقريبًا، وإن عشاهم أو غداهم كفى ذلك، ستين مسكينًا، ستين فقيرًا، يعطون ثلاثين صاعًا، كل صاع بين اثنين، هذا إن كان قصد تحريمها. أما إذا كان ما قصد إلا الامتناع من الأكل ونحوه، وليس قصده تحريمها، فإنه يكفيه كفارة اليمين، كما تقدم.\nالمقدم: جزاكم الله خيرًا، لو تكرمتم إعادة مقدار ما يعادل الصاع بالكيلو سماحة الشيخ؟\nالشيخ: ثلاثة كيلو، يعادل الصاع ثلاثة كيلو تقريبًا، يعادل الصاع، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13224/حكم-من-حلف-بالحرام-الا-يفعل-شيىا-ما-ثم-فعله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_629/nour_62911.mp3","categories":["الأيمان والنذور","الظهار"]},{"id":14732,"question":"المستمع ناصر مقبل يمني من الرياض رماح، بعث يقول: حلفت بالطلاق على ألا أعود إلى مزاولة شيء وفعلت هذا الشيء، هل علي كفارة؟ وماذا يكون حكم الدين في هذا الأمر؟ أفيدوني، أفادكم الله.","title":"ما يلزم من حلف بالطلاق ألا يفعل شيئًا ما ثم فعله؟","answer":"الجواب: هذا فيه تفصيل: إذا حلف أنه ما يفعل هذا الشيء، إن كان قصده الامتناع ومنع نفسه من هذا الشيء وليس قصده الطلاق ليس قصده إيقاع الطلاق، مثل: علي الطلاق ما آكل طعام فلان، علي الطلاق ما أزور فلانًا، قصده الامتناع ما قصده إيقاع الطلاق، ولكن قصده أن يمتنع، فهذا فيه كفارة يمين إذا فعله.  أما إذا قصد إيقاع الطلاق يقع الطلاق، إذا قال: علي الطلاق ما أكلم فلانًا وكلمه ناويًا أنه إذا كلمه يقع الطلاق، فيقع الطلاق، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13222/ما-يلزم-من-حلف-بالطلاق-الا-يفعل-شيىا-ما-ثم-فعله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_490/49006.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":14743,"question":"المستمع (ع. ن. ب) من الزرقاء بالأردن يقول في رسالة بعث بها إنه قبل حوالي عشرين عامًا حصل جدال بينه وبين شخص آخر، وقال له هذا الشخص:إن فلانًا يقول: إنك قلت كذا وكذا، فقلت له: علي علي الطلاق أنني لم أقل ذلك، وأنا كنت وقتها متأكد بأنني لم أقل ما نسب عني، ولكن الشك ساورني فيما بعد بأن أكون ربما قلت ما حلفت على أني لم أقله، أرشدوني عن إمكانية وقوع الطلاق من عدمه تجاه هذا الحلف؟ وهل علي كفارة أو أي شيء آخر؟جزاكم الله خير الجزاء.","title":"حكم من حلف بالطلاق على شيء ثم شك فيه","answer":"الجواب: إذا كنت حين طلقت تعتقد أنك لم تقل ذلك فليس عليك شيء، والطلاق ليس بواقع؛ لأنك مسؤول عن نيتك، وعن قصدك وعن حالك حين الطلاق، فمادمت حين الطلاق تعتقد أنك صادق فليس عليك شيء.  أما لو كنت قلت ذلك لتصدق وخوفًا من معرة الاعتراف وقلت ذلك لتصدق، وأنت تعلم أنك كاذب، فعليك كفارة يمين عن ذلك؛ لأنك ما قصدت إيقاع الطلاق، وإنما قصدت أن تصدق، أما إن كنت قصدت إيقاع الطلاق فإنه يقع الطلاق، وأما يمينك المسؤول عنها طلاقك المسؤول عنه فإنه لا يقع؛ لأنك حين طلقت تعتقد أنك صادق، فلا حرج عليك ولا طلاق عليك. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13259/حكم-من-حلف-بالطلاق-على-شيء-ثم-شك-فيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_630/nour_63009.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":14880,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين، يقول: سافرت أنا ووالدي إلى اليمن، فخطب لي فتاة لم أكن أعرفها، وبعد الخطوبة زرنا أهل الفتاة، فسألني أبي: ما رأيك فيها؟ فقلت له: مناسبة، وتزوجتها وأحببتها، وبعد عدة شهور بدأ الخلاف بيننا وبين الوالدين؛ لكونها تختلف مع إخوتي الصغار، والدي يقول: إنها تنقل أسرارنا إلى الجيران، وطلب مني أن أطلقها، ما هو رأيكم؟جزاكم الله خيرًا.","title":"حكم الاستجابة للوالد في طلاق الزوجة","answer":"الجواب: لا تعجل، وانصحها حتى لا تفعل ما يخالف رأي والديك من نقل أسرارهم إلى الجيران، انصحها وعلمها وخبرها أن هذا لا يجوز، وأن عليها السمع والطاعة في المعروف، فأنت تنصحها، وهي عليها السمع والطاعة، والوالدان كذلك لا يعجلان في طلب طلاقها، وينصحانها أيضًا بالكلام الطيب، والأسلوب الحسن، حتى تزول المشكلة، وحتى تستقر الأمور.  ولا تعجل في الطلاق؛ لأن هذا مرض يحتاج إلى علاج، فعليك بعلاجها بالكلام الطيب، والأسلوب الحسن، والترغيب والترهيب، وهكذا الوالدان يعالجان معك ذلك بالكلام الطيب، والأسلوب الحسن، حتى تزول المشكلة -إن شاء الله-، وتهدأ الأمور وتستمر العشرة بينكما، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13376/حكم-الاستجابة-للوالد-في-طلاق-الزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_645/nour_64519.mp3","categories":["الطلاق","الأيمان والنذور","نصائح وتوجيهات"]},{"id":14897,"question":"يقول: أنا أقسمت في يوم على الطعام أن لا آكله، ولظروف اضطرارية أكلت من هذا الطعام الذي أقسمت عليه، فما هي النصيحة؟وجهوني جزاكم الله خيرًا.","title":"حكم من حلف على شيء ألا يفعله ففعله","answer":"الجواب: عليك كفارة يمين فقط، والحمد لله، كفارة يمين، وهي إطعام عشرة مساكين، أو كسوتهم، عشرة عدد أصابعك، تعطي كل واحد نصف صاع، من صاع النبي ﷺ من قوت البلد، من تمر أو أرز أو بر أو شعير أو زبيب، أو نحو ذلك، وإن أعطيتهم، وإن كسوتهم كسوة كل واحد له قميصًا أو إزارًا ورداء، كفى، وإن عشيتهم أو غديتهم في بيتك كفى عشرة، والحمد لله، ومقداره بالوزن كيلو ونصف تقريبًا، وهو يقرب من نصف الصاع، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13393/حكم-من-حلف-على-شيء-الا-يفعله-ففعله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_639/nour_63911.mp3","categories":["الأيمان والنذور"]},{"id":14938,"question":"هذه الرسالة وردتنا من محمد سعيد أبو عين، يقول في رسالته محمد: اشتريت سيارة ديزل خمسة ركاب على أقساط، دفعت ألفين دينارًا عند استلام السيارة، وبقي ألفين، أدفع كل شهر مائة دينار، وكان لي شريك قريب لي فقلت قدام شريكي: إذا أن السيارة أوفت الأقساط سوف أذبح بقرة نذر، وأن السيارة أوفت الأقساط، وعندما أوفت الأقساط بعنا السيارة، وطلبت من شريكي أن نوفي النذر، رفض ذلك. ما هو الحل عندكم؟ مع جزيل الشكر، هل أنا ملزم به لوحدي أم لا؟وفقكم الله.","title":"هل نذر أحد الشركاء يلزم الآخرين؟","answer":"الجواب: هذا إذا كان قصد به التزام لما أنه إذا أوفى السيارة التزم بهذا، نذر لله أنه يذبح، وايش سمى ذبيحته؟ المقدم: بقرة. الشيخ: بقرة، إذا كان التزم بهذا هو يلزمه وحده، شريكه ما يلزمه ذلك إلا إذا التزم به، أما هو يلزمه؛ لأن الرسول  قال: من نذر أن يطيع الله فليطعه فإذا أوفى الله الأقساط من كد السيارة، ومن حاصل ما حصل من السيارة؛ فيذبحها إذا كان قال: إذا أوفت السيارة ذبحت هذا نذرًا، فقال: نذر، أو قال: لله علي أو صدقة لله؛ فيذبحها، ويعطيها الفقراء يقسمها بين الفقراء، إلا إذا كان له نية أنه يقسمها بين الجيران، أو بين أقاربه، أو له نية أن يذبحها في بيته، ويدعو عليها الجيران أو الأقارب والأصحاب لا بأس له نيته، الأعمال بالنيات، أما إذا كان ما له نية فالبقرة تذبح وتوزع بين الفقراء، في بلده، نعم.","link":"https://binbaz.org.sa/fatwas/13438/هل-نذر-احد-الشركاء-يلزم-الاخرين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_647/nour_64706.mp3","categories":["الأيمان والنذور"]},{"id":14957,"question":"فضيلة الشيخ عبدالعزيز هذه رسالة وردتنا من (بشير . أ. ع) من السودان، يقول في رسالته: هو أنني حلفت ووضعت يدي في كتاب الله بأنني لا أفعل كذا، ولكن بعملية غير إرادتي وقعت في العمل وتكررت مني مرتين، والآن بعد مضي زمن كثير ندمت أشد الندم على ما فعلت، ثم تبت إلى ربي رغم أنني لا أقصر في أمر من أمور الله، والله على ما أقول شهيد، فماذا أفعل؟أفيدوني، جزاكم الله عني خير الجزاء.","title":"حكم من حلف ألا يفعل شيئًا ففعله","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله رب العالمين، والصلاة والسلام على عبده ورسوله وأمينه على وحيه وصفوته من خلقه، نبينا وإمامنا وسيدنا محمد بن عبد الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد: فقد بين الله  حكم اليمين، فإذا حلف الإنسان أنه لا يفعل كذا، سواء وضع يده على المصحف أم لم يضع، المهم إذا حلف أنه لا يفعل كذا ففعله عن اختياره لا ناسيًا ولا مكرهًا، بل باختياره؛ فإن عليه كفارة اليمين؛ لقول الله : لا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِنْ يُؤَاخِذُكُمْ بِمَا عَقَّدْتُمُ الأَيْمَانَ فَكَفَّارَتُهُ إِطْعَامُ عَشَرَةِ مَسَاكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍ فَمَنْ لَمْ يَجِدْ فَصِيَامُ ثَلاثَةِ أَيَّامٍ ذَلِكَ كَفَّارَةُ أَيْمَانِكُمْ إِذَا حَلَفْتُمْ وَاحْفَظُوا أَيْمَانَكُمْ [المائدة:89] الآية، الله سبحانه بين لنا أن هذا المذكور هو كفارة اليمين، فإذا قال إنسان: والله لا أكلم فلانًا، أو والله لا أزور فلانًا، أو والله لا آكل طعام فلان، أو ما أشبه ذلك، ثم فعل ذلك ذاكرًا مختارًا؛ فإن عليه كفارة اليمين المذكورة آنفًا، وهي: إطعام عشرة مساكين نصف صاع من قوت البلد لكل واحد، يقدر بنحو كيلو ونص، سواء كان رز أو ذرة أو حنطة أو تمر أو غير ذلك من قوت البلد، يتصدق بنصف صاع من قوت بلده، أو يكسوهم كسوة تجزئهم في الصلاة: كقميص، أو إزار ورداء لكل واحد، أو يعتق عبدًا مؤمنًا أو أمة مؤمنة، فإن عجز عن ذلك صام ثلاثة أيام، هذه كفارة اليمين.  وينبغي أن تكون متتابعة كما قال ابن مسعود  وهكذا لو قال: والله لأفعلن كذا وكذا، والله لأكلمن فلانًا، والله لأزورنه، فلم يفعل في الحد الذي حده بالنية؛ فعليه كفارة اليمين، كأن ينوي أنه يزوره في اليوم الفلاني أو الليلة الفلانية، أو يحدد ذلك بفلظ يقول: والله لأزورن فلانًا هذا اليوم أو هذه الليلة، فلم يفعل؛ فعليه كفارة اليمين مثل ما لو قال: والله لا أزوره، والله لا أكلمه، ثم فعل، نعم.","link":"https://binbaz.org.sa/fatwas/13448/حكم-من-حلف-الا-يفعل-شيىا-ففعله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_648/nour_64801.mp3","categories":["الأيمان والنذور"]},{"id":15027,"question":"أيضًا يقول: ما حكم من حلف يمينًا وهو مصلح بين طرفين، ونكث فيها؟","title":"حكم النكول في اليمين لعلة الإصلاح بين الناس","answer":"الجواب: هذا مجمل، لكن يفسر على حسب ما تحتمله العبارة، إذا قال: والله لا أفعلن كذا، لا أزاورنكم، أو والله لأعيننكم على كذا وكذا، أو والله إن فلانًا ما فعل كذا، أو ما فعل كذا، بطريق الإصلاح، فهو في حلفه بقصد الإصلاح، حلفًا لا يضر أحدًا، لا حرج عليه في ذلك، والله إن فلانًا قال فيك كذا، والله إن الجماعة أثنوا عليك، ويشكرونك، ويقولون: إنه صاحبنا، وكذا، ليصلح بينهم، أو قال: والله لأزورنكم، وأساعدنكم على المهمة إذا صلحتم، وإذا تركتم هذا الشقاق؛ فإنه عليه أن يوفي لهم بهذا الشيء؛ لأن الوعد له شأن، ومن خصال المؤمن الوفاء بالوعد، قال الله في حق إسماعيل: وَاذْكُرْ فِي الْكِتَابِ إِسْمَاعِيلَ إِنَّهُ كَانَ صَادِقَ الْوَعْدِ وَكَانَ رَسُولًا نَبِيًّا [مريم:54]. ولا ينبغي له أن يخل بالوعد؛ لأن الإخلال بالوعد من صفات أهل النفاق، المنافق إذا وعد أخلف، وعليه كفارة يمين إذا أخل بذلك، مع كونه اتصف بصفات أهل النفاق، في الإخلال بالوعد، عليه أيضًا كفارة اليمين، إذا قال: والله لأزورنكم في يوم كذا، أو والله لأساعدنكم، ولم يفعل؛ فعليه كفارة اليمين، وعليه معرة إخلاف الوعد، وقد يأثم عندما من قال بوجوب الوفاء، وهو ظاهر الأدلة، وقد لا يأثم؛ لكنه وقع في خصلةٍ من خصال أهل النفاق، ينبغي له ألا يقع فيها، وظاهر الأدلة الشرعية: أن الوفاء بالوعد أمر واجب، وأن الإخلال به محرم، ومن صفات أهل النفاق، فلا يليق بالمصلح والموجه أن يخلف الوعد؛ لأن هذا يخل بالإصلاحات المستقبلة، فلا ينبغي له أبدًا أن يخلف الوعد، بل ينبغي له أن يفي بالوعد، ويحرص في ذلك. وهكذا الأيمان الأخرى، ما كان منها كذبًا للإصلاح، ولا يترتب عليه مضرة أحد، فلا حرج عليه في ذات الإصلاح، كما في الحديث الصحيح من حديث أم كلثوم بنت عقبة بن أبي معيط، قالت: سمعت الرسول -عليه الصلاة والسلام- يقول: ليس الكذاب الذي يصلح بين الناس، فيقول خيرًا، وينمي خيرًا -قالت: ولم أسمعه يرخص في شيء من الكذب إلا في ثلاث: في الإصلاح بين الناس، وفي الحرب، وفي حديث الرجل امرأته، والمرأة زوجها فالإصلاح يباح فيه الكذب الذي لا يضر الناس، ولكنه ينفع الجماعة فيصلح بينهم، ولا يضر غيرهم، نعم.","link":"https://binbaz.org.sa/fatwas/13530/حكم-النكول-في-اليمين-لعلة-الاصلاح-بين-الناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_653/nour_65305.mp3","categories":["الأيمان والنذور"]},{"id":15034,"question":"أيضًا يقول: لقد حلفت لأحد الأصدقاء بالطلاق أنني أرسلت مبلغًا من النقود، وحددت ذلك المبلغ، وكنت متأكد من ذلك المبلغ، وكان عندي دليل فيه، وبعد ذلك أخذت أفتش في تلك الأوراق، فوجدت المبلغ ينقص عن التحديد، فهل يجب أن أراجع زوجتي أم أنها تطلق مني؟أفيدوني، وفقكم الله.","title":"حكم من حلف بالطلاق معتقدًا فعل شيء فبان خلافه","answer":"الجواب: إذا طلق الإنسان على شيء يعتقد أنه فعله، فإن الطلاق لا يقع، فإذا قال: عليه الطلاق أنه أرسل كذا وكذا ظانًا معتقدًا أنه أرسله، ثم بان أنه ما أرسله، أو بان أنه ناقص، فالطلاق لا يقع في هذه الحال، هذا هو الصحيح من أقوال العلماء، وهكذا لو قال: علي الطلاق إني رأيت زيدًا، أو علي الطلاق أن زيدًا قد قدم، وهو يظن ويعتقد أنه مصيب، ثم بان أنه غلطان، وأن هذا الذي قدم، أو مات ليس هو الرجل الذي أخبر عنه فإن طلاقه لا يقع؛ لأنه في حكم اليمين اللاغية، يعني: في حكم لغو اليمين؛ لأنه ما تعمد الباطل، إنما قال ذلك ظنًا منه واعتقادًا منه أنه مصيب، فلا يقع طلاقه، بل زوجته معه، هذا هو الصواب من قولي العلماء، نعم.","link":"https://binbaz.org.sa/fatwas/13531/حكم-من-حلف-بالطلاق-معتقدا-فعل-شيء-فبان-خلافه","audio":"","categories":["الأيمان والنذور","الطلاق"]},{"id":15108,"question":"من النماص، بعث إلينا المستمع عبدالرحمن العبدالله الشهري بهذه الورقة في هذا السؤال يقول:أرجو منكم عرض سؤالي هذا على أحد المشايخ، وسؤالي هو: لقد جاءني ضيف وهو ابن أخي وعائلته، فأردت أن أذبح له ذبيحة، فقام وقال: علي الطلاق ما توجب لهم ذبيحتي، فقمت أنا وقلت مع الزعل من طلاقه، وقلت: طلاق إن ما ذبحت لكم ما عاد أدخل بيتك.فأرجو عرض هذا السؤال على فضيلة الشيخ عبدالعزيز .","title":"حكم الحلف بالطلاق على الضيف وكفارته","answer":"الجواب: لا ينبغي استعمال هذا الطلاق لا منك ولا من الضيف، لا ينبغي للضيف يطلق، بل ينبغي له أن يتسامح ويسمح لمضيفه أن يكرمه بالذبيحة وغيرها، وإذا كان ولا بد فليؤكد عليه بغير الطلاق، والمضيف كذلك لا ينبغي له أن يطلق، بل ينبغي له أن يؤكد من دون طلاق. فإذا طلق الضيف، أو طلق المضيف فالذي يحنث عليه كفارة يمين، إن كان الضيف تنازل، وأكل الذبيحة، فعليه كفارة يمين عن طلاقه إذا كان قصده منع المضيف من التكلف، وليس قصده فراق أهله، فالطلاق في حكم اليمين وعليه كفارتها، وإن كان الضيف أبى وترك.  فالمضيف الذي طلق أنه يذبح عليه كفارة يمين، ولا يذبح شيئًا، عليه كفارة اليمين؛ لأن طلاقه في حكم اليمين إذا كان قصد إكرامه وإلزامه ولم يقصد فراق زوجته، فهذا في حكم اليمين، وعليه كفارتها، وهي إطعام عشرة مساكين أو كسوتهم، عشرة يعطيهم نصف الصاع تمر أو رز حسب قوت البلد، مقداره كيلو ونصف تقريبًا، وإن عشاهم في بيته، أو في مطعم، أو غداهم أو كساهم كسوة تجزئهم في الصلاة، كفى ذلك، يعني: أعطى كل واحد قميصًا أو إزارًا ورداءً، كفى ذلك. وينبغي عدم استعمال الطلاق في مثل هذه الأمور، كما تقدم، نسأل الله للجميع الهداية، نعم.\nالمقدم: لكن مثل الكفارة في هذه الحالة هل تعطى واحد، أو..؟\nالشيخ: عشرة مساكين.\nالمقدم: لا بد من العشرة؟ الشيخ: عشرة لا بد؛ لأنه مثل اليمين سواء سواء، نعم.","link":"https://binbaz.org.sa/fatwas/13607/حكم-الحلف-بالطلاق-على-الضيف-وكفارته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_664/nour_66409.mp3","categories":["الأيمان والنذور"]},{"id":15114,"question":"أحمد عبدالله محمد علي جمعة، بعث يسأل ويقول: ما حكم الذين يحلفون بغير الله؟","title":"ما حكم الذين يحلفون بغير الله؟","answer":"الجواب: مثلما تقدم الحالف بغير الله من الشرك الأصغر، وعليهم التوبة إلى الله من ذلك، عليهم التوبة إلى الله من حلفه بغير الله، مثل: بالنبي، بالكعبة، بالأمانة، بشرف فلان، بحياة فلان، كله شرك، لكنه أصغر، فعليه التوبة إلى الله من ذلك، والندم، والإقلاع، والعزم ألا يعود في ذلك؛ لقوله ﷺ: من كان حالفًا فليحلف بالله أو ليصمت وقال ﷺ: من كان حالفًا فلا يحلف إلا بالله، أو ليصمت وقال -عليه الصلاة والسلام-: من حلف بشيء دون الله فقد أشرك. فالواجب الحلف بالله وحده، فإذا حلف بغيره صار مشركًا شركًا أصغر، وقد يكون أكبر إذا قام في قلبه تعظيم هذا الشخص، مثل تعظيم الله، أو اعتقد أنه يصح أن يعبد من دون الله يكون شركًا أكبر، بهذه النية، وبهذا القصد. فالمقصود: إذا جرى على لسانه هذا شركًا أصغر، أما إذا كان يرى أنه يصلح أن يعبد، ويدعى من دون الله، ويحلف به، وأنه يرى أن هذا أهل لذلك، أو يقوم بقلبه تعظيمه، مثلما يعظم الله بالعبادة هذا شرك أكبر، لكن جنس الحلف بغير الله شرك أصغر، ما لم يكن في قلبه تعظيم المخلوق، مثل تعظيم الله، بحيث يرى أنه يصلح للعبادة، يدعى أو يستغاث به أو يصلى له أو يصام له أو نحو ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13614/ما-حكم-الذين-يحلفون-بغير-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_494/49411.mp3","categories":["الطلاق","الأيمان والنذور","الحلف بغير الله"]},{"id":15121,"question":"تقول: أنا أدرس في الصف الثالث متوسط، حلفت أني إذا نجحت أصوم، وأعزم مدرساتي، هل أقوم بهذه الأوامر؟ علمًا بأني لا أستطيع الصيام، ولا أقدر على الصدقة. جزاكم الله خيرًا.","title":"حكم من حلفت أن تصوم إذا نجحت","answer":"الجواب: إذا حلفت المرأة، أو الذكر أنه إذا نجح يصوم كذا، أو يعزم المدرسين أو المدرسات، هو بالخيار، إن شاء كفر عن يمينه، وإن شاء صام وعزم، فإذا كان ما يستطيع الصيام، ولا يستطيع العزيمة، يكفر عن يمينه، والحمد لله، كفارة يمين: إطعام عشرة مساكين، أو كسوتهم، هذا ما يسمى نذر، هذا يمين، إذا قال: والله إذا نجحت أصوم ثلاثة أيام، أو عشرة أيام، والله إذا نجحت أعزم المدرسين، أو قالت الطالبة: والله إذا نجحت أصوم كذا، أو أعزم المدرسات، فهي بالخيار، إن صام أو صامت الطالبة، وعزموا المدرسين، الذكر، وعزمت المدرسات أدت يمينها، وهذا أحسن لها، من قدر هذا أحسن، يوفي بيمينه. أما إذا شق عليه ذلك، يكفر عن يمينه، والحمد لله، كفارة اليمين: إطعام عشرة مساكين، أو كسوتهم عشرة، كل واحد يعطى نصف الصاع، تمر أو رز، يعني: كيلو ونصف كل واحد، أو قميص مقطع يعطيه إياه، يكفي هذا، والحمد لله، عشرة. المقدم: نعم، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13621/حكم-من-حلفت-ان-تصوم-اذا-نجحت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_495/49505.mp3","categories":["الأيمان والنذور","قضايا المرأة"]},{"id":15132,"question":"هذه رسالة وردتنا من شخص متحير جدًا؛ لقرب عقد قرانه من رُبيِّع الجزار من أبناء مصر العربية، ومقيم في العراق، يقول: أرجو أن تعرض هذه الرسالة على من يتولى الإجابة في برنامج (نور على الدرب) يقول في رسالته:تعاركت مع رئيسي في العمل لبعض الأسباب؛ فقطع من راتبي خمسة أيام عقابًا لي، فأقسمت على أنه إذا أخذت الراتب ناقص فسوف أرسل برقية لرئيسه شكوى عليه، ولكنني لم أرسل برقية، وأخذت الراتب ناقصًا، والقسم هو: علي الطلاق بالثلاث من زوجتي إذا أخذت الراتب ناقصًا فسوف أرسل برقية لرئيسه، وكان هذا القسم أمام أربعة من زملائي بالعمل، وأخبر فضيلتكم بأنني عاقد قراني منذ ثمانية أشهر، ولم أدخل على زوجتي حتى الآن، فما هو حكم الدين؟جزاكم الله خير الجزاء.","title":"حكم من حلف بالطلاق أن يرفع شكوى برئيسه ولم يفعل","answer":"الجواب: لا ينبغي للمؤمن أن يقسم بالطلاق، ولا بالحرام، فإذا كان ولا بد فليقل: والله لأفعلن كذا، أو بالله لأفعلن كذا، وأما إقسامه بالطلاق والتحريم فلا ينبغي، وأقل أحواله الكراهة، لكن هذا الذي أقسم بالطلاق أنه يرفع الأمر إلى رئيس من خصم عليه بعض راتبه، إن كان قصد حث نفسه على الرفع، وإلزامها بذلك؛ فهذا حكمه اليمين، وعليه كفارة اليمين، وهي: إطعام عشرة مساكين أو كسوتهم، يعشيهم أو يغديهم أو يعطيهم على نصف الصاع من التمر أو الأرز من قوت البلد مقداره كيلو ونصف، أو يكسوهم كسوة تجزئهم الصلاة من قميص أو إزار ورداء، ويكفي ذلك. أما إن كان هذا الذي أقسم بالطلاق أراد إيقاع الطلاق، وأنه إن لم يرفع فإن زوجته تطلق منه؛ أراد إيقاع الطلاق بها إن لم يرفع إلى رئيس هذا الموظف، فإن كان قصد الطلاق يعني: قصد إيقاع الطلاق إن لم يفعل، فإنه يقع به طلقة واحدة، هذا هو الراجح، إذا قال: عليه الطلاق بالثلاث، فالصواب من أقوال العلماء أنه يقع به طلقة واحدة، ويراجعها في العدة إذا كان ما قبلها طلقتان، إذا كان لم يطلق قبل هذا طلقتين؛ فإنه يقع بهذا طلقة واحدة، وله مراجعتها ما زالت في العدة، ويشهد شاهدين يقول لهما: أشهدكما أني راجعت امرأتي فلانة، ويكفي. أما إن كان ما أراد إيقاع الطلاق على زوجته، إنما أراد حث نفسه وإلزامها بالشكوى، ولم يرد إيقاع الطلاق بزوجته أبدًا، فهذا ليس فيه إلا كفارة اليمين، نعم.","link":"https://binbaz.org.sa/fatwas/13634/حكم-من-حلف-بالطلاق-ان-يرفع-شكوى-برىيسه-ولم-يفعل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_657/nour_65705.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":15230,"question":"وردتنا رسالة من بيشة، من المرسلة (س. م. ج) تقول: نذرت امرأة أنه في حالة شفاء طفلها من المرض الذي أصيب به أن تصوم في كل شهر ثلاثة أيام طول الحياة، ماذا يجب عليها اليوم بعد أن صامت ما شاء الله من هذا النذر، ثم إنها تعرضت لمرض، وهي الآن أم لخمسة أطفال، لا تستطيع الصوم والوفاء بالنذر. نرجو التوضيح، جزيتم عنا خيرًا.","title":"حكم ترك صوم النذر لعذر المرض","answer":"الجواب:  يقول النبي ﷺ: من نذر أن يطيع الله فليطعه، ومن نذر أن يعصي الله فلا يعصه خرجه الإمام البخاري في صحيحه. والله مدح الموفين بالنذور، فقال -جل وعلا- : يُوفُونَ بِالنَّذْرِ وَيَخَافُونَ يَوْمًا كَانَ شَرُّهُ مُسْتَطِيرًا [الإنسان:7] وهذا من صفة الأبرار، وعباد الله الصالحين. فالواجب عليها أن توفي بنذرها؛ لأن الصيام ثلاثة أيام من كل شهر قربة وطاعة، الرسول -صلى الله عليه وسلم- حث عليها، ورغب فيها، فإذا نذرتها وجب عليها الأداء عند وجود الشرط، فإذا شفى الله مريضها وجب عليها أن توفي بالنذر، وإذا عجزت في بعض الشهور بسبب مرض أصابها تقضي مثل ما يقضى رمضان، تقضي الثلاثة أيام من شهر آخر عندما تصح، وإذا عجزت بالكلية في آخر عمرها، فإنها تطعم عن كل يوم مسكينًا، كرمضان كما إذا عجزت عن رمضان تطعم عن كل يوم مسكينًا، فهكذا هذه الأيام الثلاثة إذا عجزت عنها بسبب كبر السن فإنها تفعل كما تفعل في صيام رمضان، نعم.","link":"https://binbaz.org.sa/fatwas/13744/حكم-ترك-صوم-النذر-لعذر-المرض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_673/nour_67306.mp3","categories":["الأيمان والنذور"]},{"id":15242,"question":"المستمع حفظالله الشعيبي، من اليمن، بعث يسأل ويقول: حدث في يوم من الأيام مشاجرة بيني وبين زوجتي في موضوع غسل ملابسي، وبعد ذلك تناوشنا مع بعض بغضب شديد، وفي ساعة هذا الغضب قلت: علي الطلاق ما تغسلي ملابسي مرة ثانية، ومن ذلك الوقت أغسل ملابسي في المغسلة خارج البيت، هل إذا أردت أن تغسل زوجتي ملابسي بعد اليمين؛ لأنني محتاج لذلك؟ هل إذا أردت أن تغسل ملابسي أن أتصرف بتصرف معين؟أرجو أن تفيدوني، جزاكم الله خيرًا.","title":"حكم من حلف بالطلاق ألا تغسل زوجته ملابسه","answer":"الجواب: هذا يختلف بحسب نيتك، وما كان ينبغي لك التعجل بالطلاق، نصيحتي لكل زوج أن لا يتعجل بالطلاق، ولو غضب يقول: أعوذ بالله من الشيطان الرجيم، ولا يعجل في الطلاق أبدًا، ولو شدت عليه المرأة، ولو غضبت ولو طلبت لا يعجل في الطلاق، الشيطان يحضر ويزين لها ويزين لزوجها الطلاق. فالمشروع لك يا أخي، ولكل إنسان عدم العجلة في الطلاق حتى تطمئن، وحتى تعلم أن الطلاق أصلح لدينك ودنياك فلا بأس. ونصيحتي لكل امرأة أن تتقي الله، ولا تعجل في طلب الطلاق، ولا تؤذي زوجها في ذلك، ولا سيما إذا كان زوجها طيبًا صاحب دين، وصاحب صلاح، تتقي الله، ولا تعجل في الأمور، تصبر عليه، ولو أبغضها في بعض الأحيان، ولو حصل منه بعض الأذى في بعض الأحيان؛ لأن الزوج الصالح اليوم قليل، والزوجة الصالحة قليلة، فينبغي للمؤمن أن يتمسك بالزوجة الصالحة، ولا يعجل في الطلاق، ولو جرى منها بعض النقص، وهكذا المرأة إذا حصلت الزوج الصالح، فينبغي لها أن تتمسك به، وتحرص على البقاء معه، وأن لا تغضبه أبدًا، بل تتحمل، وتحرص على التحمل، فإذا غضبت تقول: أعوذ بالله من الشيطان الرجيم، وهي كذلك تقول: أعوذ بالله من الشيطان الرجيم، كرروا هذا عند الغضب ويزول الغضب؛ لما رأى النبي ﷺ شخصًا قد غضب واحمرت أوداجه من شدة الغضب قال: إني لأعلم كلمة لو قالها لذهب عنه ما يجد: أعوذ بالله من الشيطان الرجيم فأنت -يا أخي- كذلك استعذ بالله من الشيطان الرجيم. وهذا الطلاق الذي وقع منك يختلف بحسب نيتك، إن كنت نويت منعها من غسلها الملابس بعد ذلك، وأنك تستغني عنها، وأردت تخويفها وتهديدها بهذا الطلاق، فلك أن تسمح عنها، وتكفر عن يمينك، له حكم اليمين، إذا كنت قصدك منعها من الغسل غضبًا عليها، ولم ترد فراقها إن غسلت ثيابك، إنما أردت تهديدها بهذا، والشره عليها والغضب عليها، ولم ترد فراقها بهذا لو غسلت، فهذا حكمه حكم اليمين، وعليك كفارة اليمين، وهي إطعام عشرة مساكين، إطعام عشرة، كل واحد يعطى نصف الصاع، تمر أو رز كيلو ونصف كل واحد، أو كسوة على قميص قميص، أو عتق رقبة، فمن عجز يصوم ثلاثة أيام. أما إن كنت أردت الطلاق، أردت إيقاع الطلاق عليها إن غسلت يقع طلقة واحدة، إذا كنت أردت إيقاع الطلاق إن غسلت ثيابك، فإنها إذا غسلتها يقع عليها طلقة واحدة وتراجعها، تقول: اشهد يا فلان وفلان أني مراجع زوجتي، تشهد اثنين من الطيبين من جيرانك أو أصحابك أنك مراجعها، هكذا السنة إذا كان ما قبلها طلقتان، إذا كنت ما طلقتها قبلها طلقتين، أما إذا كان قبلها طلقتين ما تصلح إلا بعد زوج، لكن إذا كنت ما طلقتها قبلها طلقتين، وأنت أردت الطلاق إذا غسلت ثيابك تكون طلقة واحدة، وتراجعها بإشهاد اثنين، تقول: اشهد يا فلان وفلان أني راجعت زوجتي فلانة، ما دامت في العدة. أما إن كنت ما أردت الطلاق مثلما تقدم، وإنما أردت منعها والغضب عليها وتهديدها حتى لا تغسل ثيابك مرة أخرى من أجل غضبك، ولم ترد إيقاع الطلاق، ولا فراقها، ولكن أردت المنع، فهذا حكمه حكم اليمين، وعليك كفارة اليمين، وهي إطعام عشرة مساكين غداء أو عشاء، أو تعطي كل واحد نصف الصاع كيلو ونصف كل واحد من التمر أو الحنطة أو غيرهما من قوت البلد، وفق الله الجميع. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13739/حكم-من-حلف-بالطلاق-الا-تغسل-زوجته-ملابسه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_497/49705.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":15244,"question":"هذا سؤال بعث به المستمع سليمان محمد اللهيبي من العراق، يقول: عندنا عندما يمرض شخص يذهب إلى السادة، ويكتبون له أوراقًا يعلقونها في رؤوسهم، فهل يجوز هذا أم لا؟كذلك الحلف هناك من يحلف بغير الله أو يحلفون بهؤلاء السادة، فما حكم ذلك؟","title":"ما حكم تعليق التمائم والحلف بغير الله؟","answer":"الجواب: تعليق التمائم على الأولاد خوف العين، أو خوف الجن أمر لا يجوز، وهكذا تعليق التمائم على المرضى، وإن كانوا كبارًا لا يجوز؛ لأن هذا فيه نوع من التعلق على غير الله، فلا يجوز لا مع السادة المنسوبين إلى الحسن أو الحسين أو غيرهما، ولا مع غيرهم من العلماء، ولا مع غيرهم من العباد، لا يجوز هذا أبدًا؛ لما ثبت عن النبي ﷺ أنه قال: من تعلق تميمة فلا أتم الله له، ومن تعلق ودعة فلا ودع الله له وفي رواية عنه -عليه الصلاة والسلام- أنه قال: من تعلق تميمة فقد أشرك والتميمة: هي ما يعلق على الأولاد أو على الكبار عن العين أو عن الجن من خرز أو ودع أو عظام ذئب أو غيره، أو أوراق مكتوب فيها كتابات، حتى ولو من القرآن على الصحيح، حتى ولو آية الكرسي أو غيرها، لا يجوز التعليق مطلقًا، ولو كان من القرآن؛ لأن الأحاديث عامة، الرسول ﷺ عمم وأطلق، ولم يستثن شيئًا، فدل ذلك على أن التمائم كلها ممنوعة، وهي ما يعلق على الأولاد عن العين، أو عن الجن أو يعلق على المرضى الكبار كله لا يجوز. والمشروع في هذا أن الإنسان يسأل ربه العافية، لا بأس أن يقرأ عليه يقرأ عليه المؤمن العارف بالقراءة يقرأ عليه آيات، يدعو له بدعوات شرعية، ينفث عليه رقية طيبة هذا لا بأس، أما أنه يعلق شيئًا في قرطاس، أو في رقعة في عضده أو في رقبته هذا لا يجوز، وهذا من الشرك الأصغر يعتبر من الشرك الأصغر، وقد يكون من الأكبر إذا اعتقد صاحبه أنها تدفع عنه، وأنها تكفيه الشرور، هذا يكون من الشرك الأكبر، أما إذا اعتقد أنها من الأسباب فهذا شرك أصغر، والواجب قطعها وإزالتها. وكذلك الحلف بغير الله لا يجوز، وهو من الشرك الأصغر أيضًا، وقد يكون من الشرك الأكبر إذا اعتقد الحالف بغير الله أن هذا محلوفه مثل الله، أو أنه يصح أن يدعى من دون الله، أو أنه يتصرف في الكون يكون شركًا أكبر نعوذ بالله. فالحاصل: أن الحلف بغير الله لا يجوز، قال النبي ﷺ: من كان حالفًا فليحلف بالله أو ليصمت وقال: لا تحلفوا بآبائكم ولا بأمهاتكم ولا بالأنداد وقال -عليه الصلاة والسلام-: من حلف بغير الله فقد كفر وفي رواية: فقد أشرك وقال أيضًا -عليه الصلاة والسلام-: من حلف بالأمانة فليس منا وأدرك يومًا بعض أصحابه في السفر وهم يحلفون بآبائهم فقال لهم -عليه الصلاة والسلام-: إن الله ينهاكم أن تحلفوا بآبائكم، من كان حالفًا فلا يحلف إلا بالله أو ليصمت وقال ابن عبد البر النمري المعروف الإمام المغربي المعروف المتوفى سنة أربعمائة وثلاثًا وستين هجرية: إن العلماء أجمعوا على أنه لا يجوز الحلف بغير الله. فهذا يفيدنا أن الحلف بالأمانة أو بالنبي ﷺ أو بالكعبة أو بحياة فلان أو شرف فلان هذا لا يجوز، وإنما يكون بالله وحده، يقول: بالله، تالله، والله، هذا هو المشروع، أما الحلف بغير الله كائنًا من كان فلا يجوز، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13749/ما-حكم-تعليق-التماىم-والحلف-بغير-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_670/nour_67002.mp3","categories":["الأيمان والنذور","الحلف بغير الله"]},{"id":15277,"question":"سؤاله الآخر يقول: رجل عليه نذر منذ عام 1394هـ، وقد قام بعقيقة ابنه بدلًا من شاتين ذبح شاة واحدة، وأدخل النذر معها نية منه، ولم يخبر الذين دعاهم إلى هذه الوليمة، فهل يعتبر وفى بنذره أم لا؟","title":"حكم الذبح بنية العقيقة والوفاء بالنذر","answer":"الجواب: النذر يختلف: إن كان نذر شاة يذبحها في بيته لأقاربه وجيرانه وضيوفه، فهذا إذا ذبحها بنية النذر، وقدمها لضيوفه فلا بأس، أما إذا كان نذر نذرًا مطلقًا، ما أراد به أهل بيته ولا قراباته ولا ضيوفه، أو نذر نذرًا أراد به الفقراء، فإنه لا يفي حتى يوصلها للفقراء، فإن النذور مصروفها الفقراء، فإذا كان ما له نية خاصة، فإنه يعطي النذر للفقراء، الشاة يشتريها ويعطيها الفقراء، إذا كان النذر شاة مثلًا، أو بعيرًا، أو بقرة يذبحها ويقسمها بين الفقراء.  إلا إذا كان له نية خاصة، بأن قال مثلًا: لله علي إن رزقني الله ولدًا ذكرًا أن أذبح شاة أو بقرة أو بعيرًا وفي نيته أنه يذبحها لأهل بيته وجيرانه فهو على نيته، وإن كان ما له نية فإنها تعطى الفقراء تقسم بين الفقراء، ولا يأكلها هو، ولا أهل بيته، ولا ضيوفه، نعم.\nالمقدم: يعني: إشراكه النذر مع العقيقة؟\nالشيخ: ما يصلح.\nالمقدم: هذا...\nالشيخ: النذر مستقل، والعقيقة مستقلة، العقيقة سنة مستقلة، والنذر واجب مستقل.\nالمقدم: وهذا ما فعله هو.\nالشيخ: فإذا فعل إحدى الشاتين عن شاة عليه بالنذر، فينظر في نيته، إن كان نوى الشاة التي بالنذر أنه يذبحها في بيته للضيوف والأقارب والجيران فقد وفى، وفى بهذا الشيء حيث قدمها لضيوفه ومع أهل بيته.  وأما إن كان ما قصد هذا الشيء بل نذر ولا في نيته هذا الشيء، فالنذور مصروفها الفقراء، ما تجزئ هذه التي ذبحها في العقيقة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13782/حكم-الذبح-بنية-العقيقة-والوفاء-بالنذر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_675/nour_67504.mp3","categories":["الأيمان والنذور"]},{"id":15288,"question":"هذان سؤالان من السائل (أ. ش) من الرياض، يقول: قال رجل لصديق له: علي الطلاق ألا تشتري الثلاجة والغسالة إذا عزمت على الزواج، يقصد أنه هو الذي سيشتريهما ويهديهما إليه، فهل يجوز أن يعطيه قيمتهما مقدمًا نقدًا؟","title":"حكم من حلف بالطلاق أن يشتري لصديقه شيئًا ثم أعطاه قيمته","answer":"الجواب: الذي يظهر أنه لا حرج في ذلك، إذا شراها بنفسه، أو سلم له القيمة، اشتراها، إذا كان مقصوده مساعدته بالثمن، وليس مقصوده نفس الشراء، إنما المقصود أن يساعده في الثمن، فإذا شراها بنفسه، أو بوكيله، أو شراها صاحب الحاجة، وسلم له ثمنها، فالأمر في هذا واسع، ولا يقع عليه شيء بذلك؛ لأن طلاقه قد حصل به المقصود؛ لأن الشرط المطلوب قد حصل، نعم.\nالمقدم: إنما لو حصل وسبقه هذا الشخص واشتراهما؟\nالشيخ: إذا كان المقصود أن يساعده بالثمن هذا المقصود، وسلم له الثمن فإنه قد وفى بيمينه.\nالمقدم: حتى لو اشتراه.\nالشيخ: حتى لو اشتراها له.\nالمقدم: سؤاله الآخر يقول: رجل عليه نذر منذ عام ألف وثلاثمائة وأربعة وتسعين هجري.....\nالشيخ: ويتعلق بالسؤال الأول أمر آخر قد يخفى على بعض الناس، وهو أنه إذا كان مقصوده بالطلاق منعه من الشراء، وحثه على قبول الهدية، وليس قصده فراق زوجته إن لم يسمح له بالشراء، فإن هذا الطلاق في حكم اليمين، فلو فرضنا أن الرجل ما سمح واشتراها هو، ولم يقبل الثمن فإن الطلاق لا يقع، وعليه كفارة اليمين إذا كان مقصوده نفعه بهذا الشيء، وحثه على قبول الهدية، وليس مقصوده فراق زوجته إن لم يقبل، وإنما المقصود مقصود اليمين يعني: حث الرجل على قبول الهدية، أو قبول الثمن، وليس المقصود فراق أهله إن لم يقبل، فهذا له حكم اليمين، فلو لم يقبل صاحب الزواج شراء الشخص للثلاجة والغسالة، أو لم يقبل الثمن، فإن الرجل لا يقع على زوجته طلاق؛ لأنه ليس المقصود إيقاع الطلاق، المقصود: حث الرجل على قبول الهدية هذه، ولكن يكفيه كفارة اليمين، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13780/حكم-من-حلف-بالطلاق-ان-يشتري-لصديقه-شيىا-ثم-اعطاه-قيمته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_675/nour_67503.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":15299,"question":"أيها الإخوة، أول رسالة نستعرضها اليوم وردت إلينا من المستمع عمر محمود، من جمهورية مصر العربية الشرقية، يقول: لي زوجة طيبة مطيعة وقورة، وهي تذهب إلى العمل في غير ما تبرج ولا زينة، ولكني أنا لست راضٍ عن عملها هذا، ولا أريد منها الذهاب، واختلفنا على ذلك، وحلفت عليها بالطلاق بقولي: علي الطلاق ما أنت ذاهبة إلى العمل مرة أخرى.الشيخ: علي...؟المقدم: علي الطلاق ما أنت ذاهبة إلى العمل مرة أخرى، وكررت هذه الكلمة مرتين، وفي الثالثة قلت: علي الطلاق بالثلاث ما أنت ذاهبة إلى الشغل في السنة القادمة، وكان ذلك في جلسة واحدة، وكان غرضي ونيتي هو المنع من العمل، وكانت هي في ذلك الوقت في إجازة وضع لمدة ثلاثة أشهر، وكنت أريد أن نستفيد من مرتبها خلال هذه الإجازة في تسديد ديوننا، وبعدها لن تذهب إلى العمل، ولم تذهب إلى العمل في هذه المدة، وكانوا يرسلون إليها مرتبها، وبعدما انتهت مدة إجازتها، وحان وقت عودتها إلى العمل، ناقشني أحد أقاربي في ذلك بقصد رغبته في ذهابها إلى العمل، فقلت له: علي الطلاق ما هي ذاهبة، وكررت هذا اللفظ مرة أخرى، وكان ذلك أيضًا في جلسة واحدة، وكان غرضي ونيتي هذه المرة هو الطلاق إن هي ذهبت إلى العمل.الشيخ: أعد.المقدم: نعم.الشيخ: أعد.المقدم: يقول: وبعدما انتهت مدة إجازتها، وحان وقت عودتها إلى العمل، ناقشني أحد أقاربي في ذلك، أي: يريد أن تذهب إلى العمل، فقلت له: علي الطلاق ما هي ذاهبة الشغل، وكررت هذا اللفظ مرة أخرى، وكان ذلك في جلسة واحدة، وكان غرضي ونيتي هذه المرة هو الطلاق إن هي ذهبت إلى العمل.وفي اليوم المحدد لعودتها إلى العمل قلت لها: إن ذهبت الشغل فلن تكوني زوجة لي، كتأكيد ليميني السابق، ولكنها ذهبت إلى العمل، فما الذي يأمرني به ديني في هذه الحالة؟ وهل هذه الأيمان طلاقًا رجعيًا أم طلاقًا بائنًا لا رجعة فيه، مع العلم أنها الآن تعيش معي، وتتمسك بالبقاء معي، وترفض مغادرة منزلي، والذهاب إلى منزل أبيها.","title":"حكم الحلف بالطلاق بنية المنع وتكراره بنية الطلاق","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فإن الواجب على المرأة السمع والطاعة لزوجها فيما أباح الله، لا في المعصية، وكونه السائل منعها من الذهاب إلى العمل هذا ليس بمعصية، بل أمر له حق فيه، فالواجب عليها أن تسمع وتطيع له في ذلك، وألا تذهب إلى العمل، وقد نوى في الطلاق الأول المنع فقط، فيكون عليه في ذلك كفارة يمين بسبب ذهابها إلى العمل؛ لأنه لم يقصد إلا منعها فقط، وهذا هو الصواب من قولي العلماء فيما إذا علق الزوج الطلاق على أمر يقصد منعًا منه، أو الحمل عليه، أو التصديق أو التكذيب، هذا هو المختار عند جمع من أهل العلم.  أما طلاقه الأخير فقد أراد به إيقاع الطلاق وقد كرره مرتين.\nوالجواب عن ذلك: إن كان أراد به التكرار إيقاع الطلاق في المرة الثانية كالأولى، وقد وقع عليها طلقتان، وبقي لها واحدة، وله مراجعتها ما دامت في العدة، وإن كان لم يرد إيقاع الطلاق في المرة الثانية حين كرر، وإنما أراد تأكيد الكلام السابق، أو إفهامها فإنه لا يقع بذلك إلا طلقة واحدة، ويبقى لها طلقتان، وله مراجعتها ما دامت في العدة؛ لقول النبي ﷺ: إنما الأعمال بالنيات، وإنما لكل امرئ ما نوى وقد نوى في الطلاق الأخير إيقاع الطلاق فيقع ما قال، والله  ولي التوفيق، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13801/حكم-الحلف-بالطلاق-بنية-المنع-وتكراره-بنية-الطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_676/nour_67601.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":15323,"question":"هذه عدة أسئلة، بعث بها المستمع مسعود عبدالله، المولد من وادي الفرع، بالمدينة المنورة، يقول: أولًا: من نذر ولم يستطع الوفاء بنذره فماذا يجب عليه؟","title":"حكم من نذر ولم يستطع الوفاء بنذره","answer":"الجواب: هذا فيه تفصيل: إن نذر طاعة فعليه أن يوفي بها، كأن ينذر صلاة أو صومًا أو نحو ذلك؛ لقول النبي ﷺ: من نذر أن يطيع الله فليطعه أما من نذر مكروهًا كأن يقول: لله أن يصوم سنة كاملة، أو يصوم الأبد، هذا نذر مكروه، لا ينبغي، فعليه كفارة يمين عن هذا الشيء، عليه كفارة يمين. أما إن نذر نذرًا لا يطيقه، بأن قال: لله عليه أن يتصدق بمليون ريال، وهو ما يستطيع مليون، ولا ما يقارب مليون، عليه يكفر كفارة يمين، إن كان نذرًا لا يطيقه، فعليه كفارة يمين، إذا كان لا يطيق ذلك، ولا يظن أنه يطيق ذلك، فإن كان يمكن أن يحصل ذلك يكون دينًا في ذمته، كأن يقول: لله عليه أن يتصدق بألف ريال، وليس حاضرًا، فإن هذا دين في ذمته، يسعى في تحصيله فمتى حصله، وتيسر له تصدق به.  أما إذا كان الشيء يعني في المستحيل عادة أن يقوم به، أو يستطيعه، فهذا يكفيه كفارة يمين. المقدم: نعم.","link":"https://binbaz.org.sa/fatwas/13833/حكم-من-نذر-ولم-يستطع-الوفاء-بنذره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_677/nour_67706.mp3","categories":["الأيمان والنذور"]},{"id":15347,"question":"هذا سائل للبرنامج الحقيقة أرسل بمجموعة من الأسئلة، أبو محمد، سوداني، ومقيم بعفيف، يقول في سؤاله هذا: رجل حلف بالطلاق ألا يفعل شيئًا، ولكنه فعل ذلك ماذا عليه؟ علمًا بأنه عندما حلف أراد بذلك أن يلزم نفسه بعدم فعل ذلك الشيء، فأفيدونا، مأجورين.","title":"حكم من حلف بالطلاق ألا يفعل شيئًا معينًا ثم فعله","answer":"الجواب: إذا حلف بالطلاق بأن قال مثلًا: عليه الطلاق ألا يكلم فلانًا قصده الامتناع منه، أو عليه الطلاق ألا يسافر، ثم سافر، ومقصوده الامتناع ليس قصده سوى ذلك، فهذا فيه كفارة اليمين، ليس فيه إلا كفارة يمين، حكمه حكم اليمين؛ لأن قصده الحث والمنع؛ فيكون عليه كفارة اليمين. ومثله لو قال: عليه الطلاق إن فعلت زوجتي كذا وكذا. قصده منعها، أو عليه الطلاق إن فعل فلان كذا، قصده منعه، فهذا حكمه حكم اليمين، نسأل الله العافية، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13850/حكم-من-حلف-بالطلاق-الا-يفعل-شيىا-معينا-ثم-فعله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_566/56620.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":15353,"question":"المستمع ياسر مبارك، بعث يسأل ويقول: لقد عاهدت الله تعالى على شيء ألا أفعله، لكني فعلت ذلك الشيء وأجبرتني الظروف -كما يقول- ويرجو التوجيه، وبيان الحكم، وهل عليه شيء؟جزاكم الله خيرًا.","title":"ما يلزم من عاهد الله على ترك شيء ثم فعله؟","answer":"الجواب: إذا كان السائل قد حلف فعليه كفارة اليمين، أما مجرد المعاهدة فليس فيها كفارة، إلا أن يكون المفعول حرامًا، فعليه التوبة إلى الله من ذلك، ولو لم يفعل عهدًا، إذا كان حرامًا عاهد الله ألا يشرب الخمر، ألا يزني، ألا يتعاطى التدخين، ألا يحلق لحيته، ثم فعل، فإن عليه التوبة من ذلك؛ لأن هذه معاصٍ عليه التوبة إلى الله منها، حتى ولو ما عاهد. لكن إن كان حلف قال: والله لا أفعل، ثم فعل، عليه كفارة اليمين، مع التوبة إلى الله . وأما إذا كان إنما جرى منه عهد فقط، وليس فيه يمين، فليس فيه كفارة، وإنما عليه التوبة إلى الله مما فعله إذا كان المفعول معصية، أما إذا كان المفعول غير معصية، إذا عاهد الله أنه ما يزور فلانًا، أو ما يسافر إلى بلد فلان على وجه ليس فيه معصية، فهذا ما يضر، وليس عليه إلا اليمين، كفارة اليمين، وإنما التوبة تكون بالسير في معصية، فإذا كان عاهد الله ألا يزور رحمًا له، هذا من باب القطيعة، فعليه التوبة إلى الله من ذلك، وإذا كان عاهد الله ألا يسافر لأداء الحج، أو لأداء العمرة، فهذه معصية، فعليه التوبة إلى الله من ذلك، وإذا كان فيه يمين عليه كفارة اليمين، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13856/ما-يلزم-من-عاهد-الله-على-ترك-شيء-ثم-فعله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_498/49803.mp3","categories":["الأيمان والنذور"]},{"id":15372,"question":"محمد حامد من دمشق، يقول: فضيلة الشيخ، أمد الله بعمركم على طاعة الله، سؤالي هو كالتالي: بأنني اعتدت على أن أحلف يمينًا عندما أغضب وأزعل من أي شيء، سواء في العمل أو في المنزل، وأقول: علي الطلاق، أو علي الحرام بأن هذا كذا وكذا، وصار هذا اليمين عادة في يومي وليلتي أردده باستمرار، حاولت التخلص منه، ولكنني لم أستطع، فبماذا تنصحونني؟ وما حكم هذا اليمين يا سماحة الشيخ؟","title":"توجيه لمن يكثر الحلف بالطلاق والحرام","answer":"الجواب: نوصيك بالحذر من هذا، وعدم اعتياده، نوصيك بترك اليمين بالطلاق والتحريم، هذا الذي نوصيك به، وإذا فعلت ذلك وأنت صادق، فليس عليك شيء، قلت: علي الطلاق إن فلان سافر، علي الطلاق إني ما فعلت كذا، وأنت صادق لا شيء عليك، أو علي الحرام إني ما أفعل كذا، ولم تفعله، أو علي الحرام إن فلان قد سافر، أو علي الحرام أني ما أكلت كذا، وأنت صادق لا شيء عليك. أما إذا قلته تريد المنع، تقول: علي الطلاق ما تقومين يا فلانة من كذا، علي الطلاق ما تروحين لأهلك، وأنت قصدك منعها، فهذا حكمه حكم اليمين، عليك كفارة اليمين، أو علي الحرام إني ما أكل هذا الشيء وأكلته، قصدك الامتناع منه، فعليك كفارة اليمين، أو عليك الحرام ما تزور فلانًا، ثم زرته، وأنت قصدك الامتناع من زيارته، عليك كفارة اليمين والحمد لله، وعليك الاستغفار من ذكر التحريم، نعم. المقدم: أحسن الله إليكم، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/13875/توجيه-لمن-يكثر-الحلف-بالطلاق-والحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_567/56703.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":15421,"question":"أيها الإخوة في حلقتنا اليوم نستعرض أول سؤال ورد من المستمع عبدالوهاب أحمد من العراق، نينوى، يقول في سؤاله الأول:قبل ثلاث سنوات نذرت لوجه الله تعالى نذرًا، فقلت: علي نذر أن أضع دينارًا عراقيًا كل شهر في قبر النبي يونس ، مع العلم أن المبالغ التي توضع في القبر تؤخذ، فهل هذا النذر صحيح وجائز، وأستمر على تنفيذه أم أتوقف أم أعطيه للفقراء كل شهر؟ وما الحكم إذا توقفت عن وضعه وعدم إعطائه للفقراء؟ وما هي كفارة ذلك؟أفيدوني، أثابكم الله.","title":"حكم النذور لقبور الأنبياء والصالحين وغيرهم","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فقد أجمع أهل العلم على أن النذر لا يجوز لغير الله كائنًا من كان؛ لأنه عبادة وقربة إلى الله ، والناذر يعظم المنذور له بهذا النذر، والنذر للأموات من الأنبياء وغير الأنبياء شرك أكبر، من نذر أن يقدم دراهمًا أو دنانيرًا أو أطعمة أو زيتًا، أو غير ذلك للقبور أو للأصنام أو لغيرها من المعبودات من دون الله يكون نذرًا باطلًا، ويكون شركًا أكبر. فالواجب عليك في هذا أن تدع هذا العمل؛ لأنه نذر باطل، وعليك التوبة إلى الله ، فإن تقديم النذر لقبر النبي يونس مقصوده القربة التقرب إليه بهذا النذر، وطلب الزلفى لديه، أو طلب شفاعته، أو طلب شفاء المرضى، أو كذا أو كذا، وهذا كله باطل، ولا يجوز النذر إلا لله وحده ، وقد قال النبي ﷺ في الحديث الصحيح: من نذر أن يطيع الله فليطعه، ومن نذر أن يعصي الله فلا يعصه خرجه البخاري في صحيحه من حديث عائشة -رضي الله عنها-. والله يقول سبحانه: وَمَا أَنفَقْتُمْ مِنْ نَفَقَةٍ أَوْ نَذَرْتُمْ مِنْ نَذْرٍ فَإِنَّ اللَّهَ يَعْلَمُهُ وَمَا لِلظَّالِمِينَ مِنْ أَنصَارٍ[البقرة:270].\nفالنذر الشرعي مدح الله الموفين به، كالنذر أن تصلي أو تصوم أو تتصدق لله هذا نذر شرعي، قال سبحانه: يُوفُونَ بِالنَّذْرِ وَيَخَافُونَ يَوْمًا كَانَ شَرُّهُ مُسْتَطِيرًا[الإنسان:7] مدح المؤمنين بهذا الوفاء. أما النذور التي للقبور والأشجار والأحجار أو للأصنام أو للكواكب أو للجن أو للأنبياء أو الأولياء كلها باطلة، كلها نذور باطلة؛ لأنها عبادة والعبادة لله وحده، قال تعالى: وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ[الإسراء:23] قال سبحانه: وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ[البينة:5] قال : وَمَا خَلَقْتُ الْجِنَّ وَالإِنسَ إِلَّا لِيَعْبُدُونِ[الذاريات:56] وقال سبحانه: إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ[الفاتحة:5]، فبادر بالتوبة إلى الله، واستغفر الله ، واحفظ مالك، ولا تقدمه إلا في شيء يرضي الله، كالصدقة على الفقراء والمساكين، وصلة الرحم، وتعمير المساجد ودورات المياه حولها، ونحو ذلك مما ينفع المسلمين. أما النذور للقبور أو للجن أو للأصنام أو الأشجار والأحجار أو للكواكب كلها نذور باطلة، لا يجوز تنفيذها بالكلية، وهي قربة لغير الله، وعبادة لغير الله، وشرك بالله ، رزقنا الله وإياك الهداية والبصيرة، ومنَّ علينا وعليك بالتوبة النصوح، إنه -جل وعلا- جواد كريم.\nالمقدم: اللهم آمين. بالنسبة لصحة مكان قبر يونس  هل هو فعلًا في العراق؟ الشيخ: أما يونس فلا يعرف قبره، وليس لهذا صحة، بل جميع قبور الأنبياء لا تعرف، ما عدا قبر نبينا -عليه الصلاة والسلام-، فإنه معلوم في بيته في المدينة -عليه الصلاة والسلام-، وهكذا قبر خليل الله إبراهيم، معروف في المغارة هناك في الخليل في فلسطين، وأما سواهما، فقد بيَّن أهل العلم أنها لا تعلم قبورهم، ومن ادعى أن هذا قبر فلان، أو قبر فلان، فهو كذب لا أصل له، ولا صحة له، ودعوى أن قبر يونس موجود في نينوى، وأنه المحل المعين لا أصل له، فينبغي أن يعلم هذا. المقدم: أثابكم الله.","link":"https://binbaz.org.sa/fatwas/13932/حكم-النذور-لقبور-الانبياء-والصالحين-وغيرهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_685/nour_68501.mp3","categories":["الأيمان والنذور"]},{"id":15453,"question":"هذه رسالة من المستمع مصطفى رمضان علي رمضان، من الجمهورية العربية اليمنية، يقول: كنت أريد فعل شيء من زوجتي، وأقسمت عليها يمينًا هذا نصه: علي الطلاق لو ما جئت بهذا الشيء؛ لتكوني طالقة، فلم تحضر هذا الشيء الذي كنت أريده. ثم أقسمت يمينًا بالطلاق شافعي ومالكي وأبي حنيفة بيني وبين شريك لي في أرض، وكانت زوجتي جالسةً في هذا المجلس، حيث قلت في هذا اليمين: علي الطلاق شافعي ومالكي وأبو حنيفة لأبيع هذه الأرض بعد هذه الزرعة، ومرت الزرعة والأخرى، ولم تبع الأرض، وأنا في أثناء اليمين كنت أشير بيدي على زوجتي. ثم أقسمت يمينًا بالطلاق على زوجتي بأن ترد علي بالنداء بقول: نعم، حينما أناديها في كل مرة، وهذا نصه: علي الطلاق لو لم تقولي: نعم كلما أناديك لتكوني مطلقة، فأحيانًا تقول، وأحيانًا لا تقول، أفيدونا بارك الله فيكم عن الحل في هذه الأيمان، مع عزمي على التوبة من هذه الأقوال؟جزاكم الله خير الجزاء.","title":"حكم من حلف بالطلاق في وقائع مختلفة","answer":"الجواب: هذا غلط منك، استعمال الطلاق هكذا تلاعب لا خير فيه، غلط منك في هذا -أيها السائل-، ولا ينبغي منك استعمال هذا الطلاق، وأبغض الحلال إلى الله الطلاق، فلا ينبغي للمؤمن أن يستعمل الطلاق هكذا، بل يخاطب بغير الطلاق باليمين بالله بالتأكيد بدون يمين، أما هذا العمل هو عمل لا ينبغي منك، ولا ينبغي منك العود إليه. أما الحكم، فإن كنت أردت حكم اليمين، يعني: أردت التأكيد عليها أنها ترد عليك بنعم، والتأكيد أن تبيع الأرض، والتأكيد عليها أن تأتي بالحاجة، ولم ترد إيقاع الطلاق، إنما أردت التأكيد في هذا الأمر، والتشديد على نفسك، ولم ترد إيقاع الطلاق، ولكن للتأكيد على نفسك أن تبيع أو للتأكيد على زوجتك أنها تأتي بالحاجة أو تقول: نعم، ولم تقصد إيقاع الطلاق عليها وفراقها، فهذا حكمه حكم اليمين، فعليك في كل واحدة كفارة يمين في الحاجة وفي قول: نعم، وفي بيع الأرض عليك كفارة يمين، وهي إطعام عشرة مساكين أو كسوتهم أو عتق رقبة، والإطعام نصف صاع من قوت البلد، مقداره كيلو ونصف من تمر أو أرز أو ذرة، إن كانت قوت البلد، أو دخن إن كانت قوت البلد، أو بر، أو تكسو الفقراء عشرة، كل واحد يعطى قميصًا أو إزارًا ورداءً، أو عتق رقبة مؤمنة، فإن عجزت عن هذا كله تصوم ثلاثة أيام عن كل يمين. فطلاقك لها أن تأتي بالحاجة، ولم تأت بها؛ هذه يمين، والطلاق عليها أنها تقول: نعم يمين، والطلاق على بيع الأرض يمين، هذا إذا كنت ما أردت إلا التأكيد والتشديد على نفسك أنك تبيع الأرض، والتشديد عليها أنها تقول: نعم، والتأكيد عليها أنها تأتي بالحاجة، ولا أردت فراقها، وإيقاع الطلاق عليها في هذه المسائل، هذا فيه كفارة يمين، ثلاث كفارات. أما إن كنت أردت إيقاع الطلاق فيها، أو في إحداها، يقع الطلاق، أنت أردت الطلاق في مسألة الأرض، ما بعتها فالزوجة طالق، يقع عليها الطلاق، فيقع عليها الطلاق، وهكذا مسألة قول: نعم ومسألة الحاجة إن أردت إيقاع الطلاق، وقع الطلاق وعلى حسب. والطلقة الواحدة فيها مراجعة، الطلقة الثانية فيها مراجعة، والثالثة الأخيرة ليس فيها مراجعة تنتهي، تكون قد بانت منك حتى تنكح زوجًا غيرك في الطلقة الأخيرة الثالثة، إذا كنت أردت إيقاع الطلاق في المسائل هذه، فعند الأخيرة إن كان الأخيرة الأرض، أو قول: نعم، أو المسألة الأولى الحاجة الأخيرة منهم من هذه الثلاث تكون هي النهاية، فلا تصلح إلا بعد زوج، إذا كنت أردت إيقاع الطلاق في المسائل الثلاث، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/13983/حكم-من-حلف-بالطلاق-في-وقاىع-مختلفة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_687/nour_68703.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":15454,"question":"هذه رسالة من المستمع مصطفى رمضان علي رمضان، من الجمهورية العربية اليمنية، يقول: كنت أريد فعل شيء من زوجتي، وأقسمت عليها يمينًا هذا نصه: علي الطلاق لو ما جئت بهذا الشيء؛ لتكوني طالقة، فلم تحضر هذا الشيء الذي كنت أريده. ثم أقسمت يمينًا بالطلاق شافعي ومالكي وأبي حنيفة بيني وبين شريك لي في أرض، وكانت زوجتي جالسةً في هذا المجلس، حيث قلت في هذا اليمين: علي الطلاق شافعي ومالكي وأبو حنيفة لأبيع هذه الأرض بعد هذه الزرعة، ومرت الزرعة والأخرى، ولم تبع الأرض، وأنا في أثناء اليمين كنت أشير بيدي على زوجتي. ثم أقسمت يمينًا بالطلاق على زوجتي بأن ترد علي بالنداء بقول: نعم، حينما أناديها في كل مرة، وهذا نصه: علي الطلاق لو لم تقولي: نعم كلما أناديك لتكوني مطلقة، فأحيانًا تقول، وأحيانًا لا تقول، أفيدونا بارك الله فيكم عن الحل في هذه الأيمان، مع عزمي على التوبة من هذه الأقوال؟جزاكم الله خير الجزاء.","title":"حكم من حلف بالطلاق في وقائع مختلفة","answer":"الجواب: هذا غلط منك، استعمال الطلاق هكذا تلاعب لا خير فيه، غلط منك في هذا -أيها السائل-، ولا ينبغي منك استعمال هذا الطلاق، وأبغض الحلال إلى الله الطلاق، فلا ينبغي للمؤمن أن يستعمل الطلاق هكذا، بل يخاطب بغير الطلاق باليمين بالله بالتأكيد بدون يمين، أما هذا العمل هو عمل لا ينبغي منك، ولا ينبغي منك العود إليه. أما الحكم، فإن كنت أردت حكم اليمين، يعني: أردت التأكيد عليها أنها ترد عليك بنعم، والتأكيد أن تبيع الأرض، والتأكيد عليها أن تأتي بالحاجة، ولم ترد إيقاع الطلاق، إنما أردت التأكيد في هذا الأمر، والتشديد على نفسك، ولم ترد إيقاع الطلاق، ولكن للتأكيد على نفسك أن تبيع أو للتأكيد على زوجتك أنها تأتي بالحاجة أو تقول: نعم، ولم تقصد إيقاع الطلاق عليها وفراقها، فهذا حكمه حكم اليمين، فعليك في كل واحدة كفارة يمين في الحاجة وفي قول: نعم، وفي بيع الأرض عليك كفارة يمين، وهي إطعام عشرة مساكين أو كسوتهم أو عتق رقبة، والإطعام نصف صاع من قوت البلد، مقداره كيلو ونصف من تمر أو أرز أو ذرة، إن كانت قوت البلد، أو دخن إن كانت قوت البلد، أو بر، أو تكسو الفقراء عشرة، كل واحد يعطى قميصًا أو إزارًا ورداءً، أو عتق رقبة مؤمنة، فإن عجزت عن هذا كله تصوم ثلاثة أيام عن كل يمين. فطلاقك لها أن تأتي بالحاجة، ولم تأت بها؛ هذه يمين، والطلاق عليها أنها تقول: نعم يمين، والطلاق على بيع الأرض يمين، هذا إذا كنت ما أردت إلا التأكيد والتشديد على نفسك أنك تبيع الأرض، والتشديد عليها أنها تقول: نعم، والتأكيد عليها أنها تأتي بالحاجة، ولا أردت فراقها، وإيقاع الطلاق عليها في هذه المسائل، هذا فيه كفارة يمين، ثلاث كفارات. أما إن كنت أردت إيقاع الطلاق فيها، أو في إحداها، يقع الطلاق، أنت أردت الطلاق في مسألة الأرض، ما بعتها فالزوجة طالق، يقع عليها الطلاق، فيقع عليها الطلاق، وهكذا مسألة قول: نعم ومسألة الحاجة إن أردت إيقاع الطلاق، وقع الطلاق وعلى حسب. والطلقة الواحدة فيها مراجعة، الطلقة الثانية فيها مراجعة، والثالثة الأخيرة ليس فيها مراجعة تنتهي، تكون قد بانت منك حتى تنكح زوجًا غيرك في الطلقة الأخيرة الثالثة، إذا كنت أردت إيقاع الطلاق في المسائل هذه، فعند الأخيرة إن كان الأخيرة الأرض، أو قول: نعم، أو المسألة الأولى الحاجة الأخيرة منهم من هذه الثلاث تكون هي النهاية، فلا تصلح إلا بعد زوج، إذا كنت أردت إيقاع الطلاق في المسائل الثلاث، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/13983/حكم-من-حلف-بالطلاق-في-وقاىع-مختلفة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_687/nour_68703.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":15472,"question":"سؤالها الآخر تقول: منذ مدة صادفتني مشكلة فنذرت نذرًا لأحد الأئمة إن انحلت هذه المشكلة، وقد علمت أنه لا يجوز النذر لغير الله. علمًا أن المكان الذي فيه الإمام بعيد عني، فهل يجوز أن أدفع هذا النذر للفقراء أو أكفر عنه؟أفيدوني، حفظكم الله.","title":"ما يجب على من نذر للأولياء؟","answer":"الجواب: هذا النذر باطل؛ لأنه عبادة لغير الله، وعليك التوبة إلى الله من ذلك، والرجوع إليه والإنابة والاستغفار والندم.\nفالنذر عبادة، قال الله تعالى: وَمَا أَنفَقْتُمْ مِنْ نَفَقَةٍ أَوْ نَذَرْتُمْ مِنْ نَذْرٍ فَإِنَّ اللَّهَ يَعْلَمُهُ[البقرة:270] يعني: فيجازيكم عليه، وقال النبي ﷺ: من نذر أن يطيع الله فليطعه، ومن نذر أن يعصي الله فلا يعصه فهذا النذر باطل، الذي نذرت لأحد الأئمة الأموات لعلي أو الحسين، أو الشيخ عبد القادر أو غيرهم نذر باطل، وهكذا النذور لغير هؤلاء كالنذر للبدوي أو للسيدة زينب أو السيدة نفيسة، أو غير ذلك، كله باطل، وهكذا النذر لرسول الله ﷺ باطل أيضًا. النذر لا يجوز إلا لله وحده؛ لأنه عبادة، فالصلاة، والذبح، والنذر، والصيام، والدعاء كله لله وحده  كما قال الله سبحانه: إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ[الفاتحة:5] قال سبحانه: وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ[الإسراء:23] يعني: أمر ألا تعبدوا إلا إياه، قال سبحانه: فَادْعُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ وَلَوْ كَرِهَ الْكَافِرُونَ[غافر:14] قال : فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا[الجن:18]. فالعبادة حق الله، والنذر عبادة، والصوم عبادة، والصلاة عبادة، والدعاء عبادة، والذبح عبادة، فيجب إخلاصها لله وحده. فهذا النذر باطل ليس عليك منه شيء لا للفقراء ولا غيرهم، بل عليك التوبة والاستغفار، وليس عليك الوفاء بهذا النذر؛ لكونه باطلًا وشركًا، وعليك بالتوبة الصادقة، والعمل الصالح، وفقك الله، وهداك لما فيه رضاه، ومنَّ عليك بالتوبة النصوح، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/14002/ما-يجب-على-من-نذر-للاولياء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_688/nour_68804.mp3","categories":["الأيمان والنذور","نواقض الإسلام"]},{"id":15473,"question":"هذه رسالة من المستمع: محمد دسوقي محمد، مصري، يعمل بالمملكة، وادي الدواسر، يقول: أنا رجل متزوج، وكنت أتشاجر مع زوجتي كثيرًا، وكنت مع غضبي أقول لها: علي اليمين لتخرجي من منزلي، فكانت أحيانًا لا تخرج، ويقع علي اليمين، وأنا كنت في سن التاسعة عشرة، وجاهل للحكم، وأحيانًا تذهب إلى منزل والدها، وكان والدها لا يوافق على العودة إلى منزلي بسبب اليمين، فكنت أذهب وأحضر واحدًا يحفظ القرآن، ويجتمع أناس من عائلتي ومن عائلتها في منزل والدها، وكان الذي يحفظ القرآن يقول لي: قل: أستغفر الله، فكنت أقول مثله، أستغفر الله، ثلاثًا، ويقول لي: قل: إني رددت زوجتي إلى عصمتي، والله يشهد بذلك والحاضرون والله خير الشاهدين، وعند ذلك يسمح والدها وتذهب معي إلى منزلي، فهل صحيح أن هذا القول هو كفارة اليمين، وليس له كفارة مثل الطلاق؛ لأن فيه أناس يقولون: لفظ (علي اليمين) لا تخص الزوجة بشيء؟فأفيدوني، أفادكم الله.","title":"ما حكم قول الزوج لزوجته: علي اليمين أن تفعلي؟","answer":"الجواب: إذا قال الرجل لزوجته: علي اليمين لتخرجن من البيت، أو لا تخرجي من البيت، أو لا تكلمي فلانًا، أو لا تعملي كذا وكذا، فهو على نيته، إن كان نيته الطلاق طلاق، وإن كان نيته اليمين بالله على نيته، وإذا كان مقصوده منعها من الخروج، ولو نوى الطلاق المقصود منعها، ليس المقصود طلاقها، بل المقصود منعها من الخروج ليرهبها ويخوفها إذا سمعت هذا الكلام حتى لا تخرج فعليه كفارة يمين. وهكذا إذا كان قصد اليمين بالله، أو قصد التحريم ليمنعها من الخروج لا ليحرمها، فعليه كفارة يمين، وهي إطعام عشرة مساكين، لكل مسكين نصف صاع من قوت البلد، يعني: كيلو ونصف من قوت البلد، أو كسوتهم لكل واحد قميص، يعني: مدرعة يلبسها، أو إزار ورداء يكفي. والرجل إذا كان له نية أخرى، إذا كان ناويًا بهذا الكلام تحريمها عليه، إن خرجت، أو إن كان أراد خروجها فهو على نيته، تحريمها، أو أراد طلاقها، يقع طلقة، أراد تحريمها تكون محرمة عليه، وعليه كفارة الظهار، وهي عتق رقبة مؤمنة، وإن عجز صام شهرين متتابعين، فإن عجز أطعم ستين مسكينًا. أما إن كان ما أراد إلا منعها، لم يرد إلا منعها فقط، ولم يرد طلاقها، ولا تحريمها، ولم يرد إلا مجرد منعها من الخروج، أو أراد أن تبقى في البيت، لا تخرج، أو لا تكلم فلانًا، أو لا تزور فلانًا، فهو على نيته، وعليه كفارة يمين؛ لأنه إذا كان ما أراد إلا منعها، فإنه يكون عليه كفارة يمين فقط، ولو كان أراد الطلاق، أو أراد التحريم، يعني: ألا تخرج، يعني: أراد بهذا منعها، عليه الطلاق ألا تخرجي، عليه الحرام ألا تخرجي، عليه اليمين بالله ألا تخرجي، أو عليه اليمين بالله أن تخرجي، أو عليه الطلاق أن تخرجي، أو عليه التحريم أن تخرجي، ما دام قصده المنع بهذه الأمور، وليس قصده تحريمًا ولا طلاقًا، وإنما قصده منعها من الخروج، فهذا كله حكمه حكم اليمين، على الصحيح، ولا يقع طلاقًا، ولا تحريمًا ما دام قصده المنع، ما دام أن قصده في هذا الكلام منعها من الخروج، فعليه كفارة اليمين، وهي ما تقدم، إطعام عشرة مساكين لكل مسكين نصف صاع من قوت البلد، ومقداره كيلو ونصف تقريبًا، وإن كساهم -كسا العشرة- بقميص لكل واحد، أو أعطى كل واحد إزارًا ورداءً كفى، فإن عجز صار فقيرًا ما يقدر، يصوم ثلاثة أيام، نعم.\nالمقدم: أما فعله الذي فعله على أساس الكفارة؟\nالشيخ: أما هذا الفعل الذي فعله، ما له أصل، هذا ما له أصل، كونه القارئ يقرأ يقول: أستغفر الله، هذا ما يكفي، وليس هذا حلًا للمشكلة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13998/ما-حكم-قول-الزوج-لزوجته-علي-اليمين-ان-تفعلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_688/nour_68802.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":15477,"question":"هذا سؤال من المستمع (أ. ب. ش) من الرياض، يقول: حلفت على زوجتي بالطلاق في وقت الغضب ألا تذهب إلى الجيران، فقلت لها: علي الطلاق بالثلاث إن ذهبت إلى الجيران تكوني طالق، وفعلًا لم تذهب إلى أن جاء ذات يوم ابن الجيران يخبرها أن أمه مريضة التي هي جارتنا، فأمرتها أن تذهب لزيارتها، فماذا يجب علي في هذه الحالة؟ وهل تعتبر زوجتي طالقة أم لا؟أفيدونا، جزاكم الله خيرًا.","title":"حكم من حلف بالطلاق ألا تذهب إلى جيرانه ثم أذن","answer":"الجواب: إذا كان المقصود من هذا الطلاق منعها من الخروج، وليس المقصود إيقاع الطلاق إن خرجت أو ذهبت، إنما مقصودك -أيها السائل- منعها من خروجها إلى الجيران، وليس المقصود أنها إن خرجت يقع الطلاق، تريد تخويفها وتحذيرها، فهذا فيه كفارة اليمين؛ لما خرجت لأجل عيادة المريضة عليك كفارة يمين، ولو كان بإذنك، كفارة اليمين إطعام عشرة مساكين أو كسوتهم -عشرة- تعطيهم على نصف صاع تمر، أو كيلو ونصف تمر، أو رز، حسب قوت البلد، وإن كسوتهم على قميص قميص، أو أعطيتهم على إزار ورداء كفى ذلك. إلا إذا كنت ناويًا في يمينك هذا (إلا بإذنك)، إن كنت نويت بقولك: عليك الطلاق بالثلاث إن ذهبت يعني: إلا بإذني، إذا كنت ناويًا أنها إذا خرجت بإذنك فلا بأس، فأنت على نيتك، فلا شيء عليك حينئذٍ؛ لأنك أذنت لها، وأما إن كنت ما نويت إلا بإذنك قلتها: منعًا باتًا، فإنها إذا خرجت ولو بإذنك عليك كفارة يمين، التي عرفت إذا كان المقصود منعها. أما إن كان المقصود إيقاع الطلاق إن خرجت، ولم تنو (إلا بإذنك) وإنما قصدت منعها، وقصدت إيقاع الطلاق إن خرجت، فإنها بخروجها إليهم يقع طلقة واحدة، طلقة واحدة، ولك مراجعتها في العدة إذا كنت لم تطلقها قبل هذا مرتين، فإن لك أن تراجعها في العدة قبل أن تخرج منها، فإن خرجت من العدة، ولم تراجعها حُرمت عليك إلا بنكاح جديد، ومهر جديد، هذا إذا كنت ما طلقتها قبلها مرتين، أما إن كنت طلقتها قبل هذا مرتين وأنت قصدت إيقاع الطلاق بهذا الكلام، فإنها تحرم بذلك تكون الطلقة الأخيرة، إذا كنت أردت إيقاع الطلاق إن ذهبت إلى الجارة، يكون هذا الطلاق واقعًا، ويكون مكملًا للثلاث، إذا كان قبلها طلقتان، نعم. المقدم: إنما قوله: بالثلاث لا يعتبر العدد؟\nالشيخ: تعتبر واحدة على الصحيح؛ لأن الثلاث بلفظ واحد على الصحيح يعتبر واحدة؛ لأنه ثبت في الحديث الصحيح من حديث ابن عباس ما يدل على هذا، نعم. المقدم: ولو كرر الطلاق؟ الشيخ: على حسبه، إن كرره ناويًا التأكيد لم يقع شيء، وإن كان كرره يريد إيقاع الطلاق ثانية وثالثة، وقع.\nالمقدم: وقع؟\nالشيخ: نعم. المقدم: جزاكم الله خير الجزاء.","link":"https://binbaz.org.sa/fatwas/14003/حكم-من-حلف-بالطلاق-الا-تذهب-الى-جيرانه-ثم-اذن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_688/nour_68805.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":15488,"question":"هذا سؤال من المستمع: (ق. ع. أ) من بلاد زهران، قلوة، يقول: أنا رجل متزوج، وقد حصلت خصومة ذات يوم مع زوجتي، فطلبت منها فعل شيء، ولكنها رفضت، فكررت عليها وهي مصرة على رفضها، فقلت لها: لو رفضت فأنت محرمة علي كما حرمت علي أمي، ولكنها أصرت على رفضها، ثم استمرت حياتنا الزوجية بعد ذلك دون أن أكفر. علمًا أنني كثيرًا ما أحلف بالطلاق على أشياء وأحنث في يميني ولا أكفر، ولكني لا أقصد الطلاق، وإنما نتيجة الغضب والحماقة، والآن لي مع زوجتي أربع سنين، ولي منها طفلان، فماذا علي الآن؟أفيدوني، وفقكم الله.","title":"حكم التلفظ بالحرام والطلاق بنية التخويف","answer":"الجواب: أولًا: لا ينبغي تعاطي هذه الأمور، ينبغي لك -أخي- ألا تتعاطى هذه الأمور، لا التحريم ولا الطلاق، بل تخاطبها بغير ذلك، وتأمرها وتنهاها بغير ذلك، وينبغي أن تنزه نفسك ولسانك عن هذا حتى لا تقع في مشاكل، وفي أمور قد تحرم عليك زوجتك وأنت لا تشعر، فعليك أن تجتنب هذه الألفاظ تمامًا. أما حكم ما وقع فإذا كان الواقع منك بقصد التخويف، وحثها على أن تعمل ما قلت لها، وليس القصد من ذلك فراقها، فإنه عليك كفارة يمين، وليس عليك طلاق، ولا ظهار، إذا كان المقصود حملها على العمل، وأن تنفذ ما قلت لها، وليس قصدك إيقاع الطلاق وفراقها إن لم تفعل، فإن عليك في هذا كفارة يمين، وإن كفرت كفارة ظهار؛ لأنك قلت: كأمي من باب الاحتياط فحسن، ولكن يكفي هذا كفارة يمين؛ لأن المقصود حملها على ما قلت لها حتى تفعل. وهكذا لو تلفظت بلفظ الطلاق، عليك الطلاق أن تفعلي كذا، أو إن لم تفعلي كذا، فأنت طالق، والمقصود حملها على الفعل، وحثها، وتخويفها، فهذا كله ليس فيه إلا كفارة يمين، وهي إطعام عشرة مساكين، أو كسوتهم، والإطعام نصف صاع من التمر أو الرز أو الحنطة كيلو ونصف تقريبًا من قوت البلد، والكسوة إزار ورداء أو قميص يستر في الصلاة هذه الكسوة، أو عتق عبد أو عبدة، تحرير عبد أو عبدة، هذه هي الكفارة، فإن عجزت عن هذا كله، كفاك صيام ثلاثة أيام، كما نص عليه كتاب الله في سورة المائدة في كفارة اليمين. لكن بكل حال ننصحك أن تحذر هذه الألفاظ، وتحذر التساهل بها دائمًا، وعليك أن تبادر بالكفارة عما فعلت، كفارة الأيمان عما فعلت سابقًا، عن كل واحدة تطعم عشرة مساكين، خمسة أصواع من التمر، أو الرز أو الحنطة، كل واحد له نصف الصاع، يعني: كيلو ونصف من هذه الأطعمة، أو تكسو عشرة بإزار ورداء، أو بقميص كفارة يمينك؛ لأن هذه الأشياء في حكم اليمين، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14024/حكم-التلفظ-بالحرام-والطلاق-بنية-التخويف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_690/nour_69004.mp3","categories":["الظهار","الطلاق","الأيمان والنذور"]},{"id":15499,"question":"سماحة الشيخ، هذه رسالة وصلت من مدرسة لها مجموعة من الأسئلة، تقول: سماحة الشيخ، حلفت يمينًا، وأريد التكفير عنها، هل يكون الأفراد عددهم عشرة، أو الطعام يكفي لعشرة حتى لو لم يكون الأفراد عددهم أقل من عشرة، هل يجزئ ذلك؟","title":"اشتراط عشرة مساكين في كفارة اليمين","answer":"الجواب: لا، لا بد أن يكونوا عشرة؛ لأن الله قال: إِطْعَامُ عَشَرَةِ مَسَاكِينَ[المائدة:89] لا بد يكونوا عشرة، كل واحد له نصف الصاع، أو يعشيهم لحالهم، أو يغديهم عشرة، ما يرددها على واحد و إلا اثنين لا، لا بد عشرة، هذا غير هذا، نعم. المقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/14031/اشتراط-عشرة-مساكين-في-كفارة-اليمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_691/nour_69106.mp3","categories":["الأيمان والنذور"]},{"id":15504,"question":"هذا السائل (أ. أ. أ) بعث بسؤالين، سؤاله الأول يقول: في العام الأول من زواجنا، وعلى إثر غضب شديد، حلفت على زوجتي بالطلاق، وكانت صيغته كالآتي:إذا دخلت أمك هنا تكوني طالقة، وكنت أقصد بذلك التهديد فعلًا لا الطلاق، وبعد ذلك دخلت أمها، ومضى على زواجنا حتى الآن أكثر من عشرين عامًا، وأنجبت منها أولادًا، ولم أحلف بالطلاق مرة أخرى طيلة هذه المدة، فما حكم هذا الطلاق، هل يقع أم لا؟","title":"ما حكم الحلف بالطلاق إذا قصد به التهديد؟","answer":"الجواب: الصواب: أن هذا الطلاق له حكم اليمين؛ لأنك لم تقصد إيقاعه، وإنما قصدت المنع من دخول أمها وتهديدها بهذا الأمر، فهذا الطلاق يكون له حكم اليمين في أصح قولي العلماء.  وعليك كفارتها، وإن طال المدى، عليك أن تكفر عن يمينك بإطعام عشرة مساكين، أو كسوتهم، أو عتق رقبة مؤمنة، كما بينه الله في كتابه العظيم في سورة المائدة، ويكون الفقير الواحد له نصف الصاع من التمر، أو من الأرز أو غيرهما من قوت البلد، يدفع إلى عشرة مساكين لا ينقص عنهم، أو تكسوهم كسوة تجزئهم في الصلاة كقميص أو إزار ورداء، ويكفي هذا والحمد لله، ولا يقع الطلاق، زوجتك معك وعشرتكما -العشرة التي بينكما- باقية، ولا حرج في هذه المدة الطويلة إلا أنك أخطأت في عدم إخراج الكفارة هذه المدة الطويلة.  وأما القول بأنه يقع الطلاق فهو قول ضعيف مرجوح، والصواب: أنه لا يقع ما دام للتهديد والمنع، وليس للإيقاع، نعم.","link":"https://binbaz.org.sa/fatwas/14036/ما-حكم-الحلف-بالطلاق-اذا-قصد-به-التهديد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_702/nour_70206.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":15573,"question":"هل يجوز الحلف بهذه العبارات التالية: ورب الكعبة؟","title":"حكم الحلف برب الكعبة وحياة النبي","answer":"الجواب: نعم؟\nالمقدم: ورب المصحف؟\nالشيخ: نعم.\nالمقدم: وحياة النبي؟ الشيخ: حياة النبي ما يصلح، ورب الكعبة ورب البيت ما يخالف، أما حياة النبي إنسان مخلوق ما يجوز، الرسول ﷺ قال: من كان حالفًا فليحلف بالله أو ليصمت وقال ﷺ: من حلف بشيء دون الله فقد أشرك أن يكون الحلف بالله أو بأسمائه وصفاته، أما الحلف بحياة النبي أو بالنبي أو بالأمانة أو بشرف فلان كل هذا لا يجوز.","link":"https://binbaz.org.sa/fatwas/14113/حكم-الحلف-برب-الكعبة-وحياة-النبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_570/57010.mp3","categories":["الأيمان والنذور"]},{"id":15575,"question":"حرام بالله؟الشيخ: ما المراد بحرام بالله؟المقدم: أن يقول هذا يتردد حرام بالله أن تعمل كذا؟","title":"حكم من حلف بقوله: (حرام بالله)","answer":"الجواب: هذا معناه: علي الحرام يعني، هذا يكون فيه كفارة يمين إذا ما نفذ الذي قال له، عليه كفارة يمين، إذا قال: حرام بالله أن تقوم، وما قام، عليه كفارة يمين، حرام بالله أن تأكل الطعام، وما أكل، عليه كفارة يمين؛ لقول الله سبحانه: يَا أَيُّهَا النَّبِيُّ لِمَ تُحَرِّمُ مَا أَحَلَّ اللَّهُ لَكَ تَبْتَغِي مَرْضَاةَ أَزْوَاجِكَ وَاللَّهُ غَفُورٌ رَحِيمٌ ۝ قَدْ فَرَضَ اللَّهُ لَكُمْ تَحِلَّةَ أَيْمَانِكُمْ [التحريم:1-2] قال جماعة من المفسرين: نزلت في العسل، وقال بعضهم: في تحريم جارية، فأمره الله أن يكفر عن يمينه، نعم، جعل التحريم يمينًا، تحريم الجارية أو الطعام أو ركوب الدابة، أو ما أشبه ذلك، يكون حكمه حكم اليمين إذا قال: علي الحرام ما أركبها، علي الحرام ما آكل معك الطعام، علي الحرام ما أجلس، يكون حكمه حكم اليمين. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14116/حكم-من-حلف-بقوله-حرام-بالله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_570/57012.mp3","categories":["الأيمان والنذور"]},{"id":15579,"question":"هذا سؤال من المستمع (ج. ج. ق) من المغرب فاس، يقول: أحيانًا أقول: زوجتي طالق علي أو حرام أن لا أفعل ذلك الشيء، ثم تغريني نفسي وأفعله، والآن أريد أن أتوب إلى الله توبة خالصة.أفيدوني، جزاكم الله خيرًا، ما الحل في قولي هل يقع الطلاق، أم علي كفارة، أم علي صيام؟","title":"حلف بالطلاق وقال: حرام علي إن فعلت كذا وفعل؛ فما الحكم؟","answer":"الجواب: إذا قلت ذلك فالحكم يختلف بحسب النية؛ لأن الرسول ﷺ قال: إنما الأعمال بالنيات، وإنما لكل امرئ ما نوى فإذا قلت: علي الطلاق أني لا أفعل كذا، أو حرام علي أن لا أفعل كذا، فإن كنت أردت إيقاع الطلاق بهذا، فإنه يقع الطلاق طلقة واحدة، وإذا كررت ذلك وقع ما كررته من ثنتين أو ثلاث. أما إن كنت ما أردت الطلاق، وإنما أردت المنع، منع نفسك من هذا الشيء، لم ترد الطلاق، وإنما أردت أن تمنع نفسك، كأن تقول: علي الطلاق لا أزور فلانًا، علي الطلاق لا أكلم فلانًا، تريد منع نفسك من هذا الشيء، ولم ترد إيقاع الطلاق، فإن عليك كفارة يمين، ولا يقع الطلاق، وكفارة اليمين إطعام عشرة مساكين، أو كسوتهم، إما أن تطعمهم غداءً أو عشاءً، أو نصف صاع من قوت البلد كيلو ونصف من قوت البلد، لكل واحد تمر أو رز أو نحو ذلك، وإما أن تكسوهم كسوة قميص لكل واحد أو إزار ورداء لكل واحد، والعاجز الفقير الذي لا يستطيع هذه الأشياء يصوم ثلاثة أيام، كما دل عليه كتاب الله . وهكذا الحرام إذا قلت: علي الحرام ما أفعل كذا، فإذا أردت أنك تحرمها إن فعلته، وأنها حرام عليك إن فعلته، كان ظهارًا فيه كفارة الظهار إذا فعلت هذا الشيء وهي عتق رقبة مؤمنة، فإن عجزت صمت شهرين متتابعين، فإن عجزت أطعمت ستين مسكينًا، ثلاثين صاعًا، توزع بينهم لكل واحد نصف صاع من قوت البلد من تمر أو رز أو حنطة ونحو ذلك، هذا إذا كنت أردت التحريم تحريمها عليك إن فعلت. أما إن كنت أردت المنع منع نفسك من هذا الشيء كأن تقول: علي الحرام ما أكلم فلانًا، أو علي الحرام ما أزور فلانًا، فإن هذا حكمه حكم اليمين كما تقدم، فعليك كفارة يمين؛ لقوله تعالى: يَا أَيُّهَا النَّبِيُّ لِمَ تُحَرِّمُ مَا أَحَلَّ اللَّهُ لَكَ تَبْتَغِي مَرْضَاةَ أَزْوَاجِكَ وَاللَّهُ غَفُورٌ رَحِيمٌ ۝  قَدْ فَرَضَ اللَّهُ لَكُمْ تَحِلَّةَ أَيْمَانِكُمْ[التحريم:2] فسمى التحريم يمينًا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14120/حلف-بالطلاق-وقال-حرام-علي-ان-فعلت-كذا-وفعل-فما-الحكم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_692/nour_69205.mp3","categories":["الظهار","الطلاق","الأيمان والنذور"]},{"id":15592,"question":"هذه رسالة بعث بها أحد الإخوة المستمعين، يقول: خولة جمعة أحمد، من العراق، له سؤال طويل كتبه في صفحتين. ملخص هذا أنه حلف أكثر من مرة على موضوع معين، ثم لم يوف بذلك الحلف، وحينئذٍ يسأل سماحتكم ماذا عليه؟ هل عليه الصيام أم هناك كفارة أخرى؟جزاكم الله خيرًا.","title":"ما حكم اليمين المكررة على أمر واحد؟","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فاليمين المكررة على موضوع واحد، ليس فيها إلا كفارة واحدة ولو كثرت، فإذا قال: والله لا أكلم فلانًا، والله لا أكلم فلانًا، والله لا أكلم فلانًا، والله لا أكلم فلانًا، ولو مائة مرة؛ فليس فيها إلا كفارة واحدة، وهكذا لو قال: والله لا أزور فلانًا، والله لا أزور فلانًا، والله لا أزور فلانًا، أو والله لا أسافر، والله لا أسافر، والله لا أسافر، ثم سافر ثم زار؛ ليس فيها إلا كفارة واحدة؛ لقول الله : لا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِنْ يُؤَاخِذُكُمْ بِمَا عَقَّدْتُمُ الأَيْمَانَ [المائدة:89] . فهذه يمين عقدها على شيء واحد، فليس عليه إلا كفارة واحدة، ولو تكرر ذلك منه مرات كثيرة في أوقات متعددة، إلا إذا كفر عن الأولى، ثم عاد الكلام يكفر عن الثانية، فلو قال: والله لا أكلم فلانًا، ثم كلمه؛ كفّر، ثم عاد وقال: والله لا أكلمه فعليه كفارة أخرى لهذه اليمين الثانية؛ لأنه كرر اليمين بعد الكفارة، أما لو تعددت الأفعال، فإن كل فعل له كفارة، فإذا قال: والله لا أكلم فلانًا، والله لا آكل طعامًا، فلان والله لا أسافر، فإنه تلزمه كفارة لكل يمين إذا حنث؛ لأنها أيمان متعددة على أفعال متعددة، فكل يمين له كفارة. والمشروع للمؤمن أن يحفظ يمينه؛ لأن الله سبحانه يقول: وَاحْفَظُوا أَيْمَانَكُمْ[المائدة:89] فالمؤمن يشرع له عدم الإكثار من الأيمان والحرص على تقليل الأيمان؛ لأن إكثارها فيه استخفاف، ولأن إكثارها وسيلة إلى ترك الكفارة.  فالمشروع للمؤمن والمؤمنة العناية بقلة الأيمان، وأن لا يحلف إلا عند الحاجة والمصلحة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14131/ما-حكم-اليمين-المكررة-على-امر-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_705/nour_70501.mp3","categories":["الأيمان والنذور"]},{"id":15617,"question":"سؤاله الثاني يقول: هناك أخوان شقيقان حصل بينهما شجار بسبب المال، وحضر جماعة للإصلاح، وطلبوا من الصغير إعطاء الكبير شيئًا من المال، ويتم التراضي بينهما، ولكنه غضب، وقال: طلاق ثلاثًا لا أسامحه لا في الدنيا ولا في الآخرة، فماذا عليه الآن؟ وهل يقع طلاق بهذا لو سامح أخاه؟","title":"حكم من حلف بالطلاق ألا يسامح أخاه","answer":"الجواب: ما كان ينبغي لهذا المسلم أن يتسرع في الطلاق، وكان ينبغي له أن يقدر إخوانه الذين جاؤوا للإصلاح، وأن يعرف لهم فضلهم، ونبل مقصدهم، وأنهم جديرون بالتقدير والاعتراف بالفضل، حيث جاؤوا للإصلاح، والله شرع لنا الإصلاح، قال : لا خَيْرَ فِي كَثِيرٍ مِنْ نَجْوَاهُمْ إِلَّا مَنْ أَمَرَ بِصَدَقَةٍ أَوْ مَعْرُوفٍ أَوْ إِصْلاحٍ بَيْنَ النَّاسِ[النساء:114] وجاء في الحديث الحث على إصلاح ذات البين، والله يقول سبحانه: فَاتَّقُوا اللَّهَ وَأَصْلِحُوا ذَاتَ بَيْنِكُمْ[الأنفال:1] فكان ينبغي لهما جميعًا أن يقدرا لهؤلاء الجماعة قصدهم الطيب، ولا سيما الأصغر، فإن حق الكبير عليه عظيم. أما وقد وقع ما وقع، فإنه ينظر في قصده، فإن كان قصده بالطلاق منع نفسه من المسامحة لأخيه، وليس من قصده فراق أهله إن سامح أخاه؛ فهذا حكمه حكم اليمين، وعليه كفارتها، وهي إطعام عشرة مساكين، أو كسوتهم، أو عتق رقبة، فإن عجز صام ثلاثة أيام، هذا هو الواجب في هذه المسألة إذا كان هذا المطلق إنما قصد منع نفسه من المسامحة، ولم يقصد فراق زوجته إن سامح أخاه، فهو بهذه النية يكون طلاقه هذا في حكم اليمين في أصح قولي العلماء، وعليه كفارتها إذا سامح أخاه، وهو الأولى به أن يسامح أخاه، وأن يصل رحمه، وأن يتعوذ بالله من الشيطان، ولو كان أخوه قد أخطأ عليه، لو فرضنا أن أخاه الكبير قد أخطأ عليه، فكونه يسامح أخاه الكبير ويتنازل عن حقه هذا خير له في الدنيا والآخرة، وقد قال النبي -عليه الصلاة والسلام- في الحديث الصحيح: ليس الواصل بالمكافي، ولكن الواصل الذي إذا قطعت رحمه وصلها فهذا هو الحكم في هذه المسألة إن كان قصده منع نفسه من مسامحة أخيه، ولم يقصد فراق زوجته إن سامح أخاه. أما إن كان قصده فراق زوجته، قصد منع نفسه وفراق زوجته إن سمح أخاه هذا قصده، يعني: يقصد منع نفسه من المسامحة، ويقصد مع ذلك أنه يفارقها، وأن الطلاق يقع إذا سامح أخاه، فهو في هذه الحال ينبغي له أن يسامح أخاه، وتقع عليه طلقة واحدة، ويراجعها؛ لأن الثلاث بلفظ واحد تعتبر واحدة على الصحيح من أقوال العلماء، فقد ثبت عن النبي ﷺ من حديث ابن عباس في صحيح مسلم ما يدل على أن الثلاث إذا كانت بلفظ واحد تعتبر واحدة، فيكون له الرجعة، إذا سامح أخاه وقعت طلقة واحدة فقط من هذا اللفظ، وله أن يراجعها في العدة بقوله: راجعت امرأتي، أو أمسكت امرأتي، أو رددت امرأتي، وعليه أن يشهد على ذلك شخصين، هذا هو السنة، أن يشهد عدلين على هذه المراجعة. هذا هو الذي ينبغي إذا كان لم يطلقها قبل هذا طلقتين، أما إن كان قد طلقها قبلها طلقتين تكون هذه هي الثالثة يكون ما فيها رجعة، لكن إذا كان ما طلقها طلقتين فإنه إذا كان قصد إيقاع الطلاق فإنه يسامح أخاه، وتقع طلقة، ويراجع زوجته، والحمد لله، فصلحه مع أخيه أسهل وخير له من مسألة الطلقة إذا وقعت، فإن أمرها لا يضر ما دام له فسحة في الرجعة، ولم يطلق قبل هذا طلقتين، فإن أولى به أن يسامح أخاه، ولو وقعت على زوجته طلقة، فإن أمرها بحمد الله سهل، ومصالحة أخيه مهمة كبيرة، وقربة عظيمة إذا كان أخوه من أهل الخير والإيمان من المسلمين. أما إذا كان أخوه ليس بمسلم، أو ممن يظهر الفسوق والعصيان والكبائر، فتركه وعدم المصالحة قد يكون خيرًا لأخيه حتى يسلم من شره، وما لديه من فجور أو كفر، لكن ما دام أخوه مسلمًا مستورًا فمصالحته مطلوبة، وصلة رحم، ولو وقع بها طلقة لا تمنعه من مراجعة الزوجة، والله المستعان، نعم. المقدم: بارك الله فيكم، لو فرضنا أنه كان يقصد إيقاع الطلاق لو سامح أخاه وفعلًا كان الحكم كما تفضلتم بإيقاع طلقة عليه، لكن لو لم يعلم بهذا الحكم إلا بعد أن انقضت العدة فكيف العمل؟\nالشيخ: يعني: سامح أخاه؟ المقدم: يقصد إيقاع الطلاق لو سامح أخاه، وتفضلتم بقولكم أنه يقع عليه طلقة واحدة في هذه الحالة إذا سامح أخاه؟\nالشيخ: هي تقع منه حين المسامحة، ما هو من سابق، الطلقة تقع حين المسامحة. المقدم: وليس حين التلفظ؟ الشيخ: لا. حين المسامحة.\nالمقدم: حين المسامحة؟ الشيخ: تبدأ العدة من حين المسامحة، وتقع الطلقة من حين المسامحة. المقدم: أقصد إذا كان لم يعلم بهذا الحكم إلا بعد أن وقع الطلاق وسامح أخاه، وانتهت عدتها؟ الشيخ: ما راجعها يعني؟ المقدم: ما راجعها. الشيخ: تصلح بعقد جديد، يتزوجها من جديد إذا كان ما طلقها إلا طلقة واحدة، أو ما طلقها إلا هذه الطلقة التي سامح فيها أخاه، نعم. المقدم: يعني: إذا كانت الأولى أو الثانية فيسترجعها بعقد جديد إذا انقضت العدة، ولم يراجعها؟ الشيخ: نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/14161/حكم-من-حلف-بالطلاق-الا-يسامح-اخاه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_696/nour_69602.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":15640,"question":"وهذه أول رسالة في حلقتنا اليوم من المستمع (محمود م. ج) مصري يعمل بالمملكة العربية السعودية بعث بعدة أسئلة يقول في سؤاله الأول: نذرت لله تعالى أن أذبح عجلًا لتفضله علي بزيارة الحرمين الشريفين، وفي نيتي وكما هو متبع في بلدنا ولتقارب المستوى المعيشي فلا يوجد الفقير المعدم، ولا الغني المترف، فقصدي أن أذبحه وأولم وليمة، ثم أدعو كل المسلمين في بلدنا، ثم أدعو شيخًا وعالمًا جليلًا معروفًا عندنا يقوم بوعظ المسلمين، وإقامة حلقات الذكر، والاستغفار، والتسبيح، والتحميد لله، والصلاة على رسوله ﷺ، في ليلة محددة، ويتناولون طعام العشاء، ثم نقضي ليلتنا تلك في ذكر الله، والصلاة، والتسبيح، والتحميد، فهل في ذلك شيء يخالف شريعة الله أو لا أكون بذلك قد وفيت بنذري؟","title":"نوى أن يذبح عجلا ويجتمع مع الحاضرين على ذكر الله","answer":"الجواب: بسم الله الرحمن الرحيم. الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فإن النذر منهي عنه، قد نهى عنه النبي ﷺ فقال: لا تنذروا فإن النذر لا يرد من قدر الله شيئًا، وإنما يستخرج به من البخيل لكن من نذر طاعة لله سبحانه كالصلاة والصوم والذبح لله سبحانه فإنه يوفي بها؛ لقول النبي ﷺ: من نذر أن يطيع الله فليطعه، ومن نذر أن يعصي الله فلا يعصه خرجه البخاري في صحيحه. فعليك -أيها الأخ السائل- أن توفي بنذرك بذبح العجل وتوزيعه وتصلح الوليمة كما نويت، ولا بأس بذلك للفقراء وغيرهم من أقاربك وجيرانك على حسب ما نويت؛ لقول النبي ﷺ: إنما الأعمال بالنيات، وإنما لكل امرئ ما نوى وإحضار العالم للتذكير والوعظ بمناسبة اجتماع المسلمين هذا شيء طيب.\nكذلك إذا سبحوا الله، وذكروا الله -جل وعلا-، وكل يذكر الله في نفسه، ويسبح الله في نفسه، كل هذا عمل صالح. أما الاجتماع على أذكار مخصوصة، وتسبيح مخصوص بصوت مخصوص جماعي، فهذا لا دليل عليه، وليس له أصل في الشريعة فيما نعلم، لكن إذا سبح كل واحد، واستغفر كل واحد نفسه، وذكروا الله في أماكنهم، وسبحوا الله في أماكنهم واستغفروه  وشكروه فهذا كله طيب، وإذا كان في اجتماعهم قراءة للأحاديث الصحيحة عن رسول الله ﷺ، أو قراءة للقرآن وهم يستمعون والعالم يفسر لهم معنى الآيات ومعنى الأحاديث فهذا كله طيب. أما الحلقات التي يفعلها الصوفية على أذكار مخصوصة، وأصوات مخصوصة، ونغمات مخصوصة، فهذه لا أصل لها، بل هي من البدع، ولكن اجتماع الناس على العلم وقراءة القرآن واستماعه، وسماع كلامًا لأهل العلم وتذكيرهم ووعظهم وتفسير الآيات للحاضرين كل هذا طيب، نسأل الله للجميع التوفيق والهداية، ويكون هذا في يوم معين أو في وقت معين من الليل لا بأس إلا أن يكون يقصد بذلك تعظيم ليلة مخصوصة، مثل ليلة المولد، فهذا لا يجوز؛ لأن الموالد بدعة، والاحتفال بها من البدع المحدثة في الدين على الصحيح من أقوال العلماء، وقد تنازع العلماء المتأخرون في ذلك فزعم بعضهم أنه سنة، وأن إقامة الأعياد لا بأس بها، ولكنه قول مرجوح وضعيف. والصواب: أن الاحتفال بالموالد بدعة ما أنزل الله بها من سلطان، داخل ذلك في قوله ﷺ: من عمل عملًا ليس عليه أمرنا فهو رد وفي قوله -عليه الصلاة والسلام-: من أحدث في أمرنا هذا ما ليس منه فهو رد والدليل على هذا مع الحديثين المذكورين أن الرسول ﷺ لم يفعل ذلك في حياته، ولا فعله أصحابه بعد وفاته، لا الصديق  ولا عمر  ولا عثمان ولا علي -رضي الله عنهم-، ولا بقية الصحابة، كذلك ما فعله التابعون ولا أتباع التابعين في مولد النبي ﷺ ولا في مولد غيره، فدل ذلك على أنه بدعة. والخير كله في اتباع السلف الصالح، في السير على منهاج نبينا ﷺ وصحابته، والنبي ﷺ يذكر -والحمد لله- في كل وقت، في الأذان والإقامة خمس مرات في اليوم والليلة، في التشهد الأول والتشهد الثاني، في سائر الأوقات يصلى عليه ويسلم -عليه الصلاة والسلام-، فليس في حاجة إلى هذه البدعة. وهكذا سيرته ﷺ يجب أن تدرس في المدارس والمعاهد والمساجد والكليات حتى تعرف سيرته -عليه الصلاة والسلام-، وحتى يتأسى بأقواله وأفعاله -عليه الصلاة والسلام-، فليس المسلمون في حاجة إلى بدعة المولد. فينبغي لأهل العلم أن ينتبهوا لهذا الأمر، وأن يوضحوا للعامة طريق أهل السنة والجماعة في هذا الباب وغيره، نسأل الله للجميع الهداية والتوفيق وصلاح النية والعمل.\nالمقدم: اللهم آمين، بارك الله فيكم.\nالمقدم: يقول: هل يجوز له أن يأكل هو وأولاده وأهل بيته وأقاربه من هذه الوليمة؟\nالشيخ: لا بأس بذلك ما دام نوى هذه النية أنه يذبحها ويجمع إليها الناس ويأكل هو وأهل بيته لا بأس الأعمال بالنيات. المقدم: يعني: ما لم يحدد؟\nالشيخ: أما إذا ما نوى شيئًا فإنه يعطاها للفقراء خاصة، وما دام نوى أنه يذبحها في البيت، ويجمع عليها العلماء، ويجمع عليها الفقراء وغير الفقراء من أهل بيته وجيرانه فالأعمال بالنيات.","link":"https://binbaz.org.sa/fatwas/14186/نوى-ان-يذبح-عجلا-ويجتمع-مع-الحاضرين-على-ذكر-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_697/nour_69701.mp3","categories":["الأيمان والنذور","البدع والمحدثات"]},{"id":15644,"question":"سؤاله الثالث يقول: بينه وبين زوجته، يقول: حلفت عليها مرة قائلًا: والله العظيم إن لم تذهبي اليوم إلى بيتنا لتكوني طالقة، وكانت في بيت أبيها في حالة نفاس، ولم يمر عليها خمسة أيام من وضعها لسوء تفاهم نشب بيني وبين أبيها، وكنت لا أقصد طلاقها، وإنما أقصد أن تخاف على نفسها من الطلاق، وتذهب إلى بيتنا تاركة بيت أبيها، ولكنني بعد أن هدأت لمت نفسي على هذا الحلف وخوفًا من إصابتها بمرض أثناء ذهابها، المهم لم ينفذ الذهاب إلى بيتنا، وبعد مرور عدة سنين ولكثرة كلامها في موضوع لا أرغب في الاستماع إليه حلفت عليها قائلًا: والله العظيم إن لم تسكتي عن الحديث في هذا الموضع الآن لتكوني طالقة، ولكنها تكلمت، وكان قصدي أيضًا أن أمنعها من الحديث، وأخوفها بالطلاق، ولا أقصد تطليقها، إنما أقصد طاعتي في السكوت، فهل في هذين الحلفين وقع علي يمين أو طلاق رجعي، أو يمين وطلاق معًا؟ وبمرور السنين أيضًا حلفت عليها قائلاً: إذا تصرفت في أي موضوع بدون مشورتي لتكوني علي حرام كأمي وأختي، أقصد أيضًا تهديدها بعدم التصرف بدون مشورتي وطاعتي، فهل هذا ظهار أم يمين؟ أفيدونا عن ذلك، جزاكم الله خيرًا.","title":"حكم الطلاق والحرام بنية التخويف والزجر","answer":"الجواب: هذا التصرف لا يليق منك، بل ينبغي التثبت، وعدم المسارعة إلى الطلاق، ولا إلى التحريم أيضًا، ولكن ما دام الواقع هو ما ذكرت، وليس قصدك إلا تخويفها وحثها على امتثال أمرك، فإن هذه الوقائع الثلاث كلها في حكم اليمين، كل واحدة منها في حكم اليمين، الطلاق الأول والثاني والتحريم الأخير كله في حكم اليمين، وعليك كفارة اليمين عن هذه الوقائع الثلاث.  عليك كفارات ثلاث، عن كل واحدة كفارة يمين، وهي إطعام عشرة مساكين، لكل مسكين نصف صاع من قوت البلد من تمر أو غيره؛ وذلك يقارب كيلو ونصف، أو كسوتهم بما يجزئ في الصلاة، أو ما هو أكمل من ذلك مثل: إزار ورداء، مثل: قميص وعمامة يكفي لكل واحد، وإن عشيتهم في بيتك أو غديتهم في بيتك كفى ذلك أيضًا. وعليك التوبة إلى الله من التحريم؛ لأنه لا يجوز التحريم لما أحل الله ، وهذا الذي قلنا لك هو الأصح من أقوال أهل العلم أن في هذا كفارة يمين، ولا يلحقك طلاق ولا تحريم، هذا هو الأرجح من أقوال أهل العلم في هذه المسائل الثلاث، نسأل الله لنا ولك الهداية، نعم.\nالمقدم: اللهم آمين. المقدم: في الحلف الأخير بالظهار لا يكون ظهارًا هذا؟\nالشيخ: لا. يمين، حكمه حكم اليمين. المقدم: حكمه حكم اليمين؟ الشيخ: حكمه حكم اليمين، نعم.","link":"https://binbaz.org.sa/fatwas/14189/حكم-الطلاق-والحرام-بنية-التخويف-والزجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_697/nour_69703.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":15658,"question":"سؤاله الثاني يقول: أثناء إقامتي في بلدي حلفت على زوجتي: لو ذهبت إلى المكان الفلاني تكوني محرمة علي، ووقت بقائي هناك لم تذهب، ولكن الآن في غيابي لو ذهبت فما الحكم؟ وعلى من يكون الإثم؟ وماذا أفعل لو ذهبت وأنا لم أعلم بذلك؟","title":"حكم من قال لزوجته: أنت محرمة علي لو ذهبت إلى كذا","answer":"الجواب: إذا لم تعلم فالإثم عليها؛ لأن عليها السمع والطاعة، وعدم الخروج إلى المحل الذي منعتها منه إلا بأمر شرعي، ومسوغ شرعي، فإذا خرجت ولم تعلم فإن الإثم عليها، أما إذا علمت ففيه تفصيل:\nإن كنت أردت بهذا تحريمها إن فعلت هذا الشيء فعليك كفارة الظهار.\nوإن كنت أردت منعها فقط، أردت أن تمنعها من هذا الشيء لا تحريمها، فعليك كفارة اليمين: إطعام عشرة مساكين، أو كسوتهم، عشرة، يطعمهم على كل واحد يعطى كل واحد نصف صاع من التمر من قوت البلد من التمر، أو من الأرز، أو من الحنطة، أو من الذرة، إن كان قوت البلد، ويكفي عشرة، كل واحد يعطى نصف صاع، يعني: كيلو ونصف تقريبًا؛ لأن حكمها حكم اليمين، إذا كان يعني قال: هي محرمة إن فعلت كذا وكذا، إذا كان المقصود المنع وليس المقصود تحريمها تحريم الظهار، فإن عليه كفارة اليمين، وهي إطعام عشرة مساكين لكل مسكين نصف صاع من قوت البلد، مقداره كيلو ونصف تقريبًاً، أو كسوتهم على قميص قميص، أو إزار ورداء. أما إن كان المقصود تحريمها تحريم الظهار، تكون حرام عليه إذا فعلت، فعليه كفارة الظهار، وهي عتق رقبة مؤمنة، فإن عجز صام شهرين متتابعين، فإن لم يستطع أطعم ستين مسكينًا، ثلاثين صاعًا، كل مسكين له نصف الصاع، كيلو ونصف تقريبًا، قبل أن يمسها إذا كان قصده تحريمها، قبل أن يمسها. أما إن كان قصد بهذا الطلاق، أنها متى فعلت تطلق، فهذا يقع به طلقة واحدة، إذا كان قصده الطلاق، وأنها متى فعلت تطلق، يقع به واحدة، أما إن كان أراد المنع لم يرد طلاقًا ولا تحريمًا، وإنما أراد المنع فعليه كفارة اليمين فقط كما تقدم، نعم.\nالمقدم: لو فعلت ذلك وكان يقصد الطلاق فعلًا فتكون طالقًا من وقت الفعل أو من وقت؟\nالشيخ: إذا كان أراد الطلاق، إذا كان أراد إيقاع الطلاق تكون طالقة من وقت الفعل. المقدم: من وقت الفعل؟\nالشيخ: أما إذا كان أراد منعها فقط وتخويفها، ولم يرد منعها، ولا تحريمها، هذا فيه كفارة يمين، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14203/حكم-من-قال-لزوجته-انت-محرمة-علي-لو-ذهبت-الى-كذا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_699/nour_69909.mp3","categories":["الظهار","الطلاق","الأيمان والنذور"]},{"id":15681,"question":"من الجمهورية اليمنية هذه رسالة من إحدى الأخوات المستمعات من هناك تقول: أختكم في الله المستمعة (ج. ع) أختنا لها جمع من الأسئلة، من بينها سؤال يقول: إذا حلف الشخص ألا يعمل عملًا في الحاضر، وعمله في المستقبل، فهل تجب عليه الكفارة؟","title":"حكم من حلف أن لا يفعل شيئًا ما ثم فعله","answer":"الجواب: هذا يرجع إلى نيته، فإذا قال: والله لا أكلم فلانًا، وقصده في هذا اليوم المعين، ثم كلمه بعد ذلك فلا شيء عليه في المستقبل؛ لأنه إنما نوى اليوم الحاضر. وهكذا لو قال: والله لا أشتري السلعة الفلانية، وقصده اليوم، فلا شيء عليه إذا اشتراها بعد ذلك. أما إذا قال: والله لا أكلمه قصده أبدًا، أو قال: والله لا أشتري هذه السلعة أبدًا هذا قصده، فإنه متى كلمه أو اشتراها، وجبت عليه الكفارة، وهكذا ما يشابه ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14231/حكم-من-حلف-ان-لا-يفعل-شيىا-ما-ثم-فعله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_572/57202.mp3","categories":["الأيمان والنذور"]},{"id":15705,"question":"سائل: (ق. أ. ن) سوداني، يقول: سماحة الشيخ، عند زواجي أقسمت بالله للزوجة بألا أتزوج عليها، ما دامت على قيد الحياة، والحمد لله، لم يحدث بيننا أي شيء يكدر هذه الحياة الزوجية، ما حكم الشرع في هذا الحلف؟ مأجورين، وإذا أردت الزواج، ماذا أفعل؟","title":"حكم من حلف لامرأته ألا يتزوج عليها ثم أراد الزواج","answer":"الجواب: لا بأس أن تتزوج إذا دعت الحاجة، الله شرع لك أربعًا، إذا دعت الحاجة إلى أن تتزوج ثانية، أو ثالثة، أو رابعة، فلا بأس، وعليك كفارة يمين، عن قولك: والله ما أتزوج، عليك، كفارة يمين إذا تزوجت، وتعمل بالأصلح، إذا كنت في حاجة إلى الزواج فتتزوج، وكفر عن يمينك، وأرضها، أرض الزوجة بما تيسر من المال، أرضها -إذا لم ترض- أرضها بشيء يرضيها، عن وعدك لها، نعم. المقدم: أحسن الله إليكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/14263/حكم-من-حلف-لامراته-الا-يتزوج-عليها-ثم-اراد-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_573/57314.mp3","categories":["الأيمان والنذور"]},{"id":15709,"question":"في آخر أسئلة هذه السائلة، تقول -سماحة الشيخ-: نذرت أن أصوم شهرين، وكانت في نيتي أن أصومها متفرقة، وفعلًا فلقد صمت معظم هذه الشهرين بشكل منفرد، فهل عليّ شيء في ذلك؟","title":"حكم التتابع لمن نذر أن يصوم شهرين","answer":"الجواب: لا حرج، إذا كنتِ لم تنوي التتابع، قصدت شهرين متفرقة ستين يومًا، لا بأس، تصومينها متفرقة.\nأما إذا نوى الناذر صومها متتابعة، يصومها متتابعة، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/14267/حكم-التتابع-لمن-نذر-ان-يصوم-شهرين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_573/57318.mp3","categories":["الأيمان والنذور"]},{"id":15780,"question":"رسالة وصلت إلى البرنامج من المستمع خير الله درهم عايد، أبو التوم، من جمهورية مصر العربية، يقول: لي قريب متزوج من ثلاثين سنة، وهو كثير الحلف بالطلاق على أي شيء، يقول لزوجته: إذا لم تفعلي كذا، فأنت محرمة عليّ، أو يقول: طلاق منك لازم تفعلي كذا، رغم أنه لا ينوي طلاقها، بل من شدة الزعل، فما هو توجيه سماحتكم؟جزاكم الله خيرًا.","title":"ما التوجيه لمن يكثر الحلف بالطلاق","answer":"الجواب: المشروع أن ينصح هذا الرجل، ويعلم حتى يدع هذا التصرف، وحتى لا يستعمل الطلاق والتحريم، ينصح ويوجه إلى الخير، أما كونه يقع أو لا يقع هذا محل نظر؛ إن كان قصده التهديد والمنع والتخويف فعليه كفارة يمين، ولا يقع، إذا خالفته قال: إن فعلت كذا فأنت طالق، أو محرمة فخالفته، وهو قصده التهديد والتحذير والترهيب، فإن عليه كفارة يمين، وهي إطعام عشرة مساكين أو كسوتهم، عشرة كل واحد يعطى نصف الصاع، يعني: كيلو ونصف من الحنطة، أو من الرز، أو من التمر، أو تعشيه في البيت، أو تغديه في البيت، أو في المطعم لا بأس، أو يعطى كسوة يعني: عشرة، كفارة اليمين، هذا هو الذي ينبغي، ولكن ينصح ألا يتعاطى هذه الأمور بل يعالج الأمور بغير الطلاق، وبغير التحريم بالكلام الطيب، والترغيب والترهيب بدون الطلاق وبدون التحريم. فإن طلق يريد إيقاع الطلاق يقع الطلاق إذا خالفت شرطه، ويقع التحريم إذا خالفت شرطه، أما إذا كان المقصود تهديدها وتحذيرها وترهيبها فقط، ليس قصده الطلاق، فهذا مثلما تقدم، فيه كفارة يمين عند المخالفة، إذا خالفته ولم تنفذ ما قال، فعليه كفارة يمين، وهي إطعام عشرة مساكين، أو كسوتهم، أو تحرير رقبة، فإن كان عاجزًا فقيرًا لا يقدر، صام ثلاثة أيام، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14369/ما-التوجيه-لمن-يكثر-الحلف-بالطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_742/nour_74206.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":15784,"question":"رسالة وصلت إلى البرنامج من المستمع خير الله درهم عايد، أبو التوم، من جمهورية مصر العربية، يقول: لي قريب متزوج من ثلاثين سنة، وهو كثير الحلف بالطلاق على أي شيء، يقول لزوجته: إذا لم تفعلي كذا، فأنت محرمة عليّ، أو يقول: طلاق منك لازم تفعلي كذا، رغم أنه لا ينوي طلاقها، بل من شدة الزعل، فما هو توجيه سماحتكم؟جزاكم الله خيرًا.","title":"ما التوجيه لمن يكثر الحلف بالطلاق","answer":"الجواب: المشروع أن ينصح هذا الرجل، ويعلم حتى يدع هذا التصرف، وحتى لا يستعمل الطلاق والتحريم، ينصح ويوجه إلى الخير، أما كونه يقع أو لا يقع هذا محل نظر؛ إن كان قصده التهديد والمنع والتخويف فعليه كفارة يمين، ولا يقع، إذا خالفته قال: إن فعلت كذا فأنت طالق، أو محرمة فخالفته، وهو قصده التهديد والتحذير والترهيب، فإن عليه كفارة يمين، وهي إطعام عشرة مساكين أو كسوتهم، عشرة كل واحد يعطى نصف الصاع، يعني: كيلو ونصف من الحنطة، أو من الرز، أو من التمر، أو تعشيه في البيت، أو تغديه في البيت، أو في المطعم لا بأس، أو يعطى كسوة يعني: عشرة، كفارة اليمين، هذا هو الذي ينبغي، ولكن ينصح ألا يتعاطى هذه الأمور بل يعالج الأمور بغير الطلاق، وبغير التحريم بالكلام الطيب، والترغيب والترهيب بدون الطلاق وبدون التحريم. فإن طلق يريد إيقاع الطلاق يقع الطلاق إذا خالفت شرطه، ويقع التحريم إذا خالفت شرطه، أما إذا كان المقصود تهديدها وتحذيرها وترهيبها فقط، ليس قصده الطلاق، فهذا مثلما تقدم، فيه كفارة يمين عند المخالفة، إذا خالفته ولم تنفذ ما قال، فعليه كفارة يمين، وهي إطعام عشرة مساكين، أو كسوتهم، أو تحرير رقبة، فإن كان عاجزًا فقيرًا لا يقدر، صام ثلاثة أيام، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14369/ما-التوجيه-لمن-يكثر-الحلف-بالطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_742/nour_74206.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":15803,"question":"مستمعة تقول: السائلة سحر فاضل من العراق، تقول عن نفسها: سماحة الشيخ، إني من الفتيات اللواتي جذبتهن المدنية الحديثة، فأخذت أبحث عن آخر صيحات الموضة، وأبحث عن الرشاقة، فأقسمت إذ وضعت يدي على ألا أتذكر إما جزء عم أو تبارك، بألا أتناول الطعام في فترة العشاء، وكذلك لن أتناول الرز، ودمت على هذا الحال مدة تزيد عن سنتين، ولكن في يوم الجمعة المصادف الثامن عشر من الشهر الأول هداني الله  إلى الطريق المستقيم، فأديت الصلاة، سؤالي: كيف أصوم في شهر رمضان وأنا لا أتناول العشاء؟ وهل صلاتي مقبولة بالرغم من العمل الذي قمت به وهو القسم؟جزاكم الله خيرًا.","title":"حكم من نذر أن يمتنع عن العَشَاء ثم دخل رمضان","answer":"الجواب: هذا السؤال غير واضح، نحتاج إلى سؤال أوضح من هذا، ولو بالكتابة إلينا؛ لأن هذا السؤال فيه احتمالات، فيه احتمال ترك الصلاة.  فالمقصود: أن هذا السؤال ليس بواضح، نعم. المقدم: جزاكم الله خيرًا، إذًا يا أخت سحر إذا أردت الإجابة فاكتبي إلينا بطريقة أوضح، ولا تدخلين موضوعًا في آخر، جزاك الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14391/حكم-من-نذر-ان-يمتنع-عن-العشاء-ثم-دخل-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_743/nour_74307.mp3","categories":["الأيمان والنذور"]},{"id":15976,"question":"هذا سؤال من السائل أحمد بن قاسم بن عبد العزيز العبيدات من الدمام، يقول: والدي اشترى سيارة من زوج أختي، وكنت يومها متخاصمًا مع أخي، فحلفت، وقلت: علي بالطلاق بالثلاثة إذا سجلت السيارة باسم أخي لأحرقها، وحلفت اليمين وأنا غاضب على أخي جدًا، ولم أكن أنوي الطلاق حقيقة، وإنما تخويفًا لهم، فهل إذا حرقتها الآن أكون قد وفيت بيميني أم لا، أو ما ذا علي أن أفعل؟","title":"حكم الحلف بالطلاق بنية المنع والتخويف","answer":"الجواب: عليك كفارة يمين، ما دمت أردت تخويفهم ومنعهم، فعليك التوبة والاستغفار من هذا العمل، وعليك كفارة يمين، وذلك بإطعام عشرة مساكين -عشرة فقراء- لكل فقير نصف صاع من التمر، أو من الأرز، أو الحنطة، أو غيرها من قوت البلد، وإن عشيتهم أو غديتهم أو كسوتهم على قميص كفى ذلك والحمد لله، نسأل الله للجميع الهداية، نعم. ولا يقع الطلاق، لا يقع الطلاق؛ لأن الطلاق بهذا المعنى في حكم اليمين، ولا يقع بها طلاق؛ لأنك ما أردت إيقاع الطلاق، وإنما أردت التخويف والمنع من هذا العمل، نعم.\nالمقدم: إحراقه للسيارة؟\nالشيخ: لا، لا يحرق السيارة، يكفر كفارة يمين، ولا يحرق السيارة، هذا إضاعة مال وظلم، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/14617/حكم-الحلف-بالطلاق-بنية-المنع-والتخويف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_680/nour_68010.mp3","categories":["الأيمان والنذور"]},{"id":15980,"question":"هذا سؤال من السائل أحمد بن قاسم بن عبد العزيز العبيدات من الدمام، يقول: والدي اشترى سيارة من زوج أختي، وكنت يومها متخاصمًا مع أخي، فحلفت، وقلت: علي بالطلاق بالثلاثة إذا سجلت السيارة باسم أخي لأحرقها، وحلفت اليمين وأنا غاضب على أخي جدًا، ولم أكن أنوي الطلاق حقيقة، وإنما تخويفًا لهم، فهل إذا حرقتها الآن أكون قد وفيت بيميني أم لا، أو ما ذا علي أن أفعل؟","title":"حكم الحلف بالطلاق بنية المنع والتخويف","answer":"الجواب: عليك كفارة يمين، ما دمت أردت تخويفهم ومنعهم، فعليك التوبة والاستغفار من هذا العمل، وعليك كفارة يمين، وذلك بإطعام عشرة مساكين -عشرة فقراء- لكل فقير نصف صاع من التمر، أو من الأرز، أو الحنطة، أو غيرها من قوت البلد، وإن عشيتهم أو غديتهم أو كسوتهم على قميص كفى ذلك والحمد لله، نسأل الله للجميع الهداية، نعم. ولا يقع الطلاق، لا يقع الطلاق؛ لأن الطلاق بهذا المعنى في حكم اليمين، ولا يقع بها طلاق؛ لأنك ما أردت إيقاع الطلاق، وإنما أردت التخويف والمنع من هذا العمل، نعم.\nالمقدم: إحراقه للسيارة؟\nالشيخ: لا، لا يحرق السيارة، يكفر كفارة يمين، ولا يحرق السيارة، هذا إضاعة مال وظلم، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/14617/حكم-الحلف-بالطلاق-بنية-المنع-والتخويف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_680/nour_68010.mp3","categories":["الأيمان والنذور"]},{"id":16018,"question":"يقول أخونا في سؤاله الثاني: ما الحكم في رجل كان يصوم نذرًا لله ثلاثة أيام، وفي اليوم الثالث لم يكمل صومه، فهل عليه إثم في ذلك أو كفارة؟جزاكم الله خيرًا.","title":"حكم من أفطر متعمدًا في صوم النذر","answer":"الجواب: نعم عليه إثم في ذلك إذا تعمد الفطر، أما إذا كان ناسيًا؛ فلا شيء عليه، أما إذا كان ثلاثة أيام نذرها يصومها، ثم أفطر في واحد منها يكون يأثم؛ لأن الرسول -عليه الصلاة والسلام- قال: من نذر أن يطيع الله فليطعه فليس له أن يفطر في اليوم الذي نذر صومه عليه أن يصوم، وإذا شرع في الصوم أمسك حتى يكمل، فإذا أفطر فيه؛ لزمه قضاؤه بدل اليوم الذي أفطر فيه، نعم. المقدم: جزاكم الله خيرًا، أما كفارة فليس عليه كفارة؟ الشيخ: لا، الكفارة تخص المرأة. المقدم: بارك الله فيكم، وجزاكم الله خيرًا. الشيخ: تخص من وطئ في رمضان خاصة، حتى قضاء رمضان ما فيه كفارة، إلا من وطئ في نفس رمضان، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14659/حكم-من-افطر-متعمدا-في-صوم-النذر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_801/nour_80106.mp3","categories":["الأيمان والنذور"]},{"id":16028,"question":"يقول أخونا في سؤاله الثاني: ما الحكم في رجل كان يصوم نذرًا لله ثلاثة أيام، وفي اليوم الثالث لم يكمل صومه، فهل عليه إثم في ذلك أو كفارة؟جزاكم الله خيرًا.","title":"حكم من أفطر متعمدًا في صوم النذر","answer":"الجواب: نعم عليه إثم في ذلك إذا تعمد الفطر، أما إذا كان ناسيًا؛ فلا شيء عليه، أما إذا كان ثلاثة أيام نذرها يصومها، ثم أفطر في واحد منها يكون يأثم؛ لأن الرسول -عليه الصلاة والسلام- قال: من نذر أن يطيع الله فليطعه فليس له أن يفطر في اليوم الذي نذر صومه عليه أن يصوم، وإذا شرع في الصوم أمسك حتى يكمل، فإذا أفطر فيه؛ لزمه قضاؤه بدل اليوم الذي أفطر فيه، نعم. المقدم: جزاكم الله خيرًا، أما كفارة فليس عليه كفارة؟ الشيخ: لا، الكفارة تخص المرأة. المقدم: بارك الله فيكم، وجزاكم الله خيرًا. الشيخ: تخص من وطئ في رمضان خاصة، حتى قضاء رمضان ما فيه كفارة، إلا من وطئ في نفس رمضان، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14659/حكم-من-افطر-متعمدا-في-صوم-النذر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_801/nour_80106.mp3","categories":["الأيمان والنذور"]},{"id":16072,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلينا من إحدى الأخوات المستمعات تسأل فيها بعض الأسئلة، تقول في سؤالها الأول: عندما كان عمري أربعة عشر عامًا مرضت أمي مرضًا شديدًا، وخفت كثيرًا عليها، فنذرت نذرًا لله إن شفيت أمي؛ سوف أصوم شهر شعبان كلما هلَّ، أرجو إفادتي عن الأمر التالي: أنا الآن لا أذكر هل بلغت، أم لم أبلغ في ذلك الوقت، وبعد مضي فترة من مرض أمي شفيت بإذن الله تعالى، احترت كثيرًا يا سماحة الشيخ! ماذا أفعل؟ أفيدوني جزاكم الله خيرًا.","title":"حكم من لا يدري وقت النذر هل بلغ أم لا","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد.  فقد ثبت عن رسول الله -عليه الصلاة والسلام- أنه نهى عن النذر وقال: إنه لا يأتي بخير، وإنما يستخرج به من البخيل وفي لفظ آخر يقول ﷺ: لا تنذروا فإن النذر لا يرد من قدر الله شيئًا، وإنما يستخرج به من البخيل. فأوصيك أيها الأخت في الله! بعدم النذر في المستقبل، وإذا وقع مثل هذا من مرض الوالدة، أو غير الوالدة؛ فالحمد لله، المشروع الدعاء لها بالشفاء والعافية، والعلاج الشرعي لا بأس، أما هذا النذر فإن كنت لا تعلمين أنك قد بلغت؛ فليس عليك الوفاء، لا يلزمك الوفاء. وأما إذا كنت تعلمين أنك قد بلغت بإكمال خمسة عشر سنة، أو بالاحتلام، أو بإنبات الشعر، أو بالحيض، إذا كنت قد وجد منك واحدة؛ فأنت بالغة، عليك أن تصومي شعبان كل سنة كما نذرت؛ لأن النبي  قال: من نذر أن يطيع الله؛ فليطعه هكذا صح عن رسول الله ﷺ أنه قال: من نذر أن يطيع الله؛ فليطعه، ومن نذر أن يعصي الله؛ فلا يعصه ولا تعودي، لا ترجعي إلى مثل هذا في المستقبل، لا تنذري أبدًا، بارك الله فيك. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14703/حكم-من-لا-يدري-وقت-النذر-هل-بلغ-ام-لا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_803/nour_80301.mp3","categories":["الأيمان والنذور"]},{"id":16130,"question":"رسالة من أحد الإخوة المستمعين آثر عدم ذكر اسمه يسأل في سؤاله الأول ويقول: الذي يكون عاقًا لوالديه، هل تقبل منه صلاته وصومه وصدقته؟ وبماذا تنصحون الناس؟ جزاكم الله خيرًا.","title":"حكم قبول أعمال العاق لوالديه والحلف على المصحف","answer":"الجواب: عقوق الوالدين من كبائر الذنوب، ومن المحرمات العظيمة، فالواجب الحذر منه، وقد ثبت عن رسول الله -عليه الصلاة والسلام- أنه قال: إن الله حرم عليكم عقوق الأمهات وقال -عليه الصلاة والسلام-: ألا أنبئكم بأكبر الكبائر؟ قلنا: بلى يا رسول الله! قال: الإشراك بالله، وعقوق الوالدين وكان متكئًا فجلس فقال: ألا وقول الزور، ألا وشهادة الزور متفق على صحته.  والله يقول في كتابه الكريم : وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ [الإسراء:23] يعني: أمر أن لا تعبدوا إلا إياه وَبِالْوَالِدَيْنِ إِحْسَانًا إِمَّا يَبْلُغَنَّ عِنْدَكَ الْكِبَرَ أَحَدُهُمَا أَوْ كِلاهُمَا فَلا تَقُلْ لَهُمَا أُفٍّ وَلا تَنْهَرْهُمَا وَقُلْ لَهُمَا قَوْلًا كَرِيمًا ۝ وَاخْفِضْ لَهُمَا جَنَاحَ الذُّلِّ مِنَ الرَّحْمَةِ وَقُلْ رَّبِّ ارْحَمْهُمَا كَمَا رَبَّيَانِي صَغِيرًا [الإسراء:23، 24] ويقول سبحانه في سورة لقمان: أَنِ اشْكُرْ لِي وَلِوَالِدَيْكَ إِلَيَّ الْمَصِيرُ [لقمان:14]. فالواجب على الولد أن يشكر لوالديه، وأن يحسن إليهما، وأن يبرهما، وأن يطيعهما في المعروف، ويحرم عليه عقوقهما لا بالكلام، ولا بالفعل، فليس له أن يرفع صوته عليهما، وليس له ضربهما، وليس له عدم النفقة عليهما مع الحاجة إلى ذلك، وليس له عصيانهما في المعروف، بل يجب عليه طاعتهما في المعروف، وبرهما، وخفض الصوت إذا خاطبهما، والتأدب معهما في كل شيء. لكن لا يطيعهما في المعصية، يقول النبي ﷺ: إنما الطاعة في المعروف لا طاعة لمخلوق في معصية الخالق فلو أمراه أن يزني، أو يشرب الخمر، أو لا يصلي في الجماعة؛ لا يطيعهما، لكن يطيعهما في المعروف، يبرهما في المعروف، يحسن إليهما، يخاطبهما بالتي هي أحسن، ينفق عليهما إذا احتاجا إلى ذلك، هكذا المؤمن مع والديه، فحقهما عظيم، وبرهما من أهم الواجبات،. لكن ليس عقوقهما مبطلًا للصلاة، ولا للصوم، ولا للأعمال الصالحات، ولكن صاحبه على خطر من هذه الكبيرة العظيمة. وإنما تبطل الأعمال بالشرك، قال تعالى: وَلَوْ أَشْرَكُوا لَحَبِطَ عَنْهُمْ مَا كَانُوا يَعْمَلُونَ [الأنعام:88] أما بالعقوق، أو قطيعة الرحم، أو المعاصي الأخرى فإنها لا تبطل الأعمال، وإنما يبطلها الشرك الأكبر. وكذلك رفع الصوت على رسول الله ﷺ يخشى منه بطلان العمل في حياته ﷺ كما قال الله : يَا أَيُّهَا الَّذِينَ آمَنُوا لا تَرْفَعُوا أَصْوَاتَكُمْ فَوْقَ صَوْتِ النَّبِيِّ وَلا تَجْهَرُوا لَهُ بِالْقَوْلِ كَجَهْرِ بَعْضِكُمْ لِبَعْضٍ أَنْ تَحْبَطَ أَعْمَالُكُمْ وَأَنْتُمْ لا تَشْعُرُونَ [الحجرات:2] يعني: لئلا تحبط أعمالكم، فهذا يفيد أنه يخشى على من رفع صوته على النبي ﷺ وجهر له بالقول أن يحبط عمله، وهذا وعيد عظيم، ولهذا كان الصحابة يتأدبون مع الرسول ﷺ ويتكلمون معه كلامًا خفيفًا لينًا مخفوضًا تأدبًا معه، عليه الصلاة والسلام. فالمقصود: أن الواجب على المؤمن أن يبر والديه، وأن لا يعقهما، وأن يحسن إليهما في حياتهما، وبعد وفاتهما، ويحرم عليه العقوق لهما بالكلام السيء، أو السب، أو الضرب، أو أي إساءة لهما، أو رفع الصوت عليهما، أو عدم طاعتهما في المعروف، كل هذا من العقوق. المقدم: جزاكم الله خيرًا.  الشيخ: نسأل الله العافية. المقدم: اللهم آمين. المقدم: يسأل أيضًا أخونا ويقول: إذا حلف إنسان على القرآن وهو يحلف في نفسه، هل يجوز هذا، أم لا؟ الشيخ: كيف؟ المقدم: يقول: إذا حلف إنسان على القرآن، وهو يحلف في نفسه -لعله يقصد سرًا- هل يجوز، أم لا؟ جزاكم الله خيرًا. الشيخ: هذا السؤال ليس بواضح، إذا حلف على القرآن؛ صار أشد في اليمين، وليس هناك حاجة إلى الحلف بالقرآن، يحلف ولا حاجة إلى أن يحضر القرآن، يتقي الله وهو يحلف، ويتحرى الصدق، ولا يلزم إحضار القرآن، كثير من الناس يطلب إحضار القرآن، هذا لا أصل له، ولا حاجة إليه. الواجب على المؤمن أن يصدق أينما كان، ولا يجوز الكذب لا مع قرآن، ولا مع غير القرآن، يجب أن يصدق في الخصومات وفي غيرها، وليس له الكذب إلا إذا كان مظلومًا، إذا كان مظلومًا؛ فله الكذب، ويتأول إذا كان مظلومًا. وأما إذا كان غير مظلوم؛ فليس له أن يكذب، وليس له أن يحلف في أي شيء كاذبًا، كأن يدعى عليه أنه أخذ مال فلان، أو ضرب فلانًا، أو قتل فلانًا، ليس له أن يحلف، ينكر ذلك، بل عليه أن يقر بالحق، يعطيهم مالهم، يلزمه القصاص إذا توفرت شروطه، لا يكذب. أما إذا كان مظلومًا هذا شيء آخر، له أن يتأول إذا كان مظلومًا، أن يقال له: احلف أنك ما فعلت كذا وكذا، وهو لم يفعله، ولم يقع منه، فيحلف بالله أنه لم يقع منه، وليس في هذا شيء عليه؛ لأنه صادق. المقصود: أنه ليس له أن يكذب لا بإحضار القرآن، ولا في غير القرآن، بل عليه أن يتحرى الصدق إلا في المسائل التي أباح فيها النبي ﷺ الكذب، كالإصلاح بين الناس، والحرب، وحديث الرجل امرأته، فإذا كان ألزم باليمين في هذا، أو رأى المصلحة في هذا؛ فلا بأس أن يقول: والله ما كان كذا في الحرب، أو والله ما فعلت كذا في الحرب، إذا رأى فيه المصلحة للمسلمين. أو والله ما -يقول لامرأته-: والله ما فعلت هذا ليرضيها، ولا يضر غيره، ولا غيرها، أو في الإصلاح بين الناس، يجي قبيلة ويقول: والله ما قال هذا فلان ... يصلح بينهم، أو والله ما قالت القبيلة، أو والله إنها تحبكم، أو والله إنها تود الصلح معكم؛ ليصلح بينهم على وجه لا يضر أحدًا، هذا كله لا بأس به. المقدم: جزاكم الله خيرًا، إذًا نفهم من سماحتكم أن الحلف على المصحف أمر غير مشروع. الشيخ: ليس له أصل، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14786/حكم-قبول-اعمال-العاق-لوالديه-والحلف-على-المصحف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_803/nour_80311.mp3","categories":["الأيمان والنذور","البيوع","نصائح وتوجيهات"]},{"id":16133,"question":"بعد هذا رسالة من أحد الإخوة المستمعين يقول عبدالله حامد صالح أخونا له جمع من الأسئلة، يقول: فسروا لنا قول الحق -تبارك وتعالى-: لا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ [المائدة:89] إلى آخر الآية؟ جزاكم الله خيرًا.","title":"تفسير قوله تعالى: {لا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ}","answer":"الجواب: يقول سبحانه في سورة المائدة: لا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِنْ يُؤَاخِذُكُمْ بِمَا عَقَّدْتُمُ الأَيْمَانَ فَكَفَّارَتُهُ إِطْعَامُ عَشَرَةِ مَسَاكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍ فَمَنْ لَمْ يَجِدْ فَصِيَامُ ثَلاثَةِ أَيَّامٍ ذَلِكَ كَفَّارَةُ أَيْمَانِكُمْ إِذَا حَلَفْتُمْ وَاحْفَظُوا أَيْمَانَكُمْ [المائدة:89] الآية، ويقول سبحانه في سورة البقرة: لا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِنْ يُؤَاخِذُكُمْ بِمَا كَسَبَتْ قُلُوبُكُمْ وَاللَّهُ غَفُورٌ حَلِيمٌ [البقرة:225]. والمعنى أن الأيمان التي تمر على الإنسان من غير قصد لا يؤاخذ بها، ولا كفارة فيها، تجري على لسانه من دون قصد لعقدها في عرض كلامه: والله! ما صار كذا، والله! صار كذا، يتحدث من غير قصد اليمين، هذا هو اللغو في اليمين كما قالت عائشة، وجماعة من السلف، لغو اليمين أن يقول الرجل: لا والله، وبلى والله، في عرض كلامه. أما إذا قصد بقلبه كسب قلبه بذلك يعني: أراد بقلبه اليمين على أنه ما يفعل كذا، أو أنه يترك كذا؛ فهذا يؤاخذ بها إذا أخل بها عليه الكفارة؛ لأن الله قال: وَلَكِنْ يُؤَاخِذُكُمْ بِمَا كَسَبَتْ قُلُوبُكُمْ [البقرة:225] وفي آية المائدة: بِمَا عَقَّدْتُمُ الأَيْمَانَ [المائدة:89] يعني: بما قصدتم من عقدها، وأردتم ذلك، فإذا قال: والله! لا أكلم فلانًا؛ قاصدًا فإذا كلمه؛ فعليه كفارة اليمين، إطعام عشرة مساكين، أو كسوتهم، أو عتق رقبة، فإن عجز ولم يستطع؛ صام ثلاثة أيام. أو قال: والله! ما أزور فلانًا، ثم زاره؛ عليه كفارة يمين، أو قال لزوجته: والله! ما تكلمي فلانًا، أو والله ما تخرجي من البيت اليوم، أو هذه الليلة، أو أبدًا.. أو ما أشبه ذلك، إذا خرجت؛ عليه كفارة اليمين. وهكذا ما أشبه ذلك؛ لأن هذه أيمان مقصودة، قد كسبها القلب، وعقدها صاحبها؛ فيكون فيها الكفارة، والكفارة -كما سمعتم في الآية الكريمة- إطعام عشرة مساكين من أوسط ما تطعمون أهليكم، يعني: طعام الوسط، تمر من الرز، من الحنطة إذا كان معه إدام يكون أفضل، وهكذا إذا صنع لهم الطعام، ودعوا إليه في البيت، أو المطعم، غداء، أو عشاء، وجبة واحدة تكفي، وجبة واحدة. أو كسوتهم يكسوهم... أو إزار ورداء لكل واحد، يعني: قميص أو إزار ورداء، أو يعتق رقبة عبد وإلا عبدة، فإذا لم يستطع هذه الثلاث؛ انتقل إلى الصوم، صام ثلاثة أيام، والأفضل أن تكون متتابعة، ثلاثة أيام والأفضل تتابعها، وقال بعض أهل العلم: يجب تتابعها، فالأفضل للمؤمن أن يتابعها هذه الثلاثة، عند العجز عن الإطعام، والكسوة، والعتق، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14788/تفسير-قوله-تعالى-لا-يواخذكم-الله-باللغو-في-ايمانكم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_713/nour_71304.mp3","categories":["التفسير","الأيمان والنذور"]},{"id":16144,"question":"يسأل سؤالًا آخر، فيقول: رجل اعتاد الحلف بالحرام، فهو يقول دائمًا: علي الحرام لأفعل كذا، ولا أفعل كذا.. وما أشبه ذلك، هل يؤثر هذا على النكاح؟","title":"حكم الحلف بالحرام وكفارته","answer":"الجواب: هذا حكمه حكم اليمين، إذا قال: علي الحرام ما أكلم فلانًا، علي الحرام، ما آكل كذا، علي الحرام ما أسافر، وما أشبه ذلك هذا حكمه حكم اليمين، فيه كفارة اليمين، لقول الله : يَا أَيُّهَا النَّبِيُّ لِمَ تُحَرِّمُ مَا أَحَلَّ اللَّهُ لَكَ تَبْتَغِي مَرْضَاةَ أَزْوَاجِكَ وَاللَّهُ غَفُورٌ رَحِيمٌ  ۝ قَدْ فَرَضَ اللَّهُ لَكُمْ تَحِلَّةَ أَيْمَانِكُمْ [التحريم:1-2] نزلت في تحريمه العسل، وفي قول آخر: أنه تحريمه مارية، مملوكة له بسبب ما جرى بين أزواجه في ذلك: حفصة وعائشة وزينب في شأن العسل، أو شأن الجارية، حلف وحرم أنه لا يقربها، أو حرم ألا يأكل العسل؛ فأنزل الله الآية المذكورة، وهي قوله سبحانه: يَا أَيُّهَا النَّبِيُّ لِمَ تُحَرِّمُ مَا أَحَلَّ اللَّهُ لَكَ تَبْتَغِي مَرْضَاةَ أَزْوَاجِكَ وَاللَّهُ غَفُورٌ رَحِيمٌ  ۝ قَدْ فَرَضَ اللَّهُ لَكُمْ تَحِلَّةَ أَيْمَانِكُمْ [التحريم:1-2] قال ابن عباس: معنى ذلك أن في الحرام كفارة اليمين، وهكذا قال جمع من أهل العلم. إلا إذا قصد تحريم زوجته إذا قصد.. إذا صار في نيته عليه الحرام من زوجته، فهذا فيه كفارة الظهار، المذكورة في سورة المجادلة، وهي عتق رقبة مؤمنة، فإن عجز؛ صام شهرين متتابعين، فإن عجز؛ أطعم ستين مسكينًا ثلاثين صاعًا، قبل أن يقربها، قبل أن يمسها، كل صاع يقسم بين اثنين، كل واحد له نصف الصاع، كيلو ونص كل واحد من التمر أو من الحنطة، ستين مسكينًا، يعطى كل واحد كيلو ونص، تسعين كيلو، ثلاثين صاعًا قبل أن يمسها. أما إذا كان ما قصد الزوجة، جرى على لسانه هكذا، أو قصد الامتناع من هذا الشيء، ولم يقصد الزوجة، فهذا فيه كفارة اليمين كما تقدم، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14797/حكم-الحلف-بالحرام-وكفارته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_713/nour_71305.mp3","categories":["الأيمان والنذور","الظهار"]},{"id":16157,"question":"يقول: إنني في يوم من الأيام حلفت على زوجتي ألا تذهب إلى أهلها، وقد حلفت خوفًا من الكلام، فهل يكون علي إثم؟ أرجو الإفادة جزاكم الله خيرًا.","title":"حكم من حلف ليمنع زوجته من زيارة أهلها","answer":"الجواب: إذا حلفت عليها لمصلحة شرعية فلا بأس إذا كان أهلها يعلمونها الشر، وينشزونها عليك؛ فلا بأس، وإلا فاسمح لها، وكفر عن يمينك، إذا كنت حلفت؛ كفر عن يمينك كفارة.. إطعام عشرة مساكين من الفقراء، كل واحد يعطى نصف الصاع من التمر، أو الرز، أو الحنطة، أو غيره من قوت البلد، ومقداره كيلو ونصف، أو كسوة قميص، يعطى كل واحد كسوة عن اليمين عشرة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14824/حكم-من-حلف-ليمنع-زوجته-من-زيارة-اهلها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_750/nour_75008.mp3","categories":["الأيمان والنذور"]},{"id":16182,"question":"يسأل ويقول: ما حكم من يحلف بالحرام عادة في كل لحظة؟ جزاكم الله خيرًا.","title":"حرمة الحلف بالحرام","answer":"الجواب: هذا لا يجوز، الحلف بالحرام منكر، كما قال الله في الظهار: وَإِنَّهُمْ لَيَقُولُونَ مُنْكَرًا مِنَ الْقَوْلِ وَزُورًا [المجادلة:2] والله أنكر على نبيه ﷺ قال: يَا أَيُّهَا النَّبِيُّ لِمَ تُحَرِّمُ مَا أَحَلَّ اللَّهُ لَكَ [التحريم:1] فلا يجوز للمسلم أن يحرم ما أحل الله له، ولا يقول: علي الحرام ما أفعل كذا.. علي الحرام لأفعلن كذا.. علي الحرام ما أسافر.. علي الحرام ما أكلم فلانًا.. كل هذا لا يجوز. فإذا دعت الحاجة يحلف، يقول: والله ما أفعل كذا، يحلف إذا دعت الحاجة، أما التحريم فلا لا يجوز، وعليه كفارة اليمين إذا حلف بالحرام أنه ما يفعل هذا الشيء وفعله؛ عليه كفارة يمين، أو قال: عليه الحرام ليفعلنه.. ولم يفعله هذه كفارة يمين، كفارة التحريم، كفارة اليمين، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14847/حرمة-الحلف-بالحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_750/nour_75016.mp3","categories":["الأيمان والنذور"]},{"id":16354,"question":"ما هي كفارة اليمين بشيء من التفصيل؟ جزاكم الله خيرًا.","title":"ما هي كفارة اليمين؟","answer":"الجواب: كفارة اليمين أوضحها الله في القرآن في سورة المائدة في قوله سبحانه: لا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِنْ يُؤَاخِذُكُمْ بِمَا عَقَّدْتُمُ الأَيْمَانَ فَكَفَّارَتُهُ إِطْعَامُ عَشَرَةِ مَسَاكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍ فَمَنْ لَمْ يَجِدْ فَصِيَامُ ثَلاثَةِ أَيَّامٍ ذَلِكَ كَفَّارَةُ أَيْمَانِكُمْ إِذَا حَلَفْتُمْ وَاحْفَظُوا أَيْمَانَكُمْ [المائدة:89] الآية. هذه كفارة اليمين، وضحها ربنا  في سورة المائدة، وهي إطعام عشرة مساكين، لكل مسكين نصف صاع من التمر، أو الحنطة، أو الرز، كيلو ونص تقريبًا لكل فقير، خمسة عشر كيلو، لكل فقير كيلو ونص -نصف الصاع- أو يعشيهم، أو يغديهم في بيته، أو في المطعم يكفي. أو يكسوهم كسوة، كل واحد يعطيه إزارًا، ورداء، أو قميصًا... أو يعتق رقبة، عبدًا أو أمة، فإن عجز عن هذه الثلاث؛ يصوم ثلاثة أيام، والأفضل أن تكون متتابعة، يصوم ثلاثة أيام، والأفضل أن تكون متتابعة؛ لأن بعض أهل العلم رآها شرطًا، رأى أن التتابع شرط، فينبغي له ألا يدع التتابع، يصوم ثلاثة أيام متتابعة على الأحوط، وإن صامها متفرقة؛ أجزأه، لكن صومها متتابعة أولى، وأحوط، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم، يسأل بالذات سماحة الشيخ في كفارة اليمين: هل نحن بالخيار، أم لابد أن هناك شيء معين؟ الشيخ: بالخيار في الثلاثة: الإطعام، والكسوة، والعتق ثلاث، يختار واحدة من الثلاث، إن شاء أطعم، وإن شاء كسا، وإن شاء أعتق. أما الصوم فلا يعدل إليه إلا عند العجز عن الثلاث، الصوم لا يجزي إلا عند العجز عن الإطعام، والكسوة، والعتق، إذا عجز صار فقيرًا، لا يستطيع إطعام طعام، ولا كسوة، ولا عتقًا؛ فإنه ينتقل للصوم، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15048/ما-هي-كفارة-اليمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_714/nour_71417.mp3","categories":["الأيمان والنذور"]},{"id":16355,"question":"يقول أحد الإخوة المستمعين، وقد رمز إلى اسمه بالحروف (ع. م. ع) من الباحة يقول: لقد نذرت عندما رزقت بمولود أن أعلمه التعليم الديني، ولكن عندما كبر لم أتمكن، وسلك مسلكًا آخر، فما الحكم؟ وبماذا توجهونني؟ جزاكم الله خيرًا.","title":"حكم من نذر تعليم ابنه العلم الشرعي ولم يتمكن","answer":"الجواب: عليك أن تعلمه العلوم الدينية، وعليك أن تجتهد في ذلك، وأن توفي بنذرك، هذا واجب عليك حتى ولو لم تنذر، يجب عليك أن تسعى في صلاحه، وتعليمه، وتوجيهه إلى الخير، فإذا كنت نذرت ذلك؛ وجب بتأكد؛ لقول النبي ﷺ: من نذر أن يطيع الله؛ فليطعه وأنت نذرت طاعة لله؛ لأن تعليم الولد أمور الدين، وتشجيعه على ذلك، والعناية به، هذا من أفضل الطاعات. فالواجب عليك أن توفي بنذرك، وأن تجتهد في تعليمه الدين، ولو بعد كبره، عليك أن توفي بهذا، وأن تجتهد في إحضاره حلقات العلم، أو انتظامه في المدارس الدينية حتى يتعلم، ولا مانع أن تستعين على ذلك بخواص أهل بيتك، من أعمام، أو إخوان، أو غيرهم، أو أصدقاء، طيبين يعينونك على هذا الولد. بارك الله فيك. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15049/حكم-من-نذر-تعليم-ابنه-العلم-الشرعي-ولم-يتمكن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_714/nour_71418.mp3","categories":["الأيمان والنذور"]},{"id":16366,"question":"يقول في سؤاله الثاني: أو القسم بالرسول ﷺ؟","title":"هل يجوز الحلف بالنبي؟","answer":"الجواب: لا يجوز الحلف بغير الله، لا بالرسول ﷺ ولا بغيره من الخلق، هذا من خصائص الله هو الذي يقسم بما يشاء  كما أقسم بالطور، والسماء ذات البروج، والليل إذا يغشى، وغير ذلك. أما المخلوق فليس له أن يحلف إلا بالله وحده  لأن الحلف تعظيم، لا يليق إلا بالله  وهو الذي يعلم سر العبد، وصدقه، وكذبه، وهو الذي يجازي على الصدق والكذب  ولهذا صح عن رسول الله -عليه الصلاة والسلام- أنه قال: من كان حالفًا؛ فليحلف بالله، أو ليصمت متفق على صحته، وفي لفظ يقول ﷺ: من كان حالفًا؛ فلا يحلف إلا بالله، أو ليصمت. وفي مسند أحمد بإسناد صحيح عن عمر بن الخطاب -رضي الله تعالى عنه- عن النبي ﷺ أنه قال: من حلف بشيء دون الله؛ فقد أشرك وإسناده صحيح، وهذا عام، يعم الأنبياء، وغير الأنبياء. وفي السنن -سنن أبي داود والترمذي- بإسناد صحيح عن عبد الله بن عمر بن الخطاب -رضي الله تعالى عنهما- عن النبي ﷺ أنه قال: من حلف بغير الله؛ فقد كفر، أو أشرك شك من الراوي هل قال: كفر، أو قال أشرك، وهذا يدل على تحريم الحلف بغير الله تحريمًا شديدًا، وأنه من المحرمات الكفرية، وهو عند أهل العلم كفر أصغر، وشرك أصغر إلا أن يقوم بقلبه تعظيم المخلوق مثل تعظيم الله، أو يعتقد فيه أنه يصلح أن يعبد من دون الله، يكون فيه الشرك الأكبر، نسأل الله العافية، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15081/هل-يجوز-الحلف-بالنبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_811/nour_81102.mp3","categories":["الأيمان والنذور","الحلف بغير الله"]},{"id":16389,"question":"رسالة من أحد الإخوة المستمعين يقول: كان عندي شيء، وحلفت بالطلاق أن لا أبيعه، وبعد ذلك احتجت لقيمته؛ ثم بعته، هل وقع الطلاق؟ ثم حصل لي قضية أخرى، وقلت لزوجتي: إني لن أفعل الشيء الفلاني؛ لأنه حرام، وحلفت ألا أفعله، لكني فعلته بعد أن حلفت بالطلاق، ما الحكم فيما فعلت، وهل زوجتي حلال؟ جزاكم الله خيرًا.","title":"حكم من حلف بالطلاق على عدم فعل شيء ثم فعله","answer":"الجواب: إن كان المقصود إيقاع الطلاق؛ وقع الطلاق بالفعل بالبيع، وبالشيء الذي طلقت ألا تفعله، أما إذا كان المقصود: الامتناع من البيع، والامتناع من الفعل الذي أردت ألا تفعله، ليس قصدك إيقاع الطلاق، إنما قصدك التشديد على نفسك بأن تمتنع، وتحذر هذا الشيء، ثم فعلته؛ فعليك كفارة يمين: وهي إطعام عشرة مساكين، أو كسوتهم، أو عتق رقبة، فمن عجز؛ صام ثلاثة أيام، هذا إذا كان قصده الامتناع من البيع، والامتناع من الشيء الذي أردت ألا تفعله، وليس قصدك إيقاع الطلاق، أما إن كان قصدك الامتناع، وإيقاع الطلاق جميعًا؛ فإنه يقع بهذا طلقة على الزوجة، إذا فعلت ما حلفت على تركه. وننصحك بألا تعتاد هذه الأمور، وأن تجتنب الطلاق، وإذا دعت الحاجة؛ تكتفي باليمين، تقول: والله ما أفعل كذا، أو والله لأفعلن كذا، يكفي اليمين فيها كفاية، أما... الطلاق فهو شيء خطير، وربما فات ذلك زوجتك، وأنت لا تشعر بسبب تساهلك بهذا الأمر. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15106/حكم-من-حلف-بالطلاق-على-عدم-فعل-شيء-ثم-فعله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_754/nour_75420.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":16511,"question":"تقول: نذرت أن أصوم ثلاثة أشهر في كل عام شهرًا، هل يجب علي صوم الشهر متتال، ودون انقطاع؟ أم يجوز صومه متقطعًا، والمهم صوم ثلاثين يومًا؟ وإن لم يكن يجوز صومه متقطعًا هل من كفارة أخرجها؛ لأني صمت هذا العام شهرًا، ولكن غير متتال مع أنني لم أتأكد من نذره؛ متتال، أم لا؟ جزاكم الله خيرًا.","title":"حكم التتابع لمن نذرت أن تصوم شهرًا","answer":"الجواب: إذا كنت لا تعلمين أنك نويت التتابع؛ فإنه يجزي صوم ثلاثين يومًا، وإن كانت متفرقة، والتتابع أولى، لكن إذا لم يتيسر تجزئ الثلاثون، والحمد لله، يعني: صوم الثلاثين يجزئ -إن شاء الله- إلا إذا كنت شرطت التتابع، أو نويت التتابع جزمًا يقينًا، أما مع الشك فلا يلزمك التتابع، ويكفي ما فعلت من الصوم والحمد لله. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15232/حكم-التتابع-لمن-نذرت-ان-تصوم-شهرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_756/nour_75614.mp3","categories":["الأيمان والنذور","قضايا المرأة"]},{"id":16517,"question":"إحدى المستمعات بعثت برسالة إلى البرنامج، وآثرت عدم ذكر اسمها، إنما لها قضية تقول فيها: انقطعت عن الدراسة مدة طويلة، وكنت مولعة جدًا بالدراسة فقلت: لو أكملت دراستي سوف أذبح خروفًا، وأوزعه كما توزع الأضحية، وكما أعرف بأن الأضحية تقسم إلى ثلاثة أقسام، ويوزع كل قسم في مكانه، وبعد عدة سنوات أتيحت لي الفرصة، وأكملت -والحمد لله- دراستي، وذبحت جديًا، ذكر الماعز، ووزعته قسمًا للفقراء، وقسمًا للأقارب، وقسمًا لأهل البيت، وهم أمي، وإخوتي وأكلت منه، ولكن قيل لي: بأنه لا يجوز ما فعلت، فالنذر أولًا: يوزع كاملًا، ثانيًا: ذبحت جديًا، ونذرت أنت خروفًا، وهذا أيضًا لا يجوز، مع العلم أنني لم أقتنع، فوجهوني جزاكم الله خيرًا.","title":"حكم من وعدت أن تذبح خروفًا فذبحت جديًا","answer":"الجواب: هذا الذي قلتيه ليس بنذر، لو تمت الدراسة، أو نجحت؛ ذبحت، هذا ليس... هذا وعد، وليس بنذر، والأفضل الوفاء به، لكن لا يسمى نذرًا إلا إذا قلت: نذر لله، أو صدقة لله، أو عليّ لله، وما أشبه هذا، هذا النذر، أما لو أكملتِ فعلتِ هذا ليس بنذر. والأمر الثاني: أن الجدي لا يكفي؛ لأنك قلت: خروفًا، لابد تذبحين شيئًا يجزئ في الأضحية، يعني: جذعًا من الضأن، أو ثنيًا من المعز، يعني شيئًا تامًا يجزئ في الأضحية، وإذا كنت أردت بهذا الكلام أنك توزعينه كالأضحية، فأنت على نيتك، ولا بأس، والذي فعلت كاف، لكن يبدل الجدي ما دام الجدي صغيرًا، ما دام دون الثني؛ فلا يكفي، يعني من المعز دون الثني ما يكفي، لابد من ثني من المعز، أو جذع من الضأن، فأكبر، فهذا هو الذي يقوم مقام هذا الوعد، فأنت -إن شاء الله- توفين بالوعد، وليس بواجب، لكن هذا هو الأفضل لك؛ لأن هذا وعد نوع من النية، والشكر لله -جل وعلا- فالوفاء به مطلوب، من صفات المؤمن: إذا وعد؛ وفى، ومن صفات المنافق: إذا وعد أخلف، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15231/حكم-من-وعدت-ان-تذبح-خروفا-فذبحت-جديا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_756/nour_75613.mp3","categories":["الأيمان والنذور"]},{"id":16540,"question":"رسالة من ثلاث صفحات بعثها مستمع يقول: محمد راضي محمد محمد ، ملخص ما في هذه الصفحات الثلاث يقول: إنني اتفقت مع زوجتي إذا عملت أن تدفع لي ثلث الراتب، فلم تف بالاتفاق، فحلفت بالطلاق حتى تفي بالاتفاق، فلم تفعل، ومرة حلفت بالطلاق أن لا تخرج إلا متحجبة، فلم تفعل، وتكرر هذا اليمين بالطلاق في مناسبات أخرى، ويسأل عن الحكم، ويعقب مرة أخرى، فيقول: علمًا بأنها في اليوم الثاني، وقبل ذهابها للعمل أحضرت لي الفلوس لآخذ منها ما أريد، فرفضت بحجة أنني قد حلفت بالطلاق، وفي انتظار توجيهكم؟ جزاكم الله خيرًا.","title":"حكم من حلف بالطلاق وتكرر منه ذلك","answer":"الجواب: عليك أن تراجع المحكمة، لديكم المحكمة الشرعية أنت والمرأة ووليها حتى تسألكم جميعًا المحكمة عن الواقع بالتفصيل، ثم تفتيكم في ذلك، أو تحضر أنت والمرأة ووليها عند مدير مكتب الدعوة إذا كنت بالمملكة، مكتب الدعوة التابع لنا في بلدك في تبوك، أو في الدمام، أو في الأحساء، أو في حائل، في أي بلد فيها مكتب للدعوة، تحضر أنت والمرأة ووليها، حتى يسألكم مدير المكتب عن صفة الواقع بالتفصيل، ثم يبعث لنا بذلك، وننظر في الأمر، إن شاء الله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15275/حكم-من-حلف-بالطلاق-وتكرر-منه-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_815/nour_81507.mp3","categories":["الأيمان والنذور"]},{"id":16547,"question":"من عفيف الأخت: (ع. ص) بعثت برسالة تقول: حلفت يمينًا على أحد أولادي باجتناب عمل ما، فقطع هذا الحلف، مع العلم أنني كررت اليمين أكثر من مرة، هل علي كفارة عن كل يمين؟ أم تجزئ كفارة واحدة؟","title":"ما يجب على من كرر اليمين على شيء واحد؟","answer":"الجواب: عليك كفارة واحدة، إذا كان العمل واحدًا، إن كان قلت: والله ما تكلم فلانًا، والله ما تكلم فلانًا، والله ما تكلم فلانًا مرات؛ ليس فيها إلا كفارة واحدة، إذا لم ينفذ يمينك، بل كلم، وخالف، أو قلت مثلًا: والله ما تزور آل فلان، والله ما تزورهم، والله ما تزورهم، ثم زارهم؛ كفارة واحدة .. وهكذا ما أشبهه. أما إذا كونها أفعال، إذا كانت اليمين على أفعال، كأن قلت: والله ما تزور فلانًا، والله ما تكلمه، ثم زاره، وكلمه؛ عليك كفارتان؛ لأن الفعل مختلف، الزيارة غير الكلام، وهكذا ما أشبه ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15278/ما-يجب-على-من-كرر-اليمين-على-شيء-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_815/nour_81509.mp3","categories":["الأيمان والنذور"]},{"id":16729,"question":"رسالة وصلت إلى البرنامج من الطائف، وباعثها المستمع محمد أحمد إبراهيم، رسالته بدأها بمقدمة يقول: بسم الله الرحمن الرحيم، بعد تحيتكم بتحية الإسلام، فسلام الله عليكم ورحمته وبركاته، وكل عام وأنتم بخير، وبعد يطيب لي أن أكتب هذه الرسالة البسيطة معبرًا عن كل مشاعر الحب والتقدير لهذا البرنامج العظيم؛ لمقدار ما يقدمه من إيضاح وتوضيح لكثير من الأسئلة والمواضيع الغامضة، أو الغير مدركة لكثير من الإخوة المسلمين المؤمنين، وديننا يحث على العلم والمعرفة، ولا حرج في الدين، والعلم طالما هناك منفعة الجميع، ومزيدًا من تقديري، ومشاعري للإخوة الذين يساهمون في إنتاج هذا البرنامج، جزى الله الجميع خير الجزاء، ولا أطيل عليكم فأبدأ أسئلتي، بدأ أسئلته بالسؤال التالي سماحة الشيخ فيقول: عندنا كثير من الناس حينما يحلف يقول: والنبي، هل الحلفان بالنبي ﷺ يعتبر شركًا بالله؟ وهل إذا لم يكن شركًا عليه إثم؟ أم هو خير؟ أرجو التوضيح، أو الحلفان بغير ذلك، كمن يقول: وحياتي، بشرفي، وغير ذلك، ومن الناس من يقول لمن يريد أن يأخذ منه شيئًا بفضل الله، ثم بفضل كذا وكذا ستنقضي حاجتي، وجهوني إلى هذه الأمور، جزاكم الله خيرًا.","title":"هل الحلف بالنبي شرك بالله؟","answer":"الجواب: أولًا: جزاك الله خيرًا عن دعواتك، وعما ذكرت من السرور بهذا البرنامج، لا شك أنه برنامج مفيد، وعظيم النفع، فنسأل الله أن ينفع به المسلمين، وأن يضاعف المثوبة لمن يقوم عليه، وأن يمنحهم التوفيق للعلم النافع، والعمل الصالح. أما سؤالك فلا ريب أنه من الشرك، الحلف بالنبي ﷺ أو بالأولياء، أو بالملائكة، أو بالجن، أو بالنجوم، أو بشرف فلان، أو بحياته، كله لا يجوز؛ لقول النبي ﷺ: من كان حالفًا؛ فليحلف بالله، أو ليصمت، ويقول أيضًا -عليه الصلاة والسلام-: من كان حالفًا؛ فلا يحلف إلا بالله، أو ليصمت ويقول -عليه الصلاة والسلام-: من حلف بشيء دون الله؛ فقد أشرك ويقول أيضًا -عليه الصلاة والسلام-: من حلف بغير الله؛ فقد كفر، أو أشرك ويقول أيضًا -عليه الصلاة والسلام-: من حلف بالأمانة فليس منا، ويقول: من حلف باللات والعزى فليقل: لا إله إلا الله. والمقصود: أن الحلف بغير الله أمر لا يجوز، وهو من المحرمات الشركية، لكنه شرك أصغر، ليس بشرك أكبر. فالواجب على المسلمين الحذر من ذلك، وأن يكون الحلف بالله وحده، أو بصفة من صفاته، ولا يجوز الحلف بغير الله كائنًا من كان، لا بالأنبياء، ولا غيرهم، ومن فعل هذا؛ فعليه التوبة إلى الله، والإنابة إليه، والندم على ما مضى، والعزم الصادق ألا يعود في ذلك. والله -سبحانه- بعث الرسل -عليهم الصلاة والسلام- لبيان الحق، وإيضاح الحق، وختمهم بمحمد -عليه الصلاة والسلام-وقد أوضح في ذلك، قد أوضح ما يجب في ذلك، وكان الناس في أول الإسلام، وفي أول الهجرة يحلفون بآبائهم، ثم نهاهم النبي ﷺ وقال: لا تحلفوا بآبائكم، ولا بأمهاتكم، ولا بالأنداد، ولا تحلفوا بالله إلا وأنتم صادقون. فإن قصد بالحلف بغير الله أن هذا المحلوف به يتصرف في الكون، أو أنه يصلح أن يعبد من دون الله؛ صار شركًا أكبر، نسأل الله العافية. أما إذا جرى على لسانه من غير قصد، بل لمحبته لمحبوبه، أو لتعظيمه له فقط من دون أن يعتقد فيه أنه يصلح يعبد من دون الله، أو أنه يتصرف في الكون؛ هذا شرك أصغر يجب تركه، والتوبة إلى الله منه، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم، آخر فقرة في سؤاله يقول: من قال: سأفعل كذا، أو فعل كذا بفضل الله، ثم بفضل فلان؟ الشيخ: هذا لا حرج فيه، قال: بفضل الله، ثم بفضل فلان، أو قال: بالله، ثم فلان، أو قال: هذا من الله، ثم من فلان، أو أنا أستعيذ بالله، ثم بك؛ فلا حرج فيه، ليس من الشرك؛ لأنه قال: ثم بك، نعم. المقدم: جزاكم الله خيرًا، أيضًا الحلف بالشرف كما يذكر، أو بحياة الإنسان؟ الشيخ: كله منكر، كله لا يجوز، بشرف فلان، أو بحياة فلان، أو بحياة النبي، أو شرف النبي؛ ما يجوز. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15483/هل-الحلف-بالنبي-شرك-بالله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_761/nour_76111.mp3","categories":["الطلاق","الأيمان والنذور","الحلف بغير الله"]},{"id":16770,"question":"أولى رسائل هذه الحلقة رسالة وصلت بتوقيع إحدى الأخوات المستمعات تقول: مستمعة من الرياض، تقول في رسالتها: امرأة سافر زوجها، فنذرت أن تصوم ثلاثة أشهر متتابعة عند عودته، وأن تذبح ثلاث ذبائح، وبعد عودته من السفر لم تف بالنذر، ومضى الآن ما يقارب السنة، ونظرًا لظروفها ورعاية أطفالها؛ لم تستطع الصوم ثلاثة أشهر متتابعة، ولا أن تذبح الذبائح، وسؤالها: ماذا عليها أن تفعل؟ جزاكم الله خيرًا.","title":"حكم من لم تستطع الوفاء بالنذر","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فالواجب على هذه الناذرة الوفاء بنذرها من الصوم، والذبائح، لقول النبي ﷺ في الحديث الصحيح: من نذر أن يطيع الله؛ فليطعه، ومن نذر أن يعصي الله؛ فلا يعصه وقد مدح الله الموفين بالنذر، فقال سبحانه: يُوفُونَ بِالنَّذْرِ وَيَخَافُونَ يَوْمًا كَانَ شَرُّهُ مُسْتَطِيرًا [الإنسان:7] وذلك من صفات أهل الإيمان والتقوى الوفاء بنذر الطاعة، فعليها أن تصوم ثلاثة أشهر متتابعة، وعليها أن تذبح ثلاث ذبائح عند القدرة، والشيء في ذمتها، يبقى في ذمتها حتى تقدر. فإذا قدرت على الذبائح؛ ذبحتها ولو متفرقة، كل وقت واحدة توزع على الفقراء والمحاويج، ومتى استطاعت الصوم تصوم في الوقت الذي تستطيع، والله لا يكلف نفساً إلا وسعها، يقول سبحانه: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]. فإذا استطاعت الصيام؛ صامت، وإلا فيبقى في ذمتها معلقًا إلى أن تقدر، وهكذا الذبائح، ونوصي الناذرة، وغيرها بعدم العود إلى النذر ... النذر لا ينبغي، يقول النبي ﷺ: لا تنذروا؛ فإن النذر لا يرد من قدر الله شيئًا، وإنما يستخرج به من البخيل. فالوصية لجميع من يستمع لهذا البرنامج، الوصية للجميع عدم النذر، بجميع أشكاله، النذر لا يرد قدرًا، ولا يأتي بخير، ولكن يستخرج به من البخيل، لكن من نذر طاعة لله؛ فليوف بنذره من نذر أن يطيع الله؛ فليطعه وفق الله الجميع، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15512/حكم-من-لم-تستطع-الوفاء-بالنذر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_822/nour_82201.mp3","categories":["الأيمان والنذور"]},{"id":16824,"question":"ننتقل بعد هذا إلى المملكة الأردنية الهاشمية عمان، عبر رسالة وصلت إلى البرنامج من المستمع همام العبادي فيما يبدو، الأخ همام له سؤال يقول: أهدى قريب زوجتي لنا هدية، فلما رأيتها قلت: علي الحرام لا تدخل بيتي، فأبقوها عند الجيران، وفي اليوم الثاني أدخلت إلى بيتي، واستعملناها، واستفدنا منها، ما هو كفارة ذلك القول؟ جزاكم الله خيرًا.","title":"حكم من حلف ألا تدخل بيته هدية معينة ثم دخلت","answer":"الجواب: أولًا: هذا لغو لا يجوز، تحريم الحلال لا يجوز، عليك التوبة إلى الله من ذلك. الأمر الثاني: على حسب نيتك، إن كنت قصدت الامتناع منها، ولم تقصد تحريم زوجتك، ولا طلاقها؛ فعليك كفارة يمين، والحمد لله، إطعام عشرة مساكين، أو كسوتهم.. عشرة، كل واحد له نصف الصاع من التمر، أو الرز، أو الحنطة، كيلو ونصف كل واحد. أما إن كنت أردت تحريم الزوجة؛ فعليك كفارة الظهار، وهي عتق رقبة مؤمنة، فإن عجزت؛ تصم شهرين متتابعين، ستين يومًا، فإن عجزت؛ تطعم ستين مسكينًا، ثلاثين صاعًا قبل أن تقرب زوجتك، كل صاع بين اثنين، يعني: كل صاع ثلاثة كيلو ... كيلو ونصف من قوت البلد، من تمر، أو غيره، أو حنطة، أو أرز. أما إن كنت أردت الطلاق، أردت أنها إذا دخلت بيتك تكن امرأتك طالقًا؛ فإنه يقع بها طلقة واحدة إذا كنت أردت الطلاق، وتراجعها في الحال، تشهد اثنين من إخوانك الطيبين، تشهدهم أنك راجعت زوجتك. الخلاصة: أن لك في هذا ثلاثة أمور: الأمر الأول: أن تكون أردت الامتناع فقط، فهذا فيه كفارة يمين لما استعملتموها، ودخلت البيت، وهي إطعام عشرة مساكين، أو كسوتهم، عشرة، كل واحد له نصف الصاع، كيلو ونصف، أو كسوة ........ تجزئه في الصلاة. الحال الثاني: أن تكون أردت التحريم، تحريمها عليك، تحريم الزوجة بذلك إن دخلت البيت، فهذا فيه كفارة الظهار، كما بينها الله في سورة المجادلة، وهي: عتق رقبة مؤمنة قبل أن تمس زوجتك، فإن عجزت؛ تصم شهرين متتابعين، ستين يومًا قبل أن تمس زوجتك، فإن لم تقدر -لا هذا ولا هذا- فعليك إطعام ستين مسكينًا، ثلاثين صاعًا كل صاع بين اثنين، ومقدار ذلك تسعين كيلو، كل واحد له كيلو ونصف من قوت البلد، من تمر، أو أرز، أو حنطة، أو ذرة، ونحو ذلك، مع التوبة والاستغفار. الحال الثالث: أن تكون أردت الطلاق، أردت أنها إن دخلت بيتك فهي مطلقة زوجتك، فهذا الكلام يقع به طلقة، ولك مراجعتها في العدة، بشهادة اثنين، تشهد اثنين من أهل السنة، تشهد اثنين أنك راجعتها، إذا كنت ما طلقتها قبل هذا طلقتين، نسأل الله للجميع الهداية، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا، إذا أذنتم لي سماحة الشيخ بعرض ما أعرفة عن أحوال الناس في مثل هذا الباب. الشيخ: نعم. المقدم: مثل هذا الباب يغلب عليه أنهم يريدون توفير الهدية للمهدي، بحيث لا يكلف نفسه، فحينئذٍ لا بد لسماحتكم من تعليق وحكم آخر؟ الشيخ: على كل حال هو هذا التفصيل إذا كان أراد الامتناع من قبولها توفيرًا له، ورحمة له، وعدم تكليف له؛ فهو إذا قبلها فيها كفارة اليمين، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15579/حكم-من-حلف-الا-تدخل-بيته-هدية-معينة-ثم-دخلت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_763/nour_76314.mp3","categories":["الظهار","الطلاق","الأيمان والنذور"]},{"id":16891,"question":"إني قد نذرت على نفسي أن أصوم عشرة أيام في شعبان، وعشرة أيام في رجب، وقد صمت العام الماضي، وقال لي أحد الأقارب: إنه لا أجر في هذا الصيام، فهل هذا القول صحيح؟ علمًا بأني أصوم العاشوراء، وأصوم يوم الوقوف بعرفة، وأحب الصيام، أفيدوني أفادكم الله؟","title":"الوفاء بالنذر من الطاعات","answer":"الجواب: يقول النبي ﷺ من نذر أن يطيع الله؛ فليطعه، ومن نذر أن يعصي الله؛ فلا يعصه والصوم من طاعة الله -جل وعلا- فإذا نذرت عشرة أيام من رجب، أو غير رجب، وعشرة من شعبان؛ فلا بأس، عليك أن توفي بنذرك، إلا إذا كانت العشرة نذرتها بعد النصف من شعبان، فلا يجوز؛ لأن الرسول ﷺ نهى عن الصيام بعد النصف للذي ما صام قبل، قال: إذا انتصف شعبان؛ فلا تصوموا فعليك كفارة يمين عند العجز. أما إذا كنت نذرتها لعشرة من شعبان مطلقة، أو من النصف الأول؛ تصومها من النصف الأول، والحمد لله، ولا حرج في ذلك، بل هذا من نذور الطاعات. وهكذا صيام يوم عرفة سنة، يوم التاسع من ذي الحجة لغير الحجاج سنة، وهكذا صوم عاشوراء -وهو اليوم العاشر من المحرم- سنة، ويستحب أن يصوم قبله يومًا، أو بعده يومًا، أو يصوم الثلاثة جميعًا: التاسع، والعاشر، والحادي عشر؛ لقول النبي ﷺ: خالفوا اليهود، صوموا يومًا قبله، أو يومًا بعده وفي رواية أخرى: صوموا يومًا قبله، ويومًا بعده هذا مشروع، ومستحب، نعم. المقدم: جزاكم الله خيرًا. سماحة الشيخ: هذا الرجل الذي تصدى لفتيا أخينا، وقال: إن هذا الصيام لا أجر فيه، ما هو توجيهكم له، ولأمثاله ممن يفتي بغير علم؟ جزاكم الله خيرًا. الشيخ: الواجب على كل مسلم، وعلى كل طالب علم بالأخص أن يتقي الله، وأن لا يفتي إلا بعلم؛ لأن الفتوى بغير علم شرها عظيم، وعواقبها وخيمة. وذلك مخالف للنص القرآني في قوله -جل وعلا-: قُلْ إِنَّمَا حَرَّمَ رَبِّيَ الْفَوَاحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ وَالإِثْمَ وَالْبَغْيَ بِغَيْرِ الْحَقِّ وَأَنْ تُشْرِكُوا بِاللَّهِ مَا لَمْ يُنَزِّلْ بِهِ سُلْطَانًا وَأَنْ تَقُولُوا عَلَى اللَّهِ مَا لا تَعْلَمُونَ [الأعراف:33] فجعل القول عليه بغير علم فوق مرتبة الشرك؛ لما يترتب على القول على الله بغير علم من الشر العظيم، والعواقب الوخيمة، وتحليل الحرام، وتحريم الحلال، فيجب الحذر. وقال  في سورة البقرة: يَا أَيُّهَا النَّاسُ كُلُوا مِمَّا فِي الأَرْضِ حَلالًا طَيِّبًا وَلا تَتَّبِعُوا خُطُوَاتِ الشَّيْطَانِ إِنَّهُ لَكُمْ عَدُوٌّ مُبِينٌ  ۝ إِنَّمَا يَأْمُرُكُمْ بِالسُّوءِ وَالْفَحْشَاءِ وَأَنْ تَقُولُوا عَلَى اللَّهِ مَا لا تَعْلَمُونَ [البقرة:168-169]، فجعل القول على الله بغير علم مما يأمر به الشيطان، الشيطان لا يأمر إلا بالشر، والفساد، فيجب الحذر، ولا يخفى على كل ذي لب ما يترتب على الفتوى بغير علم من المفاسد الكثيرة، ومن تحليل الحرام، وتحريم الحلال، وإيقاع الناس في مشاكل كثيرة، ولا حول ولا قوة إلا بالله، نعم. المقدم: جزاكم الله خيرًا، ونفع بعلمكم، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15650/الوفاء-بالنذر-من-الطاعات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_765/nour_76508.mp3","categories":["الأيمان والنذور"]},{"id":16894,"question":"إني قد نذرت على نفسي أن أصوم عشرة أيام في شعبان، وعشرة أيام في رجب، وقد صمت العام الماضي، وقال لي أحد الأقارب: إنه لا أجر في هذا الصيام، فهل هذا القول صحيح؟ علمًا بأني أصوم العاشوراء، وأصوم يوم الوقوف بعرفة، وأحب الصيام، أفيدوني أفادكم الله؟","title":"الوفاء بالنذر من الطاعات","answer":"الجواب: يقول النبي ﷺ من نذر أن يطيع الله؛ فليطعه، ومن نذر أن يعصي الله؛ فلا يعصه والصوم من طاعة الله -جل وعلا- فإذا نذرت عشرة أيام من رجب، أو غير رجب، وعشرة من شعبان؛ فلا بأس، عليك أن توفي بنذرك، إلا إذا كانت العشرة نذرتها بعد النصف من شعبان، فلا يجوز؛ لأن الرسول ﷺ نهى عن الصيام بعد النصف للذي ما صام قبل، قال: إذا انتصف شعبان؛ فلا تصوموا فعليك كفارة يمين عند العجز. أما إذا كنت نذرتها لعشرة من شعبان مطلقة، أو من النصف الأول؛ تصومها من النصف الأول، والحمد لله، ولا حرج في ذلك، بل هذا من نذور الطاعات. وهكذا صيام يوم عرفة سنة، يوم التاسع من ذي الحجة لغير الحجاج سنة، وهكذا صوم عاشوراء -وهو اليوم العاشر من المحرم- سنة، ويستحب أن يصوم قبله يومًا، أو بعده يومًا، أو يصوم الثلاثة جميعًا: التاسع، والعاشر، والحادي عشر؛ لقول النبي ﷺ: خالفوا اليهود، صوموا يومًا قبله، أو يومًا بعده وفي رواية أخرى: صوموا يومًا قبله، ويومًا بعده هذا مشروع، ومستحب، نعم. المقدم: جزاكم الله خيرًا. سماحة الشيخ: هذا الرجل الذي تصدى لفتيا أخينا، وقال: إن هذا الصيام لا أجر فيه، ما هو توجيهكم له، ولأمثاله ممن يفتي بغير علم؟ جزاكم الله خيرًا. الشيخ: الواجب على كل مسلم، وعلى كل طالب علم بالأخص أن يتقي الله، وأن لا يفتي إلا بعلم؛ لأن الفتوى بغير علم شرها عظيم، وعواقبها وخيمة. وذلك مخالف للنص القرآني في قوله -جل وعلا-: قُلْ إِنَّمَا حَرَّمَ رَبِّيَ الْفَوَاحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ وَالإِثْمَ وَالْبَغْيَ بِغَيْرِ الْحَقِّ وَأَنْ تُشْرِكُوا بِاللَّهِ مَا لَمْ يُنَزِّلْ بِهِ سُلْطَانًا وَأَنْ تَقُولُوا عَلَى اللَّهِ مَا لا تَعْلَمُونَ [الأعراف:33] فجعل القول عليه بغير علم فوق مرتبة الشرك؛ لما يترتب على القول على الله بغير علم من الشر العظيم، والعواقب الوخيمة، وتحليل الحرام، وتحريم الحلال، فيجب الحذر. وقال  في سورة البقرة: يَا أَيُّهَا النَّاسُ كُلُوا مِمَّا فِي الأَرْضِ حَلالًا طَيِّبًا وَلا تَتَّبِعُوا خُطُوَاتِ الشَّيْطَانِ إِنَّهُ لَكُمْ عَدُوٌّ مُبِينٌ  ۝ إِنَّمَا يَأْمُرُكُمْ بِالسُّوءِ وَالْفَحْشَاءِ وَأَنْ تَقُولُوا عَلَى اللَّهِ مَا لا تَعْلَمُونَ [البقرة:168-169]، فجعل القول على الله بغير علم مما يأمر به الشيطان، الشيطان لا يأمر إلا بالشر، والفساد، فيجب الحذر، ولا يخفى على كل ذي لب ما يترتب على الفتوى بغير علم من المفاسد الكثيرة، ومن تحليل الحرام، وتحريم الحلال، وإيقاع الناس في مشاكل كثيرة، ولا حول ولا قوة إلا بالله، نعم. المقدم: جزاكم الله خيرًا، ونفع بعلمكم، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15650/الوفاء-بالنذر-من-الطاعات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_765/nour_76508.mp3","categories":["الأيمان والنذور"]},{"id":16904,"question":"بعد هذا رسالة وصلت إلى البرنامج من مجموعة من الأخوات المستمعات، إحداهن تقول: أم محمد من...... تسأل وتقول: يا سماحة الشيخ عندي ولد يبلغ من العمر خمسًا وعشرين سنة، وكان يصلي، ولكن صلاته في البيت لا في المسجد، وقد كان مكروهًا من قبل أعمامه، وينفونه، ويقولون لأبيه: اطرده من المنزل؛ لأنه يحلق لحيته، ولا يصلي في المسجد، ولكن والده لا يسمع لكلامهم، وأنا والدته من شدة ما أعاني قلت: لله علي إذا اهتدى ابني فإنني سوف أقوم بصيام شهر كامل، وقلت: إنني سوف أذبح شاتين، ولا أدري أقلت قبل الصيام، أم بعده، فهل لي أن أذبحها بعد نهاية الصيام؟ وهل هذا يعتبر من النذر، وآثم إذا لم أفعله؟ وجهوني جزاكم الله خيرًا، مع العلم بأن ابني قد اهتدى، وترك حلق اللحية، ويصلي الآن في المسجد، ولله الحمد.","title":"حكم من نذرت أن تذبح وتصوم إن هدى الله ولدها","answer":"الجواب: الحمد لله الذي هداه، نسأل الله لنا وله الثبات على الحق، والاستمرار في الخير، وعليك أن توفي بنذرك من الصيام والذبح، عليك أن تفعلي ذلك، سواء ذبحت قبل الصيام، أو بعد الصيام، الأمر واسع، ولا تعودي للنذر في المستقبل، لا تنذري في المستقبل، الرسول ﷺ نهى عن النذر، قال: إنه لا يأت بخير، وإنما يستخرج به من البخيل لكنه قال ﷺ: من نذر أن يطيع الله؛ فليطعه، ومن نذر أن يعصي الله؛ فلا يعصه فأنت عليك الوفاء بالنذر، والحذر في المستقبل من النذر، أما هذا فعليك أن توفي بالصيام، والذبيحة، نعم. والذبيحة تكون للفقراء، إلا إذا كان لك نية أنها تذبحينها في البيت، وتدعين لها الجيران، أو الأقارب، أو أناسًا معينين فافعلي، أما إذا كان ما لك نية؛ فاذبحيها، وتصدقي بها على الفقراء.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15662/حكم-من-نذرت-ان-تذبح-وتصوم-ان-هدى-الله-ولدها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_719/nour_71911.mp3","categories":["الأيمان والنذور"]},{"id":16920,"question":"إذا قال الشخص: بالحرام، بالطلاق -ولعدة مرات- فلان لن يتزوج فلانة، فإذا حصل الزواج؛ هل يقع عليه الطلاق؟","title":"حلف بالطلاق والحرام على عدم حصول شيء وحصل، فهل يقع؟","answer":"الجواب: هذا يختلف، حسب نيته، إذا قال: علي الطلاق ........... يتزوج فلان، هذا أولًا لا يجوز الحلف بالطلاق، ولا يجوز الحلف بالحرام، لا يجوز، الحلف يكون بالله وحده، لا يجوز لأحد يحلف بالطلاق، ولا بالحرام، ولا بالأمانة، ولا بالنبي، ولا برأس فلان، ولا شرف فلان، ولا حياة فلان؛ كل هذا لا يجوز، يقول النبي ﷺ: من كان حالفًا؛ فليحلف بالله، أو ليصمت ويقول ﷺ: من حلف بشيءٍ دون الله؛ فقد أشرك. لكن إذا كان قصده، يعني: أنه عليه الطلاق، عليه الحرام أن فلانًا ما يتزوج فلانة، وقصده منعه، فهذا إذا فعل؛ عليه كفارة يمين، حكمه حكم اليمين، إذا ما طاعوه، زوجوه... بالطلاق بالحرام ما يتزوج فلانة؛ يكون عليه كفارة يمين، ولا يقع الطلاق في أصح أقوال أهل العلم، إذا كان قصده المنع. أما إذا كان قصده أن يقع الطلاق، والتحريم، إذا كان قصده بالطلاق إذا تزوج فلانة، قصده إن زوجه طالق، أو قصده إنه حرام عليه... هذا، ويريد أنها تحرم عليه، أو تطلق؛ فله نيته، فهو على ما نوى، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15693/حلف-بالطلاق-والحرام-على-عدم-حصول-شيء-وحصل-فهل-يقع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_826/nour_82610.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":17006,"question":"السائلة (ع. س) تقول: ما كيفية إطعام، أو كسوة عشرة مساكين؟ وهل يشترط أن يكونوا من بيوت متفرقة، أو من بيت واحد؟ وهل من الممكن أن تقوم النقود مكان الإطعام، أو الكسوة؟","title":"كيفية كفارة اليمين وحكم إخراجها نقودًا","answer":"الجواب: الله -جل وعلا- جعل كفارة اليمين إطعام عشرة مساكين، أو كسوتهم، أو تحرير رقبة، قال -جل وعلا- في سورة المائدة: لا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِنْ يُؤَاخِذُكُمْ بِمَا عَقَّدْتُمُ الأَيْمَانَ فَكَفَّارَتُهُ إِطْعَامُ عَشَرَةِ مَسَاكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍ فَمَنْ لَمْ يَجِدْ فَصِيَامُ ثَلاثَةِ أَيَّامٍ ذَلِكَ كَفَّارَةُ أَيْمَانِكُمْ إِذَا حَلَفْتُمْ وَاحْفَظُوا أَيْمَانَكُمْ [المائدة:89] الآية. فإذا حلف الإنسان يمينًا أنه ما يفعل كذا، أو أنه يفعل كذا، أو أنه لا يكلم فلانًا، ثم حنث؛ يطعم هذه الكفارة، فإذا قال: والله ما أزور فلانًا، ثم زاره، أو والله ما أسافر، ثم سافر، أو ما أشبه ذلك؛ عليه هذه الكفارة: إطعام عشرة مساكين، أو كسوتهم، أو تحرير رقبة، مخير بين الثلاث، والإطعام يكون نصف صاع، لكل واحد كيلو ونصف من قوت البلد، من تمر، أو رز، أو حنطة، أو شعير من قوت البلد نصف صاع كيلو ونصف لكل واحد، سواءٌ في بيت واحد، أو في أبيات. لو كان بيت واحد فيه عشرة فقراء، امرأة وأولادها فقراء، أو رجل وأولاده فقراء عشرة كفى، أو بيتين كل بيت فيه خمسة، وأعطاهم كفى، أو كساهم كسوة كل واحد يعطى إزار ورداء، أو قميص كفى، وهكذا عتق رقبة إذا تيسر، عتق رقبة كفى، فإن لم يستطع هذا ولا هذا ولا هذا؛ صام ثلاثة أيام، والأفضل أن تكون متتابعة هذه الأيام، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15777/كيفية-كفارة-اليمين-وحكم-اخراجها-نقودا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_587/58704.mp3","categories":["الأيمان والنذور"]},{"id":17119,"question":"هذه السائلة الأخت من الطائف (ش. ع) تقول: سماحة الشيخ! كنت فيما سبق نذرت لله  بالصلاة ركعتين شكرًا لله تعالى قبل كل صلاة إذا قضى الله لي أمرًا معينًا، فلما قضي هذا الأمر بفضلٍ من الله  بدأت في الوفاء بنذري، وبعد فترة أفتى لي البعض من الإخوة، وهم ليسوا من أهل العلم بأنه لا يوجد ما يسمى بصلاة الشكر، ولكن يوجد فقط سجدة شكر، فبدأت في أدائها، فهل تكفي للوفاء بنذري؟ وما حكم الفترة التي كنت أسجد فيها سجدة الشكر فقط؟ مأجورين.","title":"وجوب الوفاء بنذر الطاعة","answer":"الجواب: الواجب أن توفي بنذرك، أن تصلي ركعتين، لقول النبي ﷺ: من نذر أن يطيع الله فليطعه وصلاة الركعتين طاعة لله، سجود الشكر غير الصلاة المنذورة، الصلاة المنذورة يجب الوفاء بها، وسجود الشكر شيء آخر، فعليك أن توفي بنذرك بالصلاة، أن تصلي ركعتين قبل كل صلاة من أجل نذرك، وتعرفي الأيام التي تركتيها تقضينها، الأيام التي تركتيها تقضينها. نعم.","link":"https://binbaz.org.sa/fatwas/15930/وجوب-الوفاء-بنذر-الطاعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_589/58916.mp3","categories":["الأيمان والنذور"]},{"id":17145,"question":"من المستمع محمد عبدالرحمن الماحي يقول: حصل بيني وبين عمي نقاش، وقد كان يصلي بنا، وأنا حلفت بالله: لا أصلي خلفه، وفي أيام رمضان أنا تقدمت إمامًا، وحينما بدأت أكبر قال لي: ارجع في الصف، وأنا رجعت، وصليت وحدي قرب الصف؛ لأنني حلفت بالله، هل يجوز ما فعلت؟ جزاكم الله خيرًا، وما الحكم إذا ما أردت الصلاة خلفه؟","title":"ماذا يفعل من حلف ألا يصلي خلف إمام ما؟","answer":"الجواب: الواجب عليك أن تصلي في الجماعة، ولا تصلي وحدك، وعليك كفارة اليمين..عليك أن تكفر عن يمينك بإطعام عشرة مساكين، أو كسوتهم، أو عتق رقبة، أما أن تصلي وحدك هذا لا يجوز، الجماعة واجبة، عليك وعلى غيرك من المسلمين في مساجد الله، مع إخوانك، يقول النبي ﷺ: من سمع النداء فلم يأت؛ فلا صلاة له إلا من عذر. وجاءه رجل أعمى، فقال: يا رسول الله! ليس لي قائد يقودني إلى المسجد، فهل لي من رخصة أن أصلي في بيتي؟ فقال له المصطفى -عليه الصلاة والسلام-: هل تسمع النداء بالصلاة؟ قال: نعم، قال: فأجب. فإذا كان رجل أعمى يجب عليه أن يجيب كيف بغيره! وهو ليس عنده قائد أيضًا، بل يحتاج إلى طلب الناس ليقودوه، فاتق الله واحذر، وتب إلى الله مما فعلت، وكفر عن يمينك، وصل مع الناس، واقتد بالإمام، واستغفر ربك مما فعلت سابقًا، وتب إليه، وعليك كفارة اليمين، وهي إطعام عشرة مساكين، أو كسوتهم، كل واحد له نصف الصاع، تمرًا، أو رزًا من قوت بلدك، نصف صاع: كيلو ونصف من قوت بلدك، أو كسوة تجزئه للصلاة كإزار ورداء، أو قميص. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16017/ماذا-يفعل-من-حلف-الا-يصلي-خلف-امام-ما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_832/nour_83206.mp3","categories":["الأيمان والنذور"]},{"id":17237,"question":"السائل يقول: من الجزائر، يقول: لقد علمت أن كفارة اليمين هي: إما إطعام، أو كسوة، أو بعد ذلك الصيام، فما مقدار الطعام والكسوة الحالية، سماحة الشيخ؟","title":"مقدار الطعام والكسوة في كفارة اليمين","answer":"الجواب: الله يقول : لا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِنْ يُؤَاخِذُكُمْ بِمَا عَقَّدْتُمُ الأَيْمَانَ فَكَفَّارَتُهُ إِطْعَامُ عَشَرَةِ مَسَاكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍ فَمَنْ لَمْ يَجِدْ فَصِيَامُ ثَلاثَةِ أَيَّامٍ ذَلِكَ كَفَّارَةُ أَيْمَانِكُمْ إِذَا حَلَفْتُمْ وَاحْفَظُوا أَيْمَانَكُمْ كَذَلِكَ يُبَيِّنُ اللَّهُ لَكُمْ آيَاتِهِ لَعَلَّكُمْ تَشْكُرُونَ [المائدة:89] هكذا قال سبحانه في سورة المائدة، والإطعام نصف صاع، كيلو ونصف من قوت البلد، من تمر، أو رز، أو حنطة، نصف صاع من قوت البلد، هذا هو الأرجح، وقال بعضهم: مد من البر، ونصف صاع من غيره، ولكن الأرجح نصف صاع من جميع القوت، نصف صاع من قوت البلد، من تمر، أو رز، أو بر، أو ذرة، أو غير ذلك. والكسوة: ما يجزئ في الصلاة؛ إما إزار ورداء، وإما قميص، أو عتق رقبة؛ عبد، أو أمة، فمن عجز عن هذا كله؛ يصوم ثلاثة أيام، والأفضل أن تكون متتابعة. نعم. المقدم: أحسن الله إليكم، وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16066/مقدار-الطعام-والكسوة-في-كفارة-اليمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_591/59114.mp3","categories":["الأيمان والنذور"]},{"id":17242,"question":"هذا السائل (م. ش. ع)، يقول: والدي كثير الحلف بالله، فمثلًا: يحلف على الشخص أن يتغذى عندنا، ويتعذر هذا الشخص؛ فيتركه، ومثلًا: يحلف على أحد الأبناء ألا يذهب إلى السوق، يريد هذا الابن أن يذهب إلى السوق، فلا يفي بهذا الحلف، فماذا تنصحون مثل هؤلاء، سماحة الشيخ؟","title":"نصيحة لمن يكثر الحلف بالله تعالى","answer":"الجواب: نصيحتي له ولأمثاله: أن يحفظ يمينه، وألا يكثر من الأيمان؛ لأنه إذا أكثر منها؛ لم يكفر عنها، وفي هذا نوع من التساهل بجنب الله، والله يقول: وَاحْفَظُوا أَيْمَانَكُمْ [المائدة:89]. فالمشروع للمؤمن أن يحفظ يمينه، وألا يحلف إلا عند الحاجة، وإذا حلف ولم تبر يمينه؛ كفر عنها، فإذا قال: والله ما تخرج، وخرج؛ عليه كفارة يمين، فإذا قال: والله أن تتغذى عندنا، ولا تغذى؛ عليه كفارة يمين، والله تتعشى عندنا، ولا تعشى؛ عليه كفارة يمين، المذكورة في قوله -جل وعلا-: وَلَكِنْ يُؤَاخِذُكُمْ بِمَا عَقَّدْتُمُ الأَيْمَانَ فَكَفَّارَتُهُ إِطْعَامُ عَشَرَةِ مَسَاكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍ فَمَنْ لَمْ يَجِدْ فَصِيَامُ ثَلاثَةِ أَيَّامٍ ذَلِكَ كَفَّارَةُ أَيْمَانِكُمْ إِذَا حَلَفْتُمْ [المائدة:89]. فلا يتساهل في اليمين، فلكن متى وقعت اليمين، ولم تبر؛ وجب عليه كفارة، يقوم بإطعام عشرة مساكين، كل مسكين له نص الصاع، كيلو ونص، من قوت البلد، أو كسوة تجزيه في الصلاة، أو عتق رقبة، فمن عجز؛ صام ثلاثة أيام، وإن تابعها فهو أفضل، ثلاثة أيام، والأفضل أن تكون متتابعة. نعم. المقدم: أحسن الله إليكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16073/نصيحة-لمن-يكثر-الحلف-بالله-تعالى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_591/59119.mp3","categories":["الأيمان والنذور"]},{"id":17271,"question":"تقول أختنا: إني قد نذرت على نفسي أن أصوم عشرة أيام في رجب، وعشرة أيام في شعبان، وقد صمت العام الماضي، فقال لي أحد الأقارب: إنه لا أجر في صيام هذه الأيام، فهل هذا القول صحيح؟ علمًا بأني أصوم عاشوراء، ويوم الوقوف بعرفة، وأحب الصيام كثيرًا. وجهوني جزاكم الله خيرًا.","title":"هل يُؤجر الشخص على الوفاء بالنذر؟","answer":"الجواب: يقول النبي ﷺ: من نذر أن يطيع الله فليطعه، ومن نذر أن يعصيه فلا يعصه ونذر الصوم طاعة، فعليك أن توفي بنذرك، وأن تصومي عشرة .. من رجب وعشرة من شعبان إذا كنت نذرت هذا دائمًا كل سنة، وعليك أن تتركي النذر، النذر لا ينبغي، يكره، فعليك مستقبلًا أن تدعي النذر لقوله ﷺ: لا تنذروا؛ فإن النذر لا يرد من قدر الله شيئًا، وإنما يستخرج به من البخيل. فأنت في المستقبل دعي النذر، لكن الذي وقع منك الآن وتم وقوعه فهذا عليك الوفاء لقوله ﷺ: من نذر أن يطيع الله فليطعه. وقد مدح الله الموفين بالنذر، قد امتدح سبحانه الموفوين بالنذر في كتابه العظيم حيث قال  في سورة الإنسان: يُوفُونَ بِالنَّذْرِ وَيَخَافُونَ يَوْمًا كَانَ شَرُّهُ مُسْتَطِيرًا [الإنسان:7] هذه من صفات الأبرار، ومن صفات المؤمنين يُوفُونَ بِالنَّذْرِ وَيَخَافُونَ يَوْمًا كَانَ شَرُّهُ مُسْتَطِيرًا [الإنسان:7] فعليك أن توفي بنذرك، وأن تدعي النذر مستقبلًا. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16114/هل-يوجر-الشخص-على-الوفاء-بالنذر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_768/nour_76807.mp3","categories":["الأيمان والنذور"]},{"id":17283,"question":"في آخر أسئلة السائل أحمد عبده من اليمن يقول: إذا نذر الإنسان أن يذبح ذبيحة لله؛ نظرًا لمرض أصابه، وذلك حتى يشفى منه، هل يجوز له الوفاء بهذا النذر في المرة الأولى فقط، أم يتمسك به في طول حياته، فيذبح في كل سنة ذبيحة؟","title":"وجوب الوفاء بالنذر حسب النية","answer":"الجواب: يلزمه أن يوفي بالنذر فقط، قول النبي ﷺ: من نذر أن يطيع الله فليطعه وإذا نذر أن يذبح في كل سنة ذبيحة لزمه ذلك، من نذر أن يطيع الله فليطعه، ومن نذر أن يعصي الله فلا يعصه. أما إذا نذر إن شفاه الله من المرض ذبح ذبيحة مرة واحدة تكفي، إذا شفاه الله يذبح الذبيحة، ولا يتعود النذر، النذر لا ينبغي، الرسول ﷺ نهى عن النذر وقال: إنه لا يأتي بخير، وإنما يستخرج به من البخيل فلا ينبغي للمؤمن أن ينذر، لكن متى نذر طاعة وفى بها، يقول ﷺ: من نذر أن يطيع الله فليطعه، ومن نذر أن يعصي الله فلا يعصه فإذا قال: لله علي إن شفاني الله أن أصوم كذا، أو أن أذبح كذا، أو أن أحج، أو أن أتصدق بكذا لزمه الوفاء. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16123/وجوب-الوفاء-بالنذر-حسب-النية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_593/59303.mp3","categories":["الأيمان والنذور"]},{"id":17296,"question":"ما حكم قول: في ذمتي، أو قول: في ذمتك؟","title":"حكم قول: في ذمتي","answer":"الجواب: ما في حرج في ذمتي ما في حرج، الممنوع بذمتي الحلف بها بذمتي، أو بأمانتي، أو بأمانة ما يجوز، أما في ذمتي، أو في أمانتي ما يصير حلفًا (في) ما يصير حلف. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16137/حكم-قول-في-ذمتي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_593/59309.mp3","categories":["الأيمان والنذور"]},{"id":17348,"question":"تقول: أنا بعض الأحيان أحلف بالله، وأقسم به، وأنا غير صادقة، ولقد فعلت ذلك لأسباب وظروف، فهل علي ذنب، وإن كان علي ذنب فما كفارة ذلك، أفيدوني؟ جزاكم الله خيرًا.","title":"حكم الحلف كذبًا وكفارة ذلك","answer":"الجواب: نعم لا يجوز لك الحلف بالله كاذبة، وعليك التوبة إلى الله  ولا تعتادي هذا الأمر، يقول النبي ﷺ: من حلف بالله فليصدق ويقول ﷺ: من حلف على يمين هو فيها كاذب يقتطع بها مال امرئ مسلم بغير حق [لقي] الله [وهو] عليه غضبان وفي اللفظ الآخر: فقد أوجب الله له النار، وحرم عليه الجنة. فالمقصود أن اليمين بالكذب لا تجوز، بل يجب الصدق في الأيمان في جميع الأحيان، وإذا حلف الإنسان على يمين ليأخذ بها مال امرئٍ مسلم، فهذا من أعظم الكبائر، وفي الحديث: لقي الله وهو عليه غضبان وفي اللفظ الآخر: فقد أو جب الله له النار، وحرم عليه الجنة هذا وعيد عظيم. وهكذا الأيمان في غير إقطاع المال، أن تقولين: والله إني ما فعلت كذا، والله إني فعلت كذا، وأنت كاذبة، لا يجوز هذا، فعليك التوبة إلى الله من ذلك، والاستغفار، وليس عليك كفارة في أصح قولي العلماء، لكن عليك التوبة إلى الله، والاستغفار، والندم، والعزم الصادق ألا تعودي إلى مثل ذلك. إلا إذا كان في أمور يباح فيها الكذب فلا بأس، كالإصلاح بين الناس، والحرب، وحديث الرجل امرأته، والمرأة زوجها، كان النبي ﷺ يرخص في الكذب في هذه الأمور الثلاثة، فإذا كذب الإنسان في الإصلاح بين شخصين، أو جماعتين، أو قبيلتين قال: والله يا فلان إن فلانًا يدعو لك.. يثني عليك، ثم راح للآخر، وقال كذلك، يريد أن يصلح بينهم فلا بأس -إن شاء الله- للإصلاح؛ لأن الرسول ﷺ رخص في هذا.. في ثلاث: في الإصلاح بين الناس، وفي الحرب، يعني: الجهاد، وفي حديث الرجل امرأته، والمرأة زوجها. وهكذا المرأة لزوجها: والله إني ما فعلت هذا الشيء، تخاف يغضب عليها، والله ما رحت لآل فلان، والله ما زرتهم، والله ما خرجت من بيتك كذا وكذا، دفعًا للفتنة بينهما، أو والله لا أعود، أو ما أشبه ذلك، وإن كانت في نيتها تعود؛ لأن هذا فيه؛ حرصًا على بقاء المودة، وبقاء العشرة الطيبة، وحذرًا من شدة الخصومة، فتفضي إلى الطلاق. فالحاصل: أنها كونها تكذب في شيء يتعلق بها مع زوجها مما يهدئ غضبه، ويسبب بقاء العشرة، ولا يتعلق بالآخرين، لا بأس بذلك، والله ما أفعل كذا، والله ما أعصيك مستقبلًا، والله ما أخرج من البيت إلا بإذنك، وما أشبه ذلك.. وهو كذلك يقول لها: والله إني ما أفعل كذا، والله إني ما أروح لفلان، أو والله ما أكلم فلانة، وإن كان كاذبًا، أو والله ما كلمت فلانًا، أو والله ما كلمت فلانة، حتى يهدئ غضبها، وحتى تبقى المودة، وحتى لا يقع الطلاق، كل هذه أمور لا بأس بها فيما بين الزوج والزوجة فيما يتعلق بهما خاصة، ولا يتعلق بظلم غيرهما، ولا بالكذب على غيرهما. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16221/حكم-الحلف-كذبا-وكفارة-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_834/nour_83409.mp3","categories":["الأيمان والنذور"]},{"id":17393,"question":"نعود في بداية هذه الحلقة إلى رسالة وصلت إلى البرنامج من المملكة الأردنية الهاشمية، أو باعثتها الأخت المستمعة إيمان يوسف عرضنا بعض أسئلتها في حلقة مضت، وفي هذه الحلقة تسأل وتقول: نذرت أن أصوم شهرًا، فهل يجوز أن أصوم ثلاثين يومًا في يومي الإثنين، والخميس؟ أم لا بد من الأيام متتالية؟","title":"ما حكم التتابع لمن نذر أن يصوم شهرًا كاملًا؟","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فالنذر مكروه لقول النبي ﷺ: لا تنذروا فإن النذر لا يرد من قدر الله شيئًا، وإنما يستخرج به من البخيل فالمشروع عدم النذر، ولكن متى نذر الإنسان طاعة لله فإنه يوفي بها، لقول النبي ﷺ: من نذر أن يطيع الله فليطعه، ومن نذر أن يعصي الله فلا يعصه رواه البخاري في الصحيح. وقد أثنى الله سبحانه على الموفين بالنذر من المؤمنين، فقال: يُوفُونَ بِالنَّذْرِ وَيَخَافُونَ يَوْمًا كَانَ شَرُّهُ مُسْتَطِيرًا [الإنسان:7] فالواجب عليك الوفاء؛ لأن الصوم طاعة لله، وعليك أن تصومي شهرًا متتابعًا إذا كنت نويت التتابع، أما إذا كنت ما نويت التتابع، فالأفضل التتابع؛ لأن الشهر يكون متتابعًا، أما إن كنت نويت عدم التتابع.. نويت أن تصومي ثلاثين يومًا مفرقة، فلا حرج أن تصومي الإثنين والخميس حتى تكملي ثلاثين. أما إذا كنت نويت التتابع فلا بد من صوم ثلاثين متتابعة، أو قلت: شهرًا، ولم تنو شيئًا فالأفضل أن تتابعي؛ لأن الشهر يكون متتابعًا، ونوصيك بعدم العود إلى النذور. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16246/ما-حكم-التتابع-لمن-نذر-ان-يصوم-شهرا-كاملا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_835/nour_83501.mp3","categories":["الأيمان والنذور"]},{"id":17427,"question":"من ضمن كفارات اليمين إطعام عشرة مساكين، هل إطعامهم يكون بوجبة واحدة، أم يومًا كاملًا، أم نعطيهم الطعام ذرة، أو قمح؟ وما مقدار ذلك؟","title":"كيفية الإطعام في كفارة اليمين","answer":"الجواب:  الواجب وجبة واحدة، غداء أو عشاء، أو تعطيهم نصف الصاع، يعني: كيلو ونصف كل واحد من طعام البلد، من قوت البلد.. إن كان قوت البلد ذرة تعطيهم ذرة، قوتها رز تعطيهم رزًا، حنطة تعطيهم حنطة، من قوت البلد، والحمد لله، أو نصف صاع من التمر، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16292/كيفية-الاطعام-في-كفارة-اليمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_835/nour_83519.mp3","categories":["الأيمان والنذور"]},{"id":17429,"question":"سماحة الشيخ عبد العزيز حفظكم الله، البعض من الناس يلزمون أنفسهم بهذه النذور، ومن ثم يعجزون عنها، ويطلبون الفتيا من المشايخ، ما الواجب على الناس في ذلك يا شيخ؟","title":"توجيه لمن يلزمون أنفسهم بالنذور","answer":"الجواب: النذر لا ينبغي، الرسول نهى عن النذر، وقال ﷺ: لا تنذروا فإن النذر لا يرد من قدر الله شيئًا، وإنما يستخرج به من البخيل.  فالواجب على الناس ترك النذور، وعدم التعاطي، يعني: ينبغي للمسلم أن يتجنب النذور؛ لأنه ينذر، ثم يندم، فالواجب تجنب النذور، لكن متى نذر طاعةً؛ وجب الوفاء؛ لأن الله قال سبحانه: يُوفُونَ بِالنَّذْرِ وَيَخَافُونَ يَوْمًا كَانَ شَرُّهُ مُسْتَطِيرًا[الإنسان:7] ويقول سبحانه: وَمَا أَنفَقْتُمْ مِنْ نَفَقَةٍ أَوْ نَذَرْتُمْ مِنْ نَذْرٍ فَإِنَّ اللَّهَ يَعْلَمُهُ [البقرة:270] يعني: فيجازيكم عليه، والنبي يقول ﷺ: من نذر أن يطيع الله فليطعه.  فإذا وقع النذر نظر فيه، فإن كان طاعةً لله؛ وجب الوفاء، وإن كان غير طاعة؛ كفَّر عن نذره، لكن لا ينبغي له أن ينذر أولًا، يعني: يعلم ألا ينذر أبدًا، لكن متى نذر طاعةً، كأن يقول مثلما تقدم: إن الله شفى مريضي؛ صمت شهرًا، أو صمت عشرة أيام.. تصدقت بألف ريال، وما أشبه ذلك؛ يلزمه الوفاء، لكن أولًا يقال له: لا تنذر، لكن متى نذر طاعة؛ لزمه الوفاء، نعم. المقدم: شكر الله لكم يا سماحة الشيخ، وبارك الله فيكم، وفي علمكم، ونفع بكم المسلمين.","link":"https://binbaz.org.sa/fatwas/16300/توجيه-لمن-يلزمون-انفسهم-بالنذور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_771/nour_77122.mp3","categories":["الأيمان والنذور","البيوع","نصائح وتوجيهات"]},{"id":17439,"question":"من السودان أبو أنس يقول: شخص نذر لله أن يتقرب بقربة معينة لله  إذا تحقق له شيء معين بشروطه،  هل يجوز التراجع عما نذر القيام به قبل وقوع ما تحقق؟","title":"نذر الطاعة يجب الوفاء به","answer":"الجواب: متى نذر وجب عليه الوفاء بالنذر، صيامًا، أو صلاة، أو صدقة إذا تحقق المنذور الذي علق عليه النذر، وليس له التراجع، بل يلزم، يقول النبي ﷺ: من نذر أن يطيع الله؛ فليطعه فإذا قال: إن شافى الله مريضي؛ صمت شهرًا، أو تصدقت بكذا، أو قال: لله علي إن ولد لي ولد أن أتصدق بكذا، أو أصوم كذا، يلزمه ذلك متى وجد الشرط، أو قال: لله علي إن بلغني الله الحج، وحججت أن أتصدق بكذا، أو أصوم كذا.. كذلك. المقصود قوله ﷺ: من نذر أن يطيع الله؛ فليطعه إذا نذر نذرًا شرعيًا؛ يلزمه الوفاء به.  أما إذا كان النذر غير شرعي؛ فإنه يكفر كفارة يمين، كأن يقول: لله علي إن ولد لي أن أشرب الخمر، أو أن أعصي الله بكذا، أو ما كذا، لا هذا ما يجوز، أو ولله عليه إن رزقه الله كذا أن يفعل ما حرم الله عليه من سائر المعاصي؛ يكفر كفارة يمين، أو شيء مباح مثل: إن شفى الله مريضي أن أنتقل من البيت الفلاني إلى البيت الفلاني، هذا المباح له ينتقل، وإلا ما ينتقل؛ يكفر كفارة يمين إذا صار شيئًا مباحًا، ما هو بقربة، ما هو بطاعة. فالحاصل: أنه إذا كان النذر طاعة؛ وجب الوفاء، وإن كان مباحًا يخير إن شاء وفى، وإن شاء كفر عن يمينه. أما إن كان معصية ليس له فعل المعصية، بل يكفر كفارة يمين، إن شاء الله إن شفى الله مريضه أن يفعل ما حرم الله عليه، أن يعمل بالربا، أن يزني، أن يسرق، أن يغتاب فلانًا؛ يكفر كفارة يمين، ولا يعصي الله، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16297/نذر-الطاعة-يجب-الوفاء-به","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_771/nour_77121.mp3","categories":["الأيمان والنذور"]},{"id":17486,"question":"يقول هذا السائل: من هم الأشخاص الذين لا يحق لهم الأكل من النذر؛ لأننا سمعنا بأن الأصول والفروع لا يحق لهم الأكل من النذر أفتونا مأجورين؟","title":"هل يأكل أصول الناذر وفروعه من النذر؟","answer":"الجواب: إذا نذر نذرًا صدقة يعطيها الفقراء، إذا قال: لله علي أن أتصدق بكذا، يعطيها الفقراء من إخوانه من أقاربه من غيرهم، أما أبوه وأمه، وأصوله وفروعه لا يعطيهم، إنما يعطي النذر للفقراء من أقاربه الحواشي كالإخوة وبنيهم، والأعمام، والأجنبيين الأجانب من الفقراء إذا كانوا فقراء، والنذر للفقراء، كأن يقول: لله علي إن عافاني الله أن أتصدق بمائة درهم أو بألف درهم فعافاه الله يتصدق على الفقراء، وإذا كان في إخوته أو أعمامه فقراء يعطيهم منه، وهكذا لو قال: لله علي أن أتصدق بمائة ألف أو بمائة صاع رز أو كذا.. أو كذا.. يعطي الفقراء لكن لا يعطي أصوله وفروعه؛ لأن عليه نفقتهم، فلا يعطي أباه ولا أمه، ولا جده ولا جدته، ولا أولاده ولا أولاد أولاده، ولكن يعطي الحواشي كالإخوة، والأعمام، وبنيهم إذا كانوا فقراء. نعم.\nالمقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16397/هل-ياكل-اصول-الناذر-وفروعه-من-النذر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_773/nour_77318.mp3","categories":["الأيمان والنذور"]},{"id":17508,"question":"من جمهورية مصر العربية السائل سالم يقول: سمعت من بعض الناس بأنه لا يجوز الحلف بصفات الله وخاصة صفة الحياة، فقلت لهم: بأن الحلف بحياة الله جائز بناء على ما قرأت، فهل كلامي صحيح؟","title":"جواز الحلف بصفات الله","answer":"الجواب: نعم. الحلف بالله وبصفاته وبأسمائه كله حق كله جائز، مثلما جاء في الحديث: أعوذ بعزة الله وقدرته من شر ما أجد وأحاذر، أعوذ برضاك من سخطك، أعوذ بكلمات التامات، فالتعوذ بصفات الله، والتعوذ بكلمات الله، والحلف بها كل ذلك جائز، يحلف بالله، يحلف بصفاته، وعزة الله، وقدرة الله، وعلم الله، وحياة الله؛ كله جائز، كما يقول: والله أو بالله تالله، أو والرحمن أو الرحيم أو العزيز أو الحكيم.. كل هذا جائز، وهكذا إذا قال: وعزة الله، أو بعزة الله، أو بعلم الله.. أو ما أشبه ذلك.\nالمقدم: أحسن الله إليكم وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/16429/جواز-الحلف-بصفات-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_774/nour_77414.mp3","categories":["الأيمان والنذور"]},{"id":17629,"question":"تقول: إنها أصيبت بمرض ومن شدة الألم نذرت نذرًا لم تستطع الوفاء به وتسأل كيف تتصرف الآن؟","title":"حكم العجز عن الوفاء بالنذر","answer":"الجواب: إذا كان النذر طاعة لله فعليها أداء الطاعة حسب طاقتها يبقى دين عليها حتى تستطيع، وإذا ما استطاعت لا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا [البقرة:286]، فإذا نذرت إن الله شفاها وعافاها أن تتصدق بألف ريال أو بعشرة آلاف ريال إذا استطاعت تخرجها تعطيها الفقراء أو نذرت صيام أيام معلومة شهرًا شهرين تصوم حسب طاقتها، وإن كانت مريضة تؤجل لقول النبي ﷺ: من نذر أن يطيع الله فليطعه. أما إن كانت نذرت شيئًا مكروهًا أو محرمًا فهذا فيه كفارة يمين، فلو قالت: إن شفاني الله من مرضي أصوم سنة كاملة هذا صوم مكروه عليها كفارة يمين؛ لأن الرسول ﷺ نهى عن صوم الدهر فتكفر كفارة يمين والحمد لله إطعام عشرة مساكين أو كسوتهم هذه كفارة اليمين عشرة فقراء تعشيهم أو تغديهم أو تعطي كل واحد نصف صاع من التمر أو الرز ونحوهما من قوت البلد، أو تكسوهم على قميص قميص لكل واحد فإن عجزت تصوم ثلاثة أيام.\nفالمقصود أنها تفعل ما تستطيع إذا كان نذر طاعة تؤدي الطاعة حسب طاقتها وإن عجزت تبقى في ذمتها، فإن كان المنذور مكروهًا أو محرمًا لم تفعله وعليها كفارة يمين. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16557/حكم-العجز-عن-الوفاء-بالنذر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_844/nour_84403.mp3","categories":["الأيمان والنذور"]},{"id":17648,"question":"من أسئلة هذا السائل يقول: يا سماحة الشيخ! ما حكم الحلف بالقرآن؟","title":"ما حكم الحلف بالقرآن؟","answer":"الجواب: القرآن كلام الله الحلف به لا بأس به، وكلام الله والقرآن ما فعلت كذا، القرآن كلام الله، كما يقول: والله أو وبالله أو وعلم الله أو ورحمة الله، أي: يقصد لصق بالرحمة سبحانه، أو وكلام الله، كل ذلك لا بأس به، الحلف بالله وبصفاته.","link":"https://binbaz.org.sa/fatwas/16578/ما-حكم-الحلف-بالقران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_594/59422.mp3","categories":["الأيمان والنذور"]},{"id":17661,"question":"إذا حلف الإنسان ثم استغفر من بعد حلفه، هل استغفاره صحيح؟ وهل يجب عليه صيام ثلاثة أيام؟","title":"حكم من حلف ثم استغفر","answer":"الجواب: إذا حلف عليه ينفذ، فإن لم ينفذ عليه كفارة إذا قال: والله لا أكلم فلان، فالاستغفار بعد هذا ما يرفع اليمين، إذا كلمه عليه كفارة اليمين، أو قال: والله ما أسافر اليوم، ثم سافر؛ عليه كفارة يمين، والذي يقول: أستغفر الله ما يكفي، عليه الكفارة، أو قال: والله ما آكل طعام فلان، ثم أكل طعامه؛ عليه كفارة يمين.","link":"https://binbaz.org.sa/fatwas/16592/حكم-من-حلف-ثم-استغفر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_594/59430.mp3","categories":["الأيمان والنذور"]},{"id":17712,"question":"من أسئلة السائلة أم محمد من مدينة الزلفي تقول: يا سماحة الشيخ! لقد حلفت على أولادي ثلاثة أيمان، وقد نقضوها، فكيف أكفر عن تلك الأيمان، مع العلم أن بين كل يمين وآخر فترة؛ وضحوا لي ذلك يا سماحة الشيخ؟","title":"كفارة الأيمان المتعددة","answer":"الجواب: إذا كانت على أفعال كل يمين لها كفارة، أما إن كانت على فعل واحد فكفارة واحدة تكفي، فإذا حلفت عليهم ثلاث مرات: والله ما تسوون كذا، والله ما تسوون كذا، والله ما تسوون كذا؛ فعل واحد، ولو في أيام، ولو في أوقات متعددة؛ كفارته واحدة.\nأما إذا كان: لا أفعل، والله ما تفعلون كذا، والله ما تزورون فلان، والله ما تشتروا هذا الشيء؛ الأفعال مختلفة، كل شيء له كفارة، كل يمين لها كفارة.","link":"https://binbaz.org.sa/fatwas/16663/كفارة-الايمان-المتعددة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_595/59523.mp3","categories":["الأيمان والنذور"]},{"id":17828,"question":"هذه الأخت السائلة تقول في هذا  أمي نذرت أن تصوم كل سنة شهرًا إذا شفى الله أخي الكبير، ولما شفي والحمد لله واصلت والدتي الصيام حتى كبرت في السن، وأصيبت بالسكري؛ لأنها تصوم رجب كاملًا وشعبان ورمضان وتصوم الست البيض، الآن هي ما تستطيع أن تصوم الأشهر التي نذرتها، هل عليها كفارة وما...؟","title":"حكم من نذر ثم عجز عن القيام بنذره","answer":"الجواب: ما عليها شيء؛ مادام ما تستطيع فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ[التغابن:16]، ..، تستطيع عليها كفارة إطعام مسكين عن كل يوم، عن الشهر الذي نذرت. نعم.\nالمقدم: أحسن الله إليكم، وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16818/حكم-من-نذر-ثم-عجز-عن-القيام-بنذره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_597/59725.mp3","categories":["الأيمان والنذور"]},{"id":17840,"question":"سماحة الشيخ! يقول هذا السائل: عندما أقسم بآيات الله هل يجوز ذلك؟","title":"حكم الحلف بآيات الله","answer":"الجواب: إن أراد آيات الله القرآن فنعم؛ لأن القرآن كلام الله، والقسم بالله وصفاته حق جائز، أما إن أراد آيات الله المخلوقة الليل والنهار، والشمس والقمر، والأرض ونحو ذلك لا ما يجوز؛ لأن الرسول  قال: من حلف بشيء دون الله فقد أشرك، قال: من كان حالفًا فليحلف بالله أو ليصمت، فليس لأحد أن يحلف إلا بالله أو بصفة من صفاته ، وليس لأحد أن يحلف بالنبي ﷺ أو بالأمانة أو شرف فلان أو حياة فلان أو بآيات الله المخلوقة، لا. أما بآيات الله التي هي كلامه  - القرآن - فلا بأس؛ لأنه قسم بصفات الله. نعم.\nالمقدم: أحسن الله إليكم وجزاكم الله عنا وعن المسلمين خير الجزاء.","link":"https://binbaz.org.sa/fatwas/16833/حكم-الحلف-بايات-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_779/nour_77913.mp3","categories":["الأيمان والنذور"]},{"id":17880,"question":"رسالة مطولة بعث بها المستمع: أحمد محمد أحمد ، ملخص ما في هذه الرسالة أنه نوى تأدية فريضة الحج، وعندما كان قادمًا إلى الأراضي المقدسة، استوقفته الجهات المختصة، وسألته بعض الأسئلة، فحلف يمينًا أنه أكبر إخوته، وهو ليس كذلك، ما حكم ما فعل؟ وبماذا توجهونه؟ جزاكم الله خيرًا.","title":"ما يلزم من حلف كاذبًا حتى يتمكن من الحج؟","answer":"الجواب: عليه الاستغفار؛ لأن هذه يمين غموس كاذبة، فعليه التوبة إلى الله من ذلك، التوبة من هذه اليمين، وحجه صحيح، والحمد لله، لكنه ناقص في اليمين الكاذبة، فإذا تاب؛ تاب الله عليه، وجبر نقصه. نعم.\nالمقدم: جزاكم الله خيرًا، وأحسن إليكم، هل توجهونه إلى شيءٍ آخر سماحة الشيخ؟\nالشيخ: ما عليه الكفارة إنما عليه التوبة إلى الله، لأن هذه تسمى اليمين الغموس، وهي اليمين الكاذبة، فعليه فيها التوبة إلى الله . نعم.\nالمقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/16892/ما-يلزم-من-حلف-كاذبا-حتى-يتمكن-من-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_728/nour_72811.mp3","categories":["الأيمان والنذور"]},{"id":17891,"question":"هذه السائلة أم أحمد من المنطقة الجنوبية تقول: بأنها امرأة كبيرة في السن وعندها ولد كان عاقًا، وفي يوم من الأيام حصل بينها وبين هذا الولد مشكلة فقامت بلعنه عدة مرات، ثم حلفت بالله وعاهدت الله أن لا تعيش معه ما دامت على قيد الحياة، وقد هداه الله  بعد ذلك وأصبحت تعيش معه، ماذا يجب عليها أن تفعل؟ بارك الله فيكم.","title":"ما يجب على من حنثت في يمينها؟","answer":"الجواب: عليها كفارة اليمين والحمد لله، كفارة يمين وهي إطعام عشرة مساكين، لكل مسكين نصف صاع من قوت البلد من تمر أو رز أو حنطة، نصف صاع كيلو ونصف تقريبًا، لعشرة فقراء خمسة عشر كيلو، كل واحد له كيلو ونصف، يعني: نصف الصاع، أو كسوة كل واحد يعطى قميص أو إزار ورداء. نعم.","link":"https://binbaz.org.sa/fatwas/16904/ما-يجب-على-من-حنثت-في-يمينها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_780/nour_78008.mp3","categories":["الأيمان والنذور"]},{"id":17915,"question":"هذا السائل يا سماحة الشيخ يقول: ما حكم من قال: عهد على نفسي أن أفعل، ولم أفعل، فهل عليه كفارة؟","title":"ما يلزم من أخذ على نفسه عهدا ولم يف به؟","answer":"الجواب: إن كفَّر فهو حسن، وليس بيمين، اليمين أن يقول: والله أو بالله أو تالله أو آلله، ولكن العهد ليس بيمين، لكن بعض أهل العلم يرى فيه كفارة اليمين؛ لأن الرسول ﷺ أمر بالوفاء بالعهود، والله أمر بذلك: وَأَوْفُوا بِعَهْدِ اللَّهِ إِذَا عَاهَدْتُمْ [النحل:91]، والنبي ﷺ ذم المنافقين فقال: آية المنافق ثلاث: إذا حدث كذب، وإذا وعد أخلف... فينبغي له أن يوفي بالوعد، وإذا أخلف فليستغفر الله، وإذا كفر عن ذلك كفارة يمين فحسن.\nالمقدم: جزاكم الله خيرًا، يا فضيلة الشيخ.","link":"https://binbaz.org.sa/fatwas/16930/ما-يلزم-من-اخذ-على-نفسه-عهدا-ولم-يف-به","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_598/59821.mp3","categories":["الأيمان والنذور"]},{"id":17923,"question":"يقول هذا السائل يا سماحة الشيخ: ما حكم من حلف أيمان كثيرة، ولكنه لا يعلم عدد هذه الأيمان، وحالته المادية متوسطة؟ فماذا عليه أن يفعل إذا أراد أن يكفر عن أيمانه السابقة؟","title":"كيفية الكفارة عن الأيمان التي لا يعلم عددها","answer":"الجواب: يتحرى ويعمل بظنه، ويكفر عنها كلها، إذا كانت على أفعال متعددة، مثل: والله ما يسافر، والله ما يكلم فلانًا، والله ما يأكل طعام فلان، على أفعال، يتحرى إذا كان ما يضبطها يتحرى ويعمل بظنه، ويكفر عنها.\nأما إذا كان يعلمها؛ يكفر عنها كلها، أما إذا كان شك فيها والتبس عليه الأمر يتحرى، إذا غلب على ظنه أنها سبع، سبع، غلب على ظنه أنها عشر، عشر، وهكذا.\nالمقدم: جزاكم الله خيرًا، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/16936/كيفية-الكفارة-عن-الايمان-التي-لا-يعلم-عددها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_598/59823.mp3","categories":["الأيمان والنذور"]},{"id":17928,"question":"يقول: لقد ذهبت في سفر وعندما كنا في الطريق حان وقت صلاة المغرب لكن أبي لم يتوقف للصلاة بحجة أننا في سفر وأننا سنقضيها في المنزل بعد الوصول، ونتيجة لذلك أقسمت أن لا أذهب معهم مرة أخرى في سفر وكنت غضبان، هل يعتبر قسمي لا حرج علي فيه؛ لأنني كنت غضبان أم أنه يجب علي أن أفعل شيء؟ جزاكم الله خيرًا.الشيخ: .......، تعيده نعم، الله المستعان. نعم.المقدم: يقول: لقد ذهبت في سفر وعندما كنا في الطريق حان وقت صلاة المغرب ولكن أبي لم يتوقف للصلاة بحجة أننا في سفر وأننا سنقضيها في المنزل بعد الوصول، ونتيجة لذلك أقسمت أن لا أذهب معهم مرة أخرى في سفر وكنت غضبان، إذا سافرت معهم هل علي كفارة أم ليس علي شيء؛ لأنني كنت غضبانا؟","title":"وجوب الكفارة على الحانث وإن كان غاضبًا","answer":"الجواب: عليك الكفارة؛ كفارة اليمين، وفعلهم لا بأس به إذا أخروا صلاة المغرب وهم في السفر صلوها جمعًا مع العشاء ولو في البلد لا حرج والحمد لله، يجوز للمسافر أن يؤخر الأولى مع الثانية إذا كان في طريق السفر، المغرب مع العشاء، الظهر مع العصر إذا كان مستمرًا في السفر فيكون جمع تأخير، وأما يمينك فعليك كفارة اليمين إطعام عشرة مساكين أو كسوتهم أو عتق رقبة فإن عجزت تصوم ثلاثة أيام والحمد لله.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16985/وجوب-الكفارة-على-الحانث-وان-كان-غاضبا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_847/nour_84720.mp3","categories":["الأيمان والنذور"]},{"id":17931,"question":"المستمع (ع. ع. ن) من الرياض بعث يسأل ويقول: إذا حلفت عدة مرات على أن لا أفعل بعض الأشياء...الشيخ: أيش؟المقدم: إذا حلفت عدة مرات على أن لا أفعل بعض الأشياء ثم فعلتها، هل أكفر عن ذلك بصيام ثلاثة أيام مع العلم أنني لا أستطيع أن أفعل غير ذلك؟","title":"حكم من حنث في يمينه ولا يستطيع غير الصيام","answer":"الجواب: إذا حلف الإنسان على أن يفعل بعض الأشياء ولو كرر ذلك مرات ثم لم يفعل فعليه كفارة اليمين، مثل: والله لأصومن يوم الخميس، والله لأصومن يوم الخميس والله لأصومه، أو والله لأكلمن فلانًا، والله لأكلمن فلانًا والله لأكلمن فلانًا، فلم يفعل عليه كفارة اليمين وهي: إطعام عشرة مساكين لكل مسكين نصف صاع من قوت البلد أو كسوتهم أو تحرير رقبة، فإن عجز صام ثلاثة أيام، وإذا كنت لا تستطيع إلا الصيام أجزأك الصيام، والحمد لله. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16984/حكم-من-حنث-في-يمينه-ولا-يستطيع-غير-الصيام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_847/nour_84719.mp3","categories":["الأيمان والنذور"]},{"id":17936,"question":"يقول: لقد ذهبت في سفر وعندما كنا في الطريق حان وقت صلاة المغرب لكن أبي لم يتوقف للصلاة بحجة أننا في سفر وأننا سنقضيها في المنزل بعد الوصول، ونتيجة لذلك أقسمت أن لا أذهب معهم مرة أخرى في سفر وكنت غضبان، هل يعتبر قسمي لا حرج علي فيه؛ لأنني كنت غضبان أم أنه يجب علي أن أفعل شيء؟ جزاكم الله خيرًا.الشيخ: .......، تعيده نعم، الله المستعان. نعم.المقدم: يقول: لقد ذهبت في سفر وعندما كنا في الطريق حان وقت صلاة المغرب ولكن أبي لم يتوقف للصلاة بحجة أننا في سفر وأننا سنقضيها في المنزل بعد الوصول، ونتيجة لذلك أقسمت أن لا أذهب معهم مرة أخرى في سفر وكنت غضبان، إذا سافرت معهم هل علي كفارة أم ليس علي شيء؛ لأنني كنت غضبانا؟","title":"وجوب الكفارة على الحانث وإن كان غاضبًا","answer":"الجواب: عليك الكفارة؛ كفارة اليمين، وفعلهم لا بأس به إذا أخروا صلاة المغرب وهم في السفر صلوها جمعًا مع العشاء ولو في البلد لا حرج والحمد لله، يجوز للمسافر أن يؤخر الأولى مع الثانية إذا كان في طريق السفر، المغرب مع العشاء، الظهر مع العصر إذا كان مستمرًا في السفر فيكون جمع تأخير، وأما يمينك فعليك كفارة اليمين إطعام عشرة مساكين أو كسوتهم أو عتق رقبة فإن عجزت تصوم ثلاثة أيام والحمد لله.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16985/وجوب-الكفارة-على-الحانث-وان-كان-غاضبا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_847/nour_84720.mp3","categories":["الأيمان والنذور"]},{"id":17968,"question":"نعود في بداية هذه الحلقة إلى رسالة المستمع عبيد بن حسين الإبراهيم سوري ومقيم في عرعر، أخونا عبيد عرضنا له سؤالًا في حلقة مضت وفي هذه الحلقة يسأل ويقول: قبل فترة نذرت لله أن أذبح ثلاثة عشر رأسًا من الضأن، وهذا الأمر سألت الله أن يسهله لي وتيسر أمري والحمد لله، وكان وقتها لا تزيد تكلفة الرأس من الضأن على مائتين وخمسين ليرة سوري والآن الرأس الواحد يكلف من ألفين وخمسمائة إلى ثلاثة آلاف وخمسمائة ليرة فقمت بذبح بقرة بدلًا عنها، سؤالي: هل تكفي البقرة وسعرها حوالي تسعة آلاف ليرة عن الثلاثة عشر رأسًا أم لا؟ جزاكم الله خيرًا.","title":"حكم ذبح البقر بدل الغنم في النذر","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:\nفظاهر الأدلة الشرعية أن البقرة لا تكفي في هذا؛ لأنك نذرت غنمًا والغنم لحمها أطيب وأنفع من لحم البقر، فالذي أرى أن عليك أن تكمل الذبائح التي نذرتها وهي الغنم حسب طاقتك: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، بين وقت وآخر حتى تكمل العدد الذي نذرته لله ، وعليك مع هذا أن تدع النذر في المستقبل، النبي ﷺ نهى عن النذر وقال: إنه لا يأتي بخير وإنما يستخرج به من البخيل. فالمشروع لك أن تترك النذر في المستقبل، أما هذا النذر فعليك أن توفي به لقول النبي ﷺ: من نذر أن يطيع الله فليطعه، ومن نذر أن يعصي الله فلا يعصه وهذا نذر طاعة لله، نذر الغنم قربة إلى الله وطاعة ...، فعليك أن توفي بنذرك حسب الطاقة كلما استطعت ذبحت ما تيسر حتى تكمل.\nأما البقرة فالأقرب أنها لا تجزئ؛ لأن الغنم أطيب منها وأنفع للفقراء والمساكين. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16992/حكم-ذبح-البقر-بدل-الغنم-في-النذر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_848/nour_84801.mp3","categories":["الأيمان والنذور"]},{"id":17974,"question":"نعود في بداية هذه الحلقة إلى رسالة المستمع عبيد بن حسين الإبراهيم سوري ومقيم في عرعر، أخونا عبيد عرضنا له سؤالًا في حلقة مضت وفي هذه الحلقة يسأل ويقول: قبل فترة نذرت لله أن أذبح ثلاثة عشر رأسًا من الضأن، وهذا الأمر سألت الله أن يسهله لي وتيسر أمري والحمد لله، وكان وقتها لا تزيد تكلفة الرأس من الضأن على مائتين وخمسين ليرة سوري والآن الرأس الواحد يكلف من ألفين وخمسمائة إلى ثلاثة آلاف وخمسمائة ليرة فقمت بذبح بقرة بدلًا عنها، سؤالي: هل تكفي البقرة وسعرها حوالي تسعة آلاف ليرة عن الثلاثة عشر رأسًا أم لا؟ جزاكم الله خيرًا.","title":"حكم ذبح البقر بدل الغنم في النذر","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:\nفظاهر الأدلة الشرعية أن البقرة لا تكفي في هذا؛ لأنك نذرت غنمًا والغنم لحمها أطيب وأنفع من لحم البقر، فالذي أرى أن عليك أن تكمل الذبائح التي نذرتها وهي الغنم حسب طاقتك: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، بين وقت وآخر حتى تكمل العدد الذي نذرته لله ، وعليك مع هذا أن تدع النذر في المستقبل، النبي ﷺ نهى عن النذر وقال: إنه لا يأتي بخير وإنما يستخرج به من البخيل. فالمشروع لك أن تترك النذر في المستقبل، أما هذا النذر فعليك أن توفي به لقول النبي ﷺ: من نذر أن يطيع الله فليطعه، ومن نذر أن يعصي الله فلا يعصه وهذا نذر طاعة لله، نذر الغنم قربة إلى الله وطاعة ...، فعليك أن توفي بنذرك حسب الطاقة كلما استطعت ذبحت ما تيسر حتى تكمل.\nأما البقرة فالأقرب أنها لا تجزئ؛ لأن الغنم أطيب منها وأنفع للفقراء والمساكين. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16992/حكم-ذبح-البقر-بدل-الغنم-في-النذر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_848/nour_84801.mp3","categories":["الأيمان والنذور"]},{"id":17989,"question":"أخيرًا تسأل أختنا وتقول: إني نذرت أن أصوم شهرًا فهل يجوز لي أن أصومه أيامًا متفرقة؟","title":"حكم صيام الشهر مفرقًا لمن نذر صيامه","answer":"الجواب: على النية، إن كانت النية المتابعة صومي متتابعة، وإن نويت شهرًا مطلقًا فالأفضل المتابعة؛ لأن الغالب من الشهر ... متتابع، وإن فرقت فلا حرج لكن الأفضل التتابع، أما إذا ما نويت التتابع قلت: ثلاثين يوم بس ما قلت شهرًا أو قلت: عشرين يوم فلا يلزم التتابع. أما إذا نويت التتابع وقلت عشرين يومًا، يعني: نويت متتابعة، أو شهرًا نويتيه متتابع وجب التتابع عملًا بالنية، الأعمال بالنيات، إما إذا لم تنوي التتابع فالتتابع إذا سميت شهرًا يكون أفضل؛ لأن الشهر من صفته أن يكون متتابعًا، ولو فرقت فلا حرج إن شاء الله؛ لأن النية معتبرة وليس هناك نية، نعم، والشهر يطلق على الثلاثين يومًا. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17043/حكم-صيام-الشهر-مفرقا-لمن-نذر-صيامه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_849/nour_84924.mp3","categories":["الأيمان والنذور"]},{"id":18002,"question":"من المستمع محمد سليمان محمد بعث يسأل ويقول: إذا حلف الرجل على زوجته وقال لها: علي الحرام لا تصلي بيت فلان مثلًا: جارة أو ما أشبه ذلك، وبعد وقت وصلت الزوجة إلى ذلك البيت المحلوف عليه فما الحكم؟","title":"حكم الحلف بالحرام على الزوجة","answer":"الجواب: هذا فيه تفصيل: إن كان مقصوده تحريمها إذا فعلت ذلك فعليه كفارة الظهار في أصح أقوال أهل العلم وهي: عتق رقبة، فإن عجز صام شهرين متتابعين، فإن عجز أطعم ستين مسكينًا ثلاثين صاعًا لكل مسكين نصف صاع من قوت البلد قبل أن يمسها. أما إن كان المراد منعها وتحذيرها وتخويفها وتهديدها فهذا عليه كفارة يمين إذا خالفته، لا يلزمه كفارة الظهار ولكن كفارة اليمين؛ لأنه في حكم اليمين وهي إطعام عشرة مساكين أو كسوتهم أو عتق رقبة، فإن عجز صام ثلاثة أيام إذا كان مقصوده من هذا التحريم تخويفها وتحذيرها، مثلًا قال لها: عليه الحرام ما تكلمي فلان، عليه الحرام ما تعشين عند دار فلان، عليه الحرام ما تحضرين عرس آل فلان قصده منعها، فهكذا إذا قال: عليه الحرام ما تزورين آل فلان إذا كان المقصود التهديد والتخويف والتحذير وليس المقصود تحريمها عليه إن فعلت فإنه يكون فيه كفارة اليمين. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17033/حكم-الحلف-بالحرام-على-الزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_849/nour_84917.mp3","categories":["الأيمان والنذور","الظهار"]},{"id":18004,"question":"من المستمع محمد سليمان محمد بعث يسأل ويقول: إذا حلف الرجل على زوجته وقال لها: علي الحرام لا تصلي بيت فلان مثلًا: جارة أو ما أشبه ذلك، وبعد وقت وصلت الزوجة إلى ذلك البيت المحلوف عليه فما الحكم؟","title":"حكم الحلف بالحرام على الزوجة","answer":"الجواب: هذا فيه تفصيل: إن كان مقصوده تحريمها إذا فعلت ذلك فعليه كفارة الظهار في أصح أقوال أهل العلم وهي: عتق رقبة، فإن عجز صام شهرين متتابعين، فإن عجز أطعم ستين مسكينًا ثلاثين صاعًا لكل مسكين نصف صاع من قوت البلد قبل أن يمسها. أما إن كان المراد منعها وتحذيرها وتخويفها وتهديدها فهذا عليه كفارة يمين إذا خالفته، لا يلزمه كفارة الظهار ولكن كفارة اليمين؛ لأنه في حكم اليمين وهي إطعام عشرة مساكين أو كسوتهم أو عتق رقبة، فإن عجز صام ثلاثة أيام إذا كان مقصوده من هذا التحريم تخويفها وتحذيرها، مثلًا قال لها: عليه الحرام ما تكلمي فلان، عليه الحرام ما تعشين عند دار فلان، عليه الحرام ما تحضرين عرس آل فلان قصده منعها، فهكذا إذا قال: عليه الحرام ما تزورين آل فلان إذا كان المقصود التهديد والتخويف والتحذير وليس المقصود تحريمها عليه إن فعلت فإنه يكون فيه كفارة اليمين. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17033/حكم-الحلف-بالحرام-على-الزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_849/nour_84917.mp3","categories":["الأيمان والنذور","الظهار"]},{"id":18042,"question":"من القصيم هذه رسالة بعثت بها إحدى الأخوات من هناك تقول: (م. ض)، أختنا تقول: إذا حلف الإنسان وهو في حالة غضب، هل يكون حلفه حلفًا يحقق فعل شيء أو ترك شيء، مع العلم أنني لا أذكر أحيانًا بعض ما أحلف عليه، ما كفارة هذا؟ جزاكم الله خيرًا.","title":"حكم يمين الغضبان","answer":"الجواب: من حلف وهو غضبان، فحاله محل تفصيل، فإن كان اشتد به الغضب حتى فقد شعوره ولم يميز بسبب شدة الغضب لم يملك نفسه، فهذا لا تنعقد يمينه، ولا يلزمه شيء، كما لو طلق في حال شدة الغضب عند المسابة والمخاصمة الشديدة، والمضاربة ونحو ذلك، حتى فقد شعوره؛ لأنه في هذه الحالة أشبه بالمعتوهين والمجانين. أما الغضب العادي فإنه لا يمنع الطلاق ولا يمنع انعقاد اليمين، فإذا قالت: والله لا أكلم فلانًا أو قال الرجل: والله لا أكلم فلانًا أو لا أزوره، أو لا أجيب دعوته، وإن كان غضبان، لكنه غضب لم يخل بشعوره، ولم يبلغ حد الشدة التي تغير الشعور، وتمنع الإنسان من الفكر والنظر، فهذا عليه كفارة اليمين، إذا خالف يمينه؛ لقول النبي ﷺ: إذا حلفت على يمين فرأيت غيرها خيرًا منها؛ فكفر عن يمينك وأت الذي هو خير. فإذا قال: والله لا أزوره، وإن كان غضبان، أو والله لا أكلمه ثم زاره أو كلمه؛ فعليه كفارة اليمين، وهكذا المرأة سواء إذا قالت: والله لا أكلم فلانة ولا أكلم فلانة أو لا أزور فلان أو لا أزور فلانة، أو لا أشتري لها كذا أو لا أعطيها كذا، ثم أرادت الفعل؛ فلها أن تفعل وتكفر عن يمينها، الرجل والمرأة في هذا سواء؛ لهذا الحديث الصحيح وهو قوله ﷺ: إذا حلفت على يمين فرأيت غيرها خيرًا منها، فكفر عن يمينك وأت الذي هو خير وقال عليه الصلاة والسلام: والله إني إن شاء الله لا أحلف على يمين فأرى غيرها خيرًا منها إلا كفرت عن يميني، وأتيت الذي هو خير عليه الصلاة والسلام. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17075/حكم-يمين-الغضبان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_600/60007.mp3","categories":["الأيمان والنذور"]},{"id":18047,"question":"من المستمع: عواد سعود علي الذهيلي الجهني، رسالة، وضمنها جمعًا من الأسئلة، في أحدها يسأل عن: حكم من حلف بالله، ثم لم يلتزم بما حلف عليه؟ جزاكم الله خيرًا.","title":"حكم من حلف بالله ثم نكث في يمينه","answer":"الجواب: الحلف بالله  حق، وعلى صاحبه الالتزام بما حلف عليه، أو الكفارة إن كان أخل به، وإذا رأى أن عدم الالتزام أصلح، وأنه يكفر عن يمينه، فهو أفضل، لقول النبي ﷺ: من حلف على يمين، فرأى غيرها خيرًا منها؛ فليكفر عن يمينه، وليأت الذي هو خير، ويقول ﷺ: إني والله لا أحلف على يمين، فأرى غيرها خيرًا منها، إلا كفرت عن يميني، وأتيت الذي هو خير، فإذا قال: والله لا أكلم فلانًا، ثم رأى أن المصلحة أنه يكلمه، وأن الهجر لا خير فيه، كلمه، يكفر عن يمينه، أو قال: والله ما أجب دعوته، ثم رأى أن المصلحة أن يجيب الدعوة، يجيب الدعوة، ويكفر عن يمينه، إطعام عشرة مساكين، أو كسوتهم؛ فإن عجز، صام ثلاثة أيام. وهكذا؛ إذا حلف أنه ما يسافر لبلد يجوز السفر إليها، ثم بدا له أن يسافر، يكفر عن يمينه. أو حلف أنه لا يحج، أو لا يعتمر، وقد حج الفريضة، لكن حلف أنه لا يتطوع، فهو حينئذٍ يكفر عن يمينه، إذا تيسر له الحج، أفضل له يكفر عن يمينه، ويحج، ويعتمر، ويتزود من الخير، أما إن كان فريضة فيلزمه أن يحج الفريضة، ويكفر عن يمينه. وهكذا، حلف أنه ما يبر والديه، أو حلف أنه يعصي أباه، أو يعصي أمه، هذه يمين فاجرة ما تجوز، يكفر عن يمينه، ويبر والديه. أو والله ما يصلي في الجماعة، هذه يمين كاذبة فاجرة، يصلي في الجماعة، ويكفر عن يمينه، ولا يطاوع الشيطان. المقصود إذا كانت اليمين على فعل معصية، أو ترك واجب، يلزمه التحلل منها، يكفر عن يمينه، ويعمل الواجب، ويدع المعصية. أما إن كانت لا، في مباح، أو في مستحب، فينظر، المستحب الأفضل أن يفعل المستحب، مثل: والله ما يصلي الراتبة، لا، يكفر عن يمينه، والله ما يصلي الضحى، يكفر عن يمينه، يصلي الضحى أفضل له، أما المباح ينظر فيه، فإن رأى الأصلح فعله، فعله، وكفر عن يمينه، قال: والله ما أتغذى عند فلان، أو والله ما أكلم فلانًا، فإن رأى المصلحة أنه يكلمه، أو يتغدى عنده، أو يتعشى عنده، يكفر عن يمينه. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17080/حكم-من-حلف-بالله-ثم-نكث-في-يمينه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_729/nour_72906.mp3","categories":["الأيمان والنذور"]},{"id":18058,"question":"هذا سؤال من المستمع محمود العراف الإبراهيم، سوري الجنسية، يعمل في مدينة عرعر يقول: أنا شاب متزوج حصل بيني وبين زوجتي نزاع بسيط وأرادت أن تذهب إلى أهلها وهي حامل، فانزعجت منها وقلت لها: إذا ذهبت إلى أهلك فأنت مطلقة. بهذا الكلام ولم أزد عليه شيئًا أبدًا، وكنت أقصد بهذا عدم ذهابها إلى أهلها، ولا أقصد الطلاق وقد ذهبت، فما الحكم في مثل هذا الأمر؟","title":"حكم من قال لزوجته: إذا ذهبت لأهلك فأنت مطلقة","answer":"الجواب: إذا كان المقصود من هذا الكلام منعها من الذهاب إلى أهلها، وليس المقصود إيقاع الطلاق؛ فإن هذا يكون في حكم اليمين، هذا الطلاق يكون في حكم اليمين، وعليك أيها السائل! كفارة اليمين؛ وهي إطعام عشرة مساكين أو كسوتهم، والطعام يعطى كل واحد نصف صاع من التمر أو الأرز أو غيرهما من قوت البلد كيلو ونص تقريبًا، أو تعشيهم أو تغديهم، أو تكسوهم كسوة كل واحد يعطى إزارًا ورداء أو يعطى قميصًا. هذا هو الواجب في مثل هذا على الصحيح من قولي العلماء، وقال بعض أهل العلم: إنه يقع الطلاق لكن الصحيح أنه لا يقع إذا كانت النية المنع، وليس النية إيقاع الطلاق؛ لقول النبي ﷺ: إنما الأعمال بالنيات وإنما لكل امرئ ما نوى نعم.","link":"https://binbaz.org.sa/fatwas/17091/حكم-من-قال-لزوجته-اذا-ذهبت-لاهلك-فانت-مطلقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_901/nour_90102.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":18064,"question":"هذا سائل (ش. ع. أ) يقول: حصلت خصومة بيني وبين أخواتي فكنت غاضبًا وقلت: علي نذر صيام شهر إذا أنا تكلمت مع إحداهن، ولكن مضت الأيام وذهب ما كان بيني وبينهن، وحادثتهن بعد ذلك حيث لا أطيق فراقهن فهن أخواتي، فهل يجب علي صيام ذلك الشهر الذي لم أعينه؟ وهل أصومه متفرقًا، أو لابد من التتابع لأنني أعيش في مكة المكرمة والجو بها حار، والنذر وقع مني في حالة غضب؟","title":"حكم نذر اللجاج والغضب","answer":"الجواب: إذا كان الواقع هو ما ذكر؛ فإن هذا النذر ليس قربة، وإنما هو نذر لجاج وغضب، والمقصود منه منع نفسه من الكلام لأخواته. فالحاصل أن هذا في حكم اليمين، هذا النذر في حكم اليمين فعليه كفارة يمين، ولا يلزمك أيها السائل الصوم، بل هذا من أحكام النذر الذي يسمى نذر اللجاج والغضب، وحكمه أنه في حكم اليمين، فعليك كفارة اليمين، وهي إطعام عشرة مساكين، أو كسوتهم أو عتق رقبة، هذه كفارة اليمين، فإذا أطعمت عشرة مساكين غداءً أو عشاءً أو أعطيت كل واحد نصف الصاع من قوت البلد كفى ذلك، أو كسوتهم كفى ذلك. وهكذا لو قال الإنسان: عليه الحج أنه ما يكلم فلانًا، أو عليه كذا وكذا أنه ما يكلم فلانًا، هذا كله ما فيه إلا كفارة اليمين؛ لأنه نذر لجاج وغضب المقصود منه المنع من هذا الشيء. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17099/حكم-نذر-اللجاج-والغضب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_901/nour_90107.mp3","categories":["الأيمان والنذور"]},{"id":18146,"question":"هذا سائل للبرنامج يقول في سؤاله: في بعض الأوقات أقول مثلًا: لو نجحت سوف أطوف حول الكعبة في المسجد الحرام وغير ذلك من العبادات لله  ثم بعد أن أنال ما أريد لا أذكر ما قلت، و ما نصيحتكم في مثل هذا؟ وإذا نسيت ماذا يجب علي أن أفعل؟هل أجتهد وأفعل ما تذكرت؟","title":"حكم الوفاء بالنذر والوعد","answer":"الجواب: هذا فيه تفصيل، إن كان نذر يلزمه الوفاء، إذا قلت: نذر لله علي، أو علي لله إن نجحت أو حصل كذا أن أصلي كذا وكذا أو أن أطوف أو أن أعتمر أو أن أحج لزمك، لزمك الوفاء لقول النبي ﷺ: من نذر أن يطيع الله فليطعه. أما مجرد كلام أنك ستفعل إن شاء الله هذا وعد؛ الأحسن لك أنك تفي به، وليس بنذر، فإذا قلت: إن شاء الله إذا نجحت أصوم كذا، أو أصلي كذا أو أحج؛ فالأحسن لك والمشروع لك الوفاء بهذا؛ لأن الله قال: وَأَوْفُوا بِعَهْدِ اللَّهِ إِذَا عَاهَدْتُمْ[النحل:91]. فهذا نوع من العهد، ولو ما صرحت بالعهد، لكنه وعد طيب، فينبغي لك إذا فعلت هذا قلت: إن شاء الله أني أصوم كذا، أو أصلي كذا، أو أحج؛ فالأفضل والأولى لك أن تفي بهذا الشيء، لكن لا يلزمك؛ لأنك لم تصرح بالعهد، ولم تصرح بالنذر. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/17200/حكم-الوفاء-بالنذر-والوعد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_781/nour_78120.mp3","categories":["الأيمان والنذور"]},{"id":18234,"question":"تقول السائلة أم عمر من البحرين: لقد حلفت عند الغضب عدة مرات ألا أفعل شيئًا، وفعلت هذا الشيء، ولم أدر ما مقدار عدد الحلفات، ماذا علي أن أفعل؟","title":"حكم من حلف على شيء ألا يفعله ثم فعله","answer":"الجواب: عليك كفارة اليمين، عن كل يمين، إذا كانت الأفعال متعددة، أما إذا كان فعلًا واحدًا كفارة واحدة، فإذا قال الإنسان: والله ما أكلم فلان، والله ما أكلم فلان، والله ما أكلم فلان ولو عشر مرات كفارة واحدة، أما إذا قال: والله ما أكلم فلان، والله ما آكل طعامه هذه ثنتين، كفارتين، والله ما أزور فلان، والله ما أسافر، هذه يمينان، كل واحدة لها كفارة. والمقصود أنه إذا كان الفعل واحدًا والأيمان تعددت كفارة واحدة، أما إذا كان أفعال .. تعددت الأيمان على أفعال فلكل يمين كفارة، إذا كان إنسان عاقل، أما إذا اشتد معه الغضب حتى زال عقله، ولم يشعر؛ ما يعتبر كلامه، أما ما دام عقله معه فإنه يعتبر وعليه الكفارة. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/17283/حكم-من-حلف-على-شيء-الا-يفعله-ثم-فعله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_782/nour_78219.mp3","categories":["الأيمان والنذور"]},{"id":18235,"question":"في ثاني أسئلة السائلة أم عمر من البحرين، تقول سماحة الشيخ: عندي صديقة نذرت عندما كانت في المدرسة إذا نجحت أن تصوم شهرًا كاملًا، وعندما ظهرت النتيجة فوجئت بأن اسمها مع الراسبين، وعند المراجعة للأسماء نجحت كانت من الناجحين ولم تصم، والآن لها حاولي تسع سنوات فهل تصوم مع الكفارة؟","title":"حكم من علق نذره على شيء فتحقق ولم يوف بنذره","answer":"الجواب: عليها الصيام؛ لأن الرسول  قال: من نذر أن يطيع الله فليطعه هكذا حديث جاء عن رسول الله ﷺ: من نذر أن يطيع الله فليطعه وإن نذرت إن نجحت وقد بان أنها نجحت عليها أن تصوم ما نذرت، ويكفي إذا صامته والحمد لله ولو تأخر، متى علمت عليها البدار والمسارعة، والحمد لله. المقدم: الحمد لله أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/17284/حكم-من-علق-نذره-على-شيء-فتحقق-ولم-يوف-بنذره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_782/nour_78220.mp3","categories":["الأيمان والنذور"]},{"id":18240,"question":"السائل الذي أرسل برسالة طويلة ملخصها، السائل (ع. ب. د) يقول: مشكلتي يا سماحة الشيخ بأنني شاب غير متزوج، وفي يوم من الأيام وضعت يدي على المصحف الشريف وأقسمت وقلت: والله العظيم لن أفعل هذا المنكر، ولكنني ضعفت أمام نفسي وفعلت هذه العادة السيئة، وحدث ذلك أكثر من مرة، والآن بمشيئة الله تبت من هذا العمل، وأريد الذهاب إلى حج بيت الله الحرام، ماذا علي أن أفعل حتى أبري نفسي وذمتي من ذلك؟","title":"حكم من حلف ولم يوف بيمينه","answer":"الجواب: عليك مع التوبة كفارة يمين والحمد لله، تبت فالحمد لله، التوبة تهدم ما قبلها وتجب ما قبلها والحمد لله، وعليك مع هذا كفارة اليمين إطعام عشرة مساكين أو كسوتهم، أو عتق رقبة فإن عجزت تصوم ثلاثة أيام، لكن الحمد لله الكفارة ميسرة إطعام عشرة مساكين، كل مسكين له نصف الصاع، كيلو ونصف من قوت البلد تمر أو رز، أو بر، أو كسوة، قميص يجزئه في الصلاة، أو إزار ورداء يجزئانه في الصلاة. نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17287/حكم-من-حلف-ولم-يوف-بيمينه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_782/nour_78221.mp3","categories":["الأيمان والنذور"]},{"id":18332,"question":"أيضًا عن موضوع الطلاق، رسالة بعث بها أخونا عبد الله محمد هلال مصري، ومقيم في جدة، أخونا يقول:في لحظة غضب وانفعال ومشادة مع زوجتي قلت لها: عليّ الطلاق ما أنت ذاهبة إلى المدرسة باكر، وكررت ذلك ثلاث مرات من شدة غضبي، وكان هدفي من ذلك هو منعها من الذهاب إلى المدرسة؛ حيث تعمل مدرسة، ولا أقصد الطلاق أبدًا؛ لأنني أبغضه ولا أعرف أحكامه.في صباح اليوم التالي ألحت عليّ زوجتي بأن من الضروري ذهابها إلى المدرسة؛ لأن ذلك هو أول يوم في العام الدراسي، فقمت بتوصيلها إلى المدرسة، منذ ذلك الوقت وأنا أعيش في قلق نفسي وخوف من الله  لذا أرجو الإفادة عن حكم هذا اليمين، هل هو حلف بغير الله؟ أم يمين طلاق تحرم بموجبه زوجتي عليه؟ أرجو إيضاح ذلك، علمًا بأنني ندمت ندمًا شديدًا، وعزمت على ألا أعود إلى ذلك أبدًا، جزاكم الله خيرًا.","title":"حكم الطلاق بنية منع الزوجة من المدرسة","answer":"الجواب: إذا كان الواقع هو ما ذكره السائل، فهذا الطلاق له حكم اليمين، وعليك كفارتها، وهي إطعام عشرة مساكين، أو كسوتهم، أو عتق رقبة؛ فإن عجزت تصوم ثلاثة أيام، والإطعام يكون نصف صاع لكل واحد، كيلو ونص لكل واحد من التمر أو الأرز أو الحنطة، أو تعشيه أو تغديه، عشرة، أو تكسو العشرة كسوة إزار ورداء، أو قميص، هكذا يجب ولا طلاق عليك، لا يقع الطلاق؛ لأنك لم ترد الطلاق، وإنما أردت منعها كما قلت، وما كان بهذه المثابة، فله حكم اليمين في أصح قولي العلماء. ونوصيك بالحذر من العود إلى ذلك، والتوبة مما حصل والصبر، وفق الله الجميع. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17395/حكم-الطلاق-بنية-منع-الزوجة-من-المدرسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_860/nour_86004.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":18401,"question":"السائلة (ف. أ) تقول: ما حكم من أقسم عدة مرات أن يعمل أشياء فندم وفعلها لما في ذلك من خير، هل تلزمه الكفارة مرة واحدة، أم لكل واحدة كفارة؟","title":"كيفية الكفارة عن أكثر من يمين حنث فيها صاحبها","answer":"الجواب: إذا كان يمينًا واحدة كفارة واحدة قال: والله ما أزور فلان ولا أكلم فلان ولا آكل طعام فلان، ثم فعل شيئًا من هذا؛ كفارة واحدة؛ لأنها يمين واحدة. أما إذا كان كرر أيمان، قال: والله ما أزور فلان هذه واحدة، والله ما أكلم فلان هذه ثنتين، والله ما آكل طعام فلان هذه ثلاث، كل واحدة لها كفارة. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17475/كيفية-الكفارة-عن-اكثر-من-يمين-حنث-فيها-صاحبها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_784/nour_78413.mp3","categories":["الأيمان والنذور"]},{"id":18422,"question":"نعود في بداية هذه الحلقة إلى رسالة المستمع سيد جعفر من السودان، أخونا عرضنا له سؤالًا في حلقة مضت، وفي هذه الحلقة يسأل ويقول: لقد قرأت في كتاب جليل للعلامة الفاضل الشيخ عبد العزيز المحمد السلمان أن الحلف بغير الله شرك أصغر، ولكن بعض الأئمة قالوا: إنه شرك أكبر، ومن فعل ذلك فقد خرج عن الملة؟ أفيدونا بارك الله فيكم.","title":"هل الحلف بغير الله شرك أصغر أم أكبر؟","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فإن الشرك نوعان: أكبر وأصغر، بإجماع المسلمين، قال الله  في الشرك الأكبر: وَلَوْ أَشْرَكُوا لَحَبِطَ عَنْهُمْ مَا كَانُوا يَعْمَلُونَ [الأنعام:88]، وقال سبحانه: وَلَقَدْ أُوحِيَ إِلَيْكَ وَإِلَى الَّذِينَ مِنْ قَبْلِكَ لَئِنْ أَشْرَكْتَ لَيَحْبَطَنَّ عَمَلُكَ وَلَتَكُونَنَّ مِنَ الْخَاسِرِينَ [الزمر:65]، وقال سبحانه: إِنَّ اللَّهَ لا يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ [النساء:48]، فهذه الآيات وأشباهها في الشرك الأكبر، ومنه دعاء الأموات والأصنام والأشجار والأحجار والنجوم والجن والملائكة ونحوهم والاستغاثة بهم، والنذر لهم والذبح لهم ونحو ذلك، هذا من الشرك الأكبر. وهكذا اعتقاد أن هؤلاء يصلحوا للعبادة وإن لم يدعهم، إذا اعتقد أن هؤلاء يدعون من دون الله ويستغاث بهم وأنه لا بأس بذلك فهو شرك أكبر وإن لم يفعل. وهكذا اعتقاد السر في حي من الأحياء أنه ينفع ويضر دون الله، وأنه يصلح لأن يعبد من دون الله ولو كان حيًا، كما يفعله بعض ضلال الصوفية بمشايخهم، هذه وأشباهها من الشرك الأكبر. وهكذا ما يفعله بعض الناس مع الجن يدعوهم أو ينذر لهم أو يذبح لهم خوفًا من شرهم هذا أيضًا من الشرك الأكبر، وهكذا ما يفعله بعض الناس مع الرسل والأنبياء والملائكة يدعوهم ويستغيث بهم وينذر لهم هو من الشرك الأكبر، قال الله : وَلا تَدْعُ مِنْ دُونِ اللَّهِ مَا لا يَنْفَعُكَ وَلا يَضُرُّكَ فَإِنْ فَعَلْتَ فَإِنَّكَ إِذًا مِنَ الظَّالِمِينَ [يونس:106] يعني: المشركين. وقال : وَأَنَّ الْمَسَاجِدَ لِلَّهِ فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن:18]، قال : ذَلِكُمُ اللَّهُ رَبُّكُمْ لَهُ الْمُلْكُ وَالَّذِينَ تَدْعُونَ مِنْ دُونِهِ مَا يَمْلِكُونَ مِنْ قِطْمِيرٍ ۝ إِنْ تَدْعُوهُمْ لا يَسْمَعُوا دُعَاءَكُمْ وَلَوْ سَمِعُوا مَا اسْتَجَابُوا لَكُمْ وَيَوْمَ الْقِيَامَةِ يَكْفُرُونَ بِشِرْكِكُمْ [فاطر:13-14] فسماه شركاً دعوة غير الله، سماها شركًا، وقال سبحانه: وَمَنْ يَدْعُ مَعَ اللَّهِ إِلَهًا آخَرَ لا بُرْهَانَ لَهُ بِهِ فَإِنَّمَا حِسَابُهُ عِنْدَ رَبِّهِ إِنَّهُ لا يُفْلِحُ الْكَافِرُونَ [المؤمنون:117] فسمى دعاة غير الله كفارًا. أما الشرك الأصغر فقد بينه النبي ﷺ في عدة أحاديث، منها حديث محمود بن لبيد عن النبي ﷺ أنه قال عليه الصلاة والسلام: أخوف ما أخاف عليكم الشرك الأصغر، فسئل عنه؟ فقال: الرياء، يقول الله يوم القيامة للمرائين: اذهبوا إلى من كنتم تراءون في الدنيا فانظروا هل تجدون عندهم من جزاء؟، وهذا الحديث صحيح رواه جماعة من أهل العلم بأسانيد صحيحة، فهو يدل على أن الشرك فيه أصغر وأكبر، فالرياء من جنس الشرك الأصغر كونه يقرأ يرائي أو يصلي بعض الصلوات يرائي الناس أو يسبح ويهلل يرائي، أو يأمر بالمعروف وينهى عن المنكر يرائي، يقول النبي ﷺ: من راءى راءى الله به، ومن سمع سمع الله به، وقال جماعة من علماء التفسير: إن قوله تعالى: فَمَنْ كَانَ يَرْجُوا لِقَاءَ رَبِّهِ فَلْيَعْمَلْ عَمَلًا صَالِحًا وَلا يُشْرِكْ بِعِبَادَةِ رَبِّهِ أَحَدًا [الكهف:110] نزلت في المرائين. هذا الرياء إذا وقع من المسلم في بعض الأعمال فهو شرك أصغر، وهكذا إذا عاد المريض أو فعل أي عبادة من العبادات التي يتقرب بها إلى الله فعلها من أجل الرياء أو من أجل السمعة كان شركاً أصغر، أما إذا كان فاسد العقيدة كالمنافقين الذين يعتقدون تكذيب الرسول ﷺ وإنكار ما جاء به من الهدى أو الشك في ذلك ثم يصلون مع الناس ويصومون ويراءونهم بهذا فهذا شرك أكبر وهذا رياء أكبر؛ لأنهم فاسدوا العقيدة، إنما أظهروا ما أظهروا تقية ورياء، فهم كفار كفرًا أكبر لفساد العقيدة؛ كما قال : إِنَّ الْمُنَافِقِينَ يُخَادِعُونَ اللَّهَ وَهُوَ خَادِعُهُمْ وَإِذَا قَامُوا إِلَى الصَّلاةِ قَامُوا كُسَالَى يُرَاءُونَ النَّاسَ وَلا يَذْكُرُونَ اللَّهَ إِلَّا قَلِيلًا ۝ مُذَبْذَبِينَ بَيْنَ ذَلِكَ لا إِلَى هَؤُلاءِ وَلا إِلَى هَؤُلاءِ [النساء:142-143]، عندهم شك وريب وتردد فصاروا كفارًا كفرًا أكبر. وقال في حقهم في الآخرة: إِنَّ الْمُنَافِقِينَ فِي الدَّرْكِ الأَسْفَلِ مِنَ النَّارِ وَلَنْ تَجِدَ لَهُمْ نَصِيرًا [النساء:145] بسبب كفرهم الأكبر واعتقادهم الفاسد، ومن الشرك الأصغر الحلف بغير الله، كما قال النبي ﷺ: من حلف بشيء دون الله فقد أشرك رواه الإمام أحمد في المسند من حديث عمر  بإسناد صحيح، وخرج أبو داود والترمذي من حديث ابن عمر رضي الله عنهما عن النبي ﷺ أنه قال: من حلف بغير الله فقد أشرك -أو كفر- هكذا شك من الراوي، (أو) بمعنى الواو يعني: وقع في الشرك والكفر جميعًا، هذا عند أهل العلم شرك أصغر؛ لأن الرسول ﷺ أقرهم على الحلف بغير الله في أول الإسلام ولم ينهاهم عن ذلك، ثم نهاهم بعد ذلك، فلو كان شركًا أكبر لم يقرهم عليه؛ لأن الله بعثه بإنكاره من حين بعثه في مكة، فلما أقرهم عليه دهرًا من الزمان ثم نهاهم في المدينة بعد ذلك دل على أنه شرك أصغر؛ إذ لو كان أكبر لما أذن فيه أبدًا، بل نهي عنه من أول وهلة. وهكذا قول: ما شاء الله وشاء فلان، أو لولا الله وفلان، هذا أيضًا من الشرك الأصغر؛ لقول النبي ﷺ: لا تقولوا: ما شاء الله وشاء فلان ولكن قولوا: ما شاء الله ثم شاء فلان، ولما جاء في حديث قتيلة عند النسائي \"أن اليهود كانوا يقولون للمسلمين: إنكم تشركون- وفي لفظ: إنكم تنددون- تقولون: ما شاء الله وشاء محمد وتقولون: والكعبة، فأمرهم النبي ﷺ إذا أرادوا أن يحلفوا أن يقولوا: ورب الكعبة، وأن يقولوا: ما شاء الله ثم شاء محمد. وفي لفظ: أن يقولوا: ما شاء الله ثم شئت، وفي لفظ قال لهم: قولوا: ماشاء الله وحده، فهذا كله يدل على أن هذه الأمور من الشرك الأصغر، وأن الكمال أن يقول ما شاء الله وحده فإن قال: ما شاء الله ثم شاء فلان، لولا الله ثم فلان فلا بأس بذلك. وفي حديث الأبرص والأقرع والأعمى في الصحيحين أن الملك الذي جاءهم بعدما عافاهم الله من البرص والقرع والعمى جاءهم يسألهم يقول: لا بلاغ لي اليوم إلا بالله ثم بك فدل على جواز مثل هذه العبارة. لكن لو اعتقد من حلف بغير الله أن هذا المحلوف به يتصرف في الكون أو ينفع ويضر دون الله، أو أن له مثل عظمة الله صار شركًا أكبر، فمن قال من العلماء: إنه شرك أكبر فمراده إذا عظمه كتعظيم الله أو اعتقد فيه أنه يصلح لما يعبد الله به أو أنه ينفع ويضر دون الله أو ما أشبهه من العقائد الباطلة، فإن حلف به على هذا الاعتقاد صار شركًا أكبر. أما إذا جرى على لسانه الحلف بغير الله كعادة جرت عليها جماعته وأهله وبلاده، أو جرى عليها سابقًا هو واعتادها سابقًا ولم يقصد أنه معظم كعظمة الله، أو أنه يتصرف في الكون، أو أنه يصلح أن يعبد من دون الله لم يعتقد هذا الاعتقاد ولكن جرى على لسانه الحلف بغير الله كعادة كثير من الناس فهذا من الشرك الأصغر، ويوجد كثير من الناس اعتادوا هذا البلاء، وقد ينسب لأهل العلم لكن لأن العادة غلبت عليهم يتكلمون بهذا، فتجده يقول: والنبي.. والأمانة.. بالنبي.. بالأمانة مع أنه من طلبة العلم ومن أهل العلم، لكن غلبت على لسانه واعتادها فينسى عند الكلام فيتكلم بها، فهذا كله من المنكر وكله غلط وكله من الشرك الأصغر، والواجب التنبيه على ذلك والتحذير منه وأن لا يتساهل في ذلك. فمن قال: إنه شرك أكبر، فله وجه كما تقدم، ومن قال: إنه شرك أصغر، فهذا هو الأصل أنه شرك أصغر كما قال الشيخ عبد العزيز السلمان، ومن قال: إنه شرك أكبر، كما حكاه السائل عن بعض العلماء، فالظاهر -والله أعلم- ما ذكرنا، يعني: من حلف بغير الله معظمًا له كتعظيم الله، أو معتقدًا فيه أنه يصلح للعبادة أو ينفع ويضر أو ما أشبه ذلك من العقائد الباطلة، والله أعلم. نعم. المقدم: الله أعلم، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17509/هل-الحلف-بغير-الله-شرك-اصغر-ام-اكبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_864/nour_86401.mp3","categories":["الأيمان والنذور","الحلف بغير الله"]},{"id":18423,"question":"المستمع (م. م) من الدمام بعث برسالة يقول فيها: أعرض عليكم مشكلتي والتي تتلخص في أنني عزمت على ترك التدخين ولكن بدلًا من أؤكد كلامي على عزمي بذلك أمام السامع بالحلف بالله كما ينبغي أن يكون عليه المسلم أكدت بالحلف بالحرام، هل يقع الطلاق في هذه الحالة مع العلم أنني صمت ثلاثة أيام وعدت إلى فعل ما عزمت على ترك فعله على اعتقادي أن الحلف حلف يمين وليس بالطلاق، وإنما نطقت بالحرام للتأكيد للسامع فقط، هل يلزم كفارة في هذه الحالة؟","title":"أكدت الحلف بالحرام على ترك التدخين، هل يقع الطلاق؟","answer":"الجواب: نعم، إذا كنت قصدت منع نفسك من شرب الدخان بالتحريم أو باليمين أو بالطلاق، قلت: علي الحرام وعلي الطلاق أني ما أشرب هذا الدخان، أني لا أعود إليه، ومقصودك منع نفسك والتأكيد على نفسك، ليس قصدك تحريم زوجتك إن فعلت، وليس قصدك طلاقها إن فعلت وإنما أردت التأكيد على نفسك وإلزامها بالكف عن التدخين، فهذا حكمه حكم اليمين وعليك كفارتها وهي إطعام عشرة مساكين أو كسوتهم، ولا يجزئ الصيام إذا كنت قادر على الطعام أو الكسوة لا يجزئ الصيام؛ لأن الصيام إنما يجزئ مع العجز في حق من عجز عن الطعام أو الكسوة أو العتق، أما من قدر على واحد من الثلاثة، قدر على أن يطعم عشرة مساكين، أو يكسوهم، أو يعتق رقبة فإنه يلزمه واحد من هذه الثلاثة، فإن عجز عنها كلها صام ثلاثة أيام كما نص عليه القرآن الكريم في سورة المائدة. أما إن كنت أردت تحريم زوجتك إن فعلت أو أردت طلاقها إن فعلت فإنها تحرم عليك وعليك كفارة الظهار وهي عتق رقبة مع القدرة، فإن عجزت تصوم شهرين متتابعين ستين يومًا، فإن عجزت تطعم ستين مسكينًا ثلاثين صاعًا كل صاع بين اثنين من قوت البلد من تمر أو أرز أو غيرهما، كل صاع يكون بين اثنين، والصاع نحو ثلاثة كيلو تقريبًا. وهكذا إذا أردت الطلاق، إذا قلت: علي الطلاق وأردت طلاقها إن دخنت يكون طلقة واحدة، وعليك أن تراجعها إذا رجعت إلى التدخين إذا كنت لم تطلقها قبل هذا طلقتين فإنه يحل لك مراجعتها إذا كنت أردت إيقاع الطلاق، فتقول: اشهد يا فلان وفلان أني راجعت زوجتي، هذا هو السنة؛ تشهد اثنين أنك راجعت زوجتك بعد أن باشرت الدخان. والواجب عليك يا أخي تقوى الله، وأن تحذر التدخين لمضرته العظيمة وخبثه الكثير، والله سبحانه إنما أباح لعباده الطيبات، كما قال : يَسْأَلُونَكَ مَاذَا أُحِلَّ لَهُمْ قُلْ أُحِلَّ لَكُمُ الطَّيِّبَاتُ [المائدة:4]، هكذا في سورة المائدة، وقال سبحانه في سورة الأعراف في وصف النبي عليه الصلاة والسلام قال: وَيُحِلُّ لَهُمُ الطَّيِّبَاتِ وَيُحَرِّمُ عَلَيْهِمُ الْخَبَائِثَ [الأعراف:157]. ولا شك أن التدخين أمر منكر وأن الدخان من الخبائث، وقد قرر الأطباء العارفون به وكل من استعمله أنه مضر وخبيث، فعليك يا أخي أن تتقي الله وأن تحذر شر هذا البلاء، وأن تبتعد عنه، وأن تعزم عزمًا صادقًا عزم الرجال أن لا تعود إليه، رزقنا الله وإياك التوفيق والهداية.","link":"https://binbaz.org.sa/fatwas/17528/اكدت-الحلف-بالحرام-على-ترك-التدخين-هل-يقع-الطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_864/nour_86404.mp3","categories":["الظهار","الطلاق","الأيمان والنذور"]},{"id":18437,"question":"على بركة الله نبدأ برسالة السائلة أم معاذ من حائل تقول:سماحة الشيخ! والدي عليه دين لشخص، ونذر لله بأنه إذا قضى من هذا الدين أن يذبح ناقة، وكان في مدينة، ثم انتقل منها، وكان نذره في المدينة التي ارتحل منها، وحيث أنه لا يسكنها إلا قلة من الناس.و هل يقضي هذا النذر في المدينة الذي نذر فيها أم التي يسكن فيها الآن، مع العلم بأنه خصص لذلك النذر في المدينة التي ارتحل منها سماحة الشيخ؟","title":"الواجب الوفاء بالنذر على نية الناذر","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:\nفعلى هذا الناذر أن يوفي بنذره؛ يقول النبي ﷺ: من نذر أن يطيع الله فليطع، وإذا كان عين أن الناقة لفقراء تلك القرية يذبح فيها، يذبح الناقة هناك، ويقسمها على فقراء القرية تنفيذًا لنذره. أما إذا كان ما عين جهة معينة، نذر ولم يعين جهة معينة؛ فإنه يوزعها في أي مكان، على الفقراء والمساكين كما نذر، وإن كان نيته أنه ينحرها، ويجمع عليها من شاء من أهل القرية من الفقراء وغيرهم، فهو على نيته، الأعمال بالنيات. نعم.","link":"https://binbaz.org.sa/fatwas/17521/الواجب-الوفاء-بالنذر-على-نية-الناذر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_785/nour_78501.mp3","categories":["الأيمان والنذور"]},{"id":18439,"question":"سماحة الشيخ! كثرة النذور من بعض الناس، ثم ترددهم فيها ويستصعبون ذلك هل من كلمة لمثل هؤلاء يا سماحة الشيخ؟","title":"كلمة توجيهية إلى الذين يكثرون النذور","answer":"الجواب: الرسول ﷺ نهى عن النذر، ولا ينبغي لأحد من الناس أن ينذروا؛ لقول النبي ﷺ: لا تنذروا فإن النذر لا يرد من قدر الله شيئًا، وإنما يستخرج به من البخيل، فلا ينبغي للناس النذر، وينهون عن النذر، لكن من نذر أن يطيع الله وجب عليه الوفاء، ويمدح بذلك قال الله تعالى: يُوفُونَ بِالنَّذْرِ وَيَخَافُونَ يَوْمًا كَانَ شَرُّهُ مُسْتَطِيرًا[الإنسان:7]، ويقول سبحانه: وَمَا أَنفَقْتُمْ مِنْ نَفَقَةٍ أَوْ نَذَرْتُمْ مِنْ نَذْرٍ فَإِنَّ اللَّهَ يَعْلَمُهُ[البقرة:270]. فعلى من نذر طاعة أن يوفي بالنذر، كأن يقول: لله عليه أن يصلي كذا، أن يصوم كذا، أن يتصدق بكذا، عليه أن يوفي بالنذر، لكن لا ينبغي له أن ينذر، ينهى عن النذر أولًا، فإذا وقع النذر وهو طاعة وجب عليه الوفاء. نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17524/كلمة-توجيهية-الى-الذين-يكثرون-النذور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_785/nour_78502.mp3","categories":["الأيمان والنذور"]},{"id":18450,"question":"رسالة بعث بها أحد المستمعين من السودان، يقول: (ع. ع) سوداني ومقيم بالمجمعة، أخونا كتب رسالته بلهجته العامية، فهمت منها أنه حلف بالحرام حتى لا تذهب زوجته إلى بيت أمها، فذهبت وتركت حرامه، ويسأل عن الحكم؟","title":"حكم الحنث في الحلف بالحرام","answer":"الجواب: هذا يختلف بحسب نيته، فإذا حلف، فقال: عليه الحرام أن لا تذهبي إلى بيت أمك أو إلى بيت أخيك أو إلى بيت آل فلان وقصده تحريمها، قصده من ذلك أنها متى ذهبت فهي محرمة، فهذا حكمه حكم الظهار في أصح أقوال أهل العلم، وعليه كفارة الظهار إذا خالفته وذهبت وهي عتق رقبة مؤمنة، فإن لم يجد فصيام شهرين متتابعين، فإن لم يستطع فإطعام ستين مسكينًا لكل مسكين نصف صاع من قوت البلد من تمر أو أرز أو غيرهما قبل أن يمسها؛ لأن هذا ظهار. أما إن أراد منعها فقط لم يرد تحريمها إنما أراد تخويفها وتهديدها ومنعها من الذهاب ولم يرد تحريمها إن ذهبت فهذا له حكم اليمين في أصح الأقوال وهي إطعام عشرة مساكين أو كسوتهم أو عتق رقبة، فإن عجز عن هذه الثلاث صام ثلاثة أيام كما جاء به النص القرآني في قوله سبحانه: لا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِنْ يُؤَاخِذُكُمْ بِمَا عَقَّدْتُمُ الأَيْمَانَ فَكَفَّارَتُهُ إِطْعَامُ عَشَرَةِ مَسَاكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍ فَمَنْ لَمْ يَجِدْ فَصِيَامُ ثَلاثَةِ أَيَّامٍ ذَلِكَ كَفَّارَةُ أَيْمَانِكُمْ إِذَا حَلَفْتُمْ وَاحْفَظُوا أَيْمَانَكُمْ [المائدة:89] الآية. فالله أرشدنا إلى حفظ الأيمان وبين لنا كفارة اليمين، والتحريم لما أحل الله من طعام أو شراب أو لباس أو نحو ذلك مثل اليمين، وهكذا تحريم المرأة إذا قصد منعها ولم يقصد تحريمها، إنما قصد منعها حكمه حكم تحريم الطعام والشراب، فيه كفارة اليمين، والله ولي التوفيق. نعم.","link":"https://binbaz.org.sa/fatwas/17532/حكم-الحنث-في-الحلف-بالحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_865/nour_86501.mp3","categories":["الأيمان والنذور"]},{"id":18454,"question":"رسالة بعث بها أحد المستمعين من السودان، يقول: (ع. ع) سوداني ومقيم بالمجمعة، أخونا كتب رسالته بلهجته العامية، فهمت منها أنه حلف بالحرام حتى لا تذهب زوجته إلى بيت أمها، فذهبت وتركت حرامه، ويسأل عن الحكم؟","title":"حكم الحنث في الحلف بالحرام","answer":"الجواب: هذا يختلف بحسب نيته، فإذا حلف، فقال: عليه الحرام أن لا تذهبي إلى بيت أمك أو إلى بيت أخيك أو إلى بيت آل فلان وقصده تحريمها، قصده من ذلك أنها متى ذهبت فهي محرمة، فهذا حكمه حكم الظهار في أصح أقوال أهل العلم، وعليه كفارة الظهار إذا خالفته وذهبت وهي عتق رقبة مؤمنة، فإن لم يجد فصيام شهرين متتابعين، فإن لم يستطع فإطعام ستين مسكينًا لكل مسكين نصف صاع من قوت البلد من تمر أو أرز أو غيرهما قبل أن يمسها؛ لأن هذا ظهار. أما إن أراد منعها فقط لم يرد تحريمها إنما أراد تخويفها وتهديدها ومنعها من الذهاب ولم يرد تحريمها إن ذهبت فهذا له حكم اليمين في أصح الأقوال وهي إطعام عشرة مساكين أو كسوتهم أو عتق رقبة، فإن عجز عن هذه الثلاث صام ثلاثة أيام كما جاء به النص القرآني في قوله سبحانه: لا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِنْ يُؤَاخِذُكُمْ بِمَا عَقَّدْتُمُ الأَيْمَانَ فَكَفَّارَتُهُ إِطْعَامُ عَشَرَةِ مَسَاكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍ فَمَنْ لَمْ يَجِدْ فَصِيَامُ ثَلاثَةِ أَيَّامٍ ذَلِكَ كَفَّارَةُ أَيْمَانِكُمْ إِذَا حَلَفْتُمْ وَاحْفَظُوا أَيْمَانَكُمْ [المائدة:89] الآية. فالله أرشدنا إلى حفظ الأيمان وبين لنا كفارة اليمين، والتحريم لما أحل الله من طعام أو شراب أو لباس أو نحو ذلك مثل اليمين، وهكذا تحريم المرأة إذا قصد منعها ولم يقصد تحريمها، إنما قصد منعها حكمه حكم تحريم الطعام والشراب، فيه كفارة اليمين، والله ولي التوفيق. نعم.","link":"https://binbaz.org.sa/fatwas/17532/حكم-الحنث-في-الحلف-بالحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_865/nour_86501.mp3","categories":["الأيمان والنذور"]},{"id":18507,"question":"نعود في بداية هذه الحلقة إلى رسالة المستمع بدوي سرحان، أخونا عرضنا جزءًا من أسئلته في حلقات مضت، وفي هذه الحلقة يسأل ويقول: لدينا عادة مستجدة وهي الحلف بالذمة، أو بالشباب، بدل الحلف بالله، فهل هذا جائز؟","title":"حكم الحلف بالذمة والشباب","answer":"الجواب: بسم الله الرحمن الرحيم. الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فالحلف بغير الله لا يجوز؛ لقول النبي ﷺ: من كان حالفًا فليحلف بالله أو ليصمت وقال أيضًا عليه الصلاة والسلام: من كان حالفًا فلا يحلف إلا بالله أو ليصمت، وقال أيضًا عليه الصلاة والسلام: من حلف بشيء دون الله فقد أشرك خرجه الإمام أحمد رحمه الله في المسند بإسناد صحيح عن عمر . وخرج أبو داود والترمذي رحمهما الله بإسناد صحيح عن ابن عمر رضي الله عنهما عن النبي ﷺ أنه قال: من حلف بغير الله فقد كفر أو أشرك وهذا يحتمل أنه شك من الراوي هل قال النبي ﷺ كفر أو قال أشرك، أو المعنى أنه حصل له هذا وهذا وتكون (أو) بمعنى الواو، يعني: كفر وأشرك. وبهذا يعلم أن الحلف بغير الله أمر لا يجوز مطلقًا، لا بالأنبياء ولا بالملائكة ولا بالكعبة ولا بالأمانة ولا بذمة فلان ولا رأس فلان ولا شرف فلان ولا حياة فلان.. ولا غير ذلك، فإذا قال: بذمتي أو برأسي أو بشرفي أو بحياتي أو حياة فلان.. أو ما أشبه ذلك كل هذا لا يجوز، أو قال: بالأمانة أو بالنبي أو بالكعبة كل ذلك لا يجوز، وفي الحديث الصحيح يقول ﷺ من حلف بالأمانة فليس منا. وبهذا يعلم أن الواجب على المسلمين الحذر من هذه الأيمان الباطلة وأن يعود نفسه الحلف بالله وحده  وأن يحذر من الحلف بغيره  كائنًا من كان، وهكذا لا يقول: ما شاء الله وشاء فلان، ولا يقول: لولا الله وفلان، ولا يقول: هذا من الله ومن فلان بل يأتي بـ(ثم) يقول: ما شاء الله ثم شاء فلان، إذا كان له تسبب الشخص بأن دفع عنك شرًا وحماك من شر تقول: ما شاء الله ثم شاء فلان جرى كذا وكذا، لولا الله ثم فلان، لأنه فعل معك معروف، هذا من الله ثم من فلان لا بأس، أما أن تقول: لولا الله وفلان أو هذا من الله وفلان، أو ما شاء الله وشاء فلان هذا لا يجوز، بل هو من المحرمات الشركية. فالواجب الحذر من هذه الكلمات ومن الحلف بغير الله ؛ تعظيمًا لله وطاعة لأمره وأمر رسوله عليه الصلاة والسلام ووقوفًا عند حدود الله . نعم.","link":"https://binbaz.org.sa/fatwas/17602/حكم-الحلف-بالذمة-والشباب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_868/nour_86801.mp3","categories":["الطلاق","الأيمان والنذور","الحلف بغير الله"]},{"id":18515,"question":"يقول هذا السائل أبو محمد: لقد حلفت في مرة من الأيام، ولم أتلفظ بهذا الأمر، وإنما بقلبي، أي: أقسمت بقلبي، ولم أقسم بلساني، وقد حنثت في هذا القسم، فهل علي كفارة؟","title":"حكم من حلف في قلبه وحنث","answer":"الجواب: قسم القلب لا يترتب عليه شيء، إنما يترتب على قسم اللسان، فإذا نوى بقلبه ما يصير شيء حتى يقسم باللسان، قسم اللسان هو المعتبر، نعم.","link":"https://binbaz.org.sa/fatwas/17615/حكم-من-حلف-في-قلبه-وحنث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_786/nour_78615.mp3","categories":["الأيمان والنذور"]},{"id":18568,"question":"تقول الأخت السائلة من جدة: إذا عاهدت الله  في ذنب ألا أعود له، ثم عدت، ثم تبت مرة أخرى، فما الحكم في ذلك؟ علمًا بأنني سمعت فتوى بأن فيه كفارة يمين، فصمت ثلاثة أيام، ولكنني خلال صيامي كنت أسمع أناشيد الأفراح بالدفوف، فما الحكم في ذلك؟ وما حكم سماع الأشرطة في الأناشيد الإسلامية؟","title":"حكم من عاهد الله على ترك ذنب ثم فعله","answer":"الجواب: الإنسان إذا عاهد الله يوفي بعهده، الله يقول: وَأَوْفُوا بِعَهْدِ اللَّهِ إِذَا عَاهَدْتُمْ [النحل:91] إذا عاهد الله أن يبتعد عن الذنوب، إذا عاهد الله أن يبر والديه، إذا عاهد الله أن يصل رحمه، إذا عاهد الله ألا يؤذي جيرانه يستمر يلزم العهد، وإذا أخل بالعهد فقد خاطر بنفسه، فعليه التوبة إلى الله والاستغفار والندم، وعدم العود، هذا هو المشروع، وإن كفر عن ذلك كفارة يمين فلعله حسن؛ لأن بعض أهل العلم قال ذلك، فالأمر في هذا واسع، لكن المهم التوبة والاستغفار، يعني: المهم أنه إذا عاهد ونقض يستغفر الله ويتوب إليه ولا يعد، هذا هو الواجب على المؤمن، سواء استغفر لهم جميعًا أو لكل واحد على حدة، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/17682/حكم-من-عاهد-الله-على-ترك-ذنب-ثم-فعله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_918/nour_91802.mp3","categories":["الأيمان والنذور","الرقائق"]},{"id":18571,"question":"مستمع يقول: (محمد . م) من جدة يسأل سماحتكم فيقول: ما رأيكم -حفظكم الله- في الحلف على المصحف هل يعتبر يمينًا؟ وهل إذا حلف صادقًا يكون آثمًا؟ وإذا حلف كاذبًا كذلك؟وجهونا جزاكم الله خيرًا.","title":"حكم الحلف بالمصحف","answer":"الجواب: إذا حلف بالمصحف قصده القرآن بكلام الله فلا بأس؛ لأن القرآن كلام الله، فإذا قال: وعزة الله، أو وكلام الله، أو بالمصحف، وقصده القرآن مقصوده كلام الله  فهذا يمين لا بأس به، هذه يمين لا بأس بها، ولا حرج فيها، والحمد لله، مثلما لو قال: وعزة الله، وعلم الله، وكلام الله لا بأس، يحلف بصفة من صفات الله، كما لو قال: والرحمن والرحيم، والعزيز، والحكيم، فهكذا إذا قال: وعزة الله، ورحمة الله، وعلم الله، وكلام الله لا بأس، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17686/حكم-الحلف-بالمصحف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_734/nour_73404.mp3","categories":["الأيمان والنذور"]},{"id":18585,"question":"رسالة وصلت إلى البرنامج من المخواه، وباعثها أخونا أحمد علي العمري، أخونا يسأل ويقول: أنا رجل أمي لا أقرأ ولا أكتب، وعندي ولد يدرس في الصف الرابع لا يذاكر، وهددته بأن قلت له: عليّ الطلاق من ظهر أمك إنك لو ما تدرس إنني لأفعل بك كذا وكذا، وزعلت أمه من كلمة الطلاق، ونرجو أن تفتونا في ذلك، جزاكم الله خيرًا.","title":"حكم طلاق من هدد ابنه بطلاق أمه إذا لم يطعه","answer":"الجواب: إذا كان المقصود من هذا الطلاق حث ولدك على المذاكرة، والعناية بدروسه، وليس قصدك تطليق أمه وفراقها، وإنما قصدك تخويفه وتخويف أمه حتى يجتهدا جميعًا فيما يتعلق بالدروس، وحتى تحرص أمه عليه؛ فلا بأس عليك بذلك، وعليك كفارة يمين إذا لم يحصل منه المطلوب، إذا تساهل ولم يقدر كلامك ولم يجتهد؛ فعليك كفارة اليمين، ولا طلاق عليك، لا يقع عليها شيء على الصحيح من أقوال العلماء. أما إذا كان مقصودك فراقها إن لم يجتهد الولد ناويًا فراقها، أنك تفارقها إذا لم يجتهد ولدها؛ لأنك تظن فيها أنها تتساهل معه، وأنها لا تشجعه، فإذا كنت أردت ذلك؛ فإنه يقع عليها طلقة إذا تساهل ولم يبال بكلامك؛ يقع عليها طلقة واحدة، وتراجعها في الحال، ولا بأس عليك، هذا إذا أردت طلاقها إذا كنت أردت الطلاق. أما إذا كنت أردت التخويف والتحذير فقط، فهذه الكلمة في حكم اليمين، وعليك كفارتها في أصح أقوال أهل العلم: وهي إطعام عشرة مساكين، أو كسوتهم، أو تحرير رقبة، فإن عجزت تصوم ثلاثة أيام، هذه كفارة اليمين. ونوصيك بعدم العجلة في الأمور، وعدم استعمال الطلاق، بل تحرضه وتوصيه بالكلام الطيب، وتؤدبه إذا رأيت تأديبه بالضرب الخفيف، أما الطلاق فاتركه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17742/حكم-طلاق-من-هدد-ابنه-بطلاق-امه-اذا-لم-يطعه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_871/nour_87105.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":18665,"question":"نعود في بداية هذه الحلقة إلى رسالة الأخت فتاة القدس المقيمة في المملكة، أختنا عرضنا جزءًا من أسئلتها في حلقة مضت، وفي هذه الحلقة لها سؤال واحد تقول فيه: إن والدتي قد أنذرت منذ زمن بعيد نذرًا، والحمد لله قد أعانها الله على الوفاء به، وهي أن تذبح ذبيحة إذا شفى الله زوجها -الذي هو والدي- والحمد لله قد شفاه الله، وسؤالها: هو أنها وزعت كل الذبيحة على مستحقيها، ولكن أخذت منها جزءًا، وهو ما يسمى المعلاق، الذي هو البلعوم والقلب والرئتين، فهل عليها إثم في ذلك؟أفيدونا، جزاكم الله خيرًا.","title":"حكم الأخذ من المنذور به","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فإن كانت نذرت توزيعها على الفقراء، فإنه يقضى عن هذا الشيء، تشترين من تركتها ما يقابل هذا الجزء الذي أخذت، وتتصدقين به على بعض الفقراء، والحمد لله. أما إن كانت نيتها أن توزع على الفقراء وأن تأكل منها بعض الشيء، فليس عليها شيء؛ لقوله -عليه الصلاة والسلام-: إنما الأعمال بالنيات، وإنما لكل امرئ ما نوى فإن كنت لا تعلمين نيتها، ولا تعرفين نيتها، فالأحوط لك أن تشتري ما يقابل هذا الشيء الذي أخذته، وتصدقي به عنها، إبراء للذمة، وحرصًا على سلامتها من التبعة. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17776/حكم-الاخذ-من-المنذور-به","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_920/nour_92001.mp3","categories":["الأيمان والنذور"]},{"id":18704,"question":"بعد هذا رسالة وصلت إلى البرنامج من المستمع علي أحمد رحمة الله، أخونا علي له قضية يقول فيها: تخاصم رجلان، وأراد الناس أن يصلحوا بينهما، فحلف أحدهما بالطلاق ثلاثًا أن لا يصالح الثاني.وبعد فترة خفت ثورة الغضب، وأراد مصالحة صاحبه، وفعلًا تم الصلح بينهما، فماذا عليه أن يفعل؟ وهل زوجته محرمة عليه؟ وإذا قال: علي الطلاق، وكان يقصد واحدة -أي: طلقة واحدة- ولم تسبقها أي طلقة قبل ذلك، فماذا يفعل؟جزاكم الله خيرًا.","title":"من حلف بالطلاق ثم حنث فهو بحسب نيته","answer":"الجواب: هذا فيه تفصيل: إن كان أراد المنع؛ فحكمه حكم اليمين،  الامتناع من المصالحة، وليس قصده إيقاع الطلاق، إنما قصد الامتناع من المصالحة فقط، فهذا حكمه حكم اليمين؛ وعليه كفارة يمين. أما إن كان أراد إيقاع الطلاق إن صالح؛ فإنه يقع به طلقة واحدة؛ لهذه المصالحة التي أراد بها إيقاع الطلاق، إذا كان أراد أنه إن صالح صاحبه، فإنه يقع عليه الطلاق، فإنه يقع الطلاق. الأحسن أن يسأل المحكمة، أو يتصل بنا مع ولي زوجته؛ حتى ينظر في الأمر على بصيرة، وإلا فهذا هو التفصيل، نعم، هذا هو التفصيل في حقه، نعم. المقدم: جزاكم الله خيرًا. الشيخ: نعم.","link":"https://binbaz.org.sa/fatwas/17809/من-حلف-بالطلاق-ثم-حنث-فهو-بحسب-نيته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_735/nour_73515.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":18758,"question":"يقول هذا السائل ياسر سليمان من محافظة البلقاء من الأردن، يقول في سؤاله: عندما يقوم الشخص بالنذر بالذبح، وذلك بذبح شاة من الماعز، هل ينطبق عليها ما ينطبق على الأضحية، وخاصة في العمر والشروط المتوفرة فيها؟","title":"حكم توفر شروط الأضحية في نذر الذبيحة","answer":"الجواب: نعم إذا نذر أن يذبح شاة أو بقرة أو ناقة يعتبر فيها ما يعتبر في الأضحية، وعليه أن يتصدق بها على الفقراء، لا يأكل منها شيئًا، النذر لا يأكل منه شيء، يتصدق بالمنذور على الفقراء إلا أن يكون له نية أن هذه الشاة يذبحها، ويجمع عليها جيرانه، وأهل بيته؛ فهو على نيته، وإلا فإذا كان ما له نية فهذه الشاة، أو هذه البقرة، أو هذا البعير يذبح، ويعطاها الفقراء والمساكين؛ لقول النبي ﷺ: من نذر أن يطيع الله فليطعه، ومن نذر أن يعصي الله فلا يعصه والمطلق يحمل على الشيء المشروع، وهو المشروع الذي يجزي في الأضحية؛ البقرة لها سنتان، والضأن ستة أشهر، والإبل ثنية قد تم لها خمس سنين، يعني: تصير ثنية. فالحاصل: أنها مثل الضحية يعمل فيها مثل الضحية ما يذبح إلا مسنة إلا إذا كان من الضأن من ضأن الشاة يذبح من الضأن ما تم له ستة أشهر، وإن كان من الماعز ما تم له سنة، وإن كان من البقر ما تم له سنتان، ومن الإبل ما تم له خمس سنين كالضحية، ثم هذا المذبوح يعطاها الفقراء، يتصدق به على الفقراء إلا إذا كان له نية أن هذا المذبوح نواه أنه يجمع عليه أهل بيته، أو يجمع عليه جيرانه أو أقاربه فهو على نيته؛ لقوله ﷺ: إنما الأعمال بالنيات، وإنما لكل امرئ ما نوى نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17888/حكم-توفر-شروط-الاضحية-في-نذر-الذبيحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_790/nour_79014.mp3","categories":["الأيمان والنذور"]},{"id":18774,"question":"هذا سائل للبرنامج أرسل بهذه الرسالة، وضمنها مجموعة من الأسئلة، محمد الطيب سوداني، يقول في هذا  ما حكم الذي يحلف بالطلاق في البيع والشراء، وهو يعلم بأنه كاذب ليروج سلعته؟وجزاكم الله خيرًا.","title":"حكم ترويج السلع بالأيمان الكاذبة","answer":"الجواب: حكمه أنه مجرم ظالم لنفسه عاصٍ، سواءً حلف بالطلاق، أو باليمين بالله، أو بغير ذلك، وهو كاذب قد خان الأمانة، فالواجب عليه التوبة إلى الله من ذلك، فالكذب محرم في البيع والشراء، وإن لم يطلق، وإن لم يحلف، فإذا أكد بالحلف والطلاق صار أشد في الإثم، نعوذ بالله. فالواجب عليه التوبة إلى الله من ذلك، والحذر من العود إلى هذا، يقول النبي ﷺ في البيعان: إن صدقا وبينا بورك لهما في بيعهما، وإن كتما وكذبا محقت بركة بيعهما ويقول ﷺ: ثلاث لا يكلمهم الله، ولا ينظر إليهم يوم القيامة، ولا يزكيهم، ولهم عذاب أليم -وذكر منهم- الرجل يبيع السلعة بعد العصر، ويقول: أعطي بها كذا وكذا، وهو كاذب نسأل الله العافية، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17902/حكم-ترويج-السلع-بالايمان-الكاذبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_791/nour_79108.mp3","categories":["الأيمان والنذور","البيوع","نصائح وتوجيهات"]},{"id":18803,"question":"أخونا في سؤاله الأخير يسأل ويقول: تشاجرت مع زوجتي، وقلت لها بعصبية: علي الطلاق بالثلاثة ما أنت ذاهبة إلى العمل على الإطلاق، وبالفعل ثاني يوم ما ذهبت إلى العمل، وذهبت أنا إلى عملها؛ لكي أقدم لها استقالة؛ فرفض المسؤولون، وعادت إلى العمل، ماذا أفعل؟جزاكم الله خيرًا.","title":"حكم الحلف بالطلاق ثلاث بلفظ واحد","answer":"الجواب: هذا فيه تفصيل يا أخي: إن كان المقصود من كلامك هذا منعها من العمل، وليس قصدك إيقاع الطلاق، وإنما أردت تهديدها وتخويفها لعلها تستجيب؛ فعليك كفارة يمين، ويكون هذا الطلاق في حكم اليمين في أصح قولي العلماء، كما أفتى بذلك جماعة من أهل العلم منهم: شيخ الإسلام ابن تيمية -رحمه الله- وتلميذه العلامة ابن القيم -رحمه الله- وجماعة من أهل العلم. هذا إذا كان قصدك منعها وتهديدها وتخويفها، ثم رجعت عن ذلك ورأيت أن تسمح لها؛ فلا بأس وعليك كفارة يمين، وهي إطعام عشرة مساكين، أو كسوتهم، أو تحرير رقبة، فمن لم يجد فصيام ثلاثة أيام -كما بينه الله في سورة المائدة- وإطعام المساكين: هو أن يعطى كل واحد نصف صاع من قوت البلد من تمر أو أرز، يعني: كيلو ونصف تقريبًا، أو كسوة تجزئهم في الصلاة كإزار ورداء أو قميص، أو إعتاق رقبة كما بينه الله . أما إن كنت قصدت إيقاع الطلاق، يعني: نيتك إيقاع الطلاق، أو ناو هذا وهذا: قصدت منعها وقصدت إيقاع الطلاق جميعًا؛ فإنه يقع عليها بهذا طلقة على الصحيح، ولو قلت بالثلاث يقع طلقة واحدة؛ لأن الطلاق بالثلاث بكلمة واحدة ولفظ واحد يعتبر طلقة واحدة في أصح قولي أهل العلم؛ لأنه ثبت من حديث ابن عباس -رضي الله عنهما- عن النبي ﷺ أنه جعل الطلاق الثلاث واحدة لفظ ابن عباس قال: \"كان الطلاق على عهد النبي ﷺ وعهد الصديق أبي بكر وأول خلافة عمر طلاق الثلاث بواحدة\"، وفي لفظ سئل: \"ألم تكن الثلاث تجعل واحدة في عهد النبي ﷺ وعهد أبي بكر وفي أول خلافة عمر؟ قال: بلى\" يعني: ابن عباس -رضي الله عنهما-. فالمقصود: أنه أخبر ابن عباس أن الطلاق كان يجعل واحدة في عهد النبي ﷺ، يعني: الطلاق بالثلاث بكلمة واحدة يجعل واحدة في عهد الصديق ، ثم في عهد عمر ، كما كان في عهد النبي ﷺ، ثم رأى عمر إمضاء الثلاث ولو بكلمة واحدة، فأمضاها  وأرضاه ردعًا للناس عن التساهل بالطلاق. فالحاصل: أنك إذا كنت أردت الطلاق أو أردت الأمرين: الطلاق والمنع جميعًا، ثم سمحت لها أو عصتك وذهبت إلى العمل؛ فإنه يقع عليها طلقة واحدة بهذا، ولك مراجعتها ما دامت في العدة، إذا كنت لم تطلقها طلقتين قبل ذلك، أما إن كنت طلقتها طلقتين قبل ذلك تكون هذه هي الأخيرة، ولا تحل إلا بعد زوج، بعد زوج شرعي، وبعد وطئه لها، ثم فراقه لها بموت أو طلاق، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17965/حكم-الحلف-بالطلاق-ثلاث-بلفظ-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_877/nour_87708.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":18804,"question":"يقول السائل: نسمع عن كفارة اليمين وهل هي بالترتيب؟ ومن لم يستطع إخراج هذه الكفارة -سماحة الشيخ- هل تسقط عنه؟","title":"التخيير والترتيب في كفارة اليمين","answer":"الجواب: كفارة اليمين فيها الترتيب، وفيها التخيير جميعًا، التخيير بين ثلاثة، وهي إطعام عشرة مساكين، أو كسوتهم، أو تحرير رقبة؛ هذه مخيرة، إذا حنث في يمينه إن شاء أطعم عشرة مساكين لكل مسكين نصف صاع كيلو ونص تقريبًا، أو كساهم كل واحد يعطيه قميصًا، أو يعطيه إزارًا ورداء، أو يعتق رقبة هو مخير. فإن عجز عن هذه الثلاثة يصوم ثلاثة أيام لقوله -جل وعلا- في سورة المائدة: وَلَكِنْ يُؤَاخِذُكُمْ بِمَا عَقَّدْتُمُ الأَيْمَانَ فَكَفَّارَتُهُ إِطْعَامُ عَشَرَةِ مَسَاكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍ فَمَنْ لَمْ يَجِدْ فَصِيَامُ ثَلاثَةِ أَيَّامٍ ذَلِكَ كَفَّارَةُ أَيْمَانِكُمْ إِذَا حَلَفْتُمْ وَاحْفَظُوا أَيْمَانَكُمْ[المائدة:89] فبيَّن سبحانه أنه مخير في الثلاث بـ(أو) فإذا عجز عنها انتقل إلى الصوم، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17935/التخيير-والترتيب-في-كفارة-اليمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_791/nour_79117.mp3","categories":["الأيمان والنذور"]},{"id":18848,"question":"إذا رجل حلف يمينًا بالله، أو يمين طلاق، وهو في حالة غضب، فهل يكتب عليه هذه اليمين؟ وهل من الواجب عليه دفع الفدية؟","title":"حكم اليمين بالطلاق وغيره أثناء الغضب","answer":"الجواب: هذا مقام تفصيل يحتاج إلى تفصيل وعناية، فاليمين ضابطها: أن يعلق الطلاق أو التحريم على شرط يقصد منه المنع أو الحث أو التصديق أو التكذيب، هذه يقال له يمين، كأن يقول: عليه الطلاق إن كلم فلانًا، يقصد منع نفسه من كلامه، أو يقول: عليه الطلاق إن لم يزر فلانًا، يقصد حث نفسه على زيارته، أو يقول: عليه الطلاق إن فلانًا قد مات، يقصد أنه يصدق في ذلك، حتى يصدق، أو عليه الطلاق أن هذا الشيء لم يقع حتى يصدق أنه لم يقع. فالحاصل: أن التعليق إنما يكون يمينًا إذا كان لقصد الحث، أو المنع، أو التصديق، أو التكذيب، فهذا إذا كان هذا قصد المتكلم يكون حكمها حكم اليمين على الصحيح، ويكفي كفارة اليمين في ذلك، ولا يقع الطلاق، ولا التحريم بهذه النية. أما إذا كان المقصود التعليق فقط، فهذا يقال له: تعليق، ولا يقال له يمين، كأن يقول: إذا دخل رمضان فزوجته طالق، فهذا يسمى تعليق إذا دخل رمضان طلقت، ليس بيمين، وكأن يقول: إذا وضعت الحمل فهي طالق، أو يقول: إذا دخل شهر ذي الحجة فهي طالق، وما أشبه ذلك من التعليقات التي ليس فيها حث ولا منع ولا تصديق ولا تكذيب، إنما هي تعليقات محضة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17974/حكم-اليمين-بالطلاق-وغيره-اثناء-الغضب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_921/nour_92113.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":18858,"question":"ننتقل إلى مواضع أخرى ورسائل أخرى أيضًا، رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول: حماد عبد الرحمن الشواف من الدوادمي.أخونا بعث برسالة مطولة أيضًا بعض الشيء ويقول فيها: علمت بهذه الآية الكريمة وهي قوله تعالى: لا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِنْ يُؤَاخِذُكُمْ بِمَا عَقَّدْتُمُ الأَيْمَانَ فَكَفَّارَتُهُ إِطْعَامُ عَشَرَةِ مَسَاكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍ فَمَنْ لَمْ يَجِدْ فَصِيَامُ ثَلاثَةِ أَيَّامٍ ذَلِكَ كَفَّارَةُ أَيْمَانِكُمْ إِذَا حَلَفْتُمْ وَاحْفَظُوا أَيْمَانَكُمْ كَذَلِكَ يُبَيِّنُ اللَّهُ لَكُمْ آيَاتِهِ لَعَلَّكُمْ تَشْكُرُونَ [المائدة:89] يستطيع المرء إطعام عشرة مساكين، ولكن إذا لم يجد المساكين، ويعرف مسكينًا واحدًا أو اثنين، هل يجوز أن يعطي الكفارة نقودًا على هؤلاء المساكين، أو إطعام المسكين الواحد عشر مرات لعدم معرفتي أكثر من ذلك؟ثانيًا: هل يجوز إعطاء الكفارة للمساكين رز أو قمح أو زبيب دون عمل طعام لهم في بيته؟ثالثًا: هل الكفارة تكون بالترتيب أو أن يختار كما يشاء؟أرجو إجابتي على هذه القضايا، جزاكم الله خيرًا.","title":"بعض أحكام كفارة اليمين","answer":"الجواب: الواجب أن يلتمس العشرة، ولا يجوز أن يكتفي بواحد، ولو كرر ذلك عليه عشر مرات؛ لأن الله نص على عشرة مساكين، إِطْعَامُ عَشَرَةِ مَسَاكِينَ [المائدة:89] فالواجب أن يلتمسهم ولو في غير بلده، ولو في بلد أخرى ينقلها إليهم، ولا بأس أن يخرجها من قوت بلده، من رز أو تمر أو حنطة أو زبيب أو أقطٍ أو غير هذا من قوت بلده يدفعها إليهم، أو يطبخ ذلك ويدعوهم إلى ذلك، فيدعوهم إلى طعام ناضج مطبوخ في بيته، ولو كانوا متفرقين، كأن يدعو يومًا اثنين، ويومًا اثنين، ويومًا أربعة، ويومًا اثنين لا بأس بذلك، إن جمعهم أو فرقهم. ولا يجوز إعطاؤهم دراهم، بل إما طعام وإما كسوة وإما عتق، هكذا قال الله : وَلَكِنْ يُؤَاخِذُكُمْ بِمَا عَقَّدْتُمُ الأَيْمَانَ فَكَفَّارَتُهُ إِطْعَامُ عَشَرَةِ مَسَاكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍ [المائدة:89] بالتخيير يخير، إن شاء أطعم، وإن شاء كسا، وإن شاء أعتق، ولا يجوز أن يدفع إليهم دراهم، بل ليس له إلا هذه الثلاث: إما إطعام، وإما كسوة، وإما عتق، فإن عجز عن الثلاث المذكورات انتقل إلى الصيام، وهو صيام ثلاثة أيام، كما بينه الله  نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17996/بعض-احكام-كفارة-اليمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_879/nour_87902.mp3","categories":["الأيمان والنذور"]},{"id":19053,"question":"تقول السائلة أم رشيدة من اليمن، يا سماحة الشيخ: ما الحكم في كثرة الحلف بالله؛ خاصةً إذا كان على شيء أعتقده صحيح؟","title":"حكم الإكثار من الحلف بالله","answer":"الجواب: لا ينبغي كثرة الحلف، يقول الله جل وعلا: وَاحْفَظُوا أَيْمَانَكُمْ [المائدة:89]، فينبغي للإنسان أن يعالج الأمور بغير اليمين وإن كان صادقًا؛ لأن كثرتها تجره إلى الكذب، فينبغي للمؤمن أن يتحرز من كثرة اليمين، ولو كان صادقًا، ويحل المشاكل بغير اليمين. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18202/حكم-الاكثار-من-الحلف-بالله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_883/nour_88304.mp3","categories":["الأيمان والنذور"]},{"id":19089,"question":"رسالة وصلت إلى البرنامج من المستمع: أبو النجار إبراهيم مصري مقيم في الأفلاج، أخونا يقول: قلت لزوجتي: إن ذهبت إلى منزل والدك فأنت طالق، وأنا الآن مقيم في المملكة، وحدث خلاف بين زوجتي وأهلي فذهبت إلى بيت والدها، أرجو إفادتي ماذا علي أن أفعل؟ ولكم جزيل الشكر.","title":"حكم من قال لزوجته: إن ذهبت إلى كذا فأنت طالق فذهبت","answer":"الجواب: إن كنت قصدت إيقاع الطلاق إن ذهبت فإنه يقع عليها طلقة ولك مراجعتها في العدة، إذا كانت لم تطلق قبل هذا طلقتين. أما إن كنت أردت منعها وتهديدها وتخويفها ولم تقصد إيقاع الطلاق، فإن هذا له حكم اليمين في أصح قولي العلماء، يكون عليك كفارة يمين، وهي إطعام عشرة مساكين أو كسوتهم لكل مسكين نصف صاع من قوت البلد من تمر أو غيره بصاع النبي ﷺ ومقدار ذلك كيلو ونصف تقريبًا، أو كسوتهم بأن تعطي كل واحد ما يجزئه في الصلاة كقميص أو إزار ورداء والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18253/حكم-من-قال-لزوجته-ان-ذهبت-الى-كذا-فانت-طالق-فذهبت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_930/nour_93004.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":19124,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول: (م.أ.م) المنياوي، أخونا له مجموعة من الأسئلة، في سؤاله الأول يقول: أنا متزوج، وفي مرة حدث خلاف بيننا، فقلت لها: أنت محرمة علي إن لم ترجعي عن الأمور التي تفعليها، وبعد أيام تصالحنا، وكان بيننا المعاشرة الزوجية، ثم سافرت إلى اليمن حيث أعمل.والآن ما هو موقفي بالنسبة لما صدر مني؟ هل تكون طلقة؟ أم يمين؟ وإذا كانت يمين فما هي الكفارة التي تكون علي؟ أسمع في الإجابة عن بعض الأسئلة والاستفسارات عن كفارتين: الأولى تقول: عتق رقبة، أو إطعام عشرة مساكين، أو صيام ثلاثة أيام، الثانية تقول: عتق رقبة، أو إطعام ستين مسكينًا، أو صيام ثلاثة أشهر، فما الفرق بين الكفارتين في الحكم الشرعي؟وهل من الممكن إخراج الكفارة على هيئة نقود توزع على الفقراء بما يساوي الإطعام؟جزاكم الله خيرًا.","title":"حكم قول الرجل لزوجته: أنت محرمة علي وما يترتب عليه","answer":"الجواب: هذا الكلام يحتاج إلى تفصيل حسب نية المتكلم، فإذا قال: هي محرمة عليه إذا لم تدع الأمور الفلانية، هذا إذا تركتها فلا تحريم، انتهى الأمر؛ لأنها امتثلت الأمر وتركت، فليس عليه شيء، أما إذا لم تترك بأن عاندت، وخالفت ولم تبالي بالكلام فهذا فيه تفصيل: إن كان أراد بهذا الكلام تحريمها أو تطليقها فهو على ما أراد، إن كان أراد التحريم فهي محرمة، وإن كان أراد الطلاق وقع الطلاق، وإن كان أراد منعها ولم يرد تحريمًا ولا طلاقًا وإنما أراد منعها والتشديد عليها وتخويفها وتحذيرها فهذا له حكم اليمين. فالمسألة تختلف بحسب النية، فإذا كان نوى بهذا الكلام تخويفها وتحذيرها ولكن لم تمتثل، فإن عليه كفارة يمين، وهي عتق رقبة مؤمنة، أو إطعام عشرة مساكين، أو كسوتهم، مخير بين الثلاث: عتق رقبة مؤمنة، أو إطعام عشرة مساكين، أو كسوتهم، والإطعام كونه يعشيهم أو يغديهم، أو يدفع إليهم نصف صاع لكل واحد، من التمر أو من الأرز من قوت البلد، يعني: كيلو ونصف تقريبًا، أو يكسوهم كسوة، كل واحد يعطيه إزار ورداء، أو قميص يستره في الصلاة، هذه هي الكفارة، فإن عجز عن هذا كله، عجز عن الإطعام وعن الكسوة وعن العتق، أجزأه أن يصوم ثلاثة أيام، عند العجز أن يصوم ثلاثة أيام، هذه كفارة اليمين. أما إن كان أراد تحريمها إذا لم تدع الأمور، أراد تحريمها فهذا حكمه حكم الظهار، كما لو قال: أنت علي كظهر أمي، أو ظهر أختي ونحو ذلك، فإذا حرمها بهذا التحريم، أو قال: أنت علي حرام أو محرمة إذا لم تدعي هذا الأمر، فلم تدعه قصده تحريمها فإن عليه كفارة الظهار: وهي عتق رقبة مؤمنة، فإن عجز فصيام شهرين متتابعين، فإن لم يستطع فإطعام ستين مسكينًا، وليس في الكفارة ثلاثة أشهر، ما فيها إلا شهران ما هي بثلاثة أشهر، الكفارة إما شهران وإما صيام ثلاثة أيام في كفارة اليمين، كما تقدم. والشهران في الظهار، يعني: تحريم الزوجة، وفي الوطء في رمضان، وفي قتل الخطأ وشبه العمد، أولاً: عتق رقبة مؤمنة، فإن عجز في تحريمه زوجته أو في وطئه في رمضان أو في قتله نفسًا بغير حق، إن عجز عن الرقبة صام شهرين متتابعين، ستين يومًا، فإن عجز بقيت الكفارة معلقة في ذمته حتى يستطيع إذا كان قتلًا، إذا كانت المعصية قتلًا، لأن الحادث قتلًا فليس فيه إطعام، بل تبقى الكفارة معلقة وهي عتق رقبة مؤمنة، فإن لم يستطع صام شهرين متتابعين، هذه كفارة القتل كما بينه الله في كتابه العظيم، فإذا عجز عن الصيام والعتق تبقى في ذمته متى قدر على العتق أعتق، ومتى استطاع الصيام صام. أما في الظهار، وتحريم الزوجة وفي الوطء في رمضان فهذا فيه أمر ثالث وهو الإطعام، عند العجز عن الرقبة وعند العجز عن الصيام يطعم ستين مسكينًا، ثلاثين صاعاً، في هاتين المسألتين: في مسألة الجماع في رمضان وفي مسألة تحريم الزوجة تحريمًا مطلقًا لا معلقًا بفعل كذا وفعل كذا، يقصد منعها، بل تحريم مطلق كأن يقول: أنت علي محرمة، أنت علي كظهر أمي، أو أنت علي محرمة إذا دخل رمضان، هذا هو التحريم المطلق، أو المعلق تعليقًا ليس فيه حث ولا منع، بل تعليقًا تامًا، فيترتب عليه حكم، فيلزم بعتق رقبة مؤمنة إذا قدر، فإن عجز صام شهرين متتابعين، فإن عجز أطعم ستين مسكينًا، وفي الظهار قبل أن يمسها، في تحريم الزوجة يأتي بهذه الكفارة قبل أن يمسها، قبل أن يقربها، وهي مرتبة على هذا الترتيب: العتق ثم الصيام عند العجز عن العتق، ثم الإطعام عند العجز عن الصيام، والإطعام يكون لستين مسكينًا، طعامًا لا نقودًا، يطعمهم يعشيهم أو يغديهم أو يعطيهم على نصف صاع من التمر أو من الأرز أو من الحنطة حسب قوت البلد، ومقداره بالوزن نحو كيلو ونصف تقريبًا من جهة الوزن. وأما في التحريم المعلق تعليقًا مراد منه الحث أو المنع أو التصديق أو التكذيب هذا فيه كفارة اليمين كما تقدم، فإذا قال: أنت محرمة علي إن فعلت كذا، أو أنت طالق إن فعلت كذا، إن كلمت فلانًا، إن فعلت الأمر الفلاني، إن عصيت أمي، إن خرجت من البيت قصده تحذيرها، ليس قصده طلاقها، قصده تحذيرها وتخويفها فهذا حكم اليمين. وهكذا لو قال: أنت علي، أنت مطلقة إن فعلت كذا، قصده منعها، تحذيرها، وليس قصده فراقها، فهذا له حكم اليمين، في أصح قولي العلماء كما تقدم، والله ولي التوفيق. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18314/حكم-قول-الرجل-لزوجته-انت-محرمة-علي-وما-يترتب-عليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_885/nour_88506.mp3","categories":["الأيمان والنذور","الطلاق","الظهار"]},{"id":19131,"question":"بسم الله الرحمن الرحيم، السلام عليكم ورحمة الله وبركاته، أنا من المعجبات ببرنامجكم، ونشكر المسئولين عليه لما فيه من النفع الكثير، وأرجوكم شاكرة عرض رسالتي على سماحة الشيخ عبد العزيز بن عبد الله بن باز.والسؤال هو كما يلي: اختلفت أنا وزوجي، فوقع منه طلاق على أن لا يكمل بناتي تعليمهن، أي: عند سنة معينة يقوم بفصلهن عن المدرسة، وفي ذلك الوقت كانت إحدى بناتي صغيرة حديثة الولادة، والآن وصلت هذه الصغيرة المرحلة نفسها، هل يقع الطلاق عندما تكمل هذه الصغيرة تعليمها؟ أم أنها لا تدخل في موضوع الطلاق؟ علمًا بأن الموضوع الذي اختلفنا فيه ليس من شأن التعليم أو المدارس، أجيبونا مشكورين، وصاحبة الرسالة هي الأخت (ل.ع. ر) من القصيم_ بريدة؟","title":"حكم الطلاق المعلق","answer":"الجواب: هذه المسألة وأشباهها ترجع إلى نية المطلق والحالف، فإذا كان المطلق أراد بذلك منعهن ولم يرد إيقاع الطلاق، وإنما أراد التشديد والتحذير والتهديد، ومنع نفسه من الإذن لهن، وليس قصده إيقاع الطلاق على أهله إذا وقع خلاف ما طلق عليه، فهذه الواقعة لها حكم اليمين، ويكون على المطلق كفارة اليمين إذا سمح لهن بالدراسة؛ لأنه لم يقصد إيقاع الطلاق وإنما قصد منعهن وشدد على نفسه بالطلاق، فهذا مثل لو قال: عليه الطلاق لا يكلم فلانًا، وعليه الطلاق لا يزور فلانًا، أو قال: عليه الطلاق في حق امرأته لا تزوري فلانًا، أو لا تذهبي إلى فلان، أو إلى فلانة، وقصده المنع والترهيب، والحث على ترك هذا الشيء، فهذا حكمه حكم اليمين، وليس له حكم الطلاق، وعليه كفارة اليمين في أصح قولي العلماء، بخلاف إذا كان قصد الطلاق فإنه يقع الطلاق، كما لو قال: عليه الطلاق إذا دخل رمضان، أو إذا خرج رمضان أو ما أشبه ذلك، فإنه يقع الطلاق؛ لأنه من الطلاق المعلق تعليقًا كاملًا، تامًا ليس فيه قصد حث أو منع.. إلى غير ذلك. فالحاصل أن التعليق قسمان: تعليق يقتضي إيقاع الطلاق، كالتعليق على دخول رمضان ونحو ذلك. وتعليق فيه تفصيل، مثل هذا الطلاق الذي علقه على الدراسة، فإن كان قصد إيقاع الطلاق، وقع الطلاق إذا درسن، وإن كان أراد منعهن فقط ولم يرد إيقاع الطلاق، وإنما أراد تخويفهن، وإلزام نفسه بمنعهن، فهذا حكمه حكم اليمين، وعليه كفارتها كفارة اليمين في أصح قولي أهل العلم. نعم. المقدم: جزاكم الله خيراً، إذًا هذه الصغيرة هل تدرس؟ الشيخ: نعم، تدخل تدخل. نعم. المقدم: تدرس. الشيخ: تدخل في الحكم. المقدم: تدخل في اليمين. الشيخ: في اليمين. نعم. المقدم: في اليمين. الشيخ: لأن قصده بناته عمومًا. المقدم: سواء من كان حاضرًا أو كان غائبًا؟ الشيخ: أما لو قال: معينات فلانة و فلانة، فإنها لا تدخل، أما إذا قال: بناتي، دخلت الصغيرة والكبيرة. نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/18308/حكم-الطلاق-المعلق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_885/nour_88502.mp3","categories":["الأيمان والنذور","الطلاق"]},{"id":19163,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات تقول: أم محمد من المدينة المنورة، أم محمد تقول عن نفسها: إنني امرأة أم لستة أطفال، كان عليَّ من الصيام ما يعادل شهرين لم أقضها في أوقاتها، ثم إني نذرت إن أنا صمت هذه الأيام أن أصوم من كل شهر ثلاثة أيام، وأن أصوم يومي الخميس والإثنين من كل أسبوع، إلا أنه يصادف العذر الشرعي في بعض الأوقات، وأيضًا صحتها لا تتحمل الوفاء بالنذر، وتسأل عن توجيهكم جزاكم الله خيرًا.","title":"حكم من نذر أن يصوم أياماً متوالية ثم صعب عليه","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله، وأصحابه، ومن اهتدى بهداه، أما بعد: فإن الواجب على السائلة أن توفي بنذرها إذا حصل الشرط الذي قالت فإن عليها أن توفي بالنذر حسب الطاقة، وإذا عجزت عن ذلك، وعن صيام رمضان لكبر سنها تطعم عن كل يوم مسكينًا كما تطعم عن صيام رمضان عن كل يوم مسكينًا مع القدرة نصف صاع من قوت البلد من تمر أو غيره. أما ما دامت تستطيع فإنها تصوم ثلاثة أيام من كل شهر، وتصوم الإثنين، والخميس؛ لقول النبي ﷺ في الحديث الصحيح: من نذر أن يطيع الله فليطعه، ومن نذر أن يعصي الله فلا يعصه؛ ولأن الله سبحانه مدح المؤمنين بالوفاء بالنذر فقال : يُوفُونَ بِالنَّذْرِ وَيَخَافُونَ يَوْمًا كَانَ شَرُّهُ مُسْتَطِيرًا[الإنسان:7]. فالواجب على السائلة أن توفي بنذرها؛ لأنه نذر طاعة، وإذا صادف الإثنين أو الخميس وقت حيض أو نفاس قضتهما بعد ذلك مثلما تقضي رمضان، فرمضان تفطر في الحيض والنفاس وتقضي، فهكذا في صوم نذرها تفطر وتقضي، والحمد لله. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18365/حكم-من-نذر-ان-يصوم-اياما-متوالية-ثم-صعب-عليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_798/nour_79809.mp3","categories":["الأيمان والنذور"]},{"id":19174,"question":"الرسالة التالية رسالة وصلت إلى البرنامج من الكويت، وباعثتها إحدى الأخوات من هناك تقول الكاتبة: أختكم في الإسلام من الكويت، لها قضيتان:القضية الأولى: تقول فيها: امرأة أصابها مرض فقالت: صدقة لوجه الله إن عافاني فلن أترك الصلاة، فشفيت ولم تحقق ما قالت، ولا تدري صدقة لوجه الله ما معناها؟ هل هو قسم أو نذر؟ وبعد مدة تابت وتتساءل ما كفارة ذلك؟","title":"حكم النذر بما أوجبه الله على العبد","answer":"الجواب: ما دامت تابت فالحمد لله؛ لأن الصلاة فرض عليها ولو لم تنذر، والنذر يزيد المقام تأكيدًا، فإذا كانت تركت الصلاة ثم تابت فالتوبة تمحو ما قبلها، كما قال النبي ﷺ: التوبة تجب ما قبلها. فعليها أن تستقيم، وأن تستمر على طاعة الله، وأن تحافظ على الصلاة التي أوجب الله عليها، وأن تحذر نزغات الشيطان وجلساء السوء، ونسأل الله لنا ولها الثبات على الحق، وليس عليها قضاء ما فات. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18343/حكم-النذر-بما-اوجبه-الله-على-العبد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_932/nour_93206.mp3","categories":["الأيمان والنذور"]},{"id":19189,"question":"لأخينا سؤال آخر يقول فيه: هل الكفارة الواحدة تجزئ عن أكثر من حنث أي أكثر من يمين واحدة؟","title":"حكم الكفارة الواحدة عن الأيمان المتعددة","answer":"الجواب: هذا فيه تفصيل: إذا كانت اليمين على فعل واحد ولو كررها تكفيه كفارة واحدة، كأن يقول: والله لا أزور فلان، والله لا أزور فلان، والله لا أزور فلان، يكررها عشر مرات أو أكثر أو أقل ثم زاره عليه كفارة واحدة، لأنه فعل واحد. أما إذا كان على أفعال مثل والله لا أزور فلان، والله لا آكل طعام فلان، والله لا أصلي خلف فلان، هذه أيمان متعددة على أفعال كل واحدة لها كفارتها إذا خالفها إذا حنث كل واحدة لها كفارتها. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18370/حكم-الكفارة-الواحدة-عن-الايمان-المتعددة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_932/nour_93215.mp3","categories":["الأيمان والنذور"]},{"id":19213,"question":"أختنا في سؤالها الثاني تقول: عندما كنت في المرحلة المتوسطة وفي الكفاءة بالأخص نذرت وقلت بالحرف الواحد: إن ربي نجحني سوف أصوم كل يوم اثنين وخميس، ولكني كنت غير مبالية ولم أوف بنذري، وأنا الآن على أبواب الجامعة وقد تبت إلى الله واستغفرت لذنبي وأصبحت أصوم الإثنين والخميس، فهل علي إثم فيما فرطت في السابق؟ وهل هناك كفارة؟ أرجو توضيح ذلك جزاكم الله خيرًا.","title":"نذرت صيام الاثنين والخميس وانقطعت فترة ثم تابت فما الكفارة؟","answer":"الجواب: إذا كنت حين النذر قد بلغت الحلم بالحيض أو بإكمال خمسة عشر سنة أو بإنبات الشعر حول الفرج، الشعر الخشن حول الفرج حول القبل، أو احتلمت يعني: أنزلت الماء المني باحتلام أو بأي نوع من أنواع الشهوة فإنه يلزمك هذا النذر؛ لأن المرأة تبلغ الحلم بأربعة أمور، بإكمال خمسة عشر سنة أو بإنزال المني عن شهوة ليلًا أو نهارًا ولو بالاحتلام أو بإنبات الشعر الخشن حول الفرج أو بالحيض. والرجل مثلها سواء بسواء ما عدا الحيض لأنه من خصائص النساء. فإذا كنت حين النذر قد بلغت الحلم بإحدى هذه الأمور فعليك أن توفي بنذرك، وأن تصومي الإثنين والخميس كما نذرت، لقول النبي ﷺ: من نذر أن يطيع الله فليطعه، ومن نذر أن يعصي الله فلا يعصه رواه البخاري في الصحيح. وعليك أن تقضي الأيام التي فرطت فيها ولم تصومي، عليك أن تقضيها ونرجو أن لا يكون عليك كفارة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18388/نذرت-صيام-الاثنين-والخميس-وانقطعت-فترة-ثم-تابت-فما-الكفارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_933/nour_93308.mp3","categories":["الأيمان والنذور"]},{"id":19266,"question":"قررت صديقة لي أن تتحجب، فأقسمت من فرحتي أن أعمل لها حفلة، إذا لم أستطع فما الحكم؟","title":"حكم من حلف على شيء ولم يستطع عمله","answer":"الجواب: إذا أقسمتِ بالله فالمشروع لك أن تفي وتبري يمينك؛ لأن الله قال: وَاحْفَظُوا أَيْمَانَكُمْ [المائدة:89]، فإذا بررت يمينك فهو أفضل، وفيه تشجيع لها على الحجاب، ورضًا بعملها الطيب، وتشجيع لغيرها أيضًا، وإذا شق عليك ذلك كفري كفارة يمين والحمد لله، يقول النبي ﷺ: إذا حلفت على يمين، فرأيت غيرها خيرًا منها فكفر عن يمينك وأت الذي هو خير، فالإنسان إذا رأى فيها مشقة عليه يكفر عن يمينه والحمد لله. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18467/حكم-من-حلف-على-شيء-ولم-يستطع-عمله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_892/nour_89212.mp3","categories":["الأيمان والنذور"]},{"id":19331,"question":"عند قضاء كفارة اليمين إذا لم نجد عشرة مساكين فهل يجوز الصيام مع القدرة على الإطعام؟","title":"حكم الانتقال للصيام في كفارة اليمين إذا لم نجد عشرة مساكين","answer":"الجواب: المساكين موجودون، ما هم معدومون، المساكين موجودون عليه أن يلتمسهم، ولو في قريته ولو في قرية أخرى غير قريته. المقصود أن الفقراء موجودون وبكثرة أيضًا، لكن عليه ألا يضعف وعليه أن يلتمسهم، أو يوكل من يلتمسهم من الثقات في بلد أخرى إذا كانت بلده كل أهلها أغنياء فيلتمس في القرى الأخرى، وعليه أن يوكل ثقة أو يذهب فيلتمس ولا يصوم إلا عند العجز إذا ما وجد فقراء.","link":"https://binbaz.org.sa/fatwas/18540/حكم-الانتقال-للصيام-في-كفارة-اليمين-اذا-لم-نجد-عشرة-مساكين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_897/nour_89704.mp3","categories":["الأيمان والنذور"]},{"id":19338,"question":"أولى قضايا هذه الحلقة قضية بعث بها مجموعة من السادة المستمعين يسألون ويقولون: ما حكم الشرع في الأموال التي تنذر للأولياء وتوضع في صناديق أخر؟ وهل لأحد حق فيها لانتسابه إلى هذا الولي؟","title":"حكم النذر لغير الله كالأولياء عند القبور","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فالنذر من العبادات التي يجب إخلاصها لله وحده؛ لأنها التزام المكلف ما ليس لازمًا له من جهة الشرع تعظيمًا للمنذور له وتقربًا إليه، وهذا لا يصلح إلا لله وحده، فليس لأحد أن يلتزم صلاة ولا صومًا ولا صدقة ولا غير ذلك، لا لملك مقرب ولا نبي مرسل ولا لنجم ولا لشجر ولا لحجر ولا لجني ولا لغير ذلك، فهذه النذور التي يقدمها بعض الجهال إلى الأولياء من أصحاب القبور تعتبر شركًا أكبر كالذبح لغير الله وكالاستغاثة بالأموات كل ذلك من قسم الشرك الأكبر، قال الله : وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ [الإسراء:23]، وقال سبحانه: وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ [البينة:5]، قال : إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ [الفاتحة:5]، قال سبحانه: وَمَا أَنفَقْتُمْ مِنْ نَفَقَةٍ أَوْ نَذَرْتُمْ مِنْ نَذْرٍ فَإِنَّ اللَّهَ يَعْلَمُهُ [البقرة:270]، المعنى فيجازيكم عليه . فالنذور عبادات وقرب يجب أن تكون لله وحده، ومع ذلك فالرسول ﷺ نهى عن النذر قال: إنه لا يأتي بخير وإنما يستخرج به من البخيل. فلا ينبغي للمؤمن النذر، ولكن متى نذر فليكن لله وحده لا لغيره ، فإذا قال: لله عليه أن يصلي كذا أو يصوم كذا أو يتصدق بكذا لزمه الوفاء؛ لما ثبت عنه ﷺ أنه قال: من نذر أن يطيع الله فليطعه ومن نذر أن يعصي الله فلا يعصه خرجه البخاري في صحيحه من حديث أم المؤمنين عائشة رضي الله تعالى عنها، فإذا قال: لله عليه أن يصلي الضحى ركعتين وجب عليه الوفاء، لله عليه أن يتصدق بكذا وكذا درهم أو بكذا وكذا صاعًا من بر أو شعير أو أرز أو غير ذلك وجب عليه الوفاء أو قال: لله عليه أن يحج وجب عليه الحج لله عليه أن يعتمر وجب عليه العمرة وهكذا، لقوله عليه الصلاة والسلام: من نذر أن يطيع الله فليطعه. أما أن ينذر للأولياء لأصحاب القبور للجن للكواكب للرسل عليهم الصلاة والسلام لغيرهم من المخلوقين هذا شرك بالله، كما لو ذبح لغير الله أو استغاث بغير الله من الأموات أو من الجن أو من الكواكب أو ما أشبه ذلك، كله شرك بالله بإجماع أهل العلم، وإنما وقع هذا من المتأخرين من الذين جهلوا توحيد الله وجهلوا أحكام شريعته فوقعوا في الشرك، وقد يقع في هذا بعض من ينتسب إلى العلم؛ لعدم بصيرته بالعقيدة الصحيحة التي درج عليها سلف الأمة. وهذه النذور التي تكون من الأموال وتجمع في الصناديق حول القبور هذه حكمها حكم الأموال التي لا رب لها تؤخذ لبيت مال المسلمين أو يأخذها ولي الأمر ويصرفها في مصالح المسلمين كمساعدة الفقراء والمساكين، أو إصلاح الطرق أو دورات المياه أو ما أشبه هذا من المصالح العامة، ولا ترد على أهلها، وليس لأحد أن يأخذها من الناس بل هذه ترجع لولي الأمر إذا كان ولي الأمر صالحًا ينفذ شرع الله وإلا فلأصحاب البصيرة من أهل العلم يأخذونها ويوزعونها في وجوه البر والخير على الفقراء والمحاويج ونحو ذلك، ويبصرون الناس وينذرونهم منها ويحذرونهم منها وأنها منكر وأنها من الشرك حتى لا يعودوا إليها، وتزال هذه الصناديق وترفع من المساجد وغيرها؛ لأنها منكر ولأنها دعوة للشرك بالله  فالواجب إزالتها والتحذير منها وتوعية الناس وتبصيرهم بأن هذا من الشرك الأكبر، وما وجد فيها حين إزالتها من نقود تصرف في أعمال الخير كما تقدم، مع إزالتها من المساجد ومع تنبيه العامة وتحذيرهم من مثل هذا، وأنه لا يجوز التقرب إلى غير الله لا بالصلاة ولا بالنذور ولا بالصدقات ولا غير هذا، لا لأصحاب القبور ولا للأصنام ولا للكواكب ولا للجن ولا لغير هذا، العبادة لله وحده  كما قال : فَاعْبُدِ اللَّهَ مُخْلِصًا لَهُ الدِّينَ [الزمر:2]، وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ [البينة:5]. والعبادة كل ما أمر الله به ورسوله، قال بعض أهل العلم: معناها: اسم جامع لكل ما يحبه الله ويرضاه من الأقوال والأعمال الظاهرة والباطنة وتكون قولية وتكون عملية وتكون بالقلب وتكون باللسان تكون بالجوارح فخوف الله وتعظيمه ومحبته هذه عبادات قلبية وهكذا رجاؤه سبحانه ونحو ذلك من سائر العبادات القلبية. وهناك عبادات عملية كالصلاة والزكاة والصدقات والذبح والنذر هذه عبادات عملية. وتكون قولية كالنذر من جهة القول فالنذر عبادة قولية وما يحصل به من صدقات ونحو ذلك عبادات مالية. فالحاصل أن جميع العبادات قولية أو عملية قلبية أو لسانية يجب أن تكون لله وحده ، ولا يجوز لأي أحد أن يصرفها لأي مخلوق من ولي أو رسول أو ملك أو جني أو صنم أو غير ذلك نسأل الله للجميع الهداية و السلامة. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18536/حكم-النذر-لغير-الله-كالاولياء-عند-القبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_897/nour_89701.mp3","categories":["الأيمان والنذور","نواقض الإسلام"]},{"id":19359,"question":"مستمع من العراق الموصل، هو عبد الله بن عبد الكريم يسأل جمعًا من الأسئلة، في سؤاله الأول يقول: هل يجوز الأكل من لحم الذبيحة المنذورة، أي: إذا نذرت أن أذبح شاة، ثم ذبحتها هل يجوز لي الأكل من لحمها؟","title":"حكم أكل الناذر من ذبيحة النذر","answer":"الجواب: هذا فيه تفصيل:\nفإن كان الناذر نذرها نذر الذبيحة ليذبحها في بيته، ويأكل منها هو وأهله، وجيرانه، أو أقاربه أو غيرهم من أصدقائه، ومعارفه، فهذا لا بأس؛ لقول النبي ﷺ: إنما الأعمال بالنيات، وإنما لكل امرئ ما نوى. أما إن كان نذرها للفقراء، أو أطلق النذر، ولم ينو شيئًا؛ فإنها تصرف للفقراء، وليس له أن يأكل منها، بل النذور تكون للفقراء والمحاويج، يذبحها لله سبحانه ثم يوزعها بين الفقراء الذين يعرفهم في بلده أو غيرها، وبذلك تبرأ ذمته. مع العلم بأنه لا ينبغي النذر، ولا يشرع للعبد أن ينذر، بل ينهى عن ذلك لقول النبي ﷺ: لا تنذروا فإن النذر لا يرد من قدر الله شيئًا، وإنما يستخرج به من البخيل. لكن متى نذر طاعة لله وجب عليه الوفاء كما قال تعالى: يُوفُونَ بِالنَّذْرِ وَيَخَافُونَ يَوْمًا كَانَ شَرُّهُ مُسْتَطِيرًا[الإنسان:7]، مدح به عباده الأبرار، وقال النبي ﷺ: من نذر أن يطيع الله فليطعه، ومن نذر أن يعصيه فلا يعصه. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18577/حكم-اكل-الناذر-من-ذبيحة-النذر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_942/nour_94204.mp3","categories":["الأيمان والنذور"]},{"id":19383,"question":"المستمع (إسماعيل . ع. م) من جمهورية مصر العربية مقيم في الرياض، أخونا بعث برسالة وضمنها سؤالًا مطولًا ملخصه: أنه ممن ابتلي بشرب الدخان، وذات يوم قال: علي الحرام بالثلاث إني لا أشرب الدخان، وبقيت ما يقارب السنتين ثم عدت في الإجازة إلى البلد وشربت، ما الحكم لو تكرمتم؟","title":"حكم من حلف بالحرام على ترك شيء محرم ثم فعله","answer":"الجواب: هذا يرجع إلى نيته؛ فإذا كان أراد بهذا منع نفسه من شرب الدخان، وليس قصده تحريم زوجته إن شربه، إنما قصده أن يمتنع من ذلك، وأن يستعين بهذا التحريم على ترك التدخين فهو في حكم اليمين وعليه كفارة اليمين مع التوبة والاستغفار وعدم العود إلى ذلك، وعليه كفارة اليمين لأن التحريم على الأصح في حكم اليمين. إذا قال: عليه الحرام لا يفعل ذلك كذا، أو ليفعلن كذا ثم حنث فالصواب: أنه في حكم اليمين إذا لم يرد تحريم أهله، تحريم زوجته وإنما أراد الامتناع والكف عن هذا الشيء فله حكم اليمين، وكفارتها معلومة إطعام عشرة مساكين أو كسوتهم أو عتق رقبة، ومن عجز عن ذلك صام ثلاثة أيام.\nفالحاصل أن هذا له حكم اليمين. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18604/حكم-من-حلف-بالحرام-على-ترك-شيء-محرم-ثم-فعله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_934/nour_93411.mp3","categories":["الأيمان والنذور"]},{"id":19384,"question":"أيضًا من أجل نفس الموضوع، نذر صيام عشرة أيام إن هو شرب الدخان، ثم وقع في نفس المشكلة، وشرب الدخان؟","title":"حكم من نذر على ترك شيء محرم ثم فعله","answer":"الجواب: لا حول ولا قوة إلا بالله، لا شك أن عليه الوفاء بالنذر .. أعد أعد نذره أعده نذر.. نعم.\nالمقدم: يقول: إنه نذر على نفسه أن يصوم عشرة أيام إن هو شرب الدخان مرة أخرى فشرب الدخان.\nالجواب: هذا مثلما تقدم فيه التفصيل:\nإن كان أراد منع نفسه بذلك كما هو الظاهر، إنما أراد أن يمتنع فلا يلزمه الصيام، وتجزيه كفارة اليمين، وإن صام أجزأه ذلك وكفى. وإن كان أراد القربة إلى الله، وأنه يصوم إذا فعل ذلك، ليس قصده الامتناع فهذا يصوم، لكن سياق الناس وعادتهم في مثل هذا أن قصده من هذا الامتناع، وأنه يريد أن يمنع نفسه بالصيام. فإذا فعله فعليه التوبة إلى الله، وقد أخطأ وغلط؛ لأن الدخان محرم وعليه كفارة يمين إن لم يصم، فإن صام أجزأه ذلك. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18605/حكم-من-نذر-على-ترك-شيء-محرم-ثم-فعله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_934/nour_93412.mp3","categories":["الأيمان والنذور"]},{"id":19416,"question":"رسالة بعث بها أحد الإخوة المستمعين يقول: أخوكم المسلم ( أبو ط. ل) مصري مقيم في المملكة، له جمع من الأسئلة في أحدها يقول: إذا كنت نذرت مبلغ خمسة آلاف جنيه مصري لله، وهذا المبلغ يمكن أن يكفي لبناء مسجد صغير في قريتي، فهل لي ثواب في بناء هذا المسجد؟ أم أن الثواب لوفاء النذر فقط؟ جزاكم الله خيرًا.","title":"نذرت مبلغا يكفي لبناء مسجد فهل لي ثواب بناء مسجد؟","answer":"الجواب: إذا نذرت نذرًا لله يعني في دراهم أو غيرها، فعليك أن توفي به على ما نذرت، وعلى ما نويت لا تغير، فإذا قلت: لله علي أن أتصدق بخمسة آلاف، قصدك للفقراء أعطها الفقراء، فإذا كان قصدك أن تبني بها مسجدًا هذه نيتك؛ فابن بها مسجدًا، وإذا كان قصدك أن تعمر بها مدرسة لتعليم القرآن والحديث الشريف كذلك، إذا كان قصدك أن تنفقها في المجاهدين في سبيل الله على حسب نيتك؛ لقوله ﷺ: إنما الأعمال بالنيات، وإنما لكل امرئ ما نوى. فالواجب عليك أن تصرف النذر في الجهة التي نويتها أو صرحت بها، يقول النبي ﷺ: من نذر أن يطيع الله فليطعه، ومن نذر أن يعصي الله فلا يعصه، وقد مدح الله الموفين بالنذر، فقال سبحانه في سورة الإنسان: يُوفُونَ بِالنَّذْرِ [الإنسان:7]، يعني: الأبرار المؤمنين يُوفُونَ بِالنَّذْرِ وَيَخَافُونَ يَوْمًا كَانَ شَرُّهُ مُسْتَطِيرًا [الإنسان:7]، ويقول سبحانه: وَمَا أَنفَقْتُمْ مِنْ نَفَقَةٍ أَوْ نَذَرْتُمْ مِنْ نَذْرٍ فَإِنَّ اللَّهَ يَعْلَمُهُ [البقرة:270]، يعني: فيجازيكم عليه . فالواجب على كل من نَذر نْذر طاعة أن يوفي بالنذر على ما نذر، في مسجد، في صدقة على الفقراء، في تعمير مدرسة لتدريس العلوم الشرعية، للمجاهدين في سبيل الله، في أي قربة من قرب الخير. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/18649/نذرت-مبلغا-يكفي-لبناء-مسجد-فهل-لي-ثواب-بناء-مسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_740/nour_74011.mp3","categories":["الأيمان والنذور"]},{"id":19533,"question":"شخص عليه مجموعة من النذور يا فضيلة الشيخ! ويقول: أريد أن أكفر عن هذه النذور، هل يلزمه التكفير؟","title":"حكم الوفاء بالنذور","answer":"الجواب: إذا نذر أن يتصدق بكذا يلزمه، من نذر أن يطيع الله فليطعه إذا نذر حج يلزمه مع الاستطاعة، نذر أن يعتمر كذلك ما عليه شيء إذا كان نذر طاعة، النبي عليه السلام يقول: من نذر أن يطيع الله فليطعه.\nفعليه أن ينفذ حسب طاقته.","link":"https://binbaz.org.sa/fatwas/18784/حكم-الوفاء-بالنذور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_939/nour_93943.mp3","categories":["الأيمان والنذور"]},{"id":19612,"question":"في آخر أسئلة هذه السائلة أم عبد الله تقول: ما حكم من حلف بالله وعلى المصحف على ترك ذنب ثم عاد إليه؛ وذلك لأنه لم يجد سبيلًا يردعه عن ذلك، وهو الآن ناوي التوبة، فبماذا توجهونه مأجورين؟","title":"حكم من حلف على ترك ذنب ثم عاد إليه","answer":"الجواب: عليه التوبة والكفارة، كفارة اليمين إذا قال: والله لا يزني، ثم عاد إلى الزنا عليه التوبة، وعليه كفارة يمين، إطعام عشرة مساكين أو كسوتهم، كل مسكين نصف صاع، كيلو ونصف تقريبًا، مع التوبة. نعم.","link":"https://binbaz.org.sa/fatwas/18868/حكم-من-حلف-على-ترك-ذنب-ثم-عاد-اليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_948/nour_94806.mp3","categories":["الأيمان والنذور"]}]
